local P = LoreForeverPacks.Begin("LoreForever_Lang_deDE")
P.entries["item:gyromechanic-gear"] = {n="Gyromechanische Getriebeteile",s="In Kharanos suchen Erfinder Gyromechanische Getriebeteile für ein kühnes Experiment. Sie hoffen, die Mutationen der Lepragnome rückgängig zu machen.",h="In Kharanos suchen Erfinder Gyromechanische Getriebeteile für ein kühnes Experiment.",kw={"gnomeregan","gyromechanische getriebeteile","kharanos","lepragnom","operation recombobulation","razzle flinkspross","rekombobulator","restabilisationszahnrad"},ang={["profession:Engineering"]="Als Ingenieur kennt Ihr die ausgeklügelte Konstruktion und die engen Toleranzen gnomischer gyromechanischer Bauteile. Sie regulieren instabile Maschinenprototypen.",["race:Gnome"]="Als Gnom bringt Ihr mit jedem geborgenen Getriebeteil die Tüftler einer Chance näher, ihre radioaktiven Artgenossen im Schnee vor Gnomeregan zu retten."},sec={{t="Bauteile für die Rekombobulation",b="Strahlung durchflutete Gnomeregan, während die Gnome darum kämpften, die Troggs zu vertreiben. Viele Überlebende wurden zu wahnsinnigen, verstrahlten Lepragnomen. Ozzie Wechselvolt und Razzle Flinkspross wollen ihre entstellten Artgenossen nicht aufgeben und haben deshalb den Rekombobulator entworfen. Die Maschine soll die Auswirkungen der Strahlung rückgängig machen.\n\nIhr Prototyp benötigt präzise Mechanismen, die dem unbeständigen Druck im Inneren standhalten können, darunter Gyromechanische Getriebeteile und Restabilisierungskettenräder. Mit dem Fall Gnomeregans endete die örtliche Fertigung. Nun müssen die Erfinder diese empfindlichen Teile von feindseligen Lepragnomen bergen, die durch Dun Morogh streifen."}},faq={{q="Wofür werden Gyromechanische Getriebeteile verwendet?",a="Razzle Flinkspross in Kharanos benötigt Gyromechanische Getriebeteile als Kernbauteile für den Rekombobulator. Der Prototyp soll sie zusammen mit Restabilisierungskettenrädern nutzen, um zu versuchen, verstrahlte Lepragnome zu heilen.",al={"gyromechanische getriebeteile verwendung","was bewirken gyromechanische getriebeteile","gyromechanische getriebeteile quest"}},{q="Woher stammen diese Getriebeteile?",a="Die Getriebeteile werden von Lepragnomen außerhalb von Gnomeregan und von Gibblewilt in Dun Morogh geborgen.",al={"wo gyromechanische getriebeteile finden","gyromechanische getriebeteile beute","wer lässt gyromechanische getriebeteile fallen"}},{q="Kann der Rekombobulator Lepragnome tatsächlich heilen?",a="Razzle Flinkspross vertraut Ozzies Bauplänen und glaubt, dass Änderungen an den Verbrennungskolben und am Elektrogummigel ihre Artgenossen wiederherstellen können. Die Maschine wurde noch nicht in großem Umfang gegen Strahlenvergiftung erprobt.",al={"funktioniert der rekombobulator","können lepragnome geheilt werden","rekombobulation erfolg"}},{q="Warum können Gnome nicht einfach neue Getriebeteile schmieden?",a="Gnomeregans Fall zerschlug die gnomische Industrie und machte ihre besten Werkzeuge, Werkstätten und automatisierten Gießereien unerreichbar. Intakte Präzisionsbauteile am Stadtrand zu bergen, geht oft schneller, als Teile von Hand zu fertigen.",al={"warum getriebeteile bergen","warum keine gyromechanischen getriebeteile herstellen"}}},fx={["93a017f3"]={q="Was ist ein gyromechanisches Getriebeteil?",a="Ein gyromechanisches Getriebeteil ist eine aufwendig konstruierte Komponente, die für komplexe gnomische Maschinen gefertigt wurde. Ursprünglich innerhalb der riesigen mechanischen Anlagen von Gnomeregan verwendet, sind diese Präzisionsteile nun in den Ruinen verstreut und werden von den elenden Kreaturen geplündert, die außerhalb der gefallenen Technologiestadt lauern.",al={"was ist ein gyromechanisches getriebeteil","info zu gyromechanischen getriebeteilen","über gyromechanische getriebeteile"}}},fp="17,121,30.581.0,37.195.0,31.94.0,50.211.0,40.221.0"}
P.entries["item:hallowed-letter"] = {n="Geheiligter Brief",s="Im Nordhaintal ruft Priesterin Anetta junge Priester in die Abtei von Nordhain. Ihr Brief leitet ihr Studium des Heiligen Lichts ein.",h="Im Nordhaintal ruft Priesterin Anetta junge Priester in die Abtei von Nordhain.",kw={"anetta","wald von elwynn","geheiligter brief","heiliges licht","abtei von nordhain","priester","priesterin anetta"},ang={["class:Priest"]="Dieses Schreiben erkennt Euch als Priester als Werkzeug des Heiligen Lichts an und bindet Euch an die Ausbilder der Abtei von Nordhain.",["race:Human"]="Als Mensch führt Ihr die Tradition heiliger Pflichterfüllung des Nordhaintals fort, die dort schon vor dem Ersten Krieg gepflegt wurde."},sec={{t="Ein Ruf zum Glauben",b="Der Geheiligte Brief trägt das persönliche Zeichen von Priesterin Anetta. Er erreicht angehende Priester nach ihren ersten Prüfungen gegen die Koboldlager des Nordhaintals. Sie erkennt in jedem Novizen einen Funken des Heiligen Lichts und fordert sie auf, die Abtei zu betreten und ihm zu dienen. Nach dem Dritten Krieg lauern noch immer dunkle Mächte in ganz Azeroth. Die Priesterschaft versammelt jene, die heilen, beschützen und einem Reich den Weg weisen können, das um den Erhalt der Ordnung ringt."}},faq={{q="Was ist der Geheiligte Brief?",a="Der Geheiligte Brief ist Priesterin Anettas Schreiben an neu eingetroffene Priester in der Abtei von Nordhain. Er ruft sie zu ihrer ersten Unterweisung als Priester.",al={"was ist der geheiligte brief","geheiligter brief gegenstand","priesterbrief nordhain"}},{q="Wer hat den Brief geschrieben?",a="Priesterin Anettas Insignien kennzeichnen den Brief. Sie unterweist und führt junge menschliche Priester, die in Nordhain eintreffen.",al={"wer hat den brief geschickt","wer ist der verfasser","absender des briefs"}},{q="Warum ruft die Priesterschaft gerade jetzt nach neuen Novizen?",a="Azeroth ist weiterhin in Aufruhr, und Überreste der Brennenden Legion suchen die Welt noch immer heim. Kalimdor steht vor neuen Prüfungen, während Sturmwind mitfühlende Heiler und Anführer braucht, um den Wiederaufbau voranzutreiben und sein Volk zu schützen.",al={"warum brauchen priester hilfe","zustand der welt","priesterhintergrund 25 adp"}},{q="Was soll ich tun, nachdem ich den Brief gelesen habe?",a="Bringt den Brief in die Abtei von Nordhain und sprecht mit Priesterin Anetta. Sie wird Euer Gelöbnis gegenüber dem Licht annehmen und Euch im Verlauf Eurer Reise in neuen priesterlichen Disziplinen unterweisen.",al={"wohin den brief bringen","geheiligter brief quest abgeben","mit wem sprechen"}}},fx={["0a342f04"]={q="Warum möchte Priesterin Anetta, dass Ihr den Geheiligten Brief habt?",a="Priesterin Anetta schickt den Brief, um vielversprechende Novizen des Heiligen Lichts innerhalb der Abtei von Nordhain zusammenzurufen. Da sie erkennt, dass Ihr Euch bei der Verteidigung des Tals als vielversprechend erwiesen habt, möchte sie sich vorstellen, Eure spirituelle Hingabe leiten und Euch tieferen Unterricht in den heiligen Künsten der Priesterschaft anbieten.",al={"warum geheiligter brief","warum schickte anetta den brief","zweck des geheiligten briefes"}}},fp="15,128,15.424.0,28.147.0,21.113.0,58.196.0,42.179.0"}
P.entries["item:hallowed-rune"] = {n="Geheiligte Rune",s="Im Coldridgetal schickt Branstock Khalder angehenden Priestern die Geheiligte Rune, damit sie ihre Ausbildung in Ambossar beginnen.",h="Im Coldridgetal schickt Branstock Khalder angehenden Priestern die Geheiligte Rune, damit sie ihre Ausbildung...",kw={"ambossar","branstock khalder","das coldridgetal","dun morogh","geheiligte rune","priester","troggs"},ang={["class:Priest"]="Als Priester beginnt Ihr mit der Geheiligten Rune Eure formelle Unterweisung im Heiligen Licht im Coldridgetal.",["race:Dwarf"]="Als Zwerg vereint Ihr Ehrfurcht vor dem Licht mit Eurer Pflicht gegenüber Eisenschmiede, während Ihr Eure Bergheimat gegen Troggs verteidigt."},sec={{t="Eine Berufung zum Licht",b="Die Geheiligte Rune trägt Lehren des Heiligen Lichts. Ein junger Priester beweist seine Entschlossenheit, indem er den Gebirgsjägern und Verteidigern des Tals hilft. Dann schickt Branstock ihn nach Ambossar, wo er ihn lehrt, Wunden zu heilen und heilige Macht gegen die Troggs einzusetzen, die Dun Morogh bedrohen."}},faq={{q="Was ist die Geheiligte Rune?",a="Die Geheiligte Rune ist ein heiliger Stein, in den Anweisungen für angehende Priester eingraviert sind. Branstock Khalder schickt sie ihnen, um sie zum Beginn ihrer geistlichen und magischen Unterweisung nach Ambossar zu rufen.",al={"was ist dieser gegenstand","geheiligte rune gegenstand","zweck der rune"}},{q="Wer schickt Euch die Geheiligte Rune?",a="Branstock Khalder, der zwergische Priesterlehrer in Ambossar, schickt die Geheiligte Rune an angehende Priester im Coldridgetal.",al={"wer hat die rune geschickt","wer hat mir diese rune gegeben","branstock rune"}},{q="Was soll ich tun, nachdem ich die Geheiligte Rune erhalten habe?",a="Lest die Rune, geht dann in die Haupthalle von Ambossar und stellt Euch Branstock Khalder vor. Er bietet an, Euch neue Gebete und Zauber zu lehren.",al={"wohin bringe ich die rune","was tun mit der geheiligten rune"}},{q="Warum will Branstock angehende Priester so schnell ausbilden?",a="Branstock will angehende Priester ausbilden, weil immer wieder Troggs ins Coldridgetal eindringen. Die Gebirgsjäger brauchen Heilung und heilige Macht, um Dun Morogh zu verteidigen.",al={"warum werden priester gebraucht","troggproblem priester"}}},fx={fac25589={q="Warum wurde mir die Geheiligte Rune gegeben?",a="Die Rune fungiert als formelle Vorladung und Nachricht an Novizenpriester, die im Coldridgetal arbeiten. Branstock Khalder schickt sie weiter, um angehende Akolythen des Heiligen Lichts nach Ambossar zu rufen, damit er sie in ihrem Glauben unterweisen und ihnen heilige Zauber beibringen kann, die für die Verteidigung des Tals von entscheidender Bedeutung sind.",al={"warum habe ich die geheiligte rune","zweck der geheiligten rune","warum geheiligte rune"}}},fp="13,114,22.281.0,26.185.0,35.121.0,51.138.0,58.152.0"}
P.entries["item:hallowed-scroll"] = {n="Geheiligte Rolle",s="In Todesend ruft die Geheiligte Rolle neu erwachte Priester der Verlassenen in die verfallene Kapelle. Mit dem Siegel des Dunklen Klerikers Duesten versehen, leitet sie ihre Ausbildung in Glauben, Willenskraft und Schatten ein.",h="In Todesend ruft die Geheiligte Rolle neu erwachte Priester der Verlassenen in die verfallene Kapelle.",kw={"todesend","duesten","verlassene","geheiligte rolle","licht","priester","tirisfal"},ang={["class:Priest"]="Als Priester der Verlassenen markiert dieses Pergament Euren Bruch mit dem traditionellen Glauben der Menschen. Es weist Euch den Weg zu Eurer eigenen Überzeugung und den Schattenkünsten des Cult of the Forgotten Shadow.",["race:Undead"]="Als untoter Reisender erhaltet Ihr diesen Ruf, während Todesend die neu Erwachten eilig sammelt und ausbildet, um sie in die Streitkräfte von Sylvanas einzugliedern."},sec={{t="Ein Ruf an die Glaubenslosen",b="Neu auferstandene Priester der Verlassenen spüren, wie sich ihre Verbindung zur Welt auf gewaltsame Weise verändert. Todesend wird inmitten des Chaos zurückerobert, und die Geheiligte Rolle schickt sie in die verfallene Kapelle der Siedlung, um dort Führung zu suchen. Das Siegel des Dunklen Klerikers Duesten kennzeichnet das Pergament. Es weist die neuen Priester an, sich zur formellen Unterweisung in den praktischen Glaubensgrundsätzen des Priestertums der Verlassenen einzufinden."},{t="Der Weg der Eigenständigkeit",b="Dunkler Kleriker Duesten fordert Priester, die dem Ruf folgen, dazu auf, alte Lehren hinter sich zu lassen. Das Heilige Licht, die Geister der Ahnen und dämonische Pakte dürfen ihnen nicht als Krücken dienen. Die Rolle begründet eine Disziplin, die auf dem eigenen Willen jedes Priesters beruht. Ihre Lehren rufen sie dazu auf, durch Überzeugung zu überleben und zu herrschen, und machen Glauben zu einem Mittel der Selbstbeherrschung und Machtausübung."}},faq={{q="Was ist die Geheiligte Rolle?",a="Die Geheiligte Rolle ruft neu auferstandene Priester der Verlassenen in Todesend zusammen. Sie weist sie an, sich zur formellen Ausbildung beim Dunklen Kleriker Duesten in der örtlichen Kapelle einzufinden.",al={"was ist diese rolle","zweck der geheiligten rolle","gegenstand geheiligte rolle"}},{q="Wer hat die Geheiligte Rolle geschickt?",a="Das persönliche Siegel des Dunklen Klerikers Duesten kennzeichnet die Geheiligte Rolle. Er bildet Priester in der verlassenen Kirche von Todesend aus.",al={"wer schrieb die geheiligte rolle","wer schickte die rolle","duestens rolle"}},{q="Was lehrt Dunkler Kleriker Duesten, wenn Ihr ihm die Rolle bringt?",a="Dunkler Kleriker Duesten lehrt untote Priester, sich nicht länger auf das Heilige Licht, die Geister der Ahnen und jenseitige Mächte zu verlassen. Er sagt, die Verlassenen hätten durch ihre eigene Willenskraft überlebt, und fordert junge Priester auf, Glauben an sich selbst zu entwickeln, um andere führen und beherrschen zu können.",al={"was sagt duesten","glaubensgrundsätze der verlassenenpriester","geschichte der priester in todesend"}}},fx={["758c1904"]={q="Warum möchte Dunkler Kleriker Duesten, dass Ihr die Geheiligte Rolle habt?",a="Dunkler Kleriker Duesten verwendet die versiegelte Rolle, um neu erstandene Priester der Verlassenen zur Kirche von Todesend zu rufen. Anstatt Euch dem vergessenen Licht oder den Geistern der Ahnen überlassen zu wollen, beabsichtigt er, Euch in der düsteren Philosophie der Priesterschaft der Verlassenen zu unterweisen – wobei Ihr Euch ausschließlich auf Eure eigene unnachgiebige Willenskraft verlasst, um Macht auszuüben und in einer feindseligen Welt zu überleben.",al={"warum geheiligte rolle","warum duesten geheiligte rolle","zweck der geheiligten rolle"}}},fp="15,183,26.374.0,25.351.0,28.161.0,29.118.0,66.279.0"}
P.entries["item:hallowed-sigil"] = {n="Geheiligtes Siegelzeichen",s="In Laubschattental ruft das Geheiligte Siegelzeichen junge Nachtelfeninitianden nach Aldrassil. Shanda schickt es, um sie in den Dienst Elunes zu rufen.",h="In Laubschattental ruft das Geheiligte Siegelzeichen junge Nachtelfeninitianden nach Aldrassil.",kw={"aldrassil","geheiligtes siegelzeichen","init iand","kaldorei","priester","laubschattental","shanda","teldrassil"},ang={["class:Priest"]="Als Nachtelfenpriester erhaltet Ihr das Geheiligte Siegelzeichen als Eure erste Vorladung zur förmlichen Ausbildung unter der Sisterhood of Elune.",["race:NightElf"]="Als Anhänger der Kaldorei markiert das Siegelzeichen den Beginn Eures Dienstes, während die ersten Reisenden der Allianz auf den Ästen Teldrassils eintreffen."},sec={{t="Ein Ruf zum Priestertum",b="Junge Nachtelfenpriester in Laubschattental erhalten das Geheiligte Siegelzeichen von einem Boten des Waldes. Heilige Zeichen bedecken das Siegelzeichen, das eine persönliche Vorladung von Shanda trägt, der Priesterlehrerin in Aldrassil. Lest die Nachricht und steigt dann zur großen Höhlung von Aldrassil hinauf. Dort führt die Vorladung den Akolythen zur Sisterhood of Elune und leitet seinen Dienst für die Kaldorei ein, während überall auf Teldrassil neue Reisende eintreffen."}},faq={{q="Was ist das Geheiligte Siegelzeichen?",a="Junge Nachtelfenpriester in Laubschattental erhalten das Geheiligte Siegelzeichen, ein heiliges Zeichen mit einer Vorladung. Es weist den Initianden an, Shanda aufzusuchen, seine Mentorin.",al={"was ist das geheiligte siegelzeichen","priester siegelzeichen laubschattental"}},{q="Wer schickt das Geheiligte Siegelzeichen?",a="Ein Bote des Waldes überbringt das Geheiligte Siegelzeichen für Shanda, die Priesterlehrerin im Inneren von Aldrassil.",al={"wer hat dieses siegelzeichen geschickt","shanda priester siegelzeichen"}},{q="Wohin soll ich das Siegelzeichen bringen?",a="Bringt das Siegelzeichen zu Shanda im Inneren von Aldrassil, im Herzen von Laubschattental auf Teldrassil. Lest die Vorladung und legt ihr dann das Siegelzeichen vor, um erstmals Eure Mentoren im Priestertum kennenzulernen.",al={"wohin das geheiligte siegelzeichen bringen","geheiligtes siegelzeichen abgeben"}}},fx={["71c8963a"]={q="Warum möchte Shanda, dass das Geheiligte Siegelzeichen zu ihr zurückgebracht wird?",a="Das Siegel dient als formelle Vorladung und einführendes Zeichen für Novizenpriester der Nachtelfen. Priesterin Shanda sandte es durch einen Boten, um Euch nach Aldrassil zu rufen, und stellt sicher, dass Ihr ihren Rat sucht, während die größere Welt aufwacht und Reisende auf Teldrassil ankommen. Die Rückgabe bestätigt, dass Ihr ihre Nachricht erhalten habt und bereit seid, mit Eurer heiligen Ausbildung zu beginnen.",al={"warum geheiligtes siegelzeichen zu shanda bringen","warum will shanda das siegelzeichen","zweck des geheiligten siegelzeichens"}}},fp="14,133,27.408.0,27.149.0,29.96.0,30.188.0"}
P.entries["item:hallowed-tablet"] = {n="Geheiligte Schrifttafel",s="Im Tal der Prüfungen ruft die Geheiligte Schrifttafel junge Priester der Dunkelspeer zu Ken'jai. Ihre Worte leiten ihre Unterweisung in der Zwiesprache mit den Geistern ein.",h="Im Tal der Prüfungen ruft die Geheiligte Schrifttafel junge Priester der Dunkelspeer zu Ken'jai.",kw={"dunkelspeer","durotar","gornek","geheiligte schrifttafel","ken'jai","trollpriester","das tal der prüfungen"},ang={["class:Priest"]="Die Tafel leitet Eure förmliche Priesterausbildung in Durotar ein und knüpft Euer Band zu Ken'jai, Eurem Mentor.",["race:Troll"]="Für die Dunkelspeer bedeutet das Priestertum eine enge Zwiesprache mit den Geistern und Loa. Die Tafel lädt Euch ein, in diese spirituellen Traditionen der Ahnen einzutreten."},sec={{t="Ein Ruf der Geister",b="Gornek überreicht die Geheiligte Schrifttafel einem vielversprechenden Trollpriester, der seine ersten Schritte im Tal der Prüfungen macht. Darauf steht eine persönliche Einladung von Ken'jai, dem Priesterlehrer außerhalb des Den. Ken'jai deutet Zeichen und hört das Flüstern der Geister.\n\nWenn also junge Dunkelspeer mit spirituellem Potenzial in Durotar eintreffen, verkünden ihm die Geister ihre Ankunft. Die Tafel fordert den Novizen auf, ihre Botschaft zu lesen und Ken'jais Anleitung zur Lenkung spiritueller Autorität zu suchen."}},faq={{q="Was ist die Geheiligte Schrifttafel?",a="Im Tal der Prüfungen überreicht Gornek angehenden Trollpriestern eine beschriftete Steintafel. Ihre Botschaft verweist sie an Ken'jai, ihren Priesterlehrer.",al={"was ist dieser gegenstand","geheiligte schrifttafel hintergrund","was bewirkt die tafel"}},{q="Wer hat die Tafel geschickt?",a="Ken'jai hat die Tafel durch Gornek überbringen lassen. Die Geister sagten die Ankunft eines neuen Akolythen voraus, also ließ Ken'jai, der Priesterlehrer außerhalb des Den, ihm eine Nachricht zukommen.",al={"wer hat sie geschrieben","wer hat mir das gegeben","verfasser der tafel"}},{q="Warum müssen Trollpriester Ken'jai aufsuchen?",a="Priester der Dunkelspeer halten Zwiesprache mit den Geistern und gebieten über sie. Ken'jai begleitet Novizen, während ihre spirituelle Verbindung tiefer wird, und hilft sicherzustellen, dass die Geister bereit sind, sie mächtigere Fähigkeiten zu lehren.",al={"was macht kenjai","warum kenjai aufsuchen"}}},fp="15,147,26.486.0,28.144.0,20.144.0,41.186.0"}
P.entries["item:hand-of-dextren-ward"] = {n="Hand von Dextren Ward",s="In Dunkelhain warten trauernde Familien auf den Beweis, dass Dextren Ward im Verlies von Sturmwind hingerichtet wurde. Seine abgetrennte Hand soll als Zeichen dafür in die Stadt gebracht werden, dass ihn die Gerechtigkeit erreicht hat.",h="In Dunkelhain warten trauernde Familien auf den Beweis, dass Dextren Ward im Verlies von Sturmwind...",kw={"dunkelhain","dextren ward","dämmerwald","ebonlocke","hand von dextren ward","adelshaus","mühlenstein","morbent fel","verlies"},ang={["class:Mage"]="Als Magier wisst Ihr, dass Ward kein Zauberwirker war. Die Leichen, die er ausgrub, dienten Morbent Fels dunklen Künsten, also trifft Wards Tod jene, die mit den Toten Handel treiben.",["faction:Alliance"]="Für die Allianz offenbart Wards Gefangenschaft die tiefe Kluft zwischen Sturmwinds fernem Adelshaus und den im Stich gelassenen Grenzsiedlern des Dämmerwalds."},sec={{t="Der Preis der Schändung",b="Lord Ebonlocke verurteilte Dextren Ward zum Tode, nachdem er ihn dabei ertappt hatte, wie er auf Friedhöfen im Dämmerwald Leichen ausgrub. Ward verkaufte diese Leichen an den Nekromanten Morbent Fel. Sturmwind griff ein, bevor Dunkelhain ihn hinrichten konnte, und brachte ihn ins Verlies. Für die trauernden Familien beweist Wards Hand, dass der Schänder trotz der unerwünschten Milde des Adelshauses hingerichtet wurde."},{t="Eine Botschaft an den Adel",b="Mit seiner Forderung nach Wards abgetrennter Hand bietet Ratsherr Mühlenstein auch der Krone die Stirn. Der Dämmerwald fühlt sich von Sturmwinds Elite im Stich gelassen, die militärische Hilfe verweigert, ihre Autorität aber geltend macht, wenn es ihr passt. Indem der Rat von Dunkelhain einen Gefangenen im tiefsten Kerker der Hauptstadt hinrichten lässt und seine Hand einfordert, zeigt er dem Adelshaus, dass er seine eigenen Gesetze durchsetzen wird, wenn die Adligen versagen."}},faq={{q="Wer war Dextren Ward?",a="Dextren Ward wurde dabei ertappt, wie er Leichen auf Dunkelhains Friedhöfen ausgrub und sie an den Nekromanten Morbent Fel verkaufte. Der Dämmerwald verurteilte ihn zum Tod durch Enthauptung, doch Sturmwinds Obrigkeit brachte ihn ins Verlies, statt die Hinrichtung zu vollstrecken.",al={"dextren ward hintergrundgeschichte","wer ist dextren ward","wards verbrechen"}},{q="Warum will Dunkelhain seine Hand?",a="Ratsherr Mühlenstein fordert Wards abgetrennte Hand als Beweis für seine Hinrichtung. Sie lässt die Familien, deren Ahnengräber geplündert wurden, endlich Frieden finden und zeigt dem Adelshaus, dass Dunkelhains Rechtsprechung nicht außer Kraft gesetzt werden kann.",al={"warum abgetrennte hand","warum wards hand abtrennen","mühlensteins beweis"}},{q="Wo ist die Hand von Dextren Ward zu finden?",a="Die Hand wird Dextren Ward direkt in den tiefer gelegenen Kammern auf der linken Seite des Verlieses von Sturmwind abgenommen. Er kämpft als Krieger und verfügt über einen furchterregenden Schrei, der Feinde in die Flucht schlägt.",al={"wo ward finden","ward fundort verlies","dextren ward fundort"}},{q="Warum sperrte Sturmwind Ward ein, statt ihn hinzurichten?",a="Das Adelshaus beanspruchte die Gerichtsbarkeit über Ward und sperrte ihn ins Verlies, statt Dunkelhain die Vollstreckung seines Todesurteils zu gestatten. Dunkelhains Anführer sehen darin eine korrupte Einmischung, die die Not der Grenzstadt missachtet.",al={"warum wurde ward verschont","sturmwind adelshaus ward","ward eingesperrt"}}},fx={["48b9455f"]={q="Was ist die Hand von Dextren Ward?",a="Es ist die abgetrennte Hand von Dextren Ward, einem berüchtigten Grabräuber und Schänder der Toten, der dabei erwischt wurde, wie er Leichen aus dem Friedhof von Dunkelhain an den Nekromanten Morbent Fel verkaufte. Sie dient als physischer Beweis für seine Ermordung im Inneren von Sturmwind Stockade und ist die düstere Bestätigung dafür, dass das Todesurteil von Lord Schwarzhaupt endlich vollstreckt wurde.",al={"was ist die hand von dextren ward","gegenstand hand von dextren ward","hand von dextren ward"}},b59a9a35={q="Woher stammt die Hand von Dextren Ward?",a="Sie stammt direkt vom Körper von Dextren Ward und wurde von Eurer eigenen Klinge in seiner Zelle in Sturmwind Stockade abgetrennt. Sie wird nicht geschmiedet oder hergestellt, sondern als unwiderlegbare Trophäe der Gerechtigkeit genommen, die an Ratsherr Mühlenstein im Dämmerwald zurückgegeben werden muss.",al={"woher stammt die hand von dextren ward","wer erschuf die hand von dextren ward","ursprung der hand von dextren ward"}}},fp="20,181,16.374.0,23.378.1,21.246.0,33.225.0,40.189.0,57.245.0"}
P.entries["item:handful-of-oats-classic"] = {n="Hand voll Hafer",s="In Westfall braucht Old Blanchy Hafer, nachdem der Wagen der Furlbrows liegen geblieben ist.",h="In Westfall braucht Old Blanchy Hafer, nachdem der Wagen der Furlbrows liegen geblieben ist.",kw={"blanchy","furlbrow","getreide","hand voll hafer","hafer","hafersäcke","westfall"},ang={["faction:Alliance"]="Als Reisende der Allianz in Westfall könnt Ihr gestrandeten Flüchtlingen wie den Furlbrows eine kleine Barmherzigkeit erweisen, indem Ihr in Sturmwinds vernachlässigtem Grenzland Hafer sammelt."},sec={{t="Futter zwischen den Ruinen",b="Westfall ernährte einst das Königreich Sturmwind. Nun liegen seine Höfe überwuchert da oder stehen unter der Kontrolle von Defias-Banditen und abtrünnigen Erntegolems. Bei Scheunen und Nebengebäuden sowie auf überwucherten Feldern liegen noch Säcke mit Getreide und Hafer. Reisende und Flüchtlinge, deren Wagen auf den staubigen Straßen liegen bleiben, können den zurückgelassenen Hafer für ihre müden Zugpferde sammeln."}},faq={{q="Wofür wird eine Hand voll Hafer verwendet?",a="Der Hafer dient als Futter für Old Blanchy, die müde Stute der Familie Furlbrow. Ihr Wagen blieb auf einer Straße in Westfall liegen, und die Stute ist erschöpft und hungrig.",al={"wozu dient hafer","warum hafer sammeln","hand voll hafer verwendung"}},{q="Wo lässt sich dieser Hafer finden?",a="Hafer liegt in Säcken verstreut auf verlassenen Höfen in Westfall. Sucht besonders im Südwesten.",al={"wo hafer finden","hafersack fundort","wie hafer bekommen"}},{q="Warum bleiben die Hafersäcke unbewacht?",a="Die Bruderschaft der Defias erhob sich plötzlich, und abtrünnige Erntemaschinen wüteten auf den Feldern. Die Bauern flohen in aller Eile und ließen geerntetes Getreide und andere Vorräte auf ihren Feldern und in ihren Scheunen zurück.",al={"warum verlassene säcke","wer ließ den hafer zurück"}}},fx={["67495104"]={q="Was ist eine Hand voll Hafer?",a="Eine Hand voll Hafer ist einfaches Viehfutter, das aus den Jutesäcken geschöpft wurde, die auf den Farmen von Westfall verstreut sind. In fruchtbaren Zeiten ernährte dieses Getreide die Arbeitspferde und Pflugtiere des Königreichs. Heute, da die Felder den abtrünnigen Erntegolems und Banditen überlassen sind, gehört loser Hafer zu den wenigen sauberen Futterresten, die für ein hungriges Lasttier geblieben sind.",al={"was ist die hand voll hafer","gegenstand hand voll hafer","was ist eine hand voll hafer"}},a4d08151={q="Warum benötigt jemand eine Hand voll Hafer?",a="Verna Brauenwirbel benötigt sie dringend, um Old Blanchy, das treue Arbeitspferd ihrer Familie, zu nähren. Nachdem die Familie Brauenwirbel ihr Zuhause verlassen hatte, blieb ihr Wagen auf der Straße liegen, was dazu führte, dass Blanchy erschöpft, ausgehungert und am Ende ihrer Kräfte ist. Ein paar nahrhafte Handvoll Getreide sind alles, was die treue Stute am Leben hält, während die Familie feststeckt.",al={"wer benötigt die hand voll hafer","warum hafer sammeln","warum wird eine hand voll hafer benötigt"}}},fp="25,75,22.347.0,35.137.0,30.94.0,37.187.0"}
P.entries["item:handful-of-stardust"] = {n="Hand voll Sternenstaub",s="In den Sternenstaubruinen südlich von Astranaar sammelt sich Reif auf Büschen. Nachtelfenheiler nutzen das Pulver, um hohes Fieber zu senken.",h="In den Sternenstaubruinen südlich von Astranaar sammelt sich Reif auf Büschen.",kw={"eschental","astranaar","orendil","pelturas","umschlag","relara","die sternenstaubruinen","sternenstaub"},ang={["profession:Herbalism"]="Sammelt Sternenstaub von Hand von schimmernden Büschen. Er zeugt davon, wie die Nachtelfen seltene heimische Pflanzen in der Heilkunst nutzen.",["race:NightElf"]="Als Nachtelf, der das Eschental verteidigt, könnt Ihr die Verbindung zwischen örtlichen Heilmitteln und den uralten Ruinen und Kräutertraditionen Eures Volkes erkennen."},sec={{t="Ein kühlendes Kräuterheilmittel",b="Sternenstaub haftet an Sträuchern in den Sternenstaubruinen südlich von Astranaar. Sein feines Pulver schimmert wie Reif. Elementargeister verweilen zwischen den zerbrochenen Steinen, doch dort gedeihen Pflanzen und nehmen ein seltenes Leuchten auf. Nachtelfenheiler verarbeiten den Belag zu Umschlägen gegen gefährliches, hartnäckiges Fieber. Sie verwenden ihn, wenn gewöhnliche Salben und Mondbrunnenwasser keine vollständige Linderung bringen."},{t="Die Hoffnung eines Vaters",b="Pelturas Weißmond, ein besorgter Vater in Astranaar, folgte dem Rat des Kräuterkundigen Orendil Rundblatt und suchte nach dem Pulver. Seine kleine Tochter Relara litt unter einer hartnäckigen magischen Krankheit und Albträumen. Ein Segen von einem durch Elune berührten Stein beruhigte zunächst ihren Geist, doch ihr hohes Fieber blieb. Pelturas suchte Sternenstaub, um eine kühlende Paste herzustellen und ihr Leben zu retten."}},faq={{q="Wo findet man die Hand voll Sternenstaub?",a="Sammelt Sternenstaub von den schimmernden Büschen in den Sternenstaubruinen südlich von Astranaar im Herzen des Eschentals.",al={"sternенstaub fundort","wo sternenstaub finden","mit sternenstaub bedeckte büsche"}},{q="Wofür wird dieser Sternenstaub verwendet?",a="Nachtelfenheiler verwenden das Pulver in Umschlägen gegen gefährliches, hartnäckiges Fieber. Pelturas Weißmond suchte danach, um eine kühlende Paste für seine Tochter Relara herzustellen.",al={"verwendung von sternenstaub","pelturas heilmittel","sternенstaub zweck"}},{q="Welche Gefahren lauern rings um die Sternenstaubbüsche?",a="Feindliche Wasserelementare lauern nahe dem Ufer und zwischen den umgestürzten Säulen in den Sternenstaubruinen, wo die Büsche wachsen.",al={"sternenstaubruinen feinde","sternenstaubruinen mobs"}},{q="Steht Sternenstaub mit der Göttin Elune in Verbindung?",a="Die Ruinen tragen einen sternenreichen Namen, doch Kräuterkundige empfehlen Sternenstaub wegen seiner reifartigen, kühlenden Beschaffenheit als körperliches Heilmittel.",al={"ist sternenstaub magisch","elune verbindung sternenstaub"}}},fx={["8cce1335"]={q="Was ist eine Hand voll Sternenstaub?",a="Eine Hand voll Sternenstaub ist ein schimmerndes, gefrostetes Pulver, das von der glitzernden Vegetation in den alten Die Sternenstaubruinen im Eschental gesammelt wird. Dieser seltene pflanzliche Rückstand besitzt beruhigende, magisch kühlende Eigenschaften, was ihn unschätzbar wertvoll für die Zubereitung wirksamer Kräuterumschläge zur Behandlung hartnäckiger, lebensbedrohlicher Fieber macht.",al={"was ist eine hand voll sternenstaub","was ist sternenstaub","hintergrundinformationen sternenstaub"}}},fp="19,128,23.366.0,15.368.1,39.106.0,31.160.0,42.126.0,41.119.0"}
P.entries["item:hardened-tortoise-shell"] = {n="Gehärteter Schildkrötenpanzer",s="Auf der Schimmernden Ebene suchen Rennfahrer Panzer, die gefährlichem Treibstoff standhalten. Gnomische Rennfahrer auf der Illusionenrennbahn schätzen Gehärtete Schildkrötenpanzer von Glitzerschalen-Schildkröten, weil sie flüchtigen, ätzenden Versuchstreibstoffen widerstehen.",h="Auf der Schimmernden Ebene suchen Rennfahrer Panzer, die gefährlichem Treibstoff standhalten.",kw={"gehärteter schildkrötenpanzer","illusionenrennbahn","raketenwagen","die schimmernde ebene","glitzerschalen","wizzel kupferbolz"},ang={["profession:Engineering"]="Als Ingenieur könnt Ihr erkennen, warum sich organische Panzer für Hochdrucktreibstofftanks eignen könnten. Wenn gnomisch gebrauter Treibstoff gewöhnliche Legierungsrohre schmilzt, können widerstandsfähige Naturmaterialien sie ersetzen.",["race:Gnome"]="Als Gnom seht Ihr in einer Wüstenschildkröte vielleicht einen leichten, widerstandsfähigen Behälter für gefährlichen Raketentreibstoff."},sec={{t="Natürlicher Panzer für rasante Gefahren",b="Glitzerschalen-Schildkröten, von Schnappern bis zu Bohrern, durchstreifen die Salzebenen. Ihre Panzer schützen sie vor dem Salz und umherstreifenden Raubtieren. Gnomische Experimentalchemie kann metallene Treibstofftanks zerfressen oder zum Bersten bringen. Deshalb schätzen Mechaniker wie Wizzel Kupferbolz die Panzer als Rohmaterial für behelfsmäßige Tanks, die Säure widerstehen und flüchtige Raketentreibstoffe aufnehmen."}},faq={{q="Wo findet Ihr Gehärtete Schildkrötenpanzer?",a="Auf den offenen Salzflächen der Schimmernden Ebene in Tausend Nadeln findet Ihr Gehärtete Schildkrötenpanzer bei Glitzerschalen-Schnappern, Glitzerschalen-Bohrern und gewöhnlichen Glitzerschalen-Schildkröten.",al={"wo schildkrötenpanzer bekommen","gehärteter panzer fundort","glitzerschalen fundort"}},{q="Warum will Wizzel Kupferbolz diese Panzer haben?",a="Wizzel Kupferbolz will die Panzer für Treibstofftanks verwenden. Wizzels Bruder entwickelt einen äußerst leistungsstarken, ätzenden Raketentreibstoff, der das Fahrgestell ihres Rennwagens zu schmelzen droht. Wizzel plant, die widerstandsfähigen Panzer auszuhöhlen und zu verstärken.",al={"warum panzer benötigt","wizzel panzer verwendung","wozu dienen panzer"}},{q="Lassen sie sich mit gewöhnlichem Werkstattzeug leicht bearbeiten?",a="Nein. Die Panzer sind unnatürlich hart. Gnomische Mechaniker rechnen damit, beim Schnitzen, Bohren und Formen der Panzer zu Tanks einen ganzen Werkzeugkasten voller Metallwerkzeuge zu ruinieren.",al={"panzer schwer zu verarbeiten","werkzeuge verbiegen panzer"}}},fx={cc86b908={q="Was ist ein Gehärteter Schildkrötenpanzer?",a="Es ist der außergewöhnlich haltbare, natürliche äußere Panzer, der von den großen Funkelschuppenschildkröten geerntet wird, die durch die Salzebenen streifen. Diese Panzer sind als weitaus zäher bekannt als gewöhnliche Tierhäute oder Standardpanzerungen, da sie Reibung, Salz und intensiver chemischer Erosion widerstehen.",al={"was ist ein gehärteter schildkrötenpanzer","gegenstand gehärteter schildkrötenpanzer","gehärteter panzer"}},["4ed6fee7"]={q="Woher stammt ein Gehärteter Schildkrötenpanzer?",a="Diese Panzer sind vollkommen natürlich und nicht hergestellt. Sie werden direkt von den Funkelschuppenschildkröten, Schnappern und Bohrern geerntet, die in der rauen, sonnenverbrannten Salzwildnis der schimmernden Ebene in Tausend Nadeln gedeihen.",al={"ursprung eines gehärteten schildkrötenpanzers","wer fertigte den gehärteten schildkrötenpanzer","woher stammen gehärtete panzer"}}},fp="23,236,36.355.0,43.181.0,45.238.0,46.156.0"}
P.entries["item:hardened-tumor"] = {n="Verhärteter Tumor",s="Im Silberwald erforscht die Königliche Apothekervereinigung ein seltenes Gewächs in Vile Fin-Murlocs. Apotheker Berard dokumentierte es erstmals, bevor Arugals Fluch ihn zu einem willenlosen Diener machte.",h="Im Silberwald erforscht die Königliche Apothekervereinigung ein seltenes Gewächs in Vile Fin-Murlocs.",kw={"apotheker faranell","apotheker renferrel","berard","die morgeninseln","verhärteter tumor","der lordameresee","murloc","new plague","vile fin"},ang={["race:Undead"]="Als Untoter helft Ihr Apothekermeister Faranell, seine Forschungen zur New Plague voranzutreiben. Ihr dient Lady Sylvanas und dem Kampf der Verlassenen gegen lebende und untote Widersacher."},sec={{t="Eine seltene biologische Anomalie",b="Am Lordameresee entwickeln Vile Fin-Murlocs manchmal ein seltenes, verkalktes Gewächs. Apotheker Berard dokumentierte es, als er die Tierwelt entlang der östlichen Grenzen des Silberwalds erforschte. Es tritt nur bei ausgewachsenen Exemplaren entlang des Ufers und auf den Morgeninseln auf. Seine Ursache bleibt ungewiss, doch das dichte Gewebe erregte die Aufmerksamkeit der Königlichen Apothekervereinigung."},{t="Grundstoff für die New Plague",b="Nachdem Arugals Fluch Berard zu einem willenlosen Diener gemacht hatte, wurde sein Tagebuch aus Lohenscheit geborgen und zu Apotheker Renferrel im Grabmal gebracht. Renferrel erkannte das Potenzial der Arbeit und entsandte Agenten der Verlassenen, um einen Verhärteten Tumor und einheimische Wassermoose zu beschaffen.\n\nApothekermeister Faranell beaufsichtigt das Apothekarium in Unterstadt. Er sucht Reagenzien, die dem Verfall widerstehen oder biologisches Material verändern können, und nahm das Gewächs in die laufenden Arbeiten der Vereinigung an der New Plague auf."}},faq={{q="Was ist ein Verhärteter Tumor?",a="Ein Verhärteter Tumor ist eine seltene, anormale, verkalkte Masse, die sich im Inneren von Vile Fin-Murlocs rund um den Lordameresee bildet. Apotheker Berard entdeckte ihn, und seine ungewöhnlichen biologischen Eigenschaften lassen ihn dem gewöhnlichen körperlichen Verfall widerstehen.",al={"was ist dieser tumor","tumor hintergrundgeschichte","verhärteter tumor beute"}},{q="Warum will die Königliche Apothekervereinigung ihn haben?",a="Die Königliche Apothekervereinigung sammelt ungewöhnliche giftige und biologische Proben für ihre Arbeit an der New Plague. Apothekermeister Faranell hält den Tumor aufgrund seiner Widerstandsfähigkeit und Zellstruktur für einen Kandidaten für Seuchenexperimente.",al={"warum will apotheker tumor","recipe for death tumor verwendung","faranell tumor"}},{q="Wo findet man diese Tumore?",a="Vile Fin-Murlocs im Silberwald tragen diese Tumore, darunter jene nahe den Morgeninseln im östlichen Lordameresee und entlang der Dorfufer nordöstlich von Mühlenbern.",al={"wo verhärteten tumor finden","welche murlocs lassen tumor fallen","tumor fundort"}},{q="Wer war Apotheker Berard?",a="Apotheker Berard war ein im Silberwald stationierter Apotheker der Königlichen Apothekervereinigung. Er erforschte die örtliche Pflanzenwelt, Tierwelt und Mutationen bei Murlocs und entdeckte den Nutzen der Moose und verhärteten Tumore von den Morgeninseln. Arugals Fluch machte ihn zu einem willenlosen Diener in Lohenscheit.",al={"wer ist berard","berard hintergrundgeschichte","berards tagebuch"}}},fx={["9aa7efc6"]={q="Woher stammt ein Verhärteter Tumor?",a="Verhärtete Tumoren sind anormale biologische Wucherungen, die bei den Vile Fin-Murlocs gefunden werden, die rund um den Lordameresee im Silberwald leben. Sie werden nicht von sterblichen Händen gefertigt, sondern aus dem Fleisch dieser verseuchten amphibischen Kreaturen geerntet. Apotheker Berard dokumentierte ihr Vorkommen erstmals in seinen Feldforschungen und merkte an, dass es bemerkenswert selten ist, einen Murloc zu finden, der eine solch ungewöhnlich dichte, verkalkte Wucherung trägt.",al={"ursprung eines verhärteten tumors","woher stammen verhärtete tumoren","wer erzeugte den verhärteten tumor"}}},fp="14,179,25.353.0,23.477.1,25.212.0,46.223.0,29.175.0,26.287.0"}
P.entries["item:harpy-lieutenant-ring"] = {n="Harpyienoffiziersring",s="In den Trockenen Hügeln kennzeichnet der Harpyienoffiziersring den Rang der Witchwing Slayers, die den Schwarm befehligen. Darsok Schnelldolch im Wegekreuz verlangt die Ringe als Beweis für ihren Tod.",h="In den Trockenen Hügeln kennzeichnet der Harpyienoffiziersring den Rang der Witchwing Slayers, die den...",kw={"das wegekreuz","darsok schnelldolch","die trockenen hügel","harpyienoffiziersring","brachland","witchwing","witchwing slayer"},ang={["class:Rogue"]="Als Schurke bevorzugt Ihr vielleicht die gezielten Schläge, die Darsok Schnelldolch verlangt. Schleicht Euch in die Nistplätze der Harpyien und tötet ihre Anführerinnen.",["faction:Horde"]="Als Mitglied der Horde steht Ihr Witchwing-Harpyien gegenüber, die Nachschublinien zwischen Durotar, Mulgore und den nördlichen Außenposten bedrohen. Ihre Führung zu zerschlagen hilft, die Durchfahrt für Karawanen der Horde durch das Brachland zu sichern."},sec={{t="Zeichen des Ranges",b="Witchwing Slayers leiten Angriffe auf Reisende der Horde im Brachland. Ihre Ringe weisen sie als Anführerinnen über den gewöhnlichen Räuberinnen aus, die kaum koordiniert kämpfen. Darsok Schnelldolch und die Verteidiger im Wegekreuz brauchen Ringe von gefallenen Witchwing Slayers. Die Ringe bestätigen, dass ein Teil der Führung der Harpyien zerschlagen wurde."}},faq={{q="Wer trägt diese Ringe?",a="Witchwing Slayers tragen die Ringe als Offizierinnen im Witchwing-Schwarm der Trockenen Hügel.",al={"wer lässt den harpyienoffiziersring fallen","witchwing slayer ringe","welche harpyien haben ringe"}},{q="Wo sind Witchwing Slayers zu finden?",a="Witchwing Slayers nisten in den Trockenen Hügeln, nordwestlich vom Wegekreuz im nördlichen Brachland.",al={"witchwing slayer fundort","wo sind harpy lieutenants","harpyien der trockenen hügel"}},{q="Warum will Darsok Schnelldolch sie haben?",a="Darsok will die Ringe als Beweis dafür, dass die Witchwing Slayers getötet wurden. Ihr Tod zerschlägt einen Teil der Führung des Schwarms.",al={"warum harpyienringe sammeln","darsok schnelldolch ringe"}},{q="Tragen gewöhnliche Harpyienräuberinnen diese Ringe?",a="Nein. Die Ringe kennzeichnen Witchwing Slayers, während gewöhnliche Harpyienräuberinnen rangniedrigere Untergebene sind.",al={"können räuberinnen ringe fallen lassen","haben witchwing-räuberinnen ringe"}}},fx={["105f77c8"]={q="Was ist ein Harpyienoffiziersring?",a="Diese Ringe sind unverwechselbare Verzierungen, die von den Witchwing-Schlächtern der trockenen Hügel getragen werden. In ihren Nestern agieren die Schlächter als Offiziere, die die niederen Harpyienuntergebenen im Auftrag ihrer Matriarchinnen befehligen. Für die Kundschafter der Horde, die das Brachland beobachten, dienen diese Schmuckstücke als identifizierbarer Rangabzeichen innerhalb der bösartigen Schar.",al={"was ist ein harpyienoffiziersring","identität des harpyienrings","hintergrundinformationen harpyienoffiziersring"}}},fp="21,180,14.331.0,24.88.0,37.94.0,38.129.0,43.96.0"}
P.entries["item:head-of-arugal"] = {n="Arugals Kopf",s="In Burg Shadowfang wird Arugals Kopf dem wahnsinnigen Erzmagier abgenommen, der die Worgen befehligt. Die Verlassenen im Grabmal verlangen ihn als Beweis für seinen Fall.",h="In Burg Shadowfang wird Arugals Kopf dem wahnsinnigen Erzmagier abgenommen, der die Worgen befehligt.",kw={"arugal","arugal must die","dalar morgenweber","arugals kopf","das grabmal","burg shadowfang","silberwald"},ang={["class:Mage"]="Als Magier seht Ihr den abgetrennten Kopf eines ehemaligen Erzmagiers der Kirin Tor als Warnung vor Wahnsinn und Verderben, die verzweifelte Beschwörungen selbst begabten Zauberkundigen bringen können.",["race:Undead"]="Als Verlassener helft Ihr dabei, einen gefährlichen Zauberer vom Südrand des Silberwalds zu beseitigen und das Land für die Dark Lady zu sichern."},sec={{t="Trophäe des wahnsinnigen Erzmagiers",b="Erzmagier Arugal befehligt die Worgen von Burg Shadowfang im Silberwald aus. Im Grabmal befiehlt Dalar Morgenweber, seinen abgetrennten Kopf zu beschaffen. Die Verlassenen sehen Arugals Fall als Schlag gegen die Bestien, die Fürstin Sylvanas' Herrschaft über den Silberwald behindern. Bringt den Kopf zu Dawnweaver, und er beweist, dass Arugals Zauberei aus dem Land getilgt wurde."}},faq={{q="Wer will Arugals Kopf?",a="Dalar Morgenweber, ein Gesandter im Grabmal im Silberwald, verlangt den Kopf im Rahmen des Auftrags Arugal Must Die.",al={"wer braucht arugals kopf","arugals kopf abgeben","wer nimmt arugals kopf"}},{q="Wo erhaltet Ihr Arugals Kopf?",a="Arugals Kopf stammt von Erzmagier Arugal, der auf der höchsten Zinne von Burg Shadowfang über Lohenscheit und den Wäldern des Silberwalds haust.",al={"wie arugals kopf bekommen","arugals kopf beute","wo ist arugals kopf"}},{q="Warum wollen die Verlassenen Arugal tot sehen?",a="Die Verlassenen wollen Arugal tot sehen, weil er und sein Worgenrudel sie daran hindern, den Silberwald als sichere Bastion für Fürstin Sylvanas und Unterstadt zu sichern.",al={"warum arugal töten","verlassene arugal grund","warum will dalar arugal tot sehen"}},{q="Was geschieht nach der Abgabe des Kopfes?",a="Nachdem er den Kopf erhalten hat, schwört Dalar Morgenweber, die Überreste von Arugals Zaubern auszumerzen. Er erklärt den Silberwald für frei vom Griff des wahnsinnigen Magiers.",al={"nach arugals tod","ergebnis von arugal must die"}}},fx={c9f64370={q="Was ist Arugals Kopf?",a="Arugals Kopf ist der abgetrennte Kopf von Erzmagier Arugal, dem wahnsinnigen ehemaligen Zauberer von Dalaran, der die Worgen auf den Silberwald losließ. Er stammt aus seiner Festung in Burg Shadowfang und dient als unbestreitbarer physischer Beweis dafür, dass der verrückte Zauberer endlich erschlagen und seine dunklen Magien gebrochen wurden.",al={"was ist arugals kopf","gegenstand arugals kopf","arugals kopf"}},["10305f38"]={q="Woher stammt Arugals Kopf?",a="Der Kopf wird direkt von Erzmagier Arugal in den Höhen von Burg Shadowfang genommen. Nachdem Ihr in die verfluchte Festung eingedrungen seid und den wahnsinnigen Erzmagier im Kampf besiegt habt, streckt Ihr ihn nieder und nehmt seinen Kopf, um seinen Tod zu bestätigen.",al={"wo bekommt man arugals kopf","wer hinterlässt arugals kopf","ursprung von arugals kopf"}}},fp="14,152,26.345.0,29.128.0,39.144.0,37.160.0,41.147.1"}
P.entries["item:head-of-bazil-thredd"] = {n="Kopf von Bazil Thredd",s="Aufseher Thelwasser verlangt einen Beweis dafür, dass der Aufstand im Verlies niedergeschlagen wurde. Bazil Thredds abgetrennter Kopf soll beweisen, dass der Rebellenführer tot ist und die Herrschaft der Defias über Sturmwinds Gefängnis beendet ist.",h="Aufseher Thelwasser verlangt einen Beweis dafür, dass der Aufstand im Verlies niedergeschlagen wurde.",kw={"bazil thredd","defias","kopf von bazil thredd","verlies","the stockade riots","aufseher thelwasser"},ang={["faction:Alliance"]="Für die Allianz legt Thredds abgetrennter Kopf die akute Panik in der Hauptstadt. Er beweist, dass die Gerechtigkeit der Krone auch das rebellische Verlies erreichen kann."},sec={{t="Beweis für das Ende des Verrats",b="Bazil Thredd führte den Aufstand im Verlies unter Sturmwind an. Von seinem Zellenblock aus lenkte er die Unruhen mithilfe treuer Defias-Häftlinge. Aufseher Thelwasser misstraut Außenstehenden und ringt darum, die Ordnung aufrechtzuerhalten. Er verlangt Thredds Kopf, um den Tod des Rädelsführers zu beweisen und die Treue des Abenteurers gegenüber Sturmwind zu prüfen."}},faq={{q="Wer will den Kopf von Bazil Thredd?",a="Am Eingang zum Verlies verlangt Aufseher Thelwasser Bazil Thredds Kopf. Er will einen Beweis für den Tod des Rädelsführers, bevor er preisgibt, was er über Thredds Mitverschwörer weiß.",al={"wer braucht thredds kopf","wo thredds kopf abgeben","thredds kopf questgeber"}},{q="Wer war Bazil Thredd?",a="Bazil Thredd war ein hochrangiges Mitglied der Bruderschaft der Defias und unter Sturmwind eingekerkert. Als die Gefangenen rebellierten, übernahm er die Führung und koordinierte den Aufstand vom östlichen Zellenblock aus.",al={"wer ist bazil thredd","thredds geschichte","was hat bazil getan"}},{q="Wo ist Bazil Thredd zu finden?",a="Bazil Thredd befindet sich im östlichen Flügel des Verlieses, am hintersten Ende des Blocks in einer mittig gelegenen Zelle. Ihm treu ergebene Defias-Häftlinge bewachen die Zelle.",al={"wo ist thredd","thredds standort","wie bazil thredd finden"}}},fx={["4fd859a6"]={q="Was ist Kopf von Bazil Thredd?",a="Es ist der abgetrennte Kopf von Bazil Thredd, dem Gefangenen, der die Rebellion tief im Verlies orchestriert. Für Aufseher Thelwasser dient die Präsentation dieser düsteren Trophäe als unbestreitbarer physischer Beweis dafür, dass der Rädelsführer des Gefängnisaufstands endgültig beseitigt wurde.",al={"was ist kopf von bazil thredd","gegenstand kopf von bazil thredd","kopf von bazil thredd"}},fe91a8a0={q="Woher stammt Kopf von Bazil Thredd?",a="Er wird direkt von Bazil Thredd genommen, nachdem Ihr ihn in seiner Zelle im Sturmwind, im Verlies, konfrontiert und erschlagen habt, wo er den Aufstand unter dem Schutz seiner brutalen Wachen leitete.",al={"wo bekommt man den kopf von bazil thredd","wie bekommt man den kopf von bazil thredd","quelle für kopf von bazil thredd"}}},fp="20,202,22.327.0,35.171.0,21.197.0,28.143.0"}
P.entries["item:head-of-deepfury"] = {n="Tiefenzorns Kopf",s="Im Verlies von Sturmwind sühnt Kam Tiefenzorns Tod bei den Gefängnisaufständen das Leid der zwergischen Verteidiger von Dun Modr. Sein abgetrennter Kopf besiegelt das Ende eines Dunkeleisen-Verschwörers.",h="Im Verlies von Sturmwind sühnt Kam Tiefenzorns Tod bei den Gefängnisaufständen das Leid der zwergischen...",kw={"tiefenzorn","dun modr","tiefenzorns kopf","kam tiefenzorn","langzopf","motley garmason","verlies","thandol-übergang"},ang={["faction:Alliance"]="Die Forderung nach Tiefenzorns Kopf offenbart Spannungen innerhalb der Allianz. Die menschlichen Behörden von Sturmwind setzen auf rechtliche Vorsicht, während die Gebirgsjäger von Eisenschmiede harte Gerechtigkeit fordern.",["race:Dwarf"]="Für die Zwerge von Eisenschmiede sühnt das Abtrennen von Tiefenzorns Kopf den Verrat der Dunkeleisenzwerge am Thandol-Übergang."},sec={{t="Gerechtigkeit für einen Verschwörer",b="Kam Tiefenzorn wurde aus politischen Gründen im Verlies von Sturmwind festgehalten und durch die Diplomatie der Menschen vor der Hinrichtung bewahrt. Roggo deckte auf, dass Tiefenzorn den Angriff auf den Thandol-Übergang geplant hatte, bei dem König Magnis Soldaten und Langzopf des Grimmigen Angehörige starben. Die Gebirgsjäger von Eisenschmiede in Dun Modr konnten nicht hinnehmen, dass er weiterhin in Haft blieb. An seinen Posten gebunden, schickte Motley Garmason Champions der Allianz in das von Aufständen erschütterte Gefängnis, um Tiefenzorns Kopf zu holen und zwergische Rache zu üben."}},faq={{q="Wer war Kam Tiefenzorn?",a="Kam Tiefenzorn war ein Dunkeleisenzwerg, der die Sabotage des Thandol-Übergangs mitplante, der Landbrücke zwischen dem Sumpfland und dem Arathihochland. Seine Verschwörung kostete zwergische Verteidiger das Leben, darunter den Bruder von Langzopf dem Grimmigen.",al={"kam tiefenzorn hintergrund","wer ist tiefenzorn","kam tiefenzorn vorgeschichte"}},{q="Warum saß Kam Tiefenzorn im Verlies, statt hingerichtet zu werden?",a="Die Behörden von Sturmwind hielten Tiefenzorn aus politischen Gründen am Leben. Die Gebirgsjäger von Eisenschmiede empfanden diese Zurückhaltung als empörend und forderten seinen Tod.",al={"warum wurde tiefenzorn eingesperrt","warum verlies"}},{q="Wer will Tiefenzorns Kopf?",a="Motley Garmason, der in Dun Modr im nördlichen Sumpfland stationiert ist, will den Kopf. Seine Ehre verpflichtet ihn, an der Seite von Langzopf dem Grimmigen auf seinem Posten zu bleiben, also schickt er jemanden, um zu tun, was er selbst nicht kann.",al={"wer holt tiefenzorns kopf","fury runs deep abgeben"}},{q="Was bewirkt es, den Kopf zurückzubringen?",a="Tiefenzorns abgetrennten Kopf nach Dun Modr zu bringen, sühnt das Leid der trauernden Zwergenfamilien. Es rächt den erschlagenen Bruder von Langzopf dem Grimmigen und zeigt, dass politische Winkelzüge der Menschen Verbrechen gegen Eisenschmiede nicht unter den Teppich kehren werden.",al={"warum tiefenzorns kopf bringen","fury runs deep ergebnis"}}},fx={["42407f6f"]={q="Was ist Tiefenzorns Kopf?",a="Es ist der abgetrennte Kopf von Kam Tiefenzorn, einem inhaftierten Dunkeleisenzwerg, der tief im Sturmwind Stockade festgehalten wird. Ihr nehmt ihn als unwiderlegbaren physischen Beweis dafür, dass der Verschwörer hinter dem katastrophalen Angriff auf The Thandol Span endlich der Gerechtigkeit zugeführt wurde.",al={"tiefenzorns kopf","was ist tiefenzorns kopf","kopf von kam tiefenzorn"}},ff6e9a29={q="Woher stammt Tiefenzorns Kopf?",a="Der Kopf wird direkt von Kam Tiefenzorn selbst in den Zellen des Verlies unter Sturmwind genommen. Obwohl er von menschlichen Behörden eingesperrt und nicht hingerichtet wurde, müsst Ihr ihn in seiner Zelle niederstrecken, um ihn zu bergen.",al={"wo bekommt man tiefenzorns kopf","wer hinterlässt tiefenzorns kopf","quelle für tiefenzorns kopf"}}},fp="16,185,23.478.0,21.230.0,57.148.0,31.183.0,44.228.0"}
P.entries["item:head-of-gath-ilzogg"] = {n="Gath'Ilzoggs Kopf",s="Im Rotkammgebirge zerschlägt Gath'Ilzoggs Fall die Schwarzfelsführung hinter der Belagerung von Burg Steinwacht und bringt Seenhain dringend benötigte Entlastung.",h="Im Rotkammgebirge zerschlägt Gath'Ilzoggs Fall die Schwarzfelsführung hinter der Belagerung von Burg...",kw={"schwarzfels","gath'ilzogg","seenhain","magistrat solomon","rotkammgebirge","steinwacht","burg steinwacht"},ang={["faction:Alliance"]="Da die Hauptstadt durch interne Streitigkeiten abgelenkt ist, müssen Freiwillige der Allianz das Rotkammgebirge verteidigen und die Anführer des Schwarzfels selbst niederstrecken.",["race:Human"]="Für die Menschen von Sturmwind rächt der Sieg über Gath'Ilzogg das Massaker an unschuldigen Siedlern und den demütigenden Fall von Burg Steinwacht."},sec={{t="Kopfgeld auf einen Kriegsherrn",b="Gath'Ilzogg führte den Angriff des Schwarzfels an, der Burg Steinwacht einnahm und ihre Verteidiger vertrieb. Von dort aus wurde das Tal ständig mit Überfällen heimgesucht. Seenhain stand kurz vor dem Untergang, und Sturmwind schickte fast keine militärische Hilfe. Also setzte Magistrat Solomon ein Kopfgeld auf den Kriegsherrn aus.\n\nGath'Ilzogg fiel in den befestigten oberen Ebenen der Burg. Sein Tod zerschlägt die örtliche Führung des Schwarzfels. Für Seenhain ist dies der erste Schritt, um die Burg für das Königreich zurückzuerobern."}},faq={{q="Wer war Gath'Ilzogg?",a="Gath'Ilzogg war ein mächtiger Kriegsherr der Schwarzfelsorcs. Er führte die Eroberung von Burg Steinwacht an und lenkte Überfälle auf Siedlungen im Rotkammgebirge, wodurch er Seenhain an den Rand des Zusammenbruchs brachte.",al={"wer ist gath'ilzogg","gathilzogg geschichte","steinwacht boss"}},{q="Wohin wird der Kopf gebracht, sobald er erbeutet wurde?",a="Ihr bringt den Kopf zu Magistrat Solomon im Rathaus von Seenhain. Er beweist, dass der Kopfgeldauftrag von der Gesuchtentafel der Stadt erfüllt wurde.",al={"wer will den kopf","gath'ilzoggs kopf abgeben","magistrat solomon kopfgeld"}},{q="Was bedeutet Gath'Ilzoggs Tod für Seenhain?",a="Gath'Ilzoggs Tod nimmt den Schwarzfelsinvasoren ihren wichtigsten Taktiker im Rotkammgebirge. Viele Schwarzfelsorcs halten sich weiterhin überall in Steinwacht verschanzt, doch die Lücke in ihrer Führung gibt den örtlichen Verteidigern eine Chance, die Region zu halten.",al={"wird seenhain gerettet","bedeutung von gath'ilzoggs tod"}},{q="Wo wurde Gath'Ilzogg gefunden?",a="Gath'Ilzogg hielt sich in den oberen Bereichen von Burg Steinwacht auf, tief in der eroberten Festung. Seine persönlichen Leibwächter und Offiziere waren bei ihm.",al={"wo ist gathilzogg","lage von burg steinwacht"}}},fx={a1bebb0c={q="Warum möchte Magistrat Solomon Gath'Ilzoggs Kopf?",a="Magistrat Solomon setzte ein hohes Kopfgeld aus, das physische Beweise für den Tod des Kriegsherrn verlangte. Gath'Ilzogg war dafür verantwortlich, unschuldige Menschen abzuschlachten und Burg Steinwacht zu überrennen. Die Übergabe seines Kopfes versichert der Führung von Seenhain, dass die unmittelbare Bedrohung gebrochen ist, was Genugtuung bietet und Hoffnung auf die Rückeroberung der Burg gibt.",al={"warum will solomon gath'ilzoggs kopf","warum gath'ilzoggs kopf abliefern","kopfgeld auf gath'ilzoggs kopf"}},["0b5a65b1"]={q="Was ist Gath'Ilzoggs Kopf?",a="Es ist der abgetrennte Kopf von Gath'Ilzogg, dem Schwarzfelsorc-Kriegsherrn, der den Angriff auf Burg Steinwacht leitete und Raubzüge organisierte, die Seenhain bedrohten. Sein Kopf ist ein unwiderlegbarer körperlicher Beweis dafür, dass der brutale Anführer, der den Feldzug der Schwarzfelse in Rotkammgebirge leitete, endgültig beseitigt wurde.",al={"was ist gath'ilzoggs kopf","gathilzoggs kopf","kopf von gath ilzogg"}},ca6d6fe9={q="Woher stammt Gath'Ilzoggs Kopf?",a="Der Kopf wird Gath'Ilzogg direkt abgenommen, nachdem er in den Höhen von Burg Steinwacht getötet wurde. Der Kriegsherr hatte sich in der Festung verschanzt, die er erobert hatte, und weitere Angriffe auf die Bewohner des Rotkammgebirges geplant, bis ein Abenteurer sich in seine Festung wagte und den Kopf als Trophäe nahm.",al={"woher stammt gath'ilzoggs kopf","wer nahm gath'ilzoggs kopf","herkunft von gath ilzoggs kopf"}}},fp="19,133,18.453.0,20.185.0,39.133.0,49.230.0,28.152.0"}
P.entries["item:head-of-grimson"] = {n="Grimsons Kopf",s="In der Tiefenfelsmine beweist Grimsons Kopf, dass die Verlassenen ihre Reichtümer gesichert haben. Dalar Morgenweber empfängt die Trophäe im Grabmal, und die Mineralien der Mine können Varimathras' Feldzüge versorgen.",h="In der Tiefenfelsmine beweist Grimsons Kopf, dass die Verlassenen ihre Reichtümer gesichert haben.",kw={"arugal","dalar morgenweber","tiefenfelsmine","grimson der bleiche","grimsons kopf","das grabmal","silberwald","varimathras"},ang={["profession:Mining"]="Die Tiefenfelsmine zählt zu den wichtigsten Mineralvorkommen des Silberwalds. Ihr Vorarbeiter ist fort, sodass Roherz für die Nachschublinien der Horde verfügbar ist.",["race:Undead"]="Als Verlassene erfüllt Ihr mit der Einnahme der Mine die Pläne des Oberkommandos von Unterstadt. Sie beweist Eure Entschlossenheit, Lordaerons lebenswichtige Infrastruktur von den wahnsinnig gewordenen Überresten zurückzuerobern."},sec={{t="Die Tiefenfelsmine sichern",b="Dunkelpirscher, Späher der Verlassenen, entdeckten eine wachsende Bedrohung in den südöstlichen Hügeln. Die Schattenverzauberungen von Erzmagier Arugal korrumpierten die Arbeiter der Tiefenfelsmine und trieben ihren Vorarbeiter, Grimson den Bleichen, in den Wahnsinn. Vom Grabmal aus entsandte Dalar Morgenweber Recken, um Grimson zu töten und seinen abgetrennten Kopf zurückzubringen. Die Trophäe zeigt, dass die Mine von abtrünniger Magie befreit ist und ihre unterirdischen Reichtümer Varimathras' Truppen zur Verfügung stehen."},{t="Eine Trophäe für den Schreckenslord",b="Grimsons Kopf markiert das Ende seiner Herrschaft über die Tiefenfelsmine. Da der Vorarbeiter fort ist, können die Verlassenen ihre reichen Mineraladern abbauen und aus dem Erz Waffen und Rüstungen fertigen. Diese Vorräte unterstützen ihren Vormarsch durch den Silberwald und die benachbarten Gebiete Lordaerons."}},faq={{q="Wer war Grimson der Bleiche?",a="Grimson der Bleiche beaufsichtigte die Tiefenfelsmine in den südöstlichen Hügeln des Silberwalds. Arugals sich ausbreitende Shadow Magic korrumpierte ihn und die anderen Bergleute, bis die Verlassenen eingriffen.",al={"wer ist grimson","geschichte von grimson dem bleichen","grimsons hintergrund"}},{q="Warum will Dalar Morgenweber Grimsons Kopf?",a="Dalar Morgenweber will Grimsons Kopf als Beweis dafür, dass der korrumpierte Vorarbeiter tot ist. Varimathras will die Mineralien der Mine für die Kriegsanstrengungen der Verlassenen, und Grimsons Tod bricht den Widerstand der korrumpierten Bergleute in ihren Stollen.",al={"warum dalar den kopf will","zweck von grimsons kopf","warum den kopf mitnehmen"}},{q="Wo liegt die Tiefenfelsmine?",a="Die Tiefenfelsmine liegt in den Hügeln südöstlich des Grabmals im Silberwald. Die Verlassenen kämpfen mit den von Arugals Magie korrumpierten Überresten um ihre Mineralien.",al={"wo ist die tiefenfelsmine","grimsons aufenthaltsort","standort der mine im silberwald"}},{q="Welche Rolle spielt Varimathras bei dieser Aufgabe?",a="Varimathras lenkt von Unterstadt aus die Ausbreitung der Verlassenen in ganz Lordaeron. Die Ressourcen der Mine dienen seinen Plänen, indem sie Rohstoffe für seine Kriegsanstrengungen im Silberwald liefern.",al={"varimathras' rolle","warum will varimathras die mine","varimathras silberwald"}}},fx={f0354d96={q="Was ist Grimsons Kopf?",a="Grimsons Kopf ist der abgetrennte Kopf von Grimson der Bleiche, der als Beweis für seinen Tod genommen wird. Einst ein gewöhnlicher Aufseher, wurde Grimson durch die dunkle magische Verderbnis verzerrt, die durch Erzmagier Arugal im Silberwald freigesetzt wurde. Ihn zu beanspruchen markiert das Ende seines Kommandos über die Tiefenfelsmine und sichert den unbestreitbaren Beweis, dass die korrumpierte Führung der Mine gefallen ist.",al={"grimsons kopf","was ist grimsons kopf"}},["923cacb6"]={q="Woher stammt Grimsons Kopf?",a="Diese düstere Trophäe stammt direkt aus der Tiefenfelsmine, die sich in den Hügeln südöstlich vom Grabmal befindet. Sie wurde Grimson der Bleiche, dem verseuchten Vorarbeiter der Mine, von den Schultern getrennt. Grimson erlag den wilden Magien, die aus Pyrewood und Burg Shadowfang sickerten, und hielt die Mine, bis er auf Befehl von Dalar Morgenweber niedergestreckt wurde.",al={"wo bekommt man grimsons kopf","wer hinterlässt grimsons kopf","ursprung von grimsons kopf"}}},fp="15,198,27.409.0,26.275.1,25.184.0,46.226.0,36.158.0,45.173.0"}
P.entries["item:head-of-kelris"] = {n="Kelris Kopf",s="In der Tiefschwarzen Grotte sucht die Argentumdämmerung Kelris abgetrennten Kopf, um seinen Fall und das Ende seiner Opferungen zu bestätigen.",h="In der Tiefschwarzen Grotte sucht die Argentumdämmerung Kelris abgetrennten Kopf, um seinen Fall und das Ende...",kw={"aku'mai","argentumdämmerung","bashana runentotem","tiefschwarze grotte","blackfathom villainy","kelris kopf","selgorm","zwielichtfürst kelris"},ang={["faction:Alliance"]="Als Champion der Allianz bringt Ihr Kelris Kopf zu Dämmerungsbehüter Selgorm in Darnassus. Ihr rächt die Entweihung eines uralten Nachtelfentempels, der Elune geweiht war.",["faction:Horde"]="Als Abenteurer der Horde überreicht Ihr Kelris Kopf Bashana Runentotem in Donnerfels. Ihr gewinnt das Vertrauen des Zirkels des Cenarius und beweist Euren Einsatz dafür, Kalimdor von Verderbnis zu reinigen."},sec={{t="Eine Trophäe des Verderbens",b="In der Tiefschwarzen Grotte leitete Zwielichtfürst Kelris Opferungen an Aku'mai, einen monströsen Diener eines Alten Gottes. Ihm den Kopf abzunehmen besiegelt das Ende seiner Herrschaft über die Kultisten des Schattenhammers und ihre Verbündeten unter den Naga in der Höhle. Der Kopf muss an die Oberfläche gelangen, damit die Anführer wissen, dass seine blutigen Zeremonien ein Ende haben."},{t="Beweis für die Dämmerung",b="Monatelang hielt die Argentumdämmerung Kelris für tot oder verschollen. Dann kehrte sein Einfluss mit den vordringenden Schatten Kalimdors zurück. Sein Kopf, zu Vertretern in Darnassus oder Donnerfels gebracht, löst noch offene Kopfgelder ein und bestätigt, dass sein Versuch, die Welt ins Urchaos zu stürzen, vereitelt wurde."}},faq={{q="Wer war Zwielichtfürst Kelris?",a="Zwielichtfürst Kelris führte die Sekte des Schattenhammers in der Tiefschwarzen Grotte an. Im Bündnis mit den Naga opferte er Unschuldige an Aku'mai, eine Hydra im Dienste eines Alten Gottes. Er strebte nach dunkler Macht und uraltem Chaos.",al={"wer ist kelris","kelris geschichte","zwielichtfürst kelris"}},{q="Wer will Kelris Kopf?",a="Champions der Allianz bringen Kelris Kopf zu Dämmerungsbehüter Selgorm in Darnassus. Abenteurer der Horde bringen ihn zu Bashana Runentotem auf der Anhöhe der Ältesten in Donnerfels. Selgorm dient der Argentumdämmerung, während Bashana dem Zirkel des Cenarius angehört.",al={"wer nimmt kelris kopf","kelris kopf abgeben","wem kelris kopf geben"}},{q="Warum interessiert sich die Argentumdämmerung für Kelris?",a="Die Argentumdämmerung spürt Bedrohungen für Azeroth auf. Kelris hatte sich ihr lange entzogen. Seine Verehrung eines Alten Gottes und seine Opferungen Unschuldiger bedrohten das Gleichgewicht Kalimdors.",al={"warum argentumdämmerung kelris","argentumdämmerung tiefschwarze grotte"}},{q="Wo erhält man den Kopf?",a="Kelris Kopf stammt von seiner Leiche in seinem Sanktum innerhalb der Tiefschwarzen Grotte. Die Höhlen liegen unter dem Zoramstrand an der Küste des Eschentals.",al={"wo kelris kopf bekommen","kelris kopf fundort"}}},fx={c257c517={q="Was ist der Kelris Kopf?",a="Es ist der abgetrennte Kopf von Zwielichtfürst Kelris, dem Anführer der Kultisten des Schattenhammers, die tief in den Ruinen der Tiefschwarzen Grotte Wurzeln geschlagen haben. Er dient als grausamer, unbestreitbarer Beweis dafür, dass der finstere Meister des Kults im versunkenen Tempel erschlagen und seine Rituale beendet wurden.",al={"kelris kopf","was ist der kelris kopf","kelris kopf gegenstand"}},["0e645b89"]={q="Woher stammt der Kelris Kopf?",a="Der Kopf wird direkt von Zwielichtfürst Kelris in den Tiefen der Tiefschwarzen Grotte am Zoramstrand genommen. Ihr müsst Euch an seinen fanatischen Kultisten und abartigen Dienern vorbeikämpfen, um den Zwielichtfürsten in seinem inneren Heiligtum zu erschlagen, bevor Ihr ihn an Euch nehmen könnt.",al={"wo bekommt man den kelris kopf","ursprung des kelris kopfes","wie erhält man den kelris kopf"}}},fp="14,116,16.305.0,18.291.0,29.202.0,29.236.0,43.156.0,27.139.0"}
P.entries["item:head-of-targorr"] = {n="Targorrs Kopf",s="Im Verlies von Sturmwind haben Adlige Targorrs Hinrichtung aufgehalten. Der Orc diente einst Gath'Ilzogg im Rotkammgebirge, und Wache Berton in Seenhain fordert nun einen Beweis für seinen Tod.",h="Im Verlies von Sturmwind haben Adlige Targorrs Hinrichtung aufgehalten.",kw={"blackrock","gath'ilzogg","wache berton","targorrs kopf","seenhain","rotkammgebirge","verlies","targorr","targorr der schreckliche"},ang={["faction:Alliance"]="Für Champions der Allianz, die das Rotkammgebirge verteidigen, rächt Targorrs Tod die abgeschlachteten Verteidiger von Seenhain und umgeht die korrupte Adelsbürokratie in Sturmwind.",["race:Human"]="Als Mensch teilt Ihr vielleicht den Groll der Soldaten und Stadtwachen gegen Targorr, weil er während der Offensive des Schwarzfelsklans gefangene Truppen des Königreichs folterte."},sec={{t="Eine aufgeschobene Hinrichtung",b="Targorr der Schreckliche war der gefürchtete Henker von Gath'Ilzogg, dem Kriegsherrn des Schwarzfelsklans im Rotkammgebirge. Vor seiner Gefangennahme folterte und schlachtete er Verteidiger des Königreichs Sturmwind ab. Im Verlies von Sturmwind zum Tode verurteilt, wurde er verschont, als Adlige aus Sturmwind eingriffen. Wachleute wie Berton vermuten ein falsches Spiel und Korruption in der Hauptstadt."},{t="Gerechtigkeit im Grenzland",b="Wache Berton fürchtet, Targorr könnte zur politischen Spielfigur werden oder einen Ausbruch organisieren. Deshalb heuert er einen auswärtigen Champion an, der das von Unruhen erschütterte Gefängnis betreten und vollenden soll, was die Gerichte aufgeschoben haben. Targorr den Kopf abzuschlagen umgeht das blockierte Rechtssystem. Es bringt auch den trauernden Familien und den belagerten Verteidigern von Seenhain Gewissheit, die unter den Klingen des Henkers gelitten haben."}},faq={{q="Wer war Targorr der Schreckliche?",a="Targorr der Schreckliche war ein berüchtigter Orc-Henker des Schwarzfelsklans im Rotkammgebirge. Unter Kriegsherr Gath'Ilzogg folterte er gefangene Soldaten und Verteidiger von Sturmwind und richtete sie hin.",al={"targorr","targorr hintergrundgeschichte","wer ist targorr"}},{q="Warum wurde Targorr im Verlies am Leben gehalten?",a="Adlige aus Sturmwind setzten Targorrs Todesurteil auf mysteriöse Weise durch bürokratische Eingriffe aus. Die Wachen von Seenhain vermuten politische Machenschaften und Korruption und fürchten, dass er als Verhandlungsmasse am Leben gehalten wird.",al={"warum targorr nicht hinrichten","targorr hinrichtungsaufschub","verlies gerichtsverfahren"}},{q="Wer will Targorrs Kopf?",a="Wache Berton, der vor dem Gasthaus von Seenhain stationiert ist, will Targorrs abgeschlagenen Kopf. Nachdem Berton das Blutbad gesehen hat, das Targorr im Rotkammgebirge anrichtete, verlangt er einen Beweis dafür, dass der Henker niemals freikommen kann.",al={"wer nimmt targorrs kopf","wache berton","targorrs kopf abgeben"}},{q="Wo ist Targorr zu finden?",a="Targorr der Schreckliche wird im Verlies von Sturmwind festgehalten, hinter Eisengittern in den zentralen Zellenblöcken mit randalierenden Insassen.",al={"targorr aufenthaltsort","targorr finden","wo im verlies"}}},fx={["1b8c229f"]={q="Was ist der Targorrs Kopf?",a="Es ist der abgetrennte Kopf von Targorr der Schreckliche, dem berüchtigten obersten Scharfrichter, der unter dem Schwarzfels-Kriegsherrn Gath'Ilzogg diente. Targorr wurde gefangen genommen und im Sturmwind Stockade unter Todesstrafe festgehalten, weil er tapfere Verteidiger des Königreichs gefoltert und hingerichtet hatte.",al={"was ist der targorrs kopf","informationen zu targorrs kopf","beschreibung von targorrs kopf"}},["29061798"]={q="Woher stammt der Targorrs Kopf?",a="Der Kopf stammt von Targorr der Schreckliche selbst, der tief im Sturmwind Stockade eingesperrt war. Nachdem ein Adliger von Sturmwind seine geplante Hinrichtung aufgehalten hatte, beauftragt Wache Berton einen Abenteurer, die Angelegenheit selbst in die Hand zu nehmen und in die Gefängniszellen zu schleichen, um dem skrupellosen Orc den Kopf abzuschlagen.",al={"woher kommt der targorrs kopf","wer lässt targorrs kopf fallen","ursprung von targorrs kopf"}}},fp="15,187,19.344.0,16.356.0,26.183.0,43.205.0,25.202.0,23.118.0"}
P.entries["item:head-of-vancleef"] = {n="Van Cleefs Kopf",s="Auf der Späherkuppe beweist van Cleefs abgetrennter Kopf Westfall, dass der Anführer der Defias gefallen ist. Aus den Todesminen gebracht, beschert er der Volksmiliz einen hart erkämpften Sieg.",h="Auf der Späherkuppe beweist van Cleefs abgetrennter Kopf Westfall, dass der Anführer der Defias gefallen ist.",kw={"die todesminen","edwin van cleef","gryan starkmantel","van cleefs kopf","volksmiliz","späherkuppe","westfall"},ang={["class:Rogue"]="Edwin van Cleef war einer der tödlichsten Schurkenmeister in der Geschichte der Menschen. Sein Tod beendet eine beispiellose Laufbahn voller Schatten und Sabotage.",["faction:Alliance"]="Der Volksmiliz bringt van Cleefs Kopf einen befreienden Sieg. Er offenbart auch, wie wenig das Sturmwind House of Nobles in Westfalls dunkelster Stunde unternahm."},sec={{t="Beweis für den Sturz des Meisters",b="Westfalls Siedler brauchen einen Beweis dafür, dass die Gefahr vorüber ist. Monatelang lenkte Edwin van Cleef den Terror der Bruderschaft der Defias aus dem tiefsten Heiligtum der Todesminen. Bewaffnete Gesetzlose, Gobliningenieure und ein gewaltiger Kriegsjuggernaut bewachten ihn dort.\n\nGryan Starkmantel führt die Volksmiliz an und verlangt einen handfesten Beweis, bevor er das Umland für sicher erklärt. Van Cleefs abgetrennter Kopf wird ans Tageslicht gebracht. Er gibt den erschöpften Verteidigern die Gewissheit, dass der Baumeister ihres Untergangs Westfall nicht länger bedrohen kann."},{t="Ein düsterer Sieg",b="Van Cleefs Tod erfüllt Starkmantels Forderung zum Wohle Westfalls, doch der Anblick seines Kopfes wiegt schwer. Einst war er der verehrte Baumeister, der Sturmwind nach dem Ersten Krieg wiederaufbaute. Verrat und unbezahlte Schulden trieben ihn und die Stonemasons Guild in einen gesetzlosen Aufstand.\n\nSein Tod beendet den Feldzug der örtlichen Miliz und offenbart das Versagen des Königreichs, seine inneren Unruhen beizulegen. Freiwilligen Bauern und fremden Abenteurern blieb es überlassen, die hohe Gerichtsbarkeit zu vollstrecken."}},faq={{q="Wer will Van Cleefs Kopf?",a="Gryan Starkmantel, Hauptmann der Volksmiliz auf der Späherkuppe in Westfall, will den Kopf, um den langen Feldzug gegen die Bruderschaft der Defias abzuschließen.",al={"bei wem abgeben","wer nimmt van cleefs kopf","wohin mit van cleefs kopf"}},{q="Warum verlangt Gryan Starkmantel ausgerechnet seinen Kopf?",a="Die Bruderschaft der Defias hielt Westfall so lange in ihrem Griff, dass Gerüchte über van Cleefs Tod die Menschen nicht überzeugen würden. Starkmantel braucht einen handfesten Beweis, um die bedrängten Bauern zu beruhigen und zu zeigen, dass der Kampf der Miliz nicht vergebens war.",al={"warum seinen kopf nehmen","warum van cleefs kopf"}},{q="Wo erhält man den Kopf?",a="Der Kopf wird Edwin van Cleef an Bord seines geheimen Panzerschiffs am äußersten Ende der Todesminen unter Mondbruch im Südwesten Westfalls abgenommen.",al={"wo van cleefs kopf bekommen","wie van cleefs kopf bekommen"}},{q="Besiegelt van Cleefs abgetrennter Kopf das Ende der Bruderschaft der Defias?",a="Starkmantel sieht van Cleefs Tod als den Anfang vom Ende der Bruderschaft. Splittergruppen, abtrünnige Banditen und Sympathisanten halten sich noch immer in ganz Westfall, im Wald von Elwynn und darüber hinaus.",al={"ist die bruderschaft der defias vernichtet","was geschieht mit den defias"}}},fx={["4a1d52aa"]={q="Was ist der Van Cleefs Kopf?",a="Der Van Cleefs Kopf ist der abgetrennte Kopf von Edwin van Cleef, dem Drahtzieher hinter der Defias-Bruderschaft, die sich tief in den Todesminen versteckt. Er dient als grausamer, unbestreitbarer Beweis dafür, dass der Anführer des Aufstands der Gesetzlosen endgültig zur Strecke gebracht wurde.",al={"was ist der van cleefs kopf","van cleefs kopf gegenstand","edwin van cleef kopf"}}},fp="16,176,26.514.0,14.475.1,31.167.0,56.249.0,27.149.0,55.192.0"}
P.entries["item:heart-of-isha-awak"] = {n="Herz von Isha Awak",s="An der Händlerküste südlich von Ratschet suchen Jäger nach Isha Awaks Herz. Mahren Skyseer verlangt es als Beweis dafür, dass der Deep Doom bezwungen wurde.",h="An der Händlerküste südlich von Ratschet suchen Jäger nach Isha Awaks Herz.",kw={"deep doom","herz von isha awak","isha awak","mahren skyseer","die händlerküste","ratschet","brachland"},ang={["class:Hunter"]="Als Jäger stellt Ihr Euch einer Mutprobe, wenn Ihr den Deep Doom unter den Wellen der Händlerküste aufspürt und bezwingt.",["race:Tauren"]="Als Jäger der Tauren verfolgt Ihr Isha Awak im Einklang mit den wildesten Raubtieren der Natur, geleitet von der Ältesten Mahren Skyseer."},sec={{t="Trophäe des Deep Doom",b="Isha Awak durchstreift das Meer vor der Händlerküste, südlich von Ratschet. Seeleute und Küstenbewohner verehren und fürchten den gewaltigen Drescher namens Deep Doom gleichermaßen. Er hat viele menschliche Eindringlinge an der Küste getötet.\n\nMahren Skyseer, eine Mystikerin der Tauren, sieht in ihm ein ehrenhaftes Raubtier statt einer stumpfsinnigen Bedrohung. Sie glaubt, dass sein wilder Geist in seinem Herzen wohnt. Deshalb schickt sie tapfere Jäger in die Wellen, um Isha Awak in seinem eigenen Reich zu besiegen und sein Herz als Trophäe und spirituelle Opfergabe zu erbeuten."}},faq={{q="Was ist das Herz von Isha Awak?",a="Isha Awaks Herz stammt von dem riesigen Drescher, der die Gewässer südlich von Ratschet durchstreift. Jäger erbeuten es für Mahren Skyseer als Beweis dafür, dass sie den Deep Doom bezwungen haben.",al={"herz von isha awak","was ist dieses herz"}},{q="Wer will das Herz von Isha Awak?",a="Mahren Skyseer, eine Seherin der Tauren, die an der Händlerküste südlich von Ratschet lagert, will, dass Jäger das Herz beschaffen. Sie möchte die Macht der Bestie ehren und ihren Geist in sich aufnehmen.",al={"wer nimmt das herz","wem das herz geben","mahren skyseer"}},{q="Wo ist Isha Awak zu finden?",a="Isha Awak lebt im Meer vor der Händlerküste im Osten des Brachlands, südlich von Ratschet.",al={"isha awak fundort","wo ist isha awak","wo isha awak finden"}},{q="Warum will Mahren Skyseer das Herz?",a="Mahren Skyseer betrachtet Isha Awak als ehrenhaften Jäger und würdigen Gegner. Indem ein Jäger die Bestie erschlägt und ihr Herz in Händen hält, nimmt er den Geist des Meereswesens in sich auf.",al={"warum isha awak töten","warum will mahren das herz"}}},fx={["1c3e01c4"]={q="Woher stammt das Herz von Isha Awak?",a="Das Herz ist kein hergestelltes Artefakt, sondern ein Organ, das direkt von Isha Awak stammt, der mächtigen Seebestie, die als Untergang der Tiefe bekannt ist. Die Kreatur sucht die Gewässer vor der Küste des Brachlands südlich von Ratschet heim und wird von den örtlichen Menschen gefürchtet, deren Verwandte sie gefressen hat. Diesen Urzeit-Raubfisch zu erlegen und ihm das Herz herauszuschneiden, ist die einzige Möglichkeit, es zu erhalten.",al={"ursprung des herz von isha awak","woher kommt das herz von isha awak","wer hat das herz von isha awak gemacht"}}},fp="18,147,23.489.0,31.174.0,33.189.0,25.94.0,39.171.0"}
P.entries["item:heartswood"] = {n="Herzholz",s="Im nordwestlichen Eschental wird Herzholz von einem Baum geschlagen, der zwischen den Ruinen von Ordil'Aran wurzelt. Der Baum wuchs dort, wo einst zwei Liebende starben, und sein Holz lockt Sukkubi an, wenn Hexenmeister sie beschwören wollen.",h="Im nordwestlichen Eschental wird Herzholz von einem Baum geschlagen, der zwischen den Ruinen von Ordil'Aran...",kw={"anathera","eschental","gakin der dunkelbinder","herzholz","latherion","ordil'aran","sukkubus"},ang={["class:Warlock"]="Für Hexenmeister der Allianz ist die Beschaffung von Herzholz ein Übergangsritus unter der Anleitung von Gakin dem Dunkelbinder. Seine Resonanz liefert den emotionalen Köder, der nötig ist, um eine Sukkubus als Dienerin zu bezwingen und zu binden.",["race:NightElf"]="Als Nachtelf seht Ihr den Baum vielleicht als heiliges Denkmal für jene, die im Krieg der Ahnen fielen. Hexenmeister und Kultisten, die sein Holz schlagen, entehren das Andenken gefallener Ahnen."},sec={{t="Ein Denkmal der Hingabe",b="Zwischen den elfischen Steinen der Ruinen von Ordil'Aran im nordwestlichen Eschental schlug ein sonderbarer Baum Wurzeln. Der Legende nach fielen dort vor Jahrtausenden zwei Liebende, Anathera und Latherion, Seite an Seite im Krieg der Ahnen. Der Herzholzbaum wuchs aus der Erde, auf der sie starben. Noch heute trägt sein Holz die Erinnerung an ihre Hingabe in sich. Wer emotionale und spirituelle Bande erforscht, interessiert sich dafür."},{t="Ein Werkzeug der Unterwerfung",b="Herzholz erregt die Aufmerksamkeit von Sukkubi, Dämonen, die von Leidenschaft, Sehnsucht und emotionaler Ausbeutung angezogen werden. Hexenmeister der Menschen und Gnomen, die bei Gakin dem Dunkelbinder in Sturmwind lernen, suchen das seltene Holz, um einen rituellen Köder herzustellen. Seine Resonanz mit dem Opfer der Liebenden kann eine Sukkubus durch den Nether locken und in einen Beschwörungskreis ziehen. Dort kann der Beschwörer sie seinem Willen unterwerfen."}},faq={{q="Was ist Herzholz?",a="Herzholz stammt von einem Baum, der in den Ruinen von Ordil'Aran im Eschental wuchs, wo einst zwei nachtelfische Liebende gemeinsam im Krieg der Ahnen starben.",al={"herzholzbaum","was ist herzholz","herzholz geschichte"}},{q="Wer waren Anathera und Latherion?",a="Anathera und Latherion waren Liebende, die im Krieg der Ahnen Seite an Seite kämpften. Sie fielen im Kampf, und ihre letzte Umarmung nährte die Erde, auf der der Herzholzbaum als bleibendes Zeichen ihrer Hingabe wuchs.",al={"anathera und latherion","liebende des herzholzes","wer starb beim herzholzbaum"}},{q="Warum brauchen Hexenmeister Herzholz?",a="Sukkubi sind Dämonen, die von Verlangen und emotionaler Manipulation angezogen werden. Hexenmeister nutzen die Resonanz des Herzholzes mit unsterblicher Liebe als Köder, um eine Sukkubus in die körperliche Welt zu locken und sie zu beschwören.",al={"warum wollen hexenmeister herzholz","herzholz sukkubus","herzholz zweck"}},{q="Wo ist Herzholz zu finden?",a="Herzholz stammt aus den Ruinen von Ordil'Aran im nordwestlichen Wald von Eschental, nahe der Grenze zur Dunkelküste.",al={"herzholz fundort","wo ist herzholz","ruinen von ordil'aran herzholz"}}},fx={["61f35e8f"]={q="Woher stammt das Herzholz und wer hat es hergestellt?",a="Das Herzholz wurde nicht von sterblichen Händen gefertigt, sondern von einem einsamen Baum geerntet, der in den Ruinen von Ordil'Aran im nordwestlichen Eschental spross. Während des katastrophalen Krieges der Ahnen vor Jahrtausenden fielen zwei Liebende namens Anathera und Latherion gemeinsam im Kampf. Wo sie ihren letzten Atemzug taten, schlug der Baum Wurzeln und wuchs, als lebendiges Denkmal ihrer ewigen Verbundenheit.",al={"ursprung des herzholz","woher stammt das herzholz","wie wurde das herzholz geschaffen"}}},fp="10,201,22.420.0,21.390.1,19.157.0,32.223.0,32.184.0,30.113.0"}
P.entries["item:heartswood-core"] = {n="Herzholzkern",s="Unter Sturmwind nutzen Hexenmeister den Herzholzkern, um eine Sukkubus zu beschwören. Gakin der Dunkelbinder stellt den verzauberten Fokus aus dem Holz eines uralten Baumes bereit, um einen Durchgang zum Wirbelnden Nether zu öffnen.",h="Unter Sturmwind nutzen Hexenmeister den Herzholzkern, um eine Sukkubus zu beschwören.",kw={"gakin der dunkelbinder","herzholzkern","slaughtered lamb","sturmwind","sukkubus","beschwörungskreis","the binding","hexenmeister"},ang={["class:Warlock"]="Als Hexenmeister der Allianz nutzt Ihr den Herzholzkern, um während Eurer Ausbildung Eure erste Sukkubus zu beschwören und zu beherrschen."},sec={{t="Ein Fokus für den Nether",b="Unter dem Slaughtered Lamb im Magierviertel von Sturmwind vollziehen Hexenmeister ihre Riten fernab der Blicke der Stadtwache. Der Herzholzkern bündelt die Magie, die ein Bindungsritual einleitet. Aus dem Holz eines uralten Baumes gefertigt, birgt er genug verbliebene Macht, um den Schleier zwischen den Welten zu durchdringen. An einem geweihten Beschwörungskreis bündelt ein Initiat dunkle Künste durch den Kern und öffnet einen Durchgang zum Wirbelnden Nether. Eine Sukkubus überquert die Kluft."},{t="Die Prüfung der Bindung",b="Ein Hexenmeister, der einen Dämon beschwört, muss seine Überlegenheit über dessen listige und verführerische Natur beweisen, bevor er ihn beherrschen kann. Gakin gibt vielversprechenden Praktizierenden den Herzholzkern, damit sie sich dem beschworenen Dämon im Kampf stellen können. Sukkuben nutzen Schwächen aus und können schwache Geister überwältigen. Die Begegnung ist ein tödlicher Initiationsritus. Der angehende Hexenmeister muss den Unhold bezwingen und den verbrauchten Kern zu Gakin zurückbringen, um einen Willen zu beweisen, der den Diener dauerhaft binden kann."}},faq={{q="Wofür wird der Herzholzkern verwendet?",a="Hexenmeister nutzen den Herzholzkern am Beschwörungskreis unter dem Slaughtered Lamb, um einen Durchgang zum Wirbelnden Nether zu öffnen. Eine Sukkubus betritt unsere Welt, und Ihr müsst sie bekämpfen und binden.",al={"was bewirkt der herzholzkern","herzholzkern verwenden","zweck des herzholzkerns"}},{q="Wer stellt den Herzholzkern bereit?",a="Gakin der Dunkelbinder stellt den Herzholzkern bereit. Er ist ein Meisterhexenmeister, der Novizen in den verborgenen Katakomben unter dem Slaughtered Lamb im Magierviertel von Sturmwind ausbildet.",al={"woher kommt der herzholzkern","wer gibt den herzholzkern"}},{q="Wo muss der Kern verwendet werden?",a="Verwendet den Herzholzkern am Beschwörungskreis in den Krypten unter dem Slaughtered Lamb, tief unter den Straßen von Sturmwind.",al={"herzholzkern fundort","wo sukkubus beschwören"}},{q="Was geschieht nach Abschluss des Rituals?",a="Nachdem Ihr die Sukkubus beschworen habt, besiegt sie im Kampf und schickt sie in die Leere zurück. Bringt dann den Herzholzkern zu Gakin dem Dunkelbinder zurück, um zu lernen, wie Ihr den Dämon nach Belieben befehligt.",al={"was nach der beschwörung tun","herzholzkern abgeben"}}},fx={["34d5c17e"]={q="Was ist der Herzholzkern?",a="Der Herzholzkern ist ein verzaubertes okkultes Relikt, das speziell für Beschwörungsrituale angefertigt wurde. Er wurde von Praktizierenden der dunklen Magie vorbereitet und fungiert als magischer Katalysator, der stark genug ist, den Schleier zwischen den Welten zu durchdringen und eine Sukkubus aus dem Wirbelnden Nether in einen Beschwörungskreis zu ziehen.",al={"herzholzkern hintergrundgeschichte","was ist herzholzkern","herzholz gegenstand"}},a2df89b9={q="Woher stammt der Herzholzkern und wer hat ihn hergestellt?",a="Der Kern wird unter Verwendung von rohem Herzholz hergestellt, das aus den Ruinen von Ordil'Aran im Eschental geborgen wurde, und unter der Anleitung von Gakin der Dunkelbinder geformt und verstärkt. Gakin vertraut das fertiggestellte Relikt vielversprechenden Hexenmeistern an, die unter dem The Slaughtered Lamb in Sturmwind studieren.",al={"wer erschuf herzholzkern","herzholzkern ursprung","wie wurde herzholzkern hergestellt"}},cef9a99d={q="Warum möchte Gakin, dass der Herzholzkern verwendet wird?",a="Ein Hexenmeister, der einen Sukkubus binden möchte, benötigt einen Anker von immenser Macht, um ein Portal in die Leere zu öffnen. Ohne den Herzholzkern könnt Ihr den für die Manifestation des Dämons und die Unterwerfung seines tückischen Geistes notwendigen Ritualzauber nicht abschließen.",al={"warum herzholzkern verwenden","herzholzkern zweck hintergrund","warum herzholzkern wollen"}}},fp="15,202,22.443.0,20.458.1,37.194.0,33.176.0,28.125.0,42.179.0"}
P.entries["item:heavy-leaden-collection-phial"] = {n="Schwere bleierne Sammelphiole",s="In Kharanos bietet Ozzie Wechselvolt die Schwere bleierne Sammelphiole für die Dekontaminationsforschung an. Sie soll instabilen, verstrahlten Ausfluss von Mutanten tief in Gnomeregan aufnehmen und sicher einschließen.",h="In Kharanos bietet Ozzie Wechselvolt die Schwere bleierne Sammelphiole für die Dekontaminationsforschung an.",kw={"gnomeregan","hall of gears","schwere bleierne sammelphiole","ozzie wechselvolt","phiole","radioaktiver niederschlag","the only cure is more green glow"},ang={["profession:Engineering"]="Als Ingenieur könnt Ihr mit der Phiole flüchtigen Niederschlag sammeln. Selbst mit einem geeigneten Gefäß kann das Sammeln einer Probe mehrere Versuche erfordern.",["race:Gnome"]="Als Gnom bringt Euch jedes bisschen flüchtiger Niederschlag, das Ihr in der Phiole sichert, der Rückeroberung Gnomeregans und dem Verständnis des chemischen Wahnsinns näher, der Euch Eure Heimat nahm."},sec={{t="Ein abgeschirmtes Gefäß",b="Die Schwere bleierne Sammelphiole entzieht lebenden, verstrahlten Kreaturen in Gnomeregan flüchtige Rückstände. Den Niederschlag im Inneren zu halten, ist schwierig. Eine geeignete Probe zu sammeln, kann mehrere Versuche erfordern."},{t="Die Suche nach Heilung",b="Ozzie Wechselvolt stellt die Phiole bereit, um seine Forschung zur Umkehrung der schrecklichen Mutationen voranzubringen, unter denen Lepragnome leiden. Frühere Proben von Troggs an der Oberfläche waren zu schwach für eine brauchbare chemische Analyse.\n\nMit der bleiernen Phiole hoffen die Forscher, Proben von virulenten Bestien zu sammeln, darunter verstrahlte Schleime und Lauerer in der Hall of Gears. Sie suchen nach den aktiven Bestandteilen im giftigen Niederschlag der Stadt und hoffen, daraus ein wirksames Gegenmittel herzustellen."}},faq={{q="Wofür wird die Schwere bleierne Sammelphiole verwendet?",a="Die Phiole saugt konzentrierten radioaktiven Ausfluss aus lebenden, verstrahlten Kreaturen in Gnomeregan ab. Forscher in Kharanos verwenden die Proben für Dekontaminationsversuche.",al={"was bewirkt diese phiole","zweck der phiole","was ist die bleierne phiole"}},{q="Wer stellt die Schwere bleierne Sammelphiole bereit?",a="Ozzie Wechselvolt, ein Gnomenforscher in Kharanos in Dun Morogh, stellt die Phiole für seine Forschung zur Heilung verstrahlter und erkrankter Lepragnome bereit.",al={"wer gibt die phiole","wo gibt es die phiole","questgeber der phiole"}},{q="Warum besteht die Phiole aus schwerem Blei?",a="Die Phiole wird als schwer und bleiern beschrieben, doch ihre genaue Bauweise wird nicht erklärt. Ozzie warnt, dass sich der radioaktive Niederschlag nur schwer eindämmen lässt und die Probe rasch zerfällt.",al={"warum eine bleierne phiole","warum schweres blei"}},{q="Welchen Kreaturen müssen mit der Phiole Proben entnommen werden?",a="Die Phiole muss an lebenden, leuchtenden Schrecken tief in Gnomeregan eingesetzt werden. Dazu gehören verstrahlte Schleime, Lauerer und Schrecken, die in den unteren Ebenen der Hall of Gears umherstreifen.",al={"woran wird sie eingesetzt","zielkreaturen","welche monster leuchten"}}},fx={ca9f55e0={q="Warum möchte Ozzie Wechselvolt die Schwere bleierne Sammelphiole zurückhaben?",a="Ozzie Wechselvolt muss sowohl die Phiole als auch eine Probe hochwirksamer radioaktiver Ablagerungen in seine Werkstatt in Kharanos zurückbringen. Nachdem er zuvor schwächere Trogg-Exemplare getestet und diese für unzureichend befunden hatte, benötigt er unverfälschte, nicht korrumpierte Strahlung direkt von den Kreaturen aus Gnomeregan, um seine Experimente zur Heilung der betroffenen aussätzigen Gnome voranzutreiben.",al={"warum die schwere bleierne phiole zurückgeben","warum will ozzie die phiole","warum wird die sammelphiole benötigt"}}},fp="29,212,17.202.0,17.442.0,51.172.0,47.150.0,36.193.0,47.175.0"}
P.entries["item:hezrul-s-head"] = {n="Hezruls Kopf",s="An der Blühenden Oase befehligt Hezrul Bloodmark die Kolkarzentauren des Brachlands. Sein Kopf geht an Regthar Totenfurt westlich des Wegekreuzes, als Beweis dafür, dass ihr Häuptling gefallen ist.",h="An der Blühenden Oase befehligt Hezrul Bloodmark die Kolkarzentauren des Brachlands.",kw={"bloodmark","zentauren","das wegekreuz","deathgate","hezrul","kolkar","blühende oase","regthar"},ang={["faction:Horde"]="Als Mitglied der Horde sichert Ihr mit dem Kopf des Kolkarhäuptlings lebenswichtige Wasserrechte an der Blühenden Oase und schützt Reisende der Horde im Brachland.",["race:Orc"]="Als Ork seht Ihr die Kolkar vielleicht als undisziplinierte Raufbolde, deren Wut der orkischen Kampfdisziplin weicht. Regthar sieht die Trophäe als Beweis kriegerischer Ehre."},sec={{t="Die Kolkar enthaupten",b="Hezrul Bloodmark führt seinen Kolkarclan von der Blühenden Oase südlich des Wegekreuzes aus. Die Zentauren halten die Oasen des Brachlands und bedrohen die Nachschubwege und jungen Siedlungen der Horde.\n\nRegthar Totenfurt ist ein orkischer Veteran, der das Land westlich des Wegekreuzes sichern soll. Er sieht wilde Wut in den Kolkar, aber wenig Disziplin. Deshalb fordert er Hezruls abgetrennten Kopf, um die Führung des Clans zu zerschlagen und seine überlebenden Kämpfer zu zerstreuen, was ihre Angriffe auf die Horde schwächt."}},faq={{q="Wem gehört dieser Kopf?",a="Hezrul Bloodmark führt den Zentaurenclan der Kolkar im zentralen Brachland.",al={"wer ist hezrul","hezruls identität","wessen kopf ist das"}},{q="Wo ist Hezrul Bloodmark zu finden?",a="Hezrul führt seine Schar rund um die Blühende Oase, südlich des Wegekreuzes im Brachland.",al={"hezruls aufenthaltsort","wo ist hezrul","hezrul finden"}},{q="Wer will Hezruls Kopf?",a="Regthar Totenfurt, ein Ork an einem Militärposten an der Straße westlich des Wegekreuzes, will Hezruls Kopf als Beweis dafür, dass Hezrul besiegt wurde.",al={"hezruls kopf abgeben","wer nimmt hezruls kopf","regthar deathgate"}},{q="Warum verlangt die Horde seinen Kopf, statt ihn einfach zu vertreiben?",a="Die Horde braucht Gewissheit, dass Hezrul tot ist. Die Zentauren sind unberechenbar und neigen zu Kämpfen untereinander. Ihren Häuptling auszuschalten, zerschlägt ihre Führung und verringert die Gefahr, die sie für das Wegekreuz darstellen.",al={"warum hezrul töten","warum seinen kopf nehmen","bedrohung durch zentauren"}}},fx={["67b3da29"]={q="Woher stammt Hezruls Kopf?",a="Dieser abgetrennte Kopf stammt von Hezrul Bloodmark, einem gerissenen und brutalen Zentaurenhäuptling an der Blühenden Oase südlich des Wegekreuzes. Hezrul führt den Stamm der Kolkar in dieser Gegend und lenkt dessen Angriffe auf Außenposten der Horde und benachbarte Siedlungen, bis er niedergestreckt wird.",al={"herkunft von hezruls kopf","woher stammt hezruls kopf","von wem stammt hezruls kopf"}}},fp="13,177,23.465.0,29.70.0,32.85.0,24.143.0,69.186.0"}
P.entries["item:high-potency-radioactive-fallout"] = {n="Hochwirksame radioaktive Ablagerung",s="In Gnomeregans Tiefen suchen Forscher nach hochwirksamen radioaktiven Ablagerungen. Sie wollen herausfinden, wie der Schlamm die Lepragnome erkranken ließ, und ein Heilmittel finden.",h="In Gnomeregans Tiefen suchen Forscher nach hochwirksamen radioaktiven Ablagerungen.",kw={"gnomeregan","grünes leuchten","hall of gears","hochwirksame radioaktive ablagerung","verstrahlter schlamm","lepragnom","ozzie wechselvolt"},ang={["profession:Engineering"]="Flüchtige Ablagerungen zerfallen schnell, also transportiert sie in eigens dafür gefertigten Bleiphiolen, um Euch vor der Strahlung zu schützen.",["race:Gnome"]="Jede Probe giftiger Ablagerungen aus Gnomeregans Tiefen bietet eine schwache Hoffnung, die Mutation rückgängig zu machen, die Eure Artgenossen beim Fall der Stadt auseinandergerissen hat."},sec={{t="Direkt von der Quelle",b="Tief in der Hall of Gears durchstreifen verstrahlte Schrecken, Lauerer und Schlämme Gnomeregans unterste Ebenen. Forscher außerhalb der gefallenen Hauptstadt benötigen Ablagerungen, die diesen lebenden Kreaturen entnommen werden. Proben, die draußen von kontaminierten Aasfressern abgekratzt wurden, sind für ihre Arbeit zu schwach.\n\nDer Schlamm zerfällt schnell. Er muss in einer Bleiphiole versiegelt werden und die Forscher erreichen, bevor seine Wirksamkeit nachlässt."},{t="Die Suche nach Heilung",b="Ozzie Wechselvolt und seine Kollegen suchen nach einem Heilmittel für die Lepragnome. Sie glauben, dass die Geheimnisse des verstrahlten Schlamms ihnen den Weg weisen könnten. Während der Trogg-Invasion wurden diese Überlebenden durch das Ablassen giftiger Dämpfe entstellt und in den Wahnsinn getrieben.\n\nDie Lepragnome bleiben in einem lebenden Albtraum gefangen. Für die Forscher sind gefährliche Expeditionen in die Ruinen das Risiko wert."}},faq={{q="Woher stammen diese radioaktiven Ablagerungen?",a="Die Ablagerungen stammen von lebenden, verstrahlten Kreaturen tief in den unteren Ebenen von Gnomeregans Hall of Gears, darunter Schlämme, Schrecken und Lauerer.",al={"woher ablagerungen bekommen","fundort der ablagerungen","quelle radioaktiver ablagerungen"}},{q="Wozu wird diese Probe benötigt?",a="Gnomenforscher, darunter Ozzie Wechselvolt, benötigen eine konzentrierte Probe von Gnomeregans Strahlung, um die Krankheit zu erforschen und ein Heilmittel für die Lepragnome zu suchen.",al={"wer will die ablagerungen","zweck der ablagerungen","warum ablagerungen sammeln"}},{q="Warum muss die Probe so vorsichtig gehandhabt werden?",a="Die Ablagerungen zerfallen schnell und verlieren ihre Wirksamkeit. Sie müssen in einer Bleiphiole transportiert und zu den Forschern zurückgebracht werden, bevor sie zerfallen.",al={"zerfall der ablagerungen","warum bleiphiole","instabile ablagerungen"}},{q="Warum waren frühere Trogg-Rückstände nicht gut genug?",a="Rückstände von Troggs außerhalb der Stadt waren für Untersuchungen zu schwach und unrein. Forscher benötigen rohe, konzentrierte Ablagerungen von Kreaturen tief im verstrahlten Gnomeregan.",al={"warum kein trogg-leuchten","trogg-strahlung gegen ablagerungen","versagen der vorherigen probe"}}},fx={["30a827ed"]={q="Was ist eine Hochwirksame radioaktive Ablagerung?",a="Diese Ablagerung ist ein konzentrierter, flüchtiger Rückstand, der direkt von den stark verstrahlten Schleimen, Schrecken und Lauerern geerntet wird, die in den verfallenen Hallen von Gnomeregan umherwandern. Sie ist höchst instabil und leuchtet in giftiger Energie, was sie zum rohen Kontaminanten macht, der im Herzen der Katastrophe verweilt.",al={"was ist hochwirksame radioaktive ablagerung","radioaktive ablagerungen lore","was ist die ablagerung"}}},fp="32,146,21.383.0,24.362.0,46.145.0,26.163.0,36.138.0,45.166.0"}
P.entries["item:highborne-relic-classic"] = {n="Hochgeborenenrelikt",s="An der Dunkelküste umklammern Geister noch immer Highborne Relics, und Nachtelfengelehrte wollen sie zerstören. Ihre schlummernde Magie könnte weiteren Schaden anrichten.",h="An der Dunkelküste umklammern Geister noch immer Highborne Relics, und Nachtelfengelehrte wollen sie...",kw={"ameth'aran","arkan","dunkelküste","hochgeborene","hochgeborenenrelikt","schildwachen","thundris windweaver"},ang={["class:Mage"]="Als Magier findet Ihr die arkane Handwerkskunst der Relikte womöglich faszinierend. Die örtlichen Autoritäten der Nachtelfen bestehen darauf, dass sie zerstört werden.",["race:NightElf"]="Für Nachtelfen rufen diese Relikte die arkane Überheblichkeit in Erinnerung, die ihre uralte Zivilisation zerriss."},sec={{t="Überreste der Zerschlagung",b="Vor zehntausend Jahren brachte die Kaste der Hochgeborenen mit rücksichtsloser arkaner Magie Verderben über das uralte Kalimdor. Überall an der Dunkelküste liegen ihre Anwesen in Trümmern. In Ameth'Aran wandeln wehklagende Erscheinungen zwischen zerfallenden Säulen und umklammern noch immer die Werkzeuge ihrer einstigen Zauberei. Arkane Verderbnis bindet die Relikte an diese Geister, die jene Gegenstände nicht loslassen wollen, die mit ihrem Untergang verbunden sind."},{t="Die arkane Verderbnis tilgen",b="Nach der Großen Zerschlagung wandten sich die meisten Nachtelfen von der arkanen Magie ab. Ihre Gelehrten betrachten die Relikte nun als ernste Gefahr. Berichte der Schildwachen erreichten Thundris Windwirker in Auberdine, der Reisende aussendet, um den verfluchten Geistern die Relikte zu entreißen. Sobald die Relikte gesammelt sind, werden sie zerstört, damit sich die uralten Schrecken und verhängnisvollen Fehler der Hochgeborenen nicht wiederholen können."}},faq={{q="Woher stammen Highborne Relics?",a="Im Süden der Dunkelküste tragen die Geister, die Ameth'Aran heimsuchen, Highborne Relics in den uralten Ruinen östlich der Hauptstraße bei sich. Zwischen den Steinen umklammern die wehklagenden Geister sie.",al={"wo highborne relics finden","wer lässt highborne relics fallen","fundort der relikte"}},{q="Warum will Thundris Windwirker diese Relikte?",a="Thundris Windwirker fürchtet die arkane Verderbnis, die den Relikten anhaftet. Er lässt sie zur Zerstörung sammeln, damit niemand die gefährliche Zauberei der Hochgeborenen wiederbeleben kann.",al={"warum relikte sammeln","was geschieht mit den relikten","windweavers ziel"}},{q="Warum sind die Geister der Hochgeborenen noch immer in Ameth'Aran?",a="Die Geister sind uralte Adlige der Hochgeborenen, die starben, als die Welt vor zehntausend Jahren zerbrach. Ihre rastlosen Seelen bleiben an die Ruinen ihrer einstigen Stadt gebunden, verflucht durch ihren Hochmut und ihre Bindung an arkane Magie.",al={"warum sind geister in ametharan","wer sind die verfluchten hochgeborenen","warum geister an der dunkelküste"}},{q="Lassen sich Highborne Relics gefahrlos verwenden?",a="Nein. Die Nachtelfen betrachten die Relikte als verdorben durch die ungezügelten arkanen Praktiken, die die Große Zerschlagung auslösten. Ihre schlummernde Magie ist gefährlich, weshalb Gelehrte ihre Zerstörung statt ihrer Erforschung fordern.",al={"highborne relics verwenden","sind relikte gefährlich"}}},fx={["9b193d00"]={q="Was ist ein Hochgeborenenrelikt?",a="Ein Hochgeborenenrelikt ist ein altes magisches Instrument, das von den Hochgeborenen-Zauberern des alten Kalimdor erschaffen wurde. Diese verzauberten Werkzeuge überdauern in den Händen der rastlosen Geister, die in den zerstörten Ruinen von Ameth'Aran hausen, und tragen den bleibenden Makel der arkanen Zauberei in sich, die das Große Schisma herbeiführte.",al={"was ist hochgeborenenrelikt","hochgeborenenrelikte lore","was sind diese relikte"}}},fp="25,141,25.381.0,24.381.0,36.173.0,47.157.0,50.228.0,33.202.0"}
P.entries["item:highperch-venom-sac"] = {n="Steilhanggiftbeutel",s="Am Steilhang tragen Wyvern ein Gift, das Käufer in ganz Kalimdor suchen. Ihre Giftbeutel bringen selbst dort Handel in Gang, wo die Bestien nicht fliegen.",h="Am Steilhang tragen Wyvern ein Gift, das Käufer in ganz Kalimdor suchen.",kw={"fiora longears","heartrazor","der steilhang","gift","theramore","tausend nadeln","giftbeutel","wyvern"},ang={["class:Rogue"]="Als Schurke könnt Ihr im konzentrierten, lähmenden Gift ungezähmter Wyvern in Tausend Nadeln einige der stärksten natürlichen Gifte Kalimdors finden.",["faction:Alliance"]="Als Mitglied der Allianz könnt Ihr die Nester des Steilhangs angreifen, um wertvolle Handelsreagenzien zu erbeuten und wilde Wyvern zu dezimieren, die die Horde sonst vielleicht fangen und als Reittiere zureiten würde."},sec={{t="Eine wirksame Ernte",b="Wilde Wyvern nisten zwischen den Felsen des Steilhangs in Tausend Nadeln. Ihre mit Widerhaken besetzten Schwänze verabreichen ein Gift, das Beute lähmen oder töten kann. Die Horde zähmt Wyvern oft als Windreiter. In ganz Kalimdor zahlen Alchemisten, Jäger und Händler gut für die Giftbeutel."},{t="Eine ferne Käuferin",b="Steilhanggift erreicht Käufer weit jenseits des zentralen Kalimdor. In Theramore zahlt die Hochelfe Fiora Longears gut für frische Giftbeutel aus den Bruten des Steilhangs. Sie sucht prall mit Gift gefüllte Beutel, die meist bei jungen Wyvern oder fruchtbaren Weibchen zu finden sind. Fern ihrer Wüstenheimat handelt sie mit diesen gefährlichen Reagenzien."}},faq={{q="Welche Kreaturen tragen diese Giftbeutel?",a="Wilde Wyvern am Steilhang tragen die Beutel. Zu ihnen gehören Highperch Wyverns, Patriarchs, Consorts und die Matriarchin Heartrazor.",al={"wo gibt es giftbeutel als beute","wer hinterlässt highperch venom","wyverngift als beute"}},{q="Warum will Fiora Longears dieses Gift in Theramore?",a="Fiora Longears weiß, dass Wyverngift in manchen Handelskreisen hoch geschätzt wird, bisweilen höher als die Reittiere. Sie bezahlt Reisende, die zum Steilhang in Tausend Nadeln aufbrechen, damit sie unversehrte Giftbeutel für den Handel zurückbringen.",al={"warum will fiora gift","giftkäuferin in theramore","wer kauft wyverngift"}},{q="Sind alle Wyverngiftbeutel gleich?",a="Die Beutel unterscheiden sich in ihrer Wirksamkeit und ihrem Inhalt. Am begehrtesten sind prall mit Gift gefüllte Beutel, meist die von jungen Wyvern oder fruchtbaren Zuchtweibchen.",al={"qualität von wyverngift","prall gefüllte giftbeutel"}},{q="Wie nutzt die Horde diese Wyvern im Vergleich zur Allianz?",a="Die Horde fängt und züchtet Wyvern als fliegende Reittiere und Späher, die Windreiter genannt werden. Unabhängige Händler und Kontakte der Allianz ohne eigene Zähmungsnetzwerke erbeuten die tödlichen Reagenzien der Bestien.",al={"wyvernnutzung der horde","nutzen orcs das gift"}}},fx={["98761a97"]={q="Was ist ein Steilhanggiftbeutel?",a="Ein Steilhanggiftbeutel ist ein Organ, das von den wilden Wyvern geerntet wird, die auf dem hoch aufragenden Tafelberg von Der Steilhang im Tausend Nadeln nisten. Während Wyvern in ganz Kalimdor vor allem als geflügelte Reittiere der Horde bekannt sind, ist ihr Gift wegen seiner enormen Stärke begehrt. Die Beutel, die den Tieren auf dem Steilhang entnommen werden, sind besonders reichhaltig und geschwollen mit diesem tödlichen Toxin, was sie zu einer lukrativen Beute für Alchemisten und Händler macht, die mit exotischen Tier-Reagenzien handeln.",al={"was ist steilhanggiftbeutel","steilhanggiftbeutel","wyverngiftbeutel"}}},fp="19,123,16.261.0,15.310.0,38.125.0,53.203.0,36.137.0,66.206.0"}
P.entries["item:highperch-wyvern-egg"] = {n="Ei eines Steilhangflügeldrachen",s="Am Steilhang suchen Rekruten der Horde nach Flügeldracheneiern, um daraus Reittiere aufzuziehen. Die Nester liegen über den Tafelbergen von Tausend Nadeln.",h="Am Steilhang suchen Rekruten der Horde nach Flügeldracheneiern, um daraus Reittiere aufzuziehen.",kw={"elu","freiwindposten","der steilhang","ei eines steilhangflügeldrachen","tausend nadeln","wind rider","flügeldrache"},ang={["class:Hunter"]="Als Jäger müsst Ihr die wilden Raubtiere einschätzen, die den Steilhang bewachen. Ausgewachsene Flügeldrachen verteidigen ihre Nester mit Klauen und Giftstacheln.",["faction:Horde"]="Als Mitglied der Horde wisst Ihr, dass verlässlicher Luftverkehr die Kommunikation und militärische Bereitschaft in Kalimdors weitläufigen Gebieten aufrechterhält. Neue Flügeldrachen sind für beides wichtig."},sec={{t="Nester auf dem Tafelberg",b="Der Steilhang bietet heimischen Flügeldrachen einen Ort, um über Tausend Nadeln zu rasten und ihre Jungen aufzuziehen. Steile Pfade winden sich die Canyonwände hinauf zu den Nistplätzen, wo ausgewachsene Flügeldrachen ihre Nester bewachen. In festen, warmen Schalen warten Jungtiere darauf, sich Kalimdors rauem Himmel zu stellen."},{t="Neue Wind Rider heranziehen",b="Die Horde braucht mehr ausgebildete Flügeldrachen für ihre Kurier- und Spähernetzwerke in ganz Kalimdor. Am Freiwindposten suchen Rekruten wie der Tauren Elu nach unversehrten Eiern aus wilden Nestern. Sie ziehen die Jungtiere vom Schlüpfen an auf und hoffen, jene Bindung zu knüpfen, die einem Wind Rider ein verlässliches Reittier verschafft."}},faq={{q="Wo sind diese Eier zu finden?",a="Die Eier liegen in Nestern überall auf dem Steilhang, einem Tafelberg entlang der westlichen Felswände von Tausend Nadeln. Vom Grund des Canyons führt ein Pfad dorthinauf.",al={"fundorte der eier","wo flügeldracheneier finden","eier am steilhang finden"}},{q="Warum sammelt die Horde wilde Flügeldracheneier?",a="Die Reihen der Wind Rider der Horde wachsen, und ausgebildete Flügeldrachen sind knapp. Rekruten wie Elu sammeln Eier und ziehen die Jungtiere von Geburt an für den Einsatz in der Luft auf.",al={"warum flügeldracheneier stehlen","wozu dienen die eier","elu eierquest zweck"}},{q="Sind die Elterntiere den Eiersammlern gegenüber feindselig?",a="Ja. Wilde Flügeldrachen bewachen ihre Nester erbittert und greifen Eindringlinge an, die den Steilhang betreten, um ihre Gelege zu stören.",al={"greifen flügeldrachen an","beschützen flügeldrachen ihre nester"}},{q="Wer nimmt diese Eier am Freiwindposten entgegen?",a="Elu, ein angehender Wind Rider, der am Freiwindposten stationiert ist, sammelt Eier, um mit der Ausbildung eines eigenen Reittiers zu beginnen.",al={"wer nimmt flügeldracheneier","elu freiwindposten"}}},fx={efbaa71b={q="Was ist ein Ei eines Steilhangflügeldrachen?",a="Dies sind die lebensfähigen Eier wilder Wyvern, die hoch oben auf den Canyon-Tafelbergen im Tausend Nadeln nisten. In ihren robusten Schalen ruhen die noch nicht geschlüpften Jungen der geflügelten Raubtiere Kalimdors, die bei denjenigen sehr begehrt sind, die sich loyale Flugreittiere von klein auf aufziehen möchten.",al={"was ist ei eines steilhangflügeldrachen","wyvernei informationen","was sind diese eier"}},bbfa5024={q="Woher stammen Eier eines Steilhangflügeldrachen?",a="Sie werden von wilden Wyvern in ihren Nestern auf den Klippen vom Steilhang gelegt, einem erhöhten Plateau, das sich über den Canyons vom Tausend Nadeln erhebt. Die ausgewachsenen Wyvern bewachen ihre Horste erbittert gegen Raubtiere und waghalsige Plünderer gleichermaßen.",al={"woher kommen eier eines steilhangflügeldrachen","wer hat die eier gelegt","ursprung von wyverneiern"}}},fp="20,116,17.269.0,23.290.0,27.139.0,44.168.0,48.118.0,40.107.0"}
P.entries["item:hildelve-s-journal"] = {n="Hangflugs Tagebuch",s="In Dun Morogh bewahrt Hangflugs Tagebuch die letzten Worte eines Zwergs, der einem wilden Bären zum Opfer fiel. Seine Seiten berichten von dem Angriff und seiner Bitte um Rache.",h="In Dun Morogh bewahrt Hangflugs Tagebuch die letzten Worte eines Zwergs, der einem wilden Bären zum Opfer...",kw={"dun morogh","hildelve","eiskrallenbär","tagebuch","mangeclaw","pilot hammerfuß","belagerungsbrigade"},ang={["faction:Alliance"]="Als Mitglied der Allianz stärkt Ihr das Band zwischen der Allianz und der Belagerungsbrigade von Eisenschmiede, indem Ihr die persönlichen Habseligkeiten gefallener Soldaten wie Hildelve bergt.",["race:Dwarf"]="Als Zwerg könnt Ihr den unbeugsamen Geist der Piloten ehren, die eisiger Kälte und wilden Bestien trotzen, um die Höhen von Khaz Modan zu sichern."},sec={{t="Letzte Worte eines Piloten",b="Der Zwergenpilot Hildelve zog allein nach Dun Morogh, nachdem sein Dampfpanzer eine Panne hatte. Er ließ seinen Partner Hammerfoot bei den Panzern zurück und durchsuchte die schneeverwehten Klippen nach Chironerz, das es dort Gerüchten zufolge geben sollte. In seinem Tagebuch schreibt Hildelve, dass Mangeclaw, ein monströser Eiskrallenbär, ihm tagelang nachstellte, bevor er angriff.\n\nHildelve kämpfte tapfer und vertrieb den Bären, doch Mangeclaw richtete ihn übel zu und ließ ihn schwer verwundet in der Kälte zurück. Seine letzten Stunden waren qualvoll. Bevor der Bär zurückkehrte, äußerte Hildelve eine einzige Bitte: Wer seinen Leichnam fand, sollte Mangeclaw jagen und seinen Tod rächen."},{t="Rückkehr zur Belagerungsbrigade",b="Pilot Hammerfuß, Hildelves Kamerad, ist nahe dem Nordtoraußenposten im östlichen Dun Morogh stationiert. Hammerfoot gehört zur Belagerungsbrigade von Eisenschmiede und befürchtete das Schlimmste, als sein Partner von der Erzsuche nicht zurückkehrte. Das Tagebuch und Mangeclaws abgetrennte Klaue beweisen, dass Hildelves letzter Wunsch erfüllt wurde und sein Geist zur Ruhe gekommen ist."}},faq={{q="Wer war Hildelve?",a="Hildelve war ein Zwerg, der einen Dampfpanzer der Belagerungsbrigade von Eisenschmiede steuerte. Nachdem sein Panzer eine Panne hatte, zog er allein nach Dun Morogh, um nach Chironerz zu suchen. Mangeclaw tötete ihn, bevor er zurückkehren konnte.",al={"hildelves geschichte","wer ist hildelve","zwergenpilot hildelve"}},{q="Was ist Mangeclaw?",a="Mangeclaw ist ein ungewöhnlich großer, wilder Eiskrallenbär, der durch die verschneiten Bergkämme von Dun Morogh streift. Der Bär überfiel Hildelve, als dieser dort festsaß, und richtete ihn schwer zu. Dann kehrte Mangeclaw zurück, um seinem Leben ein Ende zu setzen.",al={"wer ist mangeclaw","was hat hildelve getötet","bär der hildelve getötet hat"}},{q="Wer erhält das Tagebuch, nachdem es gefunden wurde?",a="Pilot Hammerfuß erhält das Tagebuch. Hildelves Kamerad ist ein Belagerungsmaschinenpilot, der nahe dem Nordtoraußenposten im östlichen Dun Morogh stationiert ist. Er hatte nach Nachrichten über den vermissten Piloten gesucht.",al={"wohin mit dem tagebuch","wer bekommt hangflugs tagebuch","hangflugs tagebuch abgeben"}},{q="Worum bittet Hildelve im Tagebuch?",a="Hildelve bittet jeden, der seine sterblichen Überreste findet, Mangeclaw zu jagen und seinen Tod zu rächen. Auf den letzten Seiten des Tagebuchs nennt er die Bestie, die ihn angegriffen hat, und äußert seine Bitte, wohl wissend, dass seine Wunden tödlich sind.",al={"hildelves letzter wunsch","was steht im tagebuch","letzter wunsch des piloten"}}},fx={b58cc0e1={q="Was ist das Hangflugs Tagebuch?",a="Dieses zerfledderte Logbuch gehörte Hildelve, einem abgestürzten zwergischen Piloten der Belagerungsbrigade von Eisenschmiede. Es wurde neben seinen Überresten in den eisigen Weiten von Dun Morogh gefunden und hält seine erschütternden letzten Momente fest – es dokumentiert, wie er eine anfängliche brutale Verstümmelung durch den großen Bären Mangeclaw überlebte, und schildert seinen letzten Wunsch nach Rache, bevor das Biest zurückkehrte, um ihn zu töten.",al={"was ist dieses tagebuch","hangflugs tagebuch lore","über das hangflugs tagebuch"}},["308c8265"]={q="Woher stammt das Hangflugs Tagebuch und wer hat es geschrieben?",a="Das Tagebuch wurde von Pilot Hildelve selbst während seines Martyriums in Dun Morogh verfasst. Nachdem sein Dampfpanzer eine Panne hatte, suchte er zu Fuß nach Chironerz und wurde von dem Bären Mangeclaw zerfleischt; er führte diese persönlichen Aufzeichnungen bis zu seinem Tod und hinterließ ein schriftliches Testament seines Kampfes und seiner letzten Bitte.",al={"wer hat das tagebuch geschrieben","woher stammt das hangflugs tagebuch","ursprung des hangflugs tagebuchs"}},["856dae3f"]={q="Warum möchte jemand das Hangflugs Tagebuch haben?",a="Sein Kamerad, der Dampfpanzerpilot Pilot Hammerfuß, suchte verzweifelt nach Nachrichten von seinem verlorenen Kameraden. Das Tagebuch liefert einen endgültigen Beweis für Hildelves Schicksal und ehrt seine letzte Bitte um Vergeltung gegen das Monster, das ihm das Leben nahm, und bringt so seinen Freunden in der Belagerungsbrigade von Eisenschmiede einen Abschluss.",al={"warum das hangflugs tagebuch behalten","wer möchte das tagebuch","warum das hangflugs tagebuch zurückbringen"}}},fp="18,145,21.567.0,27.344.1,17.205.0,18.207.0,42.179.0,42.197.0"}
P.entries["item:hillsbrad-human-skull"] = {n="Menschlicher Schädel aus dem Hügelland",s="In Hillsbrad sammeln Verlassene die Schädel erschlagener Menschen. In Tarrens Mühle bewahren sie diese als düstere Andenken an den Angriff auf die örtlichen Siedlungen auf.",h="In Hillsbrad sammeln Verlassene die Schädel erschlagener Menschen.",kw={"darthalia","hillsbrad","samsa","schädel","süderstade","tarrens mühle","trophäe"},ang={["faction:Alliance"]="Als Mitglied der Allianz seht Ihr, wie Hillsbrads Bauern und Soldaten zu bloßen Andenken werden, ein Zeichen der Grausamkeit des Feldzugs der Verlassenen in Lordaeron.",["race:Undead"]="Als Verlassener seht Ihr in den Schädeln vielleicht Vergeltung und eine düstere Erinnerung an die lebenden Verwandten, die Euch meiden."},sec={{t="Trophäen eines erbitterten Krieges",b="Die Streitkräfte der Verlassenen aus Tarrens Mühle bekämpfen die Menschen von Süderstade und den umliegenden Siedlungen. Während der Battle of Hillsbrad führen Todespirscher und Soldaten die von Darthalia befohlene Säuberung durch. Die zum Wachdienst zurückgelassenen Wachen wollen ihren Anteil am Gemetzel.\n\nTodeswache Samsa sammelt Schädel von Kämpfern an der Front. Es bereitet ihm Freude, die Überreste von Menschen aufzubewahren, unter denen die Verlassenen einst lebten. Die Trophäen zeugen von den Tötungen, während der Konflikt tobt."}},faq={{q="Wer will diese menschlichen Schädel?",a="Todeswache Samsa, ein Wachposten der Verlassenen in Tarrens Mühle, sammelt die Schädel. Neidisch auf die Soldaten, die in Hillsbrad kämpfen und plündern dürfen, während er Wache steht, bittet er vorbeiziehende Abenteurer um dreißig Schädel für seine Privatsammlung.",al={"wer will schädel","wer nimmt menschliche schädel","todeswache samsa schädel"}},{q="Wo werden Menschliche Schädel aus dem Hügelland gesammelt?",a="Verlassene sammeln im gesamten Vorgebirge des Hügellands Schädel von menschlichen Kämpfern und Arbeitern. Viele stammen aus der Nähe der von Menschen gehaltenen Bauernhöfe, Minen und Stadtbefestigungen, die während der Battle of Hillsbrad angegriffen werden.",al={"wo werden schädel erbeutet","menschliche schädel farmen","wer lässt menschliche schädel fallen"}},{q="Warum sammeln die Verlassenen menschliche Überreste?",a="Manche Verlassene sammeln menschliche Überreste aus Hass und schwarzem Humor. Soldaten wie Samsa bewahren die Schädel als Kuriositäten und als Beweis dafür auf, dass Hillsbrad kurz vor der Niederlage steht.",al={"warum wollen verlassene schädel","schädelsammlung der verlassenen"}}},fx={["0091f8c0"]={q="Was ist ein Menschlicher Schädel aus dem Hügelland?",a="Dies sind die grausamen Trophäen, die von gefallenen menschlichen Verteidigern und Stadtbewohnern abgetrennt wurden, die über das Vorgebirge des Hügellands verstreut sind. Da der Konflikt zwischen den Verlassenen von Tarrens Mühle und den lebenden Menschen vom Hügelland tobt, dienen solch makabre Zeichen als greifbarer Beweis für Verluste der Allianz in dem umkämpften Gebiet.",al={"was sind menschliche schädel aus dem hügelland","hügelland schädel gegenstand","informationen zu menschlichen schädeln aus dem hügelland"}},["9eb161fa"]={q="Woher stammt ein Menschlicher Schädel aus dem Hügelland und wer hat ihn hergestellt?",a="Diese Schädel werden direkt den sterblichen Menschen entnommen, die das Vorgebirge des Hügellands bewohnen, und von Kämpfern der Horde geerntet, die am anhaltenden Grenzkrieg beteiligt sind. Anstatt hergestellt zu werden, sind sie morbide Überbleibsel des Schlachtfelds, die von den getöteten Soldaten, Bauern und Bürgern stammen, die die dortigen menschlichen Siedlungen gegen die Verlassenen verteidigten.",al={"ursprung menschlicher schädel aus dem hügelland","woher kommen hügelland schädel","wer macht hügelland schädel"}},a9ea879b={q="Warum möchte Todeswache Samsa Menschliche Schädel aus dem Hügelland haben?",a="Todeswache Samsa, der in Tarrens Mühle Wache schiebt, ist unglaublich neidisch auf die Krieger, die ausgesandt werden, um die Lebenden zu plündern und zu bekämpfen. Da er hinter den Frontlinien feststeckt, sammelt er die Schädel als kostbare persönliche Souvenirs of Death, um stellvertretend am Schlachten der menschlichen Verteidiger vom Hügelland teilzuhaben.",al={"warum möchte samsa schädel","wer möchte menschliche schädel aus dem hügelland und warum","warum menschliche schädel aus dem hügelland sammeln"}}},fp="21,143,24.447.0,29.227.0,42.203.0,42.160.0"}
P.entries["item:hillsbrad-town-registry"] = {n="Stadtverzeichnis von Hügellandhof",s="Auf den Feldern von Hillsbrad verwahrt das Rathaus die Namen und Landrechte der Verbliebenen. Das Stadtverzeichnis von Hügellandhof hält die städtische Ordnung fest, und die Verlassenen wollen es bei ihrem Angriff auf die menschliche Bastion erbeuten.",h="Auf den Feldern von Hillsbrad verwahrt das Rathaus die Namen und Landrechte der Verbliebenen.",kw={"battle of hillsbrad","darthalia","die felder von hillsbrad","rathaus von hillsbrad","stadtverzeichnis von hügellandhof","magistrate burnside"},ang={["faction:Horde"]="Für die Horde hilft die Eroberung des Stadtverzeichnisses, die menschliche Herrschaft im Vorgebirge zu brechen und die Bastion der Verlassenen in Tarrens Mühle zu sichern.",["race:Human"]="Als Mensch könnt Ihr erkennen, dass das Verzeichnis die formelle Existenz und die Rechte der verbliebenen Stadtbewohner von Hillsbrad dokumentiert. Sein Verlust würde die Gemeinschaft der Region schwer treffen."},sec={{t="Ein Zeugnis des Widerstands",b="Das Stadtverzeichnis von Hügellandhof enthält die Namen und Rechte der Stadtbewohner. Es liegt im Rathaus nahe dem Rednerpult von Magistrate Burnside. Von Tarrens Mühle aus drängen die Verlassenen darauf, den menschlichen Widerstand im Vorgebirge zu brechen. Darthalia schickt Champions der Horde ins Rathaus, um den Rat zu töten und das Verzeichnis an sich zu reißen.\n\nSeine Seiten verzeichnen Hillsbrads Bevölkerung, Haushalte und Verwaltungsrechte. Die Verlassenen wollen damit die städtische Ordnung zerschlagen und mehr über die überlebenden Bewohner und deren Besitz erfahren."}},faq={{q="Wo wird das Stadtverzeichnis von Hügellandhof aufbewahrt?",a="Das Stadtverzeichnis von Hügellandhof wird in einer Ecke des Rathauses auf den Feldern von Hillsbrad aufbewahrt, nahe der Treppe zum Podest von Magistrate Burnside.",al={"standort des verzeichnisses","wo ist das stadtverzeichnis","verzeichnis von hillsbrad finden"}},{q="Warum wollen die Verlassenen es stehlen?",a="Hochexekutorin Darthalia will die menschliche Herrschaft im Vorgebirge zerschlagen. Das Verzeichnis erfasst die Bürger, Haushalte, Verwaltungsrechte und Besitztümer der Stadt und liefert den Verlassenen Wissen über die verbliebene Gemeinschaft.",al={"warum das verzeichnis stehlen","darthalias quest zum verzeichnis","zweck des verzeichnisses"}},{q="Wer bewacht das Verzeichnis?",a="Magistrate Burnside und die Hillsbrad Councilmen bewachen das Verzeichnis. Sie wirken Schutzmagie und sammeln sich im Rathaus und darum herum.",al={"wer schützt das verzeichnis","verteidiger des rathauses"}}},fx={["188a667c"]={q="Was ist das Stadtverzeichnis von Hügellandhof?",a="Das Stadtverzeichnis von Hügellandhof ist ein offizielles Register, das sich in der Stadthalle der Siedlung Die Felder von Hillsbrad befindet. Es wird von der örtlichen Verwaltung der Menschen unter Magistrate Burnside geführt und dokumentiert die zivilen Angelegenheiten, die Bevölkerung und die Verwaltung eines der überlebenden Außenposten der Allianz in den Ausläufern.",al={"was ist das stadtverzeichnis von hügellandhof","hügellandhof verzeichnis","was ist das verzeichnisbuch"}}},fp="23,209,20.486.0,42.136.0,37.220.0,24.138.0"}
P.entries["item:hollow-vulture-bone"] = {n="Hohler Geierknochen",s="Über der Schimmernden Ebene kreisen Geier über dem Salz, während Goblintrupps ihre Knochen sammeln. An der Illusionenrennbahn nutzen Mechaniker die hohlen Überreste, um Raketenwagen leichter zu machen, ohne ihre Stabilität zu beeinträchtigen.",h="Über der Schimmernden Ebene kreisen Geier über dem Salz, während Goblintrupps ihre Knochen sammeln.",kw={"hohler geierknochen","load lightening","illusionenrennbahn","pozzik","aasfresser","die schimmernde ebene","tausend nadeln"},ang={["class:Hunter"]="Als Jäger könnt Ihr die widerstandsfähigen, aasfressenden Geier über die blendende Salzfläche hinweg aufspüren.",["profession:Engineering"]="Goblinrennfahrer verwenden hohle Vogelknochen, um dort Gewicht zu sparen, wo Eisen und Bronze schwer wären. Ihre Wahl zeigt einen praktischen Ansatz beim Bau von Rennwagen."},sec={{t="Rennmaterial aus der Ebene",b="An der Illusionenrennbahn suchen Goblin-Boxencrews nach jeder Möglichkeit, ihre Raketenwagen schneller zu machen. Gewicht bremst einen Wagen, also verwenden sie neben Eisen und Kupfer auch das, was die Wüste bietet. Hohle Geierknochen sind leicht und dennoch stabil genug für Lenkgestänge, innere Halterungen und kleine Stützen. Pozzik und die anderen Cheftüftler sammeln sie von örtlichen Aasfressern, um auf der Rennstrecke Sekunden einzusparen."}},faq={{q="Warum wollen die Goblins Geierknochen?",a="Pozzik und andere Gobliningenieure verwenden hohle Geierknochen, um Raketenwagen leichter zu machen. Die Knochen sind leicht und stabil genug für Lenkgestänge und kleine Stützen.",al={"warum knochen","verwendung von knochen durch goblins","pozziks knochenverwendung"}},{q="Woher stammen diese Knochen?",a="Salt Flats Scavengers und Salt Flats Vultures liefern die Knochen auf der Schimmernden Ebene in Tausend Nadeln, besonders nahe den riesigen Skelettresten, die über die Salzwüste verstreut liegen.",al={"wo hohle geierknochen finden","geierknochen fundort","wie geierknochen bekommen"}},{q="Wer ist Pozzik?",a="Pozzik ist ein Gobliningenieur und leitender Mechaniker an der Illusionenrennbahn. Er stimmt Raketenwagen ab und baut sie um, um gegen das Gnomenteam unter der Leitung von Fizzel Kupferbolz anzutreten.",al={"wer ist pozzik","pozzik illusionenrennbahn","wer nimmt die knochen"}}},fx={["2d4c7633"]={q="Was ist ein Hohler Geierknochen?",a="Dies sind leichte, robuste Knochen, die von den Aasvögeln stammen, die über Die schimmernde Ebene kreisen. Die Skelette der Vögel sind von Natur aus hohl, um den Flug zu unterstützen, was sie einzigartig für die Ingenieurskunst geeignet macht, bei der jedes eingesparte Pfund zählt. Auf der Illusionenrennbahn verwenden Goblin-Mechaniker sie, um widerstandsfähige Strukturteile und Lenkkomponenten für ihre Raketenautos zu fertigen.",al={"was ist ein hohler geierknochen","hohle geierknochen"}}},fp="19,195,29.384.0,38.158.0,31.189.0,14.164.0"}
P.entries["item:honorary-picks"] = {n="Ehrenhacken",s="In Eisenschmiede sind Ehrenhacken für Brock Steinsuchers Bergbaulehrlinge in Thelsamar bestimmt. Greifen bringen die zeremoniellen Werkzeuge nach Loch Modan, wo sie Schüler auszeichnen, die bereit sind, die dortigen Erzadern zu bearbeiten.",h="In Eisenschmiede sind Ehrenhacken für Brock Steinsuchers Bergbaulehrlinge in Thelsamar bestimmt.",kw={"brock steinsucher","gryth thurden","ehrenhacken","eisenschmiede","loch modan","bergbau hacken","thelsamar","thorgrum borrelson"},ang={["profession:Mining"]="Als Bergarbeiter kennt Ihr den Wert einer soliden Hacke. Ein Ehrenwerkzeug kennzeichnet den Eintritt eines Anfängers in den Beruf.",["race:Dwarf"]="Als Zwerg kennt Ihr die Verbundenheit und Handwerkskunst, die darin liegen, Lehrlingen in den Provinzen Werkzeuge zu überreichen, die in Eisenschmiede geschmiedet wurden."},sec={{t="Werkzeuge für die nächste Generation",b="Der Bergbau hält die großen Schmieden am Brennen und versorgt die Zwerge mit dem Eisen und Stein, die sie brauchen. In Thelsamar bringt Brock Steinsucher jungen Lehrlingen den Bergbau bei. Ehrenhacken aus Eisenschmiede zeichnen die Schüler aus, die bereit sind, die offenen Erzvorkommen in ganz Loch Modan zu bearbeiten."},{t="Die Greifenverbindungen erproben",b="Die Hacken reisen über das Greifennetzwerk der Allianz, das Eisenschmiede mit seinen entlegenen Siedlungen verbindet. An der Großen Schmiede in Eisenschmiede nimmt Gryth Thurden die Lieferung entgegen. Er schickt sie über die Berge zu Thorgrum Borrelson in Thelsamar."}},faq={{q="Wofür werden die Ehrenhacken verwendet?",a="Brock Steinsuchers Bergbauschüler in Loch Modan erhalten die Ehrenhacken. Die zeremoniellen Werkzeuge liegen bereit, damit die Lehrlinge damit Erzadern in der ganzen Region bearbeiten können.",al={"was sind ehrenhacken","verwendung von ehrenhacken","zweck der ehrenhacken"}},{q="Wer verschickt die Hacken, und wer erhält sie?",a="Die Hacken werden in Eisenschmiede vorbereitet und zu Gryth Thurden am Greifenhorst der Stadt gebracht. Von dort fliegen sie nach Osten nach Thelsamar, wo Bergbaulehrer Brock Steinsucher sie entgegennimmt.",al={"wer bekommt ehrenhacken","lieferung der ehrenhacken","empfänger der ehrenhacken"}},{q="Warum müssen die Hacken per Greif geliefert werden?",a="Greifen transportieren die Hacken schnell zwischen Eisenschmiede und Loch Modan entlang der bestehenden Flugrouten der Allianz. Auf diesem Weg lernen Reisende auch, diese Routen zu nutzen. Die Hacken könnten auch zu Fuß durch den Nordtorpass getragen werden.",al={"warum hacken fliegen","warum einen greif nehmen","ehrenhacken flug"}},{q="Sind die Ehrenhacken echte Waffen oder Werkzeuge, die Ihr anlegen könnt?",a="Nein. Der Kurier trägt die Hacken als Fracht für Brock Steinsuchers Bergbauschüler. Sie können es kaum erwarten, damit die Erzvorkommen von Loch Modan zu bearbeiten.",al={"ehrenhacken anlegen","sind ehrenhacken ein gegenstand","ehrenhacken benutzbar"}}},fx={a7b14bb4={q="Was sind die Ehrenhacken?",a="Die Ehrenhacken sind ein Bündel zeremonieller oder zur Erinnerung gedachter Bergbauwerkzeuge, die in Eisenschmiede gefertigt wurden. Sie sind als besonderes Geschenk für Bergbau-Novizen gedacht, die das Handwerk unter der Anleitung erfahrener Prospektoren in den Hügeln von Loch Modan erlernen.",al={"was sind ehrenhacken","ehrenhacken gegenstand","ehrenhacken lore"}},["0ecadd79"]={q="Woher stammen die Ehrenhacken und wer hat sie hergestellt?",a="Die Hacken werden in der Zwergenhauptstadt Eisenschmiede beschafft. Sie wurden von erfahrenen Bergschmieden in der Großen Schmiede der Stadt gefertigt und speziell für den Transport zu Ausbildern verpackt, die Lehrlinge jenseits der Grenzen von Dun Morogh ausbilden.",al={"wer hat ehrenhacken hergestellt","ursprung der ehrenhacken","woher stammen die hacken"}},["1a632b74"]={q="Warum will jemand die Ehrenhacken haben?",a="Bergbauausbilder Brock Steinsucher in Thelsamar bat um die Hacken, um sie seinen Novizen-Schülern zu überreichen. Als angehende Prospektoren, die in Loch Modan arbeiten, warten die Schüler sehnsüchtig auf diese Ehrenauszeichnungen und Werkzeuge, um mit der Bearbeitung der reichen Mineraladern der Region zu beginnen.",al={"warum ehrenhacken liefern","wer will die ehrenhacken","warum will brock die hacken"}}},fp="14,202,29.256.0,25.237.0,37.165.0,43.192.0,49.237.0,61.144.0"}
P.entries["item:horn-of-arra-chea"] = {n="Horn von Arra'chea",s="In ganz Mulgore folgen junge Jäger Cairne Bluthufs Ruf und spüren Arra'chea auf. Das Horn beweist, dass sie Beute finden und für die Shu'halo sorgen können.",h="In ganz Mulgore folgen junge Jäger Cairne Bluthufs Ruf und spüren Arra'chea auf.",kw={"arra'chea","cairne bluthuf","horn von arra'chea","kodo","mulgore","rites of the earthmother","donnerfels"},ang={["class:Hunter"]="Als Jäger prüft das Verfolgen von Arra'cheas Rundweg durch Mulgore Eure Fähigkeiten im Anpirschen und Überleben in der Wildnis, die Eure Berufung auszeichnen.",["race:Tauren"]="Als Tauren vollzieht Ihr einen Übergangsritus, wenn Ihr High Chieftain Cairne Arra'cheas Horn überreicht. Es beweist, dass Ihr bereit seid, Euer Volk auf Donnerfels zu versorgen und zu verteidigen."},sec={{t="Die Prüfung eines Häuptlings",b="Nach den Rites of the Earthmother darf ein junger Tauren seinen Platz auf Donnerfels einnehmen. Doch High Chieftain Cairne Bluthuf verlangt weiterhin von seinem Volk, seinen Wert zu beweisen. Für die Tauren verbindet die Jagd ihre Identität mit dauerhaftem Einklang mit dem Land. Deshalb schickt Cairne junge Jäger auf die Suche nach Arra'chea, einem gewaltigen, einzelgängerischen Kodobullen, der das Grasland unterhalb durchstreift. Das Horn des Bullen zu erbeuten, beweist, dass sie Beute über weite Entfernungen verfolgen können."},{t="Für den Stamm sorgen",b="Arra'cheas Horn hilft, Donnerfels zu versorgen, und zeigt zugleich die Stärke eines Jägers. Tauren verwerten jeden Teil eines erlegten Tiers. Die Trophäe verrät dem High Chieftain, wo Arra'chea gefallen ist. Dann können Sammeltrupps in die Ebenen hinabsteigen und die dicke Haut und das nahrhafte Fleisch des Kodos für die junge Hauptstadt bergen."}},faq={{q="Was ist das Horn von Arra'chea?",a="Arra'cheas Horn stammt von dem mächtigen, schwer aufzuspürenden Kodo, der Mulg ores Ebenen durchstreift. Jäger bringen es Cairne Bluthuf als Übergangsritus und Beweis ihrer Kunst des Fährtenlesens.",al={"horn von arrachea","arracheas horn","was ist dieses horn"}},{q="Wer ist Arra'chea?",a="Arra'chea ist ein berühmter Kodobulle, der das Grasland nordöstlich von Donnerfels auf einem Rundkurs durchstreift. Seine Stärke und seine weite Wanderroute machen ihn zu einer schwierigen Beute für Jäger, die dem Stamm ihren Wert beweisen wollen.",al={"arrachea","wer ist arrachea","arracheas geschichte"}},{q="Warum verlangt Cairne Bluthuf diese Trophäe?",a="Cairne Bluthuf verlangt die Trophäe, weil er von seinem Volk erwartet, seinen Wert immer wieder zu beweisen. Arra'chea aufzuspüren und zu erlegen, zeigt die Hingabe eines Jägers an die Traditionen der Erdenmutter und liefert der Gemeinschaft Vorräte.",al={"warum will cairne das horn","cairne arrachea","rites of the earthmother horn"}},{q="Was geschieht nach dem Erlegen mit dem Rest des Tiers?",a="Tauren verwerten jeden Teil des erlegten Tiers. Sobald das Horn die erfolgreiche Jagd bestätigt, schickt Cairne einen Sammeltrupp nach Mulgore, um Haut und Fleisch für Donnerfels zu holen.",al={"arracheas fleisch","jagdtradition der tauren","arracheas kadaver"}}},fx={["0ff92160"]={q="Woher stammt das Horn von Arra'chea und wer hat es hergestellt?",a="Das Horn ist kein handgefertigtes Artefakt, sondern eine natürliche Trophäe, die von Arra'chea genommen wurde, einem mächtigen Kodo, der durch die Ebenen von Mulgore unterhalb von Donnerfels streift. Um es zu beanspruchen, muss ein Jäger das große Biest im offenen Grasland aufspüren und es im ehrenvollen Kampf erlegen.",al={"ursprung horn von arra'chea","woher stammt das horn von arra'chea","wer hat das horn von arra'chea hergestellt"}}},fp="17,138,18.421.0,23.316.0,30.173.0,17.199.0,46.233.0,57.169.0"}
P.entries["item:horn-of-awakening"] = {n="Horn der Erweckung",s="Auf dem Weg ins Eschental trägt Kerlonian Schattenspiel das Horn der Erweckung. Es weckt ihn, wann immer ihn der Schlaf übermannt.",h="Auf dem Weg ins Eschental trägt Kerlonian Schattenspiel das Horn der Erweckung.",kw={"eschental","dunkelküste","druid of the claw","smaragdgrüner traum","horn der erweckung","kerlonian schattenspiel","maestras posten"},ang={["class:Druid"]="Als Druide wisst Ihr, dass Druids of the Claw Generationen schlafend in den Barrow Dens verbrachten und mit dem Smaragdgrünen Traum in Verbindung standen. Die Rückkehr ins Wachsein kann sie benommen und orientierungslos zurücklassen.",["race:NightElf"]="Als Nachtelf erkennt Ihr an Kerlonians schläfriger Reise, wie schwer es Euren Druiden fallen kann, nach ihrem langen Schlummer im Smaragdgrünen Traum zu erwachen."},sec={{t="Abhilfe für schläfrige Druiden",b="Kerlonian Schattenspiel ist erst vor Kurzem nach Jahrhunderten im Smaragdgrünen Traum erwacht. Doch das Wachsein fällt ihm noch immer schwer. Der Druid of the Claw reist nach Süden in Richtung Maestras Posten und vertraut das Horn Reisenden an, die bereit sind, ihn zu eskortieren.\n\nWenn Kerlonian auf dem Pfad durch die Wildnis vor Erschöpfung einschläft, schreckt ihn ein klarer Hornstoß auf. Er kommt wieder auf die Beine, bevor wilde Bestien oder Kultisten ihn erreichen können."}},faq={{q="Wo findet man das Horn der Erweckung?",a="Das Horn liegt in Kerlonian's Chest neben Kerlonian Schattenspiels Lager im Süden der Dunkelküste, nahe der Grenze zum Eschental.",al={"fundort des horns","wo ist das horn der erweckung","kerlonians chest"}},{q="Warum braucht Kerlonian das Horn, um wach zu bleiben?",a="Nach langen Zeitaltern des Schlafs im Smaragdgrünen Traum fällt Kerlonian das Wachsein in der sterblichen Welt schwer. Auf seinen Reisen übermannt ihn oft unvermittelt ein tiefer Schlummer.",al={"warum schläft kerlonian","warum schläft er ein","schlummer im smaragdgrünen traum"}},{q="Wohin will Kerlonian gelangen?",a="Kerlonian versucht, Maestras Posten im nördlichen Eschental zu erreichen, um Liladris Moonriver zu treffen.",al={"kerlonians reiseziel","wohin geht er","eskorte zu maestras posten"}}},fx={["061d2ee3"]={q="Was ist das Horn der Erweckung?",a="Das Horn der Erweckung ist ein persönliches Instrument des Nachtelf-Druiden Kerlonian Schattenspiel. Da Kerlonian kürzlich aus dem Smaragdgrünen Traum erwacht ist, leidet er auf seinen Reisen unter Anfällen von tiefem, ungelegenem Schlaf. Er bewahrt dieses Horn speziell in seiner Truhe auf, damit ein Begleiter es erklingen lassen kann, um ihn zu wecken, wann immer er am Wegesrand zusammenbricht.",al={"horn der erweckung","was ist dieses horn","kerlonian horn"}}},fp="17,119,26.391.0,37.127.0,47.148.0,32.93.0"}
P.entries["item:horn-of-echeyakee"] = {n="Horn von Echeyakee",s="Am Wegekreuz gibt Sergra Dunkeldorn Jägern das Horn von Echeyakee, damit sie es inmitten der uralten Kodoüberreste nordöstlich der Siedlung ertönen lassen. Sein Ruf lockt das legendäre weiße Raubtier des Brachlands hervor.",h="Am Wegekreuz gibt Sergra Dunkeldorn Jägern das Horn von Echeyakee, damit sie es inmitten der uralten...",kw={"brachland","das wegekreuz","echeyakee","horn","kodoknochen","sergra darkthorn","whitemist"},ang={["class:Hunter"]="Als Jäger stellt Ihr Euch Echeyakee in einem legendären Übergangsritus. Eure Sinne werden gegen ein Raubtier geprüft, das im ganzen Brachland für seine nahezu vollkommene Heimlichkeit bekannt ist.",["race:Tauren"]="Als Taure wisst Ihr, dass Echeyakees Jagd spirituelle Bedeutung trägt. Euer Volk sieht sein schnelles, schmerzloses Töten sowohl als Gnade als auch als harte Notwendigkeit des Todes."},sec={{t="Der Ruf nach Whitemist",b="Jäger erhalten das Horn, wenn sie sich bei der Jagd bewähren müssen. Sein Ruf beschwört Echeyakee, dessen Name auf Taur-ahe „Whitemist“ bedeutet. Die Jäger der Tauren verehren den König der Savannenkatzen als Gnade und Tod. Sein schneller Schlag lässt seiner Beute keine Zeit für Angst oder Leid. Das Horn gehört an seinen Bau, zwischen die riesigen Kodoknochen hinter den Hügeln nordöstlich des Wegekreuzes."}},faq={{q="Was bewirkt das Horn von Echeyakee?",a="Das Horn ruft Echeyakee, die schwer aufzuspürende weiße Savannenkatze. Lasst es nahe den riesigen Kodoknochen nordöstlich des Wegekreuzes ertönen, und die Bestie erscheint, damit ein Jäger sich ihr stellen kann.",al={"horn von echeyakee benutzen","wozu dient das horn von echeyakee"}},{q="Woher stammt das Horn?",a="Am Wegekreuz im Brachland gibt Sergra Dunkeldorn, eine Orcjägerin, das Horn jenen, die ihr Feingefühl und ihre Fertigkeit im Spurenlesen beweisen wollen.",al={"wer gibt das horn","horn von echeyakee herkunft"}},{q="Was bedeutet der Name Echeyakee?",a="Auf Taur-ahe, der Sprache der Tauren, bedeutet Echeyakee „Whitemist“. Der Name ehrt sein blasses Fell und seinen lautlosen Gang durch trockenes Gras.",al={"echeyakee bedeutung","whitemist bedeutung"}},{q="Wo blast Ihr das Horn?",a="Lasst das Horn zwischen den riesigen Kodorippen und Skelettresten hinter den Hügeln nordöstlich des Wegekreuzes ertönen, wo der weiße Löwe umherstreift.",al={"wo das horn benutzen","echeyakee fundort"}}},fx={eb6b337d={q="Was ist das Horn von Echeyakee?",a="Das Horn von Echeyakee ist ein rituelles Jagdinstrument, das Jägern am Wegekreuz von Sergra Dunkeldorn überreicht wird. Wenn man es inmitten der riesigen Kodo-Knochen nordöstlich der Siedlung bläst, lockt sein Ruf Echeyakee selbst hervor – den weißen Löwen, der bei den Tauren als König der Savannenkatzen verehrt wird.",al={"horn von echeyakee","was ist dieses horn","was ist das horn von echeyakee"}},["5884ea69"]={q="Warum gibt Sergra Dunkeldorn Euch das Horn von Echeyakee?",a="Sergra Dunkeldorn stellt das Horn als wichtiges Werkzeug bereit, um Eure Fähigkeiten zu testen. Echeyakee schleicht wie ein weißer Nebel unsichtbar durch die Ebenen, was es fast unmöglich macht, ihn nur mit den Augen zu verfolgen. Der Ruf des Horns fordert das große Raubtier heraus und lockt es zum Kampf, damit Ihr sein Fell beanspruchen und Euer Jagdgeschick beweisen könnt.",al={"warum brauche ich das horn von echeyakee","warum echeyakee horn","zweck des horns von echeyakee"}}},fp="17,207,21.375.0,35.165.0,30.144.0,34.134.0,27.135.0"}
P.entries["item:huge-gnoll-claw"] = {n="Gewaltige Gnollklaue",s="Im Südwesten von Elwynn beweist Hoggers gewaltige Klaue seinen Tod. Die Behörden von Sturmwind in Goldhain verlangen sie, bevor sie das Kopfgeld auszahlen.",h="Im Südwesten von Elwynn beweist Hoggers gewaltige Klaue seinen Tod.",kw={"kopfgeld","wald von elwynn","goldhain","hogger","gewaltige gnollklaue","marschall dughan","riverpaw"},ang={["class:Hunter"]="Als Jäger beweist Ihr mit der Klaue eines Raubtiers, das regelmäßig bewaffnete Trupps überwältigte, Euer Geschick beim Aufspüren und Jagen von Wildtieren.",["faction:Alliance"]="Indem Ihr Hoggers Klaue für die Allianz erbeutet, befreit Ihr das Herzland des Königreichs von seinem berüchtigtsten Waldschrecken. Sie beweist Marschall Dughan und der bedrängten Garnison in Goldhain Eure Tapferkeit."},sec={{t="Beweis des Kopfgeldjägers",b="Seit Monaten terrorisiert Hogger die südlichen Wälder des Waldrands. Patrouillen konnten ihn nicht aufhalten, und die örtliche Garnison kann den Unhold weder einkreisen noch überwältigen. Die Armee von Sturmwind ist über ganz Elwynn verstreut und überlastet, weshalb sie ein offenes Kopfgeld auf ihn ausgesetzt hat. Marschall Dughan in Goldhain verlangt einen eindeutigen Beweis, bevor er zahlt. Hoggers übergroße Klaue lässt keinen Zweifel daran, dass der berüchtigte Plünderer gefallen ist."}},faq={{q="Wozu dient die Gewaltige Gnollklaue?",a="Bringt Hoggers Klaue als Beweis für seinen Tod zu Marschall Dughan in Goldhain und kassiert das ausgesetzte Kopfgeld.",al={"was tun mit hoggers klaue","gewaltige gnollklaue verwendung","wer will die klaue"}},{q="Woher stammt diese Klaue?",a="Hogger trägt die Klaue bei sich. Der Elitegnoll durchstreift die Gegend nahe den Lagern der Riverpaw entlang der südwestlichen Grenzen des Waldrands im Wald von Elwynn.",al={"wer lässt die klaue fallen","wie gewaltige gnollklaue bekommen","wo gewaltige gnollklaue finden"}},{q="Warum will Marschall Dughan eine Klaue statt des Kopfes?",a="Hogger ist für einen Gnoll ungewöhnlich groß, und seine gewaltigen Klauen sind unverwechselbar und sofort zu erkennen. Eine davon beweist der Armee von Sturmwind, dass der berüchtigte Plünderer erschlagen wurde.",al={"warum klaue als proof of demise","warum nicht hoggers kopf","dughan kopfgeld beweis"}},{q="Kann ich eine weitere Klaue bekommen, wenn ich sie verliere?",a="Ja. Wenn Ihr die Klaue verliert, bevor Ihr sie zu Marschall Dughan bringt, könnt Ihr Hogger erneut im südwestlichen Wald von Elwynn jagen und Ersatz erbeuten.",al={"gewaltige gnollklaue verloren","klaue erneut bekommen","hoggers klaue respawn"}}},fx={d9093290={q="Was ist die Gewaltige Gnollklaue?",a="Die Gewaltige Gnollklaue ist der abgetrennte physische Beweis für den Untergang von Hogger, einem berüchtigten und riesigen Gnoll, der den südwestlichen Wald von Elwynn terrorisiert. Da Hogger jeden Versuch der örtlichen Behörden, ihn gefangen zu nehmen, durchkreuzt hat, dient diese markante Kralle für Marschall Dughan als unbestreitbarer Beweis dafür, dass die Bestie endlich erlegt wurde.",al={"was ist die gewaltige gnollklaue","infos zur gewaltigen gnollklaue","hogger klaue"}},["7983cdb8"]={q="Warum will Marschall Dughan die Gewaltige Gnollklaue?",a="Marschall Dughan und die Armee von Sturmwind setzten ein Kopfgeld auf Hogger aus, nachdem die riesige Bestie ihre Patrouillen überwältigt und entkommen war. Dughan benötigt die gewaltige Klaue des Gnolls als Beweis für seinen Tod, bevor er das Kopfgeld in Goldhain auszahlt und so endlich ein Ende der Kopfschmerzen findet, die Hogger seinen Männern bereitet hat.",al={"warum will dughan die klaue","wer will die gewaltige gnollklaue","warum die gewaltige gnollklaue haben wollen"}}},fp="15,140,21.406.0,37.104.0,31.138.0,56.179.0,36.142.0"}
P.entries["item:humbert-s-sword"] = {n="Humberts Schwert",s="In Dun Garok liegt Humberts Schwert bei den Zwergen, die es aus seinem Lager mitnahmen. Todeswache Humbert verließ seinen Posten, um Feuerholz zu sammeln, während er die Festung auskundschaftete.",h="In Dun Garok liegt Humberts Schwert bei den Zwergen, die es aus seinem Lager mitnahmen.",kw={"darthalia","todeswache humbert","dun garok","hillsbrad","humberts schwert","tarrens mühle"},ang={["faction:Horde"]="Die Rückholung des Schwertes unterstützt die umfassenderen Unternehmungen der Horde gegen die Zwergenenklave von Dun Garok. Zu diesen Unternehmungen gehört auch das Sammeln von Zwergenblut und militärischen Abzeichen.",["race:Undead"]="Hochexekutorin Darthalia sorgt bei den Truppen der Verlassenen in Hillsbrad für strenge Disziplin. Wachposten wie Humbert versuchen verzweifelt, ihre Fehler zu verbergen, wenn sie unachtsam werden."},sec={{t="Die Unachtsamkeit eines Spähers",b="Todeswache Humbert verließ eines Morgens seinen verborgenen Posten nahe Dun Garok, um Feuerholz zum Wasserkochen zu sammeln. Hochexekutorin Darthalia hatte ihn entsandt, um die Zwerge dort zu beobachten. Während seiner Abwesenheit entdeckte eine Zwergenpatrouille sein Lager und plünderte seine Ausrüstung, darunter seine persönliche Klinge. Nun braucht Humbert Agenten der Horde, die die Festung durchsuchen und sie zurückholen."},{t="Die Beute der Zwerge",b="Die Verteidiger von Dun Garok brachten Humberts Habseligkeiten hinter die Barrikaden der Festung. Scharfschützen, Gebirgsjäger und Priester verteilen Vorräte innerhalb der Garnison. Um den Dieb zu finden, müssen auch die Verteidiger in den Schützengräben und Redouten durchsucht werden."}},faq={{q="Wem gehört dieses Schwert?",a="Das Schwert gehört Todeswache Humbert, einem Wachposten der Verlassenen, der in Tarrens Mühle stationiert ist und Dun Garok auskundschaften soll.",al={"wem gehört dieses schwert","humbert besitzer","wer ist humbert"}},{q="Wie kamen die Zwerge an Humberts Schwert?",a="Humbert verließ eines Morgens sein Späherlager unmittelbar vor Dun Garok, um Feuerholz zu sammeln. Während seiner Abwesenheit plünderte eine Zwergenpatrouille das Lager und nahm seine Ausrüstung mit.",al={"wie kamen die zwerge daran","warum haben die zwerge das schwert","wie wurde das schwert gestohlen"}},{q="Warum will Humbert sein Schwert so verzweifelt zurückhaben?",a="Hochexekutorin Darthalia befahl Humbert, Dun Garok zu überwachen, und dafür braucht er seine Waffe. Bei so vielen Zwergen in der Garnison kann er den Dieb nicht allein finden.",al={"warum will humbert das schwert","was passiert wenn humbert das schwert verliert","warum ist es humbert wichtig"}},{q="Wo ist das Schwert zu finden?",a="Das Schwert befindet sich bei den Zwergentruppen in Dun Garok im Südosten des Vorgebirges des Hügellands. Es lässt sich von den Gebirgsjägern, Scharfschützen oder Priestern zurückholen, die überall im Stützpunkt stationiert sind.",al={"wo wird das schwert fallen gelassen","fundort des schwertes","wie findet man humberts schwert"}}},fp="15,163,25.357.0,17.242.0,20.116.0,40.156.0,50.171.0,29.181.0"}
P.entries["item:hyacinth-mushroom"] = {n="Hyazinthpilz",s="Im Laubschattental wachsen Hyazinthpilze zwischen Teldrassils Bäumen und Wurzeln. Nachtelfische Kräuterkundige nutzen sie als Heilmittel, während Grell und Grellkin sie als Nahrung sammeln.",h="Im Laubschattental wachsen Hyazinthpilze zwischen Teldrassils Bäumen und Wurzeln.",kw={"gegengift","dirania silberschein","grell","grellkin","hyazinthpilz","iverron","laubschattental","teldrassil"},ang={["profession:Herbalism"]="Ihr braucht keine förmliche Ausbildung, um diese Pilze im Laubschattental zu sammeln. Als angehende Kräuterkundige könnt Ihr lernen, wie sie helfen, den Giften des Waldes entgegenzuwirken.",["race:NightElf"]="Als junger Nachtelf in der Ausbildung im Laubschattental könnt Ihr Wildpflanzen wie Hyazinthpilze sammeln, um Euer Volk zu versorgen."},sec={{t="Flora des Laubschattentals",b="Zwischen den Bäumen und Wurzeln von Aldrassil im Laubschattental helfen Hyazinthpilze Waldheilern, junge nachtelfische Schildwachen und Rekruten zu behandeln, denen giftige Kreaturen zugesetzt haben. Zu den Gefahren, denen sie begegnen, gehören die Spinnen der Schattenweberhöhle. Heiler verwenden die Pilze für lindernde Tränke und Gegengifte. Auch verderbte Grell horten sie."}},faq={{q="Wofür werden Hyazinthpilze verwendet?",a="Dirania Silberschein stellt aus Hyazinthpilzen ein Gegengift für Iverron her, einen jungen Nachtelfen, der beim Erkunden der Schattenweberhöhle von giftigen Spinnen vergiftet wurde.",al={"hyazinthpilz verwendung","was bewirkt er","iverron heilung"}},{q="Wo wachsen Hyazinthpilze?",a="Im Laubschattental auf Teldrassil wachsen Hyazinthpilze am Boden nahe großer Baumstämme und Wurzeln sowie neben Felsbrocken.",al={"pilz fundort","wo hyazinthpilz finden","laubschattental pilze"}},{q="Warum tragen die Grell Hyazinthpilze bei sich?",a="Grell und Grellkin sammeln im südlichen Laubschattental Hyazinthpilze als Nahrung und horten sie in ihren Lagern.",al={"grell lassen pilze fallen","warum haben grell sie","grellkin pilze"}},{q="Sind Hyazinthpilze selbst giftig?",a="Nein. Die örtlichen Heiler verwenden Hyazinthpilze gefahrlos für heilende Umschläge und Gegengifte.",al={"ist hyazinthpilz giftig","giftiger pilz"}}},fx={["77b7a797"]={q="Was ist ein Hyazinthpilz?",a="Ein Hyazinthpilz ist ein einheimischer Pilz, der überall in den schattigen Zweigen von Teldrassil zu finden ist, insbesondere an den Wurzeln von Bäumen und auf moosigen Steinen im Laubschattental. Diese Waldpilze sind für ihren medizinischen Wert bekannt und besitzen natürliche Eigenschaften, die bei richtiger Zubereitung zusammen mit anderen lokalen Pflanzen Gifte neutralisieren können.",al={"was ist ein hyazinthpilz","infos zum hyazinthpilz","über hyazinthpilze"}}},fp="17,161,19.329.0,37.158.0,33.121.0,42.102.0,44.84.0"}
P.entries["item:hypercapacitor-gizmo"] = {n="Hyperkondensator-Dingsda",s="In Tausend Nadeln liegt das Hyperkondensator-Dingsda zwischen den Trümmern einer Goblinkarawane. Ein eingesperrter Panther trug es um den Hals, und selbst sein Besitzer weiß nicht, was es bewirkt.",h="In Tausend Nadeln liegt das Hyperkondensator-Dingsda zwischen den Trümmern einer Goblinkarawane.",kw={"zentauren","wütender panther","dingsda","hyperkondensator","tausend nadeln","weißgipfelposten","wizlo lagerputzer"},ang={["faction:Horde"]="Reisende, die dem Weißgipfelposten beistehen, helfen dabei, aggressive Zentauren zu vertreiben und verlorene Kuriositäten aus zerstörten Karawanen auf dem Schluchtboden zu bergen.",["profession:Engineering"]="Das Dingsda trägt die Handschrift goblinischer Ingenieurskunst: ein kompliziertes Gerät mit einem großartigen Namen, voller Begeisterung gebaut, bevor jemand entschied, was es tun sollte."},sec={{t="Seltsames Relikt einer Karawane",b="Marodierende Zentauren überfielen eine Goblinkarawane, die durch Tausend Nadeln zog, und plünderten fast alles. Wizlo Lagerputzer, der einzige Überlebende, kroch zum Weißgipfelposten, um sich in Sicherheit zu bringen. Sein bestes Dingsda ließ er zurück, befestigt am Hals eines wilden, wütenden Panthers, der in einem Transportkäfig eingesperrt war. Die Zentauren fürchteten die Bestie und ließen den Käfig inmitten der brennenden Trümmer unberührt."},{t="Tüfteln im Dunkeln",b="Wizlo nennt das Hyperkondensator-Dingsda stolz sein bestes Dingsda, obwohl er zugibt, keine Ahnung zu haben, was es bewirkt. In dem Gerät verstrickt sich Ehrgeiz mit unberechenbaren Bauteilen. Wizlo kann nur weiter daran tüfteln, ohne zu wissen, welchen praktischen Nutzen es haben könnte."}},faq={{q="Was ist das Hyperkondensator-Dingsda?",a="Das Hyperkondensator-Dingsda gehört Wizlo Lagerputzer, einem Gobliningenieur. Selbst Wizlo weiß nicht, was es bewirkt, also will er es untersuchen, bis er seinen Zweck entdeckt.",al={"was ist das dingsda","hyperkondensator","was bewirkt das dingsda"}},{q="Wie landete das Gerät am Hals eines Panthers?",a="Zentauren überfielen und plünderten Wizlos Karawane im Norden von Tausend Nadeln. Im Chaos wurde das Gerät am Hals eines wütenden Panthers in einem Transportkäfig befestigt. Die abergläubischen Zentauren fürchteten die Bestie und ließen sie in Ruhe.",al={"warum hat der panther das dingsda","wie bekam der panther es"}},{q="Wer will das Hyperkondensator-Dingsda zurück?",a="Wizlo Lagerputzer will das Hyperkondensator-Dingsda zurück. Der einzige Überlebende der Karawane hat am Weißgipfelposten Zuflucht gefunden, einem Taurenlager im Nordwesten von Tausend Nadeln.",al={"wer braucht das dingsda","wizlos dingsda"}},{q="Warum stahlen die Zentauren es nicht?",a="Die Zentauren plünderten die Karawane, fürchteten aber den wilden Panther in seinem Käfig. Sie ließen die Bestie und ihr Metallhalsband unberührt inmitten der Trümmer zurück.",al={"warum nahmen die zentauren es nicht","zentauren und panther"}}},fx={["240fe489"]={q="Woher stammt das Hyperkondensator-Dingsda und wer hat es hergestellt?",a="Das Gerät war im Besitz des Goblin-Tüftlers Wizlo Lagerputzer, der mit einer Karawane durch Tausend Nadeln reiste, bevor Zentauren sie überfielen. Während Wizlo es als sein wertvollstes Gerät bezeichnet, bleibt sein genauer Erfinder ein Rätsel – selbst Wizlo gibt zu, dass er nicht genau versteht, was die kuriose Maschine eigentlich tut.",al={"wer hat das hyperkondensator-dingsda hergestellt","ursprung des hyperkondensator-dingsdas","woher hat wizlo das hyperkondensator-dingsda"}}},fp="20,178,25.378.0,21.227.0,33.172.0,50.235.0,40.175.0,32.147.0"}
P.entries["item:ignition-key"] = {n="Zündschlüssel",s="Im Schlickermoor wartet Wizzlecrank auf den Zündschlüssel, um einen gestohlenen Schredder freizubekommen.",h="Im Schlickermoor wartet Wizzlecrank auf den Zündschlüssel, um einen gestohlenen Schredder freizubekommen.",kw={"zündschlüssel","schredder","das schlickermoor","stotterspritter","supervisor lugwizzle","venture company","wizzlecrank"},ang={["profession:Engineering"]="Der Zündschlüssel entriegelt einen Schredder mit fortschrittlicher Steuerung. Seine Geschwindigkeitsregelung und die präzisen Armbewegungen übertreffen typische Goblinkonstruktionen."},sec={{t="Ein fehlendes Teil der Spionage",b="Wizzlecrank, der Agent von Stotterspritter aus Ratschet, wartet in einem Schredder der Venture Company im Schlickermoor. Er sollte die Maschine stehlen, doch ihre Bewegungssäule war verriegelt. Also täuschte er unter den Augen der Vorarbeiter mechanische Probleme vor und hoffte, jemand würde den Zündschlüssel holen.\n\nSupervisor Lugwizzle bewahrt den Schlüssel oben auf dem zentralen Bohrturm auf. Er entriegelt die Bewegungssäule des Schredders und gibt Wizzlecrank die Kontrolle über dessen Arm, Geschwindigkeit und Drehung."}},faq={{q="Wo ist der Zündschlüssel zu finden?",a="Supervisor Lugwizzle bewahrt den Zündschlüssel im Kontrollraum oben auf dem Bohrturm im Schlickermoor auf, wo er die Bohrarbeiten beaufsichtigt.",al={"zündschlüssel fundort","wer lässt den zündschlüssel fallen","wie den zündschlüssel bekommen"}},{q="Warum braucht Wizzlecrank genau diesen Schlüssel?",a="Der fortschrittliche Schredder der Venture Company hat eine verriegelte Bewegungssäule. Ohne den Schlüssel kann Wizzlecrank dessen Drehung, Geschwindigkeit, Stabilität oder Arm nicht gut genug steuern, um damit davonzufahren.",al={"warum den schlüssel brauchen","was bewirkt der schlüssel","zweck des shredderschlüssels"}},{q="Wer will den Schredder stehlen lassen?",a="Stotterspritter, ein Gobliningenieur in Ratschet, hat den Diebstahl eingefädelt, um an die überlegenen Konstruktionspläne der Venture Company zu gelangen.",al={"wer hat wizzlecrank geschickt","warum den schredder stehlen","ratschet schredder"}},{q="Was geschieht, sobald der Schlüssel übergeben wurde?",a="Mit dem Schlüssel entriegelt Wizzlecrank die Bewegungssäule und startet den Motor des Schredders. Dann muss er durch die feindseligen Arbeiter im Schlickermoor rasen, um in Richtung Ratschet zu entkommen.",al={"nach abgabe des schlüssels","the escape","wie geht es weiter"}}},fx={["762c90b7"]={q="Was ist der Zündschlüssel?",a="Der Zündschlüssel ist ein funktionsfähiger Schlüssel, der verwendet wird, um die Bewegungssäule eines fortgeschrittenen Schredders der Venture Company im Schlickermoor zu entriegeln. Ohne ihn bleiben die Steuerungen der schweren Holzfällermaschine gesperrt, sodass der Pilot weder steuern noch fahren kann.",al={"was ist der zündschlüssel","verwendung des zündschlüssels","schredderschlüssel"}},["8801ec8f"]={q="Woher stammt der Zündschlüssel?",a="Der Schlüssel gehört zu den Bohr- und Holzfällarbeiten der Venture Company im Schlickermoor. Er befindet sich im Besitz von Supervisor Lugwizzle, der den Standort vom Kontrollraum auf dem zentralen Bohrturm aus überwacht.",al={"wer hat den zündschlüssel hergestellt","ursprung des zündschlüssels","woher stammt der schlüssel"}}},fp="12,80,28.444.0,36.136.0,44.180.0,30.124.0,39.169.1"}
P.entries["item:ilkrud-magthrull-s-tome"] = {n="Ilkrud Magskluves Foliant",s="Am Schrein des Sengenden Feuers wendet sich Delgren der Läuterer Ilkrud Magskluves Folianten zu. Seine Seiten verbinden den Hexenmeister mit den Kultisten am Turm von Althalaxx.",h="Am Schrein des Sengenden Feuers wendet sich Delgren der Läuterer Ilkrud Magskluves Folianten zu.",kw={"eschental","delgren der läuterer","schrein des sengenden feuers","ilkrud magthrull","maestras posten","foliant","turm von althalaxx","hexenmeister"},ang={["class:Paladin"]="Als Paladin helft Ihr Brother Delgren, einem Mitstreiter des Heiligen Lichts, der sich Schatten und Verderbnis in Eschentals Wildnis entgegenstellt.",["class:Warlock"]="Als Hexenmeister könnt Ihr Magthrulls Zauberfolianten studieren, der dunkle Bindungen und die Unterwerfung von Leerwandlern und Sukkubi am verderbten Schrein des Sengenden Feuers dokumentiert."},sec={{t="Ein Zauberfoliant der Verderbnis",b="Am Schrein des Sengenden Feuers im südwestlichen Eschental hält Ilkrud Magthrull ein Gebiet besetzt, das durch dämonischen Einfluss vergiftet ist. Der furchterregende Hexenmeister der Orcs ist von beschworenen Dienern umgeben. Sein persönlicher Foliant enthält Aufzeichnungen über üble Rituale und zwielichtige Botschaften. Delgren der Läuterer, ein Paladin der Argentumdämmerung, weiß schon lange, dass Magthrull dort ist. Das Buch muss dringend geborgen werden, weil es den Hexenmeister mit den dunklen Kultisten verbindet, die sich am Turm von Althalaxx sammeln."},{t="Dem Kult auf der Spur",b="Nachdem Magthrull getötet wurde, wird sein Foliant zu Delgren an Maestras Posten gebracht. Delgren studiert die Schriften des Hexenmeisters, um das Netzwerk zu verstehen, das dämonische Aktivitäten über die Grenzen von Dunkelküste und Eschental hinweg koordiniert. Der Text liefert entscheidende Informationen über die finsteren Verschwörer, die die sich im nördlichen Kalimdor ausbreitende Verderbnis lenken."}},faq={{q="Wem gehört dieser Foliant?",a="Ilkrud Magthrull gehört der Foliant. Der mächtige Hexenmeister der Orcs hat sich inmitten der dämonischen Ruinen am Schrein des Sengenden Feuers im südwestlichen Eschental niedergelassen.",al={"wer ist ilkrud magthrull","wer schrieb den folianten","ilkrud magthrull"}},{q="Wo ist der Foliant zu finden?",a="Der Foliant wird von Ilkrud Magthrull am Schrein des Sengenden Feuers geborgen, südlich des Schreins von Aessina in Eschental.",al={"fundort des folianten","wie den folianten erhalten","wo ilkrud finden"}},{q="Warum will Delgren der Läuterer das Buch?",a="Delgren will Magthrulls Schriften studieren und die Verbindungen zwischen den örtlichen Dämonenanbetern und den Kultisten am Turm von Althalaxx aufdecken.",al={"warum delgren den folianten will","was steht im folianten","delgrens zweck für das buch"}},{q="Was geschieht, nachdem der Foliant geborgen wurde?",a="An Maestras Posten untersucht Delgren den Text, um Magthrulls dämonische Botschaften zu entschlüsseln und herauszufinden, wie sich das Netzwerk des Kults zerschlagen lässt.",al={"folianten abgeben","was macht delgren mit dem buch"}}},fx={["5352c240"]={q="Woher stammt Ilkrud Magskluves Foliant und wer hat ihn hergestellt?",a="Das Buch enthält die persönlichen Schriften und dunklen Forschungen von Ilkrud Magskluves, einem mächtigen Orc-Hexenmeister, der inmitten der dämonischen Verderbnis des Schrein des Sengenden Feuers im südwestlichen Eschental lebt. Der Band wurde vom Hexenmeister selbst verfasst und kompiliert seine dunklen Zauber und Notizen, die er bis zu seinem Untergang bei sich trug.",al={"wer hat ilkrud magskluves foliant geschrieben","ursprung von ilkrud magskluves foliant","woher stammt der foliant"}}},fp="23,159,24.434.0,19.342.1,19.142.0,24.109.0,44.139.0,41.138.0"}
P.entries["item:incantations-from-the-nether"] = {n="Zauberformeln aus dem Nether",s="Unter Orgrimmar besitzt die Searing Blade die Zauberformeln aus dem Nether, ein Zauberbuch dämonischer Magie. Sylvanas Windläufer und Varimathras suchen dessen Teufelswissen für die Verlassenen.",h="Unter Orgrimmar besitzt die Searing Blade die Zauberformeln aus dem Nether, ein Zauberbuch dämonischer Magie.",kw={"zauberformeln aus dem nether","der flammenschlund","searing blade","shadow council","schattenzauber","sylvanas","the power to destroy","varimathras"},ang={["class:Warlock"]="Folianten, die unmittelbar aus dem Nether stammen, bergen mächtige Teufelsmagie, die ehrgeizige Anwender der dunklen Künste begehren.",["race:Undead"]="Die Bergung des Buches hilft dem inneren Kreis der Dunklen Fürstin in Unterstadt. Das dunkle Wissen wird für den Krieg gegen die Geißel benötigt."},sec={{t="Gaben der Legion",b="Die Searing Blade wirkt in den feurigen Tunneln des Flammenschlunds unter Orgrimmars roten Steinstraßen. Die unterirdische Sekte ist mit dem Shadow Council verbunden. Ihre Kultisten hüten die Zauberformeln aus dem Nether, ein Zauberbuch dämonischer Riten, das ihnen Agenten der Brennenden Legion überlassen haben. Sie nutzen seine Geheimnisse, um Verrat in der orkischen Hauptstadt zu planen. Die Kunde von dem Folianten hat die königlichen Gemächer von Unterstadt erreicht."},{t="Ehrgeiz der Verlassenen",b="Varimathras schickt treue Abenteurer der Horde tief in den Flammenschlund, um die Zauberformeln aus dem Nether und ihren Schwesterband Schattenzauber zu bergen. Sylvanas Windläufer und ihr Schreckenslord-Leutnant glauben, dass solche Teufelsrelikte an Kultisten mit geringerer Weitsicht verschwendet sind. Die Dunkle Fürstin will die im Nether geschmiedete Macht des Buches gegen den Lichkönig einsetzen und Vergeltung an der Geißel üben."}},faq={{q="Wo ist das Buch Zauberformeln aus dem Nether zu finden?",a="Kultisten und Hexenmeister der Searing Blade tragen die Zauberformeln aus dem Nether im Flammenschlund bei sich, dem vulkanischen Höhlennetz unter Orgrimmar.",al={"wo zauberformeln aus dem nether erhalten","wer lässt zauberformeln aus dem nether fallen","zauberformeln aus dem nether fundort"}},{q="Wer will dieses Buch und warum?",a="Fürstin Sylvanas Windläufer und der Schreckenslord Varimathras suchen das Buch. Sie halten die Kultisten der Searing Blade für kleingeistig und wenig weitsichtig und wollen mit seiner dämonischen Magie den Lichkönig bekämpfen.",al={"wer braucht zauberformeln aus dem nether","warum will sylvanas dieses buch","varimathras buchquest"}},{q="Was ist die Searing Blade?",a="Die Searing Blade ist eine verschlossene unterirdische Sekte aus Hexenmeistern und Kultisten unter Orgrimmar, die mit dem Shadow Council verbündet ist. Ihre Mitglieder dienen der Brennenden Legion und arbeiten im Verborgenen daran, Thralls neue Horde zu untergraben.",al={"geschichte der searing blade","wer ist die searing blade"}},{q="Welches andere Buch gehört zu diesem?",a="Varimathras benötigt zwei Bände: Zauberformeln aus dem Nether und Schattenzauber. Beide müssen den Kultisten im Flammenschlund abgenommen werden, um seinen Auftrag zu erfüllen.",al={"anderes buch für varimathras","power to destroy bücher"}}},fx={e0d58fa2={q="Was sind die Zauberformeln aus dem Nether?",a="Zauberformeln aus dem Nether ist ein dunkles Grimoire, das Teufelsmagie enthält, die von der Brennende Legion verliehen wurde. Es gelangte in den Besitz der Searing Blade, einem verborgenen Kult des Shadow Council, der tief in den feurigen Klüften unter Orgrimmar operiert. Zusammen mit dem Schwesterband, Schattenzauber, enthält das Buch mächtige dämonische Rituale, die Kultisten-Hexenmeister studieren, um die Kräfte des Twisting Nether zu nutzen.",al={"was sind die zauberformeln aus dem nether","buch zauberformeln aus dem nether","was für ein buch sind die zauberformeln aus dem nether"}}},fp="28,178,19.393.0,17.383.1,53.136.0,28.188.0,26.215.0,40.164.0"}
P.entries["item:incendia-agave"] = {n="Brandpulveragave",s="Unterhalb des Düsterwolkengipfels wächst die Brandpulveragave im Kochenden See. Ein geübter Schamane kann sie verzaubern, um das heilige Feuer des Lebens zu entfachen.",h="Unterhalb des Düsterwolkengipfels wächst die Brandpulveragave im Kochenden See.",kw={"arikara","kochender see","düsterwolkengipfel","brandpulveragave","magatha grimmtotem","sacred fire","tausend nadeln"},ang={["class:Shaman"]="Als Schamane könnt Ihr mit urtümlicher Elementarkunst die Wasserpflanze in ein Pulver verwandeln, das mächtig genug ist, heilige Ritualflammen zu entfachen.",["profession:Herbalism"]="Als Kräuterkundiger hilft Euch Euer Gespür beim Aufspüren der stacheligen Büschel der Brandpulveragave am trüben Grund des Kochenden Sees."},sec={{t="Ein seltenes Wüstenkraut",b="In Tausend Nadeln wächst die Brandpulveragave im und um den Kochenden See unterhalb des Düsterwolkengipfels. Umherstreifende Dampfelementare bewachen die seltene Pflanze und erschweren ihre Ernte. Obwohl sie unter Wasser wächst, enthält die Pflanze natürliche Elemente, die sich für Flammenrituale eignen."},{t="Hochheiliges Feuer",b="Die Älteste Magatha Grimmtotem auf der Anhöhe der Ältesten in Donnerfels kann geerntete Bündel der Brandpulveragave in ein mystisches Pulver verwandeln. Ritualisten der Tauren entzünden mit diesem Pulver die zeremonielle Kohlenpfanne und beschwören die rachsüchtige Windnatter Arikara."}},faq={{q="Wo wächst die Brandpulveragave?",a="Die Brandpulveragave wächst im und um den Kochenden See unterhalb des Düsterwolkengipfels im Norden von Tausend Nadeln. Ein Großteil wächst unter Wasser am Seegrund.",al={"wo agave finden","brandpulveragave fundort","wo ist agave"}},{q="Wofür wird die Brandpulveragave verwendet?",a="Zehn Bündel der Brandpulveragave werden gesammelt und zu Ritualpulver verarbeitet. In Donnerfels verzaubert Magatha Grimmtotem es, um das heilige Feuer des Lebens zu entzünden und Arikara zu beschwören.",al={"brandpulveragave verwendung","warum agave sammeln","was bewirkt agave"}},{q="Wer kann die Brandpulveragave verzaubern?",a="Auf der Anhöhe der Ältesten in Donnerfels besitzt Magatha Grimmtotem das rituelle Wissen, um Brandpulveragave zu verzaubern. Sie ist eine einflussreiche Schamanin.",al={"wer verzaubert agave","magatha agave","wer verwandelt agave in pulver"}},{q="Welche Gefahren umgeben die Brandpulveragave?",a="Feindselige Dampfelementare durchstreifen das Wasser und die Ufer des Kochenden Sees. Sie sind außergewöhnlich widerstandsfähig gegen Frost- und Feuerzauber.",al={"agave gefahren","was bewacht agave","kochender see gefahren"}}},fx={d4005c78={q="Was ist die Brandpulveragave?",a="Brandpulveragave ist ein außergewöhnlich seltenes, stacheliges Kraut, das nur rund um und in den dampfenden Gewässern des Boiling Pool in Tausend Nadeln gedeiht. Obwohl sie in der Tiefe am Seeufer wächst, besitzt sie latente feurige Eigenschaften, was sie zu einem wesentlichen Bestandteil für Rituale macht, die elementare Kraft erfordern, sobald sie von einem erfahrenen Schamanen richtig veredelt wurde.",al={"was ist eine brandpulveragave","brandpulveragave pflanze","was für eine pflanze ist die brandpulveragave"}}},fp="14,136,18.272.0,15.238.1,31.165.0,32.172.0,35.131.0,41.131.0"}
P.entries["item:incendia-powder"] = {n="Brandpulver",s="Auf dem Düsterwolkengipfel lockt Brandpulver einen heiligen Geist hervor. Magatha Grimmtotem verzaubert es auf der Anhöhe der Ältesten in Donnerfels für den Einsatz in Tausend Nadeln.",h="Auf dem Düsterwolkengipfel lockt Brandpulver einen heiligen Geist hervor.",kw={"arikara","düsterwolkengipfel","brandpulver","motega feuermähne","sacred fire des lebens","tausend nadeln","weißgipfelposten"},ang={["class:Shaman"]="Als Schamane seht Ihr, wie elementare Flammen und spiritueller Schutz zusammenwirken, um schlummernde Ahnenwesen zu wecken.",["race:Tauren"]="Als Tauren wisst Ihr, dass rituelle Pulver Grabfeuer entzünden können, wo heilige Tradition auf die Verteidigung der Stammesführung trifft."},sec={{t="Ein Funke der Beschwörung",b="Brandpulver trägt schamanische Magie zum Sacred Fire auf dem Düsterwolkengipfel. Auf der Anhöhe der Ältesten in Donnerfels vertraut Magatha Grimmtotem es Reisenden an. Streut es über das geweihte Kohlenbecken, wo die Toten zur Ruhe gebettet werden, und es ruft Arikara hervor, eine rachsüchtige geflügelte Schlange."},{t="Beunruhigende Vorzeichen",b="Magatha Grimmtotem prägte die Riten hinter dem Brandpulver. Sie glaubte, Veränderungen in den Bräuchen der Tauren hätten uralte Geister aufgeschreckt, die nun Jagd auf Oberhäuptling Cairne Bluthuf machten. Also verzauberte sie das Pulver, um die Erscheinung hervorzulocken und zu vernichten. Die wilde Schlange erscheint, doch es bleiben Fragen darüber, warum Arikara aufgeschreckt wurde."}},faq={{q="Wofür wird Brandpulver verwendet?",a="Streut Brandpulver auf dem Düsterwolkengipfel in Tausend Nadeln in das Sacred Fire des Lebens. Die Flamme ruft Arikara hervor, die rachsüchtige Geisterschlange.",al={"brandpulver zweck","warum brauche ich brandpulver","was bewirkt brandpulver"}},{q="Wer hat das Pulver verzaubert?",a="Magatha Grimmtotem verzauberte gesammelte Brandpulveragaven auf der Anhöhe der Ältesten in Donnerfels zu veredeltem Pulver. Motega Feuermähne vom Weißgipfelposten hatte Nachricht über Arikara geschickt.",al={"wer hat brandpulver hergestellt","wer hat brandpulver verzaubert"}},{q="Wo muss das Pulver verwendet werden?",a="Streut das Pulver in die Feuergrube des Sacred Fire auf einer einsamen Grabfelsnadel auf dem Düsterwolkengipfel, hoch über den Salzschluchten von Tausend Nadeln.",al={"brandpulver ort","wohin brandpulver werfen","wo brandpulver verwenden"}},{q="Warum musste Arikara beschworen werden?",a="Magatha Grimmtotem fürchtet, dass Veränderungen in den Überlieferungen der Tauren Arikara erzürnt haben und die Schlange womöglich Cairne Bluthuf nachstellt. Sie bittet darum, Arikara zu beschwören und zu töten, bevor Cairne Schaden nimmt.",al={"warum arikara beschwören","warum arikara bekämpfen"}}},fx={["53c7ed7b"]={q="Was ist Brandpulver?",a="Brandpulver ist ein raffiniertes, gereinigtes Reagenz, das in Ritualmagie getränkt ist. Wenn es auf das Sacred Fire des Lebens auf dem Düsterwolkengipfel in Tausend Nadeln gestreut wird, wirkt sein verwobener Zauber wie ein Signalfeuer, das Arikara, den rachsüchtigen Windschlangengeist, hervorlockt.",al={"was ist brandpulver","lore über brandpulver","was ist das pulver"}}},fp="15,164,20.287.0,15.324.1,33.156.0,43.164.0,38.153.0,36.192.0"}
P.entries["item:insane-scribbles"] = {n="Irrsinniges Gekritzel",s="An der Dunkelküste tragen Kultisten Irrsinniges Gekritzel bei sich, herausgerissen aus dem Twilight Tome, ein Fragment dunkler Literatur. Die tanzende Schrift und die verzerrten Muster verstören den Geist. Uralte Beschützer des Waldes untersuchen die Seiten, um die Absichten des Twilight's Hammer zu ergründen.",h="An der Dunkelküste tragen Kultisten Irrsinniges Gekritzel bei sich, herausgerissen aus dem Twilight Tome, ein...",kw={"dunkelküste","irrsinniges gekritzel","wahnsinn","alte götter","onu","twilight tome","twilight's hammer"},ang={["class:Priest"]="Als Priester erkennt Ihr die sich windende Schrift womöglich als gefährlichen Angriff des Wahnsinns, der sich gegen die Klarheit des Lichts richtet.",["race:NightElf"]="Als Nachtelf wisst Ihr, dass Relikte des Twilight's Hammer den uralten Frieden und die heiligen Lande der Dunkelküste bedrohen."},sec={{t="Ein Manuskript des Wahnsinns",b="Der Twilight Tome kann den Verstand eines Sterblichen gefährden. Seine Schrift windet sich über das Pergament, und anmutige Schnörkel verzerren sich vor den Augen des Lesers zu grotesken Bildern. Schon ein einzelnes herausgerissenes Blatt, Irrsinniges Gekritzel genannt, lässt seinen Träger benommen und orientierungslos zurück. Das Geschriebene ergibt kaum Sinn, doch das Pergament summt von urtümlicher, zutiefst uralter Magie, verbunden mit dunklen Mächten, die unter Azeroth begraben liegen."},{t="Hinweise für die Uralten",b="Onu, der Uralte, der über den Hain der Uralten wacht, untersucht das Gekritzel auf Hinweise darauf, was die Dunkelküste verdirbt. Onu erkennt die chaotische Energie, die dem Pergament anhaftet, als Werk der Alten Götter. Daher versuchen die Verteidiger von Kalimdor, das Gekritzel zusammenzusetzen und zu ergründen, warum sich der Twilight's Hammer an den nebelverhangenen Küsten versammelt hat."}},faq={{q="Was geschieht, wenn Ihr versucht, dieses Gekritzel zu lesen?",a="Der Text lässt sich nur schwer übersetzen. Wenn Ihr das Pergament betrachtet, verschwimmen seine Buchstaben, und die Muster ringsum verzerren sich zu entsetzlichen Formen. Bald stellen sich Schwindel und geistige Erschöpfung ein, während Ihr versucht, sie zu entziffern.",al={"irrsinniges gekritzel lesen","was steht im text","lässt sich das gekritzel lesen"}},{q="Woraus wurde dieses Gekritzel herausgerissen?",a="Das Gekritzel wurde aus dem Twilight Tome herausgerissen, einem finsteren Zauberbuch im Besitz von Kultisten des Twilight's Hammer, die an der Dunkelküste wirken.",al={"woher stammt das gekritzel","herkunft des twilight tome"}},{q="Wer kann das Gekritzel verstehen oder untersuchen?",a="Onu, der Ancient of Lore, untersucht das geborgene Pergament. Mit seinem Wissen aus Jahrhunderten spürt Onu die uralte, urtümliche Magie, die die Tinte bindet, und versucht, die Absichten des Kults in der Region zu ergründen.",al={"wer will das gekritzel","onu gekritzel"}},{q="Welche Art von Macht strahlt das Pergament aus?",a="Das Pergament pulsiert vor chaotischer, urtümlicher Magie, die mit den Alten Göttern verbunden ist, den dunklen Gottheiten, die der Twilight's Hammer verehrt.",al={"welche magie steckt im gekritzel","art der magie"}}},fx={b40c7e7e={q="Warum will Onu das Irrsinnige Gekritzel?",a="Der uralte Onu spürt den chaotischen Einfluss der Alten Götter, der in das Pergament eingewoben ist. Er möchte diese geborgenen Schriften studieren, in der Hoffnung zu entschlüsseln, was der verschwiegene Schattenhammer-Kult innerhalb der Wälder und an den Küsten der Dunkelküste plant.",al={"warum will onu das irrsinnige gekritzel","wer will das gekritzel","warum das gekritzel zu onu bringen"}},["12486380"]={q="Was ist das Irrsinniges Gekritzel?",a="Es ist eine einzelne, wahnsinnig machende Seite, die aus dem dunklen Text, bekannt als Twilight Tome, herausgerissen wurde. Die Schrift darauf schwimmt, tanzt und verdreht sich vor Euren Augen in groteske Formen und strahlt eine chaotische und urtümliche magische Aura aus, die Eure Sinne zu überwältigen droht, wenn Ihr zu lange darauf starrt.",al={"was ist das irrsinniges gekritzel","lore über das irrsinniges gekritzel","was ist dieses pergament"}}},fp="16,246,22.397.0,22.356.1,48.213.0,37.122.0,42.200.0,47.123.0"}
P.entries["item:inscribed-bark"] = {n="Gravierte Rinde",s="In Teldrassil trägt Gravierte Rinde den Bericht des Oracle Tree zu Erzdruide Fandral Hirschhaupt. Er berichtet vom Zustand der Äste und den Bedrohungen, die den Wäldern noch immer zusetzen.",h="In Teldrassil trägt Gravierte Rinde den Bericht des Oracle Tree zu Erzdruide Fandral Hirschhaupt.",kw={"zirkel des cenarius","darnassus","fandral hirschhaupt","gravierte rinde","oracle tree","teldrassil"},ang={["class:Druid"]="Als Druide erkennt Ihr in Gravierter Rinde eine dringende Nachricht eines uralten Verbündeten. Sie spricht vom empfindlichen Gleichgewicht und den Leiden, die dem jungen Weltenbaum zusetzen.",["race:NightElf"]="Als Kaldorei wisst Ihr, dass Botschaften auf uralter Rinde die Natur mit ihren Hütern verbinden. Sie verknüpfen wilde Haine mit den Marmorterrassen von Darnassus."},sec={{t="Eine Botschaft des Orakels",b="Der Oracle Tree schickt Gravierte Rinde an den Zirkel des Cenarius in Darnassus. Nachdem Ihr die Harpyien aus ihren Nestern vertrieben habt, übergibt Euch der uralte Baum seine Botschaft. Er fürchtet, dass die verderbten Pfade durch Teldrassil für gewöhnliche Boten zu gefährlich sind. Der Bericht unterrichtet Erzdruide Fandral Hirschhaupt über jüngste Siege und die tiefere Verderbnis, die die Wälder noch immer im Griff hält."}},faq={{q="Was ist Gravierte Rinde?",a="Gravierte Rinde trägt den Bericht des Oracle Tree zu Erzdruide Fandral Hirschhaupt in Darnassus. Er berichtet vom Zustand der Äste und den Gefahren, die ihnen drohen.",al={"was ist gravierte rinde","oracle tree rinde","gravierte rinde zweck"}},{q="Wer schickt diese Botschaft und warum?",a="Der Oracle Tree gibt Euch Gravierte Rinde, nachdem Ihr Harpyien aus ihren Nestern vertrieben habt. Da er gewöhnliche Boten nur ungern über die gefährdeten Waldpfade schickt, vertraut er den Bericht einem bewährten Reisenden an.",al={"wer hat gravierte rinde geschrieben","wer gibt gravierte rinde","oracle tree bote"}},{q="Wie reagiert Erzdruide Fandral Hirschhaupt auf die Botschaft?",a="Fandral erkennt an, dass die Vertreibung der Harpyien eine Atempause verschafft hat, doch tiefere Probleme bestehen laut ihm fort. Der Bericht nährt erneut seine Sorge, ob seine Arbeit an Teldrassil den Nachtelfen ihre verlorene Unsterblichkeit zurückgeben kann.",al={"fandral reaktion rinde","was sagt fandral über rinde"}}},fp="14,166,25.352.0,23.152.0,31.202.0,58.213.1"}
P.entries["item:intact-raptor-horn"] = {n="Intaktes Raptorhorn",s="Im ganzen Brachland suchen Jäger nach ganzen Raptorhörnern. Mebok Mizzyrix aus Ratschet hofft, daraus Stärkungsmittel herzustellen, und vertraut auf Gerüchte, dass diese Raptoren klug seien.",h="Im ganzen Brachland suchen Jäger nach ganzen Raptorhörnern.",kw={"intaktes horn","ishamuhale","mebok mizzyrix","raptorhorn","ratschet","smart drinks","sunscale scytheclaw","takk the leaper"},ang={["class:Hunter"]="Als Jäger müsst Ihr einige der wildesten Raubtiere der Savannen sauber erlegen, um ein ganzes Horn als Trophäe zu erbeuten.",["profession:Cooking"]="Als Koch hört Ihr vielleicht, dass Mebok die Hörner für Weinauszüge pulverisieren will. Pragmatische Überlebenskünstler verwenden Raptorenteile lieber zur Herstellung von Werkzeugen als für schmackhaftes Essen."},sec={{t="Eine fragwürdige Zutat",b="Jäger schätzen Raptorenhäute, Krallen und Trophäen, doch ganze Hörner sind bei der Jagd schwerer zu erbeuten. Mebok Mizzyrix ist ein exzentrischer Goblinalchemist in Ratschet. Er glaubt, dass die Raptoren des Brachlands gerissener sind als ihre Artgenossen andernorts, und vermutet ihren Verstand in ihren Hörnern. Deshalb hofft er, ganze Hörner zu Stärkungsmitteln zu zermahlen und diese vermeintliche Genialität in Getränken zum Verkauf abzufüllen."},{t="Den Rudeln auf der Spur",b="Ein zum Brauen geeignetes Horn muss von einem besonders bösartigen Raubtier stammen, nicht von irgendeinem jungen Raptor. Sunscale Scytheclaws durchstreifen die südlichen Ebenen und die nördlichen Grenzgebiete nahe Eschental. Takk the Leaper und der schwer aufzuspürende Ishamuhale zählen zu den berüchtigten Schrecken der Savanne. Ihre kräftigen Hörner können den Kampf bei der Jagd unbeschadet überstehen."}},faq={{q="Wer will diese intakten Raptorhörner?",a="Mebok Mizzyrix, ein Goblinhändler und angehender Brauer in Ratschet, sucht intakte Hörner. Er glaubt, dass sie der Schlüssel zu seinem nächsten Plan sind, Geld zu verdienen.",al={"wer braucht raptorhörner","hornkäufer","wer kauft raptorhörner"}},{q="Warum müssen die Hörner intakt sein?",a="Mebok plant, ganze Hörner zu einem feinen Pulver zu zermahlen, das die Leute schlucken sollen. Jäger werfen angeschlagene oder zerbrochene Hörner weg oder betrachten sie als verbraucht, weil ihnen die volle Wirkkraft fehlt, die er für seine Rezepte nutzen will.",al={"warum intakt","zerbrochene hörner"}},{q="Welche Raptoren tragen sie?",a="Ausgewachsene Sunscale Scytheclaws tragen sie im äußersten Norden und Süden des Brachlands. Berüchtigte Raptoren, darunter Ishamuhale und Takk the Leaper, tragen sie ebenfalls.",al={"wo gibt es hörner als beute","welche raptoren","wer hinterlässt ein intaktes horn"}},{q="Machen Raptorhörner Euch tatsächlich klüger?",a="Die Raptoren des Brachlands zeigen im Rudel ungewöhnliche Gerissenheit und Koordination. Niemand hat bewiesen, dass ihre Intelligenz in ihren Hörnern sitzt oder durch ein Getränk auf jemanden übergehen kann.",al={"wirken smart drinks","sind raptoren klug","raptorintelligenz"}}},fx={["41f89fc5"]={q="Was ist ein Intaktes Raptorhorn?",a="Ein Intaktes Raptorhorn ist ein unbeschädigtes Schädelhorn, das von den räuberischen Raptoren geerntet wurde, die das Brachland durchstreifen. Diese Hörner werden von unternehmungslustigen Einheimischen geschätzt, die glauben, dass ihr makelloser Zustand das natürliche Wesen und die List der Bestien bewahrt.",al={"was ist ein intaktes raptorhorn","was ist ein raptorhorn"}},b3ef4089={q="Woher stammen intakte Raptorhörner?",a="Diese Hörner wachsen auf natürliche Weise auf den Köpfen der Raptoren im Brachland, insbesondere bei Sonnenwuchssensenklauen sowie berüchtigten Bestien wie Ishamuhale und Takk der Springer. Sie sind biologische Trophäen, die direkt von erlegten Raptoren in den gesamten Savannen gewonnen werden.",al={"woher kommen raptorhörner","wer lässt intakte raptorhörner fallen"}}},fp="18,157,25.376.0,19.322.0,36.152.0,35.210.0,25.168.0,42.162.0"}
P.entries["item:intrepid-strongbox-key"] = {n="Geldkassettenschlüssel der INTREPID",s="Auf dem Wrack der Intrepid trägt Kapitän Halyndor noch immer den Schlüssel zu seiner Geldkassette. Der verrostete Eisenschlüssel hielt einst einen geheimnisvollen Gegenstand an Bord des dem Untergang geweihten Allianzschiffs vor dem Sumpfland unter Verschluss.",h="Auf dem Wrack der Intrepid trägt Kapitän Halyndor noch immer den Schlüssel zu seiner Geldkassette.",kw={"kapitän halyndor","verfluchte besatzung","glorin stahlbraue","intrepid","schiffswrack","geldkassette","third fleet","sumpfland"},ang={["class:Priest"]="Als Priester könnt Ihr das verfluchte Artefakt zur Reinigung zu Glorin Stahlbraue im Hafen von Menethil bringen. Dadurch werden die Seelen der Besatzung von ihrer Qual befreit.",["faction:Alliance"]="Als Mitglied der Allianz wisst Ihr, dass der Schlüssel einem Kommandanten der Third Fleet gehörte, die vor der Küste des Hafens von Menethil unterging. Ihr Verlust bleibt eine offene Wunde für die Überlebenden des Hafens."},sec={{t="Das Geheimnis des Kapitäns",b="Die Intrepid sank mit der Third Fleet vor dem Sumpfland. Ihre Besatzung wurde zu rastlosen, verfluchten Geistern. Kapitän Halyndor bewachte einen geheimnisvollen Gegenstand in der schweren Geldkassette des Schiffes. Nun streift sein Geist mit dem verrosteten Schlüssel, der sie öffnet, über das überflutete Deck."},{t="Den Bann brechen",b="Kapitän Halyndors Schlüssel öffnet die Geldkassette der Intrepid. Darin liegt ein verfluchtes Relikt, das die Besatzung an ihre Qual bindet. Glorin Stahlbraue, ein Zwergenpriester im Hafen von Menethil, kann das Relikt reinigen."}},faq={{q="Wer trägt den Geldkassettenschlüssel der INTREPID?",a="Kapitän Halyndor trägt den Schlüssel, während er auf dem Oberdeck des nördlichen Schiffswracks vor der Nordwestküste des Sumpflands auf und ab geht.",al={"wer hat den schlüssel","intrepid schlüssel beute","halyndor schlüssel"}},{q="Was öffnet der Geldkassettenschlüssel der INTREPID?",a="Der Schlüssel öffnet die verschlossene Geldkassette der Intrepid, die im zerbrochenen Rumpf unter dem Deck des Kapitäns unter Wasser liegt.",al={"was öffnet er","intrepid geldkassette fundort","wo ist die truhe"}},{q="Warum blieb die Geldkassette verschlossen?",a="Kapitän Halyndor schloss einen verfluchten Gegenstand in der Truhe ein, um ihn verborgen und sicher zu verwahren. Nachdem die Flotte gesunken war, band das fortwirkende Böse des Gegenstands die Besatzung an den Untod.",al={"was war in der truhe","warum war sie verschlossen"}},{q="Wer kann den verfluchten Gegenstand in der Truhe reinigen?",a="Glorin Stahlbraue, ein Zwergenpriester im Hafen von Menethil, kann das verfluchte Artefakt reinigen, sobald die Truhe aufgeschlossen ist.",al={"wer reinigt es","glorin stahlbraue truhe"}}},fx={b4277111={q="Was ist der Geldkassettenschlüssel der INTREPID?",a="Es ist ein verrosteter Schiffsschlüssel, der von Kapitän Halyndor an Bord des Schiffswracks der INTREPID aufbewahrt wird. Selbst nach seinem Tod bewacht der verfluchte Kapitän den Schlüssel eifersüchtig, denn er ist das einzige Mittel, um die verstärkte Geldkassette des Schiffes zu öffnen, die im zertrümmerten Rumpf verborgen ist.",al={"geldkassettenschlüssel der intrepid","was ist der schlüssel","intrepid schlüssel"}},["90ec2e74"]={q="Warum wird der Geldkassettenschlüssel der INTREPID benötigt?",a="Der Schlüssel wird benötigt, um die Geldkassette der INTREPID zu öffnen und das darin eingeschlossene dunkle Relikt zu bergen. Erster Maat Fitzsimmons glaubt, dass dieses verstaute Artefakt den schrecklichen Fluch heraufbeschworen hat, der Halyndor und seine Mannschaft an das Wrack bindet, und das Öffnen der Truhe ist der erste Schritt, um ihn aufzuheben.",al={"warum brauche ich den schlüssel","warum den schlüssel holen","zweck des intrepid schlüssels"}}},fp="22,188,18.260.0,17.194.1,39.122.0,42.110.0,34.154.0,49.114.0"}
P.entries["item:invisibility-liquor"] = {n="Unsichtbarkeitsschnaps",s="Maybell Maclure entzieht sich mit Unsichtbarkeitsschnaps den Blicken ihrer Familie, um Tommy Joe Steinfeld zu treffen. Ihre Familien bleiben durch eine bittere Fehde verbunden.",h="Maybell Maclure entzieht sich mit Unsichtbarkeitsschnaps den Blicken ihrer Familie, um Tommy Joe Steinfeld zu...",kw={"kristalltang","wald von elwynn","unsichtbarkeitsschnaps","maybell maclure","steinfeld-fehde","the escape","tommy joe steinfeld"},ang={["class:Mage"]="Als Magier wisst Ihr, dass Arkanisten der Kirin Tor Jahre damit verbringen, Illusionen und Unsichtbarkeitszauber zu meistern. Die Bewohner von Elwynn stellen mit vergorenen Spirituosen und durchweichtem Tang eine grobe Nachahmung her.",["race:Human"]="Als Mensch wisst Ihr, dass die ländliche Fehde zwischen den Steinfelds und den Maclures bittere Ausmaße annimmt."},sec={{t="Ein Trank für unglücklich Verliebte",b="Tommy Joe Steinfeld sucht ein ungestörtes Treffen mit Maybell Maclure. Doch die Fehde ihrer Familien hält die beiden Häuser auseinander, und ihre Verwandten wachen aufmerksam. Gewöhnliche Heimlichkeit reicht nicht aus. Unsichtbarkeitsschnaps lässt den Trinker ungesehen über das umstrittene Ackerland gelangen."},{t="Unorthodoxe Alchemie in Elwynn",b="Kristalltangwedel aus Gewässern, in denen Murlocs leben, kommen in das Gebräu. Maybell Maclure trinkt den Schnaps und wird unsichtbar. Dann schleicht sie für ein geheimes Treffen in den Wald."}},faq={{q="Was bewirkt Unsichtbarkeitsschnaps?",a="Unsichtbarkeitsschnaps macht den Trinker für kurze Zeit unsichtbar. Ein alkoholisches Getränk trägt seine Magie.",al={"schnapswirkung","unsichtbarkeitsgebräu","was bewirkt er"}},{q="Wer verwendet den Unsichtbarkeitsschnaps?",a="Maybell Maclure erhält Unsichtbarkeitsschnaps, damit sie sich den Blicken ihrer Familie entziehen und Tommy Joe Steinfeld treffen kann, trotz der Fehde ihrer Familien.",al={"wer trinkt ihn","maybell maclure schnaps"}},{q="Wie wird der Schnaps hergestellt?",a="Kristalltangwedel, die aus Flussbetten und von Seeufern im Wald von Elwynn gesammelt werden, kommen in das Gebräu. Murlocs horten die Pflanzen.",al={"schnapszutaten","kristalltangschnaps"}},{q="Können Spieler den Unsichtbarkeitsschnaps selbst trinken?",a="Nein. Unsichtbarkeitsschnaps ist für Maybell Maclure bestimmt, damit sie sich von ihrer Familie fortschleichen kann.",al={"kann man ihn trinken","unsichtbarkeitsschnaps trinken"}}},fx={["19edabb3"]={q="Was ist Unsichtbarkeitsschnaps?",a="Unsichtbarkeitsschnaps ist ein starker alchemistischer Trank, der im Wald von Elwynn gebraut wird. Obwohl er offiziell als alkoholisches Getränk gilt, besitzt er magische Eigenschaften, die von Kristallseetangwedeln stammen, und verleiht demjenigen, der ihn trinkt, vorübergehend völlige Unsichtbarkeit vor sterblichen Augen.",al={"was ist unsichtbarkeitsschnaps","unsichtbarkeitsschnaps hintergrund","welche art von getränk ist unsichtbarkeitsschnaps"}},f0e7bc08={q="Warum will jemand Unsichtbarkeitsschnaps?",a="Der Schnaps wird gesucht, um eine verbotene Romanze zu ermöglichen. Maybell Maclure und Tommy Joe Steinfeld befinden sich auf entgegengesetzten Seiten der erbitterten Familienfehde in Elwynn, und der Trank erlaubt es Maybell, ungesehen an ihrer wachsamen Verwandtschaft vorbeizuschlüpfen, um ihren Geliebten zu besuchen.",al={"warum wird unsichtbarkeitsschnaps benötigt","wer will unsichtbarkeitsschnaps","warum wollen sie den schnaps"}}},fp="19,148,32.249.0,25.180.1,33.110.0,33.143.0,23.120.0,53.91.0"}
P.entries["item:iron-pike"] = {n="Eisenspitze",s="In Seenhain brauchen die Bauarbeiter Eisenspitzen, um die Everstill Bridge zu reparieren. Gnolle des Rotkammgebirges raubten die Lieferung aus Sturmwind, sodass der Stadt Eisen fehlt.",h="In Seenhain brauchen die Bauarbeiter Eisenspitzen, um die Everstill Bridge zu reparieren.",kw={"everstill bridge","großknecht oslow","eisenspitze","eisenniete","seenhain","gnolle des rotkammgebirges","rotkammgebirge"},ang={["faction:Alliance"]="Wenn Ihr als Reisender der Allianz die gestohlenen Vorräte zurückholt, helft Ihr, Seenhains Übergänge zu sichern und Sturmwinds Ostgrenze gegen Angriffe der Schwarzfelsorcs zu stärken.",["profession:Blacksmithing"]="Als Schmied erkennt Ihr, wie sehr der Krieg die örtlichen Schmiede belastete: Sie mussten ihr gesamtes Roheisen für Waffen verwenden."},sec={{t="Gestohlene Karawanenfracht",b="Nach Angriffen der Schwarzfelsorcs verbrauchte Seenhain seine Metallreserven für Rüstungen, Klingen und Munition. Daraufhin baten die Bauarbeiter Sturmwind um mehr Eisen, doch Gnolle des Rotkammgebirges überfielen die Karawane auf der Straße. Sie brachten Kisten mit Eisenspitzen und Nieten nach Norden in die Hügel, und die Arbeiten an der Everstill Bridge kamen zum Erliegen."},{t="Wiederaufbau der Brücke",b="Großknecht Oslow überwacht den Wiederaufbau der Brücke und braucht die gestohlenen Eisenwaren. Ohne die schweren Eisenspitzen zur Verstärkung ihres Stein- und Holzgerüsts bleibt Seenhain durch die beschädigte Brücke teilweise von der nördlichen Straße abgeschnitten. Zudem bleibt die Stadt dadurch weiteren Überfällen ausgesetzt."}},faq={{q="Warum tragen die Gnolle Eisenspitzen für Bauarbeiten bei sich?",a="Gnolle des Rotkammgebirges überfielen eine Versorgungskarawane auf dem Weg von Sturmwind nach Seenhain. Mit Kisten voller gestohlener Baumaterialien, darunter Eisenspitzen und Nieten, verstreuten sie sich in den Hügeln des Rotkammgebirges.",al={"warum haben gnolle eisenspitzen","woher haben gnolle eisenspitzen"}},{q="Wer braucht diese Eisenspitzen in Seenhain?",a="Großknecht Oslow braucht die Eisenspitzen, um die Everstill Bridge über den Immerruhsee wiederaufzubauen. Die jüngsten Orcangriffe zwangen Seenhain, seine Eisenreserven zu Waffen und Rüstungen einzuschmelzen, sodass kein Eisen übrig blieb.",al={"wer braucht eisenspitzen","großknecht oslow eisenspitzen"}},{q="Wo lassen sich diese Eisenspitzen zurückholen?",a="Gnolle des Rotkammgebirges bewahren die Eisenspitzen in ihren Lagern in den Hügeln und auf den Bergrücken nördlich von Seenhain auf.",al={"wo eisenspitzen finden","eisenspitze fundort"}},{q="Warum konnte Seenhain nicht einfach eigene Eisenspitzen schmieden?",a="Seenhain verbrauchte seine örtlichen Eisenvorräte im Kampf gegen die Schwarzfelsorcs und schmolz sie zu Schwertern, Kugeln und Schutzausrüstung ein. Die Stadt musste Sturmwind um neues Eisen für Bauarbeiten bitten.",al={"warum bestellte seenhain eisen","seenhain eisenmangel"}}},fx={c6b2b586={q="Was ist eine Eisenspitze?",a="Eine Eisenspitze ist ein schwerer Eisenbaupfahl, der dazu gedacht ist, Mauerwerk und Steinbauten zu verstärken. Großknecht Oslow und seine Mannschaft benötigen diese stabilen Baustützen, um die zerstörte Everstill Bridge in Seenhain zu reparieren und zu stabilisieren.",al={"was ist eine eisenspitze","was sind eisenspitzen","eisenspitze rotkammgebirge"}}},fp="9,162,20.307.0,19.266.0,47.197.0,40.193.0,40.89.0,55.180.0"}
P.entries["item:iron-pommel"] = {n="Eisenschwertknauf",s="Im Eschental bleibt der Eisenschwertknauf das letzte fehlende Teil von Dartols Stab. Der längst verstorbene Zauberer Dartol erschuf den Stab, und die Nachtelfen von Astranaar suchen ihn, um die Angriffe der Furbolgs zu verlangsamen. Druiden im Dor'danil-Grabhügel bewachten den Knauf, bis ihr Heiligtum überrannt und sie niedergemetzelt wurden.",h="Im Eschental bleibt der Eisenschwertknauf das letzte fehlende Teil von Dartols Stab.",kw={"eschental","dartols stab","dor'danil","eisenschwertknauf","oso's chest","raene's cleansing","shael'dryn"},ang={["class:Druid"]="Als Druide könnt Ihr der Druiden von Dor'Danil gedenken. Ihre heilige Aufgabe endete in einem Gemetzel am Waldrand.",["faction:Alliance"]="Als Mitglied der Allianz bringt Ihr Dartols Stab seiner Vollendung näher, indem Ihr den Knauf bergt. Der Stab ist eine unverzichtbare Hilfe bei der Verteidigung des Eschentals gegen die schleichende Verderbnis."},sec={{t="Die Bürde eines erschlagenen Zirkels",b="Dartols Stab wurde zerlegt und über das Eschental verstreut, um seine mystische Macht zu schützen. Nachtelfendruiden nahe der Straße nach Süden ins Brachland übernahmen die Obhut über den Eisenschwertknauf. Ihr Zirkel wurde im Dor'danil-Grabhügel massakriert, und ihre Zuflucht verstummte zwischen den Ruinen. Bei der Zerstörung verschwand der Knauf. Blubbernde Schlicke ziehen nun durch die entweihte Lichtung."},{t="Aus dem Morast geborgen",b="Der Eisenschwertknauf liegt in einer stabilen Truhe in der verseuchten Senke südlich des Splitterholzpostens. Wer die verderbten Schleime durchsucht, findet die Truhe unversehrt in der säurehaltigen Masse eines Schlicks. Der Knauf ist das letzte Teil, das zur Wiederherstellung von Dartols Stab benötigt wird."}},faq={{q="Wofür wird der Eisenschwertknauf verwendet?",a="Der Eisenschwertknauf ist das letzte Teil, das benötigt wird, um Dartols Stab wieder zusammenzusetzen. Bringt ihn zu Shael'dryn am Mondbrunnen, und sie kann das uralte Artefakt wiederherstellen, um die Angriffe der Furbolgs auf die Nachtelfen des Eschentals zu verlangsamen.",al={"eisenschwertknauf verwendung","wofür wird eisenschwertknauf benötigt","was bewirkt eisenschwertknauf"}},{q="Wer hatte den Knauf ursprünglich?",a="Nachtelfendruiden nahe der Straße ins Brachland hatten die Obhut über den Knauf. Ihr Zirkel wurde niedergemetzelt, bevor der Stab wieder zusammengesetzt werden konnte, und ihre Zuflucht liegt in Trümmern.",al={"wer bewachte den knauf","wer hatte eisenschwertknauf","dor'danil druiden"}},{q="Wo ist der Knauf zu finden?",a="Der Knauf ist in einer Truhe eingeschlossen, die einer der verderbten Schleime in der verseuchten Senke östlich der Hauptstraße in sich trägt. Die Senke liegt südlich des Splitterholzpostens und nördlich der Grenze zum Brachland.",al={"eisenschwertknauf fundort","wo ist eisenschwertknauf","wo gibt es eisenschwertknauf"}},{q="Zu wem soll ich den Knauf bringen?",a="Bringt den Knauf zu Shael'dryn, einer Dryade, die den Mondbrunnen östlich des Irissees hütet. Sie kennt das Ritual, das zur Wiederherstellung von Dartols Stab nötig ist.",al={"eisenschwertknauf abgeben","wohin mit eisenschwertknauf","wer will den knauf"}}},fx={["9716c2ef"]={q="Was ist der Eisenschwertknauf?",a="Der Eisenschwertknauf ist die letzte fehlende Komponente, die benötigt wird, um Dartols Stab wieder zusammenzusetzen, einen Stab, der von dem längst verstorbenen Zauberer Dartol erschaffen wurde. Vor ihrem tragischen Untergang waren die Druiden, die im Dor'danil-Grabhügel lebten, damit betraut, dieses schwere Metallteil zu beschützen. Verloren inmitten der Verderbnis und Gewalt, die über ihre Zuflucht hereinbrach, landete der Schwertknauf schließlich verschlossen in einer alten Truhe in der Wildnis und wartete darauf, dass jemand ihn bergen konnte.",al={"was ist ein eisenschwertknauf","eisenschwertknauf hintergrund","wofür ist der schwertknauf für dartols stab"}}},fp="11,302,23.366.0,23.246.1,33.213.0,30.169.0,26.199.0,29.136.0"}
P.entries["item:iron-rivet"] = {n="Eisenniete",s="Nördlich des Immerruhsees liegen Lieferungen von Eisennieten aus Sturmwind in Gnollagern. Großknecht Oslow braucht sie, um Seenhains beschädigte Brücke auszubessern.",h="Nördlich des Immerruhsees liegen Lieferungen von Eisennieten aus Sturmwind in Gnollagern.",kw={"everstill bridge","großknecht oslow","eisenspitze","eisenniete","seenhain","gnolle des rotkammgebirges","rotkammgebirge"},ang={["faction:Alliance"]="Die Bergung der gestohlenen Vorräte hilft Seenhain, seine Infrastruktur zu reparieren und die Bedrohung der Stadt durch die Gnolle einzudämmen.",["profession:Blacksmithing"]="Sturmwind schmiedete diese schweren Verbindungselemente für große Bauvorhaben, darunter Brücken aus Stein und Holz."},sec={{t="Gestohlene Karawanenfracht",b="Seenhain verbrauchte sein Eisen für Waffen und Rüstungen, als die Schwarzfelsorcs angriffen. Nachdem die Angriffe nachließen, bat Großknecht Oslow Sturmwind um Vorräte, um die beschädigte Everstill Bridge auszubessern. Gnolle des Rotkammgebirges überfielen die Karawane, bevor sie die Stadt erreichte. Sie schleppten ihre Wagen und Lasttiere in die Hügel nördlich des Immerruhsees und verteilten Eisennieten und Piken auf ihre Lager."},{t="Die Brücke ausbessern",b="Schwere Eisennieten halten das Gerüst der Everstill Bridge aus Stein und Holz unter der Last von Karren und Reisenden zusammen. Großknecht Oslow kann sie ohne diese Nieten nicht sicher reparieren. Die Brücke verbindet Seenhain mit den westlichen Tälern. Ihre Ausbesserung wird helfen, die Stadtgrenzen gegen weitere Einfälle zu sichern."}},faq={{q="Wofür werden Eisennieten verwendet?",a="Großknecht Oslow braucht die Eisennieten, um Seenhains beschädigte Everstill Bridge zu reparieren. Die ursprünglichen Eisenbestände der Stadt wurden während der Kämpfe mit den Schwarzfelsorcs eingeschmolzen.",al={"zweck der eisennieten","warum eisennieten benötigt werden","wofür sind eisennieten"}},{q="Warum haben die Gnolle diese Nieten?",a="Gnolle des Rotkammgebirges überfielen eine Nachschubkarawane aus Sturmwind und raubten ihre Baumaterialien. Die Nieten und Eisenpiken liegen nun in ihren Lagern nördlich von Seenhain.",al={"warum gnolle nieten haben","wie gnolle an eisennieten kamen","wer die nieten gestohlen hat"}},{q="Warum fehlte es Seenhain überhaupt an Eisen?",a="Seenhains Verteidiger schmolzen während der Invasion der Orcs die Eisenbestände der Stadt ein, um Schwerter, Kugeln und Rüstungen herzustellen.",al={"eisenmangel in seenhain","warum kein eisen in seenhain"}},{q="Wer sucht nach diesen Nieten?",a="Großknecht Oslow, der die Wiederherstellung der Everstill Bridge beaufsichtigt, sucht nach den Nieten.",al={"wer eisennieten will","wer eisennieten annimmt"}}},fx={["0d91405a"]={q="Was ist eine Eisenniete?",a="Eine Eisenniete ist ein stabiles Metallbefestigungsteil, das für schwere Bauarbeiten im Königreich geschmiedet wurde. Sturmwind sandte eine Lieferung dieser Nieten nach Seenhain, um beim Wiederaufbau der zerstörten Infrastruktur der Stadt zu helfen, insbesondere der lebenswichtigen Everstill Bridge.",al={"was ist eine eisenniete","was sind eisennieten","beschreibung eisenniete"}},a8a8e120={q="Woher stammen diese Eisennieten und wer hat sie hergestellt?",a="Diese Nieten wurden von Sturmwind als Teil einer Hilfskolonne entsandt, die Rohstoffe und Baumaterialien ins Rotkammgebirge transportierte. Vor Erreichen von Seenhain wurde die Kolonne von Gnollen aus dem Rotkammgebirge überfallen und geplündert, wodurch die Eisenvorräte in deren Hügellagern verstreut wurden.",al={"woher kommen eisennieten","wer hat eisennieten hergestellt","ursprung eisenniete"}}},fp="10,141,20.378.0,18.284.0,30.169.0,36.153.0,46.111.0,32.90.0"}
P.entries["item:iron-shaft"] = {n="Eisenschaft",s="Nahe dem Teufelswald bleibt der Eisenschaft unter Verschluss. Teronis sucht ihn als Teil von Dartol's Rod, in der Hoffnung, die Angriffe der Furbolgs auf Eschental einzudämmen.",h="Nahe dem Teufelswald bleibt der Eisenschaft unter Verschluss.",kw={"eschental","crazed ancient","dartol's rod","teufelswald","eisenschaft","raene's cleansing","shael'dryn","withered ancient","holzschlüssel"},ang={["class:Druid"]="Als Druide seid Ihr beim Zusammensetzen von Dartol's Rod Eurer Pflicht verpflichtet, das Land zu pflegen und es mit vergessenen Werkzeugen zu heilen.",["race:NightElf"]="Als Nachtelf bedeutet die Bergung des Eisenschafts für Euch, gegen geschätzte Treants des Waldes zu kämpfen, verdorben durch die dämonische Seuche aus dem Teufelswald."},sec={{t="Ein Teil von Dartol's Rod",b="Dartol fertigte den Stab, und seine Teile wurden über ganz Eschental verstreut. Eines wurde den Druiden von Dor'Danil anvertraut. Der Eisenschaft ist der robuste Metallkern des Stabs, eingeschlossen in einer Truhe auf einer Lichtung nahe Eschentals nördlicher Grenze, unweit des Teufelswalds."},{t="Die Verderbnis des Waldes",b="Den Schlüssel zur Truhe haben Treants, die einst diese Wälder pflegten. Dämonische Verderbnis aus dem Teufelswald hat die Crazed und Withered Ancients in den Wahnsinn getrieben. Shael'dryn, eine Dryade, bittet Reisende, den Schaft zu bergen, damit Dartol's Rod neu geschmiedet und Teronis' Werk vollendet werden kann."}},faq={{q="Wozu dient der Eisenschaft?",a="Der Eisenschaft ist ein Teil des zerbrochenen Dartol's Rod. Shael'dryn sucht die Teile, damit der Stab wieder zusammengesetzt und Teronis' Vorhaben, die Angriffe der Furbolgs auf Eschental einzudämmen, vollendet werden kann.",al={"eisenschaft zweck","was ist dieser schaft","warum brauche ich den eisenschaft"}},{q="Wo findet man den Eisenschaft?",a="Der Eisenschaft liegt in einer verschlossenen Truhe auf einer Lichtung westlich der Straße zum Teufelswald, im nördlichen Eschental.",al={"eisenschaft fundort","eisenschaft finden","wo ist die truhe"}},{q="Wie öffnet man die Truhe mit dem Schaft?",a="Ein Holzschlüssel öffnet die Truhe. Die verderbten Crazed und Withered Ancients tragen ihn bei sich, während sie durch die Wälder nordöstlich von Rajenbaum streifen.",al={"wie öffnet man die truhe","truhenschlüssel","eisenschaft schlüssel"}},{q="Wer sucht nach dem Eisenschaft?",a="Shael'dryn, eine Dryade an einem Mondbrunnen im Herzen Eschentals, weist Reisende an, die Teile von Dartol's Rod zu sammeln und bei der Reinigung des Waldes zu helfen.",al={"wer will den eisenschaft","eisenschaft questgeber"}}},fx={ad78a81b={q="Was ist der Eisenschaft?",a="Der Eisenschaft ist ein Schlüsselsegment von Dartols Stab, einem von Dartol geschaffenen Relikt. Die Teile des Stabes wurden über das Eschental verstreut, und dieses Stück landete verschlossen in einer versteckten Truhe nahe den Grenzen des Teufelswaldes, wobei sein Schlüssel von den dortigen verderbten Treants getragen wird.",al={"was ist ein eisenschaft","gegenstand eisenschaft","dartols stab eisenschaft"}},["45340e91"]={q="Woher stammt der Eisenschaft und wer hat ihn hergestellt?",a="Er wurde als Teil eines magischen Stabes geschmiedet, den Dartol erschuf. Die Teile des Stabes wurden später verstreut, und dieser spezielle Schaft wurde in einer abgenutzten Truhe in einer Lichtung nahe dem Teufelswald gesichert, indirekt bewacht von den verderbten Treants, die seinen Schlüssel halten.",al={"wer hat den eisenschaft hergestellt","ursprung eisenschaft","dartol eisenschaft"}},["3705c59d"]={q="Warum wird der Eisenschaft gesucht?",a="Raene Wolfsläufer und Shael'dryn versuchen, Dartols Stab wieder zusammenzusetzen, von dem Teronis glaubte, er könne die Furbolgangriffe auf die Nachtelfen des Eschentals verlangsamen. Der Wiederaufbau des Relikts erfordert das Sammeln der fehlenden Komponenten, und dieser stabile Eisenschaft bildet den zentralen Griff und Kern, der notwendig ist, um den magischen Edelstein und den Schwertknauf des Stabes zusammenzuhalten.",al={"warum wollen sie den eisenschaft","warum eisenschaft sammeln","eisenschaft questmotiv"}}},fp="10,146,23.242.0,19.262.1,32.190.0,30.104.0,47.138.0,34.139.0"}
P.entries["item:ironband-s-progress-report"] = {n="Eisenbands Fortschrittsbericht",s="Im östlichen Loch Modan haben Troggs die Ausgrabung von Ausgrabungsleiter Eisenband zum Stillstand gebracht. Sein Bericht bittet um mehr Sprengpulver, obwohl die Versammlung der Forscher schon vor Wochen Vorräte geschickt hat.",h="Im östlichen Loch Modan haben Troggs die Ausgrabung von Ausgrabungsleiter Eisenband zum Stillstand gebracht.",kw={"sprengpulver","versammlung der forscher","eisenband","jern hornhelm","loch modan","ausgrabungsleiter sturmlanze","thelsamar","troggs"},ang={["profession:Mining"]="Als Bergmann wisst Ihr, dass Sprengpulver hartnäckiges Gestein beseitigen kann. Ihr wisst auch, wie gefährlich es ist, wenn Vorräte im Gebiet der Troggs verschwinden.",["race:Dwarf"]="Als Zwerg, der auf Erkundung geht oder Erz abbaut, kennt Ihr die Gefahren von Ausgrabungen an uralten Titanenstätten in Khaz Modan."},sec={{t="Eine Bitte um Schießpulver",b="Jern Hornhelm erhält die Depesche in Thelsamar und leitet sie an die Versammlung der Forscher in Eisenschmiede weiter. Eisenband berichtet, dass die Arbeiten zum Stillstand gekommen sind, und bittet um schwere Munition. Die Führung der Versammlung ist ratlos. Sie hat ihm vor Wochen reichlich Sprengpulver geschickt und fragt sich nun, wo es geblieben ist."}},faq={{q="Was ist Eisenbands Fortschrittsbericht?",a="Der Bericht von Ausgrabungsleiter Eisenband beschreibt, wie Troggs seine Ausgrabung in Loch Modan stören, und bittet um mehr Sprengpulver.",al={"fortschrittsbericht","eisenbands bericht","was ist dieser bericht"}},{q="Wer erhält diesen Bericht?",a="Jern Hornhelm erhält den Bericht in Thelsamar und schickt ihn dann an Ausgrabungsleiter Sturmlanze im Hauptquartier der Versammlung der Forscher in Eisenschmiede.",al={"wer bekommt den bericht","wem den bericht geben","fortschrittsbericht abliefern"}},{q="Warum braucht Eisenband mehr Sprengpulver?",a="Eisenband sagt, er brauche Sprengpulver für seine Grabungen, doch wegen der Troggüberfälle in der Nähe könnte Sprengstoff auch zur Verteidigung nützlich sein. Hornhelm und Sturmlanze glauben, dass sie ihm vor Wochen reichlich davon geschickt haben.",al={"warum sprengpulver","was ist mit dem pulver passiert","pulvermangel"}},{q="Wie reagiert Ausgrabungsleiter Sturmlanze auf den Bericht?",a="Ausgrabungsleiter Sturmlanze ist wütend, dass die Arbeiten so langsam vorangekommen sind. Er ist ratlos, weil Eisenband die zuvor geschickte große Lieferung nicht erwähnt, und fragt sich, wo das fehlende Sprengpulver geblieben ist.",al={"sturmlanzes reaktion","ist sturmlanze wütend"}}},fx={["9e6c80e6"]={q="Woher stammt Eisenbands Fortschrittsbericht und wer hat ihn erstellt?",a="Das Dokument wird von Ausgrabungsleiter Eisenband selbst an seiner Ausgrabungsstätte im östlichen Loch Modan verfasst. Während er die beschwerlichen Grabungsarbeiten inmitten ständiger Trogg-Belästigungen beaufsichtigt, verfasste Eisenband den Bericht, um formelle Updates zum schleppenden Fortschritt seines Unternehmens zu geben und seine laufenden Materialanforderungen offiziell zu protokollieren.",al={"wer hat eisenbands fortschrittsbericht geschrieben","wer hat eisenbands bericht erstellt","woher kommt eisenbands bericht"}},["2cf6b481"]={q="Warum will jemand Eisenbands Fortschrittsbericht?",a="Der Bericht ist ein unverzichtbares Dokument, das von administrativen Kontakten in Thelsamar und dem Hauptquartier der Forscherliga in Eisenschmiede benötigt wird. Ohne diesen offiziellen Bericht, der die Schwierigkeiten der Stätte und die Trogg-Einmischung detailliert beschreibt, werden Vorgesetzte wie Ausgrabungsleiter Sturmlanze keine bürokratische Genehmigung erteilen, um neue Lieferungen von Sprengpulver freizugeben und zu versenden.",al={"warum wird eisenbands fortschrittsbericht benötigt","warum eisenbands bericht mitnehmen","zweck von eisenbands fortschrittsbericht"}}},fp="26,178,20.281.0,35.116.0,25.137.0,40.185.0,50.191.0"}
P.entries["item:ishamuhale-s-fang"] = {n="Ishamuhales Fangzahn",s="In Camp Taurajo erwartet Jorn Himmelsdeuter Ishamuhales Fangzahn, erbeutet von Speerzahn, einem gefürchteten Sonnenskalenraptor des Brachlands. Der Zahn beweist, dass ein Jäger eines der tödlichsten natürlichen Raubtiere Kalimdors bezwungen hat.",h="In Camp Taurajo erwartet Jorn Himmelsdeuter Ishamuhales Fangzahn, erbeutet von Speerzahn, einem gefürchteten...",kw={"brachland","fangzahn","ishamuhale","jorn","raptor","sergra","speerzahn","sonnenskalen","taurajo"},ang={["class:Hunter"]="Als Jäger durchlauft Ihr mit dem Erbeuten von Speerzahns Fangzahn einen Übergangsritus des Brachlands. Er prüft Euer Geschick darin, ein listiges Raubtier anzulocken, Euch ihm zu stellen und es zu bezwingen.",["race:Tauren"]="Als Tauren bedeutet Euch das Erbeuten des Zahns, die rohe Kraft eines Raubtiers in Euch aufzunehmen und dabei Disziplin und Gleichgewicht zu bewahren."},sec={{t="Trophäe von Speerzahn",b="In der gesamten zentralen Savanne fürchten Jäger Ishamuhale, den wildesten lebenden Sonnenskalenraptor. Manche sagen, der große Jäger töte aus Raubtierlust, nicht aus Hunger. Frisches Zhevrafleisch lockt die Bestie neben einem verdorrten Baum nordwestlich von Ratschet ins Freie. Dort kennt Ishamuhale keine Gnade.\n\nDas Erbeuten des gewaltigen Fangzahns beweist den Jagdausbildern der Horde, dass ein Reisender die Wildheit der Steppe bezwungen hat."},{t="Eine Lektion in Mäßigung",b="In Camp Taurajo sieht Jorn Himmelsdeuter mehr als Elfenbein und Blut in Ishamuhales Fangzahn. Für die Tauren dort überträgt das Erbeuten des Zahns die wilde Stärke des Raubtiers auf den Jäger, der es bezwungen hat. Dann folgt die Prüfung der Mäßigung. Der Jäger muss diese wilde Wut beherrschen, statt sie über seine Seele herrschen zu lassen."}},faq={{q="Was ist Ishamuhales Fangzahn?",a="Ishamuhales Fangzahn ist eine Trophäe von Ishamuhale, dem berüchtigten Sonnenskalenraptor Speerzahn, der das Brachland durchstreift.",al={"ishamuhale zahn","speerzahn fangzahn","raptor fangzahn brachland"}},{q="Wer will Ishamuhales Fangzahn?",a="Jorn Himmelsdeuter in Camp Taurajo will den Fangzahn. Er gehört zu den Jagdprüfungen, die bei Sergra Dunkeldorn am Wegekreuz beginnen.",al={"wem ishamuhales fangzahn geben","ishamuhales fangzahn abgeben","wohin gehört ishamuhales fangzahn"}},{q="Wie findet man die Bestie Ishamuhale?",a="Frisches Zhevrafleisch lockt Ishamuhale aus seinem Versteck. Es wird neben einem verdorrten Baum nordwestlich von Ratschet ausgelegt.",al={"ishamuhale erscheinen lassen","ishamuhale beschwören","wo ist ishamuhale"}},{q="Was bedeutet das Erbeuten des Fangzahns für die Tauren?",a="Für die Tauren bedeutet das Erbeuten von Ishamuhales Fangzahn, dass die legendäre Stärke des Raptors nun im Jäger lebt. Der Jäger muss diese Macht mit Mäßigung und Ehre einsetzen.",al={"bedeutung des fangzahns","tauren jägerritual ishamuhale"}}},fx={aa73e2a3={q="Woher stammt Ishamuhales Fangzahn?",a="Der Fangzahn stammt direkt aus den Kiefern von Ishamuhale, auch bekannt als Speerzahn. Er ist der wildeste Sonnenwuchs-Raptor, der das Brachland durchstreift, ein natürlicher Raubtier, der rein aus seinem wilden Instinkt heraus tötet. Er wurde nicht von sterblichen Händen gefertigt, sondern wuchs auf natürliche Weise als tödliche Waffe der Bestie.",al={"ursprung ishamuhales fangzahn","woher stammt ishamuhales fangzahn","wer hat ishamuhales fangzahn hergestellt"}}},fp="17,199,20.409.0,22.293.1,26.117.0,28.129.0,34.105.0,52.166.0"}
P.entries["item:ivar-s-head"] = {n="Ivars Kopf",s="Im nördlichen Silberwald sucht Rane Yorick Ivars Kopf, damit ihr verwundeter Bruder Quinn sich in Sicherheit erholen kann. Der Ghul überfiel sie aus dem Hinterhalt, als sie für Hochexekutor Hadrec auf Erkundung waren.",h="Im nördlichen Silberwald sucht Rane Yorick Ivars Kopf, damit ihr verwundeter Bruder Quinn sich in Sicherheit...",kw={"todespirscher","das ivar-feld","ivar the foul","ivars kopf","quinn yorick","rane yorick","silberwald"},ang={["faction:Horde"]="Als Mitglied der Horde wisst Ihr, dass die Beseitigung von Überresten der Geißel wie Ivar die Kuriere der Horde schützt, die durch den nördlichen Silberwald zum Grabmal reisen.",["race:Undead"]="Als Späher der Verlassenen wisst Ihr, dass wilde Ghule geistlose Gefahren sind. Sie stören die militärische Aufklärung und bedrohen die noch junge Sicherheit Lordaerons."},sec={{t="Eine abgetrennte Bedrohung",b="Rane und Quinn Yorick erkundeten auf Befehl von Hochexekutor Hadrec den nördlichen Silberwald, als Ivar the Foul sie auf einem verlassenen Gehöft aus dem Hinterhalt überfiel. Todespirscher der Verlassenen vertrieben den wilden Ghul, doch Quinn wurde schwer zugerichtet. Also blieb Rane auf dem verfallenen Hof, um über ihn zu wachen, da sie nicht gefahrlos aufbrechen und ihren Auftrag vollenden konnte. Ivars abgetrennter Kopf beweist, dass er das Anwesen nicht länger bedrohen kann, und gibt Quinn Zeit, sich unter Ranes Obhut zu erholen."}},faq={{q="Wessen Kopf ist das?",a="Der Kopf gehörte Ivar the Foul, einem wilden Ghul, der das verlassene Gehöft namens Ivar-Feld im nördlichen Silberwald heimsuchte.",al={"wer ist ivar","ivars kopf identität","was ist ivar"}},{q="Warum will Rane Yorick Ivars Kopf?",a="Rane will einen Beweis dafür, dass Ivar tot ist. Der Ghul hat ihren Bruder Quinn schwer zugerichtet, der Zeit braucht, sich ohne Angst vor einem weiteren Hinterhalt zu erholen, bevor sie Hochexekutor Hadrec Bericht erstatten.",al={"warum rane den kopf will","ivars kopf abgeben","warum ivar töten"}},{q="Wo wurde Ivar the Foul gefunden?",a="Ivar the Foul lauert in der baufälligen Scheune auf dem Ivar-Feld und wartet darauf, dass die verwundeten Todespirscher in ihrer Wachsamkeit nachlassen.",al={"ivars aufenthaltsort","wo ist ivar"}}},fx={fce823f2={q="Woher stammt Ivars Kopf?",a="Dieser abgetrennte Kopf stammt direkt vom Leichnam von Ivar the Foul, einem bösartigen Ghul, der in der zerstörten Scheune im Ivar-Feld im Silberwald lauert. Es ist kein Artefakt oder hergestellter Gegenstand, sondern die physische Trophäe, die von einem untoten Monster abgetrennt wurde, um zu garantieren, dass er wirklich vernichtet wurde.",al={"ursprung von ivars kopf","woher stammt ivars kopf","wer hat ivars kopf hergestellt"}}},fp="11,174,16.448.0,19.136.0,38.183.0,30.129.0"}
P.entries["item:iverron-s-antidote-item"] = {n="Iverrons Gegengift",s="Im Laubschattental muss Iverron's Antidote einen jungen Nachtelfen erreichen, bevor es verdirbt. Dirania Silberschein braut den Trank gegen das tödliche Gift der hiesigen Webwood-Spinnen, doch er hält sich nur fünf Minuten.",h="Im Laubschattental muss Iverron's Antidote einen jungen Nachtelfen erreichen, bevor es verdirbt.",kw={"aldrassil","dirania silberschein","iverron","iverron's antidote","laubschattental","spinnengift","teldrassil","webwood venom"},ang={["profession:Herbalism"]="Als Kräuterkundiger könnt Ihr erkennen, wie flüchtige Reagenzien aus Teldrassil Heilmittel hervorbringen, die sofort verwendet werden müssen.",["race:NightElf"]="Wenn Ihr als junger nachtelfischer Abenteurer im Laubschattental mit diesem Heilmittel zu Iverron eilt, zeigt sich, wie die Gemeinschaft gegen die Verderbnis in Teldrassils Ästen auf rasches Handeln und Kräuterwissen angewiesen ist."},sec={{t="Ein empfindliches Heilmittel",b="Dirania Silberschein braut Iverron's Antidote in Aldrassil für Iverron, einen jungen Nachtelfen, der von Webwood-Spinnen gebissen wurde. Seine flüchtigen Zutaten und pflanzlichen Katalysatoren begrenzen die Haltbarkeit des Tranks auf nur fünf Minuten. Boten müssen nach Norden zur Webwood-Höhle eilen und ihn abliefern, bevor er verdirbt."}},faq={{q="Wofür wird Iverron's Antidote verwendet?",a="Iverron's Antidote heilt Iverron nach einem giftigen Biss von Webwood-Spinnen vor ihrer Höhle im nördlichen Laubschattental.",al={"verwendung des gegengifts","was bewirkt iverron's antidote"}},{q="Warum ist das Gegengift nur begrenzt haltbar?",a="Dirania Silberschein sagt, dass der empfindliche Trank nach dem Brauen nur fünf Minuten lang wirksam bleibt. Danach verliert er seine heilenden Eigenschaften.",al={"warum fünf minuten","zeitlimit des gegengifts","warum verdirbt es"}},{q="Wer braut das Gegengift?",a="Dirania Silberschein, eine nachtelfische Heilerin in Aldrassil im Laubschattental, braut den Trank aus Zutaten, die gesammelt wurden, um Iverron zu retten.",al={"wer hat das gegengift hergestellt","hersteller des gegengifts"}},{q="Was geschieht, wenn das Gegengift verdirbt?",a="Nach fünf Minuten verdirbt der Trank und wirkt nicht mehr. Der Bote muss zu Dirania Silberschein in Aldrassil zurückkehren, um eine frische Mischung zu holen.",al={"gegengift verdorben","zeit abgelaufen"}}},fx={["59c1ca07"]={q="Was ist Iverron's Antidote?",a="Es ist ein frisch gebrauter medizinischer Trank, der speziell entwickelt wurde, um das tödliche Gift der Webholzspinnen zu neutralisieren, die in den Zweigen von Teldrassil lauern. Aufgrund seiner empfindlichen natürlichen Mischung ist das Heilmittel sehr flüchtig und verdirbt schnell, wenn es nicht innerhalb weniger Minuten nach seiner Zubereitung konsumiert wird.",al={"was ist iverron's antidote","iverron antidote","iverrons heilung"}}},fp="25,204,16.292.0,36.115.0,40.143.0,23.127.0,37.142.0"}
P.entries["item:jade-phial"] = {n="Jadephiole",s="In Dolanaar vertraut Corithras Mondzorn jungen Initianden die Jadephiole an. Sie bringen heiliges Wasser aus Teldrassils Mondbrunnen nach Darnassus, um den zentralen Brunnen der Druiden aufzufüllen.",h="In Dolanaar vertraut Corithras Mondzorn jungen Initianden die Jadephiole an.",kw={"corithras mondzorn","crown of the earth","dolanaar","jadephiole","mondbrunnen","sternenhauch","teldrassil"},ang={["class:Druid"]="Als junger Druide lernt Ihr früh, für Teldrassils Mondbrunnen zu sorgen. Ihre Lebenskraft verlangt beständige Ehrfurcht und Pflege.",["race:NightElf"]="Als Nachtelf wisst Ihr, dass Mondbrunnen die fortwährende Verbundenheit zwischen den kaldorei und Elune verkörpern. Sie mit Gefäßen wie der Jadephiole zu pflegen, ist eine heilige Pflicht."},sec={{t="Ein Gefäß für heilige Wasser",b="Die Jadephiole nimmt Wasser aus einem Mondbrunnen nahe Sternenhauch auf. Überall auf Teldrassil bündeln Mondbrunnen lunare und natürliche Energien, die für die Gesellschaft der Nachtelfen und die druidische Verehrung von Bedeutung sind.\n\nVon Zeit zu Zeit füllen Druiden ihren zentralen Mondbrunnen in Darnassus mit Wasser aus Brunnen auf dem gesamten großen Ast auf. Corithras Mondzorn vertraut die Phiole jungen Initianden an, die reines Wasser schöpfen, ohne die spirituelle Kraft des Mondbrunnens zu stören."}},faq={{q="Wozu dient die Jadephiole?",a="Die Jadephiole nimmt heiliges Wasser aus dem Mondbrunnen unmittelbar vor Sternenhauch auf. Bringt sie nach dem Befüllen zu Corithras Mondzorn in Dolanaar zurück, damit die Druiden ihren Mondbrunnen in Darnassus auffüllen können.",al={"jadephiole zweck","warum brauche ich die jadephiole","was macht die jadephiole"}},{q="Wer stellt die Jadephiole bereit?",a="Corithras Mondzorn, ein Nachtelfendruide in Dolanaar, stellt Abenteurern die Jadephiole bereit, wenn sie den als Crown of the Earth bekannten Ritus vollziehen.",al={"wer gibt die jadephiole","wo gibt es die jadephiole","corithras jadephiole"}},{q="Wohin gelangt das Wasser aus dieser Phiole?",a="Das in der Jadephiole gesammelte Wasser wird nach Darnassus gebracht, um den zentralen Mondbrunnen aufzufüllen, den die Cenarion-Druiden pflegen.",al={"wohin gelangt mondbrunnenwasser","jadephiole ziel","wer nutzt das wasser"}}},fx={["8250d8c3"]={q="Was ist die Jadephiole?",a="Die Jadephiole ist ein speziell angefertigtes rituelles Gefäß, das von Corithras Mondzorn in Dolanaar bereitgestellt wird. Sie wurde entwickelt, um die heiligen, gesegneten Wasser, die aus den Mondbrunnen von Teldrassil geschöpft werden, sicher aufzubewahren und zu transportieren, ohne ihre inhärenten magischen Eigenschaften zu stören oder zu beeinträchtigen.",al={"jadephiole","was ist die jadephiole","was ist eine jadephiole"}}},fp="10,185,26.442.0,32.207.0,28.143.0,44.125.0"}
P.entries["item:jennea-s-flask"] = {n="Jenneas Fläschchen",s="Im Magiersanktum in Sturmwind schickt Jennea Haubitz Lehrlinge zum Spiegelsee, um Wasser zu holen. Sie bringen eine Probe für arkane Studien zurück.",h="Im Magiersanktum in Sturmwind schickt Jennea Haubitz Lehrlinge zum Spiegelsee, um Wasser zu holen.",kw={"wald von elwynn","jennea haubitz","jenneas fläschchen","spiegelsee","sturmwind","wasserprobe","magiersanktum"},ang={["class:Mage"]="Als Magier ist das Tragen dieses Fläschchens eine Eurer ersten Aufgaben im Feld für das Magiersanktum. Dabei wird Eure Fähigkeit geprüft, behutsam arkane Forschung zu betreiben und auf Veränderungen der Ley-Linien zu achten."},sec={{t="Ein Gefäß für arkane Forschung",b="Arkane Ströme wurden durch magische Kämpfe in ganz Azeroth aus ihren uralten Bahnen gerissen. Jennea Haubitz will erfahren, wie sich diese Verschiebungen auf den Wald von Elwynn ausgewirkt haben. Sie gibt vielversprechenden Lehrlingen ein Glasfläschchen und schickt sie südwestlich der Tore von Sturmwind zum Fuß des Wasserfalls am Spiegelsee.\n\nDas Fläschchen schützt die Wasserprobe auf dem Rückweg zum Magiersanktum. Dort kann Jennea sie auf arkane Störungen untersuchen."},{t="Schutz der Gewässer",b="Mit Jenneas Fläschchen können die Magier von Sturmwind prüfen, ob sich verschiebende Ley-Linien den Spiegelsee verunreinigt haben. Schädliche Magie im Wasser könnte bei den Lebewesen der Umgebung und allen, die davon trinken, seltsame Leiden auslösen. Eine Probe könnte magische Rückstände offenbaren, bevor sich verunreinigte Ströme im Umland ausbreiten."}},faq={{q="Wofür wird Jenneas Fläschchen verwendet?",a="Verwendet Jenneas Fläschchen, um Wasser vom Wasserfall am Spiegelsee im Wald von Elwynn zu sammeln.",al={"zweck des fläschchens","was bewirkt das fläschchen","verwendung des fläschchens"}},{q="Wer gibt Euch dieses Fläschchen?",a="Jennea Haubitz, eine Magierlehrerin im Magiersanktum von Sturmwind, gibt Euch das Fläschchen.",al={"wer gibt das fläschchen","jenneas fläschchen herkunft"}},{q="Warum will Jennea Wasser aus dem Spiegelsee?",a="Jüngste mystische Konflikte haben den Fluss der Magie auf der ganzen Welt gestört. Jennea fürchtet, dass verirrte Ströme in Elwynns Gewässer sickern und alle gefährden könnten, die aus dem See trinken.",al={"warum wasser aus dem spiegelsee","warum eine wasserprobe"}},{q="Wo füllt Ihr das Fläschchen?",a="Füllt das Fläschchen am Fuß des Wasserfalls, der in den Spiegelsee mündet, südwestlich der Haupttore von Sturmwind im Wald von Elwynn.",al={"wo das fläschchen füllen","fundort des fläschchens","lage des sees"}}},fx={b836f408={q="Was ist Jenneas Fläschchen?",a="Es ist ein spezialisierter Probenbehälter, der von Jennea Haubitz bereitgestellt wird, einer Ausbilderin im Magierviertel von Sturmwind. Sie vertraut ihn vielversprechenden Lehrlingen an, um Wasser direkt vom Wasserfall am Mirror Lake zu sammeln, damit sie es auf magische Verunreinigungen untersuchen kann.",al={"was ist jenneas fläschchen","jenneas fläschchen"}}},fp="14,138,28.439.0,19.309.0,32.86.0,25.88.0,44.184.0,28.126.0"}
P.entries["item:jitters-completed-journal"] = {n="Bibbers' vollendetes Tagebuch",s="Im Dämmerwald übergibt Bibbers sein vollendetes Tagebuch und hofft, damit seinen Namen reinzuwaschen. Er fürchtet Sven Yorgens Rache, nachdem er vor dem Massaker auf Svens Hof geflohen ist.",h="Im Dämmerwald übergibt Bibbers sein vollendetes Tagebuch und hofft, damit seinen Namen reinzuwaschen.",kw={"bischof heller","kathedrale des lichts","dunkle reiter","dämmerwald","das verlassene gut","bibbers","tagebuch","morbent fel","sven yorgen"},ang={["class:Priest"]="Als Priester bringt Ihr das Tagebuch zu Bischof Heller in der Kathedrale des Lichts und tragt durch heilige Reliquien zur Reinigung von unheiliger Verderbnis bei.",["faction:Alliance"]="Als Mitglied der Allianz seht Ihr, wie sehr der Dämmerwald in Gefahr geraten ist, während Sturmwinds Anführer ihre Aufmerksamkeit anderen Dingen widmen."},sec={{t="Das Geständnis eines Feiglings",b="Bibbers floh von Svens Hof, als der Angriff begann, und ließ sein halb fertiges Tagebuch in den Trümmern zurück. Im vollendeten Tagebuch berichtet er, wie geheimnisvolle dunkle Reiter Svens Familie niedermetzelten. Wochenlang waren dessen Seiten sein einziger Trost, während er sich im Dämmerwald versteckte. Nun übergibt er den fertigen Band bereitwillig und hofft, dass die Wahrheit ihn vor Svens Zorn bewahren wird."},{t="Der Dunkelheit auf der Spur",b="Das Tagebuch bringt Sven dazu, von Reitern in schwarzen Umhängen zu erzählen, die er am Verlassenen Gut mit dem Magier Morbent Fel sprechen sah. Sven schickt das Manuskript mit Reisenden nach Norden, die zur Kathedrale des Lichts in Sturmwind unterwegs sind. Dort liest Bischof Heller Bibbers' Bericht, um mehr über die abscheuliche Verderbnis des Dämmerwalds zu erfahren. Die darin enthaltenen Enthüllungen helfen ihm, eine heilige Waffe zu fertigen, die Fels dunkle Schutzzauber durchdringen kann."}},faq={{q="Warum hat Bibbers sein Tagebuch übergeben?",a="Bibbers floh während des Angriffs von Svens Hof und ließ ein unvollendetes Tagebuch zurück. Er übergibt Abenteurern die vollendete Fassung, damit sie sie Sven bringen, und hofft, dass die ganze Wahrheit seinen Namen reinwäscht und ihn vor Svens Zorn schützt.",al={"warum übergibt bibbers das tagebuch","bibbers' tagebuch","warum hat bibbers das geschrieben"}},{q="Was enthüllt das Tagebuch über Svens Hof?",a="Bibbers' vollendetes Tagebuch enthält seinen Augenzeugenbericht über die Tragödie auf Sven Yorgens Hof und ergänzt, was sein unvollendetes Tagebuch ausgelassen hat.",al={"was geschah auf svens hof","angriff auf svens familie","dunkle reiter svens hof"}},{q="Wer ist Morbent Fel und wie hängt er mit dem Tagebuch zusammen?",a="Morbent Fel ist ein Nekromant am Verlassenen Gut. Das Tagebuch bringt Sven dazu, zu erzählen, dass er die Reiter in schwarzen Umhängen mit Fel sprechen gesehen hat.",al={"morbent fel verbindung","wer ist morbent fel","magier am verlassenen gut"}},{q="Warum wird das Tagebuch nach Sturmwind gebracht?",a="Sven schickt das Tagebuch zu Bischof Heller in der Kathedrale des Lichts in Sturmwind. Heller liest es, um die Verderbnis des Dämmerwalds zu verstehen und bei der Vorbereitung einer heiligen Waffe zu helfen, die Morbent Fels magische Schutzzauber durchdringen kann.",al={"warum bischof heller","tagebuch zur kathedrale bringen","seeking wisdom tagebuch"}}},fx={["3f8dfebe"]={q="Was ist Bibbers' vollendetes Tagebuch?",a="Es ist die vollständige persönliche Chronik von Bibbers, einem verängstigten Vagabunden, der sich im Dämmerwald versteckt. Anders als die bruchstückhaften Notizen, die er hinterließ, als er von Sven Yorgens Hof floh, legt dieses vollendete Manuskript die gesamte Abfolge der Tragödien dar, die den Hof trafen, die vordringenden Schrecken des Waldes und die finsteren Gestalten, die sich durch die Schatten bewegen.",al={"bibbers vollendetes tagebuch","was ist dieses tagebuch","bibbers tagebuch"}},e7121643={q="Woher stammt Bibbers' vollendetes Tagebuch und wer hat es verfasst?",a="Das Tagebuch wurde von Bibbers selbst geschrieben. Nachdem er das Massaker auf Svens Hof überlebt und ein früheres Tagebuch zurückgelassen hatte, verbrachte er Wochen im Versteck, hielt hastig seine Gedanken fest und chronisierte die finsteren Mächte, die den Dämmerwald heimsuchten. Er behielt den fertigen Band als seinen einzigen Begleiter, bis er ihn übergab, um nicht dem Zorn von Sven Yorgen gegenüberzustehen.",al={"wer schrieb bibbers vollendetes tagebuch","ursprung von bibbers tagebuch","woher kommt das tagebuch"}},["5c3c5710"]={q="Warum wird Bibbers' vollendetes Tagebuch gesucht?",a="Sven Yorgen sucht das Tagebuch wegen Bibbers' Augenzeugenbericht der Tragödie auf seinem Hof. Später studiert Bischof Heller in der Kathedrale des Lichts das Tagebuch, um einen Abenteurer darauf vorzubereiten, sich dem Bösen zu stellen, das den Dämmerwald heimsucht.",al={"warum wollen sie das tagebuch","warum ist bibbers tagebuch wichtig","wer will das tagebuch"}}},fp="26,161,21.343.1,23.373.1,36.219.0,47.140.1,58.142.1,38.206.1"}
P.entries["item:johaan-s-findings"] = {n="Johaans Funde",s="In Brill schickt Apotheker Johaan seine Funde nach Süden zum Grabmal. Seine Forschung bringt die jüngsten alchemistischen Arbeiten aus Tirisfal zu Apotheker Renferrel im Silberwald.",h="In Brill schickt Apotheker Johaan seine Funde nach Süden zum Grabmal.",kw={"apotheker johaan","apotheker renferrel","brill","johaan","johaans funde","new plague","königliche apothekervereinigung","das grabmal"},ang={["faction:Horde"]="Als Mitglied der Horde führt Euch der Transport der Forschungsergebnisse nach Süden aus dem vertrauten Tirisfal in die düstereren Konflikte des Silberwalds.",["race:Undead"]="Als Untoter zeigen Euch diese Funde das treibende Ziel der Königlichen Apothekervereinigung: die der Dark Lady versprochene New Plague zu liefern."},sec={{t="Korrespondenz der Apotheker",b="Apotheker Johaan schickt seine Forschungsergebnisse aus Brill an Apotheker Renferrel im Grabmal. Die Königliche Apothekervereinigung folgt der Forderung von Fürstin Sylvanas Windläufer nach einer New Plague, die sowohl die Lebenden als auch die Geißel vernichten kann. Ihre Forscher sind über die umkämpften Ruinen Lordaerons verstreut, also tauschen sie ihre Erkenntnisse zwischen den Außenposten aus.\n\nRenferrel leitet die Bemühungen der Vereinigung vom Silberwald aus, während Johaan seine örtlichen Versuche in Brill dokumentiert. Seine Dokumente fließen in die umfassendere Arbeit der Vereinigung ein, ihre tödlichen Gebräue zu verfeinern."}},faq={{q="Was sind Johaans Funde?",a="Johaans Funde sind alchemistische Notizen und Forschungsergebnisse, die Apotheker Johaan in Brill zusammengestellt hat. Sie dokumentieren seine jüngsten Versuche und Experimente in Tirisfal.",al={"johaans funde","was sind johaans funde","johaans forschungsunterlagen"}},{q="Wer soll diesen Gegenstand erhalten?",a="Apotheker Renferrel soll die Funde erhalten. Er ist ein ranghohes Mitglied der Königlichen Apothekervereinigung im Grabmal im nördlichen Silberwald.",al={"wer erhält johaans funde","wohin mit johaans funden","lieferung an renferrel"}},{q="Warum werden diese Forschungsergebnisse unter Apothekern ausgetauscht?",a="Die Königliche Apothekervereinigung teilt Wissen unter ihren verstreuten Forschern, um deren Arbeit zu beschleunigen. Sylvanas Windläufer verlangt rasche Fortschritte bei der New Plague, also müssen die Forscher im Silberwald von Entdeckungen in Tirisfal erfahren.",al={"warum erkenntnisse teilen","zweck von johaans funden","forschung der königlichen apothekervereinigung"}},{q="Wer hat diese Dokumente verfasst?",a="Apotheker Johaan hat die Dokumente verfasst. Er ist ein Alchemist der Königlichen Apothekervereinigung nahe dem Galgen in Brill, wo er örtliche Proben für die alchemistischen Arbeiten der Verlassenen untersucht.",al={"wer ist apotheker johaan","wer hat das verfasst","apotheker johaan"}}},fp="17,181,25.524.0,26.156.0,37.156.0,55.236.0,26.169.0"}
P.entries["item:johaan-s-special-drink"] = {n="Johaans Spezialgetränk",s="In Brill bietet Apotheker Johaan ein Getränk an, das die entstehende Seuche der Königlichen Apothekervereinigung erprobt. Sein tödlicher Zweck verbirgt sich hinter dem Anschein einer gewöhnlichen Erfrischung.",h="In Brill bietet Apotheker Johaan ein Getränk an, das die entstehende Seuche der Königlichen...",kw={"apotheker johaan","brill","gefangener gebirgsjäger","taverne zur galgenschlinge","johaan","johaans spezialgetränk","neue seuche"},ang={["race:Dwarf"]="Als Zwerg lauft Ihr Gefahr, nahe Tirisfal von der Todeswache gefangen genommen und als Versuchsperson benutzt zu werden.",["race:Undead"]="Als Verlassener helft Ihr der Königlichen Apothekervereinigung und treibt Lady Sylvanas’ Pläne gegen die Lebenden voran."},sec={{t="Ein giftiges Gebräu",b="In Brill mischt Apotheker Johaan giftige Bestandteile mit örtlichen Reagenzien. Das Gebräu sieht wie ein Tavernengetränk aus, doch es erprobt, wie virulent die Seuche gegen Lebewesen ist. Johaan bietet es an, als wolle er den Durst eines Gefangenen stillen. Die Arbeit hilft den Apothekern der Verlassenen, eine Waffe zu erschaffen, die mächtig genug ist, Sylvanas Windläufers Pläne für Azeroth zu verwirklichen."},{t="Der Versuch im Keller",b="Unter der Taverne Zur Galgenschlinge hält die Todeswache verirrte Eindringlinge in einer Kellerzelle fest. Ein gefangener zwergischer Gebirgsjäger liegt dort in Ketten. Er hält das Gebräu für einfaches Bier, trinkt es begierig und stirbt auf der Stelle. Sein Tod zeigt der Königlichen Apothekervereinigung, dass ihr neuester Stamm lebende Opfer rasch auslöschen kann."}},faq={{q="Was ist Johaans Spezialgetränk?",a="In Brill bereitet Apotheker Johaan ein tödliches Getränk zu, um die entstehende Seuche der Verlassenen an Lebewesen zu erproben.",al={"was ist johaans getränk","johaan getränk","was ist dieser gegenstand"}},{q="Wem wird das Getränk gegeben?",a="Das Getränk wird in den Keller unter der Taverne Zur Galgenschlinge in Brill gebracht und einem gefangenen Gebirgsjäger gegeben, den die örtliche Todeswache festhält.",al={"wer trinkt es","wem das getränk geben","empfänger des getränks"}},{q="Was geschieht, wenn jemand es trinkt?",a="Der Gefangene trinkt das Gebräu in der Erwartung, herbes Bier zu bekommen, und stirbt auf der Stelle.",al={"stirbt der zwerg","wirkung des getränks","was bewirkt es"}},{q="Warum stellt Apotheker Johaan dieses Getränk her?",a="Apotheker Johaan stellt das Getränk her, um die neue Seuche der Königlichen Apothekervereinigung zu erproben. Er gibt es einem gefangenen Zwerg, um zu sehen, wie wirksam es sterbliches Leben auslöscht.",al={"warum hat johaan es hergestellt","apotheker johaans beweggrund","warum die seuche erproben"}}},fx={["7bd04f9d"]={q="Woher stammt Johaans Spezialgetränk und wer hat es hergestellt?",a="Das Gebräu wird direkt von Apotheker Johaan in Brill in Tirisfal gebraut. Im Auftrag der Königlichen Apothekervereinigung und Fürstin Sylvanas Windläufer verfeinert Johaan experimentelle Toxine, die von lokalen Kreaturen gesammelt wurden, um diese wirksame, tödliche Mischung herzustellen.",al={"wer hat johaans spezialgetränk hergestellt","woher stammt johaans spezialgetränk","wer hat das getränk gebraut"}}},fp="22,174,12.359.0,16.323.1,31.117.0,26.139.0,36.68.1,43.163.0"}
P.entries["item:jordan-s-ore-shipment"] = {n="Jordans Erzlieferung",s="In den nordöstlichen Hügeln von Loch Modan halten Oger der Mo'grosh Jordans Erzlieferung fest. Das Erz kam per Karawane aus dem Sumpfland, damit Bailor Steinhand es für den Schmied Jordan Stillbrunn zu einer Legierung veredeln konnte.",h="In den nordöstlichen Hügeln von Loch Modan halten Oger der Mo'grosh Jordans Erzlieferung fest.",kw={"legierung","bailor steinhand","jordan stillbrunn","jordans erzlieferung","loch modan","mo'grosh","test of righteousness"},ang={["class:Paladin"]="Als Paladin müsst Ihr die gestohlene Legierung von den Ogern der Mo'grosh zurückholen, um Jordan Stillbrunns Auftrag voranzubringen. Damit beweist Ihr beim Test of Righteousness Eure Hingabe.",["profession:Blacksmithing"]="Als Schmied könnt Ihr Bailor Steinhands besondere Legierung als hochwertige zwergische Metallurgie erkennen. Jordan Stillbrunn lehnte gewöhnliche Ersatzstoffe für seine Arbeit ab."},sec={{t="Eine Lieferung im Hinterhalt",b="Jordan Stillbrunns Erz war für Bailor Steinhand bestimmt, einen Zwerg, der es zu seiner besonderen Legierung veredeln sollte. Die Karawane brachte es vom Sumpfland nach Süden durch die Berge nach Loch Modan. Dann überfielen Oger der Mo'grosh die Reisenden und schleppten die Lieferung in ihre Festung in der Wildnis. Die überlebenden Wachen erlagen ihren Wunden, und Jordans Schmiedeprojekt wartet auf die Rückkehr des Erzes."}},faq={{q="Was enthält die Lieferung?",a="Die Lieferung enthält Erz, das Bailor Steinhand zu seiner besonderen Legierung veredeln soll. Jordan Stillbrunn braucht es für seine Metallarbeiten in Eisenschmiede.",al={"was enthält jordans erzlieferung","was ist das für erz","jordans erzlieferung inhalt"}},{q="Wer hat Jordans Erzlieferung gestohlen?",a="Oger der Mo'grosh überfielen die Karawane, als sie vom Sumpfland nach Süden zog. Sie schlachteten die Begleiter ab und schleppten die Kisten in ihr Gebiet nordöstlich des Lochs.",al={"wer nahm die erzlieferung","wer hat sie gestohlen","oger erzlieferung"}},{q="Wer ist Bailor Steinhand?",a="Bailor Steinhand ist ein zwergischer Handwerker, der in Loch Modan stationiert ist, und ein alter Freund von Jordan Stillbrunn. Er organisierte die Legierungslieferung, bevor Oger sie überfielen.",al={"bailor steinhand","wer ist bailor"}},{q="Warum ist diese Lieferung für Paladine wichtig?",a="Paladine, die sich dem Test of Righteousness stellen, suchen die Legierung, um Jordan Stillbrunn beim Schmieden einer geweihten Waffe des Lichts zu helfen.",al={"paladin erzlieferung","test of righteousness erz","warum brauchen paladine das"}}},fx={bb183b6f={q="Was ist Jordans Erzlieferung?",a="Jordans Erzlieferung ist eine Kiste mit Erz, die der Zwerg Bailor Steinhand für den Schmied Jordan Stillbrunn in Eisenschmiede zu seiner Speziallegierung veredeln sollte. Die Fracht wurde von einer aus dem Sumpfland kommenden Karawane transportiert, bevor sie im nördlichen Loch Modan von Ogern der Mo'grosh überfallen und erbeutet wurde.",al={"was ist jordans erzlieferung","jordans erzlieferung info","was ist bailors erz"}},["84b5d642"]={q="Woher kommt Jordans Erzlieferung und wer hat sie hergestellt?",a="Die Lieferung besteht aus Erz, das sich auf dem Weg per Karawane aus dem Sumpfland nach Loch Modan befand, wo Bailor Steinhand es für seinen alten Freund Jordan Stillbrunn zu seiner Legierung veredeln sollte. Oger fingen den Transport ab und töteten seine Wachen, bevor er eintraf.",al={"wer stellte jordans erzlieferung her","woher kam jordans erzlieferung","ursprung von jordans erzlieferung"}}},fp="21,201,20.399.0,28.134.0,32.168.0,24.157.0,43.126.0"}
P.entries["item:jordan-s-refined-ore-shipment"] = {n="Jordans aufbereitete Erzlieferung",s="Jordans aufbereitete Erzlieferung trifft für den Test of Righteousness in Eisenschmiede ein. Das Metall ist für den Schmied Jordan Stillbrunn vorbereitet, damit er eine heilige Waffe schmieden kann.",h="Jordans aufbereitete Erzlieferung trifft für den Test of Righteousness in Eisenschmiede ein.",kw={"bailor","eisenschmiede","jordan stillbrunn","paladinwaffe","aufbereitetes erz","test of righteousness"},ang={["class:Paladin"]="Als Paladin müsst Ihr Geduld und Hingabe beweisen, um diese aufbereitete Erzlieferung zu erhalten. Dies ist eine der körperlichen Prüfungen, die Ihr bestehen müsst, um Eure symbolträchtige Waffe des Lichts zu fertigen.",["profession:Blacksmithing"]="Als Schmied wisst Ihr, dass meisterhafte Schmiedearbeit makellose, sorgfältig vorbereitete Barren statt rohem Erz aus dem Gelände erfordert."},sec={{t="Die Materialien eines Schmieds",b="Jordan Stillbrunn benötigt seltene Materialien für eine Waffe, die eines Paladins würdig ist. Er braucht einen Geläuterten Koredelstein, robustes Weißsteineichenholz, seinen verlorenen Schmiedehammer und aufbereitetes Erz. Die Lieferung bringt das Metall für dieses heilige Werk nach Eisenschmiede."}},faq={{q="Wofür wird Jordans aufbereitete Erzlieferung verwendet?",a="Das aufbereitete Erz geht an Jordan Stillbrunn vor den Toren von Eisenschmiede. Es ist eine von vier Schlüsselkomponenten für eine meisterhafte Waffe für Paladine, die sich dem Test of Righteousness stellen.",al={"zweck des aufbereiteten erzes","was macht jordan mit dem erz","verwendung der erzlieferung"}},{q="Wer bereitet das Erz auf?",a="Bailor organisiert die Lieferung und überwacht die Aufbereitung und den Versand des speziellen Metalls, das Jordan Stillbrunn benötigt.",al={"wer hat das erz hergestellt","bailor erz","wer bereitet jordans erz auf"}},{q="Warum braucht Jordan genau diese Lieferung?",a="Jordan Stillbrunn plant, ein Symbol des Paladintums und des Lichts zu fertigen. Er braucht hochwertige Materialien, die über gewöhnliche Schmiedereste hinausgehen, und das speziell verarbeitete Metall verleiht Klinge oder Hammerkopf die Ausgewogenheit und Reinheit, die eines heiligen Ritters würdig sind.",al={"warum besonderes erz","warum kann jordan kein gewöhnliches eisen verwenden","grund für aufbereitetes erz"}}},fx={ec64bb0f={q="Was ist Jordans aufbereitete Erzlieferung?",a="Jordans aufbereitete Erzlieferung ist eine Kiste mit hochwertigem, speziell verarbeitetem Metall, das für den Waffenschmied Jordan Stillbrunn vorbereitet wurde. Dieses aufbereitete Erz, das eher für feine Schmiedearbeiten als für gewöhnliche Schmiedearbeit gedacht ist, bietet das reine metallische Fundament, das Jordan benötigt, um eine außergewöhnliche Waffe zu schmieden, die eines engagierten Paladins des Lichts würdig ist.",al={"was ist jordans aufbereitete erzlieferung","hintergrund zu jordans aufbereiteter erzlieferung","was ist jordans aufbereitetes erz"}}},fp="29,158,19.241.0,47.167.0,29.114.0,44.240.0"}
P.entries["item:jordan-s-smithing-hammer"] = {n="Jordans Schmiedehammer",s="Jordan Stillbrunn wartet vor Eisenschmiede auf den Hammer seines Vaters, der in Burg Shadowfang verloren ging.",h="Jordan Stillbrunn wartet vor Eisenschmiede auf den Hammer seines Vaters, der in Burg Shadowfang verloren ging.",kw={"dun morogh","eisenschmiede","jordan stillbrunn","paladinwaffe","burg shadowfang","schmiedehammer","the test of righteousness"},ang={["class:Paladin"]="Als Paladin müsst Ihr Euch in gefährliche Lande wagen, um den ererbten Hammer zurückzuholen und Eure Entschlossenheit in den Prüfungen der Rechtschaffenheit zu beweisen.",["profession:Blacksmithing"]="Als Schmied kennt Ihr die Verbundenheit zwischen einem Meisterschmied und einem Hammer, den seine Vorfahren ihm hinterlassen haben."},sec={{t="Das Erbe eines Handwerkers",b="Jordan Stillbrunn ist ein menschlicher Schmied, der vor Eisenschmiede arbeitet. Der Hammer seines Vaters liegt in Burg Shadowfang im Silberwald. Ohne ihn kann Jordan keine heilige Waffe schmieden, die eines heiligen Streiters würdig ist, das Meisterwerk, das er zu schaffen hofft."}},faq={{q="Wo befindet sich Jordans Schmiedehammer?",a="Jordans Schmiedehammer liegt in Burg Shadowfang in den Wäldern des Silberwalds. Paladine, die sich The Test of Righteousness stellen, müssen die besetzte Festung betreten, um ihn zurückzuholen.",al={"fundort des hammers","wo ist jordans hammer","wo ist jordans schmiedehammer zu finden"}},{q="Warum ist dieser Hammer für Jordan Stillbrunn so wichtig?",a="Jordan hat den Hammer von seinem Vater geerbt, und er bedeutet ihm viel. Er braucht ihn, um sein bestes Werk zu schmieden, eine heilige Waffe, die dem Licht geweiht ist.",al={"warum will jordan den hammer","geschichte von jordan stillbrunns hammer"}},{q="Wofür wird der Hammer nach seiner Bergung verwendet?",a="Bringt den Hammer zusammen mit Bauholz, Erz und einem Edelstein zu Jordan vor den Toren von Eisenschmiede. Er wird eine heilige Waffe für den Paladin schmieden, der ihm geholfen hat.",al={"was wird mit dem hammer geschmiedet","hammerverwendung bei the test of righteousness"}}},fx={["126e648c"]={q="Was ist Jordans Schmiedehammer?",a="Jordans Schmiedehammer ist ein geschätztes Schmiedewerkzeug des Meisterschmieds Jordan Stillbrunn. Über seinen praktischen Nutzen am Amboss hinaus hat er einen tiefen sentimentalen Wert als Erbstück, das direkt von seinem Vater an Jordan weitergegeben wurde.",al={"was ist jordans schmiedehammer","gegenstand jordans hammer","über jordans schmiedehammer"}},["1df19239"]={q="Woher stammt Jordans Schmiedehammer und wer hat ihn hergestellt?",a="Der Hammer wurde Jordan Stillbrunn von seinem Vater übergeben. Sein genauer Hersteller ist nicht verzeichnet, aber bevor Ihr ihn geborgen habt, war das Erbstück irgendwie weit weg von Eisenschmiede gelandet, versteckt in den dunklen Festungsmauern von Burg Shadowfang.",al={"woher stammt jordans hammer","wer hat jordans schmiedehammer hergestellt","ursprung von jordans schmiedehammer"}}},fp="24,93,20.244.0,42.172.0,51.148.0,43.150.0"}
P.entries["item:kadrak-s-flag"] = {n="Kadraks Flagge",s="An der Grenze des Brachlands schickt Kadrak die Farben der Horde auf feindlichen Boden. Das Banner wird im Krallenbau aufgepflanzt, nachdem Rynthariel getötet wurde.",h="An der Grenze des Brachlands schickt Kadrak die Farben der Horde auf feindlichen Boden.",kw={"brachland","horde presence","kadrak","kadraks flagge","rynthariel","steinkrallengebirge","der steinkrallengipfel","krallenbau"},ang={["faction:Horde"]="Das Aufpflanzen des Banners tief im Krallenbau verkündet die Stärke der Horde. Es zeigt, dass die Horde bei Provokation Heiligtümer der Nachtelfen angreifen wird.",["race:NightElf"]="Als Nachtelf seht Ihr das Banner der Horde im Krallenbau als direkte Beleidigung der Beschützer des Steinkrallengipfels."},sec={{t="Ein Zeichen des Trotzes",b="Kadrak schickt die Flagge der Horde in den Krallenbau auf dem Steinkrallengipfel. Rynthariel, die Dryade und Schlüsselmeister des Den, hat Nachrichten über die Grenze geschickt. Kadrak beschließt, dass ihr Tod allein keine ausreichende Antwort darauf ist. Er gibt Euch ein purpurrotes Banner, das Ihr tief im Den aufpflanzen sollt. Dort warnen die Farben der Horde Nachtelfen und Dryaden, dass Einfälle ins Brachland mit Vergeltung auf dem Boden der Allianz beantwortet werden."}},faq={{q="Wofür wird Kadraks Flagge verwendet?",a="Nachdem Ihr Schlüsselmeister Rynthariel getötet habt, pflanzt Kadraks Flagge im Krallenbau auf dem Steinkrallengipfel auf. Das Banner der Horde warnt die Nachtelfen davor, weitere Späher und Boten ins Brachland zu schicken.",al={"zweck der flagge","warum die flagge aufpflanzen","was bewirkt die flagge"}},{q="Wer gibt Euch die Flagge?",a="Kadrak gibt Euch das Banner. Er ist ein Orcspäher am Grenzwachtposten zwischen dem nördlichen Brachland und Eschental und arbeitet daran, die Region zu sichern.",al={"wer gibt die flagge","wo die flagge erhalten","kadraks standort"}},{q="Wo wird die Flagge aufgepflanzt?",a="Pflanzt das Banner im Krallenbau auf, einem Höhlenheiligtum an den Westhängen des Steinkrallengipfels im Steinkrallengebirge.",al={"wo die flagge aufpflanzen","standort der flagge","flaggenplatz im krallenbau"}},{q="Wer ist Rynthariel?",a="Rynthariel ist eine Dryade und Schlüsselmeister des Krallenbaus. Sie schickt Boten ins Gebiet der Horde, bis Kadrak ihre Nachrichten abfängt und ihren Tod befiehlt.",al={"rynthariel dryade","wer ist rynthariel","schlüsselmeister"}}},fx={["555b344d"]={q="Was ist Kadraks Flagge?",a="Kadraks Flagge ist ein Emblem der Horde, das Euch vom Orc-Außenpostenkommandanten Kadrak an der Grenze zwischen dem Brachland und dem Eschental anvertraut wurde. Mit den Farben und dem Siegel der Horde versehen, dient sie als unmissverständliche Gebietsmarkierung, um Land zu beanspruchen und eine kompromisslose Botschaft des Trotz an die Streitkräfte der Allianz zu senden, die sich in den Süden wagen.",al={"was ist kadraks flagge","kadraks flagge","über kadraks flagge"}},["52bd9818"]={q="Warum möchte Kadrak, dass seine Flagge im Krallenbau aufgestellt wird?",a="Kadrak möchte, dass das Banner direkt in das Herz des Krallenbaus auf dem Steinkrallengipfel gerammt wird, nachdem die Dryadenanführerin Rynthariel erschlagen wurde. Das Aufstellen des Banners der Horde in ihrem Heiligtum stellt sicher, dass alle überlebenden Späher oder Allianz-Sympathisanten verstehen, dass das Eindringen in das Gebiet der Horde mit entschlossener, tödlicher Vergeltung beantwortet wird.",al={"warum kadraks flagge aufstellen","warum möchte kadrak die flagge platzieren","zweck des flaggenaufstellens"}}},fp="13,140,18.386.0,31.202.0,23.145.0,26.127.0,18.161.0"}
P.entries["item:keg-of-shindigger-stout"] = {n="Fässchen Kniegräberstarkbier",s="In Dun Garok füllt Kniegräberstarkbier die Fässer der Zwerge und weckt Interesse in Tarrens Mühle. Die Königliche Apothekervereinigung begehrt das Bier für einen finstereren Zweck als den bloßen Genuss.",h="In Dun Garok füllt Kniegräberstarkbier die Fässer der Zwerge und weckt Interesse in Tarrens Mühle.",kw={"apotheker lydon","dun garok","zwergenbier","elixir of agony","fässchen kniegräberstarkbier","kniegräberstarkbier","tarrens mühle"},ang={["faction:Horde"]="Als Angehörige der Horde könnt Ihr Dun Garok angreifen, einen militärischen Stützpunkt der Allianz in den südöstlichen Hügeln des Vorgebirges des Hügellands.",["race:Undead"]="Als Verlassene könnt Ihr mit Alkohol den Geruch und Geschmack tödlicher Mixturen verbergen, die für Lady Sylvanas hergestellt werden."},sec={{t="Ein Lieblingsbier der Zwerge",b="Zwerge aus Eisenschmiede halten Dun Garok im südöstlichen Vorgebirge des Hügellands. In den Kasernen und Speisesälen teilen die Verteidiger Kniegräberstarkbier während der Kälte und der Belagerung durch ihre regionalen Feinde. Das Gebräu gehört zum Alltag der Garnison."},{t="Apotheker Lydons Giftgefäß",b="Apotheker Lydon in Tarrens Mühle sucht ein unversehrtes Fässchen Kniegräberstarkbier für das Elixir of Agony der Verlassenen. Er weigert sich, die Formel an Tieren zu testen. Stattdessen plant er, das Bier für gefangene menschliche Bauern in Tarrens Mühle zu vergiften."}},faq={{q="Wofür wird Kniegräberstarkbier verwendet?",a="Apotheker Lydon in Tarrens Mühle will Kniegräberstarkbier für das Elixir of Agony. Er plant, das Bier mit Gift zu versetzen und an humanoiden Versuchspersonen zu testen.",al={"warum kniegräberstarkbier beschaffen","zweck von kniegräberstarkbier","was macht lydon mit dem fässchen"}},{q="Wo ist ein Fässchen Kniegräberstarkbier zu finden?",a="Die Zwerge bewahren Fässer mit Kniegräberstarkbier in Dun Garok im südöstlichen Vorgebirge des Hügellands auf. Sie lagern sie in den Speisesälen und unteren Kasernen der Festung.",al={"fundort des fässchens","wo ist kniegräberstarkbier","starkbier finden"}},{q="Wer braut Kniegräberstarkbier?",a="Die Zwerge von Dun Garok brauen und lagern Kniegräberstarkbier. Sie halten für Eisenschmiede eine befestigte Garnison im Vorgebirge des Hügellands.",al={"wer braut kniegräberstarkbier","ist es zwergenbier"}},{q="Warum braut Apotheker Lydon seinen Alkohol für den Versuch nicht selbst?",a="Lydon verlangt für sein Experiment ein Fässchen, das in Dun Garok lagert. Der Bericht nennt keinen weiteren Grund und sagt nichts darüber, dass er selbst Alkohol braut.",al={"warum zwergenbier stehlen","warum bier aus dun garok"}}},fx={b55cb0ca={q="Was ist ein Fässchen Kniegräberstarkbier?",a="Ein Fässchen Kniegräberstarkbier ist ein Fass mit starkem Zwergenbier, das von den Zwergen aus Eisenschmiede in der Festung Dun Garok aufbewahrt wird. Obwohl es dazu gedacht war, die Zwergensoldaten während ihres Einsatzes im Vorgebirge des Hügellands zu versorgen, macht sein starkes Gebräu es zu einem hervorragenden Medium für Apotheker Lydons Experimente im Auftrag der Königlichen Apothekervereinigung.",al={"was ist ein fässchen kniegräberstarkbier","infos zum kniegräberstarkbier","was ist kniegräberstarkbier"}}},fp="23,169,18.253.0,32.234.1,34.150.0,45.163.0,27.125.0,63.144.0"}
P.entries["item:ken-zigla-s-draught"] = {n="Ken'ziglas Trunk",s="Im Steinkrallengebirge bereitet Ken'zigla einen bitteren Trunk für Schwerverwundete zu. Eine halbe Dosis kann genug Kraft zurückgeben, um sich zu bewegen, doch mehr kann einen Patienten verbluten lassen.",h="Im Steinkrallengebirge bereitet Ken'zigla einen bitteren Trunk für Schwerverwundete zu.",kw={"camp taurajo","dogran","grunzer logmar","ken'ziglas trunk","ken'zigla","steinkrallengebirge","sukkubusquest","brachland"},ang={["class:Warlock"]="Als Hexenmeister müsst Ihr während Eurer Prüfungen zur Beschwörung und Bindung eines Sukkubus den Trunk finden und überbringen. Die Reise durch das Brachland stellt Euren Einfallsreichtum und Eure Fähigkeiten im Spurenlesen auf die Probe.",["faction:Horde"]="Da Camp Taurajo wegen Patrouillen zur Nahrungssuche unterbesetzt ist, bleibt der Trunk die einzige Lebensader für einen Agenten, der hinter den feindlichen Linien der Borstennacken gefangen wurde."},sec={{t="Ein bitteres Heilmittel",b="Ken'zigla bereitet den Trunk im Steinkrallengebirge für jene zu, die dem Tode nahe sind. Seine Stärke verlangt Vorsicht. Mehr als eine halbe Dosis auf einmal kann einen Patienten verbluten lassen, wenn sein Kreislauf hochschnellt. Eine halbe Dosis gibt einem Verwundeten genug Kraft, um sich zu bewegen und der Gefahr zu entfliehen. Der Rest muss warten, bis sich der Körper nach einer vollen Nacht der Ruhe stabilisiert hat."},{t="Gnade im Brachland",b="Hexenmeister der Horde bringen den Trunk in ein feindliches Lager der Borstennacken nördlich von Camp Taurajo, wo Dogran gefangen gehalten wird. Der Agent wurde von Borstennacken gefangen genommen und gefoltert. Die Medizin gibt ihm genug Lebenskraft, um davonzuhumpeln, obwohl seine schweren Wunden ihn dauerhaft den Gebrauch seiner Gliedmaßen gekostet haben."}},faq={{q="Wofür wird Ken'ziglas Trunk verwendet?",a="Ken'ziglas Trunk gibt Sterbenden oder Schwerverletzten Kraft zurück. Vorsichtig verabreicht kann er einem Verwundeten helfen, sich zu bewegen und der Gefangenschaft zu entkommen, ohne zu verbluten.",al={"was bewirkt ken'ziglas trunk","zweck des trunks","warum wird ken'ziglas trunk benötigt"}},{q="Wer stellt den Trunk her?",a="Ken'zigla bereitet den Trunk im Steinkrallengebirge zu.",al={"wer braut den trunk","wer ist ken'zigla","ken'ziglas aufenthaltsort"}},{q="Warum darf der Trunk nur in halben Dosen eingenommen werden?",a="Der Trunk belastet den Körper außergewöhnlich stark. Eine halbe Dosis gibt genug Kraft, um sich zu bewegen, ohne schwere Blutungen auszulösen. Die andere Hälfte muss warten, bis der Patient eine Nacht geruht hat, um eine tödliche Überlastung zu vermeiden.",al={"ken'ziglas trunk einnehmen","halbe dosis trunk","anweisungen zum trunk"}},{q="Wer erhält den Trunk?",a="Dogran erhält den Trunk. Er ist ein Agent, der schwer verletzt in einem Lager der Borstennacken nördlich von Camp Taurajo im Brachland gefangen gehalten wird.",al={"wer trinkt den trunk","wer ist dogran","wohin den trunk bringen"}},{q="Warum werden Hexenmeister ausgesandt, um diese Medizin zu beschaffen?",a="Hexenmeister der Horde, die einen Sukkubus binden wollen, werden zu Dogran geführt, der einen Gegenstand von tiefer emotionaler Bedeutung besitzt. Die Übergabe des Trunks hilft ihnen, ihn zu erreichen und sich zu beschaffen, was sie für das Beschwörungsritual brauchen.",al={"warum brauchen hexenmeister den trunk","sukkubusquest trunk","hexenmeisterquest ken'zigla"}}},fx={["6eadaa9a"]={q="Was ist Ken'ziglas Trunk?",a="Es ist ein wirksames, übel schmeckendes medizinisches Gebräu, das von dem Troll-Apotheker Ken'zigla im Steinkrallengebirge zubereitet wird. Das Gebräu wurde entwickelt, um schwere Traumata zu unterstützen, und ist mächtig genug, um die Lebenskraft eines tödlich verwundeten Soldaten wiederherzustellen und ihm zu ermöglichen, sich zu bewegen, obwohl es mit großer Vorsicht verabreicht werden muss.",al={"was ist der trunk","kenziglas trunk","kenzigla trank"}},["42d17912"]={q="Warum wird Ken'ziglas Trunk benötigt?",a="Ein Orc namens Dogran wurde von Stachelebern im Brachland gefangen genommen und brutal gefoltert. Da er in Gefangenschaft verblutet und dem Tod nahe ist, kann er ohne die wiederherstellende Magie des Trunks nicht überleben oder entkommen. Grunzer Logmar in Camp Taurajo benötigt das Heilmittel dringend, damit Dogran seinen Verletzungen lange genug standhalten kann, um seinen Entführern zu entkommen.",al={"warum benötigen sie den trunk","wer braucht kenziglas trunk","warum den trunk herstellen"}}},fp="19,177,15.340.0,20.294.1,37.180.0,22.59.0,50.208.0,25.136.0,48.207.0"}
P.entries["item:khazgorm-s-journal"] = {n="Khazgorms Tagebuch",s="Bei Bael Modan leitet Prospector Khazgorm Eisenschmiedes Ausgrabung im südlichen Brachland. Sein Tagebuch dokumentiert die Arbeit der Explorers' League auf Land, das die Stonespire-Tauren beanspruchen.",h="Bei Bael Modan leitet Prospector Khazgorm Eisenschmiedes Ausgrabung im südlichen Brachland.",kw={"bael modan","brachland","zwerg","explorers' league","gann steinkeil","tagebuch","khazgorm","prospector"},ang={["faction:Horde"]="Als Mitglied der Horde könnt Ihr Gann Steinkeil helfen, Kalimdor gegen Expeditionen der Allianz zu verteidigen, die in das Gebiet der Horde vordringen.",["race:Tauren"]="Als Tauren könnt Ihr das Tagebuch als Beweis dafür lesen, wie die Eindringlinge aus Eisenschmiede den Stamm der Stonespire missachten, während sie dessen angestammtes Land sprengen."},sec={{t="Ein Zeugnis der Zerstörung",b="Prospector Khazgorm leitet den Maschineneinsatz und die Sprengungen, die sich in die Hänge des südlichen Brachlands graben. Die Ausgrabung hat sich weit von der versprochenen Suche der Explorers' League nach Wissen entfernt. Ihre Arbeiten haben den Stamm der Stonespire vertrieben. Die Tauren strebten eine friedliche Einigung an, doch die Zwerge lehnten ab. Gann Steinkeil will durch das Tagebuch erfahren, warum Eisenschmiede in seiner Heimat ist und wie er die Expedition vertreiben kann."},{t="Ein Wechsel der Taktik",b="Gann Steinkeil findet das Tagebuch bei Khazgorms sterblichen Überresten nahe den Zelten und Pfeilern der Ausgrabungsstätte. Seine Aufzeichnungen verraten, wie die Expedition organisiert ist, welche Ausrüstung sie nutzt und wo sie verwundbar ist. Mit diesem Wissen geht Gann dazu über, die Maschinen der Ausgrabung anzugreifen, nachdem er zuvor Arbeiter vertrieben hat. Das Tagebuch verändert den Kampf um Bael Modan."}},faq={{q="Wem gehört das Tagebuch?",a="Prospector Khazgorm, einer der Leiter der zwergischen Ausgrabung aus Eisenschmiede bei Bael Modan im südlichen Brachland, besitzt das Tagebuch.",al={"wem gehört das tagebuch","khazgorm","prospector khazgorm"}},{q="Warum will Gann Steinkeil dieses Buch?",a="Gann Steinkeil will das Tagebuch, um die Pläne und Geheimnisse der Zwerge zu studieren, nachdem sie seinen Stamm vertrieben haben. Khazgorms Aufzeichnungen helfen ihm, weitere Angriffe auf das Lager bei Bael Modan zu planen.",al={"warum gann das tagebuch will","gann quest tagebuch","ganns reclamation buch"}},{q="Wo ist das Tagebuch zu finden?",a="Prospector Khazgorm trägt das Tagebuch zwischen den Zelten und Felspfeilern der aktiven Ausgrabung unmittelbar südlich von Bael Modan bei sich.",al={"wo ist khazgorms tagebuch","khazgorms tagebuch finden","khazgorm aufenthaltsort"}},{q="Was verrät das Tagebuch über die Zwerge?",a="Das Tagebuch zeigt, dass die Suche der Explorers' League nach vergrabenen Relikten und dem Erbe der Titanen unmittelbar und gewaltsam auf Kosten von Stämmen wie den Stonespire-Tauren geht.",al={"explorers' league brachland","geheimnisse der zwergenausgrabung","zweck von bael modan"}}},fx={["6ed76dba"]={q="Woher stammt Khazgorms Tagebuch und wer hat es verfasst?",a="Das Tagebuch wurde von Prospektor Khazgorm geschrieben, einem Anführer unter den Zwergen-Ausgräbern der Forscherliga, die in Bael Modan im südlichen Brachland stationiert sind. Khazgorm führte das Buch, um die Ergebnisse seiner Expedition und seine täglichen Angelegenheiten aufzuzeichnen, während er durch die angestammten Ländereien der Steinkrallen-Tauren wühlte.",al={"ursprung von khazgorms tagebuch","wer schrieb khazgorms tagebuch","woher stammt khazgorms tagebuch"}}},fp="18,180,23.415.0,18.357.1,31.122.0,40.187.0,31.123.0,47.163.0"}
P.entries["item:klaven-mortwake-s-journal"] = {n="Klaven Jagdrufs Tagebuch",s="Agenten des SI:7 bergen Klaven Jagdrufs Tagebuch aus dem Defiasturm. Es dokumentiert die Suche der Bruderschaft nach einem Weg, die Toten zu erwecken.",h="Agenten des SI:7 bergen Klaven Jagdrufs Tagebuch aus dem Defiasturm.",kw={"defiasturm","dämmerwaldtruhe","tagebuch","klaven mortwake","mathias shaw","gifte","si:7","zanzil"},ang={["class:Rogue"]="Als Schurke beweist Ihr Euer Geschick im Schlösserknacken und Schleichen, indem Ihr den Turm betretet und Mortwakes Tagebuch an Euch nehmt. Die Arbeit führt Euch auch in das Brauen tödlicher Gifte ein.",["faction:Alliance"]="Als Mitglied der Allianz liefert Ihr Sturmwinds Spionagemeistern Beweise dafür, dass der Aufstand der Defias über unzufriedene Arbeiter hinausreicht. Das Tagebuch enthüllt Verbindungen zu Trollhexendoktoren und alchemistischer Nekromantie."},sec={{t="Eine grausige Formel",b="Der Defiasturm steht auf den Höhenzügen im nördlichen Westfall. Seltsame Lieferungen treffen von den schattenhaften Grenzen des Dämmerwalds ein, und entstellte, nichtmenschliche Wachposten bewachen den Turm. Der SI:7 beobachtete den Ort lange Zeit. In der obersten Truhe fanden die Agenten Klaven Jagdrufs Tagebuch und erfuhren, was die Lieferungen enthielten.\n\nKlaven Mortwake hielt Forschungen über alchemistische Wege fest, geistlose untote Drohnen zu erwecken. Mit den Zanziltrollen in Schlingendorntal verbundene Alchemisten hatten mithilfe spezieller Gifte und Gebräue einen Weg gefunden. Die Bruderschaft der Defias wollte ihre Methode für die eigenen Reihen nachahmen."},{t="Erkenntnisse für den SI:7",b="Meister Mathias Shaw leitet Sturmwinds Geheimdienst, den SI:7. Er suchte Mortwakes Tagebuch, um den weitreichenden Bündnissen der Bruderschaft nachzugehen. Die Notizen bestätigen Experimente zur Wiederbelebung und unerlaubte Unterstützung, die den Dämmerwald, die Venture Company und die Defias miteinander verbindet. Für Schurken im Dienste der Krone ist die Bergung der Forschung ein Schritt zur Beherrschung der Gifte."}},faq={{q="Was ist Klaven Jagdrufs Tagebuch?",a="Klaven Jagdrufs Tagebuch ist ein Forschungsheft, verfasst von Klaven Mortwake, einem Agenten im Defiasturm im nordöstlichen Westfall. Es enthält Notizen über alchemistische Nekromantie und unerlaubte Versorgungswege.",al={"was ist klavens tagebuch","mortwakes tagebuch","was ist dieser gegenstand"}},{q="Wo ist das Tagebuch zu finden?",a="Das Tagebuch liegt verschlossen in einer Dämmerwaldtruhe im obersten Stockwerk des Defiasturms im nördlichen Westfall. Untote Wachposten bewachen es, und ein Schlüssel von einem von Klavens monströsen Wächtern öffnet die Truhe.",al={"wo klavens tagebuch finden","klavens tagebuch fundort","dämmerwaldtruhe fundort"}},{q="Welche Geheimnisse stehen im Tagebuch?",a="Das Tagebuch hält fest, dass die Zanziltrolle im Schlingendorntal giftige Tränke entwickelten, mit denen sich Tote erwecken und kontrollieren lassen. Die Bruderschaft der Defias versuchte, das Rezept zu beschaffen und anzuwenden.",al={"was steht im tagebuch","tagebuch geheimnisse","zanzil gift"}},{q="Wer will dieses Tagebuch?",a="Meister Mathias Shaw, Leiter von Sturmwinds Geheimdienst SI:7, will das Tagebuch, um die Logistik der Defias zu überwachen und Agenten der Krone die Gefahren und Einsatzmöglichkeiten taktischer Gifte zu vermitteln.",al={"wer gibt klavens tagebuch ab","wem das tagebuch geben","mathias shaw tagebuch"}}},fx={["887d3337"]={q="Woher stammt Klaven Jagdrufs Tagebuch und wer hat es verfasst?",a="Das Tagebuch gehört Klaven Jagdruf, der die Festung der Defias-Bruderschaft am Turm in Westfall beaufsichtigte. Es wurde zusammen mit finsteren untoten Wachen und einer Truhe aus dem Dämmerwald verschickt und detaillierte dunkle alchemistische Geheimnisse, die von den Trollen des Verbannten Zanzil im Schlingendorntal stammten.",al={"wer schrieb klavens tagebuch","ursprung von klaven jagdrufs tagebuch","woher hat klaven das tagebuch"}}},fp="25,137,18.586.1,21.348.0,34.203.0,27.201.0,44.188.0,23.183.0"}
P.entries["item:kodo-horn"] = {n="Kodohorn",s="Im ganzen Brachland werden Kodohörner für Tonga Runentotems Heilmittel gesammelt. Er behandelt damit vergiftete Wildtiere.",h="Im ganzen Brachland werden Kodohörner für Tonga Runentotems Heilmittel gesammelt.",kw={"brachland","cenarion","earthroot","gazelle","kodohorn","gift","tonga runentotem"},ang={["class:Druid"]="Als Druide der Horde sammelt Ihr unter Tonga Runentotems Anleitung Hörner, während Ihr lernt, die Gifte der Natur zu beherrschen.",["race:Tauren"]="Als Tauren verehrt Ihr Kodos zutiefst. Ihr nehmt mit Bedacht und einem klaren Ziel von ihnen, um das empfindliche Ökosystem des Brachlands zu schützen."},sec={{t="Ein Reagenz der Ebenen",b="Im ganzen Brachland verwendet Tonga Runentotem ganze Kodohörner für seine pflanzlichen Heilmittel. Er wirkt vom Wegekreuz aus, wo die Hörner seine Salben verstärken. Splittern und Bruchstücken fehlt die nötige Kraft, daher sammelt er intakte Hörner ausgewachsener Kodos, die durch die Ebenen streifen."}},faq={{q="Wofür werden Kodohörner verwendet?",a="Tonga Runentotem braut aus Kodohörnern, Earthroot und reinem Wasser eine Salbe, um vergiftete Gazellen im ganzen Brachland zu behandeln. Das Heilmittel lehrt einen Druiden, wie er mit der Hilfe der Natur Vergiftungen heilt.",al={"zweck von kodohörnern","warum kodohörner sammeln","verwendung von kodohorn"}},{q="Wo werden diese Hörner gesammelt?",a="Ihr könnt Kodohörner von Barrens Kodos und Lost Barrens Kodos im nördlichen Brachland sammeln, zwischen dem Wegekreuz und dem umliegenden Buschland.",al={"wo kodohörner finden","kodohorn fundort","welche kodos hinterlassen hörner"}},{q="Warum können Druiden stattdessen keine Hornbruchstücke verwenden?",a="Tonga Runentotem sagt, dass Splittern und Bruchstücken die nötige Wirkkraft fehlt, um die Salbe ins Gleichgewicht zu bringen. Er braucht intakte Hörner für ein Heilmittel, das stark genug ist, um hochwirksamen Giften entgegenzuwirken.",al={"warum keine zerbrochenen hörner","hornsplitter"}},{q="Gilt die Jagd auf Kodos für einen Druiden als respektvoll?",a="Ja. Druiden jagen Kodos, um dem Gleichgewicht der Natur zu dienen, und nehmen, was sie brauchen, um größeres Unheil zu heilen, etwa die rätselhaften Vergiftungen, die die heimischen Gazellenherden heimsuchen.",al={"druiden jagen kodos","gleichgewicht und kodos"}}},fx={f5876d60={q="Was ist ein Kodohorn?",a="Es ist ein intaktes Horn, das von den massiven Kodos geerntet wird, die durch die nördlichen Savannen des Brachlands streifen. Während ganze und robuste Hörner oft in Stammeshandwerk oder Werkzeugen verwendet werden, sind sie bei Schamanen und Druiden als wirksame alchemistische Reagenzien begehrt, die medizinische Mischungen mit starker natürlicher Widerstandsfähigkeit anreichern können.",al={"was ist ein kodohorn","kodohorn","über das kodohorn"}},["062d3e91"]={q="Woher kommen Kodohörner?",a="Diese Hörner stammen direkt von den Kodos des Brachlands, die über die trockenen Ebenen grasen. Wenn Jäger und Druiden eines dieser beeindruckenden Tiere erlegen, können sie ein intaktes Horn erlangen, vorausgesetzt, es wurde nicht zerschlagen oder zu bloßen Splittern und Fragmenten abgenutzt.",al={"woher kommt ein kodohorn","ursprung eines kodohorns","wie erhält man ein kodohorn"}}},fp="9,116,23.263.0,29.184.0,32.146.0,44.156.0,51.166.0"}
P.entries["item:kodo-liver"] = {n="Kodoleber",s="In Ratschet braucht Braumeister Drohn Kodoleber für ein seltsames Ale. Der wandernde Braumeister Chen Stormstout brachte ihm bei, es zu brauen.",h="In Ratschet braucht Braumeister Drohn Kodoleber für ein seltsames Ale.",kw={"brachland","brauen","chen stormstout","drohn","kodo","kodoleber","ratschet","trogg-ale"},ang={["profession:Cooking"]="Kodofleisch ernährt Menschen im gesamten zentralen Kalimdor, doch Kodoleber gilt als zu widerlich und streng riechend für die gewöhnliche Küche. Ihre Verwendung im Trogg-Ale von Ratschet hat sie berüchtigt gemacht.",["race:Tauren"]="Tauren ehren jeden Teil der Kodos, die sie jagen. Selbst erfahrene Steppenläufer betrachten Goblins und Fremde mit Argwohn, die in Ratschet aus Kodoinnereien neuartiges Ale brauen."},sec={{t="Eine bizarre Brauzutat",b="Kodos streifen durch das Brachland, wo Tauren und Raubtiere sie wegen ihrer Häute und ihres Fleisches jagen. In Ratschet mischt Braumeister Drohn eine frische Kodoleber mit Speicheldrüsen von Donnerfalken und Blitzdrüsen, um Trogg-Ale zu brauen. Chen Stormstout brachte ihm das Rezept bei, und Drohn sagt, das Gebräu habe für abenteuerlustige Reisende eine kräftige Durchschlagskraft. Seine Zutaten stammen aus der Wildnis des zentralen Kalimdor."}},faq={{q="Wofür wird eine Kodoleber verwendet?",a="Braumeister Drohn in Ratschet verwendet Kodoleber, um Trogg-Ale zu brauen. Chen Stormstout brachte ihm das Rezept bei.",al={"kodoleber verwendung","warum kodoleber benötigt wird","wofür ist kodoleber"}},{q="Von welchen Kreaturen lässt sich Kodoleber erbeuten?",a="Von Kodos im Brachland lässt sich Kodoleber erbeuten. Dazu zählen gewöhnliche, wollige, verirrte und große Kodos sowie Lakota'mani und Brontus.",al={"woher bekommt man kodoleber","wer lässt kodoleber fallen","kodoleber herkunft"}},{q="Warum sollte jemand Tierorgane in Ale geben?",a="Braumeister Drohn folgt den ungewöhnlichen Rezepten, die Chen Stormstout ihm beigebracht hat. Rohe Organe wie Kodoleber und elementare Drüsen verleihen Trogg-Ale seine Durchschlagskraft und seinen scharfen Geschmack.",al={"warum leber im bier","kodoleber in alkohol"}}},fx={a4c717e9={q="Was ist eine Kodoleber?",a="Es ist ein inneres Organ, das von den massiven, dickhäutigen Kodos geerntet wird, die durch die Ebenen des Brachlands streifen. Obwohl es kein typisches Tavernengericht ist, macht seine wirksame Natur es zu einer geschätzten Zutat für exzentrische Braumeister, die Gebräue mit einer wahrhaft legendären Note herstellen.",al={"was ist eine kodoleber","hintergrund zur kodoleber","kodoleber"}},c325e464={q="Woher stammt eine Kodoleber?",a="Sie wird direkt von den wilden Kodos gesammelt, die durch die Savanne des Brachlands streifen, von gewöhnlichen wandernden Tieren bis hin zu uralten Behemoths wie Lakota'mani und Brontus. Jäger und Abenteurer schneiden sie heraus, nachdem sie die massiven Kreaturen erlegt haben.",al={"woher bekommt man eine kodoleber","wer lässt eine kodoleber fallen","quelle einer kodoleber"}},["328036a8"]={q="Warum möchte Braumeister Drohn eine Kodoleber?",a="Braumeister Drohn in Ratschet sucht eine frische Leber, um ein ungewöhnliches Trogg-Bier-Rezept zu brauen, das ihm der wandernde Pandaren-Braumeister Chen Stormstout beigebracht hat. Zusammen mit Blitzdrüsen und Donnerfalkenspeichel verleiht die Leber dem starken Getränk seine unverwechselbare Note.",al={"warum braucht drohn eine kodoleber","wer will eine kodoleber","nutzung der kodoleber quest"}}},fp="10,128,25.371.0,30.101.0,35.127.0,42.165.0"}
P.entries["item:kodobane-s-head"] = {n="Kodobanns Kopf",s="Nahe den Vergessenen Teichen beweist Barak Kodobanes abgetrennter Kopf, dass der Häuptling tot ist. Regthar Totenfurt erhält ihn als Beweis dafür, dass die Bedrohung durch die Zentauren dort gebrochen wurde.",h="Nahe den Vergessenen Teichen beweist Barak Kodobanes abgetrennter Kopf, dass der Häuptling tot ist.",kw={"barak","brachland","zentaur","das wegekreuz","deathgate","die vergessenen teiche","kodobane","kolkar","regthar"},ang={["faction:Horde"]="Die Wegkreuzungen des Brachlands verbinden Orgrimmar und Donnerfels auf dem Landweg. Anführer der Zentauren wie Kodobane niederzuhalten hilft, die Karawanenwege zu sichern.",["race:Tauren"]="Über Generationen trieben die Zentauren die nomadischen Tauren in ganz Kalimdor an den Rand der Ausrottung. Barak Kodobane zu töten rächt Jahrhunderte des Blutvergießens und schützt die Weidegründe von Mulgore und dem Brachland."},sec={{t="Eine Kriegstrophäe",b="Die Banden der Kolkar im Brachland sind seit Langem zerstritten. Nun drohen ehrgeizige Kriegsfürsten, sie zu einer Armee zu vereinen. Barak Kodobane lagert an den Gewässern der Vergessenen Teiche, wo die Oase lebenswichtige Ressourcen bietet und nahe gelegene Wege Überfällen schutzlos ausgeliefert sind. Regthar Totenfurt ist in einem Bunker westlich vom Wegekreuz stationiert. Er verlangt Kodobanes abgetrennten Kopf als Beweis dafür, dass der Befehlshaber seine Sippe nicht länger gegen die Horde sammeln kann."}},faq={{q="Wer war Barak Kodobane?",a="Barak Kodobane ist ein bedeutender Häuptling unter den Kolkarzentauren. Wo viele seiner Sippe undiszipliniert sind, organisiert er mit List und Führungsstärke Kriegsbanden und Lager rund um die Vergessenen Teiche, um die Vorherrschaft der Kolkar über das nördliche Brachland zu sichern.",al={"barak kodobane","wer ist kodobane","baraks geschichte"}},{q="Warum will Regthar Totenfurt seinen Kopf?",a="Regthar Totenfurt hat den Auftrag, das Gebiet der Horde im Brachland zu sichern. Die Zentauren sind gewöhnlich zerstritten, weshalb Anführer mit taktischem Weitblick Aufmerksamkeit erregen. Regthar verlangt Kodobanes Kopf, um sicherzugehen, dass der Häuptling tot ist und nicht bloß vertrieben wurde.",al={"warum den kopf holen","regthar deathgate kopf","kopfgeld auf kodobane"}},{q="Wo ist Barak Kodobane zu finden?",a="Barak Kodobane lagert nahe den Vergessenen Teichen, der nördlichen Oase unmittelbar nordwestlich vom Wegekreuz im Brachland.",al={"baraks standort","wo ist kodobane","baraks erscheinungsort"}},{q="Endet mit Baraks Tod die Bedrohung durch die Kolkar?",a="Nein. Barak Kodobane ist der erste von mehreren Kriegsfürsten, die die Kolkar um sich scharen. Sein Tod schwächt ihre Präsenz an den Vergessenen Teichen, doch Verog the Dervish und Hezrul Bloodmark lenken weiterhin die Angriffe der Zentauren im gesamten Brachland.",al={"sind die zentauren besiegt","was geschieht nach baraks tod"}}},fx={["891c4b09"]={q="Was ist Kodobanns Kopf?",a="Es ist der abgetrennte Kopf von Barak Kodobann, einem der bedeutenden Häuptlinge der Kolkarzentaren im Brachland. Als physischer Beweis für das Ableben des Häuptlings aufbewahrt, bedeutet er einen entscheidenden Schlag gegen die koordinierte Zentarenbedrohung, die die Siedlungen der Horde in der Nähe von The Forgotten Pools bedroht.",al={"was ist kodobanns kopf","barak kodobann kopf gegenstand","baraks kopf hintergrundgeschichte"}}},fp="15,171,15.418.0,23.242.0,41.246.0,30.114.0,42.231.0"}
P.entries["item:kravel-s-crate"] = {n="Kravels Kiste",s="An der Illusionenrennbahn hat Kravel Kohlebart eine Kiste für die Nesingwary-Expedition im Schlingendorntal zu verschicken. Sie enthält Spezialmunition für die Jagd auf das tödlichste Wild des Dschungels.",h="An der Illusionenrennbahn hat Kravel Kohlebart eine Kiste für die Nesingwary-Expedition im Schlingendorntal...",kw={"munition","hemet nesingwary","kravel kohlebart","kravels kiste","illusionenrennbahn","die schimmernde ebene","schlingendorntal"},ang={["class:Hunter"]="Als Jäger findet Ihr schwere Spezialmunition in der Kiste. Sie ist für hochwertige zwergische Jagdgewehre und Großwildexpeditionen gefertigt.",["race:Dwarf"]="Als Zwerg erkennt Ihr die Verbindung zwischen Kravel Kohlebarts Geschäft in den Salzebenen und der berühmten Nesingwary-Jagdgesellschaft in den Östlichen Königreichen."},sec={{t="Eine Lieferung in den Dschungel",b="An der Illusionenrennbahn übergibt Kravel Kohlebart die Kiste an Reisende. Ein wohlhabender Zwerg hatte sie vor Wochen bestellt, doch die Lieferung verzögerte sich, bis der Käufer Kalimdor bereits verlassen hatte. Der Auftraggeber hatte für die Weiterleitung bezahlt, und Kravel will sich die Gunst eines wohlhabenden Kunden erhalten. Also vertraut er darauf, dass vorbeiziehende Reisende sie über Kontinente hinweg ins nördliche Schlingendorntal bringen."},{t="Munition mit Spezialkaliber",b="Salzstaub sammelt sich auf der Kiste, während sie in der Schimmernden Ebene wartet. Darin liegen schwere Geschosse mit Spezialkaliber, die für Jagdgewehre gefertigt wurden. Die Reisenden liefern sie im Expeditionslager nördlich von Grom'gol ab. Der Empfänger sagt, dass Großwildjäger die durchschlagskräftige Munition schätzen. Gegen die Raubtiere, die das Blätterdach des Dschungels durchstreifen, ist sie überlebenswichtig."}},faq={{q="Was ist in Kravels Kiste?",a="Kravels Kiste enthält schwere Munition mit Spezialkaliber für Jagdgewehre. Großwildjäger setzen sie gegen gefährliche Bestien in der Wildnis ein.",al={"was ist in der kiste","kisteninhalt","was ist in kravels kiste"}},{q="Wer hat Kravels Kiste verschickt?",a="Kravel Kohlebart hat die Kiste verschickt. Er ist ein zwergischer Händler an der Illusionenrennbahn, inmitten von Rennen und Glücksspiel in der Schimmernden Ebene in Tausend Nadeln.",al={"wer übergibt die kiste","wem gehört kravels kiste"}},{q="Wohin muss diese Kiste gebracht werden?",a="Die Kiste ist für das Lager der Nesingwary-Jagdexpedition im nördlichen Schlingendorntal bestimmt. Das Lager liegt am Fluss nördlich des Basislagers Grom'gol.",al={"wohin die kiste liefern","ziel der kiste","wer bekommt kravels kiste"}},{q="Warum hat sich die Lieferung verzögert?",a="Das Paket brauchte Wochen, um die Salzebenen von Tausend Nadeln zu erreichen. Inzwischen hatte der Kunde seine Sachen gepackt und war in den Dschungel des Schlingendorntals aufgebrochen.",al={"warum hat kravel so lange gebraucht","warum verzögert"}}},fx={["3beca7b7"]={q="Was ist Kravels Kiste?",a="Es handelt sich um ein schweres Lieferpaket, das von Kravel Kohlebart auf der Illusionenrennbahn in der schimmernden Ebene gehalten wird. Sicher für den Ferntransport über Kalimdor und das große Meer verpackt, enthält die Kiste spezielle Jagdausrüstung, die für eine Expedition in die Wildnis des Schlingendorntals bestimmt ist.",al={"was ist kravels kiste","kravels kiste info","kravels kiste gegenstand"}},["6061fde3"]={q="Warum ist Kravels Kiste gefragt?",a="Die Kiste enthält Munition mit Spezialkaliber, die speziell für die Großwildjagd bestellt wurde. Die Nesingwary-Jagdexpedition im Schlingendorntal ist auf schwere, zuverlässige Munition angewiesen, um die wildesten Bestien des Dschungels zu erlegen, was diese verspätete Lieferung zu einer wichtigen Nachschubquelle für ihr Lager macht.",al={"warum will nesingwary die kiste","warum ist kravels kiste wichtig","zweck von kravels kiste"}}},fp="14,186,24.367.0,24.340.0,30.134.0,24.154.0,33.152.0,29.147.0"}
P.entries["item:kreenig-snarlsnout-s-tusk"] = {n="Kreenig Grantelschnauzes Hauer",s="Am Wegekreuz erwartet Thork den Beweis, dass Kreenig Grantelschnauze gefallen ist. Der Hauer markiert das Ende der Angriffe des Razormane-Anführers auf Karawanen der Horde im nördlichen Brachland.",h="Am Wegekreuz erwartet Thork den Beweis, dass Kreenig Grantelschnauze gefallen ist.",kw={"brachland","das wegekreuz","kreenig","stacheleber","razormane","grantelschnauze","thork","hauer"},ang={["faction:Horde"]="Karawanen bringen Waffen, Vorräte und Siedler aus Durotar und sichern so die Ausbreitung der Horde ins Brachland. Wenn Ihr Thork diesen Hauer bringt, helft Ihr, diese Lebensadern zu schützen.",["race:Orc"]="Für einen Orc vom Wegekreuz gehört es zur zweckmäßigen Kriegsführung, einem besiegten Befehlshaber eine Trophäe abzunehmen. Es zeigt Stärke und sät Panik unter den Feinden."},sec={{t="Eine Trophäe vereitelten Ehrgeizes",b="Karawanen der Horde, die von Durotar nach Westen ziehen, sind im Brachland ständigen Angriffen ausgesetzt. Unter Kreenig Grantelschnauze, einem wilden Anführer der Razormane, wurden diese Überfälle dreister. Deshalb befahl Thork, Kommandant der Wache am Wegekreuz, Kreenig zu töten, um die Koordination der Stacheleber zu stören.\n\nKreenigs Hauer beweist den Tod des Anführers und beleidigt die Razormane. Ihre Entschlossenheit schwindet, und ihre Kämpfer bleiben ohne zentrale Führung zurück."}},faq={{q="Wer war Kreenig Grantelschnauze?",a="Kreenig Grantelschnauze führte die Stacheleber der Razormane an, die nordöstlich des Wegekreuzes lagerten. Er organisierte Angriffe auf Karawanen der Horde entlang der Hauptstraße von Durotar und machte die Nachschubroute bis zu seinem Tod gefährlich.",al={"kreenig grantelschnauze","wer ist kreenig","grantelschnauzes geschichte"}},{q="Warum will Thork ausgerechnet den Hauer?",a="Thork will den Hauer als Beweis für Kreenigs Tod und als Beleidigung für die Razormane. Einem gefallenen Häuptling den Hauer abzunehmen, verletzt ihren Stolz und entmutigt die überlebenden Räuber.",al={"warum der hauer","warum den hauer zu thork bringen","thork hauer"}},{q="Wo wurde dieser Hauer erbeutet?",a="Der Hauer stammt aus Kreenig Grantelschnauzes Lager nordöstlich des Wegekreuzes. Das Lager liegt nahe den Ausläufern der Berge, unmittelbar südlich der Hauptstraße, die von Durotar ins Brachland führt.",al={"wo ist kreenig","woher den hauer bekommen","grantelschnauzes standort"}},{q="Wie wirkt sich Kreenigs Tod auf das Brachland aus?",a="Thork glaubt, dass die Räuber der Razormane ohne Kreenigs Führung ins Wanken geraten werden. Sein Tod stürzt ihre Reihen ins Chaos und dämmt weitere Angriffe auf lebenswichtige Nachschublieferungen ein.",al={"haben die überfälle aufgehört","folgen von kreenigs tod"}}},fx={["4371b9f1"]={q="Was ist Kreenig Grantelschnauzes Hauer?",a="Es ist ein abgetrennter Ebermenschenhauer, der als düstere Trophäe von Kreenig Grantelschnauze, dem Anführer der Klingenhauer-Plünderer nordöstlich des Wegekreuzes, beansprucht wurde. Thork forderte ihn sowohl als unbestreitbaren Beweis für den Tod des Häuptlings als auch, um den Ebermenschen Salz in die Wunde zu streuen und dem verbleibenden Stamm zu zeigen, dass ihr Anführer gefallen ist.",al={"was ist kreenigs hauer","kreenig grantelschnauze hauer gegenstand"}}},fp="25,173,28.413.0,27.207.0,42.176.0,26.185.0,57.174.0"}
P.entries["item:kron-s-amulet"] = {n="Krons Amulett",s="Am Südstrom erinnert Krons Amulett an einen jungen Orcjäger, der verschollen ist.",h="Am Südstrom erinnert Krons Amulett an einen jungen Orcjäger, der verschollen ist.",kw={"amulett","dreadmaw-krokilisk","kron","misha tor'kren","klingenhügel","der südstrom"},ang={["class:Hunter"]="Für einen Jäger ist Krons Schicksal eine eindringliche Lehre über die Gefahr, bösartige Bestien in unbekanntem Flussgebiet zu unterschätzen.",["race:Orc"]="Für einen Orc zeigt Krons Schicksal, wie Stolz und das Streben nach Kriegsruhm dazu verleiten können, die Weisheit der Älteren zu missachten, mit tödlichen Folgen."},sec={{t="Tragödie am Südstrom",b="Kron war ein eigensinniger junger Orc von einem Gehöft nordwestlich von Klingenhügel. Er zog aus, um die bösartigen Dreadmaw-Krokilisken am Südstrom an der Grenze zum Brachland zu jagen. Seine Mutter, Misha Tor'kren, warnte ihn vor der Gefahr, doch sein Stolz trieb ihn weiter. Kron kehrte nie zurück. Sein Amulett wurde im Bauch eines der Raubtiere des Flusses gefunden und bestätigte, dass er getötet und verschlungen worden war. Es gibt Misha schmerzhafte Gewissheit über das Schicksal ihres Sohnes."}},faq={{q="Wer war Kron?",a="Kron war ein eigensinniger junger Orcjäger, der mit seiner Mutter, Misha Tor'kren, auf einem Gehöft nordwestlich von Klingenhügel lebte. Er zog allein aus, um seine Stärke an den Bestien des Flusses zu messen, obwohl er vor ihrer Wildheit gewarnt worden war.",al={"wer ist kron","krons vorgeschichte","krons geschichte"}},{q="Wo findet man Krons Amulett?",a="Dreadmaw-Krokilisken und Corrupted Dreadmaw Crocolisks am Ufer des Südstroms in Durotar tragen Krons Amulett in ihren Bäuchen.",al={"wo das amulett finden","krons amulett fundort","wer lässt krons amulett fallen"}},{q="Wer möchte Krons Amulett zurückhaben?",a="Misha Tor'kren möchte Krons Amulett zurückhaben. Sie wartet auf ihrem Gehöft nordwestlich von Klingenhügel auf Nachricht von ihrem Sohn, und das Amulett gibt ihr schmerzhafte Gewissheit über sein Schicksal.",al={"wer braucht das amulett","wo krons amulett abgeben","misha tor'kren"}}},fx={["5d838632"]={q="Was ist Krons Amulett?",a="Dieses persönliche Schmuckstück gehörte Kron, einem Orc-Jüngling von einem Bauernhof nordwestlich von Klingenhügel. Von Stolz angetrieben und begierig darauf, seine Stärke zu beweisen, machte er sich allein auf den Weg zum Südstrom, um die wilden Dreadmaw-Krokolisken entlang der Grenze des Brachlands zu jagen. Anstatt im Triumph zurückzukehren, fiel er den Bestien zum Opfer, die er erlegen wollte. Zusammen mit seinen Überresten verschluckt, ist dieser Talisman das einzige überlebende Stück des jungen Jägers, das seinen düsteren Tod beweisen kann.",al={"was ist das amulett","krons amulett hintergrundgeschichte","wem gehört das amulett"}}},fp="13,87,24.445.1,13.218.0,29.141.1,33.172.1"}
P.entries["item:kuz-s-skull"] = {n="Kuz' Schädel",s="Im südlichen Brachland zeugt Kuz' Schädel vom Fall einer gefürchteten Räuberin der Borstennacken. Vom Kral der Klingenhauer aus führte Kuz Angriffe auf Außenposten der Horde mit an, bis ein gefangener ehemaliger Artgenosse Rache suchte.",h="Im südlichen Brachland zeugt Kuz' Schädel vom Fall einer gefürchteten Räuberin der Borstennacken.",kw={"brachland","camp taurajo","kuz","kuz' schädel","lok orcbane","quetschzahn","nak","borstennacken"},ang={["faction:Horde"]="Als Mitglied der Horde helft Ihr mit Kuz' Kopf dabei, Siedlungen wie das Wegekreuz und Camp Taurajo vor organisierten Angriffen der Stacheleber zu schützen."},sec={{t="Eine bittere Fehde",b="Kuz, Nak und ihr Häuptling Lok Orcbane führten Angriffe der Borstennacken im gesamten südlichen Brachland an. Vom Kral der Klingenhauer entsandt, überfielen die drei Räuber Reisende und Siedlungen wie das Wegekreuz. Sie verrieten ihren Artgenossen Quetschzahn, einen Stacheleber, und ließen ihn in einem Käfig in Camp Taurajo verrotten. Von dort aus verriet Quetschzahn Kuz' Aufenthaltsort an Champions der Horde, die bereit waren, die Räuberin zu töten und ihren Kopf mitzunehmen."},{t="Beweis der Vergeltung",b="Kuz' Schädel beweist Quetschzahn, dass eine der drei Anführer der südlichen Kriegsschar tot ist. Der Kopf stillt seinen Rachedurst gegen den Stamm, der ihn im Stich gelassen hat. Kuz' Tod zerschlägt die Führung hinter den Angriffen der Borstennacken und verschafft den Nachschubwegen über die Ebenen eine kurze Atempause."}},faq={{q="Wer war Kuz?",a="Kuz war eine von drei Stachelebern der Borstennacken, die vom Kral der Klingenhauer ins südliche Brachland entsandt wurden. Gemeinsam mit Nak und Lok Orcbane leitete sie Hinterhalte und Überfälle auf Lager und Nachschublinien der Horde.",al={"wer ist kuz","kuz geschichte","kuz borstennacken"}},{q="Warum will Quetschzahn Kuz' Schädel?",a="Quetschzahn will Kuz' Schädel, weil Kuz und die anderen Borstennacken ihn in einem Käfig in Camp Taurajo zum Sterben zurückließen. Um noch vor seinem eigenen Tod Rache zu nehmen, weist er Champions der Horde den Weg zu seinen Rivalen und verlangt ihre Schädel als Beweis.",al={"warum quetschzahn kuz tot sehen will","quetschzahn rache"}},{q="Wo im Brachland ist Kuz zu finden?",a="Kuz ist im südlichen Brachland unter den Stachelebern der Borstennacken zu finden, südlich von Camp Taurajo nahe den dornigen Grenzgebieten.",al={"kuz aufenthaltsort","wo kuz zu finden ist"}},{q="Was geschieht, nachdem Kuz getötet wurde?",a="Wenn Kuz' Schädel und die Köpfe von Nak und Lok Orcbane Quetschzahn erreichen, zerschlagen sie die Führung hinter den Angriffen der Borstennacken und helfen, die südlichen Handelswege zu sichern.",al={"kuz questbelohnung","betrayal from within ausgang"}}},fx={["9baef7d0"]={q="Woher stammt Kuz' Schädel?",a="Der Schädel stammt direkt aus den Überresten von Kuz, einer bedeutenden Klingenhauer-Eberfrau, die im südlichen Brachland operierte. Aus dem Kral der Klingenhauer kommend, zusammen mit ihren Mitplünderern, half Kuz dabei, gewaltsame Angriffe gegen die Horde zu organisieren, bevor sie zur Strecke gebracht wurde.",al={"woher stammt kuz' schädel","wer hat kuz' schädel gemacht","ursprung von kuz' schädel"}}},fp="11,189,13.399.0,20.287.1,12.193.0,38.228.0,34.120.0,32.167.0"}
P.entries["item:laced-pumpkin"] = {n="Getränkter Kürbis",s="In Apotheker Johaans Händen erprobt der Getränkte Kürbis die Möglichkeiten der Alchemie der Verlassenen. In Brill sucht die Königliche Apothekervereinigung nach Waffen gegen die Geißel und die Streitkräfte lebender Menschen.",h="In Apotheker Johaans Händen erprobt der Getränkte Kürbis die Möglichkeiten der Alchemie der Verlassenen.",kw={"apotheker johaan","brill","gefangener scharlachroter zelot","zur galgenschlinge","getränkter kürbis","königliche apothekervereinigung","tirisfal"},ang={["faction:Alliance"]="Als Mitglied der Allianz wisst Ihr, dass einen gefangenen Zeloten im Gebiet der Verlassenen ein groteskes Schicksal erwartet. Sein Ende führt schonungslos vor Augen, was lebenden Menschen drohen kann, die lebend gefangen genommen werden.",["race:Undead"]="Als Verlassene wisst Ihr, dass die Königliche Apothekervereinigung jedes Mittel einsetzen wird, um Tirisfal gegen fanatische lebende Kreuzfahrer zu sichern. Gewöhnliche Nahrung in eine Waffe zu verwandeln, zeigt ihren Pragmatismus."},sec={{t="Eine bittere Ernte",b="In Tirisfal wirken Kürbisse wie gewöhnliche Feldfrüchte, die aus verseuchtem Boden geborgen wurden. In Brill behandelt Apotheker Johaan einen davon mit experimentellen Giftstoffen, um das volle Potenzial des Untodes zu erproben. Die Königliche Apothekervereinigung sucht nach Waffen gegen die Geißel im Norden und die aus dem Süden vorrückenden Streitkräfte lebender Menschen. Selbst eine einfache Ernte kann Infektionen und chemischen Tod in sich tragen."},{t="Das Experiment im Keller",b="Im Keller der Taverne Zur Galgenschlinge halten Häscher der Verlassenen einen ausgehungerten Gefangenen Scharlachroten Zeloten fest. Verzweifelt auf Nahrung angewiesen, nimmt der Gefangene eine vergiftete Gabe an. Der Getränkte Kürbis enthält Apotheker Johaans Gebräu. Der Verzehr löst eine gewaltsame Verwandlung aus: Der menschliche Zelot wird zu einem geistlosen Ghul, taumelt kurz unter Qualen und bricht dann tot auf dem kalten Steinboden zusammen."}},faq={{q="Was ist der Getränkte Kürbis?",a="Apotheker Johaan in Brill behandelt einen gewöhnlichen Feldkürbis mit einer experimentellen Rezeptur. Das Gebräu dient dazu, die Wirkung der Alchemie der Verlassenen an lebenden Versuchspersonen zu erproben.",al={"getränkter kürbis","giftkürbis","johaan kürbis"}},{q="Wer isst den Getränkten Kürbis?",a="Häscher der Verlassenen sperren einen Gefangenen Scharlachroten Zeloten im Keller unter der Taverne Zur Galgenschlinge in Brill ein. Nachdem sie ihn haben hungern lassen, isst der Gefangene die vergiftete Gabe.",al={"wer isst ihn","kürbis ziel","kürbis verfüttern"}},{q="Was geschieht, wenn jemand den Kürbis isst?",a="Das Gebräu im Kürbis löst eine gewaltsame Verwandlung aus. Der Gefangene wird zu einem geistlosen Ghul, taumelt kurz unter Qualen und bricht dann tot auf dem kalten Steinboden zusammen.",al={"kürbis wirkung","was geschieht mit dem zeloten","zelot ghul"}},{q="Warum haben die Verlassenen ihn hergestellt?",a="Apotheker Johaan und die Königliche Apothekervereinigung stellen biologische Gebräue her, um die Geißel im Norden und die aus dem Süden vorrückenden lebenden Menschen zu bekämpfen. Sie nutzen gefangene Feinde als Versuchspersonen.",al={"warum vergifteten kürbis herstellen","seuchentests der verlassenen"}}},fx={["242570cd"]={q="Woher kommt der Getränkte Kürbis und wer hat ihn hergestellt?",a="Apotheker Johaan hat diesen Kürbis in Brill zubereitet. Auf der Suche nach Waffen, um die Verlassenen gegen die Geißel im Norden und die lebenden Menschen im Süden zu verteidigen, erntete er gewöhnliche Produkte vom Sollidens Bauernhof und behandelte sie mit seiner experimentellen Seuchenmischung.",al={"wer hat den getränkten kürbis hergestellt","woher kommt der getränkte kürbis","schöpfer des getränkten kürbis"}},["071bacef"]={q="Warum will jemand den Getränkten Kürbis?",a="Apotheker Johaan muss den Kürbis einem lebenden Subjekt verfüttern, um seine neueste chemische Formel zu bewerten. Er wird einem hungernden Gefangenen des Scharlachroten Kreuzzugs angeboten, der im Keller unter der Taverne Zur Galgenschlinge in Brill eingesperrt ist, und dient als tödlicher Test für die Forschung der Königlichen Apothekervereinigung.",al={"warum will man den getränkten kürbis","warum benutzt man den getränkten kürbis","wofür wird der getränkte kürbis benötigt"}}},fp="13,177,16.375.0,21.383.1,26.160.0,27.168.0,43.170.1,31.201.0"}
P.entries["item:laird-s-response"] = {n="Lairds Antwort",s="An Teldrassils Küste schickt Laird Nessa Schattensang einen merkwürdigen Bericht. Die Fische dort sind größer und zahlreicher als jene an der Dunkelküste auf dem Festland.",h="An Teldrassils Küste schickt Laird Nessa Schattensang einen merkwürdigen Bericht.",kw={"auberdine","dunkelküste","angeln","laird","lairds antwort","nessa shadowsong","rut'theran","teldrassil"},ang={["race:NightElf"]="Als Nachtelf, der sich um Teldrassils Küsten kümmert, könnten Euch Lairds Aufzeichnungen neugierig machen und beunruhigen. Der junge Weltbaum könnte bereits die Natur um sich herum beeinflussen."},sec={{t="Eine Frage von Schuppen und Wurzeln",b="Laird vergleicht die Fänge von beiden Seiten des verhüllten Meeres. Fische von Teldrassils Küste sind größer und zahlreicher als jene von den Festlandsstränden der Dunkelküste.\n\nIn seiner Antwort an Nessa Schattensang fragt sich Laird aus Auberdine, ob die ungewöhnliche Präsenz und Lebenskraft des frisch gepflanzten Weltbaums das nahe Meeresleben verändern. Reisende bringen seinen Brief über das Wasser nach Rut'theran, wo die Fischer die Nachricht mit Staunen und stiller Neugier aufnehmen."}},faq={{q="Was ist Lairds Antwort?",a="Lairds Antwort ist Lairds Erwiderung auf Nessa Shadowsongs Anfrage in Teldrassil. Laird ist Fischhändler und Fischpökler in Auberdine.",al={"was ist dieser gegenstand","lairds antwort brief","was ist lairds antwort"}},{q="An wen schreibt Laird?",a="Laird schreibt an Nessa Schattensang, eine Nachtelfin, die in Rut'theran am südlichen Fuß Teldrassils lebt.",al={"wer erhält lairds antwort","wer bekommt diesen brief","nessa laird brief"}},{q="Was sagt der Brief über die Fische?",a="Laird berichtet, dass die Fische an Teldrassils Küsten größer und zahlreicher sind als jene an der Dunkelküste auf dem Festland. Er vermutet, dass der Weltbaum das nahe Meeresleben beeinflussen könnte.",al={"warum sind die fische groß","fischunterschied dunkelküste teldrassil","was hat laird entdeckt"}},{q="Wie gelangt die Nachricht zurück nach Rut'theran?",a="Ein Bote kann die regelmäßig verkehrende Fähre von Auberdines Docks nehmen oder bei Caylais Moonfeather, dem Flugmeister, einen Hippogryphenflug vereinbaren.",al={"wie zurück zu nessa","rut'theran boot dunkelküste","auberdine fähre zu nessa"}}},fx={aee914ad={q="Woher kommt Lairds Antwort und wer hat sie geschrieben?",a="Diese schriftliche Antwort stammt von Laird, einem Bewohner von Auberdine an der Küste der Dunkelküste. Er schreibt sie, um Fragen zu beantworten, die aus Rut'theran über das Meer geschickt wurden, die das lokale Meeresleben betreffen.",al={"wer hat lairds antwort geschrieben","woher kommt lairds antwort","ursprung von lairds antwort"}},fb1c817f={q="Warum will Nessa Lairds Antwort?",a="Nessa Schattensang in Rut'theran wartet sehnsüchtig auf Lairds Beobachtungen darüber, wie sich die Fänge auf dem Festland mit den Gewässern von Teldrassil vergleichen lassen. Die seltsamen, übergroßen Fische um die großen Äste des Weltenbaums haben die Fischer verwirrt, und Lairds Notizen bestätigen, dass an der Dunkelküste des Festlands nichts dergleichen zu sehen ist, was darauf hindeutet, dass Teldrassil selbst die lokale Tierwelt verändert.",al={"warum will nessa lairds antwort","warum ist lairds antwort gefragt","wer will lairds antwort"}}},fp="16,154,28.461.0,25.127.0,24.108.0,40.176.0,55.135.0"}
P.entries["item:lake-creeper-moss"] = {n="Seekrabblermoos",s="Rund um die südlichen Morgeninseln wächst Seekrabblermoos auf Wasserbestien. Die Royal Apothecary Society sucht diese organische Verbindung als wichtiges Reagenz zur Entwicklung einer tödlichen neuen Seuche.",h="Rund um die südlichen Morgeninseln wächst Seekrabblermoos auf Wasserbestien.",kw={"berard","die morgeninseln","elder lake creeper","faranell","lake creeper","seekrabblermoos","der lordameresee","the new plague","royal apothecary society"},ang={["profession:Herbalism"]="Obwohl es auf Wasserbestien statt im Boden wächst, gehört das Moos zu Lordaerons düsterer, experimenteller Flora. Es wird für die Forschung der Apotheker gesammelt.",["race:Undead"]="Jede Probe, die ins Apothekarium gebracht wird, bringt die Verlassenen der Vollendung von The New Plague und ihrer Rache an der Geißel und den Lebenden näher."},sec={{t="Alchemistische Ernte",b="Seekrabblermoos wächst auf den Häuten von Süßwasserbestien in den Gewässern bei den südlichen Morgeninseln. Lordaerons verseuchte Gewässer verleihen ihm ungewöhnliche Eigenschaften. Bevor Arugals Fluch ihm den Verstand raubte, beschrieb Apotheker Berard das Moos in seinem Tagebuch.\n\nEr stellte fest, dass es Spuren auf Fossilien von Kreaturen ähnelte, die durch eine uralte Seuche im See getötet worden waren. Agenten der Verlassenen schicken geborgene Proben ins Apothekarium in Unterstadt, wo Apothekermeister Faranell sie für seine Forschung nutzt."},{t="Arbeit an The New Plague",b="Seekrabblermoos ist ein entscheidender Schritt bei der Entwicklung der charakteristischen Waffe der Verlassenen. Zusammen mit Moos von Seeschleichern und erkrankten Tumoren örtlicher Vile Fin-Murlocs liefert es die organische Grundlage zur Verfeinerung eines Stammes, der lebendes Gewebe und die Geißel gleichermaßen auslöschen soll. Obwohl der Apotheker, der seinen Nutzen entdeckte, verloren ist, braut die Royal Apothecary Society weiterhin nach seinem Rezept im Dienste der Dunklen Fürstin."}},faq={{q="Wofür wird Seekrabblermoos verwendet?",a="Apothekermeister Faranell und die Royal Apothecary Society nutzen Seekrabblermoos als alchemistisches Reagenz, um The New Plague in Unterstadt zu brauen und zu verfeinern.",al={"seekrabblermoos zweck","warum seekrabblermoos sammeln","seekrabblermoos verwendung"}},{q="Woher stammt dieses Moos?",a="Seekrabblermoos wächst auf Lake Creepers und Elder Lake Creepers in den Gewässern rund um die südlichen Morgeninseln im östlichen Lordameresee.",al={"wo seekrabblermoos finden","seekrabblermoos fundort","lake creeper fundort"}},{q="Wer entdeckte den alchemistischen Wert des Mooses?",a="Bevor Arugals Fluch Apotheker Berard zu einem willenlosen Diener in Lohenscheit machte, hielt Berard die alchemistischen Eigenschaften des Mooses in seinem Feldtagebuch fest. Apotheker Renferrel barg später seine Aufzeichnungen.",al={"wer fand das moos","berard moos","wer schrieb über seekrabblermoos"}},{q="Wer erhält das geerntete Moos?",a="Apothekermeister Faranell nimmt das Moos im Apothekarium in Unterstadt entgegen. Für seine Forschung kombiniert er es mit Seeschleichermoos und einem Verhärteten Tumor.",al={"wer will seekrabblermoos","seekrabblermoos abgeben","faranell moos"}}},fx={["70aadfdf"]={q="Was ist Seekrabblermoos?",a="Seekrabblermoos ist ein organisches Gewächs, das direkt von den Körpern der aquatischen Kriecher geerntet wird, die den Lordameresee bewohnen. Während es äußerlich gewöhnliche Sumpfflora ist, schätzt die Königliche Apothekervereinigung es als wichtiges Reagenz für ihre dunklen Experimente.",al={"was ist seekrabblermoos","seekrabblermoos hintergrundgeschichte","seekrabblermoos erklärt"}}},fp="17,190,18.486.0,22.414.1,35.160.0,31.139.0,43.207.0,32.158.0"}
P.entries["item:lake-skulker-moss"] = {n="Seeschleichermoos",s="Im nördlichen Lordameresee weckt Seeschleichermoos das Interesse der Royal Apothecary Society. Apotheker Berard fand eine Verwendung dafür beim Brauen einer New Plague, bevor Arugals Fluch ihm den Verstand raubte.",h="Im nördlichen Lordameresee weckt Seeschleichermoos das Interesse der Royal Apothecary Society.",kw={"berard","die morgeninseln","faranell","der lordameresee","lake skulker","seeschleichermoos","new plague","renferrel"},ang={["race:Undead"]="Als Untoter bringt Ihr die Royal Apothecary Society der Vollendung der New Plague näher. Die Verlassenen wollen sie gegen die Geißel und die Lebenden einsetzen."},sec={{t="Ein Seuchenreagenz",b="Seeschleichermoos stammt von Lake Skulkers und Elder Lake Skulkers auf den Morgeninseln. Bevor Arugals Fluch ihm den Verstand raubte, katalogisierte Apotheker Berard die Pflanzen und Kreaturen des östlichen Silberwalds. Seinem Tagebuch zufolge konnten Moose von Lake Skulkers und Lake Creepers andere Zutaten stabilisieren oder mit ihnen reagieren.\n\nNachdem der Fluch Berard zu Arugals willenlosem Diener gemacht hatte, wurde sein Tagebuch für Apotheker Renferrel aus Lohenscheit geborgen. Renferrel schickte Champions der Verlassenen aus, um Moos und einen seltenen Tumor von einheimischen Murlocs der Vile Fin zu sammeln. Sie sollten beides zu Apothekermeister Faranell in Unterstadt bringen."}},faq={{q="Wofür wird Seeschleichermoos verwendet?",a="Die Royal Apothecary Society in Unterstadt verwendet Seeschleichermoos als organische Grundlage zum Brauen der New Plague. Dies dient den Zielen von Fürstin Sylvanas Windläufer für die Verlassenen.",al={"moos verwendung","warum seeschleichermoos sammeln","was bewirkt seeschleichermoos"}},{q="Woher stammt dieses Moos?",a="Seeschleichermoos wird von Lake Skulkers und Elder Lake Skulkers in den Gewässern rund um die Morgeninseln abgeschabt. Die Inseln liegen im nordöstlichen Lordameresee vor dem Silberwald.",al={"wo seeschleichermoos bekommen","seeschleichermoos fundort","wer lässt seeschleichermoos fallen"}},{q="Wer entdeckte den Nutzen des Mooses?",a="Apotheker Berard entdeckte das Potenzial des Mooses bei seinen Forschungen im Silberwald. Nachdem Arugals Fluch ihn zu einem willenlosen Diener gemacht hatte, half sein Tagebuch Apotheker Renferrel und Apothekermeister Faranell, die Experimente fortzusetzen.",al={"wer fand das moos","berard moos","apotheker berard forschung"}},{q="Wer benötigt dieses Reagenz?",a="Apothekermeister Faranell leitet die Royal Apothecary Society im Apothekarium von Unterstadt. Er benötigt das Moos für seine Projekte zur biologischen Kriegsführung.",al={"wer will seeschleichermoos","faranell seeschleichermoos"}}},fx={["18c0a856"]={q="Was ist Seeschleichermoos?",a="Seeschleichermoos ist ein natürliches Gewächs, das von den Rücken von Seeschleichern geerntet wird, amphibischen Bestien, die um die Morgeninseln des Lordameresees lauern. Obwohl für Fischer und Reisende unbedeutend, besitzt diese organische Materie spezifische Eigenschaften, die die Aufmerksamkeit der Alchemisten der Verlassenen auf sich zogen, die die lokale Flora und Fauna untersuchten.",al={"was ist seeschleichermoos","seeschleichermoos info","seeschleichermoos erklärt"}}},fp="17,194,16.613.0,35.178.0,31.179.0,37.225.0,26.149.0"}
P.entries["item:large-candle"] = {n="Große Kerze",s="In Elwynns Minen tragen Kobolde Große Kerzen als Lichtquelle und Wachsvorrat. Apotheker schätzen das Wachs für ihre Arbeit.",h="In Elwynns Minen tragen Kobolde Große Kerzen als Lichtquelle und Wachsvorrat.",kw={"tiefenschachtmine","goldhain","goldtooth","jaspismine","kobold candles","große kerze","wachs","william pestle"},ang={["faction:Alliance"]="Indem Abenteurer der Allianz den Kobolden in Elwynn Kerzen abnehmen, schwächen sie das Ungeziefer in den Minen und liefern wichtige Materialien für Sturmwinds Apothekengewerbe.",["profession:Mining"]="Bergleute, die die Erzadern in der Tiefenschachtmine und der Jaspismine abbauen, geraten oft mit den dort eingedrungenen Kobolden aneinander. Die Kobolde begehren sowohl das Gold als auch das Licht der Großen Kerzen."},sec={{t="Licht und Wachs unter Tage",b="Kobolde folgen dem Kerzenlicht durch die dunklen Schächte unter dem Wald von Elwynn. Sie befestigen die Kerzen an ihren Köpfen, und Kobold Miners, Tunnelers und Geomancers verteidigen sie erbittert gegen Eindringlinge. Große Kerzen aus der Tiefenschachtmine und der Jaspismine enthalten wertvolles Wachs, obwohl sie grob gefertigt sind. Handwerker an der Oberfläche können nur wenig Wachs auf einmal herstellen, daher dienen die Kerzen den Kobolden als Werkzeuge und Alchemisten als Handelsware."},{t="Handel und die Apotheke",b="William Pestle, ein Apothekenmitarbeiter aus Sturmwind, sammelt Große Kerzen im Gasthaus \"Zur Höhle des Löwen\" in Goldhain. Seine Familie betreibt eine Apotheke, und er benötigt ausgeschmolzenes Wachs für ihre Gebräue, Balsame und Salben. Pestle heuert vorbeikommende Abenteurer an, um die befallenen Minen zu säubern und den Kobolden Kerzen abzunehmen."}},faq={{q="Wofür werden Große Kerzen verwendet?",a="William Pestle sammelt Große Kerzen in Goldhain für die Apotheke, die er mit seinem Bruder in Sturmwind betreibt. Sie schmelzen die Kerzen ein, um Wachs für Salben, Balsame und alchemistische Rezepturen zu gewinnen.",al={"große kerze verwendung","warum große kerzen sammeln","wer will große kerzen"}},{q="Wo sind Große Kerzen zu finden?",a="Kobolde tragen Große Kerzen in den Minen des Waldes von Elwynn, besonders in der Tiefenschachtmine südlich von Goldhain und der Jaspismine im Osten. Tunnelers, Miners und Geomancers tragen sie bei sich.",al={"große kerze fundort","wo große kerzen bekommen","kobolde kerzenbeute"}},{q="Warum tragen Kobolde Kerzen auf dem Kopf?",a="Kobolde nutzen Kerzenlicht, um zu graben und sich in dunklen unterirdischen Tunneln zurechtzufinden. Sie befestigen Kerzen an ihren Köpfen, um die Hände für Spitzhacken, geomantische Zauber und Waffen frei zu haben.",al={"warum haben kobolde kerzen","kobolde kopfkerzen hintergrund"}},{q="Wer ist William Pestle?",a="William Pestle ist ein Apothekenmitarbeiter aus Sturmwind, der im Gasthaus \"Zur Höhle des Löwen\" in Goldhain seinen Geschäften nachgeht. Er sammelt Zutaten aus der Wildnis und den Minen, um die Apotheke zu versorgen, die er mit seinem Bruder betreibt.",al={"william pestle hintergrund","wer ist der apotheker in goldhain"}}},fx={["05873d56"]={q="Was ist eine Große Kerze?",a="Eine Große Kerze ist ein grober, kräftiger Wachsstab, der von den Kobolden getragen wird, die in den Minen des Walds von Elwynn hausen. Kobolde sind bekanntermaßen sehr auf ihre Lichtquellen bedacht und benutzen diese schweren Kerzen, um die Dunkelheit unterirdischer Tunnel wie der Minen von Fargodeep und Jasperlode zu durchdringen, während sie nach Gold und Mineralien graben.",al={"was ist eine große kerze","große kerze elwynn","große kerze hintergrundgeschichte"}}},fp="12,108,26.430.0,24.316.0,32.199.0,33.177.0,44.194.0,22.229.0"}
P.entries["item:large-soran-ruk-fragment"] = {n="Großes Fragment von Soran'ruk",s="In Burg Shadowfang liegt das Große Fragment von Soran'ruk fern der anderen Splitter. Seine zerbrochene Kugel barg einst einen in Ungnade gefallenen Dämon der Brennenden Legion.",h="In Burg Shadowfang liegt das Große Fragment von Soran'ruk fern der anderen Splitter.",kw={"brennende legion","doan karhan","großes fragment von soran'ruk","kugel von soran'ruk","burg shadowfang","soran'ruk"},ang={["class:Warlock"]="Als Hexenmeister könnt Ihr durch die Rückgewinnung des Großen Fragments von Soran'ruk den darin gefangenen dämonischen Geist beherrschen. Ihr könnt Doan Karhan helfen, eine mächtige Waffe für dämonische Künste wiederherzustellen."},sec={{t="Das Vermächtnis von Soran'ruk",b="In Ungnade gefallene Dämonen der Brennenden Legion können in verzauberten Kugeln eingesperrt werden. Mit der Legion verbündete Magier und Hexenmeister erhalten diese Gefäße und schöpfen aus den Teufelskräften darin. Selbst wenn eine Kugel zerbricht, hinterlässt ihr gebundener Unhold eine Essenz, die weiterhin Macht ausstrahlt. So locken Fragmente jene an, die Shadow Magic meistern wollen."},{t="Der Splitter in Shadowfang",b="Die Kugel von Soran'ruk zerbrach vor langer Zeit in zwei Hälften. Kultisten andernorts verstreuten eine Hälfte in kleineren Stücken, während ein Zauberer in der verfluchten Burg Shadowfang die größere Hälfte beanspruchte. Shadowfang Darksouls tragen das Große Fragment von Soran'ruk bei sich. Sein gebundener Geist bleibt darin, bis jemand das uralte Gefäß neu zu schmieden sucht."}},faq={{q="Was ist das Große Fragment von Soran'ruk?",a="Das Große Fragment von Soran'ruk ist die größere Hälfte der Kugel von Soran'ruk, die den gebundenen Geist eines in Ungnade gefallenen Dämons der Brennenden Legion birgt.",al={"großes fragment von soran'ruk","soran'ruk großes fragment","was ist dieses fragment"}},{q="Wo ist das Fragment zu finden?",a="Shadowfang Darksouls besitzen das Fragment in Burg Shadowfang, einer heimgesuchten Festung im Silberwald.",al={"wo ist das große fragment zu finden","fundort großes fragment","wer lässt das große fragment von soran'ruk fallen"}},{q="Warum wurde die Kugel zerbrochen?",a="Die ursprüngliche Kugel wurde in zwei Hauptstücke gespalten. Die kleinere Hälfte wurde in Splitter zerbrochen und in die Küstenhöhlen der Tiefschwarzen Grotte gebracht. Finstere Zauberer bewahrten die größere Hälfte in Burg Shadowfang auf.",al={"wie zerbrach die kugel","warum ist die kugel zersplittert","geschichte der kugel von soran'ruk"}},{q="Wer will sie wieder zusammensetzen?",a="Doan Karhan, ein zurückgezogen lebender Einsiedler im Südlichen Brachland, hat sein Leben dem Studium und der Wiederherstellung der verlorenen Kugeln der Brennenden Legion gewidmet.",al={"wer braucht das große fragment","wer setzt die kugel wieder zusammen"}}},fx={["0cdd1dfd"]={q="Woher stammt das Große Fragment von Soran'ruk und wer hat es gemacht?",a="Das Fragment war einst Teil des The Orb of Soran'ruk, einem Artefakt, das von der Brennenden Legion erschaffen wurde. Wenn Dämonen der Legion in Ungnade fallen, werden ihre Geister in Kugeln gebunden und sterblichen Magiern und Hexenmeistern gegeben. Soran'ruk war ein solcher Dämon, dessen Essenz eingesperrt wurde, um dämonische Magie anzutreiben. Die Kugel wurde später in zwei Teile gespalten, wobei dieser größere Splitter in die Hände eines dunklen Zauberers in Burg Shadowfang fiel.",al={"ursprung des fragments von soran'ruk","wer hat die kugel von soran'ruk gemacht","woher kommt soran'ruk"}}},fp="24,146,23.317.0,23.330.0,37.138.0,28.99.0,23.199.0,27.145.0"}
P.entries["item:laughing-sister-s-hair"] = {n="Haar der lachenden Schwester",s="In Eschental suchen Weber die natürliche Magie im Haar der Laughing Sisters. Kil'hala am Wegekreuz fertigt aus den Locken verzauberte Roben.",h="In Eschental suchen Weber die natürliche Magie im Haar der Laughing Sisters.",kw={"eschental","stoff","das wegekreuz","deino","dryade","haar","kil'hala","laughing sister","rajenbaum"},ang={["faction:Horde"]="Als Mitglied der Horde müsst Ihr in Eschental das Gebiet der Nachtelfen betreten und Waldgeister töten, um ihre Locken zu erbeuten. Ihr eignet Euch die örtliche Magie mit Gewalt an.",["profession:Tailoring"]="Als Schneider könnt Ihr Dryadenlocken als exotischen Faden verwenden, um Naturmagie in Stoff zu binden."},sec={{t="Ein seltenes Webmaterial",b="Nahe Rajenbaum leben die Laughing Sisters, Dryaden, deren Haar natürliche Magie birgt. Sie bewachen die Wälder und sind mit Cenarius und den Nachtelfen verbunden. Handwerker der Horde schätzen ihr Haar als mächtiges Material.\n\nKil'hala, ein Trollschneider am Wegekreuz, spinnt die Locken zu verzauberten Roben für Deinos vielversprechende Schüler der arkanen Magie."}},faq={{q="Woher stammt das Haar der lachenden Schwester?",a="Die Laughing Sisters sind Dryaden, die durch die verzauberten Haine nahe Rajenbaum im Herzen von Eschental streifen. Ihr Haar birgt natürliche Magie.",al={"woher haar der lachenden schwester bekommen","haar der lachenden schwester fundort","dryadenhaar herkunft"}},{q="Warum sucht Kil'hala nach Dryadenhaar?",a="Kil'hala, ein Schneider am Wegekreuz im Brachland, webt die magischen Strähnen zu verzauberten Stoffroben für Deinos vielversprechende Schüler.",al={"warum kil'hala haar will","verwendung für haar der lachenden schwester","trollschneider dryadenhaar"}},{q="Geben die Laughing Sisters ihr Haar freiwillig her?",a="Nein. Die Laughing Sisters hüten die Natur und beschützen Eschental. Wie Kil'hala anmerkt, würden Dryaden ihr Haar niemals freiwillig an die Handlanger der Horde abgeben.",al={"kann man dryaden um haar bitten","spenden dryaden haar"}}},fx={["3a458879"]={q="Was ist Haar der lachenden Schwester?",a="Haar der lachenden Schwester besteht aus abgeschnittenen Locken, die von Laughing Sisters gesammelt wurden, den Wald-Dryaden, die in der Nähe von Rajenbaum im Eschental leben. Durchdrungen von der natürlichen Anmut und Magie von Cenarius' Töchtern, sind diese Strähnen bei geschickten Schneidern als seltenes Webmaterial für mächtige Zaubergewänder begehrt.",al={"was ist haar der lachenden schwester","info zu haar der lachenden schwester","dryadenhaar material"}}},fp="22,138,24.333.0,44.136.0,39.136.0,55.149.0"}
P.entries["item:legacy-of-the-aspects"] = {n="Vermächtnis der Aspekte",s="Bei der Prüfung der Horde müssen Suchende Vermächtnis der Aspekte finden und sich seine Lehren einprägen. Der uralte Wälzer liegt im Dor'danil-Grabhügel im südlichen Eschental und birgt Wissen über die Großen Aspekte, die das uralte Azeroth formten.",h="Bei der Prüfung der Horde müssen Suchende Vermächtnis der Aspekte finden und sich seine Lehren einprägen.",kw={"eschental","grabhügel","braug dimspirit","dor'danil","vermächtnis der aspekte","der steinkrallenpfad","test of lore"},ang={["class:Druid"]="Als Druide findet Ihr den Text tief im Dor'danil-Grabhügel, inmitten der tragischen, gequälten Geister gefallener Nachtelfendruiden.",["faction:Horde"]="Als Abenteurer der Horde stellt Ihr Euch einem traditionellen Übergangsritus. Er prüft, ob Eure Weisheit und Euer Wissen Eurer körperlichen Macht ebenbürtig sind."},sec={{t="Eine Prüfung des Geistes",b="Braug Dimspirit schickt Anwärter auf die Suche nach Vermächtnis der Aspekte. Frühere Prüfungen der Taurenältesten stellen Ausdauer und Entschlossenheit auf die Probe. Diese Prüfung fordert den Geist. Braug wartet am Eingang zum Steinkrallenpfad im Steinkrallengebirge, während der Wälzer in den heimgesuchten Grabhügeln von Dor'Danil liegt.\n\nRuhelose Geister gefallener Druiden und die bösartigen Kreaturen, die sie erschlugen, bewachen den uralten Text. Er ruht auf einem steinernen Podest. Den Band zu finden, ist erst der Anfang. Bevor der Suchende ihn zurückbringt, muss er sich seinen Inhalt einprägen. Dann prüft Braug sein Wissen über die darin enthaltenen Lehren der Geschichte."}},faq={{q="Wo befindet sich das Buch?",a="Vermächtnis der Aspekte ruht auf einem steinernen Podest in den unteren Kammern des Dor'danil-Grabhügels im südlichen Eschental, südlich des Splitterholzpostens.",al={"vermächtnis der aspekte finden","fundort des buches","wo ist das buch"}},{q="Warum will Braug Dimspirit dieses Buch?",a="Braug Dimspirit nutzt den Wälzer für den Test of Lore. Die Prüfung zeigt, ob ein Abenteurer neben körperlicher Stärke auch die Fähigkeit besitzt, wichtiges geschichtliches Wissen zu erlernen und wiederzugeben.",al={"warum braug das buch will","zweck des test of lore"}},{q="Was geschieht, wenn Ihr den Text nicht studiert, bevor Ihr mit Braug sprecht?",a="Braug befragt Suchende zum Wissen aus dem Buch, sobald sie es an sich genommen haben. Eine falsche Antwort führt zur sofortigen magischen Verbannung, die den unvorbereiteten Prüfling weit fort nach Camp Taurajo im Brachland schickt.",al={"folge einer falschen antwort","prüfung nicht bestehen"}}},fx={["32a02485"]={q="Was ist Vermächtnis der Aspekte?",a="Das Vermächtnis der Aspekte ist ein altes und wertvolles Buch, das tief im Dor'danil-Grabhügel im südlichen Eschental ruht. Bewacht von den ruhelosen Geistern gefallener Druiden und den abscheulichen Kreaturen, die sie erschlugen, enthält das Buch historisches Wissen über die Drachenaspekte und dient als anspruchsvoller Test für Weisheit und Gedächtnis für diejenigen, die es wagen, es zu bergen.",al={"was ist vermächtnis der aspekte","buch vermächtnis der aspekte","was ist dieses buch"}}},fp="21,226,18.582.0,26.144.0,40.174.0,68.193.0"}
P.entries["item:letter-to-delgren"] = {n="Brief an Delgren",s="Balthule Schattenhieb sendet Nachricht vom Turm von Althalaxx an der nördlichen Dunkelküste. Sein Brief warnt Delgren den Läuterer vor dem dämonischen Wirken des Kults der Dunkelstränge und muss Maestras Posten in Eschental erreichen.",h="Balthule Schattenhieb sendet Nachricht vom Turm von Althalaxx an der nördlichen Dunkelküste.",kw={"eschental","balthule schattenhieb","dunkelstränge","dunkelküste","delgren der läuterer","brief an delgren","maestras posten","turm von althalaxx"},ang={["class:Paladin"]="Als Paladin seht Ihr, wie ein menschlicher Paladin einen Nachtelfen im Heiligen Licht unterweist. Ihr Band verbindet die Lande der Kaldorei mit dem kriegerischen Glauben der Östlichen Königreiche.",["faction:Alliance"]="Als Mitglied der Allianz seht Ihr, wie menschliche Streiter und Schildwachen der Nachtelfen im nördlichen Kalimdor gemeinsam gegen dämonische Kulte kämpfen."},sec={{t="Eine Warnung nach Süden",b="An den Ruinen des Turms von Althalaxx beobachtet Balthule Schattenhieb, wie sich der Kult der Dunkelstränge versammelt. Er kann sie nicht allein vernichten, also schreibt er an Delgren den Läuterer, seinen Lehrmeister im Heiligen Licht, und bittet um Hilfe. Ihre abscheulichen Riten bedrohen mehr als nur die Küste der Dunkelküste. Der Brief muss nach Süden durch die Dunkelküste ins westliche Eschental gelangen. Dort kämpft Delgren gemeinsam mit den Schildwachen der Nachtelfen gegen dämonische und untote Bedrohungen."}},faq={{q="Was ist der Brief an Delgren?",a="Balthule Schattenhiebs versiegelter Brief warnt Delgren den Läuterer vor den zunehmenden Aktivitäten des Kults der Dunkelstränge am Turm von Althalaxx.",al={"was ist dieser brief","brief an delgren","balthules brief"}},{q="Wer ist Delgren der Läuterer?",a="Delgren der Läuterer ist ein menschlicher Paladin an Maestras Posten im westlichen Eschental. Er dient dem Heiligen Licht und hilft den Schildwachen der Nachtelfen im Kampf gegen Dämonen und Untote in den uralten Wäldern. Er unterweist Balthule auch in heiliger Kriegsführung.",al={"wer ist delgren","delgrens geschichte","wo ist delgren"}},{q="Warum schickt Balthule den Brief so weit fort?",a="Balthule ist Delgrens Schüler und sucht die Hilfe seines Lehrmeisters im Kampf gegen dämonische Verderbnis. An Maestras Posten kann Delgren seine Kampfkraft und die örtlichen Schildwachen gegen die finsteren Rituale der Dunkelstränge einsetzen.",al={"warum nach eschental schicken","warum nicht auberdine informieren"}},{q="Wohin muss dieser Brief gebracht werden?",a="Bringt den Brief nach Süden durch die Dunkelküste und über die Grenze nach Eschental. Maestras Posten liegt an der westlichen Straße.",al={"wohin den brief bringen","zustellort des briefes"}}},fx={["8fccd45f"]={q="Woher kommt der Brief an Delgren und wer hat ihn geschrieben?",a="Der Brief wurde von Balthule Schattenhieb geschrieben, einem Nachtelfen, der in der nördlichen Dunkelküste in der Nähe von The Tower of Althalaxx stationiert ist. In dem Bestreben, die dämonische Verderbnis zu säubern, die in den alten Ruinen Wurzeln geschlagen hat, schrieb Balthule dieses dringende Schreiben, um den Beistand und Rat seines Mentors, des Paladins Delgren der Läuterer, zu erbitten.",al={"wer hat den brief an delgren geschrieben","woher kommt der brief an delgren","wer hat den brief an delgren geschickt"}},["99aa1720"]={q="Warum ist der Brief an Delgren so wichtig?",a="Das Schreiben enthält wichtige Informationen, die die finsteren Machenschaften des Kults des Dunkelstrangs bei The Tower of Althalaxx aufdecken. Delgren der Läuterer hat es sich zur Aufgabe gemacht, den Nachtelfen dabei zu helfen, Dämonen und Untote aus den Wäldern zu vertreiben, und Balthule muss seinen Mentor sofort alarmieren, damit sie der wachsenden Bedrohung entgegentreten können.",al={"warum braucht delgren den brief","warum will man den brief an delgren","bedeutung des briefes an delgren"}}},fp="17,204,20.414.0,30.134.0,28.229.0,47.214.0,44.122.0"}
P.entries["item:letter-to-ello"] = {n="Brief an Ello",s="Calvinius schickt einen versiegelten Brief an Bürgermeister Ello Ebonlocke in Dunkelhain. Der Einsiedler lebt in einer Hütte gleich nördlich des Friedhofs von Rabenflucht, behauptet, eine alte Freundschaft verbinde sie, und verfasst das Schreiben in einer archaischen Schrift.",h="Calvinius schickt einen versiegelten Brief an Bürgermeister Ello Ebonlocke in Dunkelhain.",kw={"calvinius","dunkelhain","dämmerwald","ello ebonlocke","brief an ello","note to the mayor","sirra von'indi"},ang={["faction:Alliance"]="Als Reisender der Allianz im Dämmerwald könnt Ihr eine Depesche von einem exzentrischen Einsiedler zum Bürgermeister einer Stadt bringen. Dunkelhains Amtsträger bleiben bei seltsamen Schreiben auf der Hut."},sec={{t="Ein seltsamer Gruß",b="Nachdem Ihr Calvinius bei Aufgaben im Dämmerwald geholfen habt, gibt Euch der alte Einsiedler eine Notiz für Bürgermeister Ello Ebonlocke. Er sagt, der Bürgermeister sei ein alter Freund, der Eure Leistungen feiern werde. Als Ello das Siegel bricht, kann er sich an niemanden namens Calvinius erinnern und keinen einzigen Satz der archaischen Schrift lesen. Er schickt die Notiz zur Übersetzung an Sirra Von'Indi, eine Gelehrte in Dunkelhain."},{t="Dunkle Vorzeichen",b="Die Runen von Calvinius haben für Dunkelhain eine düstere Bedeutung. Der Brief beschreibt keine alte Freundschaft zwischen Bekannten aus der Stadt; er kündet vom Untergang der ganzen Stadt."}},faq={{q="Wer hat den Brief an Ello geschrieben?",a="Calvinius hat den Brief geschrieben. Er ist ein Einsiedler, der in einer baufälligen Hütte nahe dem Friedhof von Rabenflucht im westlichen Dämmerwald lebt.",al={"wer schrieb den brief","brief an ello verfasser","wer schickte den brief"}},{q="Kann Bürgermeister Ello Ebonlocke den Brief lesen?",a="Nein. Als Ello Ebonlocke das Siegel bricht, ist die Schrift für ihn völlig unverständlich und scheint in einer uralten, ihm unbekannten Sprache verfasst zu sein.",al={"kann ello ihn lesen","warum kann ello die notiz nicht lesen","ello brief sprache"}},{q="Wer kann die Notiz übersetzen?",a="Sirra Von'Indi kann die Notiz übersetzen. Bürgermeister Ebonlocke schickt sie an die ortsansässige Gelehrte in Dunkelhain, die sich mit alten Schriften und esoterischen Sprachen auskennt.",al={"wer übersetzt die notiz","calvinius notiz übersetzen","wer kann den brief lesen"}},{q="Kennt Bürgermeister Ebonlocke Calvinius wirklich?",a="Nein. Obwohl Calvinius behauptet, sie seien alte Freunde, sagt Ello Ebonlocke, er habe noch nie von jemandem namens Calvinius gehört.",al={"kennt ello calvinius","sind ello und calvinius freunde","calvinius alte freunde ello"}}},fx={["74d18927"]={q="Was ist der Brief an Ello?",a="Der Brief an Ello ist ein mysteriöses Schreiben, das in einer alten, unleserlichen Sprache verfasst wurde und von Calvinius dem Einsiedler stammt. Direkt an Bürgermeister Ello Schwarzhaupt von Dunkelhain gerichtet, behauptet der Einsiedler, dass die Notiz seinen \"alten Freund\" über die Taten informieren wird, die Ihr auf dem Friedhof vollbracht habt.",al={"brief an ello","was ist der brief an ello","calvinius' notiz"}},ee8215fa={q="Warum möchte Bürgermeister Schwarzhaupt den Brief an Ello?",a="Bürgermeister Schwarzhaupt möchte den Brief nur, weil Ihr mit der Nachricht ankommt, dass ein alter Freund namens Calvinius ihn geschickt hat. Nach Erhalt stellt der Bürgermeister jedoch fest, dass er dessen archaische Schrift nicht lesen kann, und versucht dringend, ihn übersetzen zu lassen, um aufzudecken, was der Einsiedler eigentlich beabsichtigt hat.",al={"warum will ello den brief","warum brief an ello","warum brief an ello überbringen"}}},fp="14,205,18.399.0,10.165.1,29.117.0,41.155.0,27.151.0,47.119.1"}
P.entries["item:letter-to-jin-zil"] = {n="Brief an Jin'Zil",s="Am Wegekreuz schickt Darsok Schnelldolch Jin'Zil Neuigkeiten aus dem nördlichen Brachland. Serena Bloodfeather ist tot, und die Bedrohung durch die Bloodfeathers dort ist beendet.",h="Am Wegekreuz schickt Darsok Schnelldolch Jin'Zil Neuigkeiten aus dem nördlichen Brachland.",kw={"darsok schnelldolch","harpyien","jin'zil","brief an jin'zil","malaka'jin","rokhan","serena bloodfeather","steinkrallengebirge"},ang={["faction:Horde"]="Als Reisender der Horde tragt Ihr Nachrichten von der Verteidigung des Brachlands mitten in die tieferen Konflikte des Steinkrallengebirges.",["race:Troll"]="Als Troll könnt Ihr den Brief zu Hexendoktor Jin'Zil bringen, einem alten Voodoopraktiker, der den traditionellen Voodoo außerhalb der Echoinseln weiterführt."},sec={{t="Ein Bote ins Steinkrallengebirge",b="Nachdem die Harpyien in den Trockenen Hügeln ausgelöscht und Serena Bloodfeather erschlagen wurden, schreibt Darsok Schnelldolch einem alten Kameraden. Die Harpyien des Brachlands nisteten ursprünglich auf den Gipfeln des Steinkrallengebirges. Darsok schickt Jin'Zil, einem Hexendoktor, die Nachricht vom Tod ihrer Matrone und führt einen vielversprechenden Krieger in das weitere Grenzland ein."},{t="Alte Erinnerungen in Malaka'jin",b="Bei der Höhle in Malaka'jin nimmt Jin'Zil die Nachricht mit Genugtuung und alten Erinnerungen auf. Serenas Tod ruft die Gründung von Durotar nach dem Dritten Krieg in Erinnerung. Damals schloss sich Rokhan, Jin'Zils Freund, Rexxar an, einem Halb-Oger-Bestienmeister, um Serenas ältere Schwester Bloodfeather zu töten. Nun ist auch Serena gefallen, und Jin'Zil glaubt, dass die Rache der Bloodfeather-Blutlinie ein Ende gefunden hat."}},faq={{q="Wer hat den Brief an Jin'Zil geschrieben?",a="Darsok Schnelldolch, ein Orc am Wegekreuz im Brachland, hat den Brief geschrieben. Er koordiniert die Verteidigung gegen marodierende Harpyienschwärme.",al={"wer hat das geschrieben","absender des briefes","darsoks brief"}},{q="Wo befindet sich Jin'Zil?",a="Jin'Zil lebt in einer Höhle bei Malaka'jin, einem Außenposten der Dunkelspeer-Trolle in den südöstlichen Felsen des Steinkrallengebirges.",al={"wo ist jinzil","jin'zils aufenthaltsort","jinzil finden"}},{q="Welche Nachricht enthält der Brief?",a="Der Brief teilt Jin'Zil mit, dass Serena Bloodfeather erschlagen wurde, die Anführerin der Harpyien, die ins nördliche Brachland herabstoßen. Ihr Tod sichert das Gebiet nördlich des Wegekreuzes.",al={"was steht im brief","nachricht im brief"}},{q="Warum sind die Bloodfeathers für Jin'Zil von Bedeutung?",a="Jin'Zil erinnert sich an die Gründung von Durotar nach dem Dritten Krieg. Sein Gefährte Rokhan und Rexxar, ein Halb-Oger-Krieger, töteten Serenas ältere Schwester. Seitdem sann Serena auf Rache an der Horde, weshalb ihr Untergang einen willkommenen Abschluss bringt.",al={"warum jin'zil harpyien","geschichte der bloodfeathers","rokhan und bloodfeather"}}},fx={f9426e82={q="Warum möchte Jin'Zil, dass der Brief an Jin'Zil ihm überbracht wird?",a="Der Brief bringt lang erwartete Nachrichten von seinem alten Freund Darsok Schnelldolch aus dem Brachland. Jin'Zil hat seit vielen Jahren nichts mehr von Darsok gehört und das Schreiben bestätigt den Tod von Serena Bloodfeather, was den Harpyien-Matriarchinnen, die sowohl das Brachland als auch das Steinkrallengebirge beunruhigten, ein Ende setzt.",al={"warum brief an jinzil überbringen","wer will brief an jinzil","warum interessiert jinzil der brief"}}},fp="17,157,25.330.0,26.369.1,32.137.0,25.116.0,41.183.0,46.243.1"}
P.entries["item:letter-to-jorgen"] = {n="Brief an Jorgen",s="In Sturmwind ruft ein versiegelter Brief Jorgen auf, bei der Suche nach einem vermissten Diplomaten zu helfen.",h="In Sturmwind ruft ein versiegelter Brief Jorgen auf, bei der Suche nach einem vermissten Diplomaten zu helfen.",kw={"jaina prachtmeer","jorgen","brief an jorgen","vermisster diplomat","sturmwind","theramore","das tal der helden"},ang={["class:Rogue"]="Als Schurke wisst Ihr, dass unauffällige Depeschen und widerwillige Informanten auf der Straße helfen können, Unheil in der Hauptstadt aufzudecken.",["faction:Alliance"]="Der Brief betrifft die zerbrechliche Stabilität der Allianz und ersucht um eine diskrete Reaktion auf einen Vorfall, der die Beziehungen zwischen Sturmwind und Theramore bedroht."},sec={{t="Eine nüchterne Aufforderung",b="Ein Diplomat auf dem Weg nach Theramore kam nie zu den Gesprächen mit Lady Jaina Prachtmeer an. Königliche Ermittler handelten rasch, um die Angelegenheit geheim zu halten. Während offizielle Agenten die Hauptstadt durchsuchten, regte sich auf anderen Wegen etwas. Der Brief umgeht die militärische Rangordnung und richtet sich an Jorgen, einen mürrischen Veteranen, der unter den großen Statuen im Tal der Helden angelt. Er beruft sich auf alte Verpflichtungen und zieht ihn in verdeckte Ermittlungen hinein, während Gerüchte über eine Verschwörung der Defias umgehen."}},faq={{q="Welchen Zweck hat dieser Brief?",a="Der Brief stellt seinen Überbringer vor und fordert Jorgen auf, eine alte Verpflichtung zu erfüllen. Er schickt den Überbringer ins Tal der Helden, um im Stillen bei den Ermittlungen zum vermissten Diplomaten zu helfen.",al={"was bewirkt der brief an jorgen","warum der brief an jorgen","zweck des briefs"}},{q="Wer ist Jorgen?",a="Jorgen ist ein zurückgezogen lebender Kontakt gleich hinter den Toren von Sturmwind, der seine Zeit mit Angeln im Tal der Helden verbringt. Er wird ungern gestört, doch eine alte Schuld verpflichtet ihn zu helfen, sobald man ihm den Brief zeigt.",al={"wer ist jorgen","jorgen npc","jorgen sturmwind"}},{q="Auf welchen Vermisstenfall bezieht sich der Brief?",a="Ein angesehener Diplomat verließ Sturmwind per Schiff in Richtung Theramore, um Lady Jaina Prachtmeer zu treffen, und verschwand unterwegs. Der Verdacht fällt auf die Bruderschaft der Defias, doch die Hintergründe des Komplotts bleiben streng geheim.",al={"welcher diplomat wird vermisst","wer ist verschwunden","vermisster diplomat"}},{q="Wohin wird der Brief gebracht?",a="Der Brief wird ins Tal der Helden gebracht, den prächtigen Eingang von Sturmwind, den Denkmäler für die Helden des Zweiten Krieges säumen. Jorgen angelt am Wasser nahe den vorderen Toren.",al={"wohin mit dem brief","jorgens standort","wo ist jorgen"}}},fx={["0eeb183b"]={q="Was ist der Brief an Jorgen?",a="Dieser Brief ist eine vertrauliche Nachricht, die bezüglich des stillen Verschwindens eines Diplomaten aus Sturmwind auf dem Weg nach Theramore versandt wurde. Da offizielle königliche Agenten die Stadt bereits offen durchkämmen, rekrutiert diese versiegelte Notiz private, diskrete Kontakte außerhalb der normalen Kanäle der Krone, um die vermutete Verwicklung der The Defias Brotherhood zu untersuchen.",al={"was ist der brief an jorgen","brief an jorgen gegenstand","über brief an jorgen"}},["5d64bfbf"]={q="Woher kommt der Brief an Jorgen und wer hat ihn geschrieben?",a="Der Brief wurde von Bischof DeLavey in Sturmwind verfasst, der eine unabhängige Untersuchung zu dem vermissten Diplomaten anstrebte. Er vertraute persönlichen Verbündeten mehr als auffälligen Ermittlern der Krone und verfasste die Nachricht speziell, um einen alten Freund namens Jorgen herbeizurufen, der sich derzeit an den Gewässern im Tal der Helden verborgen hält.",al={"wer schrieb brief an jorgen","wer sandte brief an jorgen","herkunft brief an jorgen"}},["9fd54092"]={q="Warum wird der Brief an Jorgen gesucht?",a="Jorgen benötigt den Brief, weil er eine verdeckte Verpflichtung umreißt, die er nicht ignorieren kann. Obwohl er zögert, sich von seinem ruhigen Fischfang ablenken zu lassen, überzeugen ihn die Inhalte des Schreibens dazu, bei der Aufdeckung der Verschwörung der The Defias Brotherhood zu helfen, bevor in der Hauptstadt Panik ausbricht.",al={"warum brief an jorgen überbringen","warum braucht jorgen den brief","zweck der übergabe brief an jorgen"}}},fp="16,80,23.440.0,35.174.0,14.196.0,45.206.0,30.181.0"}
P.entries["item:lewis-note"] = {n="Lewis' Notiz",s="Auf der Späherkuppe schickt Rüstmeister Lewis einen Kurier per Greif los, um Rüstungen für Westfalls Garnison zu beschaffen. Die Bestellung geht an einen privaten Rüstungsschmied in Sturmwind.",h="Auf der Späherkuppe schickt Rüstmeister Lewis einen Kurier per Greif los, um Rüstungen für Westfalls Garnison...",kw={"greif","lewis' notiz","limited immunity","die altstadt","osric strang","rüstmeister lewis","späherkuppe","thor"},ang={["race:Human"]="Wenn Ihr als menschlicher Abenteurer die Bestellung überbringt, lernt Ihr, die Greifenrouten des Königreichs zu nutzen. Dabei seht Ihr auch, wie wenig Sturmwinds Herrscher für die Ausrüstung von Westfalls Verteidigern tun."},sec={{t="Ein Ersuchen um Stahl",b="Die Volksmiliz auf der Späherkuppe erhält kaum Unterstützung von Sturmwinds Haus der Adligen. Scharmützel mit der Bruderschaft der Defias zehren weiter an ihrem knappen Ausrüstungsvorrat. Deshalb wendet sich Rüstmeister Lewis an private Händler, um die Verteidiger ausgerüstet zu halten. Seine Bestellung umgeht die militärischen Dienstwege des Königreichs. Ein Kurier der Allianz muss per Greif in die Altstadt fliegen und sie Osric Strang vorlegen, dem Inhaber von Limited Immunity."}},faq={{q="Was ist Lewis' Notiz?",a="Lewis' Notiz ist Rüstmeister Lewis' schriftliche Bestellung an Osric Strang, einen Rüstungsschmied in Sturmwind, mit der Bitte, Schutzausrüstung an die Garnison in Westfall zu schicken.",al={"was ist dieser gegenstand","lewis' notiz zweck","was bewirkt die notiz"}},{q="Wer hat diese Notiz geschrieben?",a="Rüstmeister Lewis hat die Notiz geschrieben. Er verwaltet Nachschub, Proviant und Bewaffnung für die Volksmiliz auf der Späherkuppe.",al={"wer ist lewis","rüstmeister lewis"}},{q="Wer erhält die Notiz?",a="Die Notiz geht zunächst an Thor, den Greifenmeister auf der Späherkuppe. Von dort gelangt sie zu Osric Strang in seinem Rüstungsgeschäft Limited Immunity in Sturmwinds Altstadt.",al={"wohin geht die notiz","wer bekommt lewis' notiz","osric strang notiz"}},{q="Warum bekommt die Garnison ihre Rüstungen nicht einfach vom Königreich?",a="Sturmwinds Regierung hat Westfall weitgehend vernachlässigt. Seine Verteidiger erhalten von der Krone weder direkte Militärgelder noch Rüstungen, weshalb Lewis auf Händler wie Osric Strang angewiesen ist, um die Miliz auszurüsten.",al={"warum bei osric kaufen","warum keine hilfe aus sturmwind","sturmwinds hilfe für westfall"}}},fp="11,153,16.423.0,20.153.0,20.125.0,22.166.0,57.204.0"}
P.entries["item:lieutenant-s-insignia"] = {n="Insigne des Leutnants",s="Nahe Orgrimmar tragen Kultisten das Insigne des Leutnants und das Zeichen der Burning Blade. Abenteurer der Horde erbeuten es von ihnen.",h="Nahe Orgrimmar tragen Kultisten das Insigne des Leutnants und das Zeichen der Burning Blade.",kw={"burning blade","die kluft der schatten","durotar","hidden enemies","insigne des leutnants","neeru fireblade","schattenrat","die knochenhöhle","thrall"},ang={["class:Warlock"]="Für einen Hexenmeister zeigt das Insigne des Leutnants, dass die Burning Blade Teufelsmagie in den Dienst der Brennenden Legion stellt. Das strapaziert Thralls Duldung gesetzestreuer Hexenmeister der Horde.",["faction:Horde"]="Für die junge Horde steht das Insigne des Leutnants für die Gefahr dämonischer Verderbnis, die Thralls neue Nation von innen zu untergraben versucht."},sec={{t="Ein Zeichen des Kults",b="Kultisten in der Knochenhöhle an Durotars Ostküste tragen das Insigne des Leutnants. Das Zeichen weist seinen Träger als Offizier der Burning Blade aus. Kriegshäuptling Thrall duldet keine Verräter in seiner neuen Nation. Doch eine Säuberung könnte den Kult zerstreuen, bevor seine Meister enttarnt werden. Deshalb vertraut er das Abzeichen einem Recken an, um jene zu prüfen, die im Verdacht stehen, Orgrimmars Untergrund unterwandert zu haben."},{t="Die Kluft der Schatten",b="Kriegshäuptling Thrall schickt seinen Agenten mit dem Insigne des Leutnants in die Kluft der Schatten, um es Neeru Feuerklinge zu zeigen. Neeru hält den Agenten für einen frisch beförderten Untergebenen. Seiner Stellung sicher, prahlt der Hexenmeister damit, dass die Burning Blade dem Schattenrat und der Brennenden Legion dient. Diese Worte geben Thrall eine Möglichkeit, die Verderbnis unter der Stadt aufzudecken."}},faq={{q="Woher stammt das Insigne des Leutnants?",a="Fanatiker und Lehrlinge der Burning Blade in der Knochenhöhle tragen das Insigne des Leutnants. Die Höhle liegt an Durotars Küste östlich von Orgrimmar.",al={"wie das insigne des leutnants erhalten","wer lässt das insigne des leutnants fallen","insigne des leutnants herkunft"}},{q="Wozu dient das Insigne?",a="Kriegshäuptling Thrall gibt seinem Agenten das Insigne des Leutnants zur Tarnung. Ein junger Abenteurer kann damit als Offizier der Burning Blade durchgehen und Orte erreichen, die Thralls Agenten verschlossen bleiben, um die Anführer des Kults aufzuspüren.",al={"wozu wird das insigne des leutnants benötigt","insigne des leutnants questverwendung","was mit dem insigne tun"}},{q="Wer ist Neeru Feuerklinge?",a="Neeru Feuerklinge ist ein orkischer Hexenmeister in Orgrimmars Kluft der Schatten. Er behauptet, Thrall zu dienen, indem er zeigt, wie Hexenmeister der Horde helfen können, führt aber insgeheim den örtlichen Kult der Burning Blade.",al={"wer ist neeru","neeru fireblade hintergrundgeschichte"}},{q="Warum tötet Thrall Neeru Feuerklinge nicht einfach sofort?",a="Thrall weiß, dass Neeru ein Verräter ist, doch ein verfrühter Schlag könnte die wahren Meister des Kults warnen und dessen Netzwerk zerstreuen. Er nutzt Neeru als unwissentlichen Informanten, um aufzudecken, wie weit der Schattenrat in Durotar verbreitet ist.",al={"warum thrall neeru nicht tötet","warum neeru am leben lassen","warum neeru unterwandern"}}},fx={["2e1cfb76"]={q="Was ist die Insigne des Leutnants?",a="Es ist ein Emblem, das von Offizieren innerhalb des Burning Blade-Kults getragen wird und den Träger als anerkannten Leutnant in ihren Rängen kennzeichnet. Für Dämonenkultisten, die im Verborgenen durch ganz Durotar operieren, signalisiert das Vorzeigen dieses Zeichens Loyalität, Status und Autorität innerhalb des Netzwerks des Schattenrats.",al={"was ist insigne des leutnants","insigne des leutnants was ist das","burning blade insigne"}}},fp="21,121,18.363.0,19.359.1,47.135.0,30.207.1,23.183.2,57.211.1"}
P.entries["item:lightning-gland"] = {n="Blitzschlagdrüse",s="Im ganzen Brachland tragen Stormhides Blitzschlagdrüsen, die Braumeister Drohn in Ratschet benötigt. Chen Stormstout lehrte Drohn, Trogg-Bier zu brauen, ein feuriges Gebräu.",h="Im ganzen Brachland tragen Stormhides Blitzschlagdrüsen, die Braumeister Drohn in Ratschet benötigt.",kw={"brachland","braumeister drohn","chen stormstout","blitzschlagdrüse","ratschet","stormhide","trogg-bier"},ang={["profession:Cooking"]="Als Koch könnt Ihr sehen, wie Braumeister Drohn und Chen Stormstout rohe Tierorgane in Spirituosen verwenden. Blitzschlagdrüsen sind keine gewöhnliche Nahrung."},sec={{t="Eine elektrisierende Zutat",b="Stormhides durchstreifen die Savannen des Brachlands zwischen anderen Raubtieren, die von den Elementen berührt wurden. Ihr Fleisch birgt Blitzschlagdrüsen, die mit latenter Elektrizität geladen sind. Für sich allein taugen die Drüsen kaum als Nahrung, doch Brauer schätzen das Prickeln, das sie einem Gebräu verleihen."},{t="Drohns Trogg-Bier",b="In Ratschet hält Braumeister Drohn die Brautraditionen von Chen Stormstout lebendig. Für Trogg-Bier, ein starkes Gebräu, benötigt er fünf Blitzschlagdrüsen, eine Donnerfalkenspeicheldrüse und eine frische Kodoleber. Der fertige Trank hat einen scharfen Biss, den Abenteurer als belebend und kräftig empfinden."}},faq={{q="Welche Kreaturen tragen Blitzschlagdrüsen?",a="Stormhides, die die Savannen des Brachlands durchstreifen, tragen Blitzschlagdrüsen.",al={"wo blitzschlagdrüse bekommen","wer hinterlässt blitzschlagdrüse","stormhide blitzschlagdrüse"}},{q="Wer braucht Blitzschlagdrüsen und warum?",a="Braumeister Drohn in Ratschet braucht Blitzschlagdrüsen für Trogg-Bier. Chen Stormstout, der wandernde Braumeister, hat ihm das Rezept beigebracht.",al={"wer braucht blitzschlagdrüse","blitzschlagdrüse abgeben","blitzschlagdrüse verwendung"}},{q="Was wird neben der Blitzschlagdrüse noch benötigt?",a="Drohn benötigt fünf Blitzschlagdrüsen, eine Donnerfalkenspeicheldrüse von greater thunderhawks und eine frische Kodoleber von den Wildtieren des Brachlands.",al={"drohn trogg-bier zutaten","chen's keg drei gegenstände"}}},fx={f0cc18d7={q="Was ist eine Blitzschlagdrüse?",a="Eine Blitzschlagdrüse ist ein Organ, das von Sturmfellbestien geerntet wird, die im Brachland umherstreifen. Die Drüse ist von den natürlichen elektrischen Energien durchdrungen, die durch diese Kreaturen fließen, und besitzt eine starke elementare Ladung, was sie als exotische Brauzutat wertvoll macht.",al={"was ist blitzschlagdrüse","blitzschlagdrüse wissen","was ist eine blitzschlagdrüse"}},ba679c5d={q="Woher kommt eine Blitzschlagdrüse?",a="Blitzschlagdrüsen werden nicht von sterblichen Händen gefertigt; es sind biologische Organe, die direkt von den Sturmfellbestien entnommen werden, die die Savannen des Brachlands durchstreifen. Diese wilden Bestien entwickeln die Drüsen auf natürliche Weise, um knisternde elektrische Energie zu kanalisieren.",al={"woher kommen blitzschlagdrüsen","herkunft blitzschlagdrüse","wie werden blitzschlagdrüsen hergestellt"}}},fp="15,155,21.241.0,17.277.0,38.63.0,35.131.0,50.143.0"}
P.entries["item:logging-rope"] = {n="Holzfällerseil",s="Im Holzfällerlager des Kriegshymnenklans hält Holzfällerseil die Sägewerke und Maschinen in Betrieb. Furbolgstämme haben in ganz Eschental Lieferungen gestohlen, und der Kriegshymnenklan muss das benötigte Tauwerk zurückholen.",h="Im Holzfällerlager des Kriegshymnenklans hält Holzfällerseil die Sägewerke und Maschinen in Betrieb.",kw={"eschental","foulweald","locke okarr","holzfällerseil","splitterholzposten","thistlefur","holzfällerlager des kriegshymnenklans","warsong supplies"},ang={["faction:Horde"]="Die Rückgewinnung von Holzfällerseil hilft, den Kriegshymnenklan trotz der Hinterhalte der Furbolgs weiter mit Holz zu versorgen.",["race:Orc"]="Als Orc seid Ihr für die Besiedlung Kalimdors auf Holz aus Eschental angewiesen. Gestohlene Holzfällervorräte bedrohen diese Arbeit."},sec={{t="Gestohlenes Tauwerk",b="Die Furbolgs der Foulweald und Thistlefur haben Lieferungen von Holzfällerseil gestohlen, die für das Holzfällerlager des Kriegshymnenklans bestimmt waren. Sie fingen das Tauwerk ab, bevor es die Holzfäller erreichen konnte. Die Seile werden in Dorfhöhlen und Lagern im nördlichen und zentralen Eschental aufbewahrt. Verderbnis hat die Furbolgs in den Wahnsinn getrieben, und sie verteidigen ihre angestammten Wälder erbittert."},{t="Nachschub für den Krieg",b="Am Splitterholzposten will Locke Okarr die gestohlenen Vorräte zurückholen, bevor die Arbeit im Holzfällerlager des Kriegshymnenklans zum Erliegen kommt. Das schwere Seil sichert Holz, bündelt Stämme und dient zum Verspannen der Sägemaschinen. Der Widerstand der Furbolgs hält im ganzen Wald an."}},faq={{q="Wofür wird Holzfällerseil verwendet?",a="Das Holzfällerlager des Kriegshymnenklans verwendet Holzfällerseil, um in Eschental geschlagenes Holz zu sichern, Stämme zu ziehen und schwere Maschinen zu verspannen.",al={"verwendung von holzfällerseil","warum der kriegshymnenklan seil braucht","holzfällerseil des kriegshymnenklans"}},{q="Wer hat das Holzfällerseil gestohlen?",a="Die Furbolgs der Foulweald und Thistlefur haben das Holzfällerseil gestohlen. Sie bewahren es in ihren Dorfhöhlen und Lagern in ganz Eschental auf.",al={"wer hat das seil genommen","seildieb","welche furbolgs haben seil"}},{q="Wer will dieses Seil zurück?",a="Locke Okarr am Splitterholzposten will das Seil zusammen mit den anderen gestohlenen Vorräten zurückhaben, damit die Arbeit im Holzfällerlager des Kriegshymnenklans weitergehen kann.",al={"wer braucht holzfällerseil","questgeber für holzfällerseil"}},{q="Warum stehlen die Furbolgs Holzfällervorräte?",a="Die Furbolgs stehlen Holzfällervorräte, um die Sägewerke der Horde zu stören und sich ihrem Holzeinschlag in ihren angestammten Wäldern zu widersetzen.",al={"motiv der furbolgs","warum furbolgs lieferungen angreifen"}}},fx={["26f07746"]={q="Was ist ein Holzfällerseil?",a="Ein Holzfällerseil ist ein hochbelastbares Tauwerk, das für die umfangreichen Holzarbeiten des Kriegshymnenklans im Eschental unerlässlich ist. Es wird zum Sichern, Ziehen und Binden massiver gefällter Bäume verwendet und ist ein unverzichtbarer Bestandteil der täglichen Ernte im Holzfällerlager.",al={"was ist holzfällerseil","holzfällerseil info","warsong holzfällerseil"}}},fp="12,184,12.342.0,24.231.0,30.118.0,27.130.0,25.136.0,43.120.0"}
P.entries["item:lok-s-skull"] = {n="Loks Schädel",s="Im südlichen Brachland steht Loks Schädel für den Fall eines gefürchteten Anführers der Razormane. Lok Orcbane führte heftige Stacheleberüberfälle auf die Versorgungsrouten der Horde an, und der Schädel ist sein abgetrennter Kopf.",h="Im südlichen Brachland steht Loks Schädel für den Fall eines gefürchteten Anführers der Razormane.",kw={"betrayal from within","camp taurajo","das wegekreuz","lok orcbane","loks schädel","quetschzahn","razormane","thork"},ang={["faction:Horde"]="Als Mitglied der Horde zerschlagt Ihr mit der Erbeutung von Lok Orcbanes Schädel die Führung der südlichen Stacheleber, die Versorgungskarawanen zwischen Camp Taurajo und dem Wegekreuz bedrängt.",["race:Orc"]="Als Ork sorgt Ihr mit dem Zurschaustellen des abgetrennten Kopfes eines Stacheleberhäuptlings namens 'Orcbane' für tiefe Genugtuung und Sicherheit bei den Verteidigern des Brachlands."},sec={{t="Der Fall eines Häuptlings",b="Lok Orcbane führte aggressive Angriffe der Razormane auf die Versorgungslinien der Horde im südlichen Brachland an. Er kam mit seinen Leutnanten Nak und Kuz aus dem Kral der Klingenhauer. Nachdem er Quetschzahn verraten und als Gefangenen in Camp Taurajo zurückgelassen hatte, wurde Lok bei den orkischen Verteidigern für rücksichtslose Überfälle berüchtigt, die sie kaum eindämmen konnten. Quetschzahn schickt Champions der Horde zu Loks Lager. Loks Schädel zu erbeuten, rächt den Gefangenen und trifft die Anführer, die die Offensive der Razormane vorantreiben."},{t="Beweis für das Wegekreuz",b="Quetschzahn fordert für seine Rache die Schädel aller drei Verschwörer. Dann schickt er Loks Schädel nach Norden zu Thork am Wegekreuz. Thork und die Führung der Horde hatten vermutet, dass ein anderer Stacheleber die Überfälle anführte. Loks Schädel war eine grimmige Überraschung und bewies, dass die Bedrohung für die zentralen Handelsrouten des Brachlands niedergestreckt worden war."}},faq={{q="Wer war Lok Orcbane?",a="Lok Orcbane war ein gefährlicher Krieger der Razormane, der aus dem Kral der Klingenhauer kam, um Stacheleberplünderer durch das südliche Brachland zu führen. Er hasste Orks und führte mit seinen vertrauten Verbündeten Nak und Kuz aggressive Angriffe auf Karawanen und Außenposten der Horde an.",al={"wer ist lok","lok orcbane hintergrundgeschichte","wer war lok orcbane"}},{q="Warum will Quetschzahn Loks Schädel?",a="Lok Orcbane und seine Gefährten verrieten Quetschzahn und ließen ihn zurück, sodass die Tauren in Camp Taurajo ihn gefangen nahmen und einsperrten. In der Gewissheit, dass sein eigener Tod nahe ist, sucht Quetschzahn Rache an denen, die ihn im Stich ließen. Er schickt Abenteurer der Horde los, um seine ehemaligen Kameraden zu töten.",al={"warum will quetschzahn den schädel","quetschzahns rache","warum lok töten"}},{q="Warum wird der Schädel zu Thork am Wegekreuz gebracht?",a="Thork leitet die Verteidigung des Wegekreuzes und bemüht sich, die Versorgungsrouten der Horde vor Stacheleberangriffen zu schützen. Loks Schädel beweist dem orkischen Kommandanten, dass der Anführer der Überfälle im Süden getötet wurde, was Reisenden in der Region Sicherheit bringt.",al={"warum den schädel zu thork bringen","thork loks schädel","wer bekommt loks schädel"}},{q="Wer waren Nak und Kuz?",a="Nak und Kuz führten an der Seite von Lok Orcbane Überfälle im südlichen Brachland an. Quetschzahn zufolge war einer ein Zauberwirker und der andere ein Fährtenleser, die Loks Stärke als Krieger bei Überfällen auf die Horde ergänzten.",al={"nak und kuz","lok orcbanes leutnante","kuz und nak"}}},fx={a8e2f7c2={q="Was ist Loks Schädel?",a="Loks Schädel ist der abgetrennte Kopf von Lok Orcbane, einem wilden Krieger, der rücksichtslose Überfälle der Razormane-Stacheleber auf die Versorgungsrouten der Horde im südlichen Brachland anführte. Als grimmiger Beweis für seinen Tod genommen, dient er sowohl als Instrument der Rache für einen verratenen Stammesangehörigen als auch als unbestreitbarer Beweis für die Verteidiger des Wegekreuzes, dass die Bedrohung beendet wurde.",al={"was ist loks schädel","loks schädel gegenstand","was ist dieser schädel"}},["4d726f58"]={q="Woher kommt Loks Schädel?",a="Er wird direkt von der Leiche des getöteten Lok Orcbane im südlichen Brachland genommen. Lok und seine Leutnants kamen aus dem Kral der Klingenhauer, um Überfalltrupps gegen die Horde zu organisieren, bis Quetschzahn, ein verstoßener Stacheleber im Camp Taurajo, ihre Festung verriet, sodass Lok zur Strecke gebracht werden konnte.",al={"woher kommt loks schädel","wer machte loks schädel","quelle von loks schädel"}}},fp="11,183,18.461.0,24.319.1,20.250.0,38.265.0,52.240.0,21.196.0"}
P.entries["item:lonebrow-s-journal"] = {n="Einbraues Tagebuch",s="Am Fuße des Großen Aufzugs hält Henrig Lonebrows Tagebuch seine letzte Reise fest. Er durchquerte das Brachland, während sich im Kral der Klingenhauer Gefahr zusammenbraute.",h="Am Fuße des Großen Aufzugs hält Henrig Lonebrows Tagebuch seine letzte Reise fest.",kw={"crone of the kraul","falfindel wegeshut","der große aufzug","henrig lonebrow","kral der klingenhauer","thalanaar","tausend nadeln"},ang={["faction:Alliance"]="Henrig Lonebrows letzte Aufzeichnungen verbinden die Späher der Allianz mit den Druiden, die die Grenze zu Feralas bewachen. Sie bringen Hilfe gegen die Bedrohung durch die Borstennacken.",["race:Dwarf"]="Der Fund eines gefallenen Zwergs in diesen abgelegenen, feindseligen Landen erinnert Euch an die Gefahren, denen zwergische Entdecker fern von Khaz Modan begegnen."},sec={{t="Ein letzter Wunsch am Großen Aufzug",b="Henrig Lonebrow starb nahe dem Fuß des Großen Aufzugs, dem Übergang zwischen dem Brachland und Tausend Nadeln. Seine Gebeine ruhen auf einem Felsvorsprung, das verwitterte Tagebuch noch immer fest im Griff.\n\nDie Seiten schildern seine letzten Reisen und bitten den Finder, Falfindel Wegeshut, einem Nachtelfendruiden in Thalanaar, Nachricht zu bringen. Der Außenposten liegt an der Grenze zu Feralas. Lonebrows Notizen warnen vor der wachsenden Bedrohung durch die Borstennacken im südlichen Brachland."},{t="Verbindungen zu Razorfen",b="Falfindel Wegeshut erhält Aufzeichnungen, die die Befürchtungen der Allianz über die Borstennacken im Kral der Klingenhauer bestätigen. Lonebrows Bericht fordert einen Angriff auf das Herz des dornigen Baus. Charlga Klingenflanke, The Crone of the Kraul, lenkt die Bedrohung."}},faq={{q="Wer war Henrig Lonebrow?",a="Henrig Lonebrow war ein zwergischer Reisender, der am Fuße des Großen Aufzugs in Tausend Nadeln starb. Sein Tagebuch blieb in seiner Hand und sollte seinen Bericht zu den Nachtelfen in Thalanaar tragen.",al={"henrig lonebrow","wer ist lonebrow","toter zwerg aufzug"}},{q="Wo ist das Tagebuch zu finden?",a="Das Tagebuch liegt neben Henrig Lonebrows Skelett auf einem niedrigen Felsvorsprung direkt neben der Rampe am Fuße des Großen Aufzugs im nördlichen Tausend Nadeln.",al={"wo ist einbraues tagebuch","einbraues tagebuch finden","skelett am großen aufzug"}},{q="Wer soll Einbraues Tagebuch erhalten?",a="Bringt Einbraues Tagebuch nach Westen durch Tausend Nadeln zu Falfindel Wegeshut, einem Nachtelfendruiden in Thalanaar an der Grenze zu Feralas.",al={"wem das tagebuch bringen","falfindel wegeshut","wo tagebuch abgeben"}},{q="Wozu führt das Tagebuch?",a="Das Tagebuch bringt Falfindel Wegeshut Nachricht über die Borstennacken. Sein Bericht fordert einen Angriff auf den Kral der Klingenhauer und Charlga Klingenflanke.",al={"crone of the kraul quest","einbraues tagebuch folgequest"}}},fx={a9190e03={q="Was ist Einbraues Tagebuch?",a="Einbraues Tagebuch ist ein verwittertes persönliches Logbuch, das in den skelettierten Händen des Zwergs Henrig Einbrau gefunden wurde. Es wurde am Fuß des Großen Aufzugs in Tausend Nadeln entdeckt und dokumentiert seine Reisen und letzten Wünsche, bevor er im Canyon sein Ende fand.",al={"einbraues tagebuch was ist das","was ist dieses buch","henrig einbraues tagebuch"}},["090ee1d4"]={q="Woher stammt Einbraues Tagebuch und wer hat es angefertigt?",a="Das Tagebuch wurde von Henrig Einbrau verfasst, einem zwergischen Reisenden, der durch die tückischen Canyons von Tausend Nadeln wanderte. Er trug es bis zu seinem Tod nahe der Basis des Großen Aufzugs bei sich, wo seine Überreste und der Band schließlich entdeckt wurden.",al={"wer schrieb einbraues tagebuch","einbraues tagebuch autor","woher kam das tagebuch"}},ea8f453f={q="Warum will jemand Einbraues Tagebuch?",a="Die Übergabe des Tagebuchs erfüllt die letzten Wünsche des gefallenen Zwergs. Falfindel Wegeshut, ein Nachtelf-Druide, der in Thalanaar an der Grenze zu Feralas stationiert ist, möchte dessen Inhalt lesen, um Henrigs Schicksal zu verstehen und die Gefahren aufzudecken, die im Kral der Klingenhauer schlummern.",al={"warum einbraues tagebuch überbringen","wer braucht einbraues tagebuch","warum einbraues tagebuch gesucht"}}},fp="18,144,30.432.0,20.245.1,24.192.0,27.150.0,38.134.0,30.133.1"}
P.entries["item:lorgalis-manuscript"] = {n="Manuskript von Lorgalis",s="Unter dem Eschental liegt das Manuskript von Lorgalis in den versunkenen Ruinen der Tiefschwarzen Grotte. Der uralte Text handelt von den Alten Göttern, und finstere Gelehrte begehren seine Worte über schlummernde Mächte.",h="Unter dem Eschental liegt das Manuskript von Lorgalis in den versunkenen Ruinen der Tiefschwarzen Grotte.",kw={"tiefschwarze grotte","forlorn cavern","gerrig knochengriff","eisenschmiede","lorgalis","manuskript","alter gott","those who sleep"},ang={["class:Warlock"]="Als Hexenmeister erhaltet Ihr einen seltenen Einblick in verbotene Überlieferungen über die Alten Götter und die Wesen der Tiefe, Wissen, das Anhänger der dunklen Künste begehren.",["race:NightElf"]="Als Nachtelf findet Ihr den Text in versunkenen Ruinen, in denen Euer Volk einst lebte. Seine Verehrung für Aku'mai und die Alten Götter offenbart den finsteren Kult, der in jenen verfallenen Hallen wurzelt."},sec={{t="Ein Foliant über Those Who Sleep",b="Das Manuskript von Lorgalis liegt auf dem Grund der Tiefschwarzen Grotte, zwischen den Ruinen, in denen einst längst verstorbene Elfen lebten. Lorgalis schrieb von den Alten Göttern, die über Azeroth wüteten, als die Welt noch jung war, und nun angekettet schlafen. Der Text preist Aku'mai, einen Diener der Alten Götter, der in der Grotte haust.\n\nSein Wissen soll mystische Pforten öffnen und uralte Wesen aufschrecken können, die tief unter der Welt schlafen. Das Manuskript ruht in einer zerfressenen Eisentruhe inmitten der überfluteten Gänge. Kultisten und Schattengelehrte suchen gleichermaßen nach seinen Worten."},{t="Augen in den Schatten",b="In der Forlorn Cavern von Eisenschmiede heuert der exzentrische Sammler Gerrig Knochengriff Abenteurer an, die das Meer überqueren und das Manuskript bergen sollen. Knochengriff spricht voller Ehrfurcht von den Tagen des Endes und dem Erwachen schlummernder Gottheiten. Er will den Text abschreiben und in seinem zwielichtigen Kreis von Brüdern und Schwestern verbreiten lassen, um verbotenes Wissen weiterzugeben, das die Oberflächenbewohner niemals verstehen sollten."}},faq={{q="Was ist das Manuskript von Lorgalis?",a="Das Manuskript von Lorgalis ist ein alter Text, den Lorgalis über die Alten Götter verfasst hat. Sein Inhalt soll offenbaren, wie sich Pforten öffnen und schlummernde Urwesen erwecken lassen.",al={"was ist das manuskript von lorgalis","lorgalis buch hintergrund","was bewirkt das manuskript"}},{q="Wo befindet sich das Manuskript?",a="Das Manuskript ruht in einer zerfressenen Eisentruhe tief in der Tiefschwarzen Grotte, einem verfallenen Nachtelfentempel am Zoramstrand im Eschental.",al={"wo ist das manuskript von lorgalis","manuskript fundort","tiefschwarze grotte truhe"}},{q="Wer will das Manuskript haben?",a="Gerrig Knochengriff wirkt von der Forlorn Cavern in Eisenschmiede aus und will das Manuskript bergen lassen. Er plant, es abzuschreiben und seine Lehren mit seinen verschwiegenen Gefährten zu teilen.",al={"wer will das manuskript von lorgalis","gerrig knochengriff quest","wer ist knochengriff"}},{q="Warum spricht Gerrig Knochengriff von den Tagen des Endes?",a="Knochengriff verehrt und erforscht die Alten Götter. Er sucht nach uralten elfischen Schriften über das Erwachen von Those Who Sleep, das seiner Ansicht nach die nahende Endzeit ankündigt.",al={"gerrig tage des endes","knochengriff kultist","knochengriff alte götter"}}},fx={["61ae2bf7"]={q="Woher kommt das Manuskript von Lorgalis und wer hat es verfasst?",a="Das Manuskript wurde von einem gewissen Lorgalis verfasst und liegt auf dem Grund der Tiefschwarzen Grotte, den versunkenen Ruinen, in denen einst längst verstorbene Elfen lebten, bevor ihre Stadt fiel. Wer Lorgalis war, ist nicht überliefert. Der Text hält verbotene Kunde über die Alten Götter und Those Who Sleep fest und preist Aku'mai, einen Diener der Alten Götter, der in der Grotte haust. Es ruht verschlossen in einer narbigen Eisentruhe in den überfluteten Hallen.",al={"herkunft des manuskripts von lorgalis","wer schrieb das manuskript von lorgalis","wo wurde das manuskript von lorgalis hergestellt"}}},fp="19,187,25.525.0,19.394.1,32.172.0,32.139.0,25.164.0,49.155.0"}
P.entries["item:lunar-fungus"] = {n="Lunarfungus",s="In den Höhlen der Dunkelküste sammeln Druiden Lunarfungus, um kranke Hirsche zu heilen. Mit Earthroot und Wasser vermischt, verstärkt er eine Heilsalbe.",h="In den Höhlen der Dunkelküste sammeln Druiden Lunarfungus, um kranke Hirsche zu heilen.",kw={"alanndarian nachtweise","auberdine","gift heilen","dunkelküste","earthroot","lunarfungusblüte","lunarfungus"},ang={["class:Druid"]="Als junger Druide sucht Ihr in den Höhlen der Dunkelküste nach Lunarfungus, während Ihr erste Kenntnisse in Heilmagie und der Heilung vergifteter Wildtiere erwerbt.",["race:NightElf"]="Als Nachtelf helft Ihr, verderbte Waldkreaturen rund um Auberdine mit einheimischen Heilmitteln wie Lunarfungus zu versorgen."},sec={{t="Eigenschaften und Ökologie",b="Lunarfungus wächst aus Lunarfungusblüten in den unterirdischen Höhlen der Dunkelküste. Der Zirkel des Cenarius schätzt seine Fähigkeit, Heilmittel zu verstärken. Mit linderndem Wasser und gewöhnlicher Earthroot vermischt, verstärkt er eine Salbe gegen schwächende Leiden. Revierverteidigende Mondpirscher halten sich oft in den feuchten Höhlen auf, weshalb das Sammeln des Pilzes Vorsicht erfordert."},{t="Eine Lektion im Heilen",b="In Auberdine lässt Alanndarian Nachtweise junge Druiden Lunarfungus sammeln, während sie die Heilkunst der Natur studieren. Sie lernen, wie stoffliche Zutaten wie dieser Pilz Giften in einheimischen Hirschen entgegenwirken können. Durch das Studium pflanzlicher Heilmittel bereiten sich Initianden darauf vor, natürliche Gegengifte durch Gestaltwandel und spirituelle Kraft zu kanalisieren."}},faq={{q="Wofür wird Lunarfungus verwendet?",a="Lunarfungus verstärkt eine Heilsalbe. Alanndarian Nachtweise mischt ihn mit Earthroot und sauberem Wasser, um kranke Hirsche in der Dunkelküste zu behandeln.",al={"lunarfungus verwendung","was bewirkt lunarfungus","warum lunarfungus sammeln"}},{q="Wo wächst Lunarfungus?",a="Lunarfungus wächst aus Lunarfungusblüten in Höhlen östlich von Auberdine in der Dunkelküste. Reizbare Mondpirscher leben ebenfalls in diesen Höhlen und verteidigen ihr Revier gegen Eindringlinge.",al={"lunarfungus fundort","wo lunarfungus finden","lunarfungusblüten"}},{q="Wer benötigt diesen Pilz in Auberdine?",a="Alanndarian Nachtweise bittet Schüler der Wildnis, im Rahmen ihrer Ausbildung Lunarfungus zu sammeln. Der Pilz wird für Heilmittel für kranke Waldtiere verwendet.",al={"wer braucht lunarfungus","auberdine kräuterquest"}},{q="Warum müssen Druideninitianden echte Kräuter sammeln, um Gift zu heilen?",a="Zu lernen, wie stoffliche Gegengifte wirken, ist ein grundlegender Teil der druidischen Ausbildung. Indem Schüler Kräuter wie Lunarfungus sammeln und beobachten, wie sie Giften entgegenwirken, lernen sie die Grundlagen des Heilens, bevor sie Gifte durch spirituelle Magie beseitigen.",al={"warum druiden kräuter sammeln","druiden ausbildung zur giftheilung"}}},fx={["2a41e7eb"]={q="Was ist ein Lunarfungus?",a="Ein Lunarfungus ist ein starker medizinischer Pilz, der an der Dunkelküste heimisch ist. Er gedeiht in dunklen Höhlen östlich von Auberdine und wird von größeren Clustern geerntet, die als Lunarfungus-Blüten bekannt sind. Druiden schätzen den Pilz für seine natürliche Wirksamkeit und verwenden seine Eigenschaften als wesentliche Zutat beim Brauen alchemistischer Salben zur Behandlung vergifteter Wildtiere.",al={"was ist lunarfungus","lunarfungus info","über lunarfungus"}}},fp="12,136,22.338.0,19.318.0,30.136.0,29.166.0,38.154.0,68.254.0"}
P.entries["item:lurker-venom"] = {n="Lauerergift",s="In Loch Modan brauchen zwergische Verteidiger Lauerergift gegen die Sabotage der Dunkeleisenzwerge. Räuberische Spinnen in den felsigen Hügeln und Wäldern liefern das Gift.",h="In Loch Modan brauchen zwergische Verteidiger Lauerergift gegen die Sabotage der Dunkeleisenzwerge.",kw={"chefingenieur hinderweir","cliff lurker","loch modan","lauerergift","shanda the spinner","spinnengift","der steinwerkdamm","waldlauerer"},ang={["profession:Engineering"]="Der Einsatz organischer Gifte zum Unschädlichmachen feindlicher Sprengsätze zeigt, wie zwergische Ingenieure im Kampf mit reaktiven Stoffen improvisieren.",["race:Dwarf"]="Als Zwerg wisst Ihr, dass Loch Modans Gebirgsjäger und Verteidiger Gefahren der heimischen Wildnis nutzen, um lebenswichtige Bauwerke Khaz Modans vor dem Klan der Dunkeleisenzwerge zu schützen."},sec={{t="Ein flüchtiges Reagenz",b="Lauerergift hilft Zwergen, die von Dunkeleisenzwergen gelegten Sprengsätze zu entschärfen. Ashlan Schmunzelstein, ein Sprengstoffexperte, benannte Spinnengift als Zutat für die Mischung, die Chefingenieur Hinderweir zubereitet. Das Lösungsmittel verbindet das Gift mit seltenen Mineralien und Tränen der Krokilisken des Lochs. Gemeinsam bilden sie eine reaktive Verbindung, die komplexe Sprengsätze entschärfen kann.\n\nDie Lauererspinnen reichen von gewöhnlichen Waldlauerern bis zur Matriarchin Shanda the Spinner. Ihre Bisse bedrohen Reisende und Gebirgsjäger in den Hügeln und zerklüfteten Felsen von Loch Modan."}},faq={{q="Woher stammt Lauerergift?",a="Die Lauererspinnen von Loch Modan liefern das Gift. Zu ihnen gehören Cliff Lurkers, Forest Lurkers, Waldlauerer und ihre Matriarchin Shanda the Spinner.",al={"wie lauerergift bekommen","wer lässt lauerergift fallen","wo lauerergift finden"}},{q="Wofür wird Lauerergift verwendet?",a="Chefingenieur Hinderweir verwendet das Gift in einer chemischen Mischung, um Sprengsätze zu neutralisieren und zu entschärfen, die Dunkeleisenzwerge als Infiltratoren rund um den Steinwerkdamm platzieren.",al={"warum brauche ich lauerergift","lauerergift verwendung","was macht hinderweir mit dem gift"}},{q="Warum wird Gift zum Entschärfen eines Sprengsatzes verwendet?",a="Zwergische Ingenieure verwenden reaktive, säurehaltige oder ätzende Mischungen, um empfindliche mechanische Teile aufzulösen oder instabile Sprengpulver zu neutralisieren, ohne sie zu zünden.",al={"warum spinnengift für bomben","wie entschärft gift bomben der dunkeleisenzwerge"}},{q="Ist Shanda the Spinner die einzige Quelle?",a="Shanda the Spinner trägt das Gift in sich, doch auch gewöhnliche wilde Lauererspinnen in den Wäldern und Felsklippen von Loch Modan können es liefern.",al={"muss ich shanda töten","shanda lauerergift"}}},fx={["0e11e6d3"]={q="Was ist Lauerergift?",a="Lauerergift ist ein starkes natürliches Toxin, das von den räuberischen Lauererspinnen geerntet wird, die in der zerklüfteten Wildnis von Loch Modan heimisch sind. Obwohl es für Beutetiere tödlich ist, machen seine ausgeprägten chemischen Eigenschaften es für spezialisierte Handwerker und Ingenieure wertvoll. Chefingenieur Hinderweir verwendet die flüchtige Flüssigkeit speziell als entscheidendes Reagenz in einem alchemistischen Neutralisierungslösungsmittel, das dazu dient, Sprengstoffe der Dunkeleisenzwerge sicher zu entschärfen.",al={"was ist lauerergift","lauerergift wissen","welche art von gegenstand ist lauerergift"}}},fp="12,147,18.533.0,34.147.0,30.160.0,37.163.0,38.133.0"}
P.entries["item:lydon-s-toxin"] = {n="Lydons Toxin",s="In Tarrens Mühle hat Apotheker Lydon ein Toxin entwickelt, um die Abholzung durch die Venture Company im Steinkrallengebirge zu stören. Abenteurer der Horde bringen es zu Apothekerin Zamah in Donnerfels, die einen Weg finden muss, es zu verbreiten.",h="In Tarrens Mühle hat Apotheker Lydon ein Toxin entwickelt, um die Abholzung durch die Venture Company im...",kw={"apotheker lydon","apothecary zamah","lydons toxin","königliche apothekervereinigung","donnerfels","toxinvernebler","venture company"},ang={["race:Tauren"]="Die Tauren begrüßen Hilfe gegen die Naturzerstörung durch die Venture Company. Doch die chemischen Methoden der Königlichen Apothekervereinigung stellen ihr schamanisches Empfinden auf die Probe.",["race:Undead"]="Der Transport von Lydons Toxin zeigt, wie weit das Netzwerk der Königlichen Apothekervereinigung reicht. Sie koordiniert die Feldforschung zwischen Lordaeron und Kalimdor und zeigt damit den Verbündeten der Verlassenen deren Nutzen."},sec={{t="Eine königliche Apothekerlösung",b="Apotheker Lydon entwickelte das Toxin im Vorgebirge des Hügellands, um Holzfäller der Venture Company im Steinkrallengebirge zu behindern. Er sagt, es tötet bei Kontakt und kann von einem Ziel auf ein anderes übergehen.\n\nBevor das Gemisch die Goblins nahe der Scherwindklippe erreichen kann, muss es über Kontinente hinweg nach Donnerfels gelangen. Dort benötigt Apothekerin Zamah, die Vertreterin der Königlichen Apothekervereinigung, das rohe Toxin, um ein Gerät zur großflächigen Verteilung namens Toxinvernebler zu entwickeln."}},faq={{q="Wofür wird Lydons Toxin verwendet?",a="Apotheker Lydon entwickelte das Toxin, um die Arbeit der Venture Company rund um die Scherwindklippe zu stören. Es tötet bei Kontakt und kann sich unter den Goblinarbeitern verbreiten.",al={"lydons toxin zweck","was bewirkt das toxin","warum lydons toxin herstellen"}},{q="Wer ist Apotheker Lydon?",a="Apotheker Lydon ist ein Mitglied der Königlichen Apothekervereinigung, das in Tarrens Mühle im Vorgebirge des Hügellands stationiert ist. Er stellt hochwirksame Gifte und experimentelle Verbindungen für die Ziele der Verlassenen her.",al={"wer ist lydon","apotheker lydon","lydon schöpfer"}},{q="Warum muss das Toxin nach Donnerfels gebracht werden?",a="Apothekerin Zamah in Donnerfels benötigt das Toxin, weil es sich noch nicht großflächig verteilen lässt. Sie erforscht die regionale Pflanzenwelt und koordiniert die Arbeit der Vereinigung in Kalimdor. Sie passt das Gemisch für den Einsatz in einem tragbaren Vernebelungsgerät an.",al={"warum donnerfels","warum toxin zu zamah bringen","apothecary zamah aufgabe"}},{q="Was geschieht, nachdem Zamah das Toxin erhalten hat?",a="Apothekerin Zamah verarbeitet das Toxin für ein druckbetriebenes Aerosolgerät namens Toxinvernebler. Ein Agent kann damit das Toxin im Lager der Venture Company verteilen.",al={"toxinvernebler herstellung","was macht zamah mit dem toxin"}}},fx={["73882111"]={q="Was ist Lydons Toxin?",a="Lydons Toxin ist ein virulentes alchemistisches Gebräu, das von Apotheker Lydon von der Königlichen Apothekervereinigung formuliert wurde. Die Substanz wurde speziell für den Einsatz gegen die von Goblins geführte Venture Company entwickelt und ist darauf ausgelegt, verheerende und potenziell ansteckende Ergebnisse zu erzielen, wenn sie gegen feindliche Ränge eingesetzt wird.",al={"was ist lydons toxin","lydon toxin","über lydons toxin"}},["105322cc"]={q="Warum will jemand Lydons Toxin?",a="Die Apotheker der Verlassenen und ihre Verbündeten der Horde wollen das Toxin, um die vordringenden Agenten der Venture Company auszurotten. Apothekerin Zamah benötigt Lydons Gebräu, damit sie einen effektiven Verteilungsmechanismus konstruieren kann, der es der Horde ermöglicht, dessen tödliche, ansteckende Wirkung über feindliche Arbeitsstätten zu verteilen.",al={"warum will man lydons toxin","warum wird das toxin benötigt","zweck von lydons toxin"}}},fp="13,212,27.420.0,31.148.0,24.179.0,47.216.0,44.177.0"}
P.entries["item:macgrann-s-dried-meats"] = {n="MacGranns Trockenfleisch",s="In Dun Morogh hat Alteisbart Tundra MacGranns Fleischvorrat für den Winter fortgeschleppt.",h="In Dun Morogh hat Alteisbart Tundra MacGranns Fleischvorrat für den Winter fortgeschleppt.",kw={"frosthauchtal","dun morogh","macgranns trockenfleisch","fleischkasten","alteisbart","tundra macgrann"},ang={["profession:Cooking"]="Als Koch könnt Ihr Wildfleisch einsalzen und pökeln, um es in Dun Moroghs eisiger Kälte haltbar zu machen. Jäger wie MacGrann sind darauf angewiesen, um Nahrung für den Winter aufzubewahren.",["race:Dwarf"]="Als Zwerg wisst Ihr, dass Vorbereitung in den hohen Gipfeln Überleben bedeutet. Der Verlust eines Wintervorrats kann über Leben und Tod entscheiden."},sec={{t="Ein Wintervorrat",b="Tundra MacGrann jagte Wild und salzte es für den Winter ein. Er verstaute Proviant für mehrere Wochen in einer stabilen Truhe in einem Fleischkasten aus Thorium, um plündernde Bären und umherstreifende Raubtiere von seinem Gehöft fernzuhalten. Doch er rechnete nie mit einem Eindringling, der stark genug war, die ganze Truhe fortzutragen."},{t="In die Höhle des Yetis",b="Alteisbart überfiel MacGranns Lager, während der Zwerg Hirsche aufspürte. Der Yeti schleppte die schwere Truhe in seine Höhle im Frosthauchtal. Ihre massive Thoriumpanzerung hält stand, doch MacGranns verletztes Bein hindert ihn daran, den Vorrat rasch aus der Höhle zu retten. Ohne Hilfe bei der Bergung seines Vorrats vor dem Winter droht dem gestrandeten Jäger im Schnee der Berge der Hungertod."}},faq={{q="Was ist MacGranns Trockenfleisch?",a="Tundra MacGrann salzte Proviant für einen Monat ein und machte ihn haltbar, um damit den Winter in Dun Morogh zu überstehen.",al={"was ist macgranns trockenfleisch","tundras fleisch","macgranns fleischvorrat"}},{q="Warum war das Fleisch in einer Truhe eingeschlossen?",a="Hungrige Raubtiere in Dun Morogh, darunter Bergbären, könnten sich über das Trockenfleisch hermachen. MacGrann schloss seinen Wintervorrat in einem verstärkten Fleischkasten aus Thorium ein, um sie fernzuhalten.",al={"warum das fleisch einschließen","warum ein fleischkasten aus thorium","macgranns truhe"}},{q="Wer hat den Fleischkasten gestohlen?",a="Alteisbart stahl den ganzen Fleischkasten, während MacGrann auf Hirschjagd war, und schleppte ihn dann in seine Höhle im Frosthauchtal.",al={"wer hat das fleisch genommen","wer hat es gestohlen","dieb des fleischkastens"}},{q="Warum kann Tundra MacGrann sein Fleisch nicht selbst zurückholen?",a="Sein Bein ist verletzt, deshalb kann er nicht selbst in Alteisbarts Höhle gehen und die Truhe hinaustragen.",al={"warum holt macgrann es nicht","warum braucht tundra hilfe","tundra verletzt"}}},fx={["6a0307bf"]={q="Warum möchte Tundra MacGrann sein getrocknetes Fleisch zurück?",a="Ohne diesen konservierten Vorrat droht Tundra MacGrann der Hungertod, wenn die schweren Schneestürme über Dun Morogh hinwegfegen. Es handelt sich um einen ganzen Monatsvorrat an gesalzenen Vorräten. Da ihn ein schlechtes Bein daran hindert, sich in Old Icebeards Höhle zu wagen, um es zu holen, ist die Bergung des Fleisches für sein Überleben im kommenden Winter von entscheidender Bedeutung.",al={"warum will tundra das fleisch","warum das getrocknete fleisch holen","warum wird macgranns fleisch benötigt"}},["1f8f3b04"]={q="Woher stammt MacGranns Trockenfleisch und wer hat es zubereitet?",a="Dieses Trockenfleisch wurde von Tundra MacGrann, einem Bergsteiger, der draußen in der kalten Wildnis von Dun Morogh lebt, zubereitet und gesalzen. Er pökelte Rationen für einen ganzen Monat, um durch die bevorstehende raue Frostsaison zu kommen, und lagerte sie sorgfältig in einem schweren Thoriumschließfach, bevor die lokale Bestie Old Icebeard eingriff.",al={"wer machte macgranns trockenfleisch","woher kam das trockenfleisch","macgrann fleisch herkunft"}}},fp="22,76,14.284.0,20.360.0,32.102.0,37.177.0,26.124.0,53.94.0"}
P.entries["item:mackreel-s-moonshine"] = {n="MacKreels Fusel",s="Auf dem zerstörten Thandol-Übergang braut Dunst MacKreel Fusel, der stark genug ist, einen Wachposten umzuhauen. Braumeister Bilger in Süderstade nimmt eine Ladung an, um Dunsts Schulden zu begleichen.",h="Auf dem zerstörten Thandol-Übergang braut Dunst MacKreel Fusel, der stark genug ist, einen Wachposten...",kw={"braumeister bilger","zwergengebräu","dunst mackreel","mackreels fusel","fusel","süderstade","sumpfland"},ang={["profession:Cooking"]="Als Koch wisst Ihr, dass starke regionale Branntweine wie Dunsts rauer Fusel zu den üblichen Handelswaren in Grenzlandtavernen gehören.",["race:Dwarf"]="Als Zwerg erkennt Ihr einen guten, kräftigen Schnaps schon am Geruch. Dunsts Fusel hat genug Wucht, um einen Gebirgsjäger umzuhauen."},sec={{t="Ein starkes Gebräu",b="Dunst MacKreel braut Fusel, während er den Thandol-Übergang bewacht. Selbst abgehärtete Zwergenwachen kann es nach einer durchzechten Nacht damit umhauen. Sie erwachen mit Kopfschmerzen, als rollten Belagerungsmaschinen über ihre Köpfe hinweg. Reisende schätzen seine wärmende Wirkung gegen die feuchte Kälte von Lordaeron und Khaz Modan."},{t="Bezahlung nach Süderstade",b="Dunst MacKreel hatte Schulden bei Braumeister Bilger, dem Gastwirt und Meisterbrauer von Süderstade. Er schickte eine Ladung Fusel statt Münzen, um seine Zeche zu begleichen. Bilger nimmt den Schnaps anstelle von Gold an und ergänzt damit seinen Vorrat für die kühlen Küstentage im Vorgebirge des Hügellands."}},faq={{q="Wer stellt MacKreels Fusel her?",a="Dunst MacKreel, eine Zwergenwache auf dem zerstörten Thandol-Übergang zwischen dem Sumpfland und dem Arathihochland, brennt den Fusel.",al={"hersteller von mackreels fusel","wer hat ihn gebraut","dunst mackreels schnaps"}},{q="Warum wird dieser Fusel nach Süderstade geschickt?",a="Dunst MacKreel hatte Schulden bei Braumeister Bilger in Süderstade. Er erklärte sich bereit, sie mit einer frischen Ladung Fusel statt Münzen zu begleichen.",al={"warum süderstade","fusellieferung","schulden bei braumeister bilger"}},{q="Wie stark ist MacKreels Fusel?",a="MacKreels Fusel ist außergewöhnlich stark. Dunst gab zu, nach dem Trinken im Dienst ohnmächtig geworden und mit Kopfschmerzen aufgewacht zu sein, als donnerten Belagerungsmaschinen über seinen Schädel.",al={"wie stark ist er","stärke des fusels","wirkung von mackreels fusel"}},{q="Warum muss die Lieferung so eilig erfolgen?",a="Dunst trank reichlich und verschlief seine Wache. Als er erwachte, blieben nur noch wenige Minuten, um seine Schulden bei Braumeister Bilger fristgerecht zu begleichen.",al={"warum zeitbegrenzung","ist die quest zeitbegrenzt","warum die eile"}}},fx={abca7076={q="Was ist MacKreels Fusel?",a="MacKreels Fusel ist ein starker, handgemachter Schnaps, der von Dunst MacKreel im Sumpfland gebraut wird. Er ist berüchtigt dafür, eine gewaltige Wirkung zu haben, und ist stark genug, um selbst einen robusten Zwerg einen Kater erleiden zu lassen, der sich anfühlt, als wäre eine Brigade von Belagerungsmaschinen über seinen Kopf hinweggerollt. Neben seiner beachtlichen Wirkung dient er als wertvolles Tauschmittel, das selbst im weit entfernten Norden im Vorgebirge des Hügellands gesucht wird, um die Leute an kalten Tagen zu wärmen.",al={"was ist mackreels fusel","mackreels fusel","getränk von dunst mackreel"}}},fp="20,161,13.281.0,21.302.0,31.138.0,47.148.0,35.182.0,40.134.0"}
P.entries["item:maggot-eye-s-paw"] = {n="Madenauges Tatze",s="Bei Garrens Schlupfwinkel bestätigt Madenauges Tatze die Hinrichtung des Gnollhäuptlings. Sie wird als Beweis dafür nach Brill gebracht, dass er Leichen für die Geißel stahl.",h="Bei Garrens Schlupfwinkel bestätigt Madenauges Tatze die Hinrichtung des Gnollhäuptlings.",kw={"kopfgeld","brill","exekutor zygand","garrens schlupfwinkel","gnoll","maggot eye","madenauges tatze","tirisfal"},ang={["race:Undead"]="Als Verlassener aus Brill versetzt Ihr mit der Rückkehr von Madenauges Tatze den Leichendieben einen Schlag, die den verhassten Lichkönig beliefern."},sec={{t="Beweis der Hinrichtung",b="Maggot Eye plünderte Gräber und das Umland von Garrens Schlupfwinkel. Er lieferte die gestohlenen Leichen an die Armeen des Lichkönigs. Deshalb verurteilten ihn die Verlassenen zum Tode und setzten in Brill ein Kopfgeld auf ihn aus. Jäger müssen seine abgetrennte Tatze in die Stadt zurückbringen, um das Kopfgeld einzufordern und die Angelegenheit abzuschließen. Exekutor Zygand nimmt die Tatze als Beweis für Maggot Eyes Tod an, nicht bloße Gerüchte."}},faq={{q="Warum will Exekutor Zygand Madenauges Tatze?",a="Exekutor Zygand will Madenauges Tatze als Beweis dafür, dass der verurteilte Gnoll getötet wurde. Brill zahlt das Kopfgeld aus, sobald seine Hinrichtung bestätigt ist.",al={"warum tatze","maggot eye kopfgeld beweis","zygand tatze"}},{q="Welche Verbrechen hat Maggot Eye gegen die Verlassenen begangen?",a="Maggot Eye führte Raubzüge im nördlichen Tirisfal an und stahl begrabene Leichen von Gehöften wie Garrens Schlupfwinkel. Er lieferte die Leichen an die Armeen des Lichkönigs.",al={"maggot eye verbrechen","warum wird maggot eye gesucht","was hat maggot eye getan"}},{q="Wo ist Maggot Eye zu finden?",a="Maggot Eye ist bei Garrens Schlupfwinkel zu finden, einem verfallenen Gehöft nördlich von Brill in Tirisfal. Meist lauert er im verfallenen Bauernhaus.",al={"maggot eye aufenthaltsort","wo maggot eye finden","garrens schlupfwinkel gnoll"}},{q="Warum arbeiten Gnolle mit den Streitkräften des Lichkönigs zusammen?",a="In Tirisfal haben sich abtrünnige Gnollbanden mit der Geißel verbündet oder sind unter ihren Einfluss geraten. Sie plündern Gräber von Menschen und Verlassenen und liefern die Leichen an Nekromanten.",al={"gnolle und geißel","warum stehlen gnolle leichen","geißel gnolle"}}},fx={["9017e45e"]={q="Was ist Madenauges Tatze?",a="Es ist die abgetrennte Tatze des berüchtigten Gnolls Madenauge. Sie mitzunehmen dient den Behörden in Brill als unbestreitbarer, physischer Beweis für die Hinrichtung der Bestie.",al={"was ist madenauges tatze","tatze von madenauge","was ist diese tatze"}},e496e47e={q="Woher stammt Madenauges Tatze und wer hat sie hergestellt?",a="Es handelt sich nicht um ein handgefertigtes Artefakt, sondern um eine Trophäe, die direkt aus dem Kadaver von Madenauge selbst herausgeschnitten wurde, einem heimtückischen Gnoll, der in der Nähe von Garrens Schlupfwinkel in Tirisfal sein Unwesen treibt.",al={"woher stammt madenauges tatze","herkunft von madenauges tatze","wer hat madenauges tatze gemacht"}}},fp="16,148,18.356.0,47.139.0,55.167.0,26.138.0,51.166.0"}
P.entries["item:maggran-s-reserve-letter"] = {n="Maggrans Reservebrief",s="In Sonnenfels schickt Maggran Erdbinder einen Reservekrieger nach Süden, um Grish Fernläufer am Großen Aufzug abzulösen. Die Befehle erlauben Grish, heimzukehren und seine Familie zu besuchen.",h="In Sonnenfels schickt Maggran Erdbinder einen Reservekrieger nach Süden, um Grish Fernläufer am Großen Aufzug...",kw={"brachland","erdbinder","grish","brief","aufzug","fernläufer","maggran","reserve","steinkrallengebirge"},ang={["faction:Horde"]="Als Mitglied der Horde könnt Ihr sehen, wie sie frische Reserven zu entlegenen Außenposten in ganz Kalimdor schickt, um für ihre verstreuten Truppen zu sorgen."},sec={{t="Ein Wachposten wird abgelöst",b="Von Sonnenfels aus schickt Maggran Erdbinder Befehle zum Großen Aufzug. Grish Fernläufer, ein dortiger Wachposten der Horde, soll von einem Ersatzkrieger abgelöst werden.\n\nDie hölzernen Seilwinden des Großen Aufzugs stehen weit im Süden. Grish hat dort Wache gehalten, doch nun übernimmt der neue Krieger seinen Platz. Grish kann seinen Posten verlassen und heimkehren, um seine Familie zu besuchen."}},faq={{q="Welchen Zweck hat Maggrans Reservebrief?",a="Maggran Erdbinders Befehle entbinden Grish Fernläufer von seinem Dienst am Großen Aufzug im südlichen Brachland. Ein Ersatz übernimmt seinen Platz, damit Grish heimkehren und seine Familie besuchen kann.",al={"was bewirkt dieser brief","maggran brief zweck","warum den brief überbringen"}},{q="Wer hat den Brief geschrieben?",a="Maggran Erdbinder hat den Brief geschrieben. Er ist ein Ältester in Sonnenfels im Steinkrallengebirge.",al={"wer hat ihn geschrieben","verfasser des reservebriefs","maggran erdbinder"}},{q="Wer soll ihn erhalten?",a="Der Brief ist an Grish Fernläufer gerichtet, einen Wächter der Horde, der am oberen Ende des Großen Aufzugs stationiert ist. Der Aufzug verbindet das südliche Brachland mit Tausend Nadeln.",al={"wer bekommt den brief","briefempfänger","wohin geht er"}},{q="Wohin wird der Brief gebracht?",a="Bringt den Brief nach Süden durch das Brachland bis zum Rand der Schlucht von Tausend Nadeln, wo der Große Aufzug steht.",al={"zustellungsort","wo ist grish","standort des großen aufzugs"}}},fx={["419ae143"]={q="Was ist Maggrans Reservebrief?",a="Es ist eine offizielle schriftliche Depesche, die von Maggran Erdbinder im Sonnenfels im Steinkrallengebirge verfasst wurde. Die Nachricht informiert einen stationierten Wächter der Horde, Grish Fernläufer, darüber, dass ein Entsatzkrieger aus den Reserven entsandt wird, um seinen Posten zu übernehmen, was ihm Urlaub gewährt, um seine Familie zu besuchen.",al={"was ist maggrans reservebrief","maggrans brief","reservebrief"}},eb8a36e5={q="Warum möchte Grish Fernläufer Maggrans Reservebrief?",a="Grish hat schon vor langer Zeit um Ablösung von seinem Posten gebeten und sehnt sich nach Neuigkeiten. Die Bewachung des Großen Aufzugs im südlichen Brachland ist eine monotone Pflicht, und dieser Brief autorisiert offiziell seine Ablösung durch einen Reservekrieger und gewährt ihm endlich die lang ersehnte Zeit, um seine Familie zu besuchen.",al={"warum will grish den brief","warum ist der reservebrief gesucht","warum wird maggrans reservebrief benötigt"}}},fp="24,172,17.346.0,48.187.0,21.101.0,27.158.0,30.114.0"}
P.entries["item:mangy-claw"] = {n="Räudige Klaue",s="In Dun Morogh markiert die Räudige Klaue das Ende einer tödlichen Jagd. Der große Eiskrallenbär Mangeclaw tötete einen gestrandeten Zwergenpiloten, und die abgetrennte Klaue beweist, dass die Bestie erlegt wurde.",h="In Dun Morogh markiert die Räudige Klaue das Ende einer tödlichen Jagd.",kw={"dun morogh","hildelve","eiskrallenbär","mangeclaw","räudige klaue","pilot hammerfuß","belagerungsbrigade"},ang={["class:Hunter"]="Als Jäger stellt Ihr beim Aufspüren von Mangeclaw in den erbarmungslosen Schneestürmen der Berge von Dun Morogh Euer Können gegen gefährliche, revierverteidigende Bestien auf die Probe.",["race:Dwarf"]="Als Zwerg ist es für Eure persönliche Ehre und die Ehre Eures Klans von großer Bedeutung, den letzten Wunsch eines gefallenen Kameraden zu erfüllen und ein Mitglied der Belagerungsbrigade von Eisenschmiede zu rächen."},sec={{t="Der letzte Wunsch eines Piloten",b="Der Dampfpanzer von Pilot Hildelve hatte in den gefrorenen Hügeln von Dun Morogh eine Panne. Er suchte zu Fuß nach Erz und stellte sich allein der Wildnis der Berge. In seinem Tagebuch berichtet er, wie er den Eiskrallenbären Mangeclaw abwehrte, dabei aber schwer zugerichtet wurde. Der Bär kehrte zurück und tötete den geschwächten Piloten. Hildelves letzter Eintrag flehte um Rache. Dem erlegten Bären die Räudige Klaue abzunehmen, erfüllt seinen Wunsch."},{t="Rache für die Belagerungsbrigade",b="Pilot Hammerfuß schickte Suchtrupps in die Schneewehen, in der Hoffnung, seinen Freund Hildelve lebend zu finden. Hildelves Tagebuch und die Räudige Klaue zeigen, dass er starb und sein letzter Wunsch erfüllt wurde. Beides zu Hammerfuß zu bringen, verschafft der Belagerungsbrigade von Eisenschmiede Gewissheit und sichert Euch den Dank der Piloten von Eisenschmiede."}},faq={{q="Was ist die Räudige Klaue?",a="Die Räudige Klaue ist die abgetrennte Klaue von Mangeclaw, einem wilden Eiskrallenbären in Dun Morogh. Sie beweist, dass die Bestie gejagt und getötet wurde.",al={"räudige klaue zweck","was ist diese klaue","mangeclaw gegenstand"}},{q="Wer will die Räudige Klaue?",a="Pilot Hammerfuß will die Räudige Klaue und das Tagebuch seines gefallenen Freundes Hildelve. Sie bestätigen, dass der mörderische Bär tot ist. Hammerfuß ist nahe den Gebirgspässen von Dun Morogh stationiert.",al={"wer nimmt die räudige klaue","räudige klaue abgeben","pilot hammerfuß abgabe"}},{q="Warum musste Mangeclaw gejagt werden?",a="Mangeclaw richtete Hildelve schwer zu und tötete ihn schließlich, einen Zwergenpiloten, der nach einer Panne seines Dampfpanzers zu Fuß nach Erz suchte. Hildelves Tagebuch hält seinen letzten Wunsch fest, dass jemand ihn rächen möge.",al={"warum mangeclaw töten","wer starb durch mangeclaw","hildelve geschichte"}},{q="Wo streift die Bestie Mangeclaw umher?",a="Mangeclaw durchstreift die verschneiten Bergkämme und Hügel von Dun Morogh, nahe der Stelle, an der die sterblichen Überreste von Pilot Hildelve gefunden wurden.",al={"mangeclaw fundort","wo ist mangeclaw","mangeclaw dun morogh"}}},fx={["554d85fa"]={q="Woher stammt die Räudige Klaue?",a="Die Räudige Klaue stammt direkt von Räudeklaue, einem wilden Frostklauenbären, der durch die gefrorene Wildnis von Dun Morogh streift. Es ist kein handgefertigtes Artefakt, sondern eine grausige, physische Trophäe, die nach dem Erlegen der Bestie herausgeschnitten wurde.",al={"quelle der räudigen klaue","wo droppt die räudige klaue","wer hat die räudige klaue"}}},fp="10,173,20.396.0,31.302.1,23.125.0,25.184.0,36.192.0,36.105.0"}
P.entries["item:marshal-haggard-s-badge"] = {n="Marschall Haggards Abzeichen",s="In den Hügeln im Wald von Elwynn lebt Marschall Haggard im Ruhestand, fern vom Dienst für Sturmwind. Dead-tooth Jack brachte ihn durch eine List dazu, sein altes Abzeichen herauszugeben, mit dem sich die Defias als städtische Amtsträger ausgeben könnten.",h="In den Hügeln im Wald von Elwynn lebt Marschall Haggard im Ruhestand, fern vom Dienst für Sturmwind.",kw={"dead-tooth jack","defias","wald von elwynn","marschall dughan","marshal haggard","marschall haggards abzeichen","sturmwind","schließkiste"},ang={["class:Warrior"]="Als Krieger beweist Ihr einem Veteranen des Militärs von Sturmwind Euer Können, indem Ihr Haggards Abzeichen zurückholt. Er belohnt vielversprechende Krieger mit gut gepflegten, überschüssigen Waffen aus seiner Zeit im Kampf.",["faction:Alliance"]="Als Mitglied der Allianz schützt Ihr durch die Rückholung des Abzeichens Sturmwinds militärische Führung und hindert die Bruderschaft der Defias daran, die örtliche Verteidigung von innen zu untergraben."},sec={{t="Eine gestohlene Insigne",b="Dead-tooth Jack kam eines Nachts in einem Wappenrock von Sturmwind zu Haggards Hof. Der Schurke der Defias gab sich als Marschall Dughan aus, den Garnisonskommandanten von Goldhain, und behauptete, Haggards frühere Kameraden bräuchten die Insigne für Amtsgeschäfte.\n\nDer alternde Marschall händigte sie ihm ohne Argwohn aus. Jack floh in die Wälder, bevor Haggard die List durchschaute. In den Händen der Defias besitzt das Abzeichen noch immer die Autorität der Marschälle von Sturmwind. Gesetzlose könnten damit Kontrollpunkte passieren oder örtliche Patrouillen verwirren."}},faq={{q="Was ist Marschall Haggards Abzeichen?",a="Marschall Haggard trug das Abzeichen als Zeichen seines Ranges, als er dem Königreich Sturmwind diente. Obwohl er im Ruhestand ist, verleiht das Abzeichen noch immer echte Autorität.",al={"haggard abzeichen","marschall abzeichen","haggards abzeichen"}},{q="Wie kam Dead-tooth Jack an das Abzeichen?",a="Dead-tooth Jack kam nachts in einem Wappenrock von Sturmwind zu Marshal Haggards Heim. Haggard hielt ihn für Marschall Dughan aus Goldhain und händigte ihm das Abzeichen aus, als Jack darum bat.",al={"wie wurde das abzeichen gestohlen","wer stahl das abzeichen","dead-tooth jack list"}},{q="Warum ist das Abzeichen in den Händen der Defias gefährlich?",a="Ein Agent der Defias könnte sich mit dem echten Abzeichen und einer Verkleidung als hochrangiger Amtsträger von Sturmwind ausgeben. Der Agent könnte Wachposten passieren, Garnisonen betreten oder Stadtwachen falsche Befehle erteilen.",al={"warum will jack das abzeichen","defias abzeichen verwendung","abzeichen gefahr"}},{q="Wo wird das Abzeichen aufbewahrt?",a="Dead-tooth Jack schloss das Abzeichen in seiner Schließkiste in seinem Lager südlich von Marshal Haggards Hof im Wald von Elwynn ein.",al={"abzeichen fundort","wo ist das abzeichen zu finden","dead tooth schließkiste"}}},fp="23,205,17.489.0,32.160.0,38.185.0,54.192.0,24.115.0"}
P.entries["item:mary-s-looking-glass"] = {n="Marys Handspiegel",s="Im Dämmerwald wandert Marys weggeworfener Handspiegel von einem Ghul zu einem Sterngucker.",h="Im Dämmerwald wandert Marys weggeworfener Handspiegel von einem Ghul zu einem Sterngucker.",kw={"die blinde mary","dunkelhain","dämmerwald","wahnsinniger ghul","look to the stars","handspiegel","marys handspiegel","der friedhof \"stille gärten\"","viktori prism'antras"},ang={["faction:Alliance"]="Den Schrecken auf dem Friedhof \"Stille Gärten\" Relikte abzunehmen, hilft Dunkelhains geplagten Bürgern, etwas Frieden zu finden, und unterstützt die Vorhaben der Stadt.",["profession:Engineering"]="Ingenieure wissen zu schätzen, wie Viktori einen antiken Haushaltsspiegel als optischen Reflektor für ein Gerät zur Sternenbeobachtung umfunktioniert."},sec={{t="Ein verlassener Schatz",b="Die blinde Mary hütete den polierten Spiegel einst wie einen Schatz. Nach ihrem Tod und dem Verlust ihrer Augen wurde ihr Spiegelbild zu einer schmerzlichen Erinnerung an das, was sie verloren hatte. Sie warf den Handspiegel hinter ihre Scheune. Die Düsternis des Dämmerwalds sammelte sich um ihn, bis ein Wahnsinniger Ghul ihn in den zerstörten Außenbezirken fand und nach Süden zu den Krypten des Friedhofs \"Stille Gärten\" trug."},{t="Den Blick zum Himmel",b="In Dunkelhain träumt der Sterngucker Viktori Prism'Antras davon, über die ewige Dämmerung des Dämmerwalds hinaus in den klaren Himmel darüber zu blicken. Sein Teleskop braucht besondere optische Linsen und Spiegelglas. Mary schickt Abenteurer zur zerstörten Kapelle auf dem Friedhof, wo verwilderte Untote ihren Handspiegel haben. Viktori braucht ihn als Reflektor in seiner Maschine zur Sternenbeobachtung."}},faq={{q="Warum warf Mary den Handspiegel weg?",a="Der Handspiegel war einst einer von Marys kostbarsten Schätzen, doch nach einem Vorfall, den sie nicht vollständig schildert, warf sie ihn hinter die Scheune. Bei einer anderen Begegnung erklärt sie, dass sie sich selbst die Augen ausriss, weil sie ihren Anblick nicht ertragen konnte.",al={"warum mary ihn wegwarf","warum spiegel wegwerfen","die blinde mary spiegel hintergrund"}},{q="Bei wem landete der Spiegel, nachdem Mary ihn weggeworfen hatte?",a="Ein Wahnsinniger Ghul, der durch die Wälder hinter Marys altem Gehöft streifte, fand den weggeworfenen Spiegel und nahm ihn mit. Das untote Wesen ließ sich schließlich in der verlassenen Kapelle auf dem Friedhof \"Stille Gärten\" nieder.",al={"wer hat den spiegel","wer ließ den handspiegel fallen","wo ist der handspiegel"}},{q="Warum will Viktori Prism'Antras Marys Handspiegel haben?",a="Viktori baut ein aufwendiges Teleskop, um die Düsternis des Dämmerwalds zu durchdringen und die Sterne zu erforschen. Er braucht eine hochwertige spiegelnde Oberfläche, um Licht durch das Gerät zu lenken, und Marys Spiegel passt zu seinem Entwurf.",al={"warum braucht viktori den spiegel","viktori handspiegel verwendung","teleskop spiegel"}},{q="Wo ist der Wahnsinnige Ghul zu finden, der den Spiegel hat?",a="Der Wahnsinnige Ghul lauert im äußersten Südosten des Dämmerwalds und sucht die zerstörte Steinkapelle auf dem Friedhof \"Stille Gärten\" heim.",al={"wahnsinniger ghul fundort","wo ist der wahnsinnige ghul","friedhof stille gärten ghul"}}},fx={afb2ba8d={q="Was ist Marys Handspiegel?",a="Marys Handspiegel ist ein reflektierender Handspiegel, der einst der blinden Mary gehörte, bevor sie von einer Tragödie heimgesucht wurde. Von Mary als einer ihrer kostbarsten persönlichen Schätze geschätzt, warf sie ihn nach einem schrecklichen Vorfall schließlich hinter ihrer Scheune weg. Später fiel er im Dämmerwald in die Fänge eines umherwandernden untoten Ghuls.",al={"was ist marys handspiegel","marys handspiegel gegenstand","handspiegel der blinden mary"}}},fp="20,79,19.356.0,19.366.0,42.247.0,53.196.0,56.195.0,55.124.0"}
P.entries["item:mathystra-relic"] = {n="Relikt von Mathystra",s="Im Norden der Dunkelküste tragen Mathystras uralte Relikte noch immer Spuren von Magie. Der Schattenhammerkult zeigt Interesse an ihnen.",h="Im Norden der Dunkelküste tragen Mathystras uralte Relikte noch immer Spuren von Magie.",kw={"dunkelküste","der hain der uralten","die meistergleve","mathystra","relikt von mathystra","onu","die ruinen von mathystra","schattenhammerkult"},ang={["class:Druid"]="Als Druide arbeitet Ihr mit Urahnen wie Onu zusammen, um das Gleichgewicht der Dunkelküste zu schützen. Ihr helft zu verhindern, dass vergessene Magie dunkle Beschwörungen unterstützt.",["race:NightElf"]="Als Kaldorei helft Ihr durch die Bergung dieser Relikte, gefährliche uralte Magie vor dem Schattenhammerkult zu bewahren. Damit ehrt Ihr auch eine Stadt, die der Zerschlagung zum Opfer fiel."},sec={{t="Überreste einer gefallenen Bastion",b="Mathystra war einst eine Stadt und Bastion der elfischen Zivilisation an der Küste von Kalimdor. Vor der Großen Zerschlagung war es ein stolzer Ort. Heute liegen umgestürzte Säulen und gesprungene Steine halb von Gestrüpp und Meeresnebel verschlungen da. Rastlose Geister und lauernde Bestien bewegen sich zwischen ihnen.\n\nRelikte aus jener Zeit liegen über die Ruinen verstreut. Zehntausend Jahre der Vernachlässigung haben sie gezeichnet, doch Spuren arkaner Handwerkskunst der Elfen sind geblieben. In unachtsamen Händen sind diese Relikte gefährlich."},{t="Eine drohende Gefahr",b="Onu, der Urahne der Lehren, sucht Mathystras Relikte. Er erfuhr, dass der Schattenhammerkult versucht, vergessene Elfenschriften von der Meistergleve als Waffe zu nutzen. Der Kult will uralte Magie der Kaldorei wirken und die Rückkehr seiner dunklen Meister beschleunigen.\n\nOnu und die Beschützer der Dunkelküste untersuchen die verstreuten Überreste, um die Absichten des Kultes zu ergründen. Sie wollen verhindern, dass Mathystras schwindende Macht dunklen Zwecken dient."}},faq={{q="Was sind die Relikte von Mathystra?",a="Die Relikte von Mathystra sind Bruchstücke und Artefakte aus der uralten Stadt der Nachtelfen. Sie tragen noch immer Spuren elfischer Zauberkunst aus der Zeit vor der Zerschlagung, obwohl Tausende von Jahren vergangen sind.",al={"was ist das relikt von mathystra","elfische relikte mathystra","was sind diese relikte"}},{q="Wo findet man diese Relikte?",a="Die Relikte liegen zwischen zerbrochenen Steinen, umgestürzten Säulen und hohen Gräsern in den Ruinen von Mathystra im Norden der Dunkelküste verstreut.",al={"relikt von mathystra fundort","wo relikte finden","fundorte der relikte"}},{q="Wer sucht die Relikte von Mathystra?",a="Onu, ein Urahne der Lehren, bittet Reisende, die Relikte zur Untersuchung zu sammeln. Er lebt im Hain der Uralten im Süden der Dunkelküste.",al={"wer braucht relikte","wem die relikte bringen","onu relikte"}},{q="Warum interessiert sich der Schattenhammerkult für sie?",a="Der Schattenhammerkult untersucht uralte Elfenschriften, die bei der Meistergleve gefunden wurden. Er will die alte Magie der Elfen verderben und damit seine finsteren Meister in die Welt beschwören.",al={"warum will der schattenhammerkult relikte","schattenhammerkult mathystra"}}},fx={bddb4f1c={q="Woher stammen die Mathystra Relics und wer hat sie hergestellt?",a="Diese Artefakte stammen aus der alten Nachtelfenstadt Mathystra und wurden vor langer Zeit in einer Ära gefertigt, als die große Bastion noch über die nördliche Dunkelküste strahlte. Sie wurden zurückgelassen, nachdem die alte Siedlung in Ruinen zerfallen war, und bergen noch immer Reste elfischer Magie.",al={"herkunft der mathystra relics","wer hat die mathystra relics hergestellt","woher kommen die mathystra relics"}}},fp="15,130,28.460.0,15.426.1,30.195.0,29.128.0,31.132.0,48.180.0"}
P.entries["item:melenas-head"] = {n="Melenas Kopf",s="Am Teufelsfels setzt Melenas Kopf der Bedrohung durch Lord Melenas ein Ende. Der Satyrenkommandant hatte dort sein Lager aufgeschlagen, und der Kopf ist der Beweis für seinen Tod.",h="Am Teufelsfels setzt Melenas Kopf der Bedrohung durch Lord Melenas ein Ende.",kw={"teufelsfels","grell","lord melenas","melenas kopf","satyr","teldrassil","twisted hatred"},ang={["class:Warrior"]="Als Krieger wisst Ihr, dass der abgeschlagene Kopf eines feindlichen Kriegsherrn zweifelsfrei beweist, dass ein gefährlicher Widersacher und sein Grellheer bezwungen wurden.",["race:NightElf"]="Als Nachtelf wisst Ihr, dass Satyren eine tragische dämonische Entstellung Eurer uralten Abstammungslinie sind. Die heimliche Hinrichtung von Lord Melenas war notwendig, doch zugleich eine Quelle kultureller Scham."},sec={{t="Eine unausgesprochene Schande",b="Satyren auf Teldrassils neuem Weltenbaum sind eine Schande für die Nachtelfen, die das Laubschattental und die umliegenden Lande bewachen. Lord Melenas richtete seinen Unterschlupf in den verwinkelten Höhlen des Teufelsfelsens ein, gleich nördlich der elfischen Siedlungen. Dort scharte er angriffslustige Grellkrieger um sein Banner.\n\nDie Kaldorei schätzen Diskretion, wenn die Verderbnis ihrem Kernland so nahe kommt. Melenas Kopf ist ein vertraulicher Beweis dafür, dass seine Ränke ein Ende fanden, bevor sich sein Einfluss ausbreiten konnte."}},faq={{q="Wer war Lord Melenas?",a="Lord Melenas war ein Satyrenkommandant, der im Teufelsfels auf Teldrassil lauerte. Er versammelte Grellkrieger unter seinem Kommando, um gegen nahe gelegene Außenposten der Kaldorei zu intrigieren.",al={"lord melenas hintergrund","wer ist melenas","melenas geschichte"}},{q="Warum muss sein Tod geheim bleiben?",a="Satyren sind uralte Nachtelfen, verflucht und durch dämonische Verderbnis entstellt. Ihre Anwesenheit so nahe an Teldrassils heiligen Ästen ist für die Obrigkeit der Kaldorei zutiefst beschämend. Melenas rasch und still zu beseitigen, verhindert Panik und begrenzt die Schande.",al={"warum geheimhaltung","twisted hatred geheimnis","warum stillschweigen"}},{q="Wo wurde Melenas Kopf erbeutet?",a="Melenas Kopf wurde tief im Inneren des Teufelsfelsens erbeutet, einer verderbten Höhle gleich nördlich von Dolanaar im Herzen Teldrassils.",al={"wo melenas finden","teufelsfels lage","melenas aufenthaltsort"}}},fx={b9c077d0={q="Warum will Tallonkai Melenas Kopf?",a="Tallonkai Flinkwurzel sucht den Kopf als absoluten Beweis für das Ableben von Lord Melenas. Die Anwesenheit eines Satyrs so nah am Laubschattental wird als gefährliche Demütigung für die Nachtelfen angesehen. Die Übergabe seines Kopfes stellt sicher, dass der üble Intrigant schnell und leise zum Schweigen gebracht wurde, bevor sich seine Pläne weiter über Teldrassil ausbreiten konnten.",al={"warum melenas kopf bringen","wer will melenas kopf","warum will tallonkai den kopf"}},["05bed8f4"]={q="Was ist Melenas Kopf?",a="Es ist der abgetrennte Kopf von Lord Melenas, einem abscheulichen Satyr, der seinen Unterschlupf im Teufelsfels direkt nördlich von Dolanaar hatte. Melenas sammelte aggressive Grells um sich und schmiedete finstere Pläne unangenehm nah an der heiligen Heimat der Nachtelfen, was seinen abgetrennten Kopf zu einem unbestreitbaren Beweis dafür macht, dass sein verderblicher Einfluss getilgt wurde.",al={"was ist melenas kopf","melenas kopf gegenstand","wessen kopf ist das"}}},fp="13,141,20.426.0,21.159.0,32.242.0,35.110.0"}
P.entries["item:menethil-statuette"] = {n="Statuette von Menethil",s="Vor der Küste des Sumpflands liegt die Statuette von Menethil, verloren bei einem Schiffbruch. Das seltene silberne Bildnis ehrt Lordaerons gefallenen König.",h="Vor der Küste des Sumpflands liegt die Statuette von Menethil, verloren bei einem Schiffbruch.",kw={"blind princess","bluegill","bolvar fordragon","kathedrale des lichts","grayson schattenbruch","statuette von menethil","terenas menethil","sumpfland"},ang={["class:Paladin"]="Als Paladin seht Ihr König Terenas als jungen Krieger des Lichts mit erhobenem Hammer. Sein Bildnis spricht heilige Ritter an, die um das gefallene Königreich trauern.",["faction:Alliance"]="Als Mitglied der Allianz kennt Ihr Terenas als den einigenden Anführer, der die Große Allianz gründete. Jedes erhaltene Denkmal von ihm ist ein inspirierender Schatz in einer zerrissenen Welt."},sec={{t="Ein seltenes Relikt Lordaerons",b="König Terenas Menethil II. ist als junger, langhaariger Paladin dargestellt, der seinen Hammer gen Himmel hebt. Zu Lebzeiten war er bescheiden und mochte keine Denkmäler seiner selbst, weshalb nur wenige Bildnisse zu seinen Ehren geschaffen wurden. Als die Geißel Lordaeron zu Fall brachte, wurden fast alle diese Bildnisse zerstört. Dieses erhaltene Standbild ist für die Allianz kostbar."},{t="Verlust in den Sümpfen",b="Die Blind Princess brachte die Statuette zum Allianzhafen von Menethil, als Murlocs der Bluegill vor der sumpfigen Küste angriffen. Der Angriff verstreute die Ladung des Handelsschiffs, und die Statuette kam in einem halb vergrabenen Fass am Ufer zu liegen.\n\nOrcs des Dragonmaw-Clans und andere örtliche Bedrohungen blieben in der Nähe, weshalb Verteidiger das geborgene Bildnis eilig nach Süden nach Sturmwind brachten. Dort vertraute Hochlord Bolvar Fordragon es der Kathedrale des Lichts an."}},faq={{q="Wen zeigt die Statuette?",a="Die Statuette zeigt König Terenas Menethil II., den einstigen Herrscher Lordaerons und Wegbereiter der ursprünglichen Allianz. Er erscheint als junger Paladin, der einen Kriegshammer hebt.",al={"wer ist auf der statue","was stellt die statuette dar","wer ist die statuette von menethil"}},{q="Wie ging die Statuette verloren?",a="Die Blind Princess trug die Statuette über das große Meer. Murlocs der Bluegill griffen das Schiff im Sumpfland an, und seine Ladung wurde an Land gespült und im Schlamm begraben.",al={"wie ging sie verloren","wer verlor die statuette","schiffbruch sumpfland statue"}},{q="Warum sind Darstellungen von König Terenas so selten?",a="König Terenas mochte keine Denkmäler, die ihn selbst priesen, weshalb nur wenige Statuen von ihm geschaffen wurden. Als die Geißel Lordaeron verwüstete, zerstörte sie fast alle Porträts und Figuren, die im Norden verblieben waren.",al={"warum gibt es wenige statuen von terenas","terenas denkmäler"}},{q="Wohin gelangt die Statuette schließlich?",a="Nach ihrer Bergung im Sumpfland wird die Statuette zu Hochlord Bolvar Fordragon in die Burg Sturmwind gebracht. Er erkennt das Licht in dem Relikt und vertraut es Lord Grayson Schattenbruch in der Kathedrale des Lichts an.",al={"wohin die statuette bringen","wer bewahrt die statuette auf","statuette kathedrale"}}},fx={["00c7d589"]={q="Was ist die Statuette von Menethil?",a="Die Statuette von Menethil ist eine silberne Figur, die König Terenas Menethil II. in seiner Jugend als langhaarigen Paladin mit erhobenem Hammer darstellt. Über ihre Bedeutung als exquisites Abbild des gefallenen Monarchen von Lordaeron hinaus scheint das Relikt das Licht selbst in sich zu vereinen, was es sowohl zu einem kostbaren historischen Denkmal als auch zu einem gesegneten heiligen Objekt macht.",al={"was ist die statuette von menethil","menethil statue","was ist die statuette"}},["0d8a0354"]={q="Warum ist die Statuette von Menethil so begehrt?",a="König Terenas verachtete persönliche Denkmäler und Gedenkstätten, weshalb nur außerordentlich wenige Abbilder von ihm erhalten geblieben sind; fast alle wurden zerstört, als Lordaeron an die Geißel fiel. Ihre Seltenheit, das heilige Licht und die tiefe sentimentale Verbindung zum Gründer der Allianz machen sie zu einem unersetzlichen Erbstück, das Feinde wie die örtlichen Drachenmal-Orks gerne entweihen oder plündern würden, wenn es unbewacht bliebe.",al={"warum wollen leute die statuette von menethil","warum ist die statuette wertvoll","wer will die statuette"}}},fp="18,131,25.338.0,16.448.0,30.162.0,27.169.0,43.200.0,32.222.1"}
P.entries["item:merrin-s-letter"] = {n="Merrins Brief",s="An Whelgars Ausgrabungsstätte sendet Merrin Felsweber dringende Nachricht aus dem Sumpfland. Raptoren haben die Ausgrabung überrannt, doch sie teilt ihren Lieben mit, dass sie überlebt hat.",h="An Whelgars Ausgrabungsstätte sendet Merrin Felsweber dringende Nachricht aus dem Sumpfland.",kw={"explorers' league","merrin felsweber","merrins brief","mottled raptors","tarrel felsweber","sumpfland","whelgars ausgrabungsstätte"},ang={["faction:Alliance"]="Als Reisender der Allianz bringt Ihr den Wachen an der Straße durch das Sumpfland wichtige Informationen und bittersüßen Trost, wenn Ihr die Nachricht überbringt.",["race:Dwarf"]="Als Zwerg könnt Ihr erkennen, welchen persönlichen Preis die Explorers' League zahlt, um in der gefährlichen Wildnis von Khaz Modan uralte Geschichte freizulegen."},sec={{t="Eine Nachricht aus den Ruinen",b="Merrin Felsweber schreibt von der verwüsteten Ausgrabung an Whelgars Ausgrabungsstätte im Sumpfland. Die Zwergenexpedition legte gewaltige prähistorische Fossilien und Relikte frei, als sie ein Nest von Mottled Raptors aufscheuchte. Die Bestien strömten in die Gräben, töteten mehrere Arbeiter und schnitten den überlebenden Forschern den Weg ab.\n\nMitten im Chaos schickt Merrin ihrem Ehemann Tarrel im Hafen von Menethil eine Nachricht. Sie, Ausgrabungsleiter Whelgar und Ormer Eisenzopf haben hinter einem verbarrikadierten Unterschlupf überlebt."}},faq={{q="Wer hat Merrins Brief geschrieben?",a="Merrin Felsweber schrieb den Brief, während sie an der archäologischen Expedition an der Ausgrabungsstätte östlich vom Hafen von Menethil im Sumpfland teilnahm.",al={"verfasserin von merrins brief","wer ist merrin"}},{q="An wen ist der Brief gerichtet?",a="Merrin richtete den Brief an Tarrel Felsweber, der auf der Brücke im Hafen von Menethil bang auf Nachricht wartet.",al={"empfänger von merrins brief","wer bekommt merrins brief"}},{q="Was geschah mit dem Ausgrabungsteam?",a="Mottled Raptors überrannten das Archäologenteam, als es gewaltige versteinerte Knochen freilegte. Viele zwergische Arbeiter wurden getötet, und nur eine Handvoll überlebte hinter Barrikaden in einem behelfsmäßigen Lager.",al={"was geschah mit der ausgrabung","warum scheiterte die expedition"}},{q="Wer half Merrin, den Angriff zu überleben?",a="Ormer Eisenzopf half Merrin, den Angriff zu überleben. Er verteidigte Merrin und den Ausgrabungsleiter und verschaffte ihnen Zeit, sich in Sicherheit zurückzuziehen, während die Raptoren den Rest der Ausgrabung überrannten.",al={"wer rettete merrin","ormer eisenzopf"}}},fx={bce088a8={q="Was ist Merrins Brief?",a="Merrins Brief ist eine dringende Nachricht von Merrin Felsweber, einer Überlebenden des katastrophalen Raptor-Angriffs auf die Ausgrabungsstätte im Sumpfland. Die Notiz ist an ihren geliebten Tarrel Felsweber gerichtet und berichtet von dem Unglück, das ihr Grabungsteam ereilte, und bestätigt, dass sie, Ausgrabungsleiter Whelgar und Ormer Eisenzopf nur knapp mit dem Leben davongekommen sind.",al={"merrins brief","was ist merrins brief","merrin notiz"}},ded8799c={q="Warum will Tarrel Merrins Brief?",a="Tarrel Felsweber hat Euch in die gefährlichen Moore geschickt, speziell um nach Nachrichten über seine Geliebte und das Schicksal des vermissten Grabungsteams zu suchen. Merrins Brief liefert ihm die lebenswichtige Bestätigung, dass sie noch am Leben ist, während er gleichzeitig den tragischen Verlust der Ausgrabungsstätte und ihre verzweifelte Zuflucht vor den umherstreifenden Raptoren detailliert beschreibt.",al={"warum merrins brief überbringen","warum will tarrel den brief","zweck von merrins brief"}}},fp="15,152,25.471.0,26.142.0,31.112.0,37.190.0,37.183.0"}
P.entries["item:middle-of-gelkak-s-key"] = {n="Mitte von Gelkaks Schlüssel",s="Vor der Dunkelküste versenkten Dreschdonen Gelkak Gyromasts Schiff und verstreuten seinen Schlüssel in drei Teilen. Greymist-Murlocs nahmen das mittlere Fragment mit.",h="Vor der Dunkelküste versenkten Dreschdonen Gelkak Gyromasts Schiff und verstreuten seinen Schlüssel in drei...",kw={"uhrwerk","dunkelküste","gelkak gyromast","greymist","mitte von gelkaks schlüssel","murloc","schiffswrack"},ang={["profession:Engineering"]="Als Ingenieur erkennt Ihr, wie dieses maßgefertigte mechanische Bauteil einen ersten Maat mit Uhrwerk aufzieht und antreibt, ein Zeugnis gnomischen Erfindungsreichtums in Piratenhänden."},sec={{t="Ein Fragment im Schlick",b="Gelkak Gyromasts Aufziehschlüssel zerbrach, als Dreschdonen sein Schiff unter die Wellen zogen. Der Gnomenpirat gelangte an Land, während seine Habseligkeiten an den felsigen Untiefen zerschellten. Sein Spezialschlüssel war für seinen mechanischen ersten Maat bestimmt, doch beim Schiffbruch zerbrach er in drei Teile, die sich am Strand verstreuten. Küstenbestien schleppten den oberen und den unteren Teil fort. Greymist-Murlocs, die in der Brandung der Dunkelküste umherstreiften, nahmen das Mittelstück mit und verwahrten es in ihren Lagern und zwischen den Wrackteilen in ihrem Besitz."}},faq={{q="Wofür wird die Mitte von Gelkaks Schlüssel verwendet?",a="Gelkak Gyromast benötigt die Mitte von Gelkaks Schlüssel als eines von drei Teilen. Zusammen mit dem oberen und dem unteren Teil ergibt sie den Schlüssel, der seinen mechanischen ersten Maat wieder aktiviert.",al={"was bewirkt gelkaks schlüssel","mitte von gelkaks schlüssel verwendung","wofür wird dieser schlüssel benötigt"}},{q="Wo ist dieses Schlüsselstück gelandet?",a="Greymist-Murlocs bargen das mittlere Fragment. Es lässt sich bei Räubern, Orakeln, Netzwerfern, Gezeitenjägern und anderen Stammesmitgliedern an den Stränden und Schiffswracks der Dunkelküste erbeuten.",al={"wer hat das mittlere schlüsselstück","wo ist die mitte von gelkaks schlüssel","wer lässt das mittlere schlüsselstück fallen"}},{q="Warum ist der Schlüssel überhaupt zerbrochen?",a="Angriffslustige Dreschdonen versenkten Gelkaks Schiff unmittelbar vor der Küste. Der Schlüssel zerbrach an den Küstenfelsen in drei Teile, als der Gnom an Land gespült wurde, und einheimische Aasfresser schleppten die Teile fort.",al={"wie ist der schlüssel zerbrochen","warum ist er in stücken"}}},fx={d3714d13={q="Was ist die Mitte von Gelkaks Schlüssel?",a="Es ist das Mittelstück eines dreiteiligen Schlüssels, der dem schiffbrüchigen Gnom-Piraten Gelkak Gyromast gehörte. Als sein Schiff vor der Küste der Dunkelküste sank und er an Land gespült wurde, zerbrach der Schlüssel an den schroffen Felsen, wobei dieses Fragment im Wrack zurückblieb.",al={"mitte von gelkaks schlüssel","mittelstück von gelkaks schlüssel","was ist dieses schlüsselstück"}},["55a592b4"]={q="Woher stammt die Mitte von Gelkaks Schlüssel und wer hat ihn hergestellt?",a="Der Schlüssel gehört Gelkak Gyromast und wurde an Bord seines Schiffes gebracht, bevor es von Dreschadon vor der Küste der Dunkelküste zerstört wurde. Obwohl Gelkak den Schlüssel besaß, um seinen mechanischen ersten Maat zu bedienen, ist sein genauer Hersteller unbekannt.",al={"wer hat gelkaks schlüssel gemacht","herkunft des mittleren schlüsselstücks","woher kam der schlüssel"}},["7cf04b1b"]={q="Warum will Gelkak Gyromast das mittlere Schlüsselstück?",a="Gelkak Gyromast benötigt dieses Mittelstück zusammen mit den anderen beiden Fragmenten, um den gesamten Schlüssel wieder zusammenzusetzen. Ohne den vollständigen Schlüssel kann er seinen mechanischen ersten Maat nicht aufziehen und reaktivieren, um Rache an den Tieren an der Küste zu nehmen.",al={"warum will gelkak diesen schlüssel","wer will gelkaks schlüssel","warum wird der schlüssel benötigt"}}},fp="22,138,22.481.0,44.163.0,32.176.0,42.190.0"}
P.entries["item:milly-s-harvest"] = {n="Millys Ernte",s="In den Weinbergen von Nordhain liegt Millys Ernte nach der Ankunft der Defias verlassen da. Die Trauben in Kisten und Eimern könnten gestohlen oder unter den Stiefeln der Abteiwachen zerquetscht werden.",h="In den Weinbergen von Nordhain liegt Millys Ernte nach der Ankunft der Defias verlassen da.",kw={"defias","wald von elwynn","trauben","milly osworth","millys ernte","abtei von nordhain","weinberge von nordhain"},ang={["faction:Alliance"]="Die Bedrohung für Nordhains Bauern zeigt, wie knapp die Garnison von Sturmwind inzwischen besetzt ist. Einfache Leute sind auf durchreisende Abenteurer angewiesen, um ihre Lebensgrundlage zu schützen.",["race:Human"]="Wenn Ihr als Mensch in Nordhain beginnt, begegnet Ihr der Gesetzlosigkeit der Bruderschaft der Defias womöglich erstmals vor Eurer eigenen Haustür, wenn Ihr Millys Trauben bergt."},sec={{t="Eine empfindliche Ernte",b="Milly Osworth sammelt Trauben in den Weinbergen von Nordhain. Die Ernte ist für die örtlichen Winzer und die Gemeinschaft der Abtei wichtig. Als bewaffnete Räuber mit roten Masken die Felder betreten, flieht Milly auf das Gelände der Abtei. Ihre frisch gepflückten Trauben liegen verstreut zwischen den Reihen."},{t="Kollateralschäden",b="Wachen aus Sturmwind bewachen den Taleingang, doch ihre geringe Zahl macht Nordhain verwundbar. Die Garnison verspricht, die Defias zu vertreiben. Milly fürchtet, ein langer Kampf zwischen Wachen und Dieben werde ihre Ernte vernichten. Die Kisten könnten zertrampelt oder als Proviant fortgeschleppt werden, wodurch Nordhain eine seiner wenigen friedlichen Ernten verlieren würde."}},faq={{q="Was ist Millys Ernte?",a="Millys Ernte besteht aus den Trauben, die Milly Osworth gepflückt und in Kisten und Eimer gepackt hat, bevor Defias-Schläger die Weinberge von Nordhain besetzten.",al={"millys ernte","was ist die ernte","milly osworth trauben"}},{q="Warum wurden die Kisten im Weinberg zurückgelassen?",a="Banditen der Defias überfielen die Weinberge, während Milly erntete. Sie musste die Trauben zurücklassen und zur Abtei von Nordhain fliehen.",al={"warum zurückgelassen","warum ließ milly die trauben zurück","warum ernte zurücklassen"}},{q="Warum konnten die Wachen von Nordhain die Ernte nicht bergen?",a="Die Wachen von Nordhain sind durch Vorstöße der Defias und örtliche Bedrohungen überlastet. Milly fürchtet außerdem, dass ihre Stiefel die Trauben zerquetschen könnten, während sie die Banditen vertreiben.",al={"warum nicht die wachen","warum können die wachen sie nicht bergen","sturmwind wachen nordhain"}},{q="Wer sind die Banditen, die die Ernte bedrohen?",a="Die Banditen, die die Ernte bedrohen, gehören zur Bruderschaft der Defias, einem Bund aus Gesetzlosen und Räubern, der im ganzen Wald von Elwynn Unruhe stiftet.",al={"wer besetzte die weinberge","wer greift den weinberg an","weinberg banditen"}}},fx={["1d7cbab4"]={q="Warum möchte Milly ihre Ernte zurück?",a="Milly Osworth hat die Ernte selbst eingebracht und ist für ihren Lebensunterhalt darauf angewiesen, musste sie aber aufgeben, als Defias-Banditen den Weinberg überrannten. Sie befürchtet, dass die Wachen der Abtei die zerbrechlichen Trauben in den Dreck treten, wenn sie die Briganten vertreiben, falls die Diebe nicht zuvor mit der Frucht entkommen.",al={"warum will milly die ernte","warum millys ernte bergen","warum sind die trauben wichtig"}}},fp="15,174,15.261.0,17.328.0,24.138.0,48.128.0,56.161.0,44.141.0"}
P.entries["item:miners-gear"] = {n="Minenarbeiterausstattung",s="Im nördlichen Loch Modan wartet die Minenarbeiterausstattung in der Silberbachmine. Kobolde haben die Stollen überrannt, und die Miners' League will ihre Werkzeuge bergen lassen, bevor die örtlichen Wachen angreifen.",h="Im nördlichen Loch Modan wartet die Minenarbeiterausstattung in der Silberbachmine.",kw={"filthy paws","kobold","loch modan","minenarbeiterausstattung","miners' league","gebirgsjäger sturmlanze","silberbachmine"},ang={["profession:Mining"]="Als Bergarbeiter kennt Ihr den Wert von gut geschmiedetem zwergischem Eisen. Hochwertige Spitzhacken und Schaufeln kerzentragenden Plünderern zu überlassen, ist eine kleine Tragödie.",["race:Dwarf"]="Als Zwerg empfindet Ihr es womöglich als unerträgliche Beleidigung, dass Kobolde ihre schmutzigen Pfoten auf zwergische Handwerkskunst legen. Die Mine muss unverzüglich gesäubert werden."},sec={{t="Vorräte der Miners' League",b="Als das Erz in der Silberbachmine erschöpft war, machte die Miners' League ihre stillen Stollen zu einem Lager für Bergbauausrüstung. Kobolde überrannten die Mine, beschlagnahmten die gelagerten Waren und bauten Nester zwischen den Kisten. Die Liga fürchtet, ein Angriff der Gebirgsjäger könnte die zwergische Ausrüstung zerstören oder Plünderer könnten sie ruinieren. Betretet die Mine und bringt die Kisten in Sicherheit, bevor eines dieser Schicksale sie ereilt."}},faq={{q="Was ist die Minenarbeiterausstattung?",a="Die Minenarbeiterausstattung besteht aus Kisten der Miners' League mit zwergischen Ausgrabungswerkzeugen, darunter Spitzhacken und Schaufeln, die in den trockenen Stollen der Silberbachmine lagern.",al={"was ist minenarbeiterausstattung","minenarbeiterausstattung gegenstände","minenarbeiterausstattung loch modan"}},{q="Warum blieb die Ausrüstung in der Mine?",a="Nachdem das Erz in der Silberbachmine erschöpft war, verwandelte die Miners' League ihre leeren Stollen in ein Lagerdepot. Die Ausrüstung blieb dort, bis Kobolde die Schächte bevölkerten.",al={"warum ist ausrüstung in der silberbachmine","warum ausrüstung dort lassen"}},{q="Wer will diese Ausrüstung bergen lassen?",a="Gebirgsjäger Sturmlanze leitet die Bergungsaktion der Miners' League. Er will die Werkzeuge retten lassen, bevor seine Mitstreiter einmarschieren, um die Kobolde zu töten.",al={"wer will minenarbeiterausstattung","wer braucht die ausrüstung","gebirgsjäger sturmlanze ausrüstung"}},{q="Wo ist die Minenarbeiterausstattung zu finden?",a="Die Kisten der Miners' League liegen verstreut in den Schächten der Silberbachmine, im nördlichen Loch Modan östlich der Station Algaz.",al={"minenarbeiterausstattung fundort","wo minenarbeiterausstattung finden","miners' league kisten fundort"}}},fp="12,184,30.382.0,21.149.0,34.167.0,30.152.0,32.128.0"}
P.entries["item:miners-union-card"] = {n="Gewerkschaftsausweis eines Minenarbeiters",s="In Mondbruch liegen Gewerkschaftsausweise noch immer bei den Arbeitern, die unter der Erde umkamen. Einst trugen die Arbeiter sie durch die Minen, nun liegen sie bei den skelettierten Toten in den dunklen Stollen.",h="In Mondbruch liegen Gewerkschaftsausweise noch immer bei den Arbeitern, die unter der Erde umkamen.",kw={"einsturz","collecting memories","die todesminen","gewerkschaftsausweis eines minenarbeiters","mondbruch","skelettierter minenarbeiter","sturmwind","gewerkschaftsausweis"},ang={["faction:Alliance"]="Die Bergung der Ausweise kann Familien im ganzen Königreich Sturmwind Gewissheit geben, die nie erfuhren, was aus ihren in den Minen arbeitenden Angehörigen wurde.",["profession:Mining"]="Für Goldsucher und Minenarbeiter erinnern diese Ausweise an die tödlichen Gefahren durch Einstürze und ungesicherte Minenschächte."},sec={{t="Tragödie in der Tiefe",b="Bevor die Bruderschaft der Defias die Kontrolle über Mondbruch übernahm, arbeiteten Minenarbeiter unter Tage für die Gilde und förderten wertvolles Erz für das Königreich. Dann stürzte ein Tunnel ein, verschüttete einen Hauptschacht und tötete Dutzende unter dem Gestein.\n\nDie Toten erhoben sich als skelettierte Minenarbeiter, Ausgräber und Sprengmeister. Ihre Gewerkschaftsausweise stecken noch immer in knöchernen Taschen, als letzter Beweis dafür, wer sie waren. In Sturmwind suchen überlebende Kollegen nach den Ausweisen, um die verstorbenen Arbeiter zu identifizieren und ihren Familien Gewissheit zu geben."}},faq={{q="Was ist ein Gewerkschaftsausweis eines Minenarbeiters?",a="Ein Gewerkschaftsausweis eines Minenarbeiters wies seinen Träger als Mitglied der Gilde aus, die in den Minen von Mondbruch arbeitete. Überlebende Arbeiter nutzen die Ausweise, um herauszufinden, wer bei dem Einsturz starb.",al={"was ist ein gewerkschaftsausweis","minenarbeiterausweis","gewerkschaftsausweis"}},{q="Woher stammen diese Ausweise?",a="Die Ausweise finden sich bei untoten Arbeitern in den eingestürzten Stollen unter Mondbruch, darunter skelettierte Minenarbeiter, untote Ausgräber und untote Sprengmeister.",al={"wo sind gewerkschaftsausweise zu finden","wer lässt minenarbeiterausweise fallen","fundort der ausweise"}},{q="Warum sind die Minenarbeiter untot?",a="Ein Einsturz schloss die Minenarbeiter in einem tiefen Schacht ein. Was sie als Untote erhob, ist unbekannt; ihre Überreste suchen nun die eingestürzten Stollen unter Mondbruch heim.",al={"warum skelettierte minenarbeiter","wie starben die minenarbeiter","deadmines untote"}},{q="Wer möchte diese Ausweise zurückhaben?",a="Überlebende Kollegen, die dem Einsturz entkamen und nun in Sturmwind leben, suchen nach den Ausweisen. Sie hoffen, den Familien der verstorbenen Minenarbeiter sagen zu können, was geschehen ist, und ihnen Frieden zu bringen.",al={"wer nimmt gewerkschaftsausweise an","collecting memories questgeber","gewerkschaftsausweise abgeben"}}},fp="18,179,19.484.0,29.152.0,31.150.0,26.147.0,31.173.0"}
P.entries["item:minshina-s-skull"] = {n="Minshinas Schädel",s="Auf den Echoinseln hält Zalazanes dunkle Magie Minshinas Seele an seinen Schädel gebunden. Minshina war ein Dunkelspeertroll und der Bruder von Meister Gadrin. Zalazane riss die Inseln an sich und vertrieb den Stamm, dann nutzte er Minshinas Schädel für seine Rituale.",h="Auf den Echoinseln hält Zalazanes dunkle Magie Minshinas Seele an seinen Schädel gebunden.",kw={"machtkreis","dunkelspeer","die echoinseln","gadrin","minshina","sen'jin","schädel","zalazane"},ang={["faction:Horde"]="Die Bergung des Schädels versetzt Zalazanes Herrschaft über die Echoinseln, direkt vor Durotars Küste, einen ersten Schlag.",["race:Troll"]="Für die Dunkelspeere verletzt Zalazanes Schändung Minshinas die Tradition der Ahnen. Seinen Schädel zurückzuholen ist eine Frage der Stammesehre."},sec={{t="Ein gefangener Geist",b="Minshina wurde gefangen genommen und getötet, als Zalazane die Echoinseln an sich riss und die Dunkelspeere vertrieb. Der verräterische Hexendoktor band seine Seele an seinen abgetrennten Schädel, statt ihn in den Tod übergehen zu lassen. Nun liegt der Schädel in einem Machtkreis auf der südlichsten Insel und hält Minshina an Zalazanes Magie gebunden.\n\nMeister Gadrin träumt davon, wie sein Bruder nach ihm ruft, und sucht mutige Reisende, die sich auf die besetzten Inseln wagen. Er bittet sie, den Schädel zurückzuholen und Zalazanes Macht über Minshinas Geist zu brechen."}},faq={{q="Wer war Minshina?",a="Minshina war ein Dunkelspeertroll und der Bruder von Meister Gadrin aus Sen'jin. Zalazane ermordete ihn im Zuge seines Verrats auf den Echoinseln.",al={"minshina geschichte","wer ist minshina","meister gadrins bruder"}},{q="Warum ist Minshinas Seele in seinem Schädel gefangen?",a="Zalazane nutzte dunkle Magie, um Minshinas Geist in seinem abgetrennten Kopf zu binden. Er legte den Schädel in einen Machtkreis auf der Hauptinsel und hielt Minshina seinem Willen unterworfen, statt ihn zu den Ahnen ziehen zu lassen.",al={"warum seine seele gefangen halten","zalazane schädelritual","seele im schädel gefangen"}},{q="Wo befindet sich der Schädel?",a="Der Schädel liegt auf der größten und südlichsten Insel der Echoinseln. Er ruht auf einem Hügel in einem Machtkreis, zwischen Kerzen, Ritualzeichen und anderen Schädeln, bewacht von Zalazanes Sklaven.",al={"wo ist minshinas schädel","machtkreis fundort","schädel fundort echoinseln"}},{q="Was geschieht, wenn der Schädel zu Meister Gadrin gebracht wird?",a="Wenn Ihr den Schädel zu Meister Gadrin in Sen'jin zurückbringt, bricht der dunkle Zauber. Minshinas geisterhafte Gestalt erscheint kurz, verneigt sich zum Dank und zieht friedlich ins Reich der Ahnen.",al={"minshina befreien","gadrin schädel belohnung","was geschieht mit minshina"}}},fx={["5c3b75e4"]={q="Was ist Minshinas Schädel?",a="Minshinas Schädel ist der physische Überrest von Minshina, einem gefallenen Dunkelspeer-Troll und Bruder von Meister Gadrin. Anstatt in Frieden zu ruhen, wurde Minshinas Seele durch dunkles Voodoo in seinen abgetrennten Schädel gebunden, was ihn gefangen hielt und nach Erlösung schreien ließ.",al={"was ist minshinas schädel","identität von minshinas schädel","was ist dieser schädel"}},["1b71ee0f"]={q="Woher stammt Minshinas Schädel und wer hat ihn erschaffen?",a="Der Schädel gehörte Minshina, der von dem verräterischen Hexendoktor Zalazane auf den Echoinseln gefangen genommen und getötet wurde. Mit übler Zauberei trennte Zalazane den Kopf ab und band Minshinas Geist direkt an den Knochen, den er zusammen mit anderen Überresten in einen Kreis der Macht legte, um seine dunklen Rituale zu befeuern.",al={"herkunft von minshinas schädel","wer erschuf minshinas schädel","ursprung von minshinas schädel"}},b6c5f4d1={q="Warum will jemand Minshinas Schädel haben?",a="Meister Gadrin sucht den Schädel, um den gequälten Geist seines Bruders zu retten. Minshina ruft ständig in seinen Träumen nach Gadrin, unfähig, Frieden zu finden, während er durch Zalazanes Magie gefangen ist. Die Bergung des Schädels aus dem Kreis der Macht auf den Echoinseln ist der einzige Weg, die Bindung zu lösen und seiner Seele Freiheit zu gewähren.",al={"warum minshinas schädel wollen","warum minshinas schädel sammeln","wer will minshinas schädel"}}},fp="16,242,16.507.0,17.142.0,44.206.0,27.192.0,56.206.1"}
P.entries["item:mirror-lake-water-sample"] = {n="Probe des Spiegelseewassers",s="Am Spiegelsee im Wald von Elwynn wird Wasser für Jennea Haubitz in Sturmwind gesammelt. Die Magier werden es auf Anzeichen dafür prüfen, dass die arkanen Strömungen das örtliche Wasser verändert haben.",h="Am Spiegelsee im Wald von Elwynn wird Wasser für Jennea Haubitz in Sturmwind gesammelt.",kw={"arkane verderbnis","wald von elwynn","fläschchen","jennea haubitz","spiegelsee","sturmwind","wasserprobe","magiersanktum"},ang={["class:Mage"]="Als Magier in der Ausbildung beim Magiersanktum holt Ihr diese Probe als eine Eurer ersten Aufgaben. Dabei lernt Ihr, die Leylinien der Umgebung zu beobachten und unkontrolliert austretende Magie zu erkennen."},sec={{t="Elwynns Gewässer auf dem Prüfstand",b="Jennea Haubitz schickt vielversprechende Lehrlinge los, um Wasser aus dem Spiegelsee zu sammeln. Der See liegt gleich südwestlich des Tors von Sturmwind, wo sie ein speziell vorbereitetes Fläschchen am Fuße seines Wasserfalls füllen.\n\nDas Magiersanktum in Sturmwind befürchtet, dass die mystischen Bahnen der Welt nach katastrophalen Konflikten weiterhin gestört sind. Seine Magier werden die Probe auf verirrte magische Verderbnis in den Wasserläufen untersuchen, die die Menschen der Umgebung nutzen."}},faq={{q="Was ist die Probe des Spiegelseewassers?",a="Die Probe des Spiegelseewassers ist Wasser eines Wasserfalls im Wald von Elwynn, aufbewahrt in Jenneas Fläschchen. Magiernovizen sammeln es zur Untersuchung im Magiersanktum.",al={"spiegelsee probe","wasserprobe gegenstand","jennea wasser"}},{q="Warum möchte Jennea Haubitz diese Wasserprobe?",a="Jüngste mystische Umwälzungen in ganz Azeroth haben stabile magische Strömungen gestört. Jennea Haubitz befürchtet, dass unkontrollierte magische Energie die Natur verändern und das örtliche Trinkwasser vergiften könnte.",al={"warum spiegelsee untersuchen","jennea haubitz absicht","magische verderbnis im wasser"}},{q="Wo wird die Probe gesammelt?",a="Die Probe stammt vom Fuße des Wasserfalls, der in den Spiegelsee fließt, südwestlich des Tors von Sturmwind im Wald von Elwynn.",al={"wo probe holen","spiegelsee lage","probe wasserfall"}},{q="Was geschieht, wenn sich das Wasser als magisch verunreinigt erweist?",a="Jennea Haubitz befürchtet, dass langfristiges Trinken aus dem Spiegelsee schädliche magische Auswirkungen haben könnte, falls Leyströme die Wasserversorgung verunreinigt haben.",al={"verunreinigtes wasser auswirkungen","ist der spiegelsee vergiftet"}}},fx={["935f4959"]={q="Woher stammt die Probe des Spiegelseewassers und wer hat sie gesammelt?",a="Die Probe wird direkt am Fuß des Wasserfalls gesammelt, der in den Mirror Lake stürzt, südwestlich der Tore von Sturmwind im Wald von Elwynn. Mit einer leeren Phiole, die Ihr von der Magierausbilderin Jennea Haubitz erhaltet, schöpft Ihr das Wasser selbst im Auftrag der Zauberwirker von Sturmwind, damit diese den Zustand der umliegenden wilden Strömungen untersuchen können.",al={"herkunft probe des spiegelseewassers","wer hat probe des spiegelseewassers erstellt","ursprung probe des spiegelseewassers"}}},fp="24,166,28.411.0,37.151.0,46.177.0,30.123.0,60.154.0"}
P.entries["item:mist-veil-s-lockbox"] = {n="Schließkassette der Nebelschleier",s="Vor der Dunkelküste überfielen Küstenmurlocs die Nebelschleier und versenkten sie. Das Nachtelfenschiff ruht nun unter den Wellen, mit dem Logbuch und den persönlichen Gegenständen des Kapitäns in seiner Schließkassette.",h="Vor der Dunkelküste überfielen Küstenmurlocs die Nebelschleier und versenkten sie.",kw={"auberdine","dunkelküste","gorbold stahlhand","schließkassette","nebelschleier","murloc","schiffswrack","silver dawning"},ang={["faction:Alliance"]="Als Mitglied der Allianz könnt Ihr die gefallenen Besatzungsmitglieder ehren und Auberdines Seefahrergemeinschaft helfen.",["race:NightElf"]="Als Nachtelf könnt Ihr helfen, das Logbuch des gefallenen Kapitäns zurückzubringen und seinen Geist in den Gewässern vor der Dunkelküste zur Ruhe zu betten."},sec={{t="In der Tiefe verloren",b="Das Nachtelfenschiff Nebelschleier sank auf der Fahrt nach Auberdine. Küstenmurlocs überwältigten es und sein Schwesterschiff, die Silver Dawning. Der Kapitän kam ums Leben, und sein Logbuch sowie seine persönlichen Gegenstände bleiben in der Schließkassette im überfluteten Laderaum verschlossen. Noch immer umgeben Murlocs das Wrack."},{t="Ruhe für die Besatzung",b="Überlebende Seeleute erreichten Auberdine, doch sie trauern noch immer um ihr verlorenes Schiff und ihren Kommandanten. Gorbold Stahlhand sucht die Schließkassette der Nebelschleier, damit die letzten Habseligkeiten des Kapitäns gewürdigt und zur Ruhe gebettet werden können. Ihre Bergung aus dem überfluteten Wrack könnte den Überlebenden auf dem Festland Trost spenden."}},faq={{q="Was befindet sich in der Schließkassette der Nebelschleier?",a="Die Schließkassette der Nebelschleier enthält das Logbuch und die persönlichen Gegenstände des Kapitäns. Der Kapitän kam beim Untergang des Schiffs ums Leben, und die überlebenden Besatzungsmitglieder in Auberdine wollen die Andenken zurückerhalten, um ihren gefallenen Anführer zu ehren.",al={"inhalt der schließkassette der nebelschleier","was enthält die schließkassette","was ist in der kiste"}},{q="Wie sank die Nebelschleier?",a="Küstenmurlocs überfielen die Nebelschleier auf ihrer Fahrt nach Auberdine. Sie überwältigten sie und ihr Schwesterschiff, die Silver Dawning, und beide Schiffe sanken.",al={"warum erlitt das schiff schiffbruch","wer versenkte die nebelschleier","was geschah mit der nebelschleier"}},{q="Wo ist die Schließkassette zu finden?",a="Die Schließkassette liegt unter Wasser vor der Dunkelküste, nördlich von Auberdine, im überfluteten Rumpf der gesunkenen Nebelschleier. Murlocs bevölkern das Wrack.",al={"wo ist die schließkassette der nebelschleier","fundort der nebelschleier","fundort der schließkassette"}},{q="Wer möchte die Schließkassette bergen lassen?",a="Gorbold Stahlhand in Auberdine sucht die Schließkassette für die überlebenden Besatzungsmitglieder. Er hofft, den gefallenen Kapitän zu ehren und ihnen Frieden zu bringen.",al={"wer nimmt die schließkassette entgegen","wer vergibt die quest","gorbold schließkassettenquest"}}},fx={fab3edd7={q="Was ist die Schließkassette der Nebelschleier?",a="Es ist die Kapitänstruhe, die vom gesunkenen Schiff Nebelschleier geborgen wurde, welches unter den Wellen vor der Küste der Dunkelküste nördlich von Auberdine ruht. Sie wurde sicher an Bord des Schiffes aufbewahrt, bis Murlocs das Schiff zum Sinken brachten, und bewahrt die Logbücher, Tagebücher und persönlichen Gegenstände des verstorbenen Nachtelfenkapitäns von der verhängnisvollen Reise.",al={"was ist die schließkassette der nebelschleier","schließkassette der nebelschleier","was ist die schließkassette"}}},fp="19,179,18.284.0,17.291.0,35.199.0,27.152.0,27.131.0,32.131.0"}
P.entries["item:mo-grosh-crystal"] = {n="Kristall der Mo'grosh",s="Im nordöstlichen Loch Modan bauen Mo'grosh-Oger seltene Kristalle mit ungewöhnlichen alchemistischen Eigenschaften ab und bewachen sie. Zwergeningenieure nutzen sie, um Sprengstoffe der Dunkeleisenzwerge zu neutralisieren.",h="Im nordöstlichen Loch Modan bauen Mo'grosh-Oger seltene Kristalle mit ungewöhnlichen alchemistischen...",kw={"dark threat looms","hinderweir","loch modan","kristall der mo'grosh","mogrosh","der steinwerkdamm"},ang={["profession:Mining"]="Als Bergarbeiter erkennt Ihr, dass diese rohen Mineralien aus dem tiefsten Inneren des Ogergebiets stammen. Sie reagieren auf ungewöhnliche Weise, wenn sie mit organischen Reagenzien verbunden werden.",["race:Dwarf"]="Als Zwerg wisst Ihr, dass die Verteidigung des Steinwerkdamms Erfindungsreichtum erfordert. Zwergeningenieure verwandeln den von den Ogern abgebauten Schatz in einen Schutz gegen die Heimtücke der Dunkeleisenzwerge."},sec={{t="Eine seltene Ware der Oger",b="Mo'grosh-Oger bauen die Kristalle in ihrer Festung im nordöstlichen Loch Modan ab. Obwohl der Clan rohe Kraft der feinen Metallarbeit vorzieht, schätzen seine Mitglieder diese Steine. Vollstrecker, mystische Schamanen und hochgewachsene Anführer tragen sie bei sich. Die Kristalle sind selten, daher bewachen die Oger sie streng innerhalb der Festung Mo'grosh."},{t="Der Bedrohung der Dunkeleisenzwerge begegnen",b="Chefingenieur Hinderweir sucht einen Kristall der Mo'grosh, Lauerergift von Spinnen und Krokiliskenzähren. Er hat erfahren, dass Saboteure der Dunkeleisenzwerge einen Angriff auf den Steinwerkdamm planen. Zwergeningenieure verbinden das Mineral mit diesen Reagenzien zu einer Mischung, die die instabilen Sprengstoffe unschädlich macht und entschärft, bevor das Tal überflutet werden kann."}},faq={{q="Woher stammen die Kristalle der Mo'grosh?",a="Mo'grosh-Oger bauen die Kristalle im nordöstlichen Loch Modan ab und bewahren sie dort auf. Jedes Clanmitglied in der Festung Mo'grosh könnte einen bei sich tragen, darunter Mystiker, Schläger, Vollstrecker und Schamanen.",al={"kristall der mo'grosh fundort","wo kristall der mo'grosh finden","wer lässt kristall der mo'grosh fallen"}},{q="Wofür wird der Kristall verwendet?",a="Chefingenieur Hinderweir am Steinwerkdamm benötigt einen Kristall für eine neutralisierende Mischung. Zusammen mit Lauerergift und Krokiliskenzähren macht er Sprengstoffe der Dunkeleisenzwerge unschädlich, die zur Sabotage des Damms bestimmt sind.",al={"was bewirkt kristall der mo'grosh","verwendung des kristalls der mo'grosh","warum hinderweir den kristall will"}},{q="Warum bauen die Oger diese Kristalle ab?",a="Mo'grosh-Oger bauen seltene Kristalle in den Hügeln rund um ihre Festung ab. Wofür sie die Kristalle verwenden, ist nicht überliefert.",al={"warum oger kristalle haben","hintergrund der ogerkristalle"}}},fx={["1713c585"]={q="Was ist ein Kristall der Mo'grosh?",a="Ein Kristall der Mo'grosh ist ein außergewöhnlich seltenes Mineral, das von den Mo'grosh-Ogern in ihrer Festung nordöstlich von Loch Modan abgebaut wird. Da er für seine ungewöhnlichen Eigenschaften geschätzt wird, identifiziert ihn Chefingenieur Hinderweir als wesentlichen Bestandteil bei der Herstellung einer speziellen Mixtur, die dazu dienen soll, die Dunkelzwerg-Sprengstoffe zu entschärfen, die den Steinwerkdamm bedrohen.",al={"was ist ein kristall der mo'grosh","kristall der mo'grosh hintergrund","kristall der mo'grosh bedeutung"}}},fp="16,170,23.326.0,31.326.1,37.180.0,29.200.0,40.119.0"}
P.entries["item:modr-fragment"] = {n="Modrfragment",s="In Whelgar Excavation Site liegt das Modrfragment zwischen Relikten und loser Erde in einer von Raptoren überrannten Ausgrabung. Seine uralte Titanschrift füllt eine von vier Lücken im Goazstein.",h="In Whelgar Excavation Site liegt das Modrfragment zwischen Relikten und loser Erde in einer von Raptoren...",kw={"ados","ausgrabung","goazstein","golm","modrfragment","neru","alte götter","titan","sumpfland","whelgar"},ang={["faction:Alliance"]="Als Reisender der Allianz helft Ihr Ausgrabungsleiter Whelgar, der überrannten Ausgrabung zu trotzen und wertvolle historische Forschung für Eisenschmiede zu bewahren.",["race:Dwarf"]="Als Zwerg wisst Ihr, dass die Explorers' League nach verlorenen Stücken wie dem Modrfragment sucht, um das Erbe der Titanen zu entschlüsseln und die uralte Geschichte Eures Volkes aufzudecken."},sec={{t="Ein Stück des Goazsteins",b="Ausgrabungsleiter Whelgar legte den Goazstein bei seiner Ausgrabung im Sumpfland frei. Die gewaltige Tafel trägt uralte Titanschrift. Bösartige Raptoren vertrieben die Explorers' League von der Stätte, bevor ihre Mitglieder ihre Arbeit abschließen konnten. Die übersetzte Inschrift bricht an vier Lücken ab und lässt Warnungen vor einem göttlichen Plan und einer dem Untergang geweihten Prophezeiung unvollendet. Das Modrfragment ist eines der fehlenden Stücke, zurückgelassen zwischen Relikten und umgewühlter Erde, als die Ausgräber um ihr Leben flohen."},{t="Geheimnisse unter der Erde",b="Ausgrabungsleiter Whelgar kann die vollständige Inschrift wiederherstellen, indem er das Modrfragment mit den Fragmenten von Ados, Golm und Neru zusammenfügt. Die übersetzten Worte erzählen vom Anbeginn der Welt und sprechen von „Alten Göttern ... Unter dem Land angekettet“. Unter dem sumpfigen Boden hat die Ausgrabung Spuren eines Kampfes aus den Anfängen der Welt freigelegt."}},faq={{q="Was ist das Modrfragment?",a="Das Modrfragment ist ein mit Schriftzeichen versehenes Steinstück, das vom Goazstein abgebrochen ist. Ausgrabungsleiter Whelgar fand das uralte Relikt der Titanen in Whelgar Excavation Site im Sumpfland.",al={"modrfragment","was ist modr","modr relikt"}},{q="Wer sucht nach diesem Fragment?",a="Ausgrabungsleiter Whelgar, ein Archäologe der Explorers' League, sucht das Modrfragment, um den fehlenden Text der Tafel zu vervollständigen. Er hält sich am Rand der von Raptoren heimgesuchten Ausgrabungsstätte auf.",al={"wer sucht das modrfragment","whelgar fragment quest"}},{q="Was geschieht, wenn alle vier Fragmente gesammelt sind?",a="Das Zusammenfügen des Modrfragments mit den Fragmenten von Ados, Golm und Neru ermöglicht es Ausgrabungsleiter Whelgar, den Goazstein wiederherzustellen. Seine vollständige Titanschrift spricht von „Alten Göttern ... Unter dem Land angekettet“.",al={"goazstein vervollständigt","uncovering the past ende","was steht auf dem goazstein"}},{q="Wo ist das Fragment zu finden?",a="Ihr könnt das Modrfragment über Whelgar Excavation Site östlich vom Hafen von Menethil im Sumpfland verstreut finden. Es liegt in uralten Reliktkrügen oder in Flecken loser Erde, die von angriffslustigen Raptoren bewacht werden.",al={"modrfragment fundort","wo ist modr zu finden"}}},fx={c1df2f2b={q="Woher kommt das Modrfragment und wer hat es erschaffen?",a="Das Modrfragment ist ein Bruchstück des Goazsteins, eines uralten Relikts, das an der Ausgrabungsstätte östlich des Hafens von Menethil im Sumpfland entdeckt wurde. Mit Titanenschrift versehen, ist der Stein ein Artefakt der Titanen, die die Welt in Urzeiten formten und geheimnisvolle Aufzeichnungen über ihren göttlichen Plan und Untergangsprophezeiungen hinterließen.",al={"modrfragment herkunft","wer stellte das modrfragment her","woher kam das modrfragment"}}},fp="13,167,25.455.0,25.315.1,26.164.0,33.181.0,50.181.1,28.194.0"}
P.entries["item:moldy-tome"] = {n="Schimmliger Foliant",s="An der Küste von Hillsbrad liegt der Schimmlige Foliant nach einem Schiffbruch in Trümmern. Einst Teil des Tome of the Cabal, lockt er noch immer Hexenmeister an, die sein Wissen über Dämonenbeschwörung suchen.",h="An der Küste von Hillsbrad liegt der Schimmlige Foliant nach einem Schiffbruch in Trümmern.",kw={"azurschacht","teufelsjäger","hillsbrad","schimmliger foliant","süderstade","zerlumptes manuskript","tome of the cabal","hexenmeister"},ang={["class:Warlock"]="Als Hexenmeister sucht Ihr den Schimmligen Folianten, um die Rituale wiederzuerlangen, die nötig sind, um einen Teufelsjäger zu befehligen."},sec={{t="Den Wellen zum Opfer",b="Tome of the Cabal war ein seltenes Werk über die dunklen Künste, das in Lordaeron aufbewahrt wurde. Jemand schändete es und riss es entzwei. Eine Hälfte, heute als Schimmliger Foliant bekannt, reiste auf einem Schiff nach Süden zum Hafen von Menethil und nach Eisenschmiede. Das Schiff kam nie an. Es sank in den gefährlichen Gewässern westlich von Süderstade, und die erhaltene Hälfte wurde südlich des Azurschachts an Land gespült. Feuchtigkeit und Brandung ruinierten seine Seiten, während Murlocs die Küste von Hillsbrad nach Brauchbarem durchsuchten."},{t="Das dunkle Werk bergen",b="Obwohl sein Pergament schimmelt und verrottet, birgt der Schimmlige Foliant noch immer mächtiges Wissen über Dämonen. Hexenmeister, die ihn suchen, wagen sich in die Küstenlager. Krom Starkarm leitet einige von ihnen in Eisenschmiede an, während Jorah Annison andere in Unterstadt anleitet. Mit seinem Gegenstück vereint, dem Zerlumpten Manuskript aus den Höhlen von Tausend Nadeln, liefert das wiederhergestellte Buch die genauen Worte, um einen Teufelsjäger zu beschwören und zu binden."}},faq={{q="Was ist der Schimmlige Foliant?",a="Der Schimmlige Foliant ist die Hälfte des seltenen Tome of the Cabal, eines finsteren Buches mit Ritualen zur Beschwörung von Dämonen. Durchnässt und verrottet ist er die Hälfte, die bei einem Schiffbruch verloren ging.",al={"schimmliges buch","was ist dieser gegenstand","schimmliger foliant hintergrund"}},{q="Wo landete der Schimmlige Foliant?",a="Der Schimmlige Foliant wurde im Vorgebirge des Hügellands an Land gespült, westlich von Süderstade und südlich des Azurschachts. Murlocs an der Küste bewahren ihn in ihrem Lager auf.",al={"schimmliger foliant fundort","wo ist der schimmlige foliant","wo den schimmligen folianten finden"}},{q="Warum war der Foliant auf einem Schiff?",a="Ein Schiff brachte den Schimmligen Folianten von Lordaeron in Richtung des Hafens von Menethil, bestimmt für Gelehrte in Eisenschmiede. Das Schiff sank vor der Küste von Hillsbrad, bevor es seine Reise vollenden konnte.",al={"warum ging er auf see verloren","schiffbruch foliant","transport des folianten"}},{q="Was wird benötigt, um Tome of the Cabal zu vervollständigen?",a="Tome of the Cabal wird vervollständigt, indem der Schimmlige Foliant mit dem Zerlumpten Manuskript, seiner anderen Hälfte, vereint wird. Das Manuskript landete in der Spalthufhöhle in Tausend Nadeln.",al={"andere hälfte des folianten","fehlende seiten","tome of the cabal teile"}}},fx={f96f31c9={q="Woher stammt der Schimmlige Foliant?",a="Der Schimmlige Foliant war ursprünglich Teil eines einzigen, einzigartigen Bandes namens Tome of the Cabal, der einst in den großen Hallen von Lordaeron aufbewahrt wurde. Vor langer Zeit wurde das einzelne Grimoire mutwillig zerstört und ein beträchtlicher Teil seines Pergaments aus dem Einband gerissen. Der überlebende Teil des Buches sollte von Hillsbrad über das Meer nach Hafen von Menethil und Eisenschmiede verschifft werden, doch das Schiff, das ihn transportierte, zerschellte an der Küste westlich von Süderstade, wodurch die feuchten Seiten im seichten Wasser verrotteten.",al={"ursprung des schimmligen folianten","wer erschuf den schimmligen folianten","wo wurde der schimmlige foliant aufbewahrt","geschichte des schimmligen folianten"}},["53a1a6b9"]={q="Warum will jemand den Schimmligen Folianten haben?",a="Gelehrte und Praktizierende der dunklen Künste suchen ihn, weil nur ein einziges Exemplar von Tome of the Cabal jemals geschrieben wurde. Seine arkanen Passagen enthalten seltenes und streng gehütetes Hexenmeisterwissen, einschließlich Geheimnissen, die für die Beherrschung der Beschwörung und Bindung von Teufelsjägern unerlässlich sind. Gelehrte wie Krom Starkarm in Eisenschmiede und Jorah Annison in der Unterstadt begehren sogar einen kurzen Blick auf seinen verbotenen Text, weshalb die Bergung dieses wassergetränkten Überrests entscheidend für die Wiedervereinigung des vollständigen Werks ist.",al={"warum den schimmligen folianten finden","wer will den schimmligen folianten","warum ist der schimmlige foliant wichtig","warum wollen hexenmeister den schimmligen folianten"}}},fp="10,171,17.420.0,24.412.1,23.159.0,32.145.0,27.166.0,49.169.0"}
P.entries["item:moonpetal-lily"] = {n="Mondblütenlilie",s="An Teldrassils Süßwasserbecken liefern Mondblütenlilien Blütenblätter, die für ihre stärkende Kraft geschätzt werden. Heiler verwenden sie in Heilmitteln und Heiltränken.",h="An Teldrassils Süßwasserbecken liefern Mondblütenlilien Blütenblätter, die für ihre stärkende Kraft geschätzt...",kw={"aldrassil","gegengift","dirania silberschein","iverron","mondblüte","mondblütenlilie","laubschattental","teldrassil"},ang={["profession:Herbalism"]="In akuten Notlagen sammeln Heiler Mondblütenlilien von Hand. Die Blumen zeigen die stärkende Kraft von Teldrassils Pflanzen.",["race:NightElf"]="Als junger Kaldorei lernt Ihr bei Eurer Ausbildung im Laubschattental, wie heimische Pflanzen wie die Mondblütenlilie heilen können. Es ist eine frühe Lektion im Leben mit der Natur."},sec={{t="Pflanzen der Wasserbecken",b="Mondblütenlilien wachsen an den feuchten Ufern von Süßwasserbecken und Teichen. Sie sind nordwestlich von Aldrassil im Laubschattental häufig anzutreffen. Wie andere Pflanzen auf dem jungen Weltenbaum schöpfen sie aus der Essenz von Teldrassils geschützten Hainen. Ihre breiten Blütenblätter leuchten am Wasser, wo die Feuchtigkeit sie gedeihen lässt."},{t="Natürliche Gegengifte",b="Heiler und Kräuterkundige der Nachtelfen schätzen Mondblütenlilien für ihre heilenden Eigenschaften. Mit Waldpflanzen wie Hyazinthenpilzen vermischt, wirken die Lilien beruhigend und stabilisierend. Heiler brauen daraus Gegengifte gegen tödliche Giftstoffe, darunter das Gift der Waldweberspinnen in der Schattenweberhöhle."}},faq={{q="Wo wachsen Mondblütenlilien?",a="Mondblütenlilien wachsen an den Ufern zweier Süßwasserteiche nordwestlich von Aldrassil im Laubschattental auf Teldrassil.",al={"wo mondblütenlilien finden","mondblütenlilie fundort","lilienfundorte"}},{q="Wofür werden Mondblütenlilien verwendet?",a="Mondblütenlilien haben stärkende und heilende Eigenschaften. Im Laubschattental kombiniert Dirania Silberschein sie mit Hyazinthenpilzen und Waldwebersekret, um ein Gegengift gegen Spinnengift zu brauen.",al={"mondblütenlilie verwendung","was bewirkt die mondblütenlilie"}},{q="Wer braucht ein Gegengift aus diesen Lilien?",a="Iverron ist ein Nachtelf, der nahe der Schattenweberhöhle von Waldweberspinnen gebissen wurde. Er braucht ein Gegengift aus Mondblütenlilien, um zu überleben.",al={"für wen ist das gegengift","iverron gift"}},{q="Können Mondblütenlilien außerhalb von Teldrassil gesammelt werden?",a="Mondblütenlilien wachsen an Teldrassils abgeschiedenen Wasserbecken. Sie sind in den geschützten Ästen des Laubschattentals bekannt.",al={"wachsen lilien auch anderswo","mondblütenlilie andere gebiete"}}},fx={["1aae6896"]={q="Was ist eine Mondblütenlilie?",a="Die Mondblütenlilie ist eine große Wasserblume, die in den ruhigen Gewässern von Teldrassil heimisch ist. Bekannt für ihre starken natürlichen Heilkräfte, gedeiht sie in feuchtem Boden an den Rändern schattiger Waldtümpel und Teiche, wie jenen, die in der Nähe von Aldrassil im Laubschattental liegen.",al={"was ist eine mondblütenlilie","informationen zur mondblütenlilie","über die mondblütenlilie"}}},fp="14,156,18.314.0,17.289.0,31.114.0,35.186.0,45.132.0,55.110.0"}
P.entries["item:moonstalker-fang"] = {n="Mondpirscherfangzahn",s="Nahe Auberdine sammeln Reisende Mondpirscherfangzähne für Hexknall Kurbeldrehs Probenahmegeräte. Die Zähne stammen von den Moonstalkers der Dunkelküste.",h="Nahe Auberdine sammeln Reisende Mondpirscherfangzähne für Hexknall Kurbeldrehs Probenahmegeräte.",kw={"buzzbox 323","dunkelküste","moonstalker","mondpirscherfangzahn","shadowclaw","hexknall kurbeldreh"},ang={["class:Hunter"]="Als Jäger braucht Ihr scharfe Sinne, um Moonstalkers entgegenzutreten, Lauerjägern, die mit dem dunklen Blätterdach der Dunkelküste verschmelzen.",["race:Gnome"]="Als Gnom erkennt Ihr Hexknall Kurbeldrehs Geräte zur Fernkommunikation vielleicht als gnomische Ingenieurskunst. Seine verwaschene Aussprache und ungewöhnliche Probenwahl sorgen dennoch für hochgezogene Augenbrauen."},sec={{t="Ein Mahlmechanismus",b="Mondpirscherfangzähne stammen von Säbelkatzen, die an den Waldrändern der Dunkelküste jagen. Ihre langen Zähne können Fleisch und Knochen durchtrennen. Hexknall Kurbeldreh, ein exzentrischer gnomischer Tüftler, verwendet sie für einen anderen Zweck. Nördlich von Auberdine nahe der Brücke zermahlt Buzzbox 323 die widerstandsfähigen Fangzähne für seine ökologischen Untersuchungen zu Staub."}},faq={{q="Woher stammen Mondpirscherfangzähne?",a="Mondpirscherfangzähne stammen von den Moonstalkers der Dunkelküste, von Kümmerlingen und ausgewachsenen Tieren bis hin zu Vatertieren, Matriarchinnen und dem Pirscher Shadowclaw.",al={"wo mondpirscherfangzähne bekommen","wer lässt mondpirscherfangzähne fallen","herkunft der fangzähne"}},{q="Wer möchte Mondpirscherfangzähne?",a="Hexknall Kurbeldreh braucht sechs Mondpirscherfangzähne für Buzzbox 323, sein automatisiertes Überwachungsgerät nördlich von Auberdine nahe der Flussbrücke.",al={"wer braucht fangzähne","welche quest benötigt fangzähne","buzzbox 323 abgabe"}},{q="Was geschieht mit den Fangzähnen in der Maschine?",a="Die Zahnräder von Buzzbox 323 zermahlen die harten Fangzähne zu feinem Staub für Hexknalls Feldversuche.",al={"was macht buzzbox 323","warum fangzähne zermahlen"}}},fx={fbcb9ad4={q="Was ist ein Mondpirscherfangzahn?",a="Ein Mondpirscherfangzahn ist ein scharfer, räuberischer Eckzahn, der von den räuberischen Mondpirschern stammt, die durch die nebligen Wälder der Dunkelküste streifen. Diese nachtaktiven Säbelkatzen benutzen ihre gewaltigen Fangzähne, um Waldbeute zu jagen, was sie zu begehrten Trophäen und überraschend haltbarem Material für seltsame lokale Konstruktionen macht.",al={"mondpirscherfangzahn","was sind mondpirscherfangzähne","mondpirscherzähne"}}},fp="16,140,20.312.0,37.125.0,28.138.0,45.88.0"}
P.entries["item:moonwell-water-tube"] = {n="Phiole mit Mondbrunnenwasser",s="In Auberdine birgt Mondbrunnenwasser reinigende Naturmagie. Die Phiole dient dazu, einen geheimnisvollen roten Kristall in den östlichen Bergkämmen der Dunkelküste zu untersuchen.",h="In Auberdine birgt Mondbrunnenwasser reinigende Naturmagie.",kw={"as water cascades","auberdine","dunkelküste","leere wasserphiole","teufelswald","phiole mit mondbrunnenwasser","roter kristall"},ang={["class:Druid"]="Druiden kennen Mondbrunnenwasser als lebenswichtigen Träger des Gleichgewichts der Natur, der unnatürlicher Verderbnis entgegenwirken kann.",["race:NightElf"]="Für Nachtelfen spiegelt die Untersuchung fremder Verderbnis mit gesegnetem Mondbrunnenwasser ihr Vertrauen auf Elunes Gnade wider, verborgene Wahrheiten zu enthüllen."},sec={{t="Ein Gefäß reinigenden Wassers",b="Wasser aus Auberdines Mondbrunnen füllt die Phiole. Das heilige Becken ist mit Elune verbunden und birgt heilende, reinigende Magie. Schon eine kleine Menge lässt sich gegen Verderbnis einsetzen oder zur Untersuchung seltsamer mystischer Kräfte nutzen."},{t="Untersuchung des roten Kristalls",b="Forscher bereiteten die Phiole vor, um einen riesigen roten Kristall zu untersuchen, der an den östlichen Klippen der Dunkelküste aufgetaucht war. Die verderbten Höhen des Teufelswalds ragen über der Bergwand auf, weshalb sie befürchteten, dass der Kristall denselben dunklen Ursprung hatte. Wenn gesegnetes Wasser über seine Facetten fließt, wird der undurchsichtige Stein kurz durchsichtig und offenbart die Geheimnisse in seinem Inneren."}},faq={{q="Woher wird das Wasser geschöpft?",a="Das Wasser stammt aus dem heiligen Mondbrunnen in Auberdine, dem Zufluchtsort der Nachtelfen an der Westküste der Dunkelküste.",al={"wo die phiole füllen","wasserquelle der phiole","auberdine mondbrunnenwasser"}},{q="Warum wird Mondbrunnenwasser auf den roten Kristall gegossen?",a="Mondbrunnenwasser birgt konzentrierte Natur- und Mondmagie. Über den seltsamen roten Kristall gegossen, prüft es die mystische Natur des Steins und macht seine undurchsichtige Oberfläche kurz durchsichtig.",al={"warum mondbrunnenwasser","zweck der wasserphiole","was bewirkt das wasser"}},{q="Warum bereitet der Kristall den Forschern Sorgen?",a="Der Kristall liegt unterhalb der östlichen Berge, die an den Teufelswald grenzen. Dessen tiefe dämonische Verderbnis lässt Gelehrte befürchten, dass die fremdartige Formation Verderbnis hinab in die Dunkelküste trägt.",al={"warum den kristall untersuchen","gefahr des roten kristalls","verbindung zum teufelswald"}}},fx={f51af5d3={q="Was ist die Phiole mit Mondbrunnenwasser?",a="Die Phiole mit Mondbrunnenwasser ist ein einfaches Glasfläschchen, gefüllt mit gesegnetem Wasser, das direkt aus dem Mondbrunnen in Auberdine stammt. Mondbrunnen enthalten mächtige, heilige Magie, die von Nachtelfdruiden und Priesterinnen genährt wird, was die Flüssigkeit darin zu weit mehr als gewöhnlichem Quellwasser macht. Wenn Ihr sie bei Euch tragt, können Forscher ein kleines, konzentriertes Maß von Elunes reinigender Kraft ins Feld bringen, um unbekannte Phänomene zu testen.",al={"was ist die phiole mit mondbrunnenwasser","gegenstand phiole mit mondbrunnenwasser","was ist diese wasserphiole"}},["21e1d317"]={q="Warum wird die Phiole mit Mondbrunnenwasser benötigt?",a="Ermittler in Auberdine benötigen die Phiole mit Mondbrunnenwasser, um einen bedrohlichen roten Kristall zu analysieren, der in den östlichen Bergen der Dunkelküste eingebettet ist. Da vermutet wird, dass der Kristall eine dunkle Verbindung zum verderbten Teufelswald weit oben teilt, glauben die Forscher, dass das Gießen der reinen, mächtigen Magie des Mondbrunnens über seine Oberfläche sicher mit dem Stein reagieren und seine innere Zusammensetzung enthüllen wird.",al={"warum brauche ich die phiole mit mondbrunnenwasser","warum mondbrunnenwasser wollen","zweck der phiole mit mondbrunnenwasser"}}},fp="19,146,28.203.0,29.339.1,30.106.0,42.174.0,52.175.0"}
P.entries["item:mossy-tumor"] = {n="Moosartiger Tumor",s="Rund um den Quellsee breiten sich moosartige Tumore unter Teldrassils Timberlingen aus. Diese giftigen Wucherungen werden aus ihrer Rinde und ihrem Fleisch geschnitten und zeigen, wie die Verderbnis im jungen Weltenbaum Fuß fasst.",h="Rund um den Quellsee breiten sich moosartige Tumore unter Teldrassils Timberlingen aus.",kw={"verderbnis","darnassus","moosartiger tumor","rellian greenspyre","teldrassil","timberling","quellsee"},ang={["class:Druid"]="Als Druide, der sich dem Gleichgewicht der Natur verschrieben hat, mögt Ihr giftige Tumore an Pflanzenwächtern wie Timberlingen als beunruhigendes Zeichen empfinden. Mit Teldrassil stimmt etwas ganz und gar nicht.",["race:NightElf"]="Als Nachtelf wisst Ihr, dass Euer Volk Teldrassil pflanzte, um seine verlorene Verbindung zur Natur wiederherzustellen. Krankhafte Wucherungen an Eurer neuen Heimat sind ein beunruhigendes Omen."},sec={{t="Ein Zeichen von Teldrassils Leiden",b="Teldrassils Timberlinge pflegten einst die Äste des großen Baumes. Viele sind nun feindselig und krank, und ihre moosartigen Tumore machen diese Krankheit sichtbar. Voller Giftstoffe breiten sich die Wucherungen auf Schlammbestien, Tramplern und uralten Timberlingen rund um den Quellsee aus. Rellian Greenspyre und die Hüter in Darnassus schicken Reisende aus, um sie herauszuschneiden und gründlich zu verbrennen. Ihr Gift darf im Boden der Insel keine tieferen Wurzeln schlagen."}},faq={{q="Was ist ein moosartiger Tumor?",a="Ein moosartiger Tumor ist eine krankhafte Wucherung, die aus einem verderbten Timberling geschnitten wird. Sein Gift zeigt, dass eine unnatürliche Verderbnis Teldrassils Naturgeister befällt.",al={"moosartiger tumor","was ist dieser tumor","timberling-tumor"}},{q="Wo findet man moosartige Tumore?",a="Ihr findet moosartige Tumore an verderbten Timberlingen rund um den Quellsee im Norden Teldrassils. Sie wachsen auf Timberling-Tramplern, Schlammbestien und uralten Timberlingen.",al={"wo bekommt man tumore","moosartiger tumor beute","timberling fundort"}},{q="Warum will Rellian Greenspyre diese Tumore?",a="Rellian Greenspyre sammelt die Tumore, um die Verderbnis einzudämmen, die Teldrassil befällt. Er lässt sie zu Asche verbrennen, damit ihr konzentriertes Gift nicht wieder in den Boden und ins Wasser sickern kann.",al={"rellian greenspyre tumore","warum tumore verbrennen"}},{q="Warum erkranken die Timberlinge?",a="Eine Bösartigkeit breitet sich über Teldrassil aus und verformt seine Hüter und wilden Geschöpfe. Die Nachtelfen erforschen den wahren Ursprung der Krankheit, während Timberlinge mit sichtbaren Tumoren als unrettbar gelten.",al={"warum sind timberlinge krank","timberling verderbnis"}}},fp="11,189,33.427.0,22.149.0,31.164.0,46.184.0,42.220.0"}
P.entries["item:mountain-lion-blood"] = {n="Berglöwenblut",s="In Hillsbrad und Alterac sucht Apotheker Lydon Berglöwenblut. In Tarrens Mühle braucht er frisches Blut für das Elixier der Schmerzen der Königlichen Apothekervereinigung.",h="In Hillsbrad und Alterac sucht Apotheker Lydon Berglöwenblut.",kw={"alterac","apotheker lydon","elixier der schmerzen","hillsbrad","berglöwenblut","königliche apothekervereinigung","tarrens mühle"},ang={["faction:Horde"]="Als Mitglied der Horde stärkt Ihr durch das Sammeln tierischer Reagenzien um Tarrens Mühle Eure Präsenz gegenüber feindlichen Menschenenklaven in Hillsbrad.",["race:Undead"]="Als Untoter helft Ihr mit jeder gesammelten Phiole der Königlichen Apothekervereinigung, biologische Waffen zu entwickeln, um Lordaeron für die Verlassenen zu sichern."},sec={{t="Reagenz der Hügel",b="Berglöwen jagen im Hochland und in den Ausläufern von Hillsbrad und Alterac. Jäger schätzen ihre Felle und Klauen, während Verlassene der Königlichen Apothekervereinigung nach dem Blut in ihren Adern suchen. Apotheker Lydon in Tarrens Mühle glaubt, dass frisches Berglöwenblut die Grundlage für ein wirksames Gebräu bilden kann. Es soll den Lebenden Elend bringen."},{t="Nahrung für New Plague",b="Apotheker Lydons Arbeit in Tarrens Mühle unterstützt die Bemühungen der Königlichen Apothekervereinigung, New Plague der Verlassenen zu vollenden. Er sammelt Blut von kräftigen wilden Bestien, um ein Gebräu namens Elixier der Schmerzen zu verfeinern. Mit seinen Experimenten erprobt er, wie sich örtliche organische Verbindungen gegen die Feinde der Dunklen Fürstin einsetzen lassen."}},faq={{q="Wofür wird Berglöwenblut verwendet?",a="Apotheker Lydon in Tarrens Mühle braucht zehn Phiolen Berglöwenblut für das Elixier der Schmerzen. Die Königliche Apothekervereinigung erforscht neue Krankheiten.",al={"wozu dient berglöwenblut","wer braucht löwenblut","elixier der schmerzen blut"}},{q="Wo lässt sich Berglöwenblut sammeln?",a="Ihr könnt Berglöwenblut von Löwen sammeln, die im Vorgebirge des Hügellands und auf den verschneiten Felsen des nahen Alteracgebirges jagen.",al={"wo findet man berglöwenblut","berglöwenblut fundort","welche löwen lassen blut fallen"}},{q="Warum will Apotheker Lydon gerade das Blut wilder Katzen?",a="Lydon glaubt, dass die Lebenssäfte widerstandsfähiger, aggressiver Berglöwen ein giftiges Gebräu ergeben können. Es soll den lebenden Bewohnern von Hillsbrad große Schmerzen bereiten.",al={"warum löwenblut","warum will lydon löwenblut"}},{q="Ist Berglöwenblut für Alchemierezepte nützlich?",a="Nein. Berglöwenblut ist ein experimentelles Reagenz für Apotheker Lydons Arbeit, keine Zutat für gewöhnliche Alchemierezepte.",al={"können alchemisten berglöwenblut verwenden","ist löwenblut für alchemie"}}},fx={dcf44a54={q="Was ist Berglöwenblut?",a="Es ist frisches Blut, das von den räuberischen Berglöwen geerntet wird, die durch die schroffen Hänge des Vorgebirges des Hügellands und des Alteracgebirges streifen. Obwohl es für gewöhnliche Alchemisten oder Handwerker nutzlos ist, besitzt es biologische Eigenschaften, die von der Gesellschaft der Königlichen Apotheker für ihre tödlichen alchemistischen Experimente geschätzt werden.",al={"was ist berglöwenblut","berglöwenblut hintergrund","was ist dieses blut"}},["7c379830"]={q="Woher stammt Berglöwenblut und wer hat es gewonnen?",a="Es wird nicht hergestellt oder fabriziert, sondern direkt von den wilden Katzen gewonnen, die im nördlichen Lordaeron heimisch sind. Die Berglöwen, die durch das Hochland zwischen Hillsbrad und Alterac streifen, werden von Agenten gejagt und ausgeblutet, die im Auftrag der bei Tarrens Mühle stationierten Apotheker der Verlassenen arbeiten.",al={"woher stammt berglöwenblut","quelle von berglöwenblut","wer erzeugte berglöwenblut"}}},fp="19,159,20.341.0,22.323.0,37.145.0,43.138.0,59.159.0,59.128.0"}
P.entries["item:muddy-journal-pages"] = {n="Schlammverschmierte Tagebuchseiten",s="Schlammverschmierte Tagebuchseiten wurden vor Jahren an einem Mordschauplatz im Dämmerwald geborgen. Verwittert und mit Erde befleckt liegen sie noch immer bei Schankwart Smitts, der sie ohne Nachweis ihrer Urheberschaft als Beweismittel in einer ungelösten örtlichen Ermittlung aufbewahrte.",h="Schlammverschmierte Tagebuchseiten wurden vor Jahren an einem Mordschauplatz im Dämmerwald geborgen.",kw={"dunkelhain","schwarzhaupt","haggard","schlammverschmierte tagebuchseiten","smitts"},ang={["class:Rogue"]="Als Schurke zeigt Euch das Zusammenfügen vergessener Handschriftenproben und verwitterter Tagebuchfetzen die methodische kriminalistische Arbeit, die nötig ist, bevor ein verborgener Mörder niedergestreckt werden kann.",["faction:Alliance"]="Für die Allianz bringt die Aufklärung des Massakers an Adligen aus Sturmwind einen überfälligen Abschluss in einem ungelösten Fall in den umkämpften Siedlungen des Dämmerwalds."},sec={{t="Die Beweise des Massakers",b="Schankwart Smitts fand die Seiten im Morast, nachdem adlige Besucher im Dämmerwald niedergemetzelt worden waren. Er war mit dem Ermittler Haggard zum Tatort gegangen. Die Stadt hatte weder Handschriftenproben noch bestätigte Aufzeichnungen, um den Text einem Verdächtigen zuzuordnen, also bewahrte Smitts die Seiten stillschweigend in Dunkelhains Taverne auf. Er wartete darauf, dass ein Ermittler verstreute Aufzeichnungen aus den südlichen Königreichen zusammentrug und die Handschrift dem Einsiedler zuordnete, der tief im Wald lebte."}},faq={{q="Wo wurden die schlammverschmierten Tagebuchseiten gefunden?",a="Schankwart Smitts und Haggard fanden die Seiten am Tatort, an dem vor einigen Jahren adlige Besucher in den Wäldern des Dämmerwalds niedergemetzelt worden waren.",al={"wo fand smitts die seiten","herkunft der schlammverschmierten seiten","fundort des schlammverschmierten tagebuchs"}},{q="Warum konnte Smitts die Seiten nicht nutzen, als er sie fand?",a="Die örtlichen Ermittler hatten keine Schriftproben zum Vergleich mit den Seiten, daher konnten sie die Handschrift keinem Verdächtigen zuordnen.",al={"warum die seiten geheim halten","warum gab smitts sie nicht ab","smitts beweisproblem"}},{q="Wer muss diese Seiten sehen?",a="Die Seiten müssen zu Kommandantin Althea Schwarzhaupt, Anführerin der Nachtwache in Dunkelhain, gebracht werden, um über die Ermittlungen zum Massaker an den Adligen zu berichten.",al={"wem die schlammverschmierten seiten geben","schlammverschmierte tagebuchseiten abgeben","schwarzhaupt schlammverschmierte seiten"}},{q="Mit welchem Verbrechen stehen diese Seiten in Verbindung?",a="Die Seiten stehen mit dem Massaker an adligen Besuchern in den Wäldern des Dämmerwalds vor einigen Jahren in Verbindung, einem Verbrechen, das Dunkelhain damals nicht aufklären konnte.",al={"welches massaker","was hat stalvan getan","adlige besucher niedergemetzelt"}}},fx={["7e79311d"]={q="Was sind die Schlammverschmierten Tagebuchseiten?",a="Dies sind beschmutzte, zerrissene Tagebuchblätter, die vor Jahren vom Ort eines brutalen Massakers an besuchenden Adligen im Dämmerwald geborgen wurden. Sie wurden von Stalvan Dunstmantel geschrieben und dokumentieren seinen Verfall und liefern den lang gesuchten schriftlichen Beweis für seine Anwesenheit und seinen Wahnsinn am Ort des Gemetzels.",al={"was sind die schlammverschmierten tagebuchseiten","schlammverschmierte tagebuchseiten","was ist dieser gegenstand"}},bcc5553e={q="Woher stammen die Schlammverschmierten Tagebuchseiten und wer hat sie geschrieben?",a="Sie wurden von Stalvan Dunstmantel geschrieben und im Schlamm zurückgelassen, als die Adligen ermordet wurden. Schankwart Smitts und Haggard entdeckten sie, während sie das Blutbad untersuchten, aber Smitts behielt sie jahrelang, weil ihm Handschriftenproben fehlten, um zu bestätigen, wer sie verfasst hatte.",al={"wer schrieb die schlammverschmierten tagebuchseiten","woher stammen die schlammverschmierten seiten","autor der schlammverschmierten tagebuchseiten"}},f7c3dc88={q="Warum benötigt Kommandantin Althea Schwarzhaupt die Schlammverschmierten Tagebuchseiten?",a="Kommandantin Althea Schwarzhaupt beaufsichtigt die Verteidigung von Dunkelhain und benötigt endgültige Beweise, bevor sie gegen die Bedrohung in den Wäldern vorgeht. Gepaart mit den Handschriftenbeweisen, die Ihr im ganzen Königreich gesammelt habt, stellen diese Seiten Stalvans Schuld zweifelsfrei fest und drängen The Nachtwache dazu, sich endlich um ihn zu kümmern.",al={"warum seiten zu ebonlocke bringen","wer will die schlammverschmierten tagebuchseiten","warum sind die schlammverschmierten seiten wichtig"}}},fp="19,238,28.458.1,41.141.0,59.129.0,29.152.1,37.144.0"}
P.entries["item:mudsnout-blossom"] = {n="Mudsnout Blossom",s="In der Nethander-Siedlung vergiften Sporen und Fleisch von Mudsnout Blossom die Lebenden. Mudsnout-Gnolle bewachen die Pilze, und Apotheker Lydon sucht sie für seine Elixierforschung.",h="In der Nethander-Siedlung vergiften Sporen und Fleisch von Mudsnout Blossom die Lebenden.",kw={"apotheker lydon","elixir of agony","vorgebirge des hügellands","mudsnout blossom","mudsnout-gnolle","nethander-siedlung","tarrens mühle"},ang={["profession:Herbalism"]="Als Kräuterkundiger erwartet Ihr vielleicht eine Blume, doch Mudsnout Blossom ist ein instabiler, übelriechender Pilz, den Giftforscher und finstere Alchemisten suchen.",["race:Undead"]="Als Verlassener wisst Ihr, dass die Royal Apothecary Society Morastschnauzenkappen wegen ihrer giftigen Eigenschaften erntet und um biochemische Waffen zu verfeinern."},sec={{t="Ein giftiger Pilz",b="Südlich von Tarrens Mühle wachsen Morastschnauzenkappen in der Nethander-Siedlung. Ihr Name lässt Blumen vermuten, doch es sind große, übelriechende Pilze. Sie gedeihen in verschmutzter Erde zwischen den Lagern der Mudsnout-Gnolle, und die Gnolle verteidigen diesen Boden erbittert. Ihre Sporen und ihr Fleisch vergiften Lebewesen und verursachen Qualen und raschen körperlichen Verfall."},{t="Rohstoff für die Royal Apothecary Society",b="In Tarrens Mühle verwendet Apotheker Lydon Morastschnauzenkappen für seine chemischen Experimente. Fürstin Sylvanas Windläufer beauftragte die Royal Apothecary Society, eine Seuche zu erschaffen, die sowohl die Geißel als auch die lebende Menschheit auslöschen soll. Die Pilze zersetzen mit ihrem ätzenden Gift das Fleisch und bilden so eine Grundlage für Lydons Elixir of Agony."}},faq={{q="Was ist Mudsnout Blossom?",a="Trotz ihres Namens sind Morastschnauzenkappen große, stechend riechende, giftige Pilze, die im feuchten Boden des Vorgebirges des Hügellands wachsen.",al={"mudsnout blossom hintergrundgeschichte","ist mudsnout blossom eine blume","was für eine pflanze ist mudsnout blossom"}},{q="Wo wachsen Morastschnauzenkappen?",a="Morastschnauzenkappen wachsen überall in der Nethander-Siedlung, einem verlassenen Gehöft südlich von Tarrens Mühle und östlich des Flusses, der an Süderstade vorbeifließt. Das Gebiet ist von zahlreichen Mudsnout-Gnollen befallen.",al={"mudsnout blossom fundort","wo morastschnauzenkappen finden","nethander-siedlung pilze"}},{q="Warum sammelt die Royal Apothecary Society sie?",a="Apotheker Lydon in Tarrens Mühle braucht Morastschnauzenkappen, um das Elixir of Agony zu brauen. Die Verlassenen erforschen Giftstoffe, um eine Seuche zu entwickeln, die sowohl die Lebenden als auch die Geißel auslöschen kann.",al={"warum will lydon morastschnauzenkappen","elixir of agony zutaten","apotheker lydon pilz"}},{q="Wofür verwendet die Royal Apothecary Society die Kappen?",a="Apotheker Lydon sammelt die übelriechenden Pilze für sein nächstes Elixier. Es ist Teil der Forschung der Verlassenen an Krankheiten und Giften.",al={"mudsnout blossom experimente","mudsnout blossom verwendung für elixiere"}}},fx={f0998bd9={q="Woher stammen Morastschnauzenkappen?",a="Morastschnauzenkappen sind große, übelriechende Pilze, die auf den Feldern der Nethander-Siedlung im südlichen Vorgebirge des Hügellands sprießen. Sie gedeihen in der Nähe der lokalen Mudsnout-Gnolle, die dort leben und das Feld erbittert bewachen, wenngleich ungewiss ist, ob die Gnolle die beißenden Pilze absichtlich anbauen oder nur unter ihnen nisten.",al={"ursprung der morastschnauzenkappen","woher stammen die morastschnauzenkappen","wer erschuf die morastschnauzenkappen"}}},fp="16,166,14.327.0,37.322.1,27.124.0,32.184.0,52.183.0,60.137.0"}
P.entries["item:mudsnout-composite"] = {n="Morastschnauzengemisch",s="In Tarrens Mühle ist Morastschnauzengemisch für die Erforschung einer neuen Seuche bestimmt. Apotheker Lydon stellt es aus Morastschnauzenkappen her, die im Vorgebirge des Hügellands gesammelt werden, und schickt es dann nach Unterstadt.",h="In Tarrens Mühle ist Morastschnauzengemisch für die Erforschung einer neuen Seuche bestimmt.",kw={"das apothekarium","apotheker lydon","elixir of agony","apothekermeister faranell","mudsnout blossom","morastschnauzengemisch","königliche apothekervereinigung"},ang={["profession:Herbalism"]="Als Kräuterkundiger könnt Ihr sehen, wie ein Apotheker Morastschnauzenkappen zerreibt und daraus eine Waffe macht.",["race:Undead"]="Als Untoter wisst Ihr, dass jede Lieferung Morastschnauzengemisch dem Auftrag der Dunklen Fürstin dient: die Zukunft der Verlassenen mit einer Seuche gegen die Lebenden und die Geißel zu sichern."},sec={{t="Eine Grundlage für Fäulnis",b="Apotheker Lydon stellt Morastschnauzengemisch aus Morastschnauzenkappen her, die im Vorgebirge des Hügellands gesammelt werden. Die Paste ist schon für sich genommen giftig. Apothekermeister Faranell bindet sie mit einem Fäulniskolloid und bringt so ihre tödlicheren Eigenschaften hervor. Gemeinsam bilden die Zutaten einen wichtigen chemischen Bestandteil im Elixir of Agony der Dunklen Fürstin."},{t="Korrespondenz der Apotheker",b="Die Königliche Apothekervereinigung erhält Morastschnauzengemisch im Apothekarium von Unterstadt, nachdem es aus Tarrens Mühle dorthin gebracht wurde. Feldforscher sammeln Reagenzien in verschiedenen Regionen und schicken Proben zur Verfeinerung an die Meister der Hauptstadt. Fürstin Sylvanas fordert rasche Ergebnisse gegen lebende Menschen und die Geißel. Faranell lobt das Gemisch als geniale Vorarbeit auf dem Weg zu ihrem Ziel."}},faq={{q="Wofür wird das Morastschnauzengemisch verwendet?",a="Morastschnauzengemisch ist eine Paste aus Morastschnauzenkappen. In Unterstadt behandelt Apothekermeister Faranell sie mit einem Fäulniskolloid, um damit das Elixir of Agony zu entwickeln.",al={"morastschnauzengemisch zweck","was bewirkt morastschnauzengemisch"}},{q="Wer hat das Gemisch hergestellt?",a="Apotheker Lydon hat das Gemisch in Tarrens Mühle im Vorgebirge des Hügellands hergestellt. Lydon zerreibt frische Blüten zu einer Paste, bevor er sie nach Norden schickt.",al={"wer hat morastschnauzengemisch hergestellt","morastschnauzengemisch schöpfer"}},{q="Warum braucht Apothekermeister Faranell es?",a="Apothekermeister Faranell braucht das Gemisch für die Arbeit der Königlichen Apothekervereinigung an einer neuen Seuche. Lydons Paste liefert die pflanzliche Grundlage für ihre Erforschung tödlicher Gifte.",al={"warum zu faranell bringen","faranell mudsnout"}}},fx={["432a2438"]={q="Was ist Morastschnauzengemisch?",a="Morastschnauzengemisch ist eine raffinierte Mischung, die von Apotheker Lydon in Tarrens Mühle zusammengestellt wurde. Diese potente Substanz, die durch das Zermahlen seltener Morastschnauzenkappen aus dem Vorgebirge des Hügellands hergestellt wird, dient als wesentliche alchemistische Basis für die Forschung der Gesellschaft der Königlichen Apotheker, um eine verheerende neue Seuche für die Verlassenen zu entwickeln.",al={"morastschnauzengemisch","was ist morastschnauzengemisch","morastschnauzenmixtur"}}},fp="18,193,16.326.0,25.385.1,40.176.0,26.148.0,44.174.0"}
P.entries["item:mudsnout-mixture"] = {n="Morastschnauzenmixtur",s="In Unterstadt bereitet Apothekermeister Faranell eine Grundlage für ein tödliches Gift der Verlassenen zu. Pilze, die aus Tarrens Mühle nach Norden geschickt werden, bilden den Anfang der Mischung.",h="In Unterstadt bereitet Apothekermeister Faranell eine Grundlage für ein tödliches Gift der Verlassenen zu.",kw={"apotheker","kolloid des verfalls","elixir of agony","faranell","hillsbrad","lydon","morastschnauzenmixtur","unterstadt"},ang={["faction:Horde"]="Als Abenteurer der Horde in Tarrens Mühle tragt Ihr als Kurier und Feldagent giftige Gebräue durch Lordaeron. Ihr helft dabei, den Stützpunkt der Verlassenen in Hillsbrad zu sichern.",["race:Undead"]="Als Untoter könnt Ihr den rücksichtslosen Erfindungsreichtum der Königlichen Apothekervereinigung am Werk sehen. Sie verarbeitet Zutaten aus der Wildnis zu chemischen Waffen, die die Lebenden töten sollen."},sec={{t="Ein Kolloid des Verfalls",b="Apotheker Lydon in Tarrens Mühle will eine hochvirulente neue biologische Waffe erschaffen. Er schickt ein Gemisch aus Morastschnauzenkappen nach Norden nach Unterstadt. Die giftigen Pilze wachsen in der von Gnollen beherrschten Nethander-Siedlung.\n\nApothekermeister Faranell erkennt das Potenzial des Gemischs und fügt sein Kolloid des Verfalls hinzu. Die daraus entstehende Morastschnauzenmixtur ist instabil. Sie stabilisiert die Pilzverbindung und bereitet deren hochvirulente Eigenschaften auf eine weitere katalytische Verfeinerung im Vorgebirge vor."},{t="Die Qual katalysieren",b="Bevor die Verseuchungsstoffe wirken können, braucht die Morastschnauzenmixtur entscheidende Katalysatoren. Faranell schickt Kuriere mit der Phiole, einem Starken Trollblutelixier, giftigen Schuppen der Dolchflossennaga und Augen der Murlocs der Zerrissenen Flossen nach Tarrens Mühle zurück.\n\nApotheker Lydon katalysiert die Mischung mit diesen Zutaten, um das tödliche Elixir of Agony herzustellen. Dieses charakteristische Gift soll unter den lebenden Feinden der Verlassenen Verderben verbreiten."}},faq={{q="Wofür wird die Morastschnauzenmixtur verwendet?",a="Die Morastschnauzenmixtur bildet die chemische Grundlage für das Elixir of Agony. Apotheker Lydon perfektioniert das experimentelle Gift in Tarrens Mühle, um die Feinde der Verlassenen zu töten.",al={"morastschnauzenmixtur zweck","was bewirkt die morastschnauzenmixtur","morastschnauzenmixtur verwendung"}},{q="Wer stellt die Morastschnauzenmixtur her?",a="Apothekermeister Faranell stellt die Morastschnauzenmixtur in Unterstadt her. Er fügt einem rohen Morastschnauzengemisch sein Kolloid des Verfalls hinzu.",al={"wer stellt die morastschnauzenmixtur her","morastschnauzenmixtur hersteller"}},{q="Warum werden dafür Bestandteile von Gnollen benötigt?",a="Die Morastschnauzenmixtur benötigt keine Körperteile von Gnollen. Das Gemisch besteht aus Morastschnauzenkappen, giftigen Pilzen, die in der Nethander-Siedlung zwischen den Mudsnout-Gnollen wachsen. Apotheker Lydon verarbeitet sie zu einem Gemisch, bevor Faranell sein Kolloid des Verfalls hinzufügt.",al={"warum mudsnout","gnollengift hintergrundgeschichte"}},{q="Wie wird die Mixtur aktiviert?",a="Apotheker Lydon aktiviert die ruhenden Verseuchungsstoffe mit einem Starken Trollblutelixier, Schuppen der Dolchflossennaga und Augen der Murlocs der Zerrissenen Flossen, gesammelt entlang der Küste von Hillsbrad.",al={"morastschnauzenmixtur aktivieren","elixir of agony reagenzien"}}},fx={f656f7cb={q="Was ist Morastschnauzenmixtur?",a="Es ist ein experimentelles alchemistisches Gebräu, das von der Gesellschaft der Königlichen Apotheker formuliert wurde. Aufgebaut um ein Gemisch aus Morastschnauzenkappen, giftigen Pilzen aus der Nethander-Siedlung, enthält die Mixtur Apothekermeister Faranells eigenes Kolloid des Verfalls, um als flüchtige Basis für die Seuchenforschung der Apotheker zu dienen.",al={"was ist morastschnauzenmixtur","morastschnauzenmixtur","morastschnauzengemisch"}},ac01c76e={q="Warum möchte Apotheker Lydon Morastschnauzenmixtur haben?",a="Apotheker Lydon in Tarrens Mühle benötigt sie, um das Elixir of Agony zu synthetisieren, ein experimentelles Gebräu, das darauf abzielt, Krankheit und Tod unter den Feinden der Verlassenen zu verbreiten. Indem er dessen kontaminierende Wirkstoffe mit Trollblut und Küstenreagenzien aktiviert, beabsichtigt er, die Seuchenforschung der Gesellschaft der Königlichen Apotheker voranzutreiben.",al={"warum wird morastschnauzenmixtur benötigt","warum will lydon morastschnauzenmixtur","wofür ist die morastschnauzenmixtur"}}},fp="16,147,18.462.0,20.418.1,38.170.0,33.127.0,37.241.0,29.181.0"}
P.entries["item:murloc-head"] = {n="Kopf eines Murlocs",s="Am Weststrand liefert der Kopf eines Murlocs Süderstade einen düsteren Beweis für eine Bedrohung, die es eindämmen will. Leutnant Farren Orinelle sammelt die abgetrennten Köpfe für Marshal Redpath, der Beweise dafür verlangt, dass die Murlocs dezimiert werden.",h="Am Weststrand liefert der Kopf eines Murlocs Süderstade einen düsteren Beweis für eine Bedrohung, die es...",kw={"farren orinelle","farren's proof","vorgebirge des hügellands","marshal redpath","murloc","kopf eines murlocs","süderstade","weststrand"},ang={["faction:Alliance"]="Als Mitglied der Allianz helft Ihr durch das Säubern des Weststrands, Süderstades Fischwirtschaft zu schützen und seine Küste in Lordaeron zu sichern."},sec={{t="Ein grausigerer Beweis",b="Aggressive Murlocs bedrohen Süderstades Fischer und Reisende am Weststrand. Kämpfer der Allianz säubern häufig die Strände, doch Marshal Marcus Redpath verlangt Beweise, bevor er Berichte über eine Verringerung der Bedrohung bestätigt.\n\nAlso heuert Leutnant Farren Orinelle Kämpfer an, die ihm Murlocköpfe bringen sollen. Farren findet die Arbeit abstoßend, und der Anblick hat ihm den Appetit auf Süderstades Meeresfrüchte verdorben."}},faq={{q="Warum will Farren Orinelle Murlocköpfe?",a="Marshal Marcus Redpath verlangt handfeste Beweise dafür, dass die Strände von Murlocs gesäubert wurden. Leutnant Farren Orinelle sammelt ihre abgetrennten Köpfe, um ihn zufriedenzustellen.",al={"farren beweis","warum murlocköpfe","wer will murlocköpfe in süderstade"}},{q="Wo sind diese Murlocs zu finden?",a="Die Murlocs sind am Weststrand zu finden, der Küste westlich von Süderstade im Vorgebirge des Hügellands.",al={"kopf eines murlocs fundort","wo murlocköpfe im hügelland finden","weststrand murlocs"}},{q="Warum ekelt sich Farren so sehr vor ihnen?",a="Farren findet die Murlocs unnatürlich und ekelerregend. Ihre abgetrennten Köpfe widern ihn so sehr an, dass er keinen Fisch mehr essen will, ein Grundnahrungsmittel in Süderstade.",al={"farrens reaktion","farren isst fisch"}},{q="Löst das Sammeln der Köpfe Süderstades Murlocproblem?",a="Die Köpfe liefern Marshal Redpath den verlangten Beweis. Er nimmt sie an und schickt Farren los, um sich um Bedrohungen am Oststrand zu kümmern.",al={"hören murlocs auf anzugreifen","farren questreihe"}}},fx={ab7abae9={q="Was ist ein Kopf eines Murlocs?",a="Es ist der frisch abgetrennte Schädel eines Murlocs, der entlang der Küste des Vorgebirges des Hügellands erschlagen wurde. Kalt, schleimig und mit üblen Flüssigkeiten bedeckt, dient er als untrüglicher physischer Beweis für eine Bestie, die zur Verteidigung von Süderstade niedergestreckt wurde.",al={"was ist kopf eines murlocs","infos zu kopf eines murlocs","gegenstand kopf eines murlocs"}},["598cfa24"]={q="Woher stammen Köpfe eines Murlocs?",a="Sie werden direkt von den Körpern der Murlocs gehackt, die den Weststrand westlich von Süderstade durchstreifen. Anstatt handwerklich gefertigter Waren sind es grausige Trophäen, die von den Küstenplünderern genommen wurden, welche die Garnison der Allianz in Bedrängnis bringen.",al={"wo findet man köpfe eines murlocs","wer hat kopf eines murlocs hergestellt","quelle für kopf eines murlocs"}}},fp="11,228,24.399.0,43.164.0,30.100.0,35.155.0,60.131.0"}
P.entries["item:musquash-root"] = {n="Bisamwurzel",s="Unterhalb des Steinwerkdamms wächst die Bisamwurzel im Sumpfland. Nur wenige sammeln sie, doch ein verborgener Zirkel unter Sturmwind braucht sie für ein Gebräu.",h="Unterhalb des Steinwerkdamms wächst die Bisamwurzel im Sumpfland.",kw={"a noble brew","lord wishock","bisamwurzel","der steinwerkdamm","tilloaträne","sumpfland","zardeth"},ang={["class:Warlock"]="Als Hexenmeister unter dem Slaughtered Lamb braucht Ihr diese Wurzel, um neugierige Adlige zum Schweigen zu bringen und Euren gefährdeten Zufluchtsort in der Stadt zu schützen.",["profession:Herbalism"]="Als Kräuterkundler könnt Ihr erkennen, wie der feuchte Boden unterhalb der Wasserfälle des Steinwerkdamms ungewöhnlicher und gefährlicher Flora einen Nährboden bietet."},sec={{t="Eine seltene Zutat",b="Die Bisamwurzel wächst im feuchten Boden unterhalb der Wasserfälle des Steinwerkdamms. Nebel und Abgeschiedenheit erschweren das Sammeln. Nur wenige Kräuterkundler suchen nach ihr, doch Anhänger der dunkleren Künste schätzen ihre chemischen und alchemistischen Eigenschaften."},{t="Der Plan des Hexenmeisters",b="Zardeth der Schwarzen Klaue sucht unter Sturmwind, im Slaughtered Lamb, nach Bisamwurzel und Tilloaträne. Die seltenen Pflanzen sollen ein subtiles Gebräu ergeben, um Lord Wishock auszuschalten. Er ist ein Mitglied des Hauses der Adligen und hat begonnen, den verborgenen Hexenmeisterzirkel der Stadt zu untersuchen."}},faq={{q="Wo findet man Bisamwurzel?",a="Die Bisamwurzel wächst im Sumpfland am Fuß der Wasserfälle unterhalb des Steinwerkdamms.",al={"wo ist bisamwurzel","bisamwurzel fundort","wie findet man bisamwurzel"}},{q="Wofür wird Bisamwurzel verwendet?",a="Zardeth der Schwarzen Klaue will Bisamwurzel und Tilloaträne für ein Gebräu, das Lord Wishock beschäftigen soll. Er hofft, Wishocks Drängen auf eine Untersuchung des Hexenmeisterzirkels von Sturmwind Einhalt zu gebieten.",al={"was bewirkt bisamwurzel","bisamwurzel verwendungszweck","wofür braucht man bisamwurzel"}},{q="Wer will diese Wurzel ernten lassen?",a="Zardeth der Schwarzen Klaue schickt Agenten aus, um Bisamwurzel zu beschaffen. Er ist ein Hexenmeister in den Katakomben unter dem Slaughtered Lamb im Magierviertel von Sturmwind.",al={"wer braucht bisamwurzel","bisamwurzel questgeber","wer verlangt bisamwurzel"}},{q="Wer ist Lord Wishock?",a="Lord Wishock ist ein Mitglied des Hauses der Adligen von Sturmwind. Nachdem er vom Hexenmeisterzirkel der Stadt erfahren hatte, begann er, den Rat zu einer förmlichen Untersuchung zu drängen.",al={"wer ist wishock","lord wishock"}}},fx={["32cf7ee1"]={q="Was ist die Bisamwurzel?",a="Die Bisamwurzel ist eine seltene botanische Probe, die speziell im feuchten, nebligen Sprühregen am Fuß des Wasserfalls unterhalb des Steinwerkdamms im Sumpfland wächst. Unter dunklen Apothekern und Hexenmeistern für ihre starken natürlichen Eigenschaften bekannt, dient sie als entscheidendes Reagenz beim Brauen täuschender Tränke und Gifte, wenn sie mit anderer seltener Flora kombiniert wird.",al={"was ist die bisamwurzel","bisamwurzel hintergrundgeschichte","bisamwurzel info"}},d9341dd1={q="Woher stammt die Bisamwurzel und wer hat sie erschaffen?",a="Die Bisamwurzel ist eine natürlich vorkommende Pflanze und keine künstliche Schöpfung. Sie gedeiht ausschließlich im Sumpfland und wurzelt im feuchten Stein und dem gesättigten Boden am Fuße der herabstürzenden Wasserfälle direkt unterhalb des großen Steinwerkdamms.",al={"bisamwurzel ursprung","wo wächst die bisamwurzel","wer hat die bisamwurzel erschaffen"}}},fp="13,142,17.226.0,20.283.1,29.90.0,31.201.0,30.158.0,20.160.0"}
P.entries["item:mysterious-fossil"] = {n="Geheimnisvolles Fossil",s="An der Küste der Dunkelküste entdeckt Ausgrabungsleiter Wirrbart das Geheimnisvolle Fossil. Die Forscherliga schickt es zur Untersuchung über das Meer.",h="An der Küste der Dunkelküste entdeckt Ausgrabungsleiter Wirrbart das Geheimnisvolle Fossil.",kw={"dunkelküste","forscherliga","magenbitter","grauflaum","hafen von menethil","geheimnisvolles fossil","wirrbart"},ang={["faction:Alliance"]="Als Mitglied der Allianz könnt Ihr den Weg des Relikts von den Kundschaftern in der Dunkelküste zu den Gelehrten in Darnassus und im Hafen von Menethil nachverfolgen.",["race:Dwarf"]="Als Zwerg könnt Ihr das Fossil als ein weiteres fehlendes Puzzlestück bei der Suche der Forscherliga nach dem uralten Erbe der Titanen und vergessenen Geheimnissen betrachten."},sec={{t="Eine seltsame Entdeckung",b="Ausgrabungsleiter Wirrbart entdeckt ein ungewöhnliches Fossil an der wilden Küste der Dunkelküste. Er sorgt dafür, dass zwergische Gelehrte es erhalten, statt es in der Wildnis zurückzulassen. In Darnassus erkennt Chefarchäologe Grauflaum darin einen außergewöhnlichen Fund unter den Steinen Kalimdors."},{t="Verbindungen über den Ozean",b="Chefarchäologe Grauflaum erkennt eine Ähnlichkeit mit einem seltenen Fossil, das einst bei einer Zusammenkunft der Forscherliga in Eisenschmiede gezeigt wurde. Archäologe Magenbitter untersuchte jenes Fossil und vermutete, dass es Macht barg, die darauf wartete, zu erwachen. Um die Herkunft des neuen Fossils zu bestätigen und zu erfahren, was es bergen könnte, schickt Grauflaum es über das Meer zu Magenbitter. Magenbitter wartet in der Tiefenwassertaverne im Hafen von Menethil."}},faq={{q="Wo wurde das Geheimnisvolle Fossil gefunden?",a="Ausgrabungsleiter Wirrbart fand das Geheimnisvolle Fossil bei seiner Arbeit an der uralten nördlichen Küste der Dunkelküste.",al={"fundort des fossils","wo wurde es gefunden","herkunft des fossils"}},{q="Warum will die Forscherliga dieses Fossil haben?",a="Chefarchäologe Grauflaum erkennt eine Verbindung zwischen dem Fossil und den Forschungen von Archäologe Magenbitter. Magenbitter vermutet, dass solche Fossilien Macht bergen könnten, die sich erwecken lässt.",al={"warum wollen die zwerge es","interesse der forscherliga","was bewirkt das fossil"}},{q="Wer ist Archäologe Magenbitter?",a="Archäologe Magenbitter forscht für die Forscherliga und hat ähnliche versteinerte Relikte untersucht. Er hält sich in der Tiefenwassertaverne im Hafen von Menethil auf und wartet auf Geleit zur Whelgar Excavation Site im Sumpfland.",al={"wer ist magenbitter","aufenthaltsort von magenbitter","wo ist magenbitter"}},{q="Wer ist Chefarchäologe Grauflaum?",a="Chefarchäologe Grauflaum ist der ranghöchste Vertreter der Forscherliga in Darnassus. Grauflaum beaufsichtigt die zwergische Forschung und die archäologischen Arbeiten im gesamten nördlichen Kalimdor.",al={"grauflaum","wer ist grauflaum","zwergischer archäologe in darnassus"}}},fx={dc519f37={q="Was ist das Geheimnisvolle Fossil?",a="Das Geheimnisvolle Fossil ist ein altes Relikt, das in der Wildnis der Dunkelküste vom zwergischen Ausgrabungsleiter Wirrbart ausgegraben wurde. Anders als gewöhnliche versteinerte Überreste weist dieses Exemplar eine auffällige Ähnlichkeit mit einem außergewöhnlichen Artefakt auf, das zuvor der Forscherliga in Eisenschmiede präsentiert wurde. Seine eigenartige Natur legt nahe, dass es schlummernde Geheimnisse oder Macht birgt, die von einem erfahrenen Archäologen freigeschaltet werden wollen.",al={"lore zu geheimnisvolles fossil","was ist dieses fossil","infos zu geheimnisvolles fossil"}}},fp="17,134,19.267.0,21.388.1,38.104.0,48.171.0,31.232.0,39.182.0"}
P.entries["item:nak-s-skull"] = {n="Naks Schädel",s="Naks Schädel hat Gewicht im südlichen Brachland, wo Überfälle der Borstennacken der Horde zusetzen. In Camp Taurajo sinnt Quetschzahn auf Rache an seinen Stammesgenossen, die ihn zum Sterben zurückließen.",h="Naks Schädel hat Gewicht im südlichen Brachland, wo Überfälle der Borstennacken der Horde zusetzen.",kw={"brachland","betrayal from within","camp taurajo","kuz","lok orcbane","quetschzahn","nak","naks schädel","stacheleber","borstennacken"},ang={["faction:Horde"]="Als Mitglied der Horde könnt Ihr den Druck auf die Versorgungswege zwischen Camp Taurajo und dem Wegekreuz mindern, indem Ihr die Köpfe von Borstennacken-Kriegsfürsten wie Nak holt."},sec={{t="Ein Zeichen der Rache",b="Nak, Kuz und Lok Orcbane führen vom Kral der Klingenhauer aus Raubzüge durch das Brachland an. Ihre Kriegstrupps greifen Siedlungen und Straßen der Horde an, während die Verteidiger des Wegekreuzes nichts von Plänen jenseits gewöhnlicher Stammesscharmützel wissen.\n\nIn Camp Taurajo wurde der gefangene Borstennacken-Stacheleber Quetschzahn von seinen eigenen Leuten in einem Käfig zum Sterben zurückgelassen. Nun sinnt er auf Rache an diesen einstigen Brüdern. Er verlangt, dass Abenteurer der Horde ihm die abgetrennten Schädel von Nak, Kuz und Lok Orcbane als Beweis für ihren Tod bringen. Mit diesem Beweis will er die Raubtrupps im Süden zerschlagen."}},faq={{q="Wer war Nak?",a="Nak ist ein Kommandant der Borstennacken-Stacheleber, der gemeinsam mit Kuz und Lok Orcbane Raubzüge anführt. Die drei kamen aus dem Kral der Klingenhauer und greifen Reisende und Siedlungen der Horde im gesamten südlichen Brachland an.",al={"wer ist nak","naks geschichte","nak brachland"}},{q="Wer will Naks Schädel?",a="Quetschzahn, ein gefangener Borstennacken-Stacheleber in Camp Taurajo, will Naks Schädel. Seine eigenen Stammesgenossen ließen ihn im Stich, und er sinnt auf Rache an den Anführern, die ihn verraten haben.",al={"wer will den schädel","wem naks schädel geben","quetschzahn schädel"}},{q="Warum will Quetschzahn die Schädel seiner eigenen Leute?",a="Nak, Kuz und Lok Orcbane ließen Quetschzahn in Gefangenschaft zum Sterben zurück. Er hilft der Horde, sie zu finden, und verlangt ihre abgetrennten Köpfe als Beweis für ihren Tod.",al={"warum den eigenen stamm verraten","quetschzahns beweggrund","warum will quetschzahn schädel"}},{q="Hilft es, das Wegekreuz zu schützen, wenn man Naks Schädel beschafft?",a="Ja. Quetschzahn sagt, dass Nak und seine Gefährten die Überfälle der Borstennacken auf das Wegekreuz und die zentralen Handelswege lenken. Ihre Niederlage schwächt die koordinierten Angriffe des Stammes.",al={"wegekreuz sicher","überfälle der stacheleber stoppen"}}},fx={["96a0c2b0"]={q="Woher stammt Naks Schädel?",a="Der Schädel stammt unmittelbar von den Überresten Naks, eines bedeutenden Stachelebers der Razormane, der aus dem Kral der Klingenhauer kam. Nak und seine Brüder reisten weit in den Süden des Brachlands, um rücksichtslose Überfälle auf Lager der Horde zu organisieren. Wenn Ihr Nak im südlichen Dornengestrüpp aufspürt und besiegt, dient sein abgetrennter Schädel als unwiderlegbarer Beweis, dass dieser gefährliche Stacheleberräuber beseitigt wurde.",al={"naks schädel herkunft","woher stammt naks schädel","wer hat naks schädel"}}},fp="11,169,20.535.0,12.191.0,22.158.0,55.148.0,56.172.0"}
P.entries["item:nek-rosh-s-head"] = {n="Nek'roshs Kopf",s="Im Sumpfland erreicht Nek'roshs Kopf Hauptmann Starkfaust als Beweis, dass der Häuptling des Dragonmaw-Clans gefallen ist. Die Verteidiger des Hafens von Menethil können nun sehen, dass die Bedrohung gebannt ist.",h="Im Sumpfland erreicht Nek'roshs Kopf Hauptmann Starkfaust als Beweis, dass der Häuptling des Dragonmaw-Clans...",kw={"hauptmann starkfaust","häuptling","dragonmaw","menethil","nek'rosh","nekrosh","sumpfland"},ang={["faction:Alliance"]="Für die Allianz hilft die Übergabe von Nek'roshs Kopf an Hauptmann Starkfaust, den Hafen von Menethil vor einem unmittelbar bevorstehenden Angriff zu schützen, und bringt Ansehen beim Königreich Eisenschmiede.",["race:Dwarf"]="Als Zwerg wisst Ihr, dass die Dragonmaw Khaz Modan seit dem Zweiten Krieg heimsuchen. Den abgetrennten Kopf des Häuptlings zu tragen, bringt den Verteidigern der Marschen die lang ersehnte Gerechtigkeit."},sec={{t="Ein entscheidender Schlag",b="Überall in den Marschen sammelt der Dragonmaw-Clan Streitkräfte und Belagerungswaffen gegen den Hafen von Menethil, einen Hafen der Allianz. Nachdem die Katapulte des Clans verbrannt sind, hängt die Verteidigung des Hafens davon ab, Häuptling Nek'rosh zu töten. Sein abgetrennter Kopf liefert Hauptmann Starkfaust und den Behörden von Eisenschmiede den Beweis, dass die Herrschaft des Kriegsfürsten über das Sumpfland gebrochen ist."}},faq={{q="Wer war Nek'rosh?",a="Nek'rosh führte die Überreste des Dragonmaw-Clans im Sumpfland an. Er leitete Angriffe und Kriegsanstrengungen gegen nahe gelegene Gebiete der Allianz.",al={"wer ist nek'rosh","häuptling nek'rosh","wer war nekrosh"}},{q="Wer will Nek'roshs Kopf?",a="Hauptmann Starkfaust will Nek'roshs Kopf als Beweis dafür, dass der Häuptling gefallen ist. Er befehligt die Verteidigung des Hafens von Menethil und bietet im Namen von Eisenschmiede eine Belohnung an.",al={"wer nimmt den kopf","nekrosh kopf abgeben","wohin nek'roshs kopf bringen"}},{q="Warum sollte Nek'rosh getötet werden?",a="Nek'rosh befehligte die Streitkräfte des Dragonmaw-Clans, die den Hafen von Menethil bedrohten. Die Allianz wollte die Präsenz des Clans in der Region schwächen, indem sie seine Belagerungswaffen zerstörte und seinen Häuptling tötete.",al={"warum nekrosh töten","warum nek'rosh besiegen"}}},fx={e464fcda={q="Was ist Nek'roshs Kopf?",a="Es ist das abgetrennte Haupt des Häuptlings Nek'rosh, des Kriegsherrn, der den Dragonmaw-Clan im Sumpfland befehligt. Er dient als grausiger, unbestreitbarer Beweis dafür, dass der größte lokale Feind der Gebirgssoldaten von Eisenschmiede endlich erschlagen wurde.",al={"was ist nek'roshs kopf","gegenstand nek'roshs kopf","abgetrennter kopf von nek'rosh"}},["160e4c8d"]={q="Woher stammt Nek'roshs Kopf und wer hat ihn hergestellt?",a="Er wird direkt von Häuptling Nek'rosh genommen, nachdem Ihr ihn im Lager der Dragonmaw im Sumpfland besiegt habt. Er wurde nicht handwerklich gefertigt oder hergestellt, sondern vom gefallenen Orc-Häuptling als Trophäe und Bestätigung seines Ablebens abgetrennt.",al={"woher stammt nek'roshs kopf","wie bekommt man nek'roshs kopf","ursprung von nek'roshs kopf"}},ce210494={q="Warum will Hauptmann Starkfaust Nek'roshs Kopf?",a="Hauptmann Starkfaust benötigt einen unbestreitbaren Beweis dafür, dass der Anführer des Dragonmaw-Clans gefallen ist. Mit Nek'roshs Tod und der Zerstörung ihrer Kriegskatapulte weiß Starkfaust, dass es den Dragonmaw schwerfallen wird, sich zu erholen, was sicherstellt, dass der Hafen von Menethil und das Sumpfland endlich vor organisierten Angriffen sicher sind.",al={"warum will starkfaust nek'roshs kopf","warum will man nek'roshs kopf","zweck von nek'roshs kopf"}}},fp="15,176,17.341.0,17.130.0,26.160.0,36.191.0"}
P.entries["item:neru-fragment"] = {n="Nerufragment",s="In Whelgars Ausgrabungsstätte im Sumpfland bewahrt das Nerufragment einen Teil der uralten Titanschrift des Goazsteins. Seine Worte erzählen von Azeroths Urgeschichte.",h="In Whelgars Ausgrabungsstätte im Sumpfland bewahrt das Nerufragment einen Teil der uralten Titanschrift des...",kw={"ausgrabung","goazstein","lockere erde","nerufragment","ausgrabungsleiter whelgar","uncovering the past","sumpfland"},ang={["race:Dwarf"]="Für die Explorer's League hilft die Bergung von Tafelstücken wie dem Nerufragment, Geheimnisse der Titanen aufzudecken und die Ursprünge des Zwergenvolks zu rekonstruieren."},sec={{t="Ein Stück des Goazsteins",b="Ausgrabungsleiter Whelgar führte die Zwergenexpedition an, die den Goazstein fand. Das Relikt zerbrach in vier Stücke: Ados, Modr, Golm und Neru. Dann überrannten Raptoren die Ausgrabungsstätte und brachten die Arbeit zum Erliegen. Das Nerufragment blieb inmitten der aggressiven Bestien unter lockerer Erde zurück.\n\nNach seiner Bergung lässt sich das Fragment mit den anderen zusammenfügen, um die Tafel wiederherzustellen. Die erhaltenen Worte sprechen von einem göttlichen Plan und einer unheilvollen Prophezeiung. Die Zwergengelehrten haben eine Aufzeichnung zu entziffern."},{t="Die wiederhergestellte Tafel lesen",b="Ausgrabungsleiter Whelgar stellt den Goazstein wieder her, sobald alle vier Fragmente gesammelt sind. Er setzt die Übersetzung seiner Titanschrift fort. Die nun lesbaren Worte erzählen von Alten Göttern, die unter dem Land angekettet sind."}},faq={{q="Was ist das Nerufragment?",a="Das Nerufragment ist ein abgebrochenes Steinstück des Goazsteins, eines größeren Relikts. Die Zwergenexpedition legte es im Sumpfland frei, bevor Raptoren die Ausgrabungsstätte überrannten.",al={"nerufragment hintergrundgeschichte","was ist das nerufragment","neru tafelstück"}},{q="Wo wird das Fragment gefunden?",a="Das Nerufragment liegt verstreut in Whelgars Ausgrabungsstätte, östlich vom Hafen von Menethil im Sumpfland. Meist ist es unter lockerer Erde begraben oder zwischen zurückgelassenen Artefakten verborgen.",al={"wo nerufragment finden","nerufragment fundort","wie nerufragment erhalten"}},{q="Was geschieht, wenn alle vier Fragmente gesammelt sind?",a="Nachdem alle vier Fragmente gesammelt sind, setzt Ausgrabungsleiter Whelgar den Goazstein wieder zusammen und fährt mit der Übersetzung seiner Titanschrift fort. Er geht dem Geheimnis nach, das der erhaltene Text andeutet.",al={"goazstein vervollständigen","was steht auf dem goazstein","uncovering the past ende"}}},fx={["1f660d59"]={q="Woher stammt das Nerufragment und wer hat es hergestellt?",a="Das Fragment stammt vom alten Goazstein, der bei Ausgrabungsleiter Whelgars Ausgrabung im Sumpfland entdeckt wurde. Seine Inschrift verwendet Titanenschrift, aber der wiedergefundene Questtext identifiziert seinen Schöpfer nicht.",al={"ursprung des nerufragments","wer hat nerufragment hergestellt","woher stammt das nerufragment"}},b6f45f31={q="Warum will Ausgrabungsleiter Whelgar das Nerufragment?",a="Ausgrabungsleiter Whelgar hat den Goazstein ausgegraben, kurz bevor die Ausgrabungsstätte von Raptoren überrannt wurde, stellte jedoch fest, dass die Inschrift an vier verschiedenen Stellen abgebrochen war. Er benötigt dringend das Nerufragment zusammen mit den anderen drei Teilen, um die Tafel zusammenzusetzen und die Verweise auf einen göttlichen Plan und eine dem Untergang geweihte Prophezeiung weiter zu entschlüsseln.",al={"warum nerufragment finden","warum braucht whelgar das nerufragment","zweck des nerufragments"}}},fp="13,161,23.442.0,27.190.1,26.162.0,28.175.0,50.193.1"}
P.entries["item:nessa-s-collection"] = {n="Nessas Sammlung",s="In Rut'theran ist Nessas Sammlung für Laird in Auberdine bestimmt und birgt Beweise für die großen Fische nahe Teldrassils Wurzeln.",h="In Rut'theran ist Nessas Sammlung für Laird in Auberdine bestimmt und birgt Beweise für die großen Fische...",kw={"auberdine","fischgräten","laird","nessa shadowsong","nessas sammlung","rut'theran","teldrassil","vesprystus"},ang={["race:NightElf"]="Als Nachtelf könnt Ihr sehen, wie sich die Gewässer um Teldrassil von denen des Festlands unterscheiden."},sec={{t="Gaben des Weltbaums",b="Nessa Schattensang lebt in Rut'theran am Fuße von Teldrassil. Sie sammelte Fischgräten und Schuppen, um das Meeresleben der Insel mit dem des Festlands von Kalimdor zu vergleichen. Die Fänge aus den Gewässern um den Großen Baum erreichen eine erstaunliche Größe. Also schickte Nessa Beweise über das Meer zu Laird, einem Fischhändler an den Docks von Auberdine. Das Paket reist über Vesprystus, den Hippogryphenmeister von Rut'theran, und zeugt von Teldrassils wachsender Lebenskraft."},{t="Ein neugieriger Vergleich",b="An der Dunkelküste stellt Laird fest, dass diese Exemplare ihre Gegenstücke vom Festland an Größe weit übertreffen. Die Sammlung enthält Kieferknochen, die fast doppelt so groß sind wie die von Fischen, die an der Küste der Dunkelküste heimisch sind. Ihre Schuppen sind so groß wie eine geballte Faust. Für die Nachtelfen der Küste zeigt das Paket, wie sehr sich Teldrassils Gewässer von den düsteren Gestaden des nördlichen Kalimdor unterscheiden."}},faq={{q="Was enthält Nessas Sammlung?",a="Die Sammlung enthält Fischgräten und Schuppen. Ihre Kieferknochen sind fast doppelt so groß wie die von Fischen der Dunkelküstenküste, und ihre Schuppen sind so groß wie eine geballte Faust. Die Fische stammen aus den Gewässern um Rut'theran.",al={"nessas sammlung inhalt","was ist im paket","fischgrätenpaket"}},{q="An wen wird die Sammlung geschickt?",a="Nessa schickt die Sammlung an Laird, einen nachtelfischen Fischhändler an den Docks von Auberdine an der Dunkelküste.",al={"wer bekommt nessas sammlung","wer ist laird","lieferziel"}},{q="Warum hat Nessa diese Fischexemplare gesammelt?",a="Nessa sammelte die Exemplare, um die großen Fische, die um Teldrassil gedeihen, mit dem Meeresleben des Festlands von Kalimdor zu vergleichen.",al={"warum fischgräten verschicken","nessa fischvergleich","gaben teldrassils grund"}},{q="Wie erreicht die Sammlung Auberdine?",a="Ihr bringt das Paket zu Vesprystus, dem Hippogryphenmeister von Rut'theran. Er organisiert den Transport über das Wasser nach Auberdine zur Übergabe an Laird.",al={"wie wird es geliefert","vesprystus lieferung","hippogryphenpaket"}}},fx={["6bde19ac"]={q="Was ist Nessas Sammlung?",a="Nessas Sammlung ist ein Bündel aus Fischgräten und Schuppen, das aus den Gewässern um Rut'theran gesammelt wurde. Es repräsentiert die ungewöhnliche marine Fülle, die am Fuße des Weltenbaums Teldrassil gedeiht, sicher verpackt für den Transport über das Meer zum Festland von Kalimdor.",al={"was ist nessas sammlung","nessas sammlung","gegenstand nessas sammlung"}},eb414ab6={q="Woher stammt Nessas Sammlung und wer hat sie zusammengestellt?",a="Die Sammlung wurde von Nessa Schattensang, einer Nachtelfin, die in Rut'theran am südlichen Fuße von Teldrassil lebt, zusammengestellt. Ausgehend von den bemerkenswert großen Fängen, die von den örtlichen Fischerbooten der Insel eingebracht wurden, sammelte sie auserlesene Exemplare, um sie über das Meer zu versenden.",al={"wer hat nessas sammlung zusammengestellt","woher stammt nessas sammlung","ursprung von nessas sammlung"}},d01c5154={q="Warum will jemand Nessas Sammlung haben?",a="Ein Fischhändler namens Laird in Auberdine wartet auf die Exemplare, damit er sie untersuchen kann. Nessa hofft, die erstaunliche Größe und Vitalität von Rut'therans Fängen mit denen vom Festland vergleichen zu können, und Laird ist begierig darauf, Kieferknochen zu untersuchen, die zweimal so groß wie normal sind, und Schuppen, die so groß wie eine Faust sind.",al={"warum will laird nessas sammlung","warum nessas sammlung liefern","zweck von nessas sammlung"}}},fp="18,132,24.419.0,20.355.0,34.237.0,36.98.0,42.120.0,40.145.0"}
P.entries["item:nether-gem"] = {n="Netheredelstein",s="Quer durch Tirisfal trägt der Netheredelstein eine rätselhafte Gestalt vom Blendwassersee zu Bethor Eismacht in Unterstadt. Was sie verbindet, müsst Ihr selbst ergründen.",h="Quer durch Tirisfal trägt der Netheredelstein eine rätselhafte Gestalt vom Blendwassersee zu Bethor Eismacht...",kw={"bethor eismacht","blendwassersee","gunther arkanus","netheredelstein","prodigal lich","unterstadt"},ang={["class:Mage"]="Als Magier seht Ihr, wie arkane Meister große Entfernungen durch magische Hellsicht und projizierte Antlitze überbrücken können, statt die Reise zu wagen.",["race:Undead"]="Als Untoter wisst Ihr, dass die Übergabe des Steins einen diplomatischen Triumph für die Verlassenen darstellt. Sie sichert ihnen Gunther Arkanus als mächtigen Verbündeten gegen die Geißel und den Scharlachroten Kreuzzug."},sec={{t="Ein Kanal arkaner Verständigung",b="Gunther Arkanus schmiedete oder verzauberte den Netheredelstein auf seiner Insel im Blendwassersee. Er hatte sich aus eigener Willenskraft aus der Kontrolle des Lichkönigs befreit, doch Misstrauen hielt ihn von der jungen Nation der Verlassenen fern. Als sein verlorenes Zauberbuch zurückgebracht wird, übergibt Gunther den Edelstein einem Gesandten als Geste des guten Willens.\n\nOben auf dem Magieviertel in Unterstadt kanalisiert Bethor Eismacht Magie durch den Stein. Gunthers magisches Antlitz erscheint vor dem Anführer der Magiergilde, und die beiden Magier sprechen quer durch Tirisfal miteinander. Ihre Begegnung ebnet Gunther den Weg, sich Fürstin Sylvanas und den Verlassenen anzuschließen."}},faq={{q="Was bewirkt der Netheredelstein?",a="Der Netheredelstein ermöglicht es Gunther Arkanus, über große Entfernung mit Bethor Eismacht zu sprechen. Wenn Bethor in Unterstadt Magie in ihn kanalisiert, erscheint Gunthers ätherisches Antlitz, und die beiden Magier können unmittelbar miteinander sprechen.",al={"netheredelstein zweck","was ist der netheredelstein","was bewirkt der netheredelstein"}},{q="Wer hat den Netheredelstein hergestellt?",a="Gunther Arkanus stellt den Netheredelstein bereit. Er lebt auf einer Insel im Blendwassersee und übergibt ihn einem Gesandten für seinen alten Kameraden Bethor, nachdem sein verlorenes Zauberbuch zurückgebracht wurde.",al={"wer hat den netheredelstein hergestellt","woher stammt der netheredelstein","gunther edelstein"}},{q="Warum ist der Netheredelstein für die Verlassenen von Bedeutung?",a="Der Netheredelstein hilft dabei, Gunther Arkanus für die Verlassenen zu gewinnen. Er misstraute anderen Untoten, weil er fürchtete, sie seien noch immer der Geißel hörig. Durch den Edelstein nimmt er wieder Verbindung zu Bethor Eismacht auf und schwört Fürstin Sylvanas die Treue.",al={"warum ist der netheredelstein wichtig","gunther verlassene","verlassene netheredelstein"}}},fx={aa73e2cb={q="Was ist der Netheredelstein?",a="Der Netheredelstein ist ein magischer Fokus, der Euch von Gunther Arkanus, einem mächtigen untoten Magier, der auf einer Insel im Blendwassersee lebt, anvertraut wurde. Aufgeladen mit mystischen arkanen Energien, fungiert er als magischer Kanal, der es Gunther ermöglicht, über große Entfernungen zu kommunizieren und sein Abbild direkt zu seinem alten Verbündeten Bethor Eismacht in die Unterstadt zu projizieren.",al={"was ist der netheredelstein","lore zu netheredelstein","gegenstand netheredelstein"}}},fp="10,160,29.595.1,28.211.0,27.175.1,50.228.1"}
P.entries["item:ng-5"] = {n="NG-5",s="Im Steinkrallengebirge bereitet Gaxim Rostknirsch mit NG-5 ein Ablenkungsmanöver vor. Die flüchtige Chemikalie Nitromirglyceronium ist die Zündverbindung, die er für mit Dynamit beladene Wagen benötigt.",h="Im Steinkrallengebirge bereitet Gaxim Rostknirsch mit NG-5 ein Ablenkungsmanöver vor.",kw={"dynamit","sprengstoffe","gaxim rostknirsch","gnom","ng-5","ng5","nitromirglyceronium","steinkrallengebirge"},ang={["profession:Engineering"]="Als Ingenieur kennt Ihr NG-5 vielleicht als Nitromirglyceronium, einen launischen chemischen Katalysator, den Tüftler schätzen, wenn gewöhnlichem Schwarzpulver die Sprengkraft für schwere Geschütze fehlt.",["race:Gnome"]="Als Gnom erkennt Ihr vielleicht den risikofreudigen Erfindergeist darin, mit einer instabilen Chemikalie ganze Wagenladungen Dynamit als bloße Ablenkung zu sprengen."},sec={{t="Ein flüchtiges Reagenz",b="Gaxim Rostknirsch ist ein gnomischer Agent im Steinkrallengebirge, und NG-5 ist die Verbindung, die er für seine Ingenieurspläne benötigt. Ihr vollständiger Name lautet Nitromirglyceronium. Die gefährliche Lösung liefert die Reaktion, um mit Dynamit beladene Wagen zu sprengen und mit einer gewaltigen Explosion seine Widersacher in der Region abzulenken."}},faq={{q="Was ist NG-5?",a="NG-5 ist die Kurzbezeichnung für Nitromirglyceronium, eine höchst instabile Chemikalie, die in der gnomischen Ingenieurskunst zum Zünden von Sprengstoffen verwendet wird.",al={"was ist ng5","was ist nitromirglyceronium","ng 5 gegenstand"}},{q="Wer will NG-5 und warum?",a="Gaxim Rostknirsch, ein gnomischer Ingenieur im Steinkrallengebirge, benötigt NG-5, um mehrere mit Dynamit vollgepackte Wagen zu sprengen. Er plant, die Explosionen als Ablenkung zu nutzen.",al={"wer braucht ng-5","gaxim rostknirsch ng-5","warum ng5 beschaffen"}},{q="Ist der Umgang mit NG-5 gefährlich?",a="Der Umgang mit NG-5 ist äußerst gefährlich. Sein Lieferant mahnt Kuriere zu äußerster Vorsicht und scherzt, dass sich jeder, der kein Verbündeter von Gaxim ist, vermutlich selbst in Stücke sprengen wird.",al={"ist ng5 sicher","ng-5 sprengstoff","explodiert ng5"}}},fx={["43a87313"]={q="Woher stammt NG-5 und wer hat es hergestellt?",a="NG-5, auch bekannt als Nitromirglyceronium, wird von einem Bekannten von Gaxim Rostknirsch bezogen, der spezielle chemische Verbindungen braut. Es ist eine extrem flüchtige alchemistische Mischung, die speziell für explosive Reaktionen zusammengestellt wurde und nur mit strengen Warnungen übergeben wird, wie leicht sie einen unvorsichtigen Boten in Stücke reißen kann.",al={"wer hat ng-5 hergestellt","wo bekommt man ng-5","erfinder von ng-5"}}},fp="4,190,18.319.0,13.115.0,23.170.0,28.183.0"}
P.entries["item:nida-s-necklace"] = {n="Hilarys Halskette",s="In Seenhain sucht Hilary im Immerruhsee nach der Halskette, die ihr Vater ihr geschenkt hat. Sie versank im Wasser, als Hilary und die anderen Kinder an den Stegen angelten.",h="In Seenhain sucht Hilary im Immerruhsee nach der Halskette, die ihr Vater ihr geschenkt hat.",kw={"effsee","glitzernder schlamm","hilary","der immerruhsee","seenhain","nida","nidas halskette","rotkammgebirge","shawn"},ang={["faction:Alliance"]="Die Verteidiger von Seenhain sehen sich Bedrohungen aus der Umgebung gegenüber. Durchreisende Abenteurer der Allianz können den Kindern des Ortes helfen, verlorene Erinnerungsstücke wiederzufinden."},sec={{t="In der Tiefe verloren",b="Hilary verlor ihre Halskette beim Angeln mit ihrem Freund Shawn am Ufer von Seenhain. Ihr Vater hat sie ihr geschenkt, und sie hält sein Geschenk in Ehren.\n\nWilde Bestien und aggressive Murlocs leben in den Tiefen des Sees, deshalb bleiben die Kinder des Ortes auf den Stegen. Hilarys Halskette liegt unter Wasser, im Schlamm des Seegrunds begraben."}},faq={{q="Wem gehört diese Halskette?",a="Hilary, ein junges Mädchen aus Seenhain im Rotkammgebirge, ist die Besitzerin der Halskette. Ihr Vater hat sie ihr geschenkt.",al={"wem gehört die halskette","nida halskette besitzerin","wessen halskette ist das","hilary halskette besitzerin"}},{q="Wie ist die Halskette im Immerruhsee gelandet?",a="Hilary angelte mit Shawn am Wasser, als die Halskette abrutschte und im Immerruhsee versank.",al={"wie kam sie in den see","warum ist die halskette im wasser","wie ging die halskette verloren"}},{q="Warum sind die Kinder nicht nach ihr getaucht?",a="Ihre Eltern verbieten den Kindern, im Immerruhsee zu schwimmen. Gefährliche Raubtiere und aggressive Murlocs leben in seinen tiefen Gewässern und bedrohen die Stadtbewohner.",al={"warum schwamm nida nicht nach ihr","warum kann shawn die halskette nicht holen","warum schwamm hilary nicht nach ihr"}},{q="Wer ist Effsee?",a="Effsee ist Hilarys Hauskatze. Effsee bleibt in Seenhain an ihrer Seite und freut sich, wenn die Halskette zu ihrer jungen Besitzerin zurückkehrt.",al={"wer ist das kätzchen","nida katze","hilary katze"}}},fx={a22bd4db={q="Woher hat Hilary ihre Halskette?",a="Die Halskette war ein Geschenk von Hilarys Vater. Auch wenn sie weder geschichtlich noch magisch von großer Bedeutung ist, ist sie ein wertvolles Familienerbstück, das einem jungen Mädchen in Seenhain geschenkt wurde.",al={"wer fertigte hilarys halskette an","woher stammt hilarys halskette","wer gab hilary die halskette"}},["14f3017c"]={q="Warum wird nach Hilarys Halskette gesucht?",a="Hilary verlor die Halskette beim Angeln an den Docks des Immerruhsees. Da ihre Eltern den Kindern verbieten, in die von Monstern verseuchten Gewässer zu tauchen, bittet ihre Freundin Shawn vorbeikommende Abenteurer, sich in die Tiefen des Sees zu wagen und das geschätzte Andenken zurückzuholen.",al={"warum nach hilarys halskette suchen","wer will hilarys halskette","warum möchte hilary ihre halskette zurück"}}},fp="17,165,18.314.0,33.106.0,46.102.0,47.157.0,14.120.0"}
P.entries["item:nightmare-shard"] = {n="Alptraumsplitter",s="In den Höhlen des Wehklagens trägt der Alptraumsplitter einen Makel, den Falla Weisenwind nicht ignorieren kann. Sie bannt die reine, verstörte Essenz des Smaragdgrünen Traums in ihn und schickt ihn mit einer Warnung an ranghohe Druiden, die nur für sie bestimmt ist.",h="In den Höhlen des Wehklagens trägt der Alptraumsplitter einen Makel, den Falla Weisenwind nicht ignorieren...",kw={"smaragdgrüner traum","falla weisenwind","leuchtender splitter","hamuul runetotem","in nightmares","mathrengyl bärenfährte","alptraumsplitter","die höhlen des wehklagens"},ang={["class:Druid"]="Den Druiden offenbart der Splitter, dass die Verderbnis den Smaragdgrünen Traum erreicht hat. Er bestätigt ihre Sorgen um Naralex' Schicksal in den Höhlen des Wehklagens.",["faction:Horde"]="Für Reisende der Horde bringt der Splitter ernste Nachrichten zur Anhöhe der Ältesten in Donnerfels. Dort arbeitet Hamuul Runetotem daran, den Platz der Tauren in der größeren Bruderschaft des Cenarius zu festigen."},sec={{t="Eine verderbte Vision",b="Tief in den Höhlen des Wehklagens untersucht Falla Weisenwind einen leuchtenden Splitter. Seine Energie ist dunkler, als sie erwartet hatte. Er spiegelt ein unnatürliches Leiden im Smaragdgrünen Traum wider, wie einen wachen Alptraum. Falla bannt diese verderbte Essenz in den Alptraumsplitter und befiehlt, ihn unverzüglich zu den ältesten Anführern des Zirkels des Cenarius zu bringen."},{t="Verschwiegene Vorzeichen",b="Der Alptraumsplitter erreicht Erzdruide Hamuul Runetotem auf der Anhöhe der Ältesten oder Mathrengyl Bärenfährte in Darnassus. Beide blicken bestürzt in seine Tiefen. Die Vision beunruhigt sie und bestätigt ihren stillen Verdacht, dass im Traum etwas furchtbar schiefgelaufen ist. Aus Furcht vor öffentlicher Panik nehmen die Druiden den Splitter an sich und ermahnen den Boten, nicht weiter über das Gesehene zu sprechen."}},faq={{q="Was ist der Alptraumsplitter?",a="Nachdem Falla Weisenwind ein leuchtendes Fragment aus den Höhlen des Wehklagens untersucht hat, vertraut sie den Alptraumsplitter einem Boten an. Er enthält die reine, verstörte Essenz des Smaragdgrünen Traums, mit einer dunklen, verderblichen Vision anstelle friedlicher Naturenergien.",al={"was ist der alptraumsplitter","alptraumsplitter hintergrundgeschichte"}},{q="Wer hat den Alptraumsplitter erschaffen?",a="Falla Weisenwind untersucht ein leuchtendes Fragment aus den Höhlen des Wehklagens und erkennt seine Verderbnis. Sie beauftragt den Boten, den Splitter zur Untersuchung direkt zu ranghohen Druiden zu bringen.",al={"wer hat den alptraumsplitter erschaffen","woher kommt der splitter"}},{q="Warum sind die Druidenanführer deswegen so beunruhigt?",a="Beim Blick in den Splitter sehen Hamuul Runetotem und Mathrengyl Bärenfährte einen Alptraum, der den Smaragdgrünen Traum verzerrt. Aus Furcht vor Gefahr und öffentlicher Panik unterbinden sie weitere Gespräche und halten die Angelegenheit im Kreis ranghoher Mitglieder des Zirkels des Cenarius.",al={"warum ist hamuul besorgt","warum versteckt mathrengyl den splitter"}},{q="Wohin muss der Splitter gebracht werden?",a="Reisende der Horde werden angewiesen, den Splitter zu Erzdruide Hamuul Runetotem auf der Anhöhe der Ältesten in Donnerfels zu bringen. Reisende der Allianz bringen ihn zu Mathrengyl Bärenfährte beim Zirkel des Cenarius in Darnassus.",al={"zu wem den splitter bringen","alptraumsplitter abgeben"}}},fp="15,214,18.327.0,12.369.1,28.241.0,32.186.0,43.240.1,42.205.0"}
P.entries["item:nightsaber-fang"] = {n="Nachtsäblerfangzahn",s="In Teldrassil erbeuten Jäger Fangzähne von Nachtsäblern, die durch den Wald streifen. Waldbewohner suchen die Zähne als Reagenzien.",h="In Teldrassil erbeuten Jäger Fangzähne von Nachtsäblern, die durch den Wald streifen.",kw={"dolanaar","fangzahn","nachtsäbler","reagenz","satyr","teldrassil","zenn faulhuf"},ang={["class:Hunter"]="Als Jäger beweist Ihr Euer Geschick in der Wildnis, indem Ihr einen Nachtsäbler erlegt und seinen Fangzahn an Euch nehmt. Seine Körperteile verderbten Waldgeistern zu geben, verdreht den Geist der Jagd.",["race:NightElf"]="Als Nachtelf kennt Ihr Nachtsäbler als geschätzte Gefährten und Sinnbilder Elunes. Diese heiligen Raubtiere für einen verräterischen Satyr zu jagen, bringt Schande."},sec={{t="Trophäe der Jagd",b="Unter Teldrassils Blätterdach jagen Nachtsäbler als einige der tödlichsten natürlichen Raubtiere im Norden Kalimdors. Nachtelfen verehren sie für ihre Wendigkeit, Wildheit und tiefe spirituelle Verbindung zu Elune. Ein Jäger, der einen erlegt, kann dessen scharfe Fangzähne als Beweis seines Geschicks mitnehmen. Doch manche Gestalten im Wald begehren diese Fangzähne für finsterere Rituale."},{t="Reagenz eines Satyrs",b="Außerhalb von Dolanaar hat es der Satyr Zenn Faulhuf auf eifrige, unerfahrene Reisende abgesehen. Er behauptet, Reagenzien aus dem Wald zu benötigen, und überredet Neuankömmlinge dann, Nachtsäblerfangzähne, Strigidfedern und Spinnenseide zu sammeln. Ihm diese Materialien zu geben, hilft dem Betrüger. Bei der Übergabe verspottet er den naiven Helden ganz offen."}},faq={{q="Woher stammen Nachtsäblerfangzähne?",a="Nachtsäblerfangzähne stammen von den räuberischen Nachtsäblern, die durch Teldrassil streifen, besonders im Wald um Dolanaar.",al={"wo nachtsäblerfangzähne bekommen","wer lässt nachtsäblerfangzähne fallen","nachtsäblerfangzahn herkunft"}},{q="Wer will Nachtsäblerfangzähne in Teldrassil?",a="Zenn Faulhuf, ein Satyr außerhalb von Dolanaar, bittet umherziehende Abenteurer, ihm Nachtsäblerfangzähne zu bringen.",al={"wer braucht nachtsäblerfangzähne","nachtsäblerfangzahn abgeben","wer kauft nachtsäblerfangzähne"}},{q="Warum will Zenn Faulhuf Nachtsäblerfangzähne?",a="Zenn behauptet, tierische Reagenzien für seine Arbeit im Wald zu benötigen, hält ihren Zweck jedoch geheim. Er hat seine Freude daran, leichtgläubige Reisende zu täuschen.",al={"warum zenn fangzähne will","zenn faulhuf reagenzien zweck","zenn bidding motiv"}},{q="Welche anderen Reagenzien verlangt Zenn neben den Fangzähnen?",a="Neben zwei Nachtsäblerfangzähnen verlangt Zenn zwei Strigid-Eulenfedern und zwei Stücke Waldweberspinnenseide.",al={"was braucht zenn noch","zenn bidding gegenstände","andere reagenzien für zenn"}}},fx={bc504af2={q="Was ist ein Nachtsäblerfangzahn?",a="Ein Nachtsäblerfangzahn ist ein scharfer Eckzahn, der von den Nachtsäblern stammt, die durch die Wälder von Teldrassil streifen. Obwohl er lediglich ein natürlicher Teil dieser raubtierhaften Großkatzen ist, werden solche Fangzähne von Praktizierenden dunkler Künste gesucht, die sie als rohe Reagenzien für geheime Rituale und nicht genehmigte Gebräue schätzen.",al={"was ist ein nachtsäblerfangzahn","lore zu nachtsäblerfangzahn","über nachtsäblerfangzähne"}}},fp="15,118,18.331.0,17.310.1,36.115.0,41.98.0,45.138.1,58.112.0"}
P.entries["item:nissa-s-remains"] = {n="Nissas sterbliche Überreste",s="Im nördlichen Tirisfal stammen Nissas sterbliche Überreste von einer Adligen der einst wohlhabenden Familie Agamand. Die Geißel erschlug sie und ihre Verwandten während des Dritten Krieges und band sie dann als geistlose Diener an sich. Nun jagen ehemalige Arbeiter die Familie, um Rache zu nehmen.",h="Im nördlichen Tirisfal stammen Nissas sterbliche Überreste von einer Adligen der einst wohlhabenden Familie...",kw={"agamands mühlen","brill","coleman heller","deaths in the family","nissa agamand","nissas sterbliche überreste","tirisfal"},ang={["faction:Horde"]="Die wiederbelebten Agamands zu erschlagen und ihre Mühlen zu säubern, hilft, das nördliche Tirisfal vor verbliebenen Geißeltruppen zu sichern, die Brill und Unterstadt bedrohen.",["race:Undead"]="Für die Verlassenen bedeutet die Rückeroberung Tirisfals, ihre früheren Unterdrücker von der Geißel und die reichen Adligen auszumerzen, deren Stolz einfache Arbeiter zum Untod verdammte."},sec={{t="Ein Erbe des Stolzes",b="Vor dem Dritten Krieg waren die Agamands die wohlhabendste und einflussreichste Familie in Tirisfal. Ihre florierenden Mühlen standen über die nördlichen Hügel verteilt. Als sich die Seuche des Untods in Lordaeron ausbreitete, weigerten sich die Patriarchen zu fliehen. Sie befestigten ihre Anwesen und überredeten ihre Gefolgsleute und Arbeiter, zu bleiben und zu kämpfen. Ihr Stolz kostete sie das Leben. Die Geißel erschlug die Agamands und erweckte sie als geistlose Knechte, die an den Willen des Lichkönigs gebunden waren."},{t="Bittere Vergeltung",b="In Brill erinnern sich Überlebende, die sich später unter Königin Sylvanas Windläufer befreiten, noch immer an den verhängnisvollen Stolz der Agamands. Coleman Heller arbeitete einst in ihren Mühlen und grollt seinen ehemaligen Herren, weil sie die Arbeiter in den Untod lockten. Er schickt Abenteurer aus, um die wiedererweckten Agamands niederzustrecken und ihre körperlichen Überreste zu bergen, darunter auch Nissas. Für Heller und andere Verlassene bringt die Zerstörung dieser Relikte ein düsteres Gefühl von Abschluss und Rache."}},faq={{q="Wer war Nissa Agamand?",a="Nissa Agamand war eine Adlige der Familie Agamand, der die weitläufigen Agamands Mühlen in Tirisfal gehörten. Als die Geißel durch Lordaeron fegte, starb sie mit ihren Verwandten und wurde als untote Dienerin unter der Kontrolle des Lichkönigs wiedererweckt.",al={"wer ist nissa","nissas geschichte","nissa agamand"}},{q="Warum will Coleman Heller Nissas sterbliche Überreste?",a="Coleman Heller arbeitete zu Lebzeiten in den Mühlen der Agamands. Er grollt der Familie, weil sie sich weigerte zu fliehen und ihre treuen Arbeiter überredete, zu bleiben und zu sterben. Die Überreste der Familie zu sammeln, lässt ihn Rache an seinen ehemaligen Herren nehmen.",al={"warum will coleman die überreste","warum die agamands töten","coleman hellers beweggrund"}},{q="Wo werden diese Überreste gesammelt?",a="Nissa Agamand sucht die Ruinen von Agamands Mühlen im nördlichen Tirisfal heim. Sie wandert mit ihren wiederbelebten Verwandten und geistlosen Knechten der Geißel zwischen den verfallenen Bauernhäusern umher.",al={"wo ist nissa zu finden","nissa agamand fundort"}},{q="Behielt Nissa ihren freien Willen wie die Verlassenen?",a="Nein. Nissa und ihre Familie blieben als geistlose Untote von der Geißel versklavt, während die Verlassenen sich vom Lichkönig befreiten. Ihnen fehlten das Bewusstsein und die Freiheit der Bürger von Unterstadt.",al={"ist nissa eine verlassene","hatte nissa einen freien willen","gehört nissa zur geißel"}}},fx={a9aa03e3={q="Was sind Nissas sterbliche Überreste?",a="Dies sind die physischen Überreste von Nissa Agamand, einem Mitglied der wohlhabenden Agamand-Dynastie, der einst die Mühlen im nördlichen Tirisfal gehörten. Als die Geißel durch Lordaeron fegte, befestigte die Familie ihr Anwesen und überzeugte ihre Arbeiter, standhaft zu bleiben. Wie der Rest ihrer Verwandtschaft fiel Nissa der Seuche zum Opfer und erhob sich als gedankenloser Thrall im Dienste des Lichkönigs.",al={"was sind nissas sterbliche überreste","nissas sterbliche überreste","wem gehören nissas sterbliche überreste"}},["4cb46b58"]={q="Woher stammen Nissas sterbliche Überreste und wer hat sie hergestellt?",a="Sie werden direkt von der zerstörten Leiche von Nissa Agamand bei Agamands Mühlen geborgen. Einst eine stolze Aristokratin, erlag sie der Seuche des Untodes und verweilte auf ihrem angestammten Land als untote Kreatur. Die Überreste sind das, was Ihr bergt, nachdem Ihr ihre gedankenlose Geißelgestalt zur Ruhe gelegt habt.",al={"wo bekommt man nissas sterbliche überreste","wie bekommt man nissas sterbliche überreste","wer hat nissas sterbliche überreste fallen gelassen"}}},fp="15,240,17.460.0,18.437.0,22.243.0,47.228.0,33.176.0,49.195.0"}
P.entries["item:nitroglycerin"] = {n="Nitroglyzerin",s="In Bael Modan treiben Zwerge mit Nitroglyzerin ihre Ausgrabungen ins Land der Tauren voran. Soldaten und Offiziere tragen die flüchtige Chemikalie bei sich, die sich auch gegen die Festung richten lässt.",h="In Bael Modan treiben Zwerge mit Nitroglyzerin ihre Ausgrabungen ins Land der Tauren voran.",kw={"bael modan","bael'dun","brachland","sprengstoffe","gann steinkeil","nitroglyzerin","revenge of gann"},ang={["profession:Engineering"]="Als Ingenieur kennt Ihr Nitroglyzerin als Sprengstoff zur Herstellung von Sprengstoffgemischen. Holzbrei saugt es auf, während Natriumnitrat dazu beiträgt, es stabil und zündfähig zu machen.",["race:Tauren"]="Als Tauren kennt Ihr die flüchtigen Chemikalien rund um Bael Modan als bitteres Zeichen der Zerstörung, die dem Stamm der Stonespire zugefügt wurde."},sec={{t="Industrielle Sprengarbeiten",b="In Bael Modan graben Zwerge im angestammten Land der Stonespire-Tauren. Schwere Bohrmaschinen und flüchtige Chemikalien helfen ihnen, die Ausgrabungen voranzutreiben. An der Grabungsstätte und in der zugehörigen befestigten Burg sprengen sie mit Nitroglyzerin tiefe Löcher und reißen Hügel auseinander. Während die Arbeiten weitergehen, tragen Soldaten und Offiziere Phiolen bei sich, darunter auch Lord Cyrik Blackforge."},{t="Ihre eigene Medizin",b="Nach dem Tod von Prospector Khazgorm will Gann Steinkeil die Festung zerstören, die in das Land seines Volkes vordringt. Trotz der Gefahr studiert der vertriebene Tauren die Konstruktionspläne der Zwerge. Er erfährt, dass sich Nitroglyzerin, Holzbrei und Natriumnitrat zu einer Sprengladung verbinden lassen, die stark genug ist, Bael Modans Militärgarnison anzugreifen."}},faq={{q="Woher stammt das Nitroglyzerin?",a="Die Zwergentruppen in Bael Modan im Südlichen Brachland tragen Nitroglyzerin bei sich. Zu ihnen gehören Bael'dun Soldiers, Riflemen, Officers und Lord Cyrik Blackforge in der Burg.",al={"wo nitroglyzerin finden","wer lässt nitroglyzerin fallen","nitroglyzerin quelle"}},{q="Wofür wird das Nitroglyzerin verwendet?",a="Gann Steinkeil verbindet Nitroglyzerin mit Holzbrei und Natriumnitrat zu einer mächtigen Sprengladung gegen Bael Modans Militärfestung.",al={"wofür ist nitroglyzerin","nitroglyzerin verwendung","revenge of gann zutaten"}},{q="Warum trugen die Zwerge es überhaupt bei sich?",a="An ihrer archäologischen Grabungsstätte setzen die Prospektoren und Soldaten von Bael Modan Sprengstoffe, Dampfmaschinen und flüchtige Chemikalien ein, um die Erde aufzubrechen.",al={"warum haben zwerge nitroglyzerin","bael modan sprengstoffe"}},{q="Wer ist Gann Steinkeil?",a="Gann Steinkeil ist ein verbannter Taurenkrieger. Die Zwerge errichteten die Ausgrabungsstätte und die Burg von Bael Modan im angestammten Land seines Stammes und vertrieben die Stonespire durch industrielle Zerstörung.",al={"wer ist gann","gann steinkeil"}}},fx={["9ba54f78"]={q="Was ist Nitroglyzerin?",a="Nitroglyzerin ist eine flüchtige chemische Substanz, die von den zwergischen Streitkräften mitgeführt wird, die sich in Bael Modan im südlichen Brachland verschanzt haben. Die Bael'dun-Expedition verlässt sich auf schwere Ingenieurskunst und Sprengstoffe, um angestammtes Land der Tauren auszuheben und die Erde aufzureißen. In flüchtigen Mischungen dient es als entscheidende Komponente bei der Konstruktion hocheffektiver Sprengladungen.",al={"was ist nitroglyzerin","lore zu nitroglyzerin","was bewirkt nitroglyzerin"}}},fp="13,181,21.348.0,29.333.1,35.166.0,35.138.0,52.142.0,23.199.0"}
P.entries["item:nondescript-letter"] = {n="Unscheinbarer Brief",s="Calvin Montague schickt einen Unscheinbaren Brief aus Todesend an Gastwirtin Renee in Brill. Er bittet frisch erwachte Verlassene, ihn nach Osten zu bringen, und gibt ihnen damit einen Anlass, das Tal in Richtung der Taverne Zur Galgenschlinge zu verlassen.",h="Calvin Montague schickt einen Unscheinbaren Brief aus Todesend an Gastwirtin Renee in Brill.",kw={"a rogue's deal","brill","calvin montague","todesend","gastwirtin renee","unscheinbarer brief","renee"},ang={["class:Rogue"]="Für Euch als Schurke deuten Calvin Montagues zwielichtige Art und Renees plötzlicher Stimmungswechsel auf Intrigen und verschlüsselte Nachrichten aus der Unterwelt hin.",["race:Undead"]="Als frisch auferstandener Verlassener gibt Euch dieser Botengang früh einen Anlass, Todesend zu verlassen und die Siedlungen von Tirisfal zu erkunden."},sec={{t="Ein Botengang",b="Nahe Todesend bittet Calvin Montague frisch auferstandene Verlassene, einen unbeschrifteten Umschlag nach Osten nach Brill zu bringen. Er sagt, er sei vom Kampf gegen Zombies und Spinnen erschöpft und der Brief sei für Gastwirtin Renee bestimmt. Sein Versprechen einer reichen Belohnung klingt hohl. Der Botengang führt Reisende aus dem Tal in Richtung der Taverne Zur Galgenschlinge."},{t="Verdächtige Korrespondenz",b="In Brill behauptet Gastwirtin Renee, der Brief bringe erfreuliche Nachrichten von ihrer heiligen Mutter in Todesend. Als der Bote ihre Geschichte durchschaut, schlägt ihre Heiterkeit in Verärgerung um. Sie reißt den Brief an sich und weigert sich zu sagen, wer ihn geschickt hat oder was darin steht. Sofern der Überbringer nicht für ein Zimmer bezahlen will, schickt sie ihn fort."}},faq={{q="Was ist der Unscheinbare Brief?",a="Der Unscheinbare Brief ist ein unbeschrifteter Umschlag, den Calvin Montague frisch erwachten Verlassenen nahe Todesend gibt, damit sie ihn zu Gastwirtin Renee in Brill bringen.",al={"unscheinbarer brief","was ist dieser brief","calvins brief"}},{q="Wer schickt den Brief, und wer erhält ihn?",a="Calvin Montague übergibt den Brief in Todesend an Boten. Er ist an Gastwirtin Renee in der Taverne Zur Galgenschlinge in Brill adressiert.",al={"wer hat den brief geschickt","wer bekommt den brief","absender des briefes"}},{q="Was steht tatsächlich in dem Brief?",a="Der Inhalt des Briefes wird nie enthüllt. Wenn Ihr nachfragt, lässt Gastwirtin Renee ihre gespielte Heiterkeit fallen und erklärt wütend, Herkunft und Inhalt gingen Euch nichts an.",al={"was steht im brief","briefinhalt","lässt sich der brief lesen"}},{q="Warum möchte Calvin Montague den Brief zustellen lassen?",a="Calvin sagt, er sei zu sehr mit dem Kampf gegen Zombies und Spinnen in der Nähe beschäftigt, um den Brief selbst zu überbringen. Die Zustellung führt Reisende aus Todesend hinaus und zu den Gasthäusern und Rastplätzen von Brill.",al={"warum den brief schicken","calvins beweggrund","warum brill"}}},fp="18,205,18.327.0,25.323.1,31.146.0,42.131.0,34.163.0,43.190.0"}
P.entries["item:nori-s-mug"] = {n="Noris Becher",s="In Dun Morogh schickt Nori Stolzmut einen Becher Morgengebräu nach Ambossar. Reisende bringen das Getränk zu Durnan Pelznaht und geben den leeren Becher dann seinem Besitzer zurück.",h="In Dun Morogh schickt Nori Stolzmut einen Becher Morgengebräu nach Ambossar.",kw={"bring back the mug","dun morogh","durnan pelznaht","morgengebräu","nori stolzmut","noris becher"},ang={["race:Dwarf"]="Als Zwerg wisst Ihr, dass ein warmes Getränk Euch in den Stürmen von Dun Morogh Trost spenden kann. Nori erwartet, dass Ihr seinen Becher zurückbringt."},sec={{t="Die Rückkehr des Boten",b="Nori Stolzmut verleiht seinen Becher für eine Lieferung durch die eisigen Pässe von Dun Morogh. Er enthält heißes Morgengebräu für Durnan Pelznaht in Ambossar, wo ihm das Getränk in der bitteren Kälte wohltut. Nachdem Durnan ihn geleert hat, kehrt der Becher zu Nori zurück. Er erinnert Reisende daran, dass Becher nicht auf Bäumen wachsen, und erwartet sein robustes Trinkgefäß zurück."}},faq={{q="Wozu dient Noris Becher?",a="Noris Becher enthält brühend heißes Morgengebräu für Durnan Pelznaht in Ambossar. Nachdem Durnan es getrunken hat, geht der leere Becher zurück an Nori Stolzmut.",al={"zweck von noris becher","was war im becher","noris becher"}},{q="Wem gehört dieser Becher?",a="Nori Stolzmut gehört der Becher. Er erwartet, dass Reisende ihn zurückbringen, nachdem sie sein Getränk nach Ambossar geliefert haben.",al={"wer ist nori","besitzer des bechers","wem gehört der becher"}},{q="Warum besteht Nori darauf, den Becher zurückzubekommen?",a="Nori erwartet den Becher zurück, denn wie er sagt, wachsen Becher nicht auf Bäumen. Er möchte sein verliehenes Trinkgefäß zurückhaben.",al={"warum den becher zurückbringen","warum will nori ihn zurück","becher wachsen nicht auf bäumen"}},{q="Was wurde aus dem Becher getrunken?",a="Der Becher enthielt brühend heißes Morgengebräu, ein warmes Getränk, das die beißende Kälte von Dun Morogh abwehren soll.",al={"was war in der tasse","was ist morgengebräu","morgengebräu getränk"}}},fp="10,154,18.339.0,28.137.0,18.103.0,45.128.0,28.88.0"}
P.entries["item:notched-rib"] = {n="Schartige Rippe",s="Bei Agamands Mühlen brechen die Verlassenen die Herrschaft der Geißel über Tirisfal.",h="Bei Agamands Mühlen brechen die Verlassenen die Herrschaft der Geißel über Tirisfal.",kw={"agamands mühlen","brill","soldat mit gespaltenem schädel","todeswache dillinger","schartige rippe","klapperkäfigsoldat","geißel","tirisfal"},ang={["race:Undead"]="Als Verlassene sammelt Ihr diese zersplitterten Knochen in einem Überlebenskampf gegen die geistlosen Diener des Lichkönigs. Sie würden Euch wieder in die Knechtschaft zerren."},sec={{t="Düstere Beweise der Schlacht",b="Im Norden von Tirisfal sammelt die Geißel Skelette in zerschlissenen Rüstungen. Soldaten mit gespaltenem Schädel und Klapperkäfigsoldaten greifen jedes Lebewesen und jede Kreatur mit freiem Willen an, denen sie begegnen. Ihre spröden Knochen tragen die Dellen und Kerben der Schlacht. Die Todeswachen brauchen Beweise dafür, dass Kundschafter und Freiwillige der Verlassenen diese geistlosen Eindringlinge töten. Jede schartige Rippe zeugt von einem weiteren zerschmetterten Knecht des Lichkönigs."},{t="Die Mühlen sichern",b="Nordwestlich von Brill nehmen Agamands Mühlen eine Schlüsselposition ein. Sollte sich die Geißel zwischen den verfallenen Gehöften und Windmühlen festsetzen, könnten die Untoten von diesem Stützpunkt aus tief nach Tirisfal vorstoßen. Todeswache Dillinger überwacht die nördlichen Straßen und entsendet Streiter, um die Skelettreihen zu zerschlagen, bevor sie an Stärke gewinnen. Die nach Brill zurückgebrachten Rippen zeigen, dass die Front der Verlassenen hält und die Vorhut der Geißel Knochen für Knochen aufreibt."}},faq={{q="Was ist eine Schartige Rippe?",a="Eine Schartige Rippe ist ein von Kämpfen gezeichneter Knochen eines wiederbelebten Soldaten der Geißel aus dem Norden von Tirisfal. Sie beweist Todeswache Dillinger, dass ein Feind vernichtet wurde.",al={"schartige rippe","was ist eine schartige rippe","schartige rippe gegenstand"}},{q="Woher stammen Schartige Rippen?",a="Schartige Rippen stammen von Soldaten mit gespaltenem Schädel und Klapperkäfigsoldaten, die bei Agamands Mühlen nordwestlich von Brill patrouillieren.",al={"wo findet man eine schartige rippe","wer lässt schartige rippen fallen","schartige rippe herkunft"}},{q="Wer will diese Knochen?",a="Todeswache Dillinger sammelt an der Straße außerhalb von Brill Schartige Rippen und Geschwärzte Schädel, um zu bestätigen, dass der Vormarsch der Geißel zurückgeschlagen wurde.",al={"wer nimmt schartige rippen","schartige rippe abgeben","wer braucht eine schartige rippe"}},{q="Warum sammelt sich die Geißel bei Agamands Mühlen?",a="Die geistlosen Untoten versuchen, bei Agamands Mühlen einen Stützpunkt zu errichten. Von dort aus könnten sie in ganz Tirisfal zuschlagen und Siedlungen der Verlassenen bedrohen.",al={"geißel bei agamands mühlen","warum sind skelette bei den mühlen","agamands mühlen bedrohung durch die geißel"}}},fp="11,75,20.419.0,18.431.0,22.173.0,32.119.0,22.147.0,46.156.0"}
P.entries["item:nugget-slug"] = {n="Schraubniete",s="Werkzeugeimer im Schlickermoor enthalten Schraubnieten, die die Venture Company für ihre schwere Ausrüstung verwendet. Tüftler suchen diese Verbindungselemente der Stärke siebzehn Komma fünf für Arbeiten an unberechenbaren Maschinen.",h="Werkzeugeimer im Schlickermoor enthalten Schraubnieten, die die Venture Company für ihre schwere Ausrüstung...",kw={"brachland","schraubniete","samophlange","das schlickermoor","werkzeugeimer","venture company","wenikee boltbucket"},ang={["profession:Engineering"]="Für einen Ingenieur passen herstellerspezifische Bauteile der Stärke siebzehn Komma fünf schlecht zu einer instabilen, von Goblins konstruierten Samophlange. Rechnet mit einer raschen, explosiven Zerlegung."},sec={{t="Industrielle Verbindungselemente des Schlickermoors",b="An den Förderstätten der Venture Company halten Schraubnieten schwere Ausrüstung zusammen. Sie sind für anspruchsvolle industrielle Baugruppen gefertigt und haben die Stärke siebzehn Komma fünf. Im gewöhnlichen Handel finden sie wenig Verwendung. Doch Tüftler brauchen sie für maßgefertigte Goblintechnik."},{t="Tüftelei an der Samophlange",b="Wenikee Boltbucket braucht viele Schraubnieten, um eine instabile Samophlange zu überholen, die aus dem Brachland geborgen wurde. Über die Bohranlagen der Venture Company im Schlickermoor verstreut liegen Werkzeugeimer, was die Bergung für Plünderer einträglich macht.\n\nWenikees Reparaturen enden in einem plötzlichen Fehlschlag. Die Samophlange explodiert, während sie daran arbeitet."}},faq={{q="Was ist eine Schraubniete?",a="Eine Schraubniete ist ein metallisches Verbindungselement der Stärke siebzehn Komma fünf, das in schweren Maschinen verwendet wird. Diese Verbindungselemente halten komplexe Mechanismen wie Ölbohrer und Samophlangen zusammen.",al={"was sind schraubnieten","schraubniete hintergrund","schraubniete verbindungselement"}},{q="Wo sind Schraubnieten zu finden?",a="Schraubnieten werden in Werkzeugeimern aufbewahrt, die im Schlickermoor verstreut stehen, einem Bohrlager der Venture Company im nordöstlichen Brachland.",al={"wo sind schraubnieten zu finden","schraubniete fundort","schlickermoor werkzeugeimer"}},{q="Warum braucht Wenikee Boltbucket sie?",a="Wenikee Boltbucket will an einer aus dem Brachland geborgenen Samophlange tüfteln und sie reparieren. Ihr sind die Verbindungselemente der Stärke siebzehn Komma fünf ausgegangen, also schickt sie Abenteurer los, um weitere aus dem nahen Lager der Venture Company zu bergen.",al={"wer braucht schraubnieten","warum wenikee verbindungselemente will","samophlange reparatur"}},{q="Wird die Samophlange durch den Einsatz der Schraubnieten repariert?",a="Nein. Wenikee baut die geborgenen Verbindungselemente in die Samophlange ein und beginnt mit der Wartung. Dann explodiert sie direkt vor ihren Augen.",al={"funktioniert die maschine","samophlange explosion","wenikee reparaturergebnis"}}},fx={f3aea894={q="Woher kommen die Schraubnieten und wer stellt sie her?",a="Diese speziellen Schraubnieten der Stärke 17,5 sind Industrieteile, die von der Venture Company im Schlickermoor verwendet werden. Ihre Arbeiter und Ingenieure lagern sie in Werkzeugeimern, die rund um ihre Bohr- und Grabungsstellen im östlichen Brachland verstreut sind.",al={"woher kommen schraubnieten","wer stellt schraubnieten her","ursprung der schraubniete"}}},fp="11,185,38.263.0,30.327.1,22.174.0,29.131.0,38.228.0,48.115.1"}
P.entries["item:ogre-s-monocle"] = {n="Ogermonokel",s="Im südlichen Dämmerwald trägt Zzarc'Vul ein Monokel, das Viktori Prism'Antras für ein Teleskop benötigt. Seine Linse hat die passende Größe und Krümmung, um Licht durch das Instrument zur Sternbeobachtung in Dunkelhain zu bündeln.",h="Im südlichen Dämmerwald trägt Zzarc'Vul ein Monokel, das Viktori Prism'Antras für ein Teleskop benötigt.",kw={"cog","dunkelhain","look to the stars","ogermonokel","teleskop","viktori prism'antras","ogerhort vul'gol","zzarc'vul"},ang={["faction:Alliance"]="Die Beschaffung der Linse befreit die südlichen Wälder von einem gefährlichen Grobian und hilft Dunkelhains bedrängten Bürgern, Trost in den Sternen zu finden.",["profession:Engineering"]="Cogs Bauplan zeigt den typischen Ehrgeiz der Gnome: Wenn vor Ort keine präzise geschliffenen Linsen verfügbar sind, muss eine riesige Sehhilfe herhalten."},sec={{t="Eine ungewöhnliche Linse",b="Zzarc'Vul, ein Oger, trägt ein Monokel, das für seine gewaltige Statur gefertigt wurde. Als Viktori Prism'Antras aus Dunkelhain nach den Bauplänen des Gnomeningenieurs Cog ein Instrument zur Sternbeobachtung zu bauen begann, erwiesen sich gewöhnliche Linsen als zu klein. Zzarc'Vuls Sehhilfe ist das einzige geschliffene Glas in der Region mit der passenden Größe und Krümmung, um Licht durch das fertige Teleskop zu bündeln."},{t="Vul'Gol die Linse entreißen",b="Im Ogerhort Vul'Gol im südlichen Dämmerwald lebt Zzarc'Vul unter seinen brutalen Brüdern. Er zeigt wenig Neigung, sein unverwechselbares Zubehör herzugeben. Ihr müsst ihn auf seinem eigenen Gebiet besiegen, um die Linse zu erbeuten, und sie dann nach Dunkelhain zurückbringen, damit Viktori seinen Blick auf den Nachthimmel richten kann."}},faq={{q="Wer trägt das Ogermonokel?",a="Zzarc'Vul, ein Oger, trägt das Monokel im Ogerhort Vul'Gol im südlichen Dämmerwald.",al={"wer lässt das monokel fallen","wer hat das ogermonokel","zzarc'vul gegenstand"}},{q="Warum braucht Viktori Prism'Antras die Sehhilfe eines Ogers?",a="Viktori Prism'Antras benötigt eine ungewöhnlich große Linse für ein Teleskop, das nach den Bauplänen des Gnomen Cog gebaut wird. Zzarc'Vuls Monokel ist das einzige Stück Glas im Dämmerwald, das passt.",al={"warum wird das monokel gebraucht","wofür ist das monokel","teleskoplinse"}},{q="Wie kam ein Oger an ein riesiges Monokel?",a="Der Bericht erklärt nicht, wie Zzarc'Vul an das Monokel gelangte. Er besagt nur, dass er eines besitzt, das groß genug für Viktoris Teleskop ist.",al={"warum hat ein oger ein monokel","oger lesebrille hintergrundgeschichte"}},{q="Wo liegt der Ogerhort Vul'Gol?",a="Der Ogerhort Vul'Gol liegt in den südlichen Hügeln des Dämmerwalds, südlich der Hauptstraße zwischen Dunkelhain und der westlichen Grenze.",al={"wo ist vulgol","ogerhort dämmerwald"}}},fx={["94fbe42d"]={q="Was ist das Ogermonokel?",a="Das Ogermonokel ist eine überdimensionale optische Linse, die als Okular von Zzarc'Vul getragen wird, einem bedeutenden Oger, der im Ogerhort Vul'Gol im südlichen Dämmerwald lebt. Während solch feine optische Ausrüstung bei Ogern äußerst selten ist, macht sie ihre massive Glaslinse besonders geeignet für schwere optische Maschinen.",al={"was ist das ogermonokel","ogermonokel gegenstand","oger okular"}}},fp="14,186,14.351.0,22.286.0,31.87.0,54.175.0,36.131.0,40.127.0"}
P.entries["item:okra"] = {n="Okraschote",s="Auf Saldeans Farm helfen Okraschoten, Westfalls Siedler zu ernähren. Sie wachsen auf den Feldern der Farm und binden die Eintöpfe, die den Siedlern Kraft geben.",h="Auf Saldeans Farm helfen Okraschoten, Westfalls Siedler zu ernähren.",kw={"nutzpflanze","farm","okraschote","saldean","salma saldean","gemüse","westfall-eintopf"},ang={["faction:Alliance"]="Sturmwinds Adlige speisen importiertes Fleisch, während Siedler der Allianz im Grenzland zwischen Westfalls Ruinen widerstandsfähige Nutzpflanzen wie Okraschoten anbauen.",["profession:Cooking"]="Ein wandernder Koch weiß, dass ein guter Eintopf mehr als rohes Fleisch braucht. Okraschoten verleihen zäher Nahrung aus der Wildnis die Stärke und Fülle einer warmen Mahlzeit."},sec={{t="Ein Grundnahrungsmittel von Saldeans Farm",b="Saldeans Farm liefert noch immer Gemüse, während weite Teile Westfalls brachliegen, bedroht von Gesetzlosen der Defias und Angriffen abtrünniger Erntegolems. Okraschoten wachsen auf den bestellten Feldern rund um die Farm und trotzen den rauen Bedingungen. Sie ernähren die örtlichen Siedler, wenn der Handel und die Lieferungen aus Sturmwind versiegen."},{t="Westfall-Eintopf",b="Salma Saldeans berühmter Westfall-Eintopf kommt ohne Okraschoten nicht aus. Sie mischt die geschnittenen Schoten mit allem Fleisch, das Siedler in den staubigen Ebenen erjagen können, darunter Geierfleisch, Schnauzen von Goretusks und Augen von Küstenmurlocs. Die Schoten zerkochen in der Hitze und binden dünne Brühe zu einer sättigenden, stärkenden Mahlzeit. Für Siedler, die sich an ihre Gehöfte klammern, machen frische Okraschoten aus kärglich zusammengetragener Nahrung ein warmes Abendessen."}},faq={{q="Wo wachsen Okraschoten in Westfall?",a="Okraschoten wachsen auf den bestellten Feldern von Saldeans Farm an Westfalls zentraler Straße. Die grünen Pflanzen gedeihen in den Furchen nahe dem Gehöft von Bauer Saldean.",al={"okraschoten fundort","wo okraschoten finden","wo wachsen okraschoten"}},{q="Wofür werden Okraschoten verwendet?",a="Salma Saldean erntet auf Saldeans Farm Okraschoten für ihre Spezialität, den Westfall-Eintopf. Ihre natürliche Stärke bindet die Brühe und vereint Geierfleisch, Eberschnauzen und Murlocaugen zu einer herzhaften Mahlzeit.",al={"okraschoten verwendung","wofür sind okraschoten","warum brauche ich okraschoten"}},{q="Warum sind Okraschoten für die Saldeans wichtig?",a="Da der Handel gestört ist und das Königreich kaum Hilfe leistet, sind die Siedler auf das angewiesen, was sie anbauen und erjagen können. Okraschoten gehören zu den wenigen Nutzpflanzen, die auf Saldeans Farm noch angebaut werden, und helfen, die Familie und durchreisende Wanderer zu ernähren.",al={"saldean okraschoten","warum okraschoten wichtig sind"}}},fx={["301f0b5e"]={q="Was ist Okraschote?",a="Okraschote ist ein essbares Gemüse, das im gepflügten Boden von Westfall wächst. Die auf Bauernhöfen wie der Saldean-Farm kultivierten Schoten sind kräftig genug, um das schwierige Klima der Region zu überstehen, und bilden ein zuverlässiges Grundnahrungsmittel für die kämpfenden Siedler.",al={"was ist okraschote","okraschote gegenstand","okraschote pflanze"}},["5bbd3a8c"]={q="Woher kommt Okraschote?",a="Okraschote wird lokal auf den Farmen von Westfall angebaut, vor allem von Salma und Bauer Saldean auf der Saldean-Farm. Obwohl ein Großteil der Landschaft verfallen und verwahrlost ist, wachsen in den verbliebenen gepflügten Feldern weiterhin robuste Pflanzen wie die Okraschote.",al={"woher kommt okraschote","wer baut okraschote an","ursprung der okraschote"}},b45f6830={q="Warum möchte Salma Saldean Okraschote haben?",a="Salma Saldean benötigt frische Okraschote als wichtige Zutat für ihren berühmten Westfall-Eintopf. Wenn das Gemüse zusammen mit Wild und lokalem Fleisch geschnitten und gedünstet wird, hilft es, die herzhafte Brühe einzudicken und bietet eine reichhaltige, sättigende Mahlzeit, um die Menschen der Ebenen zu ernähren.",al={"warum wird okraschote benötigt","warum will salma okraschote","wer möchte okraschote"}}},fp="4,136,26.306.0,13.393.0,33.147.0,22.188.0,38.219.0"}
P.entries["item:ordanus-head"] = {n="Ordanus' Kopf",s="Bei Rajenbaum wird Ordanus' Kopf als Beweis gesucht, dass Hüter Ordanus gefallen ist. Braelyn Feuerhand, eine Blutelfenmagierin, sucht ihn im Eschental.",h="Bei Rajenbaum wird Ordanus' Kopf als Beweis gesucht, dass Hüter Ordanus gefallen ist.",kw={"eschental","braelyn feuerhand","cenarius","hüter des hains","ordanus","ordanus' kopf","rajenbaum","steinkrallengebirge","sunrock retreat"},ang={["class:Druid"]="Als Druide führt Euch das Tragen des abgetrennten Kopfes eines älteren Sohnes von Cenarius deutlich vor Augen, welchen bitteren Hass arkane Zauberer noch immer gegen die Beschützer der Wildnis hegen.",["faction:Horde"]="Als Mitglied der Horde helft Ihr durch Ordanus' Tod und die Übergabe seines Kopfes an Braelyn, den Einfluss der Horde entlang der umkämpften Grenzen des Steinkrallengebirges und des Eschentals zu festigen. Das schwächt die örtliche Führung der Nachtelfen."},sec={{t="Ein alter Groll",b="Hüter Ordanus war ein uralter Hüter des Hains und einer der älteren Söhne von Cenarius. Seine Druiden unterdrückten die Magie auf dem Gipfel des Steinkrallengebirges, und Braelyn Feuerhand bestieg diese Höhen im Auftrag ihres Meisters. Sie wollte ihre Herrschaft beenden und Rache an Ordanus nehmen. Bevor sie zuschlagen konnte, wurde der Hüter ins Herz des Eschentals fortgebracht.\n\nBraelyn spähte mithilfe arkaner Wahrnehmung durch das Blätterdach des Waldes und fand Ordanus' Heiligtum in den Zweigen von Rajenbaum. Dort forderte sie seinen abgetrennten Kopf als Beweis dafür, dass die Arroganz des wilden Halbgottes gesühnt worden war."},{t="Der Preis des Hochmuts",b="Braelyn Feuerhand kannte Ordanus vor langer Zeit und hegt einen alten Groll gegen ihn. Sie hasst auch die Druiden, die die Magie unterdrücken wollen. Zu Lebzeiten hielt sich Ordanus selbst dem uralten Adel der Hochgeborenen für überlegen.\n\nIndem Braelyn seinen Kopf nimmt, schlägt sie gegen das Vermächtnis von Cenarius zurück. Sie erklärt, dass kein Wächter der Wildnis die Rückkehr roher magischer Macht aufhalten kann."}},faq={{q="Wer war Hüter Ordanus?",a="Hüter Ordanus war ein uralter Hüter des Hains und einer der älteren Söhne von Cenarius. Vor langer Zeit geriet er mit arkanen Magiewirkern unter dem nachtelfischen Adel aneinander und begegnete allen, die arkane Künste ausübten, mit großer Arroganz.",al={"wer ist ordanus","ordanus geschichte","was ist ordanus"}},{q="Wo wird dieser Kopf erbeutet?",a="Ordanus' Kopf wird Hüter Ordanus auf der erhöhten Holzplattform bei Rajenbaum abgenommen, einer befestigten Enklave der Nachtelfen im Blätterdach des zentralen Eschentals.",al={"wo ordanus' kopf finden","ordanus aufenthaltsort","rajenbaum ordanus"}},{q="Warum will Braelyn Feuerhand seinen Kopf?",a="Braelyn Feuerhand kannte Ordanus vor langer Zeit und verabscheute seine Arroganz. Er hielt sich selbst den Hochgeborenen für überlegen. Sie hasst auch die Druiden und die Söhne von Cenarius, weil sie den Fluss der Magie aufhalten wollen und Ordanus vom Gipfel fortbrachten, bevor sie ihn erreichen konnte.",al={"warum braelyn ordanus' kopf will","braelyns groll","warum ordanus töten"}},{q="Was geschieht nach der Übergabe des Kopfes?",a="Die Übergabe von Ordanus' Kopf an Braelyn in Sunrock Retreat begleicht ihre Blutschuld. Sie belohnt den Söldner mit der mächtigen Gabe, die sie versprochen hat.",al={"ordanus' kopf abgeben","nach ordanus' tod","braelyn feuerhand questbelohnung"}}},fx={e1459048={q="Woher stammt Ordanus' Kopf?",a="Diese grimmige Trophäe stammt direkt von Hüter Ordanus, einem der ältesten Söhne des Halbgottes des Waldes Cenarius. Obwohl man ihn einst auf dem Steinkrallengipfel in Sicherheit wähnte, floh Ordanus in das Eschental und suchte Zuflucht hoch oben im Rajenbaum, bevor er zur Strecke gebracht wurde.",al={"ursprung von ordanus' kopf","woher stammt ordanus' kopf","wem gehört ordanus' kopf"}}},fp="13,146,22.579.0,19.368.1,23.225.0,29.161.0,40.265.0,41.141.1"}
P.entries["item:orendil-s-cure"] = {n="Orendils Heilmittel",s="Im nördlichen Eschental braut Orendil Rundblatt einen Trank für ein krankes Kind in Astranaar. Seltenes Bathranshaar gibt Pelturas Weißmond Hoffnung für seine Tochter Relara.",h="Im nördlichen Eschental braut Orendil Rundblatt einen Trank für ein krankes Kind in Astranaar.",kw={"eschental","astranaar","bathranshaar","orendil rundblatt","orendils heilmittel","pelturas weißmond","relara"},ang={["profession:Herbalism"]="Die einheimischen Pflanzen des Eschentals besitzen große Heilkraft. Bathranshaar ist ein solches Kraut und wächst nur in bestimmten, schattigen Winkeln des Waldes.",["race:NightElf"]="Für die Nachtelfen in Astranaar ist Relaras Rettung eine dringende Angelegenheit der Gemeinschaft. Einsiedler wie Orendil bringen ihr Wissen über den Wald ein, während der Glaube an Elune göttlichen Beistand bringt."},sec={{t="Die Hoffnung eines Vaters",b="Relara Whitemoon wurde schon in jungen Jahren todkrank, und gewöhnliche Heilmittel halfen ihr in Astranaar nicht. Ihr Vater, Pelturas Weißmond, suchte Hilfe bei Orendil Rundblatt, einem Einsiedler, der im nördlichen Eschental lebt und die Naturheilkunde beherrscht.\n\nOrendil sammelte Bündel des seltenen Bathranshaars in den heimgesuchten Ruinen von Bathrans Schlupfwinkel und braute einen Trank für Relara. Als die Phiole eintrifft, schöpft Pelturas Hoffnung. Doch das Heilmittel verlangsamt die Krankheit nur, weshalb er nach den weiteren Heilmitteln suchen muss, die Orendil vorgeschlagen hat."}},faq={{q="Wofür wird Orendils Heilmittel verwendet?",a="Orendils Heilmittel soll die Beschwerden von Relara Whitemoon lindern, einem jungen Nachtelfenkind in Astranaar. Ihre plötzliche und schwere Erkrankung hat sie schwer gezeichnet.",al={"orendils heilmittel zweck","was bewirkt das heilmittel","für wen ist das heilmittel"}},{q="Wer hat das Heilmittel hergestellt?",a="Orendil Rundblatt hat das Heilmittel zubereitet. Er ist ein zurückgezogen lebender Nachtelf und Kräuterkundiger in den nördlichen Wäldern des Eschentals, bekannt für sein meisterhaftes Wissen über Waldpflanzen und Heilmittel.",al={"wer hat orendils heilmittel hergestellt","hersteller von orendils heilmittel"}},{q="Welche Zutaten wurden zur Herstellung verwendet?",a="Das Heilmittel enthält Bathranshaar, eine zarte und seltene Pflanze, die in den Ruinen von Bathrans Schlupfwinkel im nördlichen Eschental gesammelt wird.",al={"zutaten des heilmittels","was ist in orendils heilmittel"}},{q="Heilt dieser Trank das Kind vollständig?",a="Nein. Pelturas erfährt, dass Orendils Heilmittel die Krankheit seiner Tochter nur verlangsamt. Deshalb sucht er nach dem stärkeren Heilmittel, das Orendil vorgeschlagen hat: Elunes Träne.",al={"hat es relara geheilt","ist relara geheilt"}}},fx={["8e86537e"]={q="Was ist Orendils Heilmittel?",a="Orendils Heilmittel ist ein medizinischer Trank, der von dem Kräuterkundigen Orendil Rundblatt im nördlichen Eschental gebraut wird. Es wurde als spezielle Behandlung für ein plötzliches, schweres Leiden entwickelt und stellt einen dringenden Versuch dar, das Leben eines jungen Nachtelfenkindes zu retten, das an einer rätselhaften Krankheit leidet.",al={"lore über orendils heilmittel","was ist orendils heilmittel","orendils arznei"}},["6add91d1"]={q="Warum wird Orendils Heilmittel benötigt?",a="In Astranaar liegt die kleine Tochter von Pelturas Weißmond, Relara, todkrank darnieder. Verzweifelt auf der Suche nach einem Heilmittel, als herkömmliche Behandlungen wirkungslos blieben, suchte ihr Vater die Expertise von Orendil Rundblatt. Der Kräuterkundige bereitete diese spezielle Mischung in der Hoffnung zu, das Kind zu stabilisieren, bevor die Krankheit ihr das Leben nimmt.",al={"warum wird orendils heilmittel benötigt","wer braucht orendils heilmittel","warum orendils heilmittel liefern"}}},fp="14,163,15.497.0,32.142.0,21.161.0,38.126.0,43.152.1"}
P.entries["item:oslow-s-toolbox"] = {n="Oslows Werkzeugkasten",s="Oslows Werkzeuge liegen auf dem Grund des Immerruhsees, wo Schwarzfelsorcs das Boot mit der Ladung aus Goldhain versenkten.",h="Oslows Werkzeuge liegen auf dem Grund des Immerruhsees, wo Schwarzfelsorcs das Boot mit der Ladung aus...",kw={"großknecht oslow","der immerruhsee","seenhain","oslow","rotkammgebirge","versunkene kiste","the lost tools","werkzeugkasten"},ang={["faction:Alliance"]="Seenhain ist unter der Belagerung durch die Schwarzfelsorcs nahezu abgeschnitten. Oslows Vorräte zu bergen ist entscheidend, um die Verteidigungsanlagen der Stadt instand zu halten."},sec={{t="Eine verhängnisvolle Überfahrt",b="Großknecht Oslow braucht Bauwerkzeuge, um Seenhains Verteidigungsanlagen und Gebäude instand zu halten. Schwarzfelsorcs belagern das Rotkammgebirge, und die Brücke in die Stadt liegt in Trümmern. Deshalb überquerte die Lieferung aus Goldhain den Immerruhsee in einem Ruderboot.\n\nTruppen der Schwarzfelsorcs trafen das Boot mit einem Katapult. Das Boot und Oslows schwere Kiste versanken zwischen den Murlocs in der Tiefe."}},faq={{q="Warum liegt Oslows Werkzeugkasten auf dem Grund des Sees?",a="Die Werkzeuge wurden von Goldhain nach Seenhain gebracht. Da die Brücke zerstört war, überquerten sie den Immerruhsee in einem Boot. Schwarzfelsorcs trafen das Ruderboot mit einem Katapult und versenkten den Werkzeugkasten auf dem Seegrund.",al={"warum ist der werkzeugkasten im wasser","wie hat oslow seine werkzeuge verloren","geschichte des versunkenen werkzeugkastens"}},{q="Wem gehört dieser Werkzeugkasten?",a="Großknecht Oslow besitzt den Werkzeugkasten und beaufsichtigt Bauarbeiten und Reparaturen in Seenhain. Ohne geeignete Ausrüstung ist es nahezu unmöglich, die Befestigungen der Stadt angesichts anhaltender Angriffe instand zu halten.",al={"wer ist oslow","oslow besitzer","großknecht oslow werkzeuge"}},{q="Wo im Immerruhsee sind die Werkzeuge gesunken?",a="Die Werkzeuge ruhen in einer versunkenen Kiste nahe dem Wrack des Ruderboots im Immerruhsee. Die Kiste liegt zwischen Felsblöcken unter Wasser, südlich eines markanten Murloclagers am Ufer.",al={"werkzeugkasten fundort","wo ist die versunkene kiste","wo ist das boot gesunken"}},{q="Welche Gefahren bewachen die versunkene Kiste?",a="Feindselige Murlocs und räuberische Wasserbestien bevölkern die Gewässer um das Wrack. Gefährliche Lake Threshers durchstreifen die tieferen Bereiche des Sees.",al={"gefahren beim werkzeugkasten","immerruhsee feinde","was bewacht oslows werkzeuge"}}},fx={["543d5407"]={q="Warum muss Großknecht Oslow seinen Werkzeugkasten zurückerhalten?",a="Seenhain wird schwer belagert, wodurch die Stadt abgeschnitten ist und ein dringender Mangel an lebenswichtigen Vorräten herrscht. Als Großknecht der Stadt benötigt Oslow seine Ausrüstung, um die Gebäude und Verteidigungsanlagen von Seenhain instand zu halten und zu reparieren. Da der Lieferwagen aus Goldhain die zerstörte Brücke nicht überqueren konnte, hat der Verlust der Ersatzwerkzeuge im See die kritischen Bauarbeiten zum Stillstand gebracht, weshalb ihre Bergung für das Überleben der Stadt entscheidend ist.",al={"warum will oslow den werkzeugkasten","warum braucht oslow seine werkzeuge","warum oslows werkzeugkasten bergen"}}},fp="15,106,18.372.0,49.208.0,22.198.0,43.173.0,36.144.0"}
P.entries["item:osric-s-crate"] = {n="Osrics Kiste",s="Auf der Späherkuppe bringt Osrics Kiste der Volksmiliz neue Rüstungen aus Sturmwind. Die Verteidiger stellen sich der Bruderschaft der Defias und marodierenden Gnollen ohne die Armee von Sturmwind.",h="Auf der Späherkuppe bringt Osrics Kiste der Volksmiliz neue Rüstungen aus Sturmwind.",kw={"dungar longdrink","greif","osric","osrics kiste","volksmiliz","rüstmeister lewis","späherkuppe","westfall"},ang={["faction:Alliance"]="Für die Allianz hilft jede Lieferung von Waffen und Rüstungen, die die Späherkuppe erreicht, die Westgrenzen des Königreichs vor der Bruderschaft der Defias zu bewahren."},sec={{t="Nachschub für die Front",b="Rüstmeister Lewis nimmt die Lieferung entgegen und verteilt die Schutzausrüstung unter den freiwilligen Kämpfern. Die Krone gewährt der Volksmiliz keine offizielle Unterstützung. Diese frisch gefertigten Rüstungen sollen den Freiwilligen helfen, ihre Stellung zu halten."},{t="Geflügeltes Kuriernetz",b="Von Dungar Longdrinks Greifenhorst im Handelsdistrikt von Sturmwind trägt ein Greif die Kiste zu Thor auf der Späherkuppe. Der Flug umgeht gefährliche Straßen durch den Wald von Elwynn und über die Grenze nach Westfall, wo Banditen Reisenden auflauern können. Greifen helfen dabei, Grenzgarnisonen in Kriegszeiten mit Nachschub zu versorgen."}},faq={{q="Was befindet sich in Osrics Kiste?",a="Osrics Kiste enthält schützende Rüstungen, die in Sturmwind gefertigt wurden. Rüstmeister Lewis nimmt die Lieferung entgegen und bereitet ihre Verteilung unter den Kämpfern vor, die die Späherkuppe verteidigen.",al={"was ist in der kiste","inhalt von osrics kiste","osrics kiste inhalt"}},{q="Wer ist Osric?",a="Osric ist ein Rüstungsschmied in Sturmwind, der die Lieferung für die Volksmiliz vorbereitet hat, die Westfall hält.",al={"wer ist osric","wer hat osrics kiste geschickt"}},{q="Wer erhält die Kiste?",a="Rüstmeister Lewis nimmt die Kiste entgegen. Er verwaltet Nachschub und Ausrüstung für die Volksmiliz auf der Späherkuppe in Westfall.",al={"wohin geht die kiste","wem osrics kiste übergeben","empfänger der kiste"}},{q="Warum wird die Kiste per Greif geliefert?",a="Banditen und Gesetzlose machen die Straßen durch Sturmwind, den Wald von Elwynn und Westfall gefährlich. Ein Greif trägt die Rüstungen schnell und sicher von Dungar Longdrink in Sturmwind zu Thor auf der Späherkuppe.",al={"warum die kiste fliegen","warum greifen nutzen","osrics kiste flug"}}},fx={["34d354cb"]={q="Was ist Osrics Kiste?",a="Osrics Kiste ist eine Rüstungslieferung, die aus Sturmwind verschickt wurde. Sie ist für die Verteidiger auf der Späherkuppe in Westfall bestimmt, denen es verzweifelt an Ausrüstung mangelt, während sie gegen The Defias Brotherhood ausharren.",al={"was ist osrics kiste","osrics kiste gegenstand","was ist in osrics kiste"}},["091b5cbb"]={q="Woher kommt Osrics Kiste und wer hat sie hergestellt?",a="Die Kiste stammt aus Sturmwind, vorbereitet und verschickt von Osric, um The People's Militia zu versorgen. Greifenmeister Dungar Longdrink vertraut sie Euch an, damit Ihr sie per Greifen durch das Königreich nach Westfall befördert.",al={"wer hat osrics kiste hergestellt","woher stammt osrics kiste","ursprung von osrics kiste"}},["11fb3015"]={q="Warum möchte jemand Osrics Kiste haben?",a="Rüstmeister Lewis und The People's Militia auf der Späherkuppe benötigen die Rüstung im Inneren dringend. Da Westfall von den königlichen Truppen aufgegeben wurde und von Gesetzlosen überrannt ist, ist jedes Stück Schutzausrüstung lebenswichtig, um die Verteidiger am Leben zu halten.",al={"warum osrics kiste ausliefern","warum will lewis osrics kiste","zweck von osrics kiste"}}},fp="13,181,22.237.0,22.301.0,29.174.0,13.101.0,23.128.0,38.199.0"}
P.entries["item:package-of-empty-ooze-containers"] = {n="Kiste mit leeren Schlammbehältern",s="In Eisenschmiede steht eine Kiste mit leeren Schlammbehältern für gefährliche Probennahmen im Teufelswald bereit. Laris Bummelritzel liefert Gläser, die verdorbenen und verfluchten Schlamm aufnehmen können, ohne sich aufzulösen.",h="In Eisenschmiede steht eine Kiste mit leeren Schlammbehältern für gefährliche Probennahmen im Teufelswald...",kw={"behälter","verflucht","teufelswald","eisenschmiede","gläser","laris bummelritzel","schlamm","kiste","schleim","verdorben"},ang={["faction:Alliance"]="Als Mitglied der Allianz helft Ihr durch das Sammeln dieser Proben, mit der beunruhigenden Forschung der Königlichen Apothekervereinigung der Verlassenen Schritt zu halten.",["race:Gnome"]="Dem Gnom Laris Bummelritzel bietet seine Schlammforschung die Gelegenheit, den Zwergen von Eisenschmiede zu zeigen, dass die Aufnahme gnomischer Flüchtlinge die Mühe wert war."},sec={{t="Forscherausrüstung für den Feldeinsatz",b="Laris Bummelritzel schickt Reisenden, die in den Teufelswald aufbrechen, ein Dutzend leere Gläser mit. Sechs sind für verfluchten Schlamm und sechs für verdorbenen Schlamm bestimmt. Rohe Proben sind ätzend und können gewöhnliches Gepäck zerfressen. Stabiles, versiegeltes Glas hält die säurehaltigen Rückstände auf der Reise über Kontinente hinweg zu Laris' Werkbank in Eisenschmiede sicher eingeschlossen."},{t="Das Geheimnis des Schlamms",b="Laris Bummelritzels Interesse an Schlamm geht über ein schrulliges Hobby hinaus. Er hat gesehen, wie Forscher der Verlassenen von der Königlichen Apothekervereinigung diese seltsamen Organismen in ganz Azeroth sammeln, und fragt sich, was sie wissen. Er vermutet, dass Schleime urzeitliche Sekrete sein könnten, die mit der Entstehung der Welt verbunden sind. Feldagenten sammeln in seinen Gläsern Beweise, die ihm hoffentlich Anerkennung in der Forscherliga einbringen werden."}},faq={{q="Was befindet sich in der Kiste mit leeren Schlammbehältern?",a="Die Kiste enthält zwölf leere Probengläser: sechs für verfluchten Schlamm und sechs für verdorbenen Schlamm.",al={"kisteninhalt","was enthält die kiste","schlammgläser in der kiste"}},{q="Wer stellt diese Kiste bereit?",a="Laris Bummelritzel, ein gnomischer Gelehrter und Forscher in Eisenschmiede, stellt die Kiste Abenteurern der Allianz bereit.",al={"wer gibt die gläser","laris bummelritzel questgegenstand","wo gibt es die schlammkiste"}},{q="Wo sollen diese Behälter verwendet werden?",a="Die Behälter sind für den Teufelswald bestimmt. Dort besiegen Abenteurer verdorbene und verfluchte Brühschlammer und sammeln anschließend Rückstände von den gefallenen Kreaturen.",al={"wo schlammgläser verwenden","welches gebiet für brühschlammer","schlammglas fundort"}},{q="Warum will Laris Bummelritzel diese Schlammproben?",a="Laris hat gesehen, wie die Königliche Apothekervereinigung der Verlassenen auf der ganzen Welt Schlamm sammelt, und will dessen Geheimnisse ergründen. Er vermutet, dass Schleime urzeitliche Sekrete sein könnten, die mit Azeroths Entstehung verbunden sind, und hofft, durch Beweise Ansehen in der Forscherliga zu gewinnen.",al={"warum schleim sammeln","bummelritzels forschung","warum will laris schlamm"}}},fx={d8bf9111={q="Was ist die Kiste mit leeren Schlammbehältern?",a="Es handelt sich um ein Feldset, das von dem Gnom-Forscher Laris Bummelritzel in Eisenschmiede zusammengestellt wurde. Das Paket enthält eine Reihe speziell vorbereiteter Gläser, die dazu dienen, Proben zu sammeln und sicher aufzubewahren, die von den korrupten Schlämmen und Schleimen im Teufelswald geerntet wurden.",al={"was ist die kiste mit leeren schlammbehältern","paket mit schlammbehältern","bündel leerer schlammbehälter"}}},fp="32,181,24.324.0,23.402.0,52.91.0,26.110.0,44.137.0,50.260.0"}
P.entries["item:painted-gnoll-armband"] = {n="Bemalte Gnollarmbinde",s="In der Weststromgarnison beweisen Bemalte Gnollarmbinden, dass Gnolle der Riverpaw erschlagen wurden. Ihre Rudel bedrängen die Westgrenze des Walds von Elwynn.",h="In der Weststromgarnison beweisen Bemalte Gnollarmbinden, dass Gnolle der Riverpaw erschlagen wurden.",kw={"kopfgeld","stellvertreter rainer","wald von elwynn","gnolle","bemalte gnollarmbinde","riverpaw","der steinhügelsee","weststromgarnison"},ang={["faction:Alliance"]="Als Abenteurer der Allianz helft Ihr durch das Sammeln dieser Armbinden der Weststromgarnison, Sturmwinds Westgrenze zu halten, während die stehende Armee der Stadt andernorts eingesetzt wird."},sec={{t="Trophäen der Riverpaw",b="Krieger und Aasfresser der Riverpaw tragen grobe Binden mit einfachen Stammesmustern. Diese Armbinden stammen von Gnollen der Riverpaw entlang der Wildnisgrenzen des Walds von Elwynn. Die Verteidiger von Sturmwind stehen nahe dem Steinhügelsee und in den Wäldern südlich der Weststromgarnison einer wachsenden Bedrohung gegenüber."},{t="Kopfgeld der Weststromgarnison",b="Die Armee von Sturmwind ist über das ganze Königreich verstreut, weshalb die Weststromgarnison die Westgrenze nur mit Mühe bewachen kann. Stellvertreter Rainer bietet ein ständiges Kopfgeld für das Erschlagen von Riverpaw Outrunners und Riverpaw Runts. Mit den bemalten Binden können die Stellvertreter Kopfgelder abrechnen und die Rudel im Umkreis der nahen Felder ausdünnen."}},faq={{q="Warum will die Weststromgarnison diese Armbinden?",a="Stellvertreter Rainer in der Weststromgarnison sammelt die Armbinden als Beweis dafür, dass Gnolle der Riverpaw erschlagen wurden. Die Garnisonstruppen können die vordringenden Rudel nicht allein bewältigen, deshalb zahlt Sturmwind Kopfgelder an jene, die diese Trophäen zurückbringen.",al={"warum armbinden","wer will bemalte gnollarmbinden","stellvertreter rainer kopfgeld"}},{q="Welche Gnolle tragen diese bemalten Armbinden?",a="Gnolle der Riverpaw tragen die bemalten Armbinden. Riverpaw Outrunners und Riverpaw Runts machen die Wälder südlich der Weststromgarnison und die Ufer rund um den Steinhügelsee unsicher.",al={"wo werden armbinden erbeutet","wer hinterlässt bemalte gnollarmbinde","welche gnolle haben armbinden"}},{q="Warum sind Gnolle der Riverpaw im Wald von Elwynn?",a="Rudel der Riverpaw sind entlang der Grenzen des Walds von Elwynn nach Osten vorgedrungen und haben nahe dem Steinhügelsee und an den Waldrändern Lager errichtet. Da die Truppenpräsenz des Königreichs geschwächt ist, jagen sie, suchen nach Verwertbarem und bedrohen nahe gelegene Siedlungen.",al={"warum sind gnolle hier","gnollinvasion elwynn","riverpaw elwynn"}},{q="Welche Bedeutung hat die Bemalung der Armbinden?",a="Die Bemalung kennzeichnet Trophäen von Gnollen der Riverpaw und hilft, Stellvertreter Rainer die Tötungen nachzuweisen. Für die Muster sind weder Rang noch Bedeutung angegeben.",al={"warum sind sie bemalt","gnollarmbinde muster"}}},fx={["586b453e"]={q="Was ist eine Bemalte Gnollarmbinde?",a="Eine Bemalte Gnollarmbinde ist ein einfacher persönlicher Schmuck, der von Riverpaw-Gnollen getragen wird. Diese Armbinden werden von der Meute gefertigt und bemalt und markieren ihre Präsenz in den Grenzgebieten des Waldes von Elwynn. Für die Armee von Sturmwind dienen sie als unbestreitbarer physischer Beweis dafür, dass ein marodierender Gnoll getötet wurde.",al={"was ist die bemalte gnollarmbinde","lore der bemalten gnollarmbinde","gnollarmbinde"}}},fp="21,142,22.279.0,29.306.0,48.226.0,41.166.0,41.226.0,54.140.0"}
P.entries["item:panther-cage-key"] = {n="Pantherkäfigschlüssel",s="Am Weißgipfelposten bewacht Wizlo Lagerputzer den Pantherkäfigschlüssel. Er öffnet den Käfig zwischen den zerstörten Wagen einer überfallenen Karawane in Tausend Nadeln.",h="Am Weißgipfelposten bewacht Wizlo Lagerputzer den Pantherkäfigschlüssel.",kw={"zentauren","hyperkondensator-dingsda","pantherkäfigschlüssel","tausend nadeln","weißgipfelposten","wizlo lagerputzer"},ang={["faction:Horde"]="Wizlo zu helfen, kann die Straßen rund um den Weißgipfelposten in Tausend Nadeln nach den Zentaurenüberfällen sicherer machen.",["profession:Engineering"]="Der Schlüssel öffnet einen Käfig, in dem sich der instabile Prototyp eines Tüftlers befindet. Wizlo hat seine empfindliche Erfindung an einem gefährlichen Ort zurückgelassen."},sec={{t="Ein heikles Schloss",b="Wizlo Lagerputzer ist ein Goblintüftler, der einem Zentaurenangriff auf seine Karawane nördlich des Weißgipfelpostens nur knapp entkam. Die Räuber durchwühlten die Wagen und die Fracht, ließen jedoch einen stabilen Käfig unberührt. Darin wartet ein seltener, wilder Panther. Um seinen Hals hängt Wizlos geschätzte Erfindung, ein Hyperkondensator-Dingsda. Die knurrende Bestie hielt die Zentauren auf Abstand, und nur mit Wizlos Schlüssel lässt sich der Käfig öffnen und das Gerät bergen."}},faq={{q="Wer stellt den Pantherkäfigschlüssel bereit?",a="Wizlo Lagerputzer, ein Goblintüftler, der am Weißgipfelposten im Nordwesten von Tausend Nadeln rastet, stellt den Schlüssel bereit.",al={"wer gibt den pantherschlüssel","wo gibt es den pantherkäfigschlüssel","herkunft des pantherkäfigschlüssels"}},{q="Was öffnet der Schlüssel?",a="Der Schlüssel öffnet einen Eisenkäfig zwischen den zerbrochenen Wagen einer zerstörten Karawane gleich nördlich des Weißgipfelpostens. Darin befindet sich ein wütender, gefährlicher Panther.",al={"was öffnet der pantherschlüssel","standort des pantherkäfigs","wo ist der käfig"}},{q="Warum haben die Zentauren den Käfig nicht geplündert?",a="Die Zentauren durchwühlten den Rest der Karawane, ließen den Käfig aber in Ruhe. Der gefangene Panther war zu wild und bedrohlich, um sich ihm zu nähern.",al={"warum ließen die zentauren den panther zurück","zentauren haben angst vor dem panther"}},{q="Was befindet sich außer der Bestie im Käfig?",a="Wizlos geschätzter Hyperkondensator-Dingsda hängt um den Hals des Panthers. Um ihn zu bergen, muss jemand den Käfig aufschließen und sich dem Raubtier stellen.",al={"warum den käfig öffnen","was trägt der panther"}}},fx={b335554a={q="Warum möchte Wizlo Lagerputzer den Pantherkäfigschlüssel zurückhaben?",a="Wizlo Lagerputzer vertraut Euch den Schlüssel nur an, damit Ihr den Käfig an seinem zerstörten Karawanenwagen öffnen und den wilden Panther darin erlegen könnt. Die Bestie trägt sein kostbares Hyperkondensator-Dingsda um den Hals. Er möchte, dass der Schlüssel zusammen mit seiner Erfindung zurückgegeben wird, sobald die Tat vollbracht ist, um sicherzustellen, dass die Überreste des Karawanenwagens und sein gefährliches Eigentum vollständig erfasst sind.",al={"warum pantherkäfigschlüssel","warum braucht wizlo den schlüssel","warum wird der pantherkäfigschlüssel benötigt"}}},fp="16,160,17.423.0,34.115.0,25.142.0,37.137.0,42.139.0"}
P.entries["item:parker-s-lunch"] = {n="Parkers Mittagessen",s="In Seenhain packt Darcy Parkers Mittagessen für Wache Parkers Patrouille ein. Die Mahlzeit gewährt einen Einblick in die Bande und bescheidenen Annehmlichkeiten unter den Verteidigern des Rotkammgebirges.",h="In Seenhain packt Darcy Parkers Mittagessen für Wache Parkers Patrouille ein.",kw={"a free lunch","darcy","wache parker","seenhain","parkers mittagessen","rotkammgebirge"},ang={["faction:Alliance"]="Da Verstärkung aus der Hauptstadt auf sich warten lässt, unterstützen die Stadtbewohner und die wenigen verbliebenen Wachen einander, um das Leben in Seenhain aufrechtzuerhalten.",["profession:Cooking"]="Für Wachen an der Grenze ist eine warme, eingepackte Mahlzeit ein Trost während langer Stunden in der Wildnis zwischen feindseligen Bestien."},sec={{t="Eine Mahlzeit für unterwegs",b="Darcy arbeitet als Kellnerin im Gasthaus von Seenhain, wo sie eine Mahlzeit für Wache Parker einpackt. Er patrouilliert auf der ungeschützten Straße nach Süden in Richtung Dämmerwald, während das Rotkammgebirge Angriffen von Gnollen und Schwarzfelsorcs ausgesetzt ist. Die Garnison ist überlastet und von der Hilfe aus Sturmwind abgeschnitten, sodass ihre Wachen lange, einsame Wachdienste leisten. Darcys kleine Geste gibt Parker zu essen und lässt eine schüchterne Liebelei zwischen ihnen aufkeimen."}},faq={{q="Wer hat Parkers Mittagessen zubereitet?",a="Darcy, eine Kellnerin im Gasthaus von Seenhain, bereitet Parkers Mittagessen für Wache Parker zu, während er auf Patrouille ist. Ein Reisender bringt ihm die Mahlzeit.",al={"wer hat parkers mittagessen zubereitet","wer hat mir parkers mittagessen gegeben","darcy rotkammgebirge mittagessen"}},{q="Wo ist Wache Parker zu finden?",a="Wache Parker patrouilliert auf der unbefestigten Hauptstraße, die von Seenhain nach Südwesten zur Grenze des Dämmerwalds führt. Er marschiert auf und ab und hält nach umherstreifenden Gnollen Ausschau.",al={"wache parker standort","wo ist wache parker","wache parker finden"}},{q="Was tut Wache Parker, nachdem er sein Mittagessen erhalten hat?",a="Parker ist von Darcys Aufmerksamkeit gerührt und sucht nach einer Möglichkeit, ihre Freundlichkeit zu erwidern. Er lässt ihr frische Narzissen vom Kräuterkundigen schicken.",al={"parkers mittagessen fortsetzung","darcy und parker","parkers reaktion auf das mittagessen"}},{q="Warum bringt Darcy das Mittagessen nicht selbst?",a="Gnolle und Blackrock-Invasoren bedrohen die Straßen außerhalb von Seenhain. Darcy ist eine gewöhnliche Stadtbewohnerin, während Parker die Ausbildung und Rüstung besitzt, um dort zu patrouillieren.",al={"warum kann darcy es nicht bringen","warum mittagessen im rotkammgebirge ausliefern"}}},fx={["2351e721"]={q="Was ist Parkers Mittagessen?",a="Parkers Mittagessen ist eine verpackte Mahlzeit, die von Darcy, der Gehilfin eines Gastwirts in Seenhain, zubereitet wurde. Sie hat es speziell für Wache Parker gepackt, der lange, anstrengende Stunden damit verbringt, die tückischen Straßen südlich der Stadt in Richtung Dämmerwald zu patrouillieren.",al={"was ist parkers mittagessen","gegenstand parkers mittagessen"}},b73a829b={q="Warum muss Parkers Mittagessen ausgeliefert werden?",a="Wache Parker ist weit außerhalb der relativen Sicherheit von Seenhain stationiert und hält entlang der Grenzstraße Ausschau nach umherstreifenden Gnollen und Schwarzfelsorcs. Da er seinen Posten nicht verlassen kann, um zum Gasthaus zurückzukehren, ist er auf die Freundlichkeit der Stadtbewohner wie Darcy – und vorbeiziehender Reisender – angewiesen, um während des Dienstes versorgt zu werden.",al={"warum parkers mittagessen liefern","warum will parker sein mittagessen","warum braucht wache parker sein mittagessen"}}},fp="14,154,19.382.0,28.143.0,32.148.0,52.147.1,44.158.0"}
P.entries["item:partially-filled-vessel"] = {n="Teilweise gefülltes Gefäß",s="In Aldrassil gibt Tenaron Sturmgewalt jungen Nachtelfen-Initianden das Teilweise gefüllte Gefäß. Es trägt gesegnetes Mondbrunnenwasser aus Laubschattental in Richtung Dolanaar.",h="In Aldrassil gibt Tenaron Sturmgewalt jungen Nachtelfen-Initianden das Teilweise gefüllte Gefäß.",kw={"aldrassil","corithras mondzorn","crown of the earth","dolanaar","mondbrunnen","teilweise gefülltes gefäß","laubschattental","tenaron sturmgewalt","gefäß"},ang={["class:Druid"]="Als Druide tragt Ihr geweihtes Wasser im Dienst der Bemühungen des Zirkels des Cenarius, den Weltbaum zu nähren und seine Gesundheit zu prüfen.",["race:NightElf"]="Als junger Nachtelf führt Euch das Tragen dieses Gefäßes aus der Zuflucht von Laubschattental zu den umfassenderen Aufgaben bei der Pflege Teldrassils."},sec={{t="Eine heilige Lieferung",b="Junge Initianden der Kaldorei sammeln gesegnetes Wasser aus dem abgelegenen Mondbrunnen von Laubschattental. In Aldrassil gießt Tenaron Sturmgewalt eine Probe in das Gefäß für dessen Reise durch Teldrassil. Weiteres Wasser aus den Mondbrunnen des Baumes wird benötigt, um die Gesundheit der Insel zu pflegen."},{t="Weiter nach Dolanaar",b="Tragt das Gefäß nach Süden durch die Tore des Tals und folgt dann den Kopfsteinpflasterstraßen nach Westen bis nach Dolanaar. Die Reise führt über die geschützte Wiege von Laubschattental hinaus in die weite Wildnis von Teldrassil. Am zentralen Mondbrunnen in Dolanaar nimmt Corithras Mondzorn das Gefäß entgegen und leitet den nächsten Teil des Rituals an."}},faq={{q="Was befindet sich in dem Gefäß?",a="Druide Tenaron Sturmgewalt gießt reines Wasser aus dem heiligen Mondbrunnen von Laubschattental in das Gefäß.",al={"was ist im gefäß","inhalt des gefäßes","welches wasser ist darin"}},{q="Warum ist es nur teilweise gefüllt?",a="Der Mondbrunnen von Laubschattental liefert nur die erste Probe. Die Pflege Teldrassils erfordert Wasser aus mehreren Mondbrunnen, bevor das Gefäß voll ist.",al={"warum teilweise gefüllt","warum ist es nicht voll"}},{q="Wem bringe ich dieses Gefäß?",a="Tragt das Gefäß nach Süden aus Laubschattental hinaus und folgt dann der Kopfsteinpflasterstraße nach Westen bis nach Dolanaar. Übergebt es Corithras Mondzorn, der den Mondbrunnen des Ortes hütet.",al={"wer bekommt das gefäß","wohin bringen","gefäß abgeben"}},{q="Warum wird Mondbrunnenwasser durch Teldrassil transportiert?",a="Druiden und Priesterinnen überwachen und nähren Teldrassil mithilfe seines Mondbrunnenwassers. Der Austausch von Wasser zwischen den Brunnen hilft, ihre Segnungen in den angeschlagenen Ästen des neu gewachsenen Weltbaums aufrechtzuerhalten.",al={"warum mondbrunnenwasser transportieren","zweck des wassers","warum wasser bewegen"}}},fx={["5f4a3df1"]={q="Was ist das Teilweise gefülltes Gefäß?",a="Das Teilweise gefülltes Gefäß ist ein verzauberter Behälter, den Nachtelfen-Druiden verwenden, um die heiligen Wasser der Mondbrunnen von Teldrassil zu sammeln und zu transportieren. Wenn Tenaron Sturmgewalt Euch von Laubschattental aus aussendet, gießt er Eure gesammelte Phiole mit gesegnetem Mondbrunnenwasser in dieses Gefäß, damit die heilige Arbeit über die Äste des Weltenbaums hinweg fortgesetzt werden kann.",al={"lore über teilweise gefülltes gefäß","was ist dieses gefäß","was ist das teilweise gefüllte gefäß"}},["4f920d4c"]={q="Woher stammt das Teilweise gefülltes Gefäß und wer hat es hergestellt?",a="Tenaron Sturmgewalt, einer der älteren Druiden, die auf Aldrassil in Laubschattental stationiert sind, stellt Euch dieses Gefäß zur Verfügung. Nachdem Ihr Wasser aus dem Mondbrunnen von Laubschattental geschöpft habt, gießt Tenaron Eure Phiole in den Behälter, um die Sammlung zu beginnen, und vertraut Euch damit, es in die weiteren Weiten von Teldrassil zu tragen.",al={"wer hat das gefäß hergestellt","woher stammt das gefäß","ursprung des gefäßes"}},["089d2d88"]={q="Warum möchte Corithras Mondzorn das Teilweise gefülltes Gefäß haben?",a="Corithras Mondzorn erwartet das Gefäß am Mondbrunnen in Dolanaar, um eine wichtige druidische Aufgabe fortzusetzen, die als Krone der Erde bekannt ist. Das Sammeln der Wasser von Teldrassil ist unerlässlich, um den jungen Weltenbaum zu untersuchen und zu pflegen, und Corithras benötigt das Wasser, das Ihr von Aldrassil gebracht habt, bevor er Euch auf die nächsten Stufen des Rituals hinweisen kann.",al={"warum will corithras das","warum das gefäß nach dolanaar bringen","warum gefäß zu corithras bringen"}}},fp="23,159,17.262.0,18.309.0,26.93.0,32.142.0,29.159.0,52.198.0"}
P.entries["item:pendant-of-shadow"] = {n="Schattenanhänger",s="Im Turm von Ilgalar trägt Morganth den Schattenanhänger, während er nach der Sichel von Elune sucht. Theocritus will ihn als Beweis für Morganths Tod zum Turm von Azora bringen lassen.",h="Im Turm von Ilgalar trägt Morganth den Schattenanhänger, während er nach der Sichel von Elune sucht.",kw={"morganth","schattenanhänger","rotkammgebirge","sichel von elune","theocritus","turm von azora","der turm von ilgalar"},ang={["class:Mage"]="Wenn Ihr als Magier den Talisman für Theocritus beschafft, zeigt Ihr die Verantwortung der Magier, rücksichtslose, abtrünnige Zauberwirker aufzuhalten, die das Reich bedrohen.",["class:Warlock"]="Als Hexenmeister zeigt Morganth, wie gefährlich es ist, bei der Jagd nach unberechenbaren, verbotenen Artefakten wie der Sichel von Elune die Aufmerksamkeit des Turms von Azora auf sich zu ziehen."},sec={{t="Zeichen eines finsteren Hexenmeisters",b="Im Turm von Ilgalar besitzt Morganth den Schattenanhänger. Der abtrünnige Hexenmeister ergründet die Geheimnisse der Sichel von Elune, eines uralten Relikts von gewaltiger und unberechenbarer Macht.\n\nTheocritus fürchtet das Unheil, das Morganth über das Rotkammgebirge und das Königreich Sturmwind bringen könnte. Der Magier schickt Abenteurer aus, um Ilgalar zu infiltrieren, Morganths Ränken ein Ende zu setzen und den Talisman als Beweis seines Todes mitzunehmen."}},faq={{q="Wo finde ich den Schattenanhänger?",a="Morganth trägt den Anhänger auf der Spitze des Turms von Ilgalar im Nordosten des Rotkammgebirges.",al={"schattenanhänger fundort","wo ist der schattenanhänger","wie bekommt man den schattenanhänger"}},{q="Wer will den Schattenanhänger haben?",a="Theocritus will den Talisman zu sich zum Turm von Azora im Osten des Waldes von Elwynn bringen lassen.",al={"wer nimmt den schattenanhänger","schattenanhänger abgeben","theocritus anhänger"}},{q="Warum braucht Theocritus diesen Anhänger?",a="Theocritus braucht den Anhänger als Beweis dafür, dass Morganth getötet wurde und die Suche nach der gefährlichen Sichel von Elune beendet ist.",al={"warum theocritus ihn will","zweck des schattenanhängers"}},{q="Welche Bedrohung ging von Morganth mit dem Anhänger aus?",a="Morganth suchte nach der Sichel von Elune. Theocritus fürchtete, der Hexenmeister würde im Rotkammgebirge und im umliegenden Königreich verheerende Macht entfesseln, wenn er das Artefakt erlangte.",al={"was hat morganth getan","morganth hintergrundgeschichte"}}},fx={d0e37f9a={q="Was ist der Schattenanhänger?",a="Der Schattenanhänger ist ein dunkler Talisman, der von dem Schurken-Hexenmeister Morganth oben auf dem Turm von Ilgalar im Rotkammgebirge getragen wird. Direkt mit Morganths finsteren Ambitionen und dunklen Künsten verbunden, dient der Anhänger dem Zauberer Theocritus als Beweis für seine Niederlage, da dieser fürchtet, welch verheerende Wirkung Morganth auf Sturmwind ausüben könnte, wenn er nicht aufgehalten würde.",al={"was ist schattenanhänger","schattenanhänger lore","schattenanhänger info"}}},fp="17,180,23.403.1,38.99.0,32.92.0,38.121.1,47.171.1"}
P.entries["item:pendant-of-the-sea-lion"] = {n="Anhänger des Seelöwen",s="Am Schrein von Remulos fügen Druiden die beiden Hälften des Anhängers des Seelöwen zusammen. Der fertige Talisman zeigt, dass ein Initiat bereit ist, eine Aquatic Form zu erlernen.",h="Am Schrein von Remulos fügen Druiden die beiden Hälften des Anhängers des Seelöwen zusammen.",kw={"aquatic form","dendrite sternenschauer","mathrengyl bärenfährte","mondlichtung","anhänger des seelöwen","remulos","turak runentotem"},ang={["class:Druid"]="Als Druide erreicht Ihr mit dem Zusammensetzen des Anhängers einen Meilenstein Eurer Ausbildung. Er lässt Euch unter Wasser atmen und als Seelöwe schnell schwimmen.",["race:Tauren"]="Als Tauren auf dem Pfad des Zirkels des Cenarius ehrt Ihr Eure Ahnen und die Lehren von Mondlichtung, wenn Ihr den Anhänger zu Turak Runentotem bringt."},sec={{t="Ein Zeichen der Tiefe",b="Ein Druide muss sich den Gefahren des Wassers stellen, um den aquatischen Aspekt des Seelöwen zu erlangen. Der Anhänger besteht aus zwei Hälften. Eine verleiht die Beweglichkeit, um an Raubtieren im Wasser vorbeizugleiten, während die andere die Ausdauer gewährt, lange unter Wasser auszuharren. Am Schrein von Remulos in Mondlichtung fügen Druiden die Teile zusammen."},{t="Beweis der Meisterschaft",b="Sobald der Anhänger geschmiedet ist, bringt ein Initiat ihn zu einem älteren Mentor. Turak Runentotem wartet auf den Anhöhen von Donnerfels, während Mathrengyl Bärenfährte in Darnassus ist. Der Talisman beweist, dass der Initiat die Prüfungen unter Dendrite Sternenschauer bestanden hat. Dann kann der Ältere die Geheimnisse der Verwandlung in eine Aquatic Form lehren."}},faq={{q="Welchen Zweck erfüllt der Anhänger des Seelöwen?",a="Der Anhänger beweist, dass ein Initiat Prüfungen der Beweglichkeit und Ausdauer im Wasser bestanden hat und bereit ist, eine Aquatic Form zu erlernen.",al={"was bewirkt der anhänger des seelöwen","anhänger des seelöwen verwendung","warum den anhänger des seelöwen holen"}},{q="Wo wird der Anhänger zusammengesetzt?",a="Druiden fügen die beiden Hälften des Anhängers am Schrein von Remulos in Mondlichtung zusammen. Eine Hälfte steht für Beweglichkeit und die andere für Ausdauer.",al={"anhänger des seelöwen herstellen","wo anhängerhälften zusammenfügen"}},{q="Wem überreiche ich den Anhänger in Donnerfels?",a="In Donnerfels überreicht Ihr den fertigen Anhänger Turak Runentotem auf der Anhöhe der Ältesten.",al={"wer nimmt den anhänger in donnerfels","turak runentotem anhänger","horde aquatic form abgeben"}},{q="Können auch Nachtelfen diesen Anhänger erlangen?",a="Ja. Nachtelfendruiden durchlaufen dieselbe Prüfung in Mondlichtung und bringen den zusammengesetzten Anhänger dann zu Mathrengyl Bärenfährte in Darnassus.",al={"allianz anhänger des seelöwen","darnassus anhänger des seelöwen"}}},fx={["203d1c94"]={q="Was ist der Anhänger des Seelöwen?",a="Der Anhänger des Seelöwen ist ein heiliger druidischer Talisman, der die Beherrschung über das Wasser symbolisiert. Er verkörpert die Agilität, die erforderlich ist, um gefährlichen Raubtieren im Wasser auszuweichen, sowie die tiefe Belastbarkeit, die nötig ist, um untergetaucht zu bleiben, ohne an die Oberfläche zurückzukehren. Druiden tragen dieses vereinte Relikt als greifbaren Beweis dafür, dass sie das natürliche Gleichgewicht verstehen, bevor sie eine Aquatic Form annehmen.",al={"was ist anhänger des seelöwen","anhänger des seelöwen info","seelöwenanhänger lore"}},ad633d46={q="Woher stammt der Anhänger des Seelöwen und wer hat ihn angefertigt?",a="Der Talisman wird von jungen Druiden geschmiedet, die sich der Prüfung des Seelöwen unterziehen. Er wird erschaffen, indem zwei separate Teile – der Halbe Anhänger der Wasser-Beweglichkeit und der Halbe Anhänger der Wasser-Belastbarkeit – von den Prüfungsorten geborgen und vor dem Schrein von Remulos in der Mondlichtung zusammengeführt werden, wodurch die Aspekte zu einem einzigen heiligen Emblem vereint werden.",al={"wer fertigte anhänger des seelöwen","ursprung seelöwenanhänger","wie wird anhänger des seelöwen erschaffen"}},["384283bf"]={q="Warum möchte jemand den Anhänger des Seelöwen haben?",a="Druidische Mentoren verlangen, den vollständigen Anhänger als unbestreitbaren Beweis Eurer Ausbildung zu sehen. In Donnerfels benötigt Turak Runentotem das Medaillon, um zu überprüfen, ob Ihr die Prüfungen der Mondlichtung bestanden habt, bevor er Euch die Geheimnisse der Aquatic Form lehrt. Dendrite Sternenschauer in der Mondlichtung untersucht das vereinte Relikt ebenfalls, um den Abschluss der Prüfung zu bestätigen.",al={"warum anhänger des seelöwen wollen","wer will seelöwenanhänger","warum anhänger des seelöwen zeigen"}}},fp="23,154,19.299.0,16.307.0,51.119.0,31.128.0,49.89.0,39.130.0"}
P.entries["item:perenolde-tiara"] = {n="Tiara von Perenolde",s="In den Ruinen von Alterac ist die Tiara von Perenolde wieder aufgetaucht. Zwergenhandwerker aus Eisenschmiede fertigten das smaragdbesetzte Erbstück, und Sammler in Sturmwind suchen danach.",h="In den Ruinen von Alterac ist die Tiara von Perenolde wieder aufgetaucht.",kw={"alterac","smaragde","grel'borg","eisenschmiede","geizhals","perenolde","remington","kronenbrunn","tiara"},ang={["faction:Alliance"]="Als Mitglied der Allianz steht Ihr vor einer bitteren Erinnerung an das Haus Perenolde, dessen Verrat während des Zweiten Krieges die ursprüngliche Allianz von Lordaeron beinahe zerstörte.",["race:Dwarf"]="Als Zwerg erkennt Ihr Eisenschmiedes Edelsteinkunst an den Smaragden, die seine Juweliermeister für die menschlichen Königshäuser des Nordens schliffen und fassten."},sec={{t="Relikt eines zerstörten Königreichs",b="Die Familie Perenolde herrschte über Alterac, bis das Königreich während des Zweiten Krieges fiel. Zu ihren Schätzen gehörte eine filigrane Tiara, die Juweliermeister in Eisenschmiede gefertigt und mit strahlenden Smaragden besetzt hatten. Nachdem der Verrat von König Aiden Perenolde Alterac ins Verderben gestürzt hatte, verschwand die Tiara inmitten der Verwüstung der hohen Felsklippen."},{t="Der Schatz des Geizhalses",b="Grel'borg the Miser, ein Ogermagier, grub die Tiara aus, als er Alteracs Ruinen nach herrenlosen Reichtümern durchsuchte. Die Kunde von dem Relikt erreichte Graf Remington Kronenbrunn, einen wohlhabenden Adligen in Sturmwind, der berühmte Relikte für sein Familienmuseum sammelt. Nun will der Graf dem Oger die Tiara abnehmen."}},faq={{q="Was ist die Tiara von Perenolde?",a="Die Tiara von Perenolde ist ein Erbstück der königlichen Familie Perenolde aus Alterac. Zwergische Juweliere in Eisenschmiede fertigten sie und besetzten sie mit Smaragden, bevor sie beim Untergang des Königreichs verloren ging.",al={"tiara von perenolde hintergrundgeschichte","was ist diese tiara","alterac tiara"}},{q="Wer besitzt die Tiara jetzt?",a="Grel'borg the Miser, ein Ogermagier, fand die Tiara in Alteracs verschneiten Ruinen. Er bewacht sie, während er das zerstörte Königreich nach weiteren Schätzen durchsucht.",al={"wo ist die tiara","wer lässt die tiara fallen","grelborg tiara"}},{q="Warum will Graf Remington Kronenbrunn sie haben?",a="Graf Remington Kronenbrunn sammelt historische und prestigeträchtige Antiquitäten für sein Familienmuseum in Sturmwind. Er will die Tiara als Kronjuwel aus einem gefallenen Menschenkönigreich.",al={"wer will die tiara","warum will remington sie","remington kronenbrunn beweggrund"}},{q="Wer waren die Perenoldes?",a="Die Perenoldes herrschten über das Königreich Alterac. Während des Zweiten Krieges verriet König Aiden Perenolde die Allianz an die orkische Horde, und sein Reich fiel in Trümmer.",al={"familie perenolde","haus perenolde","herrscher von alterac"}}},fx={da959daa={q="Woher stammt die Tiara von Perenolde und wer hat sie angefertigt?",a="Die Tiara stammt aus dem zerstörten nördlichen Königreich Alterac, wo sie als geschätztes Familienerbstück des königlichen Hauses Perenolde diente. Anstatt von menschlichen Handwerkern geschmiedet worden zu sein, heißt es, sie sei von meisterhaften Zwergenjuwelieren in Eisenschmiede gefertigt worden, die das kunstvolle Stück mit den feinsten Smaragden verzierten.",al={"wer fertigte tiara von perenolde","ursprung tiara von perenolde","wo wurde tiara gefertigt"}}},fp="15,167,27.319.0,17.295.0,28.187.0,28.152.0,43.172.0,24.161.0"}
P.entries["item:phial-of-scrying"] = {n="Wahrsagephiole",s="Überall an der Dunkelküste erreichen Späher Onu aus gefährlichem Gelände. Onu stellt die Wahrsagephiole bereit, deren verzaubertes Wasser eine Schale zur Weissagung über die verderbten Wälder hinweg bildet.",h="Überall an der Dunkelküste erreichen Späher Onu aus gefährlichem Gelände.",kw={"dunkelküste","die meistergleve","onu","wahrsagephiole","wahrsageschale","schattenhammer"},ang={["class:Druid"]="Als Druide erkennt Ihr in Wahrsageschalen eine Verbindung aus natürlichem Wasser und Magie der Zwiesprache. Sie ermöglichen es den Hütern des Waldes, über verderbtes Gelände hinweg flüsternd Nachrichten auszutauschen.",["race:NightElf"]="Als Nachtelf von der Dunkelküste wisst Ihr, dass Wahrsagewasser dabei hilft, heilige Wälder zu überwachen, in die fremdartige Kulte vordringen."},sec={{t="Eine Linse über die Dunkelküste",b="Späher tief im Inneren der Dunkelküste nutzen die Wahrsagephiole zur Weissagung über weite Entfernungen. Ihr mystisches Wasser bildet vorübergehend eine Schale auf dem Boden. Von gefährlichen Orten wie der Meistergleve aus können sie mit Onu sprechen, ohne zu seinem Hain zurückzukehren."},{t="Dem Kult auf der Spur",b="Onu gibt Spähern die Phiole, um die Kultisten des Schattenhammers zu beobachten. Dort, wo ein uralter gefallener Meister von einer gewaltigen Gleve aufgespießt liegt, stellt ein Späher eine Wahrsageverbindung her. Die Vision bestätigt, dass sich finstere Kultisten um die uralten Überreste versammeln und nach Splittern vergessener Macht suchen, die selbst im Tod fortbesteht."}},faq={{q="Was bewirkt die Wahrsagephiole?",a="Entkorkt die Wahrsagephiole, und eine magische Schale bildet sich auf dem Boden. Damit könnt Ihr von unterwegs Kontakt zu Onu aufnehmen und über gewaltige Entfernungen hinweg mit ihm sprechen.",al={"wahrsagephiole benutzen","funktion der wahrsageschale","wozu dient diese phiole"}},{q="Wer stellt die Wahrsagephiole bereit?",a="Das uralte Urtum Onu gibt Spähern an der Dunkelküste die Phiole, wenn er sie nach Süden schickt, um die Meistergleve auszukundschaften.",al={"wer gibt die wahrsagephiole","wo gibt es die phiole"}},{q="Was geschieht, wenn die Phiole verloren geht oder aufgebraucht ist?",a="Wenn Ihr die Phiole verliert oder benutzt, bevor Ihr Euren Auftrag abschließt, kann Onu Euch eine weitere geben, während er an der Dunkelküste meditiert.",al={"wahrsagephiole verloren","weitere phiole erhalten","phiole ersetzen"}},{q="Warum erforscht Onu die Meistergleve durch Weissagung?",a="Onu weiß, dass ein alter Herrscher an der Meistergleve fiel, und bittet Euch, dort nach Kultisten des Schattenhammers zu suchen. Ihre Absicht wird im Verlauf der Untersuchung deutlich.",al={"warum die meistergleve durch weissagung erforschen","onu meistergleve auftrag"}}},fx={["92e56a99"]={q="Was ist die Wahrsagephiole?",a="Die Wahrsagephiole ist ein verzaubertes Gefäß, das mystische Wasser enthält, die vom Ältesten der Lehren, Onu, bereitgestellt wurden. Wenn sie im Feld ausgegossen wird, erschafft sie eine temporäre Wahrsageschale, die als magisches Leitmedium dient und es Euch ermöglicht, über große Entfernungen eine direkte spirituelle Verbindung mit dem Ältesten aufzubauen.",al={"was ist wahrsagephiole","wahrsagephiole lore","wahrsagephiole erklärt"}},["16c85a4e"]={q="Warum möchte Onu, dass Ihr die Wahrsagephiole benutzt?",a="Onu bittet Euch, The Master's Glaive nach Kultisten des Schattenhammers zu durchsuchen. Die Phiole lässt Euch eine Wahrsageschale erschaffen und nach der Durchsuchung des Ortes mit ihm sprechen, ohne vorher zu seinem Hain zurückkehren zu müssen.",al={"warum wahrsagephiole benutzen","warum will onu wahrsagephiole","warum wahrsagephiole brauchen"}}},fp="16,173,23.242.0,19.313.1,34.155.0,34.122.0,47.120.0,44.171.0"}
P.entries["item:piece-of-krom-zar-s-banner"] = {n="Teil von Krom'zars Flagge",s="An Regthar Deathgates Bunker westlich des Wegekreuzes zeugt ein zerrissenes Banner vom gescheiterten Angriff. Kriegsfürst Krom'zar führte die Vergeltungsstreitmacht der Kolkar von Desolace nach Osten.",h="An Regthar Deathgates Bunker westlich des Wegekreuzes zeugt ein zerrissenes Banner vom gescheiterten Angriff.",kw={"banner","zentaur","gegenangriff","das wegekreuz","deathgate","kolkar","krom'zar","regthar"},ang={["faction:Horde"]="Krom'zars Niederlage und die Erbeutung seines Banners stoppen eine große Offensive der Zentauren. Die nördlichen Wege zwischen Durotar, Mulgore und dem Wegekreuz sind sicher.",["race:Tauren"]="Als Tauren wisst Ihr, dass die Angriffe der Zentauren den nomadischen Stämmen schon lange zusetzen. Krom'zars Vorhut ist vernichtet, und die Pfade nach Mulgore sind sicherer."},sec={{t="Trophäe des Zentaureneinfalls",b="Kriegsfürst Krom'zar führte seine Kriegsschar von Desolace nach Osten, um zurückzuschlagen. Im ganzen Brachland waren Häuptlinge der Kolkar gefallen, und die erzürnten Zentauren griffen die Verteidigungsbunker westlich des Wegekreuzes an. Ein Streifen von Krom'zars gefallener Standarte beweist Regthar Totenfurt, dass der Angriff niedergeschlagen wurde und die südlichen Handelswege für die Horde gesichert blieben."}},faq={{q="Wozu dient dieses Bannerstück?",a="Bringt den zerrissenen Stoff zu Regthar Totenfurt in seinem Bunker westlich des Wegekreuzes. Er beweist, dass Kriegsfürst Krom'zar erschlagen und seine Angriffstruppe zerschlagen wurde, womit die Verteidigung des nördlichen Brachlands abgeschlossen ist.",al={"zweck des banners","warum banner behalten","was tun mit bannerstück"}},{q="Wer war Kriegsfürst Krom'zar?",a="Krom'zar war ein Kommandant der Kolkar aus Desolace. Nachdem die örtlichen Anführer der Kolkar getötet worden waren, führte er einen direkten Gegenangriff auf Außenposten der Horde an.",al={"wer ist kromzar","krom'zars geschichte","kriegsfürst krom'zar"}},{q="Warum griffen die Kolkar den Bunker an?",a="Nachdem Barak, Verog, Hezrul und die anderen örtlichen Häuptlinge gefallen waren, sammelten die erzürnten Zentauren Verstärkung aus Desolace. Sie wollten sich an der Horde westlich des Wegekreuzes rächen.",al={"warum gegenangriff","warum invasion der kolkar","grund für gegenangriff im brachland"}},{q="Erfährt Thrall von diesem Sieg?",a="Ja. Regthar Totenfurt verspricht, Kriegshäuptling Thrall in Orgrimmar direkt Bericht zu erstatten. Er wird die Verteidiger loben, die die Invasion zerschlagen haben.",al={"thralls belohnung","weiß thrall davon"}}},fx={["92115071"]={q="Was ist der Teil von Krom'zars Flagge?",a="Es ist ein zerrissenes Stück des Schlachtbanners von Kriegsfürst Krom'zar, dem Kommandanten der rachsüchtigen Kolkar-Zentaurenarmee, die von Desolace in das Brachland marschierte. Für die Streitkräfte der Horde, die die westlichen Bunker verteidigen, dient es als unbestreitbarer physischer Beweis dafür, dass der Kriegsfürst in der Schlacht gefallen ist und seine Invasion abgewehrt wurde.",al={"was ist teil von krom'zars flagge","krom'zars flaggenteil","was ist das bannerfragment"}},caa193f6={q="Woher stammt der Teil von Krom'zars Flagge?",a="Das Banner wurde von Kriegsfürst Krom'zar und seinem Kolkar-Heer in das Brachland getragen, die den ganzen Weg aus ihrer Heimat in Desolace zurücklegten, um sich an der Horde zu rächen. Als Krom'zar außerhalb der westlichen Bunker das Feld betritt und im Kampf fällt, bleibt sein Banner auf dem Schlachtfeld zurück, wo dieser Überrest abgerissen werden kann.",al={"woher kam krom'zars flagge","wer fertigte krom'zars flagge","ursprung krom'zars flagge"}},["7a980ed6"]={q="Warum möchte Regthar Totenfurt einen Teil von Krom'zars Flagge haben?",a="Regthar Totenfurt benötigt einen konkreten Beweis dafür, dass die eindringende Kolkar-Armee entscheidend zerschlagen wurde. Die Vorlage dieses zerrissenen Banners bestätigt, dass Kriegsfürst Krom'zar vor den Bunkern der Horde erschlagen wurde, was es Regthar ermöglicht, die Invasion offiziell für beendet zu erklären und Kunde von Eurer Tapferkeit direkt an Kriegshäuptling Thrall zu senden.",al={"warum will regthar die flagge","warum krom'zars flagge zu regthar bringen","warum wird krom'zars flagge benötigt"}}},fp="26,163,31.357.0,35.193.0,25.140.0,37.197.0,33.139.0"}
P.entries["item:plainstrider-beak"] = {n="Ebenenschreiterschnabel",s="Im ganzen Brachland bringen Jäger Ebenenschreiterschnäbel zum Wegekreuz als Beweis, dass bedrohliche Vögel erlegt wurden.",h="Im ganzen Brachland bringen Jäger Ebenenschreiterschnäbel zum Wegekreuz als Beweis, dass bedrohliche Vögel...",kw={"brachland","das wegekreuz","ebenenschreiterschnabel","plainstrider menace","sergra darkthorn","tallstrider"},ang={["class:Hunter"]="Als Jäger pirscht Ihr Euch auf Kalimdors offenen Ebenen an Ebenenschreiter heran und sammelt ihre Schnäbel, wobei Ihr lernt, Eure Beute zu sichern.",["faction:Horde"]="Als Mitglied der Horde helft Ihr, die Handels- und Versorgungswege zu schützen, die den Außenposten versorgen, indem Ihr lästige Schwärme östlich des Wegekreuzes dezimiert."},sec={{t="Ein Maß der Jagd",b="Ebenenschreiter suchen nahe dem Wegekreuz nach Nahrung und bedrohen seine Vorräte. Große, flüchtige und boshafte Ebenenschreiter durchstreifen die umliegende Savanne. Sergra Dunkeldorn bittet eintreffende Jäger, ihre Schnäbel zurückzubringen, als Beweis, dass die Schwärme von Versorgungslinien und Lagerhäusern vertrieben wurden."}},faq={{q="Warum will Sergra Dunkeldorn Ebenenschreiterschnäbel?",a="Sergra Dunkeldorn bittet Jäger, Ebenenschreiter zu dezimieren, weil die Vögel die Nahrungsvorräte rund um das Wegekreuz bedrohen. Ihre Schnäbel zeigen, dass die Gefahr für die örtlichen Vorräte verringert wurde.",al={"warum schnäbel sammeln","sergra ebenenschreiterschnabel quest","warum schnäbel"}},{q="Von welchen Kreaturen stammen diese Schnäbel?",a="Jäger erbeuten die Schnäbel von großen, flüchtigen und boshaften Ebenenschreitern, die durch die Savanne des Brachlands streifen.",al={"wer lässt ebenenschreiterschnäbel fallen","ebenenschreiterschnabel quellen","wo schnäbel bekommen"}},{q="Warum liefert nicht jeder erlegte Ebenenschreiter einen Schnabel?",a="Schnelle, um sich schlagende Ebenenschreiter können im Kampf einen Schnabel beschädigen, zerschmettern oder als unversehrte Trophäe unbrauchbar machen. Jäger sammeln nur intakte Schnäbel.",al={"warum niedrige droprate","ebenenschreiterschnabel fällt nicht"}}},fx={["7e2762f5"]={q="Was ist ein Ebenenschreiterschnabel?",a="Ein Ebenenschreiterschnabel ist der abgetrennte Schnabel, der von den flugunfähigen Ebenenschreitern stammt, die die Savanne des Brachlandes durchstreifen. Hart und spitz, werden diese Schnäbel von Jägern als greifbarer Beweis dafür gesammelt, dass die lästigen Vögel, die die lokalen Vorräte bedrohen, erlegt wurden.",al={"ebenenschreiterschnabel gegenstand","was ist ebenenschreiterschnabel","ebenenschreiterschnäbel"}},["6978f6b2"]={q="Woher stammt ein Ebenenschreiterschnabel?",a="Diese Schnäbel stammen direkt von den verschiedenen Rassen der Ebenenschreiter – wie den größeren, flüchtigen und störrischen Ebenenschreitern –, die im Brachland heimisch sind. Sie werden von Jägern über die trockenen Ebenen hinweg als Trophäen und Beweis einer erfolgreichen Jagd geerntet.",al={"wo ebenenschreiterschnabel bekommen","wer lässt ebenenschreiterschnabel fallen","ebenenschreiterschnabel quelle"}}},fp="17,120,21.282.0,50.177.0,34.101.0,54.148.0"}
P.entries["item:plainstrider-feather"] = {n="Ebenenschreiterfeder",s="Auf der Hochwolkenebene sammeln junge Jäger Ebenenschreiterfedern von den Vögeln, die Mulg ores Ebenen durchstreifen. Camp Narache fertigt aus den Federn Kleidung und Stammesschmuck und ehrt damit die Geschöpfe, die das Dorf versorgen.",h="Auf der Hochwolkenebene sammeln junge Jäger Ebenenschreiterfedern von den Vögeln, die Mulg ores Ebenen...",kw={"camp narache","feder","grull falkenwind","mulgore","ebenenschreiter","die hochwolkenebene","the hunt begins"},ang={["class:Hunter"]="Wenn Ihr als Jäger flinken Ebenenschreitern auf der Hochwolkenebene nachstellt, prüft das Eure Geduld und Euer Fährtenlesen und lehrt Euch, Eure Beute zu ehren.",["race:Tauren"]="Als junger Tauren lernt Ihr beim Sammeln der Federn eines Ebenenschreiters, die Geschöpfe der Earth Mother zu schätzen und jeden Teil der Beute für Nahrung und Kleidung zu nutzen."},sec={{t="Die erste Gabe eines Jägers",b="Junge Tauren auf der Hochwolkenebene lernen, Fährten zu lesen und zu erjagen, was ihr Stamm braucht. Ebenenschreiter durchstreifen das grasbewachsene Plateau und liefern Nahrung und nützliche Federn. Camp Narache fertigt aus ihrem Gefieder Kleidung und Ausrüstung.\n\nJunge Jäger bringen Grull Falkenwind Federn und frisches Fleisch, um das Lager zu versorgen. Diese Gabe ist ihre erste Prüfung. Häuptling Falkenwind erkennt sie an und heißt sie in Donnerfels willkommen."}},faq={{q="Wofür werden Ebenenschreiterfedern verwendet?",a="Camp Narache fertigt aus Ebenenschreiterfedern Kleidung und zeremonielle Gegenstände. Grull Falkenwind sammelt sie bei jungen Jägern ein, um die Vorräte des Stammes aufzufüllen.",al={"zweck der federn","verwendung der ebenenschreiterfeder","warum federn sammeln"}},{q="Wer sammelt Ebenenschreiterfedern auf der Hochwolkenebene?",a="Auf Grull Falkenwinds Bitte sammeln junge Jäger Ebenenschreiterfedern auf der Hochwolkenebene. Er füllt damit die Vorräte von Camp Narache auf und prüft ihre Disziplin bei der Versorgung des Stammes.",al={"wer will federn","wer braucht federn","grull falkenwind federn"}},{q="Wo sind Ebenenschreiter zu finden?",a="Ebenenschreiter durchstreifen das offene Grasland der Hochwolkenebene und die wogenden Ebenen von Mulgore.",al={"wo ebenenschreiter finden","ebenenschreiter fundort","federn farmen"}},{q="Warum verlangt Grull Falkenwind diese Federn für Stammesriten?",a="In der Kultur der Tauren dient die Jagd dem Überleben und dem Zeitvertreib. Wer Häuptling Falkenwind Fleisch und Gefieder bringt, zeigt als junger Jäger, dass er den Stamm versorgen kann, bevor er nach Donnerfels weiterzieht.",al={"the hunt begins hintergrund","bewährungsjagd tauren","warum ebenenschreiter jagen"}}},fx={f2ff74a3={q="Was ist eine Ebenenschreiterfeder?",a="Eine Ebenenschreiterfeder ist ein Gefieder, das von den großen, flugunfähigen Vögeln gesammelt wird, die durch die Graslandschaften von Mulgore wandern. Die Tauren der Hochwolkenebene nutzen jede Ernte des Landes mit tiefem Respekt, und diese robusten, farbenfrohen Federn dienen als praktisches Material für die Herstellung von Alltagskleidung sowie traditionellem Schmuck.",al={"was ist ebenenschreiterfeder","ebenenschreiterfeder info","ebenenschreiterfedern"}},["8bb68bd8"]={q="Woher stammen Ebenenschreiterfedern?",a="Diese Federn sind natürlich gewachsenes Gefieder, das direkt von den wilden Ebenenschreitern geerntet wird, die die Hochwolkenebene und die weiteren Ebenen von Mulgore durchstreifen. Sie werden nicht von sterblichen Händen gefertigt, sondern von Jägern nach einer erfolgreichen Jagd in der offenen Prärie gesammelt.",al={"ebenenschreiterfeder quelle","wo ebenenschreiterfedern bekommen","wer fertigte ebenenschreiterfeder"}}},fp="20,225,25.400.0,40.153.0,52.186.0,33.85.0,64.179.0"}
P.entries["item:plainstrider-kidney"] = {n="Ebenenschreiterniere",s="Im ganzen Brachland sammeln Jäger Ebenenschreiternieren für Kalimdors ungewöhnliche Brautraditionen. Die meisten Reisenden finden das Organ unappetitlich, doch für ein exotisches Ale ist es unverzichtbar.",h="Im ganzen Brachland sammeln Jäger Ebenenschreiternieren für Kalimdors ungewöhnliche Brautraditionen.",kw={"braumeister drohn","chen stormstout","ebenenschreiter","ebenenschreiterniere","ratschet","stormstout","brachland"},ang={["class:Hunter"]="Als Jäger müsst Ihr Ebenenschreiter in der Savanne sorgfältig ausnehmen, damit ihre inneren Organe für den Handel mit Ratschets Braumeistern unversehrt bleiben.",["profession:Cooking"]="Als Koch schreckt Ihr vielleicht davor zurück, Vogelnieren zu edlen Spirituosen zu vergären. In Kalimdors Wildnis bedeutet Überleben oft, jeden Teil der erlegten Beute zu verwerten."},sec={{t="Eine unorthodoxe Brauzutat",b="Große, flugunfähige Ebenenschreiter durchstreifen das Brachland, und Jäger nutzen ihre Federn und ihr Fleisch für Werkzeuge und einfache Rationen. Braumeister Drohn in Ratschet sucht ihre Nieren für einen anderen Zweck: Er sagt, sie seien nötig, um Chen Stormstouts legendär starkes Ale nachzubrauen.\n\nDrohn sagt, die Nieren verleihen dem Gebräu einen einzigartigen Kick. Das Rezept stammt aus einer unkonventionellen Braumeistertradition und wurde über die Jahre weitergegeben."}},faq={{q="Wofür wird eine Ebenenschreiterniere verwendet?",a="Braumeister Drohn in Ratschet braucht Ebenenschreiternieren, um eine legendäre Charge Stormstout-Ale nachzubrauen. Er sagt, sein Mentor habe das Rezept von Chen Stormstout gelernt, dem wandernden Pandarenbraumeister.",al={"ebenenschreiterniere verwendung","warum werden ebenenschreiternieren gebraucht","ebenenschreiterniere zweck"}},{q="Warum braut jemand Ale mit tierischen Organen?",a="Kalimdors ungewöhnliche Gebräue verwenden oft Teile der widerstandsfähigen heimischen Tierwelt für kräftige Aromen und einen unverwechselbaren Kick. Braumeister Drohn sagt, das Brauen starker, wilder Rezepturen erinnere ihn an unorthodoxe Schöpfungen wie Trogggebräu.",al={"niere im bier","warum niere in stormstout","tierteile in alkohol"}},{q="Welche Kreaturen liefern diese Nieren?",a="Flüchtige, störrische und große Ebenenschreiter, die das Brachland durchstreifen, liefern diese Nieren.",al={"wo gibt es ebenenschreiternieren als beute","wer hinterlässt ebenenschreiternieren","ebenenschreiterniere herkunft"}},{q="Welche weiteren Zutaten werden neben den Nieren benötigt?",a="Braumeister Drohn verlangt für sein Gebräu fünf Ebenenschreiternieren, fünf Hauer von Savannenlöwen und ein Donnerechsenhorn.",al={"weitere brauzutaten","was braucht drohn sonst noch","stormstout zutaten"}}},fx={d14d143c={q="Was ist eine Ebenenschreiterniere?",a="Es ist ein inneres Organ, das von den großen, flugunfähigen Ebenenschreitern geerntet wird, die die Savannen des Brachlandes durchstreifen. Während die meisten Jäger solche Innereien wegwerfen oder sie Aasfressern überlassen, schätzen bestimmte exzentrische Braumeister sie als potente und unkonventionelle Zusätze für exotische Spirituosen.",al={"was ist ebenenschreiterniere","ebenenschreiterniere info","erzähl mir von ebenenschreiterniere"}},["4fd58422"]={q="Woher stammt eine Ebenenschreiterniere?",a="Diese Organe werden direkt von den wilden Ebenenschreitern entnommen, die im Brachland heimisch sind, einschließlich der größeren, störrischen und flüchtigen Varietäten. Sie sind natürlich vorkommende Teile der Anatomie der Vögel und keine hergestellten Waren, obwohl die Sicherung einer Niere erfordert, die schnellen und aggressiven Vogelbestien über die Ebenen hinweg nachzujagen.",al={"ebenenschreiterniere quelle","wo ebenenschreiterniere bekommen","ebenenschreiterniere ursprung"}},["53f4067b"]={q="Warum möchte Braumeister Drohn Ebenenschreiternieren haben?",a="Braumeister Drohn in Ratschet sucht nach diesen Nieren, um das legendäre, potente Gebräu von Chen Sturmbräu nachzubrauen. Chen gab das unkonventionelle Rezept an Drohns Mentor weiter, und Drohn benötigt die Nieren zusammen mit Löwenzähnen und einem Donnerechsenhorn, um das Starkbier mit seiner charakteristischen, heftigen Note zu brauen.",al={"warum werden ebenenschreiternieren benötigt","wer will ebenenschreiternieren","ebenenschreiterniere zweck drohn"}}},fp="19,181,32.415.0,39.198.0,46.215.0,36.86.0,56.126.0"}
P.entries["item:plainstrider-meat"] = {n="Ebenenschreiterfleisch",s="Auf der Hochwolkenebene sammeln junge Tauren Ebenenschreiterfleisch, um Camp Narache mit Nahrung zu versorgen. Die Jagd auf die Vögel wegen ihres Fleisches und ihrer Federn beweist ihr Geschick und ihre Selbstständigkeit.",h="Auf der Hochwolkenebene sammeln junge Tauren Ebenenschreiterfleisch, um Camp Narache mit Nahrung zu versorgen.",kw={"camp narache","häuptling falkenwind","grull falkenwind","mulgore","ebenenschreiter","ebenenschreiterfleisch","die hochwolkenebene","the hunt begins"},ang={["class:Hunter"]="Als Jäger könnt Ihr Euer Geschick im Fährtenlesen und Eure Treffsicherheit an flinken Ebenenschreitern in den offenen Ebenen von Mulgore erproben.",["race:Tauren"]="Für Euch als jungen Tauren auf der Hochwolkenebene ist die Jagd auf Ebenenschreiter ein früher Schritt, um Häuptling Falkenwinds Respekt und das Recht zu erlangen, Donnerfels zu betreten."},sec={{t="Nahrung für die Hochebene",b="Camp Narache auf der Hochwolkenebene ist auf Wild aus dem umliegenden Grasland angewiesen. Wenn die Nahrungsvorräte knapp werden, hilft Ebenenschreiterfleisch, das Dorf zu ernähren. Die Vögel liefern auch Federn für Kleidung und zeremonielle Verzierungen. Tauren sind auf das Land angewiesen und nehmen, was sie brauchen, während sie die Natur achten."},{t="Die Prüfung eines jungen Jägers",b="Grull Falkenwind schickt junge Jäger über die Hochwolkenebene, um flinke Ebenenschreiter aufzuspüren. Sie sammeln Fleisch und Federn, um ihr Geschick im Fährtenlesen und ihre Selbstständigkeit zu beweisen. Dann treten sie vor Grulls Vater, Häuptling Falkenwind."}},faq={{q="Wofür wird Ebenenschreiterfleisch verwendet?",a="Junge Jäger sammeln auf der Hochwolkenebene Ebenenschreiterfleisch, um für Grull Falkenwind die Nahrungsvorräte von Camp Narache aufzufüllen.",al={"warum ebenenschreiterfleisch","ebenenschreiterfleisch quest","was tun mit ebenenschreiterfleisch"}},{q="Wer bittet um dieses Fleisch?",a="Grull Falkenwind bittet junge Jäger, Ebenenschreiter zu jagen und die Nahrungsvorräte des Stammes aufzufüllen, um sich dabei als Versorger zu beweisen.",al={"wer will ebenenschreiterfleisch","grull falkenwind fleisch"}},{q="Wo lässt sich Ebenenschreiterfleisch finden?",a="Ebenenschreiter durchstreifen das Grasland von Mulgore, darunter auch die Hochwolkenebene, wo Jäger ihr Fleisch sammeln.",al={"wo ebenenschreiterfleisch bekommen","ebenenschreiter fundorte","ebenenschreiterfleisch farmen"}},{q="Warum gilt die Jagd auf Ebenenschreiter den Tauren als wichtig?",a="Tauren jagen Ebenenschreiter zur Nahrungsbeschaffung und als spirituelle Übung. Wild ins Lager zu bringen, zeigt Respekt vor der Earth Mother, Selbstständigkeit und die Fähigkeit, den Stamm zu ernähren.",al={"jagdkultur der tauren","warum ebenenschreiter jagen"}}},fx={f404715e={q="Was ist Ebenenschreiterfleisch?",a="Ebenenschreiterfleisch ist frisches Wild, das von den flugunfähigen Vögeln geerntet wird, die durch die Ebenen von Mulgore wandern. Für die Tauren der Hochwolkenebene dient es als lebenswichtiges Grundnahrungsmittel, das durch traditionelle Jagden gesammelt wird, die die Siedlung erhalten und das Band zwischen Jäger und Beute ehren.",al={"ebenenschreiterfleisch info","was ist ebenenschreiterfleisch","ebenenschreiterfleisch lore"}},["00c8b7f8"]={q="Woher stammt Ebenenschreiterfleisch?",a="Ebenenschreiterfleisch stammt von den wilden Ebenenschreitern, die in Mulgore heimisch sind. Junge Jäger ernten es direkt von den Bestien, die während ihrer ersten Jagdriten für den Stamm die Hochwolkenebene durchstreifen.",al={"woher stammt ebenenschreiterfleisch","ebenenschreiterfleisch ursprung","wie ebenenschreiterfleisch bekommen"}},f1043112={q="Warum wird Ebenenschreiterfleisch in Camp Narache benötigt?",a="Die Nahrungsvorräte von Camp Narache sind knapp geworden, und der Stamm verlässt sich auf geschickte Jagd, um seine Vorräte wieder aufzufüllen. Grull Falkenwind bittet junge Jäger, Ebenenschreiterfleisch zu sammeln, um das Dorf zu ernähren und Häuptling Falkenwind ihre Geschicklichkeit zu beweisen.",al={"warum ebenenschreiterfleisch brauchen","ebenenschreiterfleisch zweck","warum ebenenschreiterfleisch sammeln"}}},fp="17,165,23.293.0,22.221.0,35.116.0,23.135.0,37.99.0,64.176.0"}
P.entries["item:plainstrider-scale"] = {n="Schuppe eines Ebenenschreiters",s="In Mulgore braucht Maur Regenrufer eine Schuppe eines Ebenenschreiters für ein Heilmittel im Dorf der Bluthufe. Die zähe Schuppe hilft gegen eine sich ausbreitende Infektion.",h="In Mulgore braucht Maur Regenrufer eine Schuppe eines Ebenenschreiters für ein Heilmittel im Dorf der...",kw={"dorf der bluthufe","maur regenrufer","mazzranache","mulgore","ebenenschreiter","heilmittel","schuppe","schreiter"},ang={["race:Tauren"]="Als Tauren lernt Ihr, Heilmittel aus der Natur zu sammeln und die Tierwelt der Ebenen zu nutzen, um Euren Stamm zu versorgen."},sec={{t="Eine seltene Zutat",b="Ebenenschreiter durchstreifen Mulgore mit zähen Schuppen an ihren kräftigen Beinen. Die Schuppen schützen sie, doch nur manche sind fest genug, um für Volksheilmittel gemahlen zu werden."},{t="Ein Heilmittel gegen Giftbisse",b="Maur Regenrufer im Dorf der Bluthufe wurde von Mazzranache in die Schulter gebissen, einem legendären Schreiter mit dämonisch roten Augen und einem giftigen Biss. Die Wunde ließ Maur in Fieberwahn verfallen. Um die sich ausbreitende Infektion zu reinigen, bevor sie tödlich endet, braucht er eine Schuppe eines Ebenenschreiters, ein Wolfsherz, einen Puma-Oberschenkelknochen und einen Sturzfliegermagen."}},faq={{q="Wofür wird die Schuppe eines Ebenenschreiters verwendet?",a="Maur Regenrufer im Dorf der Bluthufe braucht eine Schuppe eines Ebenenschreiters für ein Heilmittel. Er kombiniert sie mit Teilen anderer Raubtiere aus Mulgore, um die infizierte Wunde zu behandeln, die Mazzranache mit seinem giftigen Biss verursacht hat.",al={"was bewirkt die schuppe eines ebenenschreiters","schuppe eines ebenenschreiters verwendung","warum schuppe eines ebenenschreiters benötigt"}},{q="Wo findet Ihr eine Schuppe eines Ebenenschreiters?",a="Ihr findet Schuppen von Ebenenschreitern bei wilden Ebenenschreitern, die Mulg ores offenes Grasland durchstreifen.",al={"wo schuppe eines ebenenschreiters finden","wie schuppe eines ebenenschreiters erhalten","schuppe eines ebenenschreiters fundort"}},{q="Warum hat Maur Regenrufer eine Infektion?",a="Maur Regenrufer wurde von Mazzranache in die Schulter gebissen, einem Schreiter mit purpurroten Augen und einem giftigen Biss. Die Wunde verursachte bei ihm zunehmend schweres Fieber und Wahnvorstellungen.",al={"wie wurde maur krank","warum ist maur krank","mazzranaches biss"}},{q="Welche weiteren Zutaten braucht Maur für sein Heilmittel?",a="Maur braucht eine Schuppe eines Ebenenschreiters, ein Herz eines Präriewolfs, einen Knochen eines Flachlandpumas und einen Muskelmagen eines Sturzfliegers für sein Heilmittel.",al={"maur regenrufer zutaten","heilmittel gegen mazzranache","mazzranache questgegenstände"}}},fx={["95a4c3dd"]={q="Was ist eine Schuppe eines Ebenenschreiters?",a="Es handelt sich um eine zähe, spezialisierte Schuppe, die von den Schreitern geerntet wird, die durch das windgepeitschte Grasland von Mulgore streifen. Während Vögel und Schreiter vor allem für ihr Gefieder und ihre scharfen Schnäbel bekannt sind, weisen ihre robusten Beine und Füße grobe, gehärtete Schuppen auf, die den rauen Ebenen standhalten können. Schamanen und Kräuterkundige schätzen diese seltenen, dichten Schuppen wegen ihrer schützenden Eigenschaften bei der Zubereitung spezieller Umschläge und Heilmittel.",al={"was ist schuppe eines ebenenschreiters","schuppe eines ebenenschreiters","schuppen eines ebenenschreiters"}},d7ded3c8={q="Woher stammt eine Schuppe eines Ebenenschreiters?",a="Es ist ein natürlicher tierischer Bestandteil, der direkt von den wilden Ebenenschreitern stammt, die durch Mulgore streifen. Niemand stellt sie her; Jäger ernten sie von den Beinen gefallener Schreiter in den Ebenen und sammeln nur die robustesten Schuppen für die Verwendung in medizinischen Zubereitungen.",al={"quelle für schuppe eines ebenenschreiters","woher kommt schuppe eines ebenenschreiters","wer hat schuppe eines ebenenschreiters hergestellt"}}},fp="18,142,17.156.0,28.325.1,40.203.0,39.85.0,32.167.0,53.115.0"}
P.entries["item:plainstrider-talon"] = {n="Ebenenschreiterkralle",s="In ganz Mulgore sammeln Taurenschamanen Ebenenschreiterkrallen, um Totems zu reinigen. Die scharfen Krallen stammen von großen, flugunfähigen Ebenenschreitern, die in der Region heimisch sind, und helfen, verderbtes Wasser zu reinigen.",h="In ganz Mulgore sammeln Taurenschamanen Ebenenschreiterkrallen, um Totems zu reinigen.",kw={"dorf der bluthufe","reinigungstotem","mulgore","mull donnerhorn","ebenenschreiter","ebenenschreiterkralle","poison water","brunnen der winterhufe"},ang={["class:Shaman"]="Als Schamane könnt Ihr erkennen, wie Taurenrituale Körperteile von Bestien, etwa Krallen, nutzen, um reinigende Totems herzustellen und Kraft aus den heimischen Geistern des Landes zu schöpfen.",["race:Tauren"]="Als Tauren ehrt Ihr Mulg ores Tierwelt durch die Jagd. Jede erlegte Bestie hilft, die Earth Mother zu heilen, wenn die Ausbeutung durch Goblins Schaden anrichtet."},sec={{t="Bande der Ebenen",b="Große, flugunfähige Ebenenschreiter durchstreifen Mulg ores offene Graslandschaften. Ihre kräftigen Beine und scharfen Krallen helfen ihnen, in der harten Prärieerde nach Nahrung zu suchen und sich gegen Raubtiere zu verteidigen. Für die Tauren im Dorf der Bluthufe hat jeder Teil einer erlegten Bestie eine spirituelle Bedeutung.\n\nAls Unternehmungen der Goblins heilige Quellen wie den Brunnen der Winterhufe verunreinigten, suchte Schamane Mull Donnerhorn nach Ebenenschreiterkrallen und Präriewolfpfoten. Im rituellen Handwerk der Tauren leiten Körperteile einheimischer Raubtiere und Nahrungssucher die spirituelle Essenz des Landes in Totems, die unnatürliche Gifte austreiben."}},faq={{q="Welche Kreaturen lassen eine Ebenenschreiterkralle fallen?",a="Ausgewachsene Ebenenschreiter, alte Ebenenschreiter und der berüchtigte Schreiter Mazzranache liefern Ebenenschreiterkrallen in ganz Mulg ores Graslandschaften.",al={"wer lässt ebenenschreiterkrallen fallen","wo gibt es ebenenschreiterkrallen","herkunft der ebenenschreiterkralle"}},{q="Wofür werden Ebenenschreiterkrallen verwendet?",a="Mull Donnerhorn im Dorf der Bluthufe benötigt Ebenenschreiterkrallen und Präriewolfpfoten, um ein Reinigungstotem herzustellen. Damit reinigt er den verderbten Brunnen der Winterhufe.",al={"verwendung der ebenenschreiterkralle","warum brauche ich krallen","quest zur ebenenschreiterkralle"}},{q="Warum braucht Mull Donnerhorn Tierteile, um das Wasser zu reinigen?",a="Der Schamanismus der Tauren beruht auf dem Einklang mit Mulg ores Naturgeistern. Die Einbindung heimischer Wildtiere in ein Ritualtotem beschwört die ungebändigte Kraft des Landes gegen unnatürliche Schadstoffe, die Goblins der Venture Company eingebracht haben.",al={"warum tierpfoten und krallen","schamanisches reinigungsritual krallen"}},{q="Wer hat die Wasserbrunnen in Mulgore vergiftet?",a="In Mulgore tätige Agenten der Venture Company haben gemeinsam mit ihren Handlangern die heiligen Wasserbrunnen der Stämme verunreinigt. Ihre Taten stören die örtliche Umwelt und bedrohen die Taurenstämme.",al={"wer hat die brunnen verunreinigt","wer hat mulgores wasser vergiftet","poison water schuldiger"}}},fx={fdecb439={q="Was ist eine Ebenenschreiterkralle?",a="Eine Ebenenschreiterkralle ist die scharfe Kralle, die von den großen, flugunfähigen Ebenenschreitern geerntet wird, die durch Mulgore streifen. Während diese schnellen Vögel sie natürlicherweise zur Verteidigung und zur Nahrungssuche in den Ebenen einsetzen, tragen die Krallen auch eine angeborene Verbindung zur natürlichen Welt in sich. Für die Tauren repräsentieren solche Materialien die Stärke des Landes und können durch schamanische Rituale kanalisiert werden.",al={"was ist ebenenschreiterkralle","ebenenschreiterkralle hintergrund","ebenenschreiterkrallen"}},["07c33870"]={q="Woher stammen Ebenenschreiterkrallen?",a="Diese Krallen stammen von den ausgewachsenen Ebenenschreitern, die die offenen Ebenen von Mulgore südwestlich des Dorfes der Bluthufe durchstreifen. Jäger sammeln sie von erwachsenen und älteren Ebenenschreitern oder sogar von seltenen Bestien wie Mazzranache als Opfergabe aus dem Überfluss des Landes.",al={"ebenenschreiterkralle quelle","wo bekommt man ebenenschreiterkrallen","ursprung der ebenenschreiterkralle"}},["826885d3"]={q="Warum benötigt Mull Donnerhorn Ebenenschreiterkrallen?",a="Mull Donnerhorn im Dorf der Bluthufe benötigt diese Krallen, um ein Reinigungstotem für den Brunnen der Winterhufe herzustellen. Goblins und ihre Handlanger der Venture Company haben das heilige Wasser verunreinigt, und Mull muss die ursprüngliche Essenz der einheimischen Bestien von Mulgore herbeirufen, um dem Gift entgegenzuwirken und die Reinheit des Brunnens wiederherzustellen.",al={"warum will mull krallen","warum benötigt man ebenenschreiterkrallen","zweck der ebenenschreiterkralle"}}},fp="18,188,19.568.0,41.136.0,38.171.0,63.212.0,40.189.0"}
P.entries["item:podrig-s-order"] = {n="Podrigs Anforderungsliste",s="Im Silberwald fordert Podrigs Anforderungsliste Waffen aus der Unterstadt an, um das Grabmal zu bewaffnen.",h="Im Silberwald fordert Podrigs Anforderungsliste Waffen aus der Unterstadt an, um das Grabmal zu bewaffnen.",kw={"gordon wendheim","hadrec","karos razok","podrig","podrigs anforderungsliste","das grabmal","silberwald"},ang={["profession:Blacksmithing"]="Als Schmied wisst Ihr, dass geschmiedete Waffen an der Front unerlässlich sind. Kämpfe zehren ständig die Vorräte einer Garnison auf.",["race:Undead"]="Als Untoter könnt Ihr sehen, wie die Unterstadt Außenposten wie das Grabmal versorgt. So bleiben die Soldaten der Dark Lady gegen die Geißel bewaffnet."},sec={{t="Waffen für das Grabmal",b="Todeswache Podrig befand die Vorräte des Grabmals für größtenteils ausreichend, nachdem Vollstrecker Hadrec eine Bestandsaufnahme angeordnet hatte. Doch Ersatzwaffen wurden verzweifelt knapp. Sein Schreiben nennt die Klingen und Waffen, die die Todeswachen benötigen, um den Außenposten im Silberwald zu halten. Die Geißel, wilde Tiere und andere Gefahren bedrohen die Grenze."},{t="Versand über den Fledermausführer",b="Die Anforderungsliste ist an Gordon Wendheim gerichtet, einen Waffenhändler im Handwerksviertel der Unterstadt. Die feuchten Krypten des Silberwalds erschweren das Schmieden von Waffen. Kuriere bringen das Dokument zum Fledermausmeister Karos Razok, damit die Flugrouten der Verlassenen die Lieferung aus der Hauptstadt beschleunigen können."}},faq={{q="Was steht in Podrigs Anforderungsliste?",a="Podrigs Anforderungsliste führt Ersatzwaffen für die Todeswachen am Grabmal auf. Ihre Waffen sind im Einsatz verloren gegangen oder zerbrochen.",al={"was steht in der anforderungsliste","inhalt von podrigs anforderungsliste","einzelheiten zu podrigs anforderungsliste"}},{q="Wer hat Podrigs Anforderungsliste verfasst?",a="Todeswache Podrig verfasste die Anforderungsliste auf Anweisung von Vollstrecker Hadrec. Er tat dies nach einer Bestandsaufnahme der Waffenkammer des Grabmals.",al={"wer hat sie verfasst","verfasser von podrigs anforderungsliste"}},{q="Wer erhält die Anforderungsliste?",a="Gordon Wendheim, ein Waffenhändler im Handwerksviertel der Unterstadt, soll die Anforderungsliste erhalten.",al={"wer erhält die anforderungsliste","wohin geht podrigs anforderungsliste","empfänger von podrigs anforderungsliste"}},{q="Warum braucht das Grabmal neue Waffen?",a="Bei Scharmützeln mit der Geißel und anderen feindlichen Mächten im Silberwald geht die Ausrüstung der Todeswachen oft zu Bruch oder verloren. Sie brauchen Ersatzwaffen.",al={"warum werden waffen gebraucht","waffenmangel im grabmal"}}},fx={["92a3bbc0"]={q="Was ist Podrigs Anforderungsliste?",a="Podrigs Anforderungsliste ist ein offizielles Anforderungsdokument der Verlassenen, das verfasst wurde, um frische Bewaffnung für den Außenposten am Grabmal sicherzustellen. Die von Podrig im Namen von Executor Hadrec verfasste Schriftrolle listet Ersatzwaffen auf, die die Todeswachen der Garnison benötigen, um ihre ständigen Zusammenstöße gegen die Geißel und andere Schrecken, die im Silberwald lauern, zu überstehen.",al={"was ist podrigs anforderungsliste","gegenstand podrigs anforderungsliste","podrig anforderung"}},["6fc9fe58"]={q="Warum benötigt Gordon Wendheim Podrigs Anforderungsliste?",a="Als Waffenhändler im Handwerksviertel der Unterstadt benötigt Gordon Wendheim die formelle Anforderung, um das Versorgungsgesuch der Garnison zu prüfen und zu erfüllen. Ohne dieses verifizierte Manifest kann das Grabmal die notwendige Lieferung an Klingen und Ausrüstung nicht erhalten, um seine Todeswachen an der Front neu auszustatten.",al={"warum will gordon wendheim die anforderungsliste","warum podrigs anforderungsliste in die unterstadt bringen","warum wird podrigs anforderungsliste benötigt"}}},fp="14,82,20.335.0,24.268.0,34.124.0,25.121.0,23.96.0,40.152.0"}
P.entries["item:pork-belly-pie"] = {n="Schweinebauchpastete",s="Im Wald von Elwynn wartet Billy Maclure auf eine Pastete vom Hof der Steinfelds, bevor er über eine vermisste Halskette spricht. Tante Bernice backt sie trotz der langen Fehde zwischen den Familien.",h="Im Wald von Elwynn wartet Billy Maclure auf eine Pastete vom Hof der Steinfelds, bevor er über eine vermisste...",kw={"tante bernice steinfeld","back to billy","billy maclure","wald von elwynn","maclure","schweinebauchpastete","steinfeld"},ang={["faction:Alliance"]="Reisenden der Allianz, die im ländlichen Elwynn helfen, offenbart das Ausliefern von Pasteten die tief verwurzelten Streitigkeiten im bäuerlichen Kernland von Sturmwind.",["profession:Cooking"]="Tante Bernices hausgemachte Pastete hat selbst inmitten der Familienfehde großen Einfluss, doch ihr Rezept bleibt ein Geheimnis."},sec={{t="Bestechung zwischen verfeindeten Höfen",b="Die Familien Steinfeld und Maclure streiten seit Jahren um Land und Stolz. Der junge Billy Maclure hat eine Schwäche für Tante Bernices Schweinebauchpastete. Als eine wertvolle Halskette der Familie Steinfeld verschwindet, weigert sich Billy, sein Wissen preiszugeben, bis ein Abenteurer ihm ein warmes Stück bringt. Bernice backt sie widerwillig und wünscht sich, der gierige Junge möge daran ersticken."}},faq={{q="Wofür wird die Schweinebauchpastete verwendet?",a="Tante Bernice Steinfeld backt die Pastete, um den jungen Billy Maclure zum Reden zu bringen. Er weiß etwas über die vermisste Halskette der Familie Steinfeld, weigert sich aber zu reden, bis er etwas von ihrer Kochkunst bekommt.",al={"verwendung der pastete","warum schweinebauchpastete","was tun mit der pastete"}},{q="Wer backt die Schweinebauchpastete?",a="Tante Bernice Steinfeld backt die Pastete auf dem Hof der Steinfelds. Sie hegt Groll gegen Billy Maclure und seine Familie, bereitet sie aber zu, um die verlorene Halskette ihrer Familie zurückzubekommen.",al={"wer hat die pastete gemacht","wer backt die pastete","oma steinfelds pastete"}},{q="Warum will Billy Maclure Essen von einer verfeindeten Familie?",a="Billy Maclure will trotz der Fehde zwischen den Steinfelds und den Maclures etwas von Tante Bernices Kochkunst. Die Schweinebauchpastete ist ihm wichtiger, als den Groll seiner Familie aufrechtzuerhalten.",al={"warum billy pastete will","warum maclure essen von steinfeld will"}},{q="Können Spieler die Schweinebauchpastete essen?",a="Nein. Die Pastete ist für Billy Maclure bestimmt und kann nicht gegessen werden, um Gesundheit oder Mana wiederherzustellen.",al={"kann man sie essen","ist schweinebauchpastete essbar"}}},fx={["6505ed9f"]={q="Was ist die Schweinebauchpastete?",a="Es ist eine herzhafte Fleischpastete, die mit Schweinebauch gebacken wird und dafür bekannt ist, trotz der erbitterten Fehde zwischen den beiden Bauernfamilien im südlichen Wald von Elwynn köstlich zu sein. Frisch zubereitet in der Küche der Steinfelds, dient sie als leckeres Bestechungsmittel, um Informationen aus dem Jungen der Maclures, Billy, herauszulocken, der behauptet, sein Gedächtnis funktioniere nur mit vollem Magen.",al={"was ist schweinebauchpastete","schweinebauchpastete hintergrund","über die schweinebauchpastete"}}},fp="14,167,29.366.0,36.188.0,29.161.0,53.181.0,35.85.0"}
P.entries["item:powdered-azurite"] = {n="Pulverisierter Azurit",s="Im Vorgebirge des Hügellands zermahlen Arbeiter blauen Stein aus dem Azurschacht zu Pulverisiertem Azurit. Thun'grim Brandblick braucht ihn, um brutale Rüstungen für aufstrebende Krieger der Horde zu schmieden.",h="Im Vorgebirge des Hügellands zermahlen Arbeiter blauen Stein aus dem Azurschacht zu Pulverisiertem Azurit.",kw={"der azurschacht","azurit","brutal armor","hillsbrad","pulverisierter azurit","reagenz","thun'grim firegaze"},ang={["class:Warrior"]="Als Krieger stellt Ihr in der Fremde Eure Ausdauer auf die Probe, während Ihr Pulverisierten Azurit für Thun'grim Brandblick sammelt. Er braucht das Reagenz, um Eure Rüstung von wilder Stärke zu schmieden.",["faction:Horde"]="Als Mitglied der Horde müsst Ihr tief in die Östlichen Königreiche vorstoßen und im Vorgebirge des Hügellands verfeinerten Staub aus den Händen der Allianz erbeuten."},sec={{t="Eine seltene Mineralverbindung",b="Menschliche Arbeiter bauen blauen Stein aus Mineraladern unter dem Vorgebirge des Hügellands ab. Sie zermahlen und verpacken ihn für den Handel und die Metallverarbeitung. Ein geschickter Schmied mischt den Staub mit dichten Metallen und macht Rüstungen dadurch haltbarer und widerstandsfähiger."},{t="Brutal Armor schmieden",b="Schmiede der Horde schätzen Pulverisierten Azurit für seine stärkende Wirkung bei der Metallverarbeitung, obwohl das Mineral aus Tunneln unter menschlicher Kontrolle jenseits des großen Meeres stammt. Thun'grim Brandblick ist ein alternder Orc-Rüstungsschmied im Brachland. Er verlangt kleine Mengen davon sowie veredeltes Eisen und feurige Reagenzien. Der Schmelze beigemischt, hilft ihm das Pulver, die schweren Platten seiner Brutal Armor zu schmieden."}},faq={{q="Wofür wird Pulverisierter Azurit verwendet?",a="Thun'grim Brandblick mischt Pulverisierten Azurit mit Eisenbarren und flüchtigen Reagenzien, um Teile der Brutal Armor für Champions der Horde zu schmieden.",al={"pulverisierter azurit verwendung","was ist pulverisierter azurit"}},{q="Wo findet man Pulverisierten Azurit?",a="Menschliche Bergleute gewinnen Pulverisierten Azurit im Azurschacht an der Südküste des Vorgebirges des Hügellands in den Östlichen Königreichen.",al={"wo findet man pulverisierten azurit","pulverisierter azurit fundort","wer lässt pulverisierten azurit fallen"}},{q="Warum braucht ein Rüstungsschmied im Brachland Reagenzien aus Hillsbrad?",a="Thun'grim Brandblick sucht erlesene Materialien für Rüstungen, die legendärer Krieger würdig sind. Eisen ist leicht zu finden, doch das Mineral aus dem Azurschacht härtet Metall, also schickt er seine Champions übers Meer, um es zu beschaffen.",al={"warum hillsbrad","thungrim mineralquelle"}}},fx={["139f7c50"]={q="Was ist Pulverisierter Azurit?",a="Pulverisierter Azurit ist ein zerkleinertes blaues Mineralreagenz, das aus tiefen Adern im Vorgebirge des Hügellands gewonnen wird. Von meisterhaften Rüstungsschmieden wegen seiner einzigartigen metallurgischen Eigenschaften verehrt, kann das feine Pulver beim Schmieden mit Basismetallen legiert oder gehärtet werden. Es wird besonders von Thun'grim Brandblick, dem Rüstungsschmied der Horde, geschätzt, der es zusammen mit exotischen Reagenzien verwendet, um schwere, widerstandsfähige Kettenrüstungen herzustellen, die ruhmreichen Kriegern würdig sind.",al={"was ist azuritpulver","pulverisierter azurit hintergrund","pulverisierter azurit gegenstand"}},["720f3d61"]={q="Woher stammt Pulverisierter Azurit und wer hat ihn abgebaut?",a="Die Substanz wird im Azurschacht abgebaut, der in den südlichen Hügeln des Vorgebirge des Hügellands liegt. Menschliche Bergleute, die in den unterirdischen Schächten des Azurschachts arbeiten, fördern das rohe Azuriterz und mahlen es zu einem raffinierten Pulver. Da die Mine unter der festen Kontrolle der menschlichen Arbeiter von Hillsbrad bleibt, erfordert die Beschaffung des Pulvers, es direkt von den Bergleuten zu nehmen, die unter der Erde arbeiten.",al={"wo bekommt man pulverisierten azurit","wer baut pulverisierten azurit ab","quelle für pulverisierten azurit"}}},fp="16,168,23.218.0,20.366.0,34.133.0,36.128.0,67.193.0"}
P.entries["item:powers-of-the-void"] = {n="Macht der Leere",s="In Nordhain erregt ein gestohlener Foliant Drusilla La Salles Aufmerksamkeit. Ein Novize nahm Macht der Leere aus einem bewachten Flügel der Bibliothek der Abtei von Nordhain mit, als er zur Bruderschaft der Defias überlief. Drusilla sucht das Buch für ihre eigenen Studien der dunklen Magie.",h="In Nordhain erregt ein gestohlener Foliant Drusilla La Salles Aufmerksamkeit.",kw={"bruderschaft der defias","drusilla la salle","wichtel","khadgar","abtei von nordhain","macht der leere","gestohlene bücher","the stolen tome","hexenmeister"},ang={["class:Warlock"]="Als Hexenmeister stellt Euch die Wiederbeschaffung des gestohlenen Folianten auf die Probe: Habt Ihr den Willen, Euch die Unterweisung in der Wichtelbeschwörung zu verdienen?",["race:Human"]="Als Mensch könnt Ihr erkennen, dass Nordhains Holy Order gefährliche magische Aufzeichnungen neben klerikalen Texten aufbewahrt, verborgen vor den Augen der Novizen."},sec={{t="Ein gesperrter Text aus Nordhain",b="Macht der Leere wurde hinter bewachten Regalen in der Bibliothek der Abtei von Nordhain aufbewahrt. Die Archive der Abtei bergen heilige Schriften und klerikale Aufzeichnungen ebenso wie wissenschaftliche Werke über Schatten- und Netherenergien. Erzmagier Khadgar soll den Folianten verfasst haben. Sein Thema war gefährlich, weshalb die Verantwortlichen der Abtei ihn bewachen ließen und gewöhnlichen Besuchern vorenthielten. Deshalb konnte Drusilla La Salle, Nordhains Hexenmeisterlehrerin, ihn nicht durchblättern, ohne den Verdacht der Priesterschaft zu erregen."},{t="Diebstahl und Wiederbeschaffung",b="Ein Novize aus Nordhain nahm den Folianten mit, als er seine Gelübde brach, um sich der Bruderschaft der Defias anzuschließen. Bei seiner Flucht in die benachbarten Weinberge nahm er mehrere wertvolle Bände aus der Abtei mit. Drusilla schickt vielversprechende Hexenmeister-Initianden ins Banditenlager der Defias, um das Buch aus ihren Zelten zurückzuholen. Sie will dessen dunkles Wissen für ihre eigenen Studien. Die Aufgabe prüft, ob ein Initiand die nötigen Nerven hat, um jenseitige Dämonen zu binden."}},faq={{q="Was ist Macht der Leere?",a="Macht der Leere ist ein seltenes okkultes Buch über Schatten- und Netherenergien, das Erzmagier Khadgar verfasst haben soll. Vor dem Diebstahl wurde der Foliant in einem bewachten Flügel der Bibliothek der Abtei von Nordhain aufbewahrt.",al={"was ist macht der leere","macht der leere buch","was ist the stolen tome"}},{q="Warum war das Buch in der Abtei von Nordhain unter Verschluss?",a="Die Abtei von Nordhain bewahrt historische Archive auf, darunter gefährliche Texte über verbotene Magie. Bücher über Leerenenergien und Dämonologie werden weggeschlossen, damit Novizen und fehlgeleitete Magiewirker sie nicht missbrauchen können.",al={"warum war es in der abtei","warum hatten die priester es","nordhain bibliotheksflügel"}},{q="Wie kam die Bruderschaft der Defias an das Buch?",a="Ein Novize der Abtei von Nordhain lief zur Bruderschaft der Defias über und nahm mehrere wertvolle Bände aus der gesperrten Bibliothek mit. Er versteckte sie im Banditenlager in den Weinbergen von Nordhain.",al={"wer hat das buch gestohlen","defias gestohlene bücher","wie kamen die defias daran"}},{q="Warum will Drusilla La Salle Macht der Leere?",a="Drusilla La Salle will das Wissen des Folianten für ihre eigene dunkle Kunst. Als Nordhains Hexenmeisterlehrerin konnte sie die bewachte Bibliothek der Abtei nicht betreten, ohne Verdacht zu erregen.",al={"warum will drusilla es","wer will das buch","drusilla la salle gestohlener foliant"}},{q="Was beweist die Wiederbeschaffung des Folianten Drusilla?",a="Die Wiederbeschaffung des Folianten prüft, ob ein Initiand die nötigen Nerven hat, um Dämonen zu binden. Drusilla nutzt diese Prüfung, bevor sie Initianden lehrt, ihren ersten Wichtel zu beschwören.",al={"warum brauchen hexenmeister das buch","wichtelbeschwörung prüfung","gestohlener foliant belohnung"}}},fx={["082e56cb"]={q="Wer hat „Macht der Leere“ verfasst?",a="Es wird angenommen, dass diese arkanwissenschaftliche Abhandlung von dem legendären Erzmagier Khadgar verfasst wurde, der viele tiefgründige und gefährliche Aspekte der Magie studierte, bevor er sich hinter Das Dunkle Portal wagte. Ihre verbotenen Einblicke in die tiefere Leere wurden als viel zu gefährlich für das beiläufige Lesen erachtet, was die Priester und Gelehrten der Abtei von Nordhain dazu veranlasste, sie in einem geschützten Flügel ihrer Bibliothek zu versiegeln, bis ein verräterischer Novize sie stahl.",al={"autor von macht der leere","wer hat macht der leere gemacht","schöpfer von macht der leere"}}},fp="18,251,28.476.0,25.427.0,27.217.0,47.198.0,44.183.0,51.175.0,48.147.0"}
P.entries["item:prairie-alpha-tooth"] = {n="Präriealphazahn",s="Nahe Donnerfels durchstreifen Präriewolfalphas die offenen Ebenen von Mulgore. Mull Donnerhorn braucht ihre Zähne, um den Brunnen der Wildmähnen zu reinigen.",h="Nahe Donnerfels durchstreifen Präriewolfalphas die offenen Ebenen von Mulgore.",kw={"dorf der bluthufe","mulgore","mull donnerhorn","präriealphazahn","präriewolfalpha","wasserbrunnen","wildmane totem"},ang={["class:Shaman"]="Als Schamane besänftigt Ihr die Geister der Brunnen, indem Ihr das Gleichgewicht der Erde wiederherstellt. Die Fangzähne eines Spitzenjägers als Opfergabe festigen diese natürliche Harmonie.",["race:Tauren"]="Als Tauren ehrt Ihr mit dem Erbeuten eines Präriealphazahns Eure heilige Pflicht als Jäger. Sammelt mit Respekt, was benötigt wird, und gebt dann diese ursprüngliche Essenz zurück, um die vergiftete Erde zu heilen."},sec={{t="Eine reinigende Opfergabe",b="Die Brunnen von Mulgore versorgen die Tauren, und Riten des Respekts und des Opfers halten sie rein. Mull Donnerhorn aus dem Dorf der Bluthufe braucht Zähne von den Präriewolfalphas unterhalb von Donnerfels, um den Brunnen der Wildmähnen zu reinigen. Diese wilden Rudelführer verkörpern die Stärke der Wildnis. Ihre Zähne ehren das Gleichgewicht zwischen Jäger, Beute und den Geistern der Erde."}},faq={{q="Wozu dient ein Präriealphazahn?",a="Mull Donnerhorn verwendet acht Präriealphazähne in einem Ritual, um den Brunnen der Wildmähnen zu reinigen. Er ist der letzte verseuchte Brunnen nahe dem Dorf der Bluthufe.",al={"alphazahn verwendung","wozu dienen wolfszähne in mulgore","wildmane totem gegenstand"}},{q="Wo streifen Präriewolfalphas umher?",a="Präriewolfalphas durchstreifen die offenen Grasebenen von Mulgore, besonders die mittleren und nördlichen Gebiete nahe den Klippen am Fuße von Donnerfels.",al={"wo sind präriewolfalphas","alphawolf fundorte","präriewolfalpha fundorte"}},{q="Warum braucht ein Wasserreinigungsritual Wolfszähne?",a="Die Riten der Tauren ehren das Gleichgewicht der Natur. Die Reinigung verlangt heilige Körperteile der wilden einheimischen Tiere von Mulgore, Symbole des Opfers und der Lebenskraft seiner Tierwelt.",al={"warum wolfszähne für wasser","mull donnerhorn zahnritual hintergrund"}}},fx={f1f3b80c={q="Was ist ein Präriealphazahn?",a="Ein Präriealphazahn ist ein Zahn, der einem Präriealphawolf entnommen wurde, einem der wildesten Rudelführer, die durch die Ebenen von Mulgore streifen. Unter den Tauren repräsentieren diese Reißzähne die Stärke und den Geist der Spitzenprädatoren des Landes und tragen spirituelles Gewicht, wenn sie in Ritualen dargebracht werden.",al={"präriealphazahn","was ist präriealphazahn","präriealphawolftahn"}},["0674aadd"]={q="Woher stammt ein Präriealphazahn?",a="Diese Zähne werden von Präriealphawölfen geerntet, die das Grasland von Mulgore durchstreifen, insbesondere in der Nähe der Basis von Donnerfels im Norden. Da es sich um natürliche Reißzähne lebender Raubtiere handelt, werden sie während der Jagd direkt von den Bestien genommen und nicht von sterblichen Händen gefertigt.",al={"woher kommen präriealphazähne","präriealphazahn ursprung","wer lässt präriealphazahn fallen"}}},fp="19,134,20.357.0,39.147.0,34.146.0,53.169.0"}
P.entries["item:prairie-wolf-heart"] = {n="Herz eines Präriewolfs",s="Maur Regenrufer im Dorf der Bluthufe braucht ein Herz eines Präriewolfs, um einen giftigen Biss zu behandeln.",h="Maur Regenrufer im Dorf der Bluthufe braucht ein Herz eines Präriewolfs, um einen giftigen Biss zu behandeln.",kw={"dorf der bluthufe","maur regenrufer","mazzranache","mulgore","prairie stalker","herz eines präriewolfs","wolfsherz"},ang={["class:Hunter"]="Als Jäger lernt Ihr, die Wolfsrudel aufzuspüren, die in den Ebenen von Mulgore jagen, und die dort lebenden Tiere zu verstehen.",["race:Tauren"]="Als Tauren wisst Ihr, dass sich aus Tierteilen nützliche Heilmittel für das Überleben in Mulg ores Wildnis herstellen lassen."},sec={{t="Ein Heilmittel gegen einen giftigen Biss",b="Maur Regenrufer lebt im Dorf der Bluthufe, wo das Gift von Mazzranache, dem legendären Ebenenschreiter, bei ihm Fieber ausgelöst hat. Der Biss droht, das Gift in seinem Körper zu verbreiten. Maur sucht ein Präriewolfherz, einen Cougarknochen und einen Vogelmuskelmagen für ein traditionelles Heilmittel der Ebenen. Er hofft, die Infektion aufzuhalten, bevor das Delirium tödlich wird."}},faq={{q="Wofür wird ein Herz eines Präriewolfs verwendet?",a="Maur Regenrufer im Dorf der Bluthufe braucht ein Herz eines Präriewolfs für ein Volksheilmittel. Er kombiniert es mit anderen Tierteilen, um den giftigen Biss zu behandeln, den Mazzranache ihm zugefügt hat.",al={"wolfsherz verwendung","warum wolfsherz beschaffen","herz eines präriewolfs zweck"}},{q="Wo erhält man ein Herz eines Präriewolfs?",a="Präriewölfe, prairie wolf alphas und prairie stalkers jagen in den Ebenen von Mulgore. Ihre Körper liefern das Herz.",al={"wolfsherz fundort","wer lässt wolfsherz fallen","herz eines präriewolfs finden"}},{q="Warum braucht Maur Regenrufer Tierorgane, um seine Wunde zu behandeln?",a="Mazzranaches infizierter Biss verursacht Fieber und Delirium. Maur vertraut auf Heilmittel der Tauren aus den Ebenen mit einem Wolfsherz, einem Cougaroberschenkelknochen, einer Schuppe eines Ebenenschreiters und einem Muskelmagen eines Sturzfliegers, um die Infektion zu beseitigen, bevor sie tödlich wird.",al={"warum wolfsherz als medizin","maurs heilmittel"}},{q="Kann jedes Wolfsherz für das Heilmittel verwendet werden?",a="Maur bittet um ein Wolfsherz. Das Herz für sein Heilmittel stammt von Präriewölfen, prairie wolf alphas oder prairie stalkers aus den Ebenen von Mulgore.",al={"jedes wolfsherz","welche wölfe lassen es fallen"}}},fx={ee1c9772={q="Was ist ein Herz eines Präriewolfs?",a="Ein Herz eines Präriewolfs ist das geerntete Organ der räuberischen Wölfe, die durch die wogenden Ebenen von Mulgore streifen. Obwohl es wenig allgemeinen Handelswert besitzt, macht die Vitalität des Herzens eines wilden Tieres es zu einer geschätzten Zutat in der traditionellen Medizin der Tauren. Es dient als eines von mehreren wirksamen Reagenzien, die benötigt werden, um Heilmittel zu brauen, die in der Lage sind, virulente natürliche Gifte und tiefe Infektionen zu beseitigen.",al={"was ist herz eines präriewolfs","herz eines präriewolfs","über herz eines präriewolfs"}},["1392571f"]={q="Woher stammt ein Herz eines Präriewolfs?",a="Das Herz wird direkt von den wilden Präriewölfen, Präriealphawölfen und Präriepirschern genommen, die auf den grasbewachsenen Plateaus von Mulgore heimisch sind. Es ist ein natürliches biologisches Organ, das einem getöteten Raubtier entnommen wurde, anstatt ein von sterblichen Händen gefertigtes Objekt.",al={"woher stammt herz eines präriewolfs","ursprung von herz eines präriewolfs","wer hat herz eines präriewolfs gemacht"}}},fp="18,89,28.330.0,38.170.0,43.121.0,63.220.0,42.143.0"}
P.entries["item:prairie-wolf-paw"] = {n="Präriewolftatze",s="In ganz Mulgore jagen Präriewölfe über die Ebenen, und ihre Tatzen werden für die Arbeit eines Schamanen gesammelt. Im Dorf der Bluthufe verbindet Mull Donnerhorn sie mit Ebenenschreiterkrallen, um ein Reinigungstotem herzustellen.",h="In ganz Mulgore jagen Präriewölfe über die Ebenen, und ihre Tatzen werden für die Arbeit eines Schamanen...",kw={"dorf der bluthufe","mulgore","mull donnerhorn","ebenenschreiterkralle","poison water","präriewolf","präriewolftatze","brunnen der winterhufe"},ang={["class:Shaman"]="Als Schamane nutzt Ihr Reinigungstotems aus Körperteilen einheimischer Tiere, um die lebendige Essenz des Landes anzurufen und unnatürliche Verderbnis zu beseitigen.",["race:Tauren"]="Als Tauren sammelt Ihr Wolftatzen, um das Land zu bewahren. Seine einheimischen Tiere helfen, uralte Wasserbrunnen zu heilen, die durch die Gier der Goblins verunreinigt wurden."},sec={{t="Natürliche Reagenzien der Ebenen",b="Präriewölfe jagen in Rudeln durch Mulgores Grasland, zusammen mit Präriepirschern und ihren Rudelalphas. Sie bedrohen junge Jäger und das einheimische Vieh. Taurenschamanen betrachten die Tatzen als mehr als Trophäen, denn sie tragen die natürliche Lebenskraft des Landes und sind für das spirituelle Gleichgewicht der Ebenen wichtig."},{t="Die Reinigung der Brunnen",b="Als Unternehmungen der Goblins Mulgores heilige Wasservorräte verunreinigten, brauchte der Schamane Mull Donnerhorn die Hilfe des Landes gegen die Verschmutzung. Verbunden mit Ebenenschreiterkrallen verleihen Wolftatzen Reinigungstotems spirituelle Resonanz. Sobald das Totem fertig ist, kann die Reinigung des Brunnens der Winterhufe beginnen."}},faq={{q="Welche Kreaturen lassen eine Präriewolftatze fallen?",a="Präriewölfe, Präriepirscher und Präriewolfalphas jagen in Mulgores Ebenen, vor allem südwestlich vom Dorf der Bluthufe, und liefern Präriewolftatzen.",al={"wer lässt präriewolftatzen fallen","wo gibt es präriewolftatzen","präriewolftatze quelle"}},{q="Wer braucht Präriewolftatzen?",a="Mull Donnerhorn, ein Taurenschamane im Dorf der Bluthufe, braucht die Tatzen, um ein Reinigungstotem für die verunreinigten Wasserbrunnen herzustellen.",al={"wer braucht präriewolftatzen","mull donnerhorn wolftatzen","präriewolftatze abgeben"}},{q="Warum werden Wolftatzen zur Wasserreinigung gebraucht?",a="Taurenschamanen rufen die natürliche Lebenskraft des Landes gegen Verderbnis an. Verbunden mit Vogelkrallen binden Wolftatzen Mulgores lebendigen Geist in ein elementares Totem, das Goblingifte beseitigen kann.",al={"warum wolftatzen","präriewolftatze hintergrundgeschichte","warum will mull tatzen"}},{q="Bei der Reinigung welches Brunnens helfen diese Tatzen?",a="Die Tatzen helfen bei der Herstellung eines Reinigungstotems für den Brunnen der Winterhufe, den eingedrungene Goblins und ihre Handlanger vergiftet haben.",al={"welcher brunnen","brunnen der winterhufe reinigung"}}},fx={["94c15e4c"]={q="Was ist eine Präriewolftatze?",a="Eine Präriewolftatze ist eine natürliche rituelle Komponente, die von den wilden Hunden geerntet wird, die durch die Ebenen von Mulgore streifen. Anstatt als bloße Trophäen zu dienen, tragen diese Tatzen die lebendige Essenz des Landes in sich, was sie für Schamanen der Tauren wertvoll macht, die Totems herstellen, um die Erde zu heilen und zu bewahren.",al={"präriewolftatze","was sind präriewolftatzen","wolftatze mulgore"}},["7a637be5"]={q="Woher stammen Präriewolftatzen?",a="Diese Tatzen werden direkt von Präriewölfen, Präriepirschern und Wolfalphas geerntet, die auf den grasbewachsenen Plateaus von Mulgore heimisch sind. Sie sind natürliche Teile der Wildnis, die von Jägern genommen werden, um in Zeiten spiritueller Not die Stärke des Landes anzubieten.",al={"woher kommen präriewolftatzen","präriewolftatze quelle","wer lässt wolftatzen fallen"}}},fp="16,198,30.301.0,19.306.0,39.155.0,28.130.0,42.193.0,44.116.0"}
P.entries["item:pridewing-venom-sac"] = {n="Prachtschwingengiftbeutel",s="Am Mirkfallonsee erregt das Gift der Prachtschwingen die Aufmerksamkeit der Nachtelfen von Astranaar. Berichten zufolge sammeln Agenten der Horde es für verdeckte Angriffe, und die Schildwachen wollen ihnen dieses Gift vorenthalten.",h="Am Mirkfallonsee erregt das Gift der Prachtschwingen die Aufmerksamkeit der Nachtelfen von Astranaar.",kw={"astranaar","mirkfallonsee","prachtschwinge","shindrell feuerflink","steinkrallengebirge","giftbeutel","wyvern"},ang={["faction:Alliance"]="Agenten der Horde das Prachtschwingengift vorzuenthalten, hilft, Grenzpatrouillen entlang der umkämpften Grenzen des Steinkrallengebirges und Eschentals vor ungesehenen Assassinen zu schützen.",["race:NightElf"]="Als Nachtelf bedauert Ihr vielleicht, dass unschuldige wilde Bestien gejagt werden müssen. Dennoch hat der Schutz elfischer Leben vor vergifteten Klingen Vorrang."},sec={{t="Gefahr in den Klippen",b="Prachtschwingen jagen in den Klippen südlich von Eschental, besonders nahe dem Mirkfallonsee. Diese Flugräuber sind im Steinkrallengebirge heimisch, durchstreifen aber auch diese Gegend, und ihr Gift befindet sich in Drüsen in ihrem Körper. Berichten aus Theramore zufolge bestreichen Assassinen der Horde ihre Klingen mit dem Gift für heimliche Angriffe auf Nachtelfensiedlungen. Deshalb entsenden die Schildwachen von Astranaar Späher, um die Wyvern zu jagen und ihre Drüsen einzusammeln, bevor Agenten der Horde sie an sich bringen können."}},faq={{q="Von welchen Kreaturen erhält man einen Prachtschwingengiftbeutel?",a="Junge Prachtschwingen, Himmelsjäger, Patriarchen und Gefährtinnen nahe dem Mirkfallonsee liefern die Giftbeutel.",al={"woher pra chtschwingengiftbeutel","wer lässt prachtschwingengiftbeutel fallen","quellen für prachtschwingengift"}},{q="Warum will Astranaar Prachtschwingengiftbeutel?",a="Shindrell Feuerflink liegen Berichte vor, dass Agenten der Horde Prachtschwingengift auf Waffen auftragen, um lautlose Angriffe gegen die Allianz auszuführen. Die Drüsen an sich zu nehmen oder zu zerstören, kann diese Angriffe verhindern.",al={"warum giftbeutel sammeln","shindrell feuerflink gift"}},{q="Wer nimmt diese Giftbeutel in Eschental entgegen?",a="In Astranaar, der Nachtelfenstadt in Eschental, sammelt Shindrell Feuerflink die Giftbeutel, um ihr Volk vor verdeckten Angriffen zu schützen.",al={"wer nimmt prachtschwingengift","prachtschwingenquest abgeben"}},{q="Sind die Prachtschwingen von Natur aus mit der Horde verbündet?",a="Nein. Die Prachtschwingen nahe dem Mirkfallonsee sind wilde Bestien, keine willigen Verbündeten der Horde. Orcagenten nutzen ihr Gift für die Kriegsführung.",al={"gehören prachtschwingen zur horde","arbeiten prachtschwingen für orcs"}}},fx={e2bba8d5={q="Was ist ein Prachtschwingengiftbeutel?",a="Ein Prachtschwingengiftbeutel ist ein Organ, das von den Prachtschwingenwyvern geerntet wird, die in den Steinkrallengebirge nisten. Er enthält die wirksamen natürlichen Toxine, die diese geflügelten Raubtiere produzieren, um ihre Beute zu unterwerfen. Im fragilen Patt zwischen den Nachtelfen und der Horde ist solches Gift zu einer geschätzten Waffe für verdeckte Angriffe geworden, was die Verteidiger von Astranaar aufhorchen lässt.",al={"was ist prachtschwingengiftbeutel","prachtschwingengiftbeutel gegenstand","was sind prachtschwingengiftbeutel"}},["816b56c2"]={q="Woher stammt ein Prachtschwingengiftbeutel?",a="Diese Beutel werden direkt aus den Körpern von Prachtschwingen geerntet – wilden, grimmigen Wyvern, die in der Nähe vom Mirkfallonsee in den Steinkrallengebirge nisten. Da es sich um natürliche Körperorgane handelt, die von den Bestien selbst produziert werden, und nicht um Fabrikate, erfordert ihre Beschaffung die Jagd auf die Wyvern durch das zerklüftete Gebirge und die Sicherung des Gifts, bevor Agenten der Horde es ernten können.",al={"prachtschwingengiftbeutel quelle","woher kommen prachtschwingengiftbeutel","wer lässt prachtschwingengiftbeutel fallen"}}},fp="19,193,21.446.0,43.97.0,45.181.0,42.133.0,51.133.0"}
P.entries["item:prismatic-punch-card"] = {n="Prismalochkarte",s="In Gnomeregan trägt die Prismalochkarte die höchste Sicherheitsfreigabe. Gnomische Flüchtlinge in Eisenschmiede suchen die Aufzeichnungen, die sie zugänglich macht.",h="In Gnomeregan trägt die Prismalochkarte die höchste Sicherheitsfreigabe.",kw={"castpipe","data rescue","engineering labs","gnomeregan","matrixlochograph","prismalochkarte"},ang={["profession:Engineering"]="Als Ingenieur könnt Ihr die schrittweise Lochkartenprogrammierung und ein automatisiertes Terminalnetzwerk als Beispiele für den hohen Standard der Rechenmaschinen sehen, die Gnomeregans Tüftler bauten.",["race:Gnome"]="Als Gnom könnt Ihr im Sicherheitssystem der Punchographs gnomischen Erfindungsgeist und Bürokratie erkennen, die auch nach dem Fall Eurer Heimat weiterwirken."},sec={{t="Eine Frage der Sicherheit",b="Als die Gnome aus Gnomeregan flohen, trieben Troggs und toxische Verstrahlung sie aus der Stadt. Gewaltige Bestände an Forschungsdaten und Zivilaufzeichnungen blieben in ihren Tiefen zurück. Die Gnome schützten hochrangige Systeme durch gestaffelte Freigabestufen. Um den Matrixlochograph 3005-D in den unteren Engineering Labs zu erreichen, muss eine Karte eine Reihe von Terminals durchlaufen.\n\nDie Karte beginnt weiß und durchläuft dann Gelb, Blau und Rot. Am letzten Terminal wird sie zur Prismalochkarte gestanzt. Ihre codierte Freigabestufe ist mit dem Vermerk angegeben, dass sie auf die Erfindung einer völlig neuen Zahl wartet."},{t="Die lebenswichtige Übertragung",b="Mechanikermeister Castpipe schickt Abenteurer aus den Flüchtlingsenklaven von Eisenschmiede in die verseuchten Hallen von Gnomeregan, um Daten zu bergen, die er für lebenswichtig und unverzichtbar hält. Die binäre Nachricht auf der Prismalochkarte enthüllt den Inhalt der Übertragung: Castpipe wird mitgeteilt, dass seine Wäsche zur Abholung bereitliegt."}},faq={{q="Wie stellt Ihr eine Prismalochkarte her?",a="Steckt eine Rote Lochkarte in den Matrixlochograph 3005-D in den unteren Engineering Labs von Gnomeregan. Wertet zunächst eine Weiße Lochkarte nacheinander an den Terminals der Modelle A, B und C im gesamten Komplex auf.",al={"prismalochkarte erhalten","prismalochkarte herstellen","lochkarte aufwertungsreihenfolge"}},{q="Welche Daten sind auf der Prismalochkarte gespeichert?",a="Die Karte gibt ihre Sicherheitsstufe als auf die Erfindung einer neuen Zahl wartend an und enthält danach eine lange Folge von Binärcode. Mechanikermeister Castpipe sagt, die Daten seien lebenswichtig.",al={"was steht auf der karte","lochkarte binärcode übersetzung","entschlüsselte lochkarte"}},{q="Wer will die Prismalochkarte?",a="Mechanikermeister Castpipe, ein im Exil lebender gnomischer Ingenieur in Eisenschmiede, verlangt die Karte im Rahmen von Data Rescue. Er sagt, sie enthalte dringende, unschätzbar wertvolle Informationen, die zurückblieben, als die Gnome Gnomeregan evakuierten.",al={"wer gibt die prismalochkarte ab","castpipe quest","wer braucht die karte"}},{q="Wo befinden sich die Matrixlochograph-Terminals?",a="Die Terminals sind nach Freigabestufe über Gnomeregan verteilt. Punchograph 3005-A befindet sich nahe dem oberflächennahen Train Depot und dem Workshop Entrance. Modell B steht im Dormitory jenseits der Clean Zone, Modell C liegt tiefer im Komplex und Modell D in den unteren Engineering Labs.",al={"terminalstandorte","wo sind die punchographs","wo lochkarten stanzen"}}},fx={f4168582={q="Was ist eine Prismalochkarte?",a="Eine Prismalochkarte ist eine Datenkarte mit außergewöhnlich hoher Freigabestufe, die von den Rechensystemen innerhalb von Gnomeregan generiert wird. Ihre automatisierte Sicherheitsklassifizierung ist angeblich so hoch, dass die gnomische Mathematik noch keine angemessene Zahl erfunden hat, um sie zu beschreiben. In Wahrheit enthält sie kodierten Binärtext, der von Terminals tief in der Stadt produziert wurde, und fungiert als Höhepunkt des abgestuften Datenabrufprotokolls der Gnome.",al={"was ist prismalochkarte","prismalochkarte hintergrund","prismakarte gnomeregan"}},["7551673e"]={q="Woher stammt die Prismalochkarte und wer hat sie hergestellt?",a="Die Karte wird tief in der gefallenen Stadt Gnomeregan vom Matrix Punchograph 3005-D produziert, einem hochsicheren automatisierten Terminal, das sich auf der unteren Ebene der Engineering Labs befindet. Sie ist nicht von Hand gefertigt, sondern wird vom mechanisierten Netzwerk der Gnome kodiert, wenn ein Benutzer eine korrekt aufgerüstete Rote Lochkarte in das Gerät einführt.",al={"ursprung der prismalochkarte","wer hat prismalochkarte hergestellt","wo bekommt man prismalochkarte"}}},fp="20,134,20.538.0,22.316.1,41.204.0,48.169.1,35.200.0,51.268.0"}
P.entries["item:pristine-spider-silk"] = {n="Makellose Spinnenseide",s="Im Dämmerwald liefern giftige Spinnen den feinen Faden, den Sturmwinds Magier für Roben brauchen, die Verzauberungen standhalten.",h="Im Dämmerwald liefern giftige Spinnen den feinen Faden, den Sturmwinds Magier für Roben brauchen, die...",kw={"brütling der schwarzen witwe","aas-einsiedlerspinne","dämmerwald","magierrobe","makellose spinnenseide","magiersanktum","wynne larson"},ang={["class:Mage"]="Als Magier von Sturmwind werdet Ihr in den Dämmerwald geschickt, um diesen feinen Faden zu sammeln und Euch eine Robe zu verdienen, die Eurem wachsenden arkanen Rang entspricht.",["profession:Tailoring"]="Als Schneider arbeitet Ihr mit zarten, widerstandsfähigen Fäden, die von tödlichen Spinnen gesammelt werden. Sie sind ein feines natürliches Gewebematerial für magische Roben."},sec={{t="Das Arkane verweben",b="Sturmwinds Magier brauchen Seide, die Verzauberungen und der Beanspruchung durch einen Adepten standhält. Schneider verwenden gewöhnliche Spinnenseide, doch Fäden von Aas-Einsiedlerspinnen und Brütlingen der Schwarzen Witwe im Dämmerwald sind widerstandsfähiger. Magier aus dem Sanktum des Zauberers schicken aufstrebende Adepten in diese Wälder, um sie zu sammeln. Schneidermeisterin Wynne Larson webt die Seide dann zu einer Robe für einen Adepten."}},faq={{q="Woher stammt Makellose Spinnenseide?",a="Makellose Spinnenseide stammt von Aas-Einsiedlerspinnen und Brütlingen der Schwarzen Witwe im Dämmerwald.",al={"wo makellose spinnenseide bekommen","wer lässt makellose spinnenseide fallen","makellose spinnenseide fundort"}},{q="Wer fertigt Gewänder aus dieser Seide?",a="Wynne Larson, eine Tuchmacherin in Sturmwinds Magierviertel, webt die gesammelte Seide zu einer Robe für das Sanktum des Zauberers.",al={"wer verwendet makellose spinnenseide","wer verarbeitet seide zu roben","wynne larson robe"}},{q="Warum benötigen die Magier gerade diese Seide?",a="Die Magier brauchen Seide, die widerstandsfähig genug ist, damit die Robe eines Adepten Verzauberungen und Beanspruchung standhält. Die Seide der Spinnen des Dämmerwalds besitzt die nötige Stärke und Qualität.",al={"warum makellose seide","magische spinnenseide verwendung"}}},fx={dfaa8e27={q="Was ist Makellose Spinnenseide?",a="Makellose Spinnenseide ist ein außergewöhnlich feines, makelloses Gewebe, das von den Arachniden gesponnen wird, die den Dämmerwald heimsuchen. Im Gegensatz zu den gewöhnlichen, zerfetzten Netzen, die in dem schattigen Wald an Bäumen haften, gelten nur die reinsten, unversehrten Stränge als makellos. Schneider und Magier schätzen sie aufgrund ihrer überlegenen Qualität und Textur sehr und verwenden sie als wesentlichen Grundstoff für die Anfertigung vornehmer Kleidungsstücke für praktizierende Magier.",al={"makellose spinnenseide","was ist makellose seide","gegenstand makellose seide"}}},fp="20,108,18.366.0,42.88.0,35.120.0,44.157.0"}
P.entries["item:prowler-claws"] = {n="Streunerklauen",s="Aus dem ganzen Brachland gelangen Streunerklauen zu Sergra Dunkeldorn im Wegekreuz. Sie beweisen, dass ein Jäger die Streuner aufspüren und bezwingen kann, die durch die Ebenen schleichen.",h="Aus dem ganzen Brachland gelangen Streunerklauen zu Sergra Dunkeldorn im Wegekreuz.",kw={"brachland","das wegekreuz","streunerklauen","streuner des brachlandes","savannenstreuner","sergra darkthorn"},ang={["class:Hunter"]="Als Jäger prüft Ihr beim Aufspüren von Savannenstreunern und Erbeuten ihrer Klauen Eure Fähigkeiten im Schleichen, Spurenlesen und Umgang mit Bestien auf kurze Distanz.",["faction:Horde"]="Als Mitglied der Horde schützt Ihr Boten, Karawanen und Siedler auf Kalimdors zentralen Straßen, indem Ihr helft, die Streuner rund um das Wegekreuz zu dezimieren."},sec={{t="Trophäen des Pirschers",b="Savannenstreuner warten im hohen Gras des Brachlands, bereit, mit Geduld und List zuzuschlagen. Anders als grasende Schreiter und Zhevras überfallen diese großen Katzen jene Kreaturen, die ihr Jagdrevier betreten. Ihre gebogenen Klauen zu erbeuten bedeutet, Raubtieren gegenüberzutreten, die auf Heimlichkeit setzen und ihr Revier verteidigen. Für Krieger und Späher der Horde prüft die Jagd, ob sie einen Pirscher durch sein eigenes Revier verfolgen und zur Beute machen können."},{t="Beweis für die Jägerin",b="Sergra Dunkeldorn, die Jägerin im Wegekreuz, bittet Anwärter, ihr Streunerklauen zu bringen, bevor sie sich größeren Prüfungen stellen. Die Klauen beweisen, dass ein Jäger Spuren durch das Savannengras folgen und dem Angriff eines Raubtiers standhalten kann. Wer mit ihnen zurückkehrt, hat gezeigt, dass er unter den gefährlichen Bestien der Ebenen wachsam bleiben kann."}},faq={{q="Wo bekomme ich Streunerklauen?",a="Savannenstreuner durchstreifen das Grasland im zentralen Brachland, besonders die Ebenen südwestlich des Wegekreuzes. Nehmt ihre Klauen und bringt sie zurück.",al={"streunerklauen fundort","wie streunerklauen bekommen","wo streunerklauen finden"}},{q="Wer will diese Klauen und warum?",a="Sergra Dunkeldorn, eine erfahrene Jägerin im Wegekreuz, verlangt sieben Streunerklauen. Sie ihr zu bringen prüft Euer Spurenlesen und Eure Kampffähigkeiten gegen gefährliche Raubtiere.",al={"wer braucht streunerklauen","streunerklauen abgeben","sergra klauen quest"}},{q="Warum gilt die Jagd auf Savannenstreuner als bedeutende Prüfung?",a="Savannenstreuner sind heimliche Fleischfresser, die Reisenden und Beutetieren aus dem hohen Gestrüpp auflauern. Die Jagd auf sie prüft, ob Ihr einem Hinterhalt entgehen und eine listige, tödliche Bestie bezwingen könnt.",al={"warum streuner jagen","streuner gefährlich"}}},fx={c8bad4fe={q="Woher stammen Streunerklauen?",a="Diese Klauen stammen direkt von den Savannenstreunern, die durch das Brachland streifen, insbesondere im Grasland südwestlich des Wegekreuzes. Es handelt sich um natürliche Trophäen, die von Jägern, die geschickt genug sind, die Raubkatzen zur Strecke zu bringen, von deren Kadavern geerntet werden.",al={"woher stammen streunerklauen","quelle für streunerklauen","wie bekommt man streunerklauen"}},["551eb0e2"]={q="Was sind Streunerklauen?",a="Streunerklauen sind die messerscharfen Krallen, die von den Pfoten der Savannenstreuner stammen, den tödlichen katzenartigen Raubtieren, die durch das hohe Savannengras vom Brachland schleichen. Für die Jäger vom Wegekreuz beweist das Nehmen dieser Trophäen, dass Ihr eine schlaue, tödliche Bestie aufspüren und besiegen könnt, ohne selbst zur Beute zu werden.",al={"was sind streunerklauen","streunerklauen gegenstand","über streunerklauen"}}},fp="13,154,23.425.0,22.323.0,29.143.0,30.170.0,56.179.0"}
P.entries["item:pure-hearts"] = {n="Reine Herzen",s="In Unterstadt locken Reine Herzen eine Sukkubus aus dem Twisting Nether. Carendin Halgar gibt diese Ritualreagenzien an Hexenmeister der Verlassenen, die damit die Dämonin herbeirufen und versuchen, sie zu besiegen und zu binden.",h="In Unterstadt locken Reine Herzen eine Sukkubus aus dem Twisting Nether.",kw={"carendin halgar","magieviertel","reine herzen","sukkubus","beschwörung","the binding","unterstadt"},ang={["class:Warlock"]="Für Euch als Hexenmeister markiert die Verwendung Reiner Herzen einen Wendepunkt in der Dämonologie. Sie beweist Eure geistige Stärke gegenüber den verführerischen Lockungen des Twisting Nether.",["race:Undead"]="Als Untoter nutzt Ihr unbefleckte Herzen, um dämonische Begierden zu lenken. Diese kalte, pragmatische Zauberei ist beispielhaft für die Praktiken der Verlassenen."},sec={{t="Köder für den Nether",b="Carendin Halgar gibt Reine Herzen an Hexenmeister, die im Magieviertel von Unterstadt eine Sukkubus beschwören. Sie legen die unbefleckten spirituellen Essenzen auf den Beschwörungskreis. Die Herzen locken die Dämonin durch den Twisting Nether ins Reich der Sterblichen.\n\nSobald sie erscheint, muss der Hexenmeister ihren betörenden Geistbezauberungen widerstehen und sie niederstrecken. Der Sieg über die Sukkubus beweist mystische Überlegenheit und schickt sie in den Twisting Nether zurück. Dann lehrt Carendin den Hexenmeister den Zauber, mit dem er sie nach Belieben beschwören kann."}},faq={{q="Wofür werden die Reinen Herzen verwendet?",a="Reine Herzen locken eine Sukkubus durch den Twisting Nether und bringen sie ins Reich der Sterblichen. Am Beschwörungskreis im Magieviertel von Unterstadt kann ein Hexenmeister sie bekämpfen und binden.",al={"reine herzen verwendung","warum reine herzen","was bewirken reine herzen"}},{q="Wer stellt die Reinen Herzen bereit?",a="Carendin Halgar, ein Hexenmeisterlehrer der Verlassenen in Unterstadt, gibt Reine Herzen an Hexenmeister, die sich auf die Beschwörung einer Sukkubus vorbereiten.",al={"wer gibt reine herzen","reine herzen questgeber"}},{q="Warum reagiert eine Sukkubus auf Reine Herzen?",a="Sukkubi leben von Verderbnis und Verführung. Der Glanz unbefleckter Herzen lockt sie durch den Twisting Nether zum Beschwörungskreis eines Hexenmeisters.",al={"warum will die sukkubus reine herzen","hintergrund der reinen herzen"}},{q="Dürft Ihr die Reinen Herzen nach dem Ritual behalten?",a="Nein. Nachdem die Sukkubus beschworen und bezwungen wurde, gehen die Überreste der Reinen Herzen als Beweis für die abgeschlossene Bindungsprüfung an Carendin Halgar zurück.",al={"behalte ich die reinen herzen","was geschieht mit den reinen herzen"}}},fx={["105bfa16"]={q="Was sind Reine Herzen?",a="Die Reinen Herzen sind mächtige Ritualkomponenten, die von Hexenmeistern der Verlassenen in der Unterstadt verwendet werden. Wenn sie über einem Beschwörungskreis eingesetzt werden, wirkt ihre unverdorbene Essenz wie ein Köder durch den Wirbelnden Nether und öffnet einen Riss, der speziell dazu entworfen wurde, eine gefährliche Sukkubus anzulocken und in Eure Gegenwart zu beschwören.",al={"was sind reine herzen","reine herzen gegenstand","reine herzen hexenmeister"}},["3abadf0f"]={q="Warum sollte jemand Reine Herzen haben wollen?",a="Ein angehender Hexenmeister benötigt die Reinen Herzen, um das gefährliche Bindungsritual für eine Sukkubus abzuschließen. Ohne einen solchen unverdorbenen Köder anzubieten, um die Leere zu überbrücken, könnt Ihr den Dämon nicht in das Reich der Sterblichen ziehen, um sie zu unterwerfen und die Kunst zu meistern, sie auf Euren Befehl zu beschwören.",al={"warum will man reine herzen","zweck der reinen herzen","warum werden reine herzen gesucht"}}},fp="11,206,19.499.0,34.183.0,29.123.0,43.149.0,52.151.0"}
P.entries["item:purified-kor-gem"] = {n="Geläuterter Koredelstein",s="An Jordan Stillbrunns Schmiede vor Eisenschmiede wird ein Geläuterter Koredelstein benötigt, um eine Waffe des Lichts zu formen. Zuerst muss Elfenmagie den verderbten Stein reinigen.",h="An Jordan Stillbrunns Schmiede vor Eisenschmiede wird ein Geläuterter Koredelstein benötigt, um eine Waffe...",kw={"auberdine","tiefschwarze grotte","verderbter koredelstein","dun morogh","jordan stillbrunn","geläuterter koredelstein","test of righteousness","thundris windweaver"},ang={["class:Paladin"]="Als Paladin beweist Ihr Eure Hingabe, indem Ihr diesen Edelstein beschafft und läutert. Dann tragt Ihr ihn von Kalimdor nach Dun Morogh, wo er hilft, eine Waffe des Lichts zu schmieden.",["faction:Alliance"]="Als Mitglied der Allianz verlasst Ihr Euch auf die Weisheit der Nachtelfen in Auberdine, um einem menschlichen Schmied an den Hängen von Dun Morogh zu helfen."},sec={{t="Von Verderbnis zu Heiligkeit",b="Naga bewahren den Verderbten Koredelstein in der Tiefschwarzen Grotte unter der Küste von Eschental auf. Ein Paladin bringt ihn zu Thundris Windwirker, einem Nachtelfen in Auberdine. Dort nutzt Thundris arkane und natürliche Künste, um den Stein von seinem wässrigen und schattenhaften Makel zu befreien. Der Stein geht geläutert daraus hervor, bereit, heilige Macht zu kanalisieren."},{t="Das Meisterwerk des Schmieds",b="Jordan Stillbrunn, ein menschlicher Waffenschmied vor Eisenschmiede, benötigt den Edelstein für eine meisterhafte Waffe. Schon lange besitzt er Entwürfe für eine Waffe, die der Silbernen Hand würdig ist, doch ihm fehlten die seltenen Materialien, um sie zu schmieden. Der Geläuterte Koredelstein, Weißsteineichenholz und seltenes Erz verleihen der Waffe ihren spirituellen Kern, um den rechtschaffenen Zorn eines Paladins zu kanalisieren."}},faq={{q="Wofür wird der Geläuterte Koredelstein verwendet?",a="Der Edelstein wird zu Jordan Stillbrunn gebracht, dem Schmied vor Eisenschmiede in Dun Morogh. Er verwendet ihn, um eine geweihte Waffe für einen Paladin zu schmieden, der sich seinen Prüfungen stellt.",al={"geläuterter koredelstein verwendung","warum wird der koredelstein benötigt","wofür ist der koredelstein"}},{q="Woher stammt der Edelstein?",a="Naga bewahren den verderbten Stein in der Tiefschwarzen Grotte unter der Küste von Eschental auf.",al={"koredelstein herkunft","wo wird der koredelstein fallen gelassen","wer lässt den koredelstein fallen"}},{q="Wer läutert den Edelstein?",a="Thundris Windwirker, ein Nachtelf in Auberdine, reinigt den Verderbten Koredelstein und versetzt ihn wieder in einen geläuterten Zustand.",al={"wie wird der koredelstein geläutert","wer läutert den koredelstein","thundris windweaver koredelstein"}},{q="Kann jeder Abenteurer den Geläuterten Koredelstein nutzen?",a="Paladine, die sich dem Test of Righteousness stellen, suchen den Edelstein. Jordan Stillbrunn schmiedet für heilige Krieger, die ihm den geläuterten Kristall und andere seltene Materialien bringen.",al={"koredelstein nur für paladine","kann jeder den geläuterten koredelstein nutzen"}}},fx={a30b14db={q="Was ist ein Geläuterter Koredelstein?",a="Der Geläuterte Koredelstein ist eine seltene, geheiligte Mineralkomponente, die von übler Verderbnis gereinigt wurde. Ursprünglich als korrupter Stein von den Naga in der Tiefschwarzen Grotte geborgen, wurde er von Thundris Windwirker in Auberdine mühsam von seinem dunklen Einfluss befreit, sodass seine verborgenen Eigenschaften sicher für heilige Arbeiten genutzt werden können.",al={"was ist geläuterter koredelstein","bedeutung geläuterter koredelstein","infos zu geläuterter koredelstein"}}},fp="16,161,27.299.0,23.338.0,38.161.0,29.83.0,21.114.0,52.161.0"}
P.entries["item:putrid-claw"] = {n="Eitrige Klaue",s="Bei Brill helfen Kopfgelder für Eitrige Klauen, die Geißel in Schach zu halten. Geistlose Untote durchstreifen die Wälder westlich der Stadt, besonders nahe der alten Brücke, und Todeswache Dillinger nimmt die Klauen als Beweis entgegen.",h="Bei Brill helfen Kopfgelder für Eitrige Klauen, die Geißel in Schach zu halten.",kw={"a putrid task","brill","todeswache dillinger","eitrige klaue","geschändete leiche","verrottende tote","geißel","tirisfal"},ang={["race:Undead"]="Wenn Ihr als frisch aufgenommener Verlassener Todesend verlasst, erkennt Ihr, dass Befreiung bedeutet, sich gegen die geistlosen Hüllen zu verteidigen, denen Ihr einst geglichen habt."},sec={{t="Trophäe der Geistlosen",b="Die geistlose Geißel dringt immer wieder nach Tirisfal ein. Verrottende Tote und geschändete Leichen durchstreifen die östlichen Grenzgebiete und sammeln sich entlang der Straßen und nahe der alten Brücke westlich von Brill. Todeswachen setzen Kopfgelder auf diese Schrecken aus, um Reisende und die Nachschublinien der Garnison zu schützen. Eine abgetrennte eitrige Klaue beweist, dass eine weitere schlurfende Leiche endgültig zur Ruhe gebracht wurde."}},faq={{q="Wofür werden eitrige Klauen verwendet?",a="Todeswache Dillinger in Brill sammelt eitrige Klauen als Belege für Kopfgelder. Sie zeigen, dass örtliche Rekruten der Verlassenen die Reihen der Geißel lichten, die Tirisfal durchstreift.",al={"eitrige klaue verwendung","warum eitrige klauen sammeln","wer will eitrige klauen"}},{q="Woher stammen eitrige Klauen?",a="Eitrige Klauen stammen von den verrottenden Toten und geschändeten Leichen, die die verwunschenen Wälder westlich von Brill durchstreifen, besonders nahe der alten Flussbrücke.",al={"wo eitrige klauen finden","eitrige klaue beute","verrottende tote beute"}},{q="Warum ist die Geißel in Tirisfal?",a="Nach der Verwüstung Lordaerons dringen Überreste der geistlosen Geißel des Lichkönigs immer wieder nach Westen in Tirisfal ein. Sie bedrohen Straßen und Siedlungen, wenn niemand ihre Reihen lichtet.",al={"warum sind zombies bei brill","geißel in tirisfal"}},{q="Warum lassen die Verlassenen die geistlosen Untoten nicht einfach umherwandern?",a="Königin Sylvanas und die Verlassenen entzogen sich dem Zugriff des Lichkönigs und erlangten ihren Willen zurück. Die geistlose Geißel folgt finsteren Instinkten oder seinem fortwirkenden Befehl und greift alle Lebenden oder freien Untoten an, sobald sie sie erblickt.",al={"verlassene gegen geistlose zombies","warum andere untote töten"}}},fx={["37750c4d"]={q="Was ist eine Eitrige Klaue?",a="Eine Eitrige Klaue ist die abgetrennte, verrottende Hand eines hirnlosen Zombies, der zur Geißel gehört. Diese verwesenden Gliedmaßen werden den wandelnden Leichen, die Tirisfal heimsuchen, als Beweis für ihre Vernichtung abgenommen.",al={"was ist eine eitrige klaue","infos zu eitrige klauen","hintergrund eitrige klaue"}}},fp="11,191,22.354.0,31.155.0,32.140.0,38.170.0,59.205.0"}
P.entries["item:pyrewood-shackle"] = {n="Lohenscheitfessel",s="In Lohenscheit binden verzauberte Fesseln die Bewohner an Erzmagier Arugals seltsame Magie. Wenn die Nacht hereinbricht, erwartet die Dorfbewohner ein düsteres Schicksal.",h="In Lohenscheit binden verzauberte Fesseln die Bewohner an Erzmagier Arugals seltsame Magie.",kw={"arugal","morgenweber","moonrage","lohenscheit","das grabmal","fessel","silberwald","worgen"},ang={["class:Mage"]="Als Magier könnt Ihr die rücksichtslose Verwandlungs- und Bindungsmagie erkennen, die in gewöhnlichen Stahl eingewoben ist.",["race:Undead"]="Als Verlassene wisst Ihr, dass Arugals zügellose Zauberei Eure Grenzen bedroht. Diese verzauberten Fesseln zu sammeln, ist entscheidend, um den Einfluss der Burg Shadowfang zu neutralisieren."},sec={{t="Arugals Bindungsmagie",b="Die Bewohner von Lohenscheit leben tagsüber als Menschen und werden bei Sonnenuntergang zu wilden Moonrage-Worgen. Erzmagier Arugal legte ihnen während seiner Experimente mit Worgenzauberei verzauberte Fesseln an. Im Grabmal untersucht Dalar Morgenweber, ein arkaner Forscher der Verlassenen, diese Bänder. Er sammelt ihre verbliebene Energie, um die Wirkung der Verzauberungen zu ergründen, Arugals Magie zu verstehen und den Einfluss des wahnsinnigen Erzmagiers auf die Region zu schwächen."}},faq={{q="Wozu dienen Lohenscheitfesseln?",a="Im Grabmal untersucht Dalar Morgenweber die Verzauberungen der Fesseln. Er hofft, Erzmagier Arugals Zauber zu entschlüsseln und dessen Einfluss im Silberwald zu brechen.",al={"lohenscheitfesseln verwendung","warum fesseln sammeln","dalar morgenweber fesseln"}},{q="Wer trägt diese Fesseln?",a="Die verfluchten Bewohner von Lohenscheit im südlichen Silberwald tragen die Fesseln. Sie tragen sie tagsüber als Menschen und nachts als Moonrage-Worgen.",al={"wer lässt lohenscheitfesseln fallen","fesseln herkunft","wo lohenscheitfesseln finden"}},{q="Warum verwandeln sich die Dorfbewohner nachts?",a="Erzmagier Arugals rücksichtslose Experimente und Verzauberungen führten dazu, dass sich die Bewohner von Lohenscheit nachts verwandeln. Die Fesseln tragen eine Verzauberung, die sie bei Tageslicht als gewöhnliche Menschen erscheinen lässt, während die Dunkelheit ihre wilden Worgengestalten offenbart.",al={"warum sich lohenscheits bewohner in worgen verwandeln","lohenscheit fluch","lohenscheit werwolfgeheimnis"}},{q="Wer ist Dalar Morgenweber?",a="Dalar Morgenweber ist ein Magier der Verlassenen im Grabmal im Silberwald. Er untersucht arkane Anomalien, die Erzmagier Arugal hinterlassen hat, und versucht, dessen Flüche zu brechen.",al={"dalar morgenweber","wer ist dalar"}}},fx={b92f5faa={q="Was ist eine Lohenscheitfessel?",a="Eine Lohenscheitfessel ist eine verzauberte Fessel, die an die unglücklichen Bewohner von Lohenscheit im südlichen Silberwald gebunden ist. Diese Fesseln sind mit der seltsamen, rücksichtslosen Zauberei des verrückten Magiers Erzmagier Arugal durchdrungen und spielen eine direkte Rolle dabei, die Stadtbewohner an seinen Willen zu binden und den dunklen Fluch zu verbergen, der sie heimsucht.",al={"lohenscheitfessel","was sind lohenscheitfesseln","lohenscheitfesseln"}},f6bcbb50={q="Woher stammt eine Lohenscheitfessel und wer hat sie hergestellt?",a="Diese verzauberten Fesseln wurden von Erzmagier Arugal, dem abtrünnigen Magier aus Dalaran, der in Burg Shadowfang residierte, geschmiedet und den Dorfbewohnern angelegt. Arugal legte den Bauern von Lohenscheit die Fesseln als Teil seiner verdrehten Verzauberungen an, um sie unter seiner Kontrolle zu halten und ihre lupine Verwandlung hinter einer tagsüber wirkenden Illusion eines gewöhnlichen menschlichen Lebens zu verbergen.",al={"wer hat lohenscheitfesseln gemacht","ursprung der lohenscheitfessel","woher kommen die fesseln"}},["98d012f7"]={q="Warum will jemand Lohenscheitfesseln?",a="Dalar Morgenweber, ein ehrgeiziger Hexenmeister der Verlassenen, der am Grabmal forscht, sucht nach diesen verzauberten Fesseln, um Arugals Magie zu studieren. Durch das Absaugen ihrer verbleibenden Energie hofft Dalar, den bizarren Zauber zu entschlüsseln, der die Dorfbewohner tagsüber menschlich erscheinen lässt und sie nach Einbruch der Dunkelheit in gefräßige Mondzorn-Worgen verwandelt, mit dem endgültigen Ziel, Arugals Zauber aufzuheben.",al={"warum lohenscheitfesseln sammeln","wer braucht lohenscheitfesseln","zweck der lohenscheitfessel"}}},fp="16,141,22.410.1,36.176.0,27.155.1,40.234.1,24.167.0"}
P.entries["item:quinn-s-potion"] = {n="Quinns Trank",s="Im Grabmal bereitet Apotheker Renferrel Quinns Trank für einen verwundeten Späher zu. Quinn Yorick braucht ihn nach einer verheerenden Patrouille im Silberwald.",h="Im Grabmal bereitet Apotheker Renferrel Quinns Trank für einen verwundeten Späher zu.",kw={"apotheker renferrel","todespirscher","das ivar-feld","quinn yorick","quinns trank","das grabmal","silberwald"},ang={["race:Undead"]="Als Verlassene wisst Ihr, dass die Königliche Apothekervereinigung selten Mühe auf einfache Feldheilmittel verwendet, es sei denn, sie erhalten Späher, die die Grenzen des Silberwalds bewachen."},sec={{t="Renferrels Heilmittel",b="Apotheker Renferrel braut ein Heilmittel für Todespirscher Quinn Yorick. Die Königliche Apothekervereinigung im Grabmal erreichte die Nachricht, dass Quinn nahe dem Ivar-Feld schwer verwundet worden war und sich nicht mehr bewegen konnte. Renferrel stellte den Trank her, um seine Genesung zu unterstützen.\n\nLeichtere Verwundungen im Feld lenken Renferrel selten von seinen finsteren Forschungen für Fürstin Sylvanas ab. Dennoch stellte er das Heilmittel bereit, damit Quinn wieder genug Kraft für die Reise schöpfen konnte."}},faq={{q="Wofür wird Quinns Trank verwendet?",a="Quinns Trank hilft Todespirscher Quinn Yorick, sich von seinen Verletzungen im nördlichen Silberwald zu erholen. Er gibt ihm genug Kraft zurück, um wieder reisen zu können.",al={"quinns trank zweck","was bewirkt quinns trank","warum quinns trank brauen"}},{q="Wer hat diesen Trank gebraut?",a="Apotheker Renferrel, ein in den Krypten des Grabmals stationierter Alchemist der Königlichen Apothekervereinigung, hat den Trank gebraut.",al={"wer hat quinns trank hergestellt","wer hat ihn gebraut","renferrels trank"}},{q="Wohin muss der Trank gebracht werden?",a="Bringt den Trank nördlich des Grabmals zu Quinn Yorick, der nahe dem Gehöft namens Ivar-Feld Zuflucht gefunden hat.",al={"wohin den trank bringen","quinns aufenthaltsort","quinn yoricks standort"}},{q="Warum brauchte Quinn Yorick einen Trank?",a="Quinn erkundete mit einer Todespirscherpatrouille den nördlichen Silberwald. Am Ivar-Feld griff der Ghul Ivar the Foul die Späher an und ließ Quinn schwer verwundet und hilflos zurück.",al={"warum ist quinn verletzt","was ist quinn yorick passiert","quinn verwundet"}}},fx={["52098f03"]={q="Was ist Quinns Trank?",a="Es ist ein stärkendes Gebräu, das von Apotheker Renferrel am Grabmal hergestellt wird. Der Trank wurde speziell formuliert, um dem verletzten Späher Quinn Yorick zu helfen, und verleiht ihm die Kraft, die er braucht, um sich von seinen Wunden zu erholen und genügend Mobilität zurückzugewinnen, um zu reisen.",al={"quinns trank","was ist dieser trank","was ist quinns gebräu"}}},fp="14,154,16.415.0,32.156.0,23.123.0,43.109.0,41.169.0"}
P.entries["item:ran-bloodtooth-s-skull"] = {n="Ran Blutreißers Schädel",s="Im Eschental erreicht Ran Blutreißers Schädel die Nachtelfen von Astranaar als Beweis, dass eine wilde Bedrohung gefallen ist.",h="Im Eschental erreicht Ran Blutreißers Schädel die Nachtelfen von Astranaar als Beweis, dass eine wilde...",kw={"eschental","astranaar","blutreißer schädel","blutreißer","furbolg","raene wolfsläufer","raene's cleansing","ran blutreißer"},ang={["faction:Alliance"]="Die Überbringung der grausigen Trophäe beweist die Tapferkeit der Champions der Allianz, die an der Seite der Schildwachen die gefährdeten Grenzen des Eschentals verteidigen.",["race:NightElf"]="Für die Nachtelfen steht der Schädel für einen düsteren Sieg und ehrt Teronis' unvollendete Aufgabe. Er erinnert auch daran, wie schwer die dämonische Verderbnis ihre einstigen Verbündeten, die Furbolgs, gezeichnet hat."},sec={{t="Eine Trophäe der Verteidigung des Eschentals",b="Dämonischer Makel und die Verderbnis der Wildnis haben die Furbolgs des Eschentals in mörderischen Wahn getrieben. Ran Blutreißer führte einen der wildesten Stämme an. Sein Schädel beweist den Schildwachen der Nachtelfen, dass er gefallen und seine Macht über die örtlichen Furbolgs gebrochen ist. Astranaar erhält eine kleine Atempause."},{t="Die Gefallenen ehren",b="In Astranaar nimmt Schildwache Raene Wolfsläufer Ran Blutreißers Schädel entgegen. Er markiert das Ende einer Untersuchung, die der gefallene Kundschafter Teronis begonnen hatte. Neben dem Schädel ruht Dartols Rute, die wieder zusammengesetzt wurde, nachdem Teronis aufgebrochen war, um sie zu finden. Gemeinsam ehren Schädel und Rute jene, die für den Erhalt des heiligen Waldes kämpften."}},faq={{q="Wer war Ran Blutreißer?",a="Ran Blutreißer führte einen verderbten Furbolgstamm im Eschental an. Die Schildwachen der Nachtelfen zählten ihn zu den wildesten Bedrohungen der Region.",al={"wer ist ran blutreißer","ran blutreißer hintergrundgeschichte","wer war blutreißer"}},{q="Warum wollen die Schildwachen seinen Schädel?",a="Raene Wolfsläufer nimmt Ran Blutreißers Schädel in Astranaar als Beweis entgegen, dass er gefallen ist. Er ruht neben Dartols Rute im Gedenken an jene, die bei der Verteidigung des Eschentals ihr Leben ließen.",al={"warum brauche ich den schädel","raene wolfsläufer schädel","wozu dient der schädel"}},{q="Wer war Teronis?",a="Teronis war ein langjähriger Freund von Raene Wolfsläufer und ein Verbündeter der Schildwachen im Eschental. Er suchte einen Edelstein für eine Rute des verstorbenen Zauberers Dartol und hoffte, damit die Angriffe der Furbolgs einzudämmen. Murlocs erschlugen ihn am Falathimsee, woraufhin Raene Wolfsläufer und durchreisende Abenteurer seine Aufgabe übernahmen.",al={"teronis hintergrundgeschichte","wer ist teronis","teronis astranaar"}}},fx={["4d0a3ce4"]={q="Was ist Ran Blutreißers Schädel?",a="Dies ist der abgetrennte Schädel von Ran Blutreißer, einer der wildesten und gefährlichsten korrumpierten Furbolg-Bedrohungen, die das Eschental durchstreifen. Als Beweis für seinen Sieg genommen, markiert er das Ende des Schreckens, den er über die Sentinels und den Wald brachte.",al={"ran blutreißers schädel","was ist ran blutreißers schädel","ran blutreißer kopf"}},f5c7858d={q="Woher stammt Ran Blutreißers Schädel?",a="Der Schädel wird direkt von Ran Blutreißer genommen, nachdem man ihn im Eschental erschlagen hat. Er ist kein Artefakt, das von sterblichen Händen geschmiedet oder gefertigt wurde, sondern eine düstere Trophäe, die vom Häuptling selbst geerntet wurde.",al={"woher stammt der schädel von ran blutreißer","wer hat ran blutreißers schädel gemacht","quelle für ran blutreißers schädel"}}},fp="22,115,31.284.0,19.305.1,23.136.0,36.164.0,16.287.0"}
P.entries["item:raptor-head"] = {n="Raptorkopf",s="Im Wegekreuz werden Raptorköpfe als Trophäen für Gazrogs Kopfgeld abgegeben. Der Sold der Wachen verschwand aus einem Wachturm, und ein wilder Raptor wurde beim Diebstahl ertappt.",h="Im Wegekreuz werden Raptorköpfe als Trophäen für Gazrogs Kopfgeld abgegeben.",kw={"brachland","das wegekreuz","gazrog","raptorkopf","raptor thieves","gestohlenes silber","sunscale"},ang={["class:Hunter"]="Wenn Ihr Sunscale-Raptoren durch das trockene Gestrüpp des Brachlands verfolgt, messt Ihr Euer Können mit einigen der aggressivsten und gerissensten Rudeljäger der Savanne.",["faction:Horde"]="Das Wegekreuz ist der Verkehrsknotenpunkt der Horde im Herzen Kalimdors. Die diebischen Raubtiere zu dezimieren hilft, die Vorräte und den Sold der Garnison zu sichern."},sec={{t="Kopfgeld des Wegekreuzes",b="Eine Kiste mit dem Sold der Wachen wurde aus dem Wachturm des Wegekreuzes gestohlen, sodass die Verteidiger ohne ihr Silber dastanden. Zu ihrem Unglauben ertappten sie einen wilden Raptor auf frischer Tat. Gazrog bietet nun ein Kopfgeld auf die gerissenen Reptilien, die durch das Brachland streifen. Bringt ihre abgetrennten Köpfe zum Außenposten, damit die Raubtiere dezimiert werden können, bevor sie weitere Vorräte der Horde stehlen."}},faq={{q="Warum will Gazrog Raptorköpfe?",a="Eine Kiste mit Silber für die Wachen des Wegekreuzes wurde aus ihrem Turm gestohlen. Zu allgemeinem Unglauben wurde ein Raptor auf frischer Tat ertappt. Gazrog will die Bestien im ganzen Brachland jagen lassen, damit sie die Siedlung nicht erneut überfallen können.",al={"warum raptorköpfe sammeln","gazrog raptoren","raptorkopf kopfgeld"}},{q="Warum sollten wilde Raptoren Silber stehlen?",a="Gazrog gibt zu, dass er keine Ahnung hat, warum wilde Bestien Metallmünzen haben wollen. Raptoren in Kalimdor sind für ihre beunruhigende Gerissenheit bekannt. Der Diebstahl hat die Wachen des Wegekreuzes beschämt, und sie sinnen auf Vergeltung.",al={"warum wollen raptoren silber","raptoren stehlen münzen","raptor thieves rätsel"}},{q="Welche Raptoren tragen diese Köpfe?",a="Die Köpfe stammen von Sunscale-Raptoren, die durch das mittlere und südliche Brachland streifen, darunter Sunscale Lashtails, Screechers und Scytheclaws. Auch berüchtigte Bestien wie Ishamuhale und Takk the Leaper liefern Köpfe.",al={"wo raptorköpfe bekommen","welche raptoren lassen köpfe fallen","brachland raptoren"}},{q="Was geschieht nach der Abgabe der Köpfe?",a="Nachdem Gazrog zwölf Köpfe erhalten hat und die Raptoren dezimiert wurden, gilt es herauszufinden, wohin die gestohlene Silberlieferung gebracht wurde.",al={"was folgt auf raptor thieves","nach dem sammeln von raptorköpfen"}}},fx={f6102aac={q="Was ist ein Raptorkopf?",a="Ein Raptorkopf ist die abgetrennte Trophäe und der Kopfgeldbeweis, der von Raptoren genommen wird, die das Brachland durchstreifen, einschließlich lokaler Sonnenhautrudel und berüchtigter Bestien wie Ishamuhale oder Takk der Lepringer. Die Behörden des Wegekreuzes verlangen diese grausigen Beweisstücke als überprüfbaren Nachweis, dass die listigen Raubtiere, die ihre Nachschublinien und Wachen beunruhigen, zur Strecke gebracht wurden.",al={"was ist ein raptorkopf","raptorkopf gegenstand","was sind raptorköpfe"}},["377da5ba"]={q="Woher stammt ein Raptorkopf?",a="Diese Köpfe stammen direkt von den räuberischen Raptoren, die die Savannen und Bergrücken des Brachlands durchstreifen. Sonnenhaut-Peitschenschwänze, Kreischer, Sensenklauen und bekannte Jäger in der gesamten Ebene liefern sie, sobald sie erschlagen wurden. Da es sich um biologische Überreste handelt, die im Feld geerntet werden, werden sie von niemandem hergestellt, sondern als Trophäen einer erfolgreichen Jagd beansprucht.",al={"woher stammen raptorköpfe","ursprung des raptorkopfs","wer hat raptorköpfe gemacht"}}},fp="11,150,24.355.0,34.228.0,36.207.0,32.207.0,40.139.0"}
P.entries["item:rare-earth"] = {n="Seltene Erde",s="In Dolanaar wartet Seltene Erde auf einen Reisenden, der zu Denalans Lager nahe dem Al'Amethsee unterwegs ist. Die Erde kam aus Darnassus für seine botanischen Experimente auf Teldrassil.",h="In Dolanaar wartet Seltene Erde auf einen Reisenden, der zu Denalans Lager nahe dem Al'Amethsee unterwegs ist.",kw={"darnassus","denalan","dolanaar","kräuterkunde","al'amethsee","seltene erde","syral messerblatt"},ang={["profession:Herbalism"]="Als Kräuterkundiger könnt Ihr Euch an Syral Messerblatt und Denalan orientieren, die erforschen, wie besondere Erde das Wachstum und die Eigenschaften von Teldrassils Setzlingen verändert.",["race:NightElf"]="Als Nachtelf, der den jungen World Tree pflegt, könnt Ihr sehen, wie Experimente am Al'Amethsee zeigen, wie sich das Leben an Teldrassils ungezähmte Äste anpasst."},sec={{t="Erde aus Darnassus",b="Seltene Erde aus Darnassus ist verspätet in Dolanaar eingetroffen. Denalan, ein exzentrischer Botaniker am Ostufer des Al'Amethsees, hat sie angefordert, um Pflanzen im jungen Ökosystem von Teldrassil zu erforschen. Die Kräuterkundige Syral Messerblatt vertraut die Erde nun Reisenden an, die nach Süden ziehen. Sie hofft, dass sie Denalan erreicht, bevor ihre Wirksamkeit nachlässt."}},faq={{q="Wofür wird Seltene Erde verwendet?",a="Am Al'Amethsee verwendet Denalan Seltene Erde für seine botanischen Experimente. Er zieht die heimischen Pflanzen Teldrassils mit mineralischen Verbindungen und angereicherten Böden aus Darnassus.",al={"seltene erde verwendung","was macht denalan mit seltener erde","seltene erde zweck"}},{q="Wer schickt die Seltene Erde zu Denalan?",a="Die Kräuterkundige Syral Messerblatt bewahrt das Paket in Dolanaar auf. Es kam verspätet aus Darnassus an, und sie bittet Reisende, die nach Süden zum Al'Amethsee ziehen, es zu Denalan zu bringen.",al={"wer gibt seltene erde","wo gibt es seltene erde","syral messerblatt paket"}},{q="Warum machte sich Denalan Sorgen um die Lieferung?",a="Die Lieferung verzögerte sich auf dem Weg nach Dolanaar, sodass Denalan am See warten musste. Als sie eintrifft, befürchtet er, die Erde könnte die für seine Experimente nötige Frische verloren haben.",al={"ist seltene erde verdorben","denalan frische erde","warum kommt die erde zu spät"}}},fx={e720b4cb={q="Was ist Seltene Erde?",a="Seltene Erde ist eine speziell beschaffte, fruchtbare Bodenlieferung aus Darnassus. Sie wird sorgfältig für sensible landwirtschaftliche und botanische Forschungen vorbereitet und verpackt und enthält spezielle Nährstoffe, die eine frische Lieferung erfordern, um ihre Wirksamkeit für empfindliche Anbauexperimente aufrechtzuerhalten.",al={"was ist seltene erde","seltene erde gegenstand","hintergrund seltene erde"}},["5312d2a9"]={q="Warum will Denalan Seltene Erde?",a="Denalan ist ein Kräuterkundiger, der an den östlichen Ufern des Al'Amethsees stationiert ist und die lokale Flora von Teldrassil untersucht. Er verlässt sich auf diese seltene, nährstoffreiche Erde aus Darnassus, um seine empfindlichen Pflanzungen zu pflegen und seine botanische Arbeit auf der Insel voranzutreiben.",al={"warum will denalan seltene erde","warum will man seltene erde","warum wird seltene erde benötigt"}}},fp="10,160,17.313.0,28.170.0,36.170.0,43.172.0"}
P.entries["item:rattlecage-skull"] = {n="Schädel eines klappernden Skeletts",s="In Todesend sammeln angehende Hexenmeister der Verlassenen Schädel von geistlosen Untoten. Venya Marthand stellt ihnen diese Prüfung, bevor sie sie die dunklen Künste der Beschwörung lehrt.",h="In Todesend sammeln angehende Hexenmeister der Verlassenen Schädel von geistlosen Untoten.",kw={"todesend","wichtel beschwören","piercing the veil","rattlecage skeleton","schädel eines klappernden skeletts","tirisfal","venya marthand"},ang={["class:Warlock"]="Als Hexenmeister der Verlassenen ist das Sammeln dieser Schädel Euer erster Schritt zur Disziplin. Es beweist, dass Ihr den kalten Willen besitzt, Euren ersten Dämon zu versklaven.",["race:Undead"]="Als Untoter spiegelt das Zerschmettern niederer, gedankenloser Skelette den Glauben der Verlassenen an Herrschaft durch reine Willenskraft wider. Untote mit freiem Willen heben sich von geistlosen Knechten ab."},sec={{t="Die Prüfung eines Neulings",b="In Todesend leitet Venya Marthand frisch erweckte Verlassene an, die mit einer Begabung für dunkle Magie gesegnet sind. Sie schickt sie aus, um Rattlecage Skeletons nahe der verfallenen Schmiede zu bezwingen und deren Schädel zurückzubringen. Die Prüfung zeigt, ob ein junger Hexenmeister Wesen von jenseits dieser Welt seinem Befehl unterwerfen kann. Sie bereitet ihn darauf vor, die Leere zu durchbrechen und seinen ersten dämonischen Diener zu binden."}},faq={{q="Wofür werden Schädel klappernder Skelette verwendet?",a="In Todesend nimmt Venya Marthand drei Schädel klappernder Skelette von Hexenmeistern der Verlassenen entgegen. Damit beweisen sie ihre Konzentration und Entschlossenheit, bevor sie sie lehrt, einen Wichtel zu beschwören und zu binden.",al={"was sind schädel klappernder skelette","schädel eines klappernden skeletts verwendung","wer will schädel klappernder skelette"}},{q="Woher stammen Schädel klappernder Skelette?",a="Schädel klappernder Skelette stammen von geistlosen Rattlecage Skeletons, die über die überwucherten Wege und das verfallene Gelände nahe der verlassenen Schmiede von Todesend streifen.",al={"woher bekommt man schädel klappernder skelette","wer lässt schädel klappernder skelette fallen","schädel eines klappernden skeletts fundort"}},{q="Warum verlangt Venya Marthand Skelettschädel für eine Hexenmeisterprüfung?",a="Venya Marthand glaubt, dass Macht den Unwissenden verwehrt bleibt und Meisterschaft bedeutet, äußere Kräfte dem eigenen Willen zu unterwerfen. Geistlose Skelette zu erschlagen und ihre Köpfe an sich zu nehmen, zeigt, dass ein Lehrling chaotische Energien beherrschen kann, ohne von ihnen verzehrt zu werden.",al={"warum schädel für hexenmeister","venya marthand prüfung"}},{q="Welches Wissen wird nach dem Sammeln dieser Schädel gewährt?",a="Nachdem die Schädel übergeben wurden, lehrt Venya Marthand das geheime Ritual, um einen Wichtel herbeizurufen und zu binden. Dadurch erhalten junge Hexenmeister ihren ersten wahren dämonischen Diener.",al={"was erhält man für schädel klappernder skelette","piercing the veil belohnung"}}},fx={["9627b388"]={q="Was ist der Schädel eines klappernden Skeletts?",a="Der Schädel eines klappernden Skeletts ist der abgetrennte Kopf eines klappernden Skeletts, einem der hirnlosen Untoten, die auf dem verheerten Gelände nahe der verlassenen Schmiede von Todesend umherwandern. Für angehende Hexenmeister der Verlassenen dienen diese düsteren Trophäen als Beweis für grundlegende magische Entschlossenheit und Fokus, die zeigen, dass ein Initiand den wandelnden Toten entgegentreten und sie überwinden kann.",al={"was ist der schädel eines klappernden skeletts","hintergrund des schädels eines klappernden skeletts"}}},fp="16,155,17.352.0,36.172.0,37.145.0,68.239.0,55.160.0"}
P.entries["item:raven-claw-talisman"] = {n="Rabenkrallentalisman",s="Im Grabhügel von Ban'ethil wartet der Rabenkrallentalisman zwischen Relikten, die schlafende Druiden wecken sollen. Er ist eines der vier Relics of Wakening, die die Druids of the Talon sicher aus dem Smaragdgrünen Traum zurückführen sollen.",h="Im Grabhügel von Ban'ethil wartet der Rabenkrallentalisman zwischen Relikten, die schlafende Druiden wecken...",kw={"athridas bearmantle","ban'ethil","grabhügel","dolanaar","druids of the talon","rabenkrallentalisman","relics of wakening","teldrassil"},ang={["class:Druid"]="Als Druide wisst Ihr, wie der Rabenkrallentalisman den Druids of the Talon als ritueller Fokus dient, um einen im Smaragdgrünen Traum wandernden Geist zu schützen.",["race:NightElf"]="Als Nachtelf schützt Ihr eine uralte Tradition und Eure schlafenden Brüder, indem Ihr dieses Relikt von den Furbolgs der Gnarlpine zurückholt."},sec={{t="Ein Schlüssel zum Erwachen",b="Der Rabenkrallentalisman ruht in einer Truhe im Grabhügel von Ban'ethil. Dort versanken Teldrassils Druids of the Talon in einen tiefen meditativen Schlaf. Ohne den richtigen zeremoniellen Fokus kann ein Druide, der von der wachen Welt abgeschnitten ist, im Smaragdgrünen Traum stranden. Athridas Bearmantle in Dolanaar braucht diesen Talisman und drei weitere Relikte, um die Schlafenden sicher zurückzubringen: den Schwarzen Federkiel, den Saphir des Himmels und die Rune des Nistens."},{t="Die Bedrohung im Grabhügel",b="Verderbte Furbolgs der Gnarlpine haben den Grabhügel von Ban'ethil überrannt. Die heiligen Truhen und schlafenden Druiden sind nun in Gefahr. Ihre Entweihung hat das Heiligtum von äußerer Hilfe abgeschnitten, und die Relikte könnten verloren gehen oder zerstört werden. Athridas Bearmantle ruft Teldrassils Verteidiger auf, den gewundenen Erdgängen des Grabhügels zu trotzen und den Rabenkrallentalisman zu sichern, bevor die vertriebenen Druiden für immer im Traum verloren sind."}},faq={{q="Wozu dient der Rabenkrallentalisman?",a="Der Rabenkrallentalisman ist eines der vier heiligen Relics of Wakening. Die Relikte werden benötigt, um die Druids of the Talon aus ihrem tiefen Winterschlaf im Smaragdgrünen Traum zu wecken.",al={"was bewirkt der rabenkrallentalisman","zweck des rabenkrallentalismans","warum wird der rabenkrallentalisman benötigt"}},{q="Wo ist der Rabenkrallentalisman zu finden?",a="Der Rabenkrallentalisman ruht in der Chest of the Raven Claw in den Erdgängen des Grabhügels von Ban'ethil. Der Grabhügel liegt westlich von Dolanaar auf Teldrassil.",al={"wo ist der rabenkrallentalisman","fundort der chest of the raven claw","rabenkrallentalisman finden"}},{q="Wer braucht den Rabenkrallentalisman?",a="Athridas Bearmantle, ein Nachtelfendruide in Dolanaar, braucht den Talisman. Er wird damit die Erweckungsriten für seine vertriebenen Brüder vorbereiten.",al={"wer will den rabenkrallentalisman","wer nimmt den rabenkrallentalisman an","bei wem abgeben"}},{q="Warum können die Druiden ohne ihn nicht erwachen?",a="Der druidische Winterschlaf ist eine empfindliche Trance im Smaragdgrünen Traum. Ohne die Relics of Wakening als Anker für das Ritual droht der Geist eines Schlafenden auf unbestimmte Zeit dort verloren zu bleiben.",al={"warum brauchen druiden relikte zum erwachen","warum relics of wakening","können druiden ohne relikte erwachen"}}},fx={["33636b37"]={q="Was ist der Rabenkrallentalisman?",a="Der Rabenkrallentalisman ist eine der vier heiligen Relikte des Erwachens, die von den Druiden der Kralle aufbewahrt werden. Er wird in einer speziellen Truhe im Grabhügel von Ban'ethil aufbewahrt und ist ein wesentlicher Bestandteil des heiklen Rituals, das erforderlich ist, um schlafende Druiden sicher aus ihrem Winterschlaf im Smaragdgrünen Traum zurückzuholen.",al={"was ist der rabenkrallentalisman","infos zum rabenkrallentalisman","relikt rabenkrallentalisman"}}},fp="19,210,18.440.0,28.413.0,41.164.0,39.153.0,34.139.0,40.175.0"}
P.entries["item:razorflank-s-medallion"] = {n="Klingenflankes Medaillon",s="Tief im Kral der Klingenhauer trägt Charlga Klingenflanke das Medaillon als Zeichen ihrer Herrschaft. Seine Rückkehr liefert den Schildwachen der Nachtelfen den Beweis, dass sie gefallen ist.",h="Tief im Kral der Klingenhauer trägt Charlga Klingenflanke das Medaillon als Zeichen ihrer Herrschaft.",kw={"agamaggan","charlga klingenflanke","falfindel wegeshut","lonebrow","kral der klingenhauer","klingenflankes medaillon","thalanaar"},ang={["faction:Alliance"]="Als Abenteurer der Allianz rächt Ihr mit der Bergung des Medaillons Heralath, den gefallenen Späher, und Lonebrow, den zwergischen Forscher. Damit sichert Ihr Thalanaars Grenzroute nach Feralas.",["race:NightElf"]="Als Nachtelf ermöglicht Ihr Eurem Volk, Agamaggans verderbte heilige Ruhestätte gefahrlos zu erforschen, indem Ihr Charlga tötet und ihr Medaillon an Euch nehmt."},sec={{t="Beweis für den Fall der Greisin",b="Charlga Klingenflanke führt die Klingenhauer-Borstennacken an und trägt das Medaillon. In Thalanaar erfährt Falfindel Wegeshut von gefallenen Forschern, darunter Heralath und der Zwerg Lonebrow. Er schickt Abenteurer der Allianz gegen die Anführerin der Borstennacken aus.\n\nDas Medaillon bestätigt Charlgas Tod gegenüber den Schildwachen der Nachtelfen, die die Grenzen von Feralas bewachen. Die versammelten Streitkräfte im Kral haben ihre Anführerin verloren."}},faq={{q="Wer trägt Klingenflankes Medaillon?",a="Charlga Klingenflanke trägt das Medaillon tief im Kral der Klingenhauer. Sie führt dort die Borstennacken an.",al={"wer lässt klingenflankes medaillon fallen","klingenflankes medaillon herkunft","charlga medaillon"}},{q="Wer möchte dieses Medaillon erhalten?",a="Falfindel Wegeshut in Thalanaar bittet um das Medaillon. Er will einen Beweis dafür, dass Charlga getötet wurde.",al={"wer will klingenflankes medaillon","klingenflankes medaillon abgeben","falfindel medaillon"}},{q="Warum braucht Falfindel einen Beweis für Charlgas Tod?",a="Charlga versammelte im Kral der Klingenhauer eine feindliche Streitmacht der Borstennacken, die die umliegenden Gebiete bedrohte. Heralath und Lonebrow gehörten zu den Spähern, die starben. Das Medaillon gibt den Nachtelfen Gewissheit, dass die unmittelbare Bedrohung gebannt ist, sodass sie ihre Untersuchungen fortsetzen können.",al={"warum charlga töten","zweck des medaillons","warum wird das medaillon gebraucht"}}},fx={b119a669={q="Was ist Klingenflankes Medaillon?",a="Klingenflankes Medaillon ist ein persönliches Erkennungszeichen, das von Charlga Klingenflanke, der Anführerin der Stachelkauer, die tief im Kral der Klingenhauer leben, getragen wird. Mehr als einfacher Schmuck, dient es als unverkennbares Symbol ihrer Autorität über die schwärmenden Stämme im Kral und macht es somit zur definitiven Trophäe ihres Falls.",al={"was ist klingenflankes medaillon","hintergrund zu klingenflankes medaillon","charlga klingenflanke medaillon"}}},fp="22,157,25.393.0,35.98.0,41.100.0,49.269.0"}
P.entries["item:reagent-pouch-shaman"] = {n="Reagenzienbeutel (Schamane)",s="In Durotar tragen Kultisten der Burning Blade Reagenzien für das erste Feuersapta eines Schamanen bei sich. Telf Joolam mischt sie mit Feuerteer von Borstennacken-Stachelebern zu einem Trank, der einen jungen Schamanen das Reich des Feuers sehen lässt.",h="In Durotar tragen Kultisten der Burning Blade Reagenzien für das erste Feuersapta eines Schamanen bei sich.",kw={"burning blade","call of fire","durotar","staubwindhöhle","feuersapta","feuertotem","reagenzienbeutel","telf joolam"},ang={["class:Shaman"]="Als Schamane ist das Beschaffen des Beutels für Euch ein Initiationsritus auf dem Weg zu Eurem Feuertotem. Er lehrt, dass verderbte elementare Kräfte zurückgewonnen werden können, um dem Gleichgewicht zu dienen.",["class:Warlock"]="Als Hexenmeister erkennt Ihr die Beutel als Zauberbedarf für Teufelskultisten. Ihre rituellen Elemente sind für dämonische Feuermagie bestimmt, nicht für Zwiesprache mit der Natur."},sec={{t="Bestandteile der Flamme",b="Kultisten der Burning Blade tragen Reagenzien für das erste Feuersapta eines jungen Schamanen bei sich. Der Einsiedler Telf Joolam mischt die Pulver und Öle aus ihren Beuteln mit Feuerteer von Borstennacken-Stachelebern. Zusammen ergeben diese Zutaten einen Trank, der Einblick in das Reich des Feuers gewährt und den Schamanen auf die Geister der Flamme einstimmt."},{t="Verderbte Quellen, reine Sicht",b="Kultisten der Burning Blade nutzen die Flamme für Zerstörung und Teufelsmagie. Doch die Elemente in ihren Beuteln gehören weiterhin zu Hitze und Verbrennung. Schamanen lehren, dass elementare Kräfte in einem Spannungsverhältnis stehen: Feuer erschafft ebenso, wie es zerstört. Ein Schamane kann die Werkzeuge der Kultisten nutzen, um wahre Zwiesprache mit den Geistern zu erwecken."}},faq={{q="Wofür wird der Reagenzienbeutel verwendet?",a="Telf Joolam verwendet die Reagenzien zusammen mit Feuerteer von Borstennacken-Stachelebern, um ein Feuersapta zu brauen. Wer es trinkt, erhält als Schamane die visionäre Sicht, um die Elementargeister aufzusuchen und das Feuertotem zu erlangen.",al={"reagenzienbeutel verwendung","was bewirkt der reagenzienbeutel","reagenzienbeutel schamanenquest"}},{q="Wo finde ich einen Reagenzienbeutel?",a="Ihr könnt einen Beutel von Kultisten der Burning Blade in der Staubwindhöhle erbeuten, in den felsigen Höhen nordöstlich von Klingenhügel in Durotar.",al={"reagenzienbeutel beute","wo reagenzienbeutel bekommen","burning blade beutel fundort"}},{q="Warum braucht ein Schamane Hexenmeisterreagenzien?",a="Kultisten der Burning Blade füllen ihre Beutel mit Zutaten, die mit Feuermagie verbunden sind. Ihre Flammenrituale machen die Reagenzien zu nützlichen Katalysatoren für das Brauen eines Feuersaptas.",al={"warum hexenmeistergegenstände","warum reagenzien der burning blade","schamane verwendet teufelsgegenstände"}}},fx={ad39cae0={q="Was ist der Reagenzienbeutel?",a="Es handelt sich um einen kleinen Beutel, der von Kultisten der Burning Blade getragen wird, gefüllt mit rituellen Kräutern, Asche und okkulten Katalysatoren, die sie für ihre dunklen Zauber verwenden. Obwohl er für dunkle Hexerei gedacht ist, macht die schiere Konzentration feuriger Komponenten den gesamten Beutel zu einem mächtigen Bündel roher elementarer Materialien.",al={"was ist reagenzienbeutel","reagenzienbeutel lore","burning blade reagenzienbeutel"}},["2a611680"]={q="Woher stammt der Reagenzienbeutel?",a="Die Beutel werden von Kultisten der Burning Blade zusammengestellt und getragen, die sich in den Höhlen von Durotar und dem Brachland verstecken. Diese Hexenmeister sammeln und lagern spezifische Komponenten, die für ihre zerstörerischen Riten benötigt werden, und halten sie griffbereit, wann immer sie Flammen- und Shadow Magic wirken.",al={"reagenzienbeutel ursprung","wer hat den reagenzienbeutel hergestellt","woher kommt der reagenzienbeutel"}}},fp="22,209,23.316.0,28.307.0,35.189.0,32.126.0,40.160.0"}
P.entries["item:reconstructed-tome"] = {n="Rekonstruierter Foliant",s="In Hexenmeisterhänden vereint der Rekonstruierte Foliant die verstreuten Lehren der Kabale. Seine Seiten enthalten Riten, um einen Teufelsjäger aus dem Wirbelnden Nether zu beschwören und zu binden.",h="In Hexenmeisterhänden vereint der Rekonstruierte Foliant die verstreuten Lehren der Kabale.",kw={"bindung","dragonmaw","teufelsjäger","ratschet","rekonstruierter foliant","strahad farsan","tome of the cabal"},ang={["class:Warlock"]="Als Hexenmeister erschließt Ihr Euch durch das Zusammensetzen des Rekonstruierten Folianten dunkle Riten zur Beherrschung eines Teufelsjägers. Sein Hunger nach Magie lässt sich gegen feindliche Zauberwirker richten."},sec={{t="Ein wiederhergestelltes Grimoire",b="Hexenmeister der Allianz und der Horde suchen die zerrissenen Seiten des Tome of the Cabal. Sobald sie das Grimoire zusammengesetzt haben, ziehen sie okkulte Gelehrte zurate. Die Gelehrten brennen darauf, einen Blick auf seine seltenen Lehren zu werfen, bevor das fertige Buch übergeben wird."},{t="Schlüssel zum Teufelsjäger",b="Strahad Farsan erhält den wiederhergestellten Folianten und Kanalisierungsstäbe, die Dragonmaw-Zauberwirkern abgenommen wurden. Er ist ein Beschwörungsmeister nahe dem Hafen von Ratschet im Brachland. Die Rituale des Folianten liefern seinen Akolythen die Worte, um einen unersättlichen Teufelsjäger zu beschwören, zu bezwingen und an den Willen eines Hexenmeisters zu binden."}},faq={{q="Wozu dient der Rekonstruierte Foliant?",a="Der Rekonstruierte Foliant enthält Lehren der Kabale und Riten, um einen Teufelsjäger zu beschwören und zu binden. Ein Hexenmeister bringt ihn zusammen mit Kanalisierungsstäben für das Ritual zu Strahad Farsan in Ratschet.",al={"zweck des rekonstruierten folianten","warum wird der rekonstruierte foliant benötigt","verwendung des rekonstruierten folianten"}},{q="Wer ist Strahad Farsan?",a="Strahad Farsan ist ein erfahrener Beschwörer, der oberhalb des Hafens von Ratschet im Brachland lebt. Er beaufsichtigt Prüfungen für Hexenmeister, die gefährlichere Dämonen versklaven wollen.",al={"wer ist strahad","strahad farsans rolle"}},{q="Warum wollen die Gelehrten, die das Buch untersuchen, eine Abschrift?",a="Die Gelehrten, die beim Entziffern der zerrissenen Seiten helfen, finden die okkulten Texte der Kabale selten und faszinierend. Forscher unter den Zwergen und Verlassenen begehren dieses dämonische Wissen, das über ihre übliche Lektüre hinausgeht.",al={"wer hat ihn übersetzt","gelehrte rekonstruierter foliant"}},{q="Was wird neben dem Folianten noch für das Ritual benötigt?",a="Strahad benötigt drei Kanalisierungsstäbe, damit seine Akolythen das Beschwörungsritual aufrechterhalten können. Dragonmaw-Zauberwirker im Sumpfland besitzen die Stäbe.",al={"weitere benötigte gegenstände","was gehört zum rekonstruierten folianten"}}},fx={a9385a16={q="Was ist der Rekonstruierte Foliant?",a="Der Rekonstruierte Foliant ist die zusammengefügte Version des Tome of the Cabal, einem verbotenen Grimoire, das esoterische dämonische Rituale enthält. Nachdem die verstreuten Seiten und Bindungsmaterialien aus der ganzen Welt zusammengetragen wurden, setzen Gelehrte den fragmentierten Text mühsam wieder zusammen, sodass sein dunkles Wissen entziffert und genutzt werden kann.",al={"was ist der rekonstruierte foliant","hintergrund zum rekonstruierten folianten","buch tome of the cabal"}},d276d405={q="Woher stammt der Rekonstruierte Foliant und wer hat ihn hergestellt?",a="Das Buch ist die wiederhergestellte Form des alten Tome of the Cabal. Hexenmeister-Gelehrte setzen seine zerrissenen Kapitel und abgenutzten Einbände wieder zusammen, nachdem abenteuerlustige Praktizierende seine verstreuten Komponenten an gefährlichen Orten auf den Kontinenten geborgen haben.",al={"ursprung des rekonstruierten folianten","wer hat den rekonstruierten folianten gemacht","woher stammt der rekonstruierte foliant"}},["04500ccd"]={q="Warum ist der Rekonstruierte Foliant begehrt?",a="Hexenmeister und dunkle Gelehrte suchen den Folianten wegen der mächtigen, verbotenen Geheimnisse, die auf seinen wiedererlangten Seiten aufgezeichnet sind. Strahad Farsan benötigt seine spezifischen Riten, um einen aufstrebenden Hexenmeister bei der Beschwörung und Bindung eines bösartigen dämonischen Teufelsjägers anzuleiten, während örtliche Gelehrte eine Kopie rein wegen seines seltenen und faszinierenden magischen Wissens begehren.",al={"warum den rekonstruierten folianten wollen","warum will strahad den rekonstruierten folianten","zweck des rekonstruierten folianten"}}},fp="18,172,22.250.0,20.291.1,40.182.0,22.160.0,51.199.0,54.146.0"}
P.entries["item:recruitment-letter"] = {n="Anwerbungsbrief",s="In Durotar schickt Takrin Pathseeker vielversprechende Abenteurer nach Westen zum Dienst im Brachland. Sein Brief weist wehrfähige Freiwillige an, sich bei Kargal Schlachtnarbes Grenzaußenposten zu melden.",h="In Durotar schickt Takrin Pathseeker vielversprechende Abenteurer nach Westen zum Dienst im Brachland.",kw={"brachland","conscript of the horde","das wegekreuz","kargal schlachtnarbe","klingenhügel","anwerbungsbrief","takrin pathseeker"},ang={["faction:Horde"]="Als Mitglied der Horde markiert das Tragen dieses Briefes Euren Übergang von der örtlichen Verteidigung Durotars zum aktiven Militärdienst im Grenzgebiet Kalimdors.",["race:Orc"]="Als junger Orc ist das Vorlegen eines unterzeichneten Dienstbriefes bei einem Veteranen wie Kargal Schlachtnarbe ein früher Schritt, um unter Kriegshäuptling Thralls neuer Horde Ehre zu erringen."},sec={{t="Anwerbung für die Grenze",b="Rund um Klingenhügel beobachtet Takrin Pathseeker, wie junge Krieger und Späher sich beweisen. Er wählt jene aus, die stark genug für den Frontdienst sind, und gibt ihnen einen Brief für den Dienst im Brachland. Rekruten überqueren die Brücke über den Südstrom, verlassen Durotars geschützte rote Erde und verstärken die Wache der Horde gegen Stacheleber, Zentauren und Späher der Allianz."},{t="Meldung bei Schlachtnarbe",b="Gleich jenseits des Flusses empfängt Kargal Schlachtnarbe Rekruten am Außenposten. Der ergraute Veteran leitet den Posten und mustert jeden Eingezogenen, bevor er dessen Einberufung mit seiner Unterschrift bestätigt. Jene, deren Einberufung er unterzeichnet, werden bald weiter nach Westen zum Wegekreuz geschickt, wo die Grenzaußenposten unterbesetzt sind."}},faq={{q="Wer hat diesen Anwerbungsbrief geschrieben?",a="Takrin Pathseeker händigt den Brief aus. Der Orcspäher ist an der Straße von Klingenhügel stationiert und hält nach fähigen Rekruten Ausschau, die nach Westen ziehen.",al={"wer gibt den anwerbungsbrief","wer hat ihn geschrieben","takrin pathseeker brief"}},{q="Wohin muss dieser Brief gebracht werden?",a="Bringt den Brief zu Kargal Schlachtnarbe am Wachposten der Orcs gleich hinter der Brücke über den Südstrom, an der Grenze zwischen Durotar und dem Brachland.",al={"wohin den anwerbungsbrief bringen","anwerbungsbrief abgeben","wem den brief geben"}},{q="Was geschieht, sobald der Brief unterzeichnet ist?",a="Kargal unterzeichnet das Dokument, um Eure Einberufung offiziell zu bestätigen, und befiehlt Euch dann, tiefer in die Ebenen vorzudringen und Euch am Wegekreuz zum Dienst zu melden, wo dringend Verstärkung benötigt wird.",al={"was passiert nach kargals unterschrift","nächste quest nach anwerbungsbrief"}},{q="Warum zieht die Horde Abenteurer im Brachland ein?",a="Die Horde zieht Abenteurer ein, weil das Brachland ein weitläufiges, gefährliches Gebiet ist, das bedeutende Siedlungen der Horde verbindet. Zentaurenklans, aggressive Bristleback-Stacheleber und Operationen der Allianz sorgen für eine ständige Bedrohung, weshalb die Frontkommandanten jede wehrfähige Hand brauchen.",al={"warum wird angeworben","warum einberufung im brachland"}}},fx={e6a35429={q="Was ist der Anwerbungsbrief?",a="Der Anwerbungsbrief ist ein offizielles Einberufungsdokument, das an fähige Abenteurer in Durotar ausgegeben wird. Kundschafter Takrin Pathseeker händigt ihn denjenigen aus, die stark genug erscheinen, um die wachsende Präsenz der Horde an der rauen Grenze des Brachlands zu unterstützen, und empfiehlt sie den Kommandanten der militärischen Außenposten.",al={"was ist der anwerbungsbrief","zweck des anwerbungsbriefs","was ist das für ein brief"}},["6a5949ec"]={q="Warum will Kargal Schlachtnarbe den Anwerbungsbrief?",a="Kargal Schlachtnarbe befehligt den Grenzaußenposten, der die Brücke ins Brachland sichert, und benötigt dringend fähige Rekruten, um die Grenze zu verstärken. Der unterzeichnete Brief bestätigt, dass Ihr von Kundschafter Takrin Pathseeker geprüft wurdet und bereit seid, dort eingesetzt zu werden, wo die Horde Euch am meisten braucht.",al={"warum will kargal den brief","warum den anwerbungsbrief abgeben","anwerbungsbrief abgegeben"}}},fp="18,168,27.348.0,23.286.0,34.141.0,34.139.0,39.174.0,57.263.0"}
P.entries["item:red-burlap-bandana"] = {n="Rotes Sackleinenkopftuch",s="Bei den Weinbergen der Abtei im Nordhaintal sammelt Deputy Willem rote Kopftücher von erschlagenen Dieben der Defias. Der Stoff kennzeichnet die rangniedrigen Wegelagerer und Beutelschneider der Bruderschaft.",h="Bei den Weinbergen der Abtei im Nordhaintal sammelt Deputy Willem rote Kopftücher von erschlagenen Dieben der...",kw={"kopftuch","brotherhood of thieves","defias","maske","nordhain","rotes sackleinenkopftuch","willem"},ang={["class:Rogue"]="Als angehender Schurke könnt Ihr von Nordhains unbeholfenen Wegelagerern lernen, wie schnell undisziplinierte Gesetzlose zu leichten Zielen für die örtlichen Ordnungshüter werden.",["faction:Alliance"]="Als Mitglied der Allianz könnt Ihr sehen, wie rote Kopftücher bis vor die Tore der Abtei von Nordhain gelangen, ein Zeichen dafür, dass Sturmwind die Kontrolle über die ländlichen Grenzen des Königreichs verliert."},sec={{t="Ein Zeichen der Bruderschaft",b="In Nordhain tragen junge Rekruten und gewöhnliche Schläger der Bruderschaft der Defias rote Sackleinenmasken. Der billige, raue Stoff verbirgt ihre Gesichter und zeigt ihre Zugehörigkeit zur wachsenden Rebellion. Sie tragen diese Tücher in die östlichen Obstgärten, wo die örtlichen Wachen den roten Stoff als Beweis für in der Nähe getötete Diebe erkennen."}},faq={{q="Warum will Deputy Willem diese Kopftücher?",a="Deputy Willem sammelt die Kopftücher als Beweis dafür, dass ein Abenteurer Schläger der Defias nahe der Abtei von Nordhain getötet hat. Die Diebe tragen den roten Stoff offen und bestätigen damit, dass das Kopfgeld verdient wurde.",al={"warum kopftücher sammeln","willem kopftücher","brotherhood of thieves abgeben"}},{q="Wer trägt die roten Sackleinenkopftücher?",a="Wegelagerer und Schläger der Bruderschaft der Defias tragen rote Sackleinenkopftücher. Der grobe Stoff verbirgt ihre Gesichter und kennzeichnet ihre Treue zu den Gesetzlosen.",al={"wer trägt ein rotes kopftuch","hintergrund der defiasmasken","wer lässt rote kopftücher fallen"}},{q="Warum sind Diebe der Defias in Nordhain tätig?",a="Späher und Banditen der Defias lagern jenseits des Bachs östlich der Abtei von Nordhain, um Vorräte aufzutreiben und zu stehlen. Die Garnison der Abtei ist überlastet, wodurch die nahen Obstgärten den Wegelagerern schutzlos ausgeliefert sind.",al={"warum sind defias in nordhain","diebe nahe der abtei"}},{q="Was macht die Kopftücher rot?",a="Karminroter Farbstoff verleiht den billigen Sackleinenkopftüchern ihre rote Farbe. Der Farbton dient der Bruderschaft der Defias als Banner und Uniform und hilft ihren Mitgliedern, einander im Einsatz zu erkennen.",al={"warum sind defiasmasken rot","bedeutung des roten stoffs"}}},fx={c4ebebb0={q="Was ist ein Rotes Sackleinenkopftuch?",a="Ein Rotes Sackleinenkopftuch ist die charakteristische Stoffmaske, die von Mitgliedern der The Defias Brotherhood getragen wird. Günstig aus grobem Sackleinen hergestellt und rot gefärbt, verbirgt es das Gesicht des Trägers und kennzeichnet seine Zugehörigkeit zu der gesetzlosen Gilde. In Nordhain dient es als direkter Beweis für die Anwesenheit und Aktivität eines Schlägers östlich des Flusses.",al={"herkunft des roten sackleinenkopftuchs","was sind rote kopftücher","lore zum defias-kopftuch"}}},fp="18,180,25.319.0,43.189.0,34.148.0,47.188.0,28.172.0"}
P.entries["item:red-leather-bandana"] = {n="Rotes Lederkopftuch",s="In Westfall kennzeichnet das Rote Lederkopftuch jene, die der Krone von Sturmwind trotzen. Die Bruderschaft der Defias trägt es, um ihre Gesichter zu verbergen und ihre Sache zu bekunden.",h="In Westfall kennzeichnet das Rote Lederkopftuch jene, die der Krone von Sturmwind trotzen.",kw={"bruderschaft","defias","galiaan","maske","rotes lederkopftuch","späherkuppe","westfall"},ang={["class:Rogue"]="Als Schurke kennt Ihr die karmesinrote Maske als Zeichen des Banditenwesens im Untergrund der Menschenlande. Diebe, die mit militärischer Präzision organisiert sind, tragen sie.",["faction:Alliance"]="Für die Allianz bedeutet jedes rote Kopftuch, das einem gefallenen Gesetzlosen abgenommen wird, einen Banditen weniger, der Westfalls hungernde Bauern und bedrängte Miliz bedroht."},sec={{t="Zeichen der Bruderschaft",b="Auf Westfalls Feldern und verlassenen Höfen tragen Wegelagerer, Plünderer und aufständische Arbeiter karmesinrote Kopftücher, um ihre Gesichter zu verbergen. Die Volksmiliz auf der Späherkuppe sieht jedes davon als Beweis der Treue zu Edwin van Cleefs abtrünniger Bruderschaft. Späher Galiaan sammelt die Kopftücher von Reisenden, um die Bewegungen und schwindenden Zahlen der Bruderschaft in der gesamten Region zu verfolgen."}},faq={{q="Warum tragen die Defias rote Lederkopftücher?",a="Die Defias tragen rote Kopftücher, um bei Überfällen auf Höfe und Straßen ihre Gesichter zu verbergen. Sie zeigen damit auch ihre Treue zu Edwin van Cleefs Aufstand gegen Sturmwind.",al={"defias maske","warum rotes kopftuch","defias kopftuch bedeutung"}},{q="Wer lässt diese Kopftücher in Westfall sammeln?",a="Späher Galiaan von der Volksmiliz auf der Späherkuppe bittet Reisende, die Kopftücher zu sammeln. Mit ihnen verfolgt er die Bewegungen der Bande und bestätigt den Tod umherziehender Banditen.",al={"wer nimmt rote kopftücher","galiaan kopftuch quest","späherkuppe kopftuch abgeben"}},{q="Wo findet man diese Kopftücher?",a="Schurken der Defias, Wegelagerer und Schmuggler tragen diese Kopftücher in Lagern, auf Feldern und in Minen in ganz Westfall.",al={"rotes kopftuch beute","rote kopftücher farmen","wer lässt rotes lederkopftuch fallen"}}},fp="19,153,23.372.1,44.153.1,47.179.0,31.112.0"}
P.entries["item:red-linen-bandana"] = {n="Rotes Leinenkopftuch",s="Im Wald von Elwynn kennzeichnet das Rote Leinenkopftuch die Bruderschaft der Defias und verhüllt die Gesichter seiner Träger. Sara Roderwald im Holzfällerlager des Osttals will den Stoff für Kleidung und Verbände.",h="Im Wald von Elwynn kennzeichnet das Rote Leinenkopftuch die Bruderschaft der Defias und verhüllt die...",kw={"defiasmaske","eastvale","wald von elwynn","leinen","rotes leinenkopftuch","sara roderwald"},ang={["class:Rogue"]="Als Schurke kennt Ihr den karminroten Stoff, der über die untere Gesichtshälfte gebunden wird. Er kennzeichnet Wegelagerer und Beutelschneider in den Wäldern rund um die Hauptstadt.",["profession:Tailoring"]="Im ländlichen Elwynn können Weber das Leinen aus Banditenmasken zu Arbeitskleidung verarbeiten."},sec={{t="Zeichen der Defias",b="Im Nordhaintal tragen Initianden und gewöhnliche Schläger grobe Rupfenmasken. Das karminrote Leinen kennzeichnet die Treue vollwertiger Agenten zu Edwin van Cleefs abtrünniger Bruderschaft. Es signalisiert auch Auflehnung gegen die Krone von Sturmwind."},{t="Stoff für neue Zwecke",b="Sara Roderwald bittet Reisende, Kopftücher aus den Lagern der Gesetzlosen zu sammeln. Die Masken werden mit Banditen in Verbindung gebracht, doch ihr Leinen ist anständig. Gewaschen und mit der Nadel bearbeitet, kann der Stoff zu robuster Kleidung und Verbänden für die arbeitenden Menschen des Waldes werden."}},faq={{q="Warum tragen die Defias Rote Leinenkopftücher?",a="Agenten der Defias tragen Rote Leinenkopftücher, um ihre Gesichter zu verbergen. Der Stoff kennzeichnet auch ihre Treue zu Edwin van Cleefs Bruderschaft und ihre Auflehnung gegen Sturmwind.",al={"bedeutung der defiasmaske","warum rote masken","rotes kopftuch der defias"}},{q="Wie unterscheiden sie sich von den Masken, die in Nordhain getragen werden?",a="Die Schläger im Nordhaintal tragen grobe Rupfenmasken. Gestandene Agenten der Defias im gesamten Wald von Elwynn tragen feineres rotes Leinen.",al={"rupfen oder leinen","masken in nordhain","rupfenkopftuch"}},{q="Wer will diese Kopftücher sammeln?",a="Sara Roderwald im Holzfällerlager des Osttals will die Kopftücher. Sie wäscht die Masken und trennt sie auf, um daraus praktische Kleidung zu weben.",al={"wer nimmt rote leinenkopftücher","sara roderwald kopftuch","kopftuchquest abgeben"}},{q="Welche Gegner tragen Rote Leinenkopftücher bei sich?",a="Agenten der Defias im gesamten Wald von Elwynn tragen Rote Leinenkopftücher bei sich. Dazu gehören Defias Bandits, Ambushers, Rogue Wizards, Hafenarbeiter und Rädelsführer wie Morgan der Sammler.",al={"wer lässt rotes leinenkopftuch fallen","wo kopftücher farmen","kopftuchbeute der defias"}}},fp="17,190,18.223.0,16.251.0,42.165.0,54.122.0,36.127.0,39.178.0"}
P.entries["item:red-wool-bandana"] = {n="Rotes Wollkopftuch",s="Im Verlies von Sturmwind kennzeichnen Fetzen Roter Wollkopftücher die Bruderschaft der Defias. Gefangene reißen Wolle aus ihren Decken und tragen den roten Stoff als Zeichen des Trotzes.",h="Im Verlies von Sturmwind kennzeichnen Fetzen Roter Wollkopftücher die Bruderschaft der Defias.",kw={"defias","mac raskol","nikova raskol","rotes wollkopftuch","sturmwind","the color of blood","das verlies"},ang={["faction:Alliance"]="Für die Verteidiger der Allianz bedeutet das Beschaffen dieser Kopftücher grimmige Gerechtigkeit für den jungen Mac Raskol und einen Schlag gegen die Aufrührer, die das Stadtgefängnis besetzt halten.",["profession:Tailoring"]="Diese groben Kopftücher zeigen, wie verzweifelte Hände in Gefangenschaft derbe Wolldecken auftrennen und die Fasern erneut verwenden können."},sec={{t="Aus Trotz genäht",b="Im Verlies von Sturmwind halten Insassen der Bruderschaft der Defias ihre Identität lebendig. Heimlich reißen sie Fetzen aus den Wolldecken des Gefängnisses und nähen daraus rote Kopftücher. Wachen behandeln die Tücher als Schmuggelware, und ihr Fund kann tödliche Meutereien auslösen. Jedes Kopftuch verkündet, dass die Bruderschaft und ihre Rebellion selbst in Ketten fortbestehen."},{t="Die Rache einer Großmutter",b="Rote Wollkopftücher stehen mit dem Tod von Mac Raskol in Verbindung, einem vierzehnjährigen Gefängniswärter. Er ertappte Insassen dabei, wie sie Decken für Tücher zerrissen, und versuchte, sie zu maßregeln. Verurteilte der Defias stachen ihm in den Rücken. Seine trauernde Großmutter Nikova sucht nun Abenteurer, die den von Aufruhr erschütterten Kerker betreten, die Aufrührer dezimieren und ein karmesinrotes Tuch als Rachebeweis zurückbringen."}},faq={{q="Woher bekommen Gefangene im Verlies diese Kopftücher?",a="Insassen der Defias reißen die Kopftücher aus den Wolldecken, die ihnen das Gefängnis stellt. Obwohl sie entwaffnet und eingesperrt sind, verwandeln sie ihr karges Bettzeug in Zeichen des Trotzes, die sie in ihren Zellen tragen.",al={"woher kommen kopftücher","verlies kopftuch herkunft","wie entstehen rote kopftücher"}},{q="Wer will diese Kopftücher sammeln lassen?",a="Nikova Raskol, eine trauernde Großmutter in Sturmwind, bittet Abenteurer, die Kopftücher zu sammeln. Ihr vierzehnjähriger Enkel Mac bewachte das Verlies, und Gefangene ermordeten ihn, nachdem er sie beim Anfertigen der Tücher ertappt hatte.",al={"wer braucht rote wollkopftücher","color of blood questgeber","nikova raskol kopftuch"}},{q="Warum ist es den Gefangenen so wichtig, rote Tücher zu tragen?",a="Die Bruderschaft der Defias trägt rote Masken und Kopftücher als Bandenfarben und Uniform. Hinter Gittern helfen die Fetzen den Insassen, ihren Rang, ihre Moral und ihren Zusammenhalt zu bewahren.",al={"warum rote kopftücher","defias rotes symbol","bedeutung des roten kopftuchs"}},{q="Welche Insassen tragen sie bei sich?",a="Fast jedes aufständische Mitglied der Defias im Verlies trägt eines bei sich, darunter Defias Captives, Inmates, Prisoners, Insurgents und Convicts.",al={"wer lässt rotes wollkopftuch fallen","verlies kopftuch beute"}}},fx={["7f0c1a2a"]={q="Was ist ein Rotes Wollkopftuch?",a="Ein Rotes Wollkopftuch ist ein provisorischer purpurroter Schal, der von inhaftierten Mitgliedern der The Defias Brotherhood im Inneren der Sturmwind Stockade angefertigt wird. Indem sie ihre vom Gefängnis ausgegebenen Wolldecken zerfetzen und färben, stellen die Insassen diese Stoffabzeichen her, um offen ihre Zugehörigkeit zur Brotherhood zu zeigen und ihre Bandenidentität sogar hinter Gittern aufrechtzuerhalten.",al={"was ist ein rotes wollkopftuch","rotes wollkopftuch gegenstand","rotes kopftuch aus dem verlies"}}},fp="16,166,20.335.0,25.366.0,54.181.0,35.218.0,60.156.0,25.134.0"}
P.entries["item:remaining-drops-of-purest-water"] = {n="Verbleibende Tropfen reinsten Wassers",s="In ganz Kalimdor und Lordaeron warten Verbleibende Tropfen reinsten Wassers auf eine gefährliche Reise. Brine sammelte das Wasser für einen Trank, der Schamanen helfen soll.",h="In ganz Kalimdor und Lordaeron warten Verbleibende Tropfen reinsten Wassers auf eine gefährliche Reise.",kw={"kohlenbecken von everfount","brine","call of water","verderbte manifestation","reinstes wasser","silberwald","wassertotem"},ang={["class:Shaman"]="Als Schamane tragt Ihr die Tropfen vom trockenen Brachland an die verseuchte Küste des Silberwalds als Teil Eurer Prüfungen zur Beherrschung des Wassers. Diese Pilgerreise ist unerlässlich, um Euer Wassertotem zu erhalten.",["faction:Horde"]="Als Mitglied der Horde reist Ihr aus dem Gebiet der Horde in Kalimdor zu den gefährdeten Besitzungen der Verlassenen im Silberwald. Über diese Entfernung hinweg bringt die Pilgerreise spirituelle Erneuerung angesichts der Verderbnis der Geißel."},sec={{t="Ein Heilmittel für verdorbenes Wasser",b="Im Brachland bereitet Brine einen Trank aus Wasser zu, das in ganz Kalimdor und Lordaeron gesammelt wurde. Ein Teil davon gewährt Schamanen einen Blick auf ferne Elemente. Die übrigen Tropfen dienen einem schwierigeren Zweck.\n\nSchamanen tragen sie an die Küste des Silberwalds, nahe dem Grabmal, wo das Kohlenbecken von Everfount steht. Dort verbrennen sie die Tropfen zusammen mit den Armschienen eines gefallenen, verdorbenen Elementars. Das reine Wasser durchdringt die Verderbnis der untoten Seuche und ruft einen unverdorbenen Wassergeist herbei, um mit dem Schamanen Zwiesprache zu halten. So wird ihre Verbindung mit dem Element vollendet."}},faq={{q="Wofür werden diese Tropfen verwendet?",a="An der Küste des Silberwalds werden die Tropfen zusammen mit den Armschienen einer verderbten Wassermanifestation auf dem Kohlenbecken von Everfount verbrannt. Das Ritual reinigt den verderbten Elementarschrein und beschwört einen unverdorbenen Wassergeist.",al={"was bewirken verbleibende tropfen","zweck der verbleibenden tropfen","reinstes wasser verwenden"}},{q="Woher stammt die Flüssigkeit?",a="Brine, eine Orcschamanin, die auf einem Hügel im südlichen Brachland lebt, hat den Trank zubereitet. Sie stellt ihn während der spirituellen Prüfungen angehender Schamanen her, und diese Tropfen sind der Rest.",al={"wer hat reinstes wasser hergestellt","herkunft der tropfen","brines wassertropfen"}},{q="Warum wird das Ritual im weit entfernten Silberwald vollzogen?",a="Ein Wasserschrein an der Küste des Silberwalds, westlich des Grabmals, wurde von der Seuche des Untodes verderbt. Seine Elementargeister wurden feindselig und entstellt. Die Reinigung des Beckens stellt die Hingabe und die Beherrschung der Kräfte eines Schamanen über große Entfernungen hinweg auf die Probe.",al={"warum silberwald","warum in den silberwald reisen","wasserschrein im silberwald"}},{q="Was geschieht, wenn sie das Kohlenbecken berühren?",a="Zusammen mit den verderbten Armschienen in die Flammen des Kohlenbeckens gegossen, knistern die Tropfen im Feuer. Die Beschwörung beseitigt die verbliebene Seuche und ruft eine reine Wassermanifestation herbei.",al={"ritual am kohlenbecken","was geschieht auf dem kohlenbecken","ritual am kohlenbecken von everfount"}}},fx={db79eea5={q="Was sind die Verbleibenden Tropfen reinsten Wassers?",a="Diese kleine Phiole enthält die letzten Überreste des reinigenden Tranks, der von dem Eremiten Brine im südlichen Brachland gebraut wurde. Angereichert mit Wasser aus dem Brachland, Tarrens Mühle und dem Eschental besitzt die starke Flüssigkeit enorme reinigende Eigenschaften. Obwohl nur noch wenige Tropfen übrig sind, reicht ihre konzentrierte Reinheit aus, um anhaltende Verderbnis zu durchdringen, wenn sie in elementaren Riten dargebracht wird.",al={"was sind die verbleibenden tropfen reinsten wassers","was sind die tropfen reinsten wassers","lore zu den tropfen reinsten wassers"}},["55d7092f"]={q="Warum möchte Islen Wasserdeuter, dass Ihr die Verbleibenden Tropfen reinsten Wassers benutzt?",a="Islen Wasserdeuter verlangt, dass Ihr die Tropfen auf das Becken der Immerquelle im Silberwald gießt. Ein heiliger Wasserschrein dort ist der untoten Plage zum Opfer gefallen, was seine örtlichen Geister für schamanische Kommunikation taub gemacht hat. Indem Ihr diese verbleibenden Tropfen zusammen mit den Armschienen einer gefallenen verderbten Manifestation darbringt, kann das Becken ein Reinigungsritual entzünden, das stark genug ist, um einen reinen Wassergeist zu beschwören.",al={"warum tropfen reinsten wassers benutzen","warum werden die verbleibenden tropfen reinsten wassers benötigt","warum braucht man tropfen reinsten wassers"}}},fp="31,152,27.549.0,30.221.0,31.181.0,61.235.0,41.179.0"}
P.entries["item:remedy-of-arugal"] = {n="Arznei des Arugal",s="Im Silberwald sucht Dalar Morgenweber Arugals Zauber, um zu verstehen, wie dessen Worgenmagie wirkt.",h="Im Silberwald sucht Dalar Morgenweber Arugals Zauber, um zu verstehen, wie dessen Worgenmagie wirkt.",kw={"arugal","arugal's folly","dalar morgenweber","verstaubte zauberbücher","moonrage","arznei des arugal","das grabmal","silberwald"},ang={["class:Mage"]="Als Magier der Verlassenen teilt Ihr womöglich Dalar Morgenwebers Verachtung für Arugals stümperhafte, rücksichtslose Experimente und erkennt zugleich die Gefahr ungezügelter Beschwörungsmagie.",["race:Undead"]="Als Verlassener helft Ihr, diesen Zauber zu sichern, als frühen, entscheidenden Schritt gegen die wilden Worgen, die die Grenzen des Silberwalds bedrohen."},sec={{t="Hinterlassenschaften eines Magiers",b="Bevor er Burg Shadowfang einnahm, fand Erzmagier Arugal auf einem verlassenen Weizenbauernhof nördlich der Flussbrücke im Silberwald Unterschlupf. Zwischen Ackergeräten und verrottenden Dielen hinterließ er Zauberbücher, die seine seltsamen Künste festhielten. Eine Schriftrolle, die Arznei des Arugal, beschreibt frühe Methoden und magische Formeln aus seinen Experimenten mit den Transmutationen, die die einheimische Bevölkerung verfluchten."},{t="Prüfender Blick der Verlassenen",b="Am Grabmal hält Dalar Morgenweber, ein Zauberwirker der Verlassenen, wenig von Arugals Ansehen. Er betrachtet Arugals Verstand als zerbrechlich und durchschaubar. Dennoch muss Morgenweber verstehen, wie der Worgenfluch wirkt. Die Bergung der Arznei verschafft Agenten der Verlassenen das von ihm gesuchte arkane Wissen, um Arugals wachsender Bedrohung entgegenzuwirken und den Silberwald für Fürstin Sylvanas zu sichern."}},faq={{q="Was ist die Arznei des Arugal?",a="Die Arznei des Arugal hält die arkanen Methoden fest, die Arugal bei seinen ersten Experimenten mit Worgenmagie im Silberwald anwandte.",al={"was ist die arznei des arugal","arugal arznei gegenstand","arznei zauber"}},{q="Wo wurde die Arznei zurückgelassen?",a="Arugal hinterließ die Arznei in verstaubten Zauberbüchern im Obergeschoss eines verlassenen Weizenbauernhofs nördlich der Flussbrücke im Silberwald.",al={"wo findet man die arznei des arugal","arznei des arugal fundort","bauernhof zauberbuch"}},{q="Warum will Dalar Morgenweber diesen Zauber?",a="Dalar Morgenweber will Arugals Magie studieren, damit die Verlassenen Wege finden, ihr entgegenzuwirken und den Silberwald zu sichern.",al={"warum will dalar die arznei","dalar morgenweber arznei"}},{q="Wer bewacht die Zauberbücher auf dem Bauernhof?",a="Arugals wolfsartige Diener haben den Bauernhof befallen. Wenn jemand die verstaubten Zauberbücher im zweiten Stock anrührt, springt ein Moonrage Darkrunner hervor, um die Besitztümer seines Meisters zu verteidigen.",al={"was greift auf dem bauernhof an","zauberbuch hinterhalt"}}},fx={["157696b2"]={q="Woher stammt die Arznei des Arugal und wer hat sie hergestellt?",a="Die Arznei des Arugal ist ein Zauberspruch, der von Erzmagier Arugal selbst während seiner frühen Tage im Silberwald verfasst wurde. Nachdem seine Pläne begannen, sich zu entfalten, wohnte er kurzzeitig auf einer Weizenfarm nördlich der Hauptflussbrücke und hinterließ staubige Zauberbücher, die seine Forschungen enthielten.",al={"wer hat die arznei des arugal hergestellt","herkunft der arznei des arugal","woher kommt die arznei des arugal"}}},fp="16,96,18.379.0,17.375.0,29.124.0,33.136.0,42.113.0,38.171.0"}
P.entries["item:rendered-spores"] = {n="Weiterverarbeitete Sporen",s="Weiterverarbeitete Sporen werden durch das Brachland eilig nach Donnerfels gebracht, bevor ihre Emulsion zerfällt. Apothekerin Zamah muss sie unterhalb der Stadt stabilisieren.",h="Weiterverarbeitete Sporen werden durch das Brachland eilig nach Donnerfels gebracht, bevor ihre Emulsion...",kw={"apotheker helbrim","apothecary zamah","brachland","das wegekreuz","emulsion","die teiche der visionen","weiterverarbeitete sporen","donnerfels"},ang={["race:Tauren"]="Als Taure seht Ihr, wie Apotheker der Verlassenen in den heiligen Teichen der Visionen mit seltsamen Pflanzen des Brachlands experimentieren. Ihre Arbeit spiegelt das angespannte, zweckmäßige Bündnis wider, das innerhalb von Donnerfels geschmiedet wurde.",["race:Undead"]="Als Untoter gehört Ihr einem Volk an, dessen Royal Apothecary Society in ganz Kalimdor nach biologischen Verbindungen sucht, um den Verlassenen zu helfen. Schnelle Kuriere verbinden Feldforscher wie Helbrim mit Spezialisten wie Zamah."},sec={{t="Eine flüchtige Mischung",b="Nahe den feuchten Oasen des Brachlands sammelt Apotheker Helbrim Pilzsporen und verarbeitet sie zu einer aktiven chemischen Emulsion. Die Mischung ist instabil. Nach fünfundvierzig Minuten zerfällt sie und kann nicht mehr untersucht werden."},{t="Lieferung zu den Teichen der Visionen",b="An seinem abgelegenen Außenposten kann Apotheker Helbrim die Veredelung der Emulsion nicht abschließen. Sie muss seine Kollegin von den Verlassenen, Apothekerin Zamah, unterhalb der Anhöhe der Geister in Donnerfels erreichen. In den Teichen der Visionen hat Zamah die Ausrüstung und Reagenzien, um die Sporen erneut zu versiegeln und ihre Verarbeitung für die Royal Apothecary Society abzuschließen."}},faq={{q="Wofür werden Weiterverarbeitete Sporen verwendet?",a="Apotheker Helbrim verarbeitet Pilzmaterial zu einer Emulsion, die von der Royal Apothecary Society untersucht werden soll. In Donnerfels setzt Apothekerin Zamah damit die Untersuchung der seltsamen Gewächse fort, die sich im Brachland ausbreiten.",al={"zweck der weiterverarbeiteten sporen","was macht zamah mit sporen","warum weiterverarbeitete sporen"}},{q="Warum gibt es für die Emulsion ein Zeitlimit?",a="Die von Apotheker Helbrim hergestellte Emulsion ist flüchtig und beginnt zu zerfallen, sobald sie angemischt ist. Ihre Wirksamkeit hält nur fünfundvierzig Minuten an, also muss sie über die Ebenen nach Donnerfels gelangen, bevor sie wirkungslos wird.",al={"warum haben weiterverarbeitete sporen ein zeitlimit","warum verfallen sporen","haltbarkeit weiterverarbeiteter sporen"}},{q="Wer hat diese Sporen hergestellt?",a="Im Wegekreuz im Brachland verarbeitet Apotheker Helbrim rohe Pilzsporen, die nahe den Oasen gesammelt wurden, zu einer instabilen flüssigen Verbindung.",al={"wer hat weiterverarbeitete sporen hergestellt","wer verarbeitet die sporen","helbrim sporen"}},{q="Wohin muss die Mischung gebracht werden?",a="Die Mischung muss Apothekerin Zamah in den Teichen der Visionen unterhalb der Anhöhe der Geister in Donnerfels, der Hauptstadt der Tauren, erreichen.",al={"wohin weiterverarbeitete sporen bringen","zamah standort","teiche der visionen standort"}}},fx={["7897c588"]={q="Was sind Weiterverarbeitete Sporen?",a="Weiterverarbeitete Sporen sind der verarbeitete Extrakt seltsamer Pilzgewächse, die im gesamten Brachland geerntet wurden. Apotheker Helbrim kochte die rohen Sporen auf und verarbeitete sie zu einer flüchtigen, instabilen flüssigen Emulsion, wobei er die Mischung sorgfältig für weitere alchemistische Studien durch die Königliche Apothekergesellschaft vorbereitete.",al={"was sind weiterverarbeitete sporen","infos zu weiterverarbeiteten sporen","was genau sind die weiterverarbeiteten sporen"}}},fp="15,153,18.219.0,31.310.0,34.217.0,40.211.0,25.134.0,34.120.0"}
P.entries["item:renferrel-s-findings"] = {n="Renferrels Funde",s="Im Silberwald tragen Renferrels Funde seine Forschung nach Süden zu Tarrens Mühle. Apotheker Renferrel stellte die Notizen im Grabmal für Apotheker Lydon zusammen, der beim Brauen der neuen Seuche der Verlassenen hilft.",h="Im Silberwald tragen Renferrels Funde seine Forschung nach Süden zu Tarrens Mühle.",kw={"funde","lydon","neue seuche","renferrel","königliche apothekervereinigung","das grabmal","tarrens mühle"},ang={["faction:Horde"]="Als Mitglied der Horde wisst Ihr, dass Kuriere mit Renferrels Papieren Außenposten wie das Grabmal und Tarrens Mühle verbinden und die Stellung der Horde in ganz Lordaeron stärken.",["race:Undead"]="Als Untoter wisst Ihr, dass diese Papiere Sylvanas Windläufers Bestreben dienen: eine neue Seuche gegen die Geißel und die lebenden Feinde zu vollenden, die in die Ländereien der Verlassenen vordringen."},sec={{t="Eine Seuche in Entwicklung",b="Im Grabmal hält Apotheker Renferrel seine Arbeit an der neuen Seuche fest. Die Königliche Apothekervereinigung untersteht direkt Fürstin Sylvanas Windläufer, der Dunklen Fürstin. Die über Lordaeron verstreuten Forscher müssen ihre Arbeit zusammenführen, um einen Durchbruch zu erzielen. Deshalb schickt Renferrel seine Funde nach Süden zu Tarrens Mühle, wo andere Apotheker auf seinen Ergebnissen aufbauen können."},{t="Nach Tarrens Mühle",b="Renferrels Papiere verbinden den Silberwald mit dem Vorgebirge des Hügellands und der alchemistischen Arbeit der Verlassenen. Apotheker Lydon erwartet die Notizen in Tarrens Mühle, wo er sie mit seiner eigenen Forschung gegen die Lebenden und die Geißel vergleichen kann. Die Straßen durch Hillsbrad sind umkämpft, daher ist die Vereinigung auf verlässliche Kuriere angewiesen. Ohne sie würde ihre verstreute Forschung bald ins Stocken geraten."}},faq={{q="Was enthalten Renferrels Funde?",a="Renferrels Funde enthalten Apotheker Renferrels neueste Forschungsergebnisse und Versuchsdaten aus dem Silberwald. Die Notizen betreffen die Arbeit der Verlassenen am Brauen einer neuen Seuche.",al={"was sind die funde","renferrels forschung","was steht in den notizen"}},{q="Wer soll diese Forschungsergebnisse erhalten?",a="Apotheker Lydon soll die Dokumente erhalten. Er betreibt Seuchenforschung in Tarrens Mühle, einer Siedlung der Verlassenen im Vorgebirge des Hügellands.",al={"wer erhält renferrels funde","wohin gehen die funde","lieferziel"}},{q="Warum tauschen die Apotheker Notizen aus?",a="Fürstin Sylvanas Windläufer hat der Königlichen Apothekervereinigung befohlen, eine neue Seuche zu erschaffen. Die Apotheker glauben, dass der Vergleich ihrer Ergebnisse viel früher zu einem Durchbruch führen wird als die Arbeit allein.",al={"warum funde teilen","warum an lydon senden","kommunikation der apotheker"}},{q="Wo führt Apotheker Renferrel seine Experimente durch?",a="Apotheker Renferrel führt seine Experimente im Grabmal durch, dem wichtigsten Außenposten der Verlassenen im Herzen des Silberwalds.",al={"wo ist renferrel","standort von apotheker renferrel","wer schrieb renferrels funde"}}},fx={f680c460={q="Was sind Renferrels Funde?",a="Renferrels Funde sind eine Sammlung alchemistischer Notizen und Forschungsdokumente, die von Apotheker Renferrel zusammengestellt wurden. Sie beschreiben seine laufenden Experimente, die im Auftrag der Königlichen Apothekergesellschaft durchgeführt wurden, und sind dazu bestimmt, direkt mit seinen Fachkollegen in ganz Lordaeron geteilt zu werden.",al={"was sind renferrels funde","gegenstand renferrels funde","was sind das für funde"}},bf8d559a={q="Woher stammen Renferrels Funde und wer hat sie angefertigt?",a="Diese Dokumente wurden von Apotheker Renferrel verfasst, einem ehrgeizigen Forscher, der am Grabmal im Silberwald stationiert ist. Während er fleißig unter dem Mandat der Verlassenen arbeitete, verfasste er diese Notizen, um seine Fortschritte und Durchbrüche beim Mischen experimenteller Gebräue festzuhalten.",al={"wer schrieb renferrels funde","woher stammen renferrels funde","schöpfer von renferrels funden"}},["21b2c0f4"]={q="Warum möchte jemand Renferrels Funde haben?",a="Die Königliche Apothekergesellschaft steht unter immensem Druck von Fürstin Sylvanas Windläufer, eine A New Plague zu brauen. Im Glauben, dass Zusammenarbeit ihre düstere Arbeit beschleunigen wird, sandte Renferrel seine Forschung an Apotheker Lydon in Tarrens Mühle, der begierig darauf ist, die Methoden seines Kollegen zu studieren und sie in seine eigenen Bemühungen zu integrieren.",al={"warum renferrels funde liefern","wer will renferrels funde","warum will lydon renferrels funde"}}},fp="20,209,23.354.0,14.377.0,36.173.0,41.139.0,39.189.0,56.127.0"}
P.entries["item:report-on-the-defias-brotherhood"] = {n="Bericht über die Bruderschaft der Defias",s="In der Burg Sturmwind erreichen die Erkenntnisse über die Bruderschaft der Defias den königlichen Hof. Stadtarchitekt Baros Alexston vertraut den Bericht dem Abenteurer an, der die Verschwörung aufgedeckt hat.",h="In der Burg Sturmwind erreichen die Erkenntnisse über die Bruderschaft der Defias den königlichen Hof.",kw={"audienz beim könig","baros alexston","defias","bericht","burg sturmwind","vancleef","westfall"},ang={["faction:Alliance"]="Mit der Übergabe des Berichts wird der lange Kampf, Westfall zu sichern und Sturmwinds Anführer vor dem Aufstand an den Grenzen zu warnen, vor den königlichen Hof getragen.",["race:Human"]="Als Mensch des Reiches tragt Ihr einen Bericht über den ungelösten Konflikt zwischen Sturmwinds Adelshaus und den Steinmetzen, die die Stadt wieder aufgebaut haben."},sec={{t="Eine Depesche für den Thron",b="Stadtarchitekt Baros Alexston verfasste den Bericht für Sturmwinds Anführer nach einer langen Untersuchung der Unruhen in Westfall und den angrenzenden Gebieten. Er vertraute ihn dem Abenteurer an, der die Verschwörung aufgedeckt hatte.\n\nDer Bericht wird für eine persönliche Audienz zur Burg Sturmwind gebracht. Dort geht es um die Erkenntnisse über die Pläne der Verschwörer und die Gefahr, die sie für das Königreich darstellen."},{t="Empfang in der Burg",b="König Varian Wrynn ist auf diplomatischer Reise, als der Bote den Thronsaal erreicht. Königliche Berater und die Regentschaft, die für den jungen König Anduin herrscht, nehmen den Bericht an seiner Stelle entgegen. Sie loben den Boten dafür, VanCleefs Pläne vereitelt zu haben.\n\nLady Katrana Prestor gehört zu den anwesenden Mitgliedern des Hofes, als die Warnungen die Regentschaft erreichen."}},faq={{q="Was ist der Bericht über die Bruderschaft der Defias?",a="Der Bericht ist eine offizielle Unterrichtung von Baros Alexston. Er bündelt Erkenntnisse über Edwin van Cleef, seine unterirdische Armee und die umfassendere Verschwörung der Defias gegen Sturmwind.",al={"was ist dieser bericht","defias bericht gegenstand","baros alexston bericht"}},{q="Wer hat diesen Bericht verfasst?",a="Sturmwinds Stadtarchitekt Baros Alexston hat den Bericht verfasst. Einst arbeitete er mit den Steinmetzen zusammen, bevor sie sich abspalteten und die Bruderschaft der Defias gründeten.",al={"wer verfasste den defias-bericht","verfasser des berichts"}},{q="Warum überbringe ich diesen Bericht der Burg Sturmwind?",a="Baros Alexston glaubt, dass der Abenteurer, der die Verschwörung aufgedeckt hat, es verdient, dem Thron die Erkenntnisse vorzutragen. Er hofft, dass Ihr für den Schutz des Reiches königliche Anerkennung erhaltet.",al={"warum überbringe ich das","audienz beim könig übergabe"}},{q="Liest König Varian den Bericht?",a="Nein. König Varian Wrynn ist auf diplomatischer Reise, als Ihr die Burg Sturmwind erreicht. Sein Hof und die Regentschaft nehmen den Bericht an seiner Stelle entgegen.",al={"liest der könig ihn","varian wrynn audienz"}}},fp="32,178,25.367.0,21.337.1,45.170.1,22.160.1,43.182.0,33.138.0"}
P.entries["item:resonite-crystal"] = {n="Resonitkristall",s="In der Steinschlaghöhle graben Kobolde fieberhaft nach Resonitkristallen. Ihre Arbeit hat Mor'rogal in Sonnenfels beunruhigt.",h="In der Steinschlaghöhle graben Kobolde fieberhaft nach Resonitkristallen.",kw={"boulderslide","kristall","irdische","kobold","mor'rogal","resonit","steinkrallengebirge","titanen"},ang={["class:Shaman"]="Als Schamane könnt Ihr die beunruhigende Resonanz in Resonitkristallen spüren. Es ist schlummernde, urzeitliche Erdmagie, hinterlassen von Schöpfungen der Titanen, die unter dem Gebirge begraben liegen.",["profession:Mining"]="Als Bergarbeiter findet Ihr Resonit in äußerst dichten Formationen, die sich von gewöhnlichen Kupfer- oder Zinnadern unterscheiden. Um es zu erreichen, müsst Ihr an aggressiven Kobolden vorbei in die tiefsten unterirdischen Schichten vordringen."},sec={{t="Uralte Resonanz",b="Tief in der Steinschlagklamm graben Kobolde fieberhaft nach Resonitkristallen. Ihr plötzliches Interesse alarmiert die Schamanen in Sonnenfels. Mor'rogal untersucht die Steine und hört ein leises magisches Summen. Er erkennt Spuren der Magie der Irdischen. Die Anzeichen deuten auf eine uralte Schicht hin, die von den Titanen geformt wurde."},{t="Die Erde anzapfen",b="Die Koboldgräber sind tief genug vorgedrungen, um die uralten Irdischen zu stören. Die Titanen formten die Irdischen, um die Fundamente der Welt zu behauen und zu gestalten. Ihre Magie haftet noch immer am umliegenden Gestein. Agenten der Horde sammeln Resonitkristalle, um zu ergründen, was die Kobolde antreibt, und die Macht des verzauberten Steins gegen alles zu wenden, was darunter schlummert."}},faq={{q="Wo findet man Resonitkristalle?",a="Resonitkristalle liegen in der Steinschlaghöhle, tief in der Steinschlagklamm im südöstlichen Steinkrallengebirge.",al={"resonit fundort","wo resonit finden","resonitkristalle farmen"}},{q="Warum bauen die Kobolde Resonitkristalle ab?",a="Die Kobolde bauen die seltenen Kristalle fieberhaft ab, doch Mor'rogal weiß nicht, warum. Er bittet um Proben und eine Untersuchung der Höhlentiefen, um herauszufinden, was sie dort tun.",al={"warum graben kobolde","kristallplan der kobolde","boulderslide kobolde"}},{q="Welche Art von Macht steckt in einem Resonitkristall?",a="Mor'rogal vermutet, dass die Kristalle mit etwas Beunruhigendem unter dem Gebirge verbunden sind. Er erkennt ihre magische Natur, nachdem ihn Proben und Neuigkeiten aus der Höhle erreichen.",al={"resonitkristall magie","was ist resonit","ist resonit magisch"}},{q="Wer untersucht diese Kristalle?",a="Mor'rogal, ein Tauren in Sonnenfels im Steinkrallengebirge, untersucht die Kristalle. Er will den plötzlichen Anstieg der Koboldaktivität verstehen und einen Weg finden, dem freigelegten Bösen entgegenzuwirken.",al={"wer will resonit","mor'rogal kristalle","sonnenfels resonit"}},{q="Was sind die Irdischen, die im Zusammenhang mit dem Kristall erwähnt werden?",a="Die Irdischen wurden von den Titanen erschaffen, um das Land zu formen. Mor'rogal untersucht eine mögliche Verbindung zwischen ihnen und Resonit.",al={"was sind irdische","irdische titanen verbindung"}}},fx={c14b6c8c={q="Was ist ein Resonitkristall?",a="Resonit ist ein seltener Mineralkristall, der in der Steinschlaghöhle im Steinkrallengebirge gefunden wird. Der hektische Bergbau der Kobolde hat Mor'rogal alarmiert, der Proben und Neuigkeiten aus der Höhle anfordert, um Nachforschungen anzustellen.",al={"was ist resonit","lore zum resonitkristall","resoniterz"}},af246400={q="Warum möchte jemand Resonitkristalle haben?",a="Mor'rogal möchte Erzproben, um den hektischen Bergbau der Kobolde zu verstehen und zu erfahren, was sich unter der Steinschlagklamm befindet. Er bittet einen Abenteurer, die Höhle zu erkunden sowie die Kristalle zu sammeln.",al={"warum resonitkristalle sammeln","wer will resonitkristalle","zweck des resonitkristalls"}}},fp="16,131,17.290.1,17.334.1,34.123.0,45.172.0,44.170.0,31.194.0,60.129.0"}
P.entries["item:restabilization-cog"] = {n="Restabilisationszahnrad",s="Vor Gnomeregans Toren tragen Lepragnome noch immer Restabilisationszahnräder. In Kharanos brauchen Tüftler intakte Zahnräder für eine Maschine, die die Lepramutation rückgängig machen soll.",h="Vor Gnomeregans Toren tragen Lepragnome noch immer Restabilisationszahnräder.",kw={"dun morogh","gibblewilt","gnomeregan","kharanos","lepragnom","operation recombobulation","razzle flinkspross","restabilisationszahnrad"},ang={["profession:Engineering"]="Als Ingenieur erkennt Ihr, wie Restabilisationszahnräder in gnomische Maschinen wie den Recombobulator passen.",["race:Gnome"]="Als nach Dun Morogh verbannter Gnom nehmt Ihr Euren verderbten Artgenossen Maschinerie ab, in der Hoffnung, ein Heilmittel für Gnomeregans Gefallene zu finden."},sec={{t="Bauteile für ein Heilmittel",b="Strahlung überflutete Gnomeregan bei einem gescheiterten Versuch, die eindringenden Troggs auszulöschen. Zahllose Gnome wurden krank und feindselig und flohen dann als Verbannte aus ihrer Heimat. Selbst in ihrem Wahnsinn tragen sie komplizierte gnomische Maschinerie bei sich.\n\nOzzie Wechselvolt und Razzle Flinkspross glauben, dass sich die schreckliche Veränderung rückgängig machen lässt. Ihr Prototyp des Recombobulation Device benötigt Bauteile, die den Befallenen vor Gnomeregans Toren abgenommen werden. Intakte Restabilisationszahnräder sollen seine inneren Verbrennungssysteme ins Gleichgewicht bringen."}},faq={{q="Wofür wird ein Restabilisationszahnrad verwendet?",a="In Kharanos benötigt Tüftler Razzle Flinkspross Restabilisationszahnräder für den Recombobulator. Zusammen mit Gyromechanic Gears sind sie Teil der experimentellen Maschine, die verstrahlte Lepragnome heilen soll.",al={"zweck der zahnräder","was bewirkt ein restabilisationszahnrad","warum zahnräder sammeln"}},{q="Wo sind diese Zahnräder zu finden?",a="Lepragnome und der wahnsinnige Gibblewilt tragen diese Zahnräder bei sich. Sie streifen bei den äußeren Toren und in den Gräben vor Gnomeregan im westlichen Dun Morogh umher.",al={"restabilisationszahnrad fundort","wer lässt zahnräder fallen","wo zahnräder farmen"}},{q="Kann der Recombobulator die Lepragnome tatsächlich heilen?",a="Razzle Flinkspross und Ozzie Wechselvolt glauben, dass kalibrierte Maschinerie die Mutation rückgängig machen kann. Ob der Recombobulator Geist und Körper der Lepragnome wiederherstellen kann, bleibt unerprobt, und die Suche nach einem Heilmittel geht weiter.",al={"funktioniert der recombobulator","gibt es ein heilmittel für lepragnome"}}},fx={["8ac7e8f1"]={q="Was ist ein Restabilisationszahnrad?",a="Ein Restabilisationszahnrad ist eine präzisionsmechanische Komponente, die von den gefallenen Maschinen und verstrahlten Leprognomen geborgen wurde, die außerhalb der zerstörten Stadt Gnomeregan umherirren. Diese Zahnräder wurden entwickelt, um das strukturelle und rotatorische Gleichgewicht in komplexen gnomischen Geräten aufrechtzuerhalten, und sind bei Tüftlern begehrt, die nach robusten, maschinell vorgefertigten Teilen suchen, um temperamentvolle Erfindungen wie Ozzie Wechselvolts Rekombobulator zu stabilisieren.",al={"was ist ein restabilisationszahnrad","lore zum restabilisationszahnrad","über das restabilisationszahnrad"}},ceb0040c={q="Woher stammen Restabilisationszahnräder?",a="Diese Zahnräder stammen aus Gnomeregans riesigen mechanischen Werken. Als die Stadt nach der katastrophalen Strahlungsemission evakuiert wurde, trugen zahllose automatisierte Geräte und die tragischen Überlebenden, die dem Leprawahnsinn verfielen, diese standardisierten Komponenten hinaus in den Schnee vor den Toren.",al={"wer hat das restabilisationszahnrad hergestellt","herkunft des restabilisationszahnrads","woher stammt das restabilisationszahnrad"}}},fp="19,156,21.476.0,39.203.0,30.142.0,54.220.0"}
P.entries["item:ring-of-zoram"] = {n="Ring von Zoram",s="Bei Zoram ist der Ring der einstigen Stadtherrscher nach Jahrtausenden unter dem Meer wieder aufgetaucht. Die Naga besitzen ihn, und Talen sucht den Schlüssel zu einer Antiken Statuette.",h="Bei Zoram ist der Ring der einstigen Stadtherrscher nach Jahrtausenden unter dem Meer wieder aufgetaucht.",kw={"antike statuette","eschental","lady vespia","ring von zoram","ruuzel","talen","der zoramstrand"},ang={["faction:Alliance"]="Den Ring von den Naga zurückzuholen hilft dem nachtelfischen Gelehrten Talen, die Geschichte der Kaldorei entlang der umkämpften Grenzen des Eschentals zurückzugewinnen.",["race:NightElf"]="Der Ring ist ein Stück des Erbes aus der Zeit vor der Zerschlagung, bevor arkane Hybris und verschlingende Meere das Reich der Kaldorei zerrissen."},sec={{t="Ring der versunkenen Stadt",b="Bevor der Brunnen der Ewigkeit zusammenbrach, lag Zoram als Juwel des nachtelfischen Reiches an Kalimdors Westküste. Seine Herrscher trugen den Ring von Zoram, dessen Innenseite einen seltsamen Code in der Sprache der Nachtelfen trägt. Die Große Zerschlagung zerriss den Kontinent vor zehntausend Jahren. Der Ring versank mit der Stadt in den Fluten und liegt heute unter den Wassern des Zoramstrands."},{t="Bergung durch die Naga",b="Jahrtausendelang verbargen Schlick und Ruinen den Ring. Dann begannen Naga, die Küste des Eschentals zu durchkämmen, und Ruuzel, ihr Anführer auf einem Eiland vor dem nördlichen Strand, entdeckte ihn zwischen den versunkenen Trümmern. Der nachtelfische Gelehrte Talen sucht ihn nicht allein wegen seines Alters. Der Ring ist der einzige Schlüssel, der aus der Tiefe geborgene Relikte öffnen kann, darunter Antike Statuetten, die am Meeresgrund versiegelt wurden."}},faq={{q="Wozu dient der Ring von Zoram?",a="Bevor die Zerschlagung Zoram überflutete, trugen seine Herrscher den Ring, der zugleich als Schlüssel zu einem antiken Schloss diente. Talen sucht ihn nun, um eine verschlossene Statuette zu öffnen, die aus den versunkenen Ruinen geborgen wurde.",al={"ring von zoram zweck","was bewirkt der ring","ring von zoram hintergrund"}},{q="Wer besitzt den Ring von Zoram?",a="Naga, die am Zoramstrand eindrangen, bargen den Ring aus den Ruinen. Ihr Anführer Ruuzel besitzt ihn auf einer Insel vor der nördlichen Küste, doch auch die bedeutende Naga Lady Vespia hat ihn bereits getragen.",al={"wer hat den ring","ring von zoram beute","wo ring von zoram bekommen"}},{q="Warum will Talen den Ring?",a="Talen will die Geheimnisse einer Antiken Statuette enthüllen, die am Zoramstrand geborgen wurde. Ohne den Ring von Zoram als Schlüssel lässt sich der Mechanismus der Statuette nicht öffnen.",al={"warum talen den ring will","talen ring quest"}},{q="Wo ist die Stadt Zoram geblieben?",a="Vor der Großen Zerschlagung war Zoram eine nachtelfische Stadt am westlichen Rand Kalimdors. Als der Brunnen der Ewigkeit vor zehntausend Jahren implodierte, wurde die Stadt zerstört und versank in den Fluten, sodass nur der Zoramstrand zurückblieb.",al={"was geschah mit zoram","stadt zoram hintergrund"}}},fx={["7e40c0d5"]={q="Was ist der Ring von Zoram?",a="Der Ring von Zoram ist ein antikes Relikt, das einst von den Herrschern der versunkenen Stadt Zoram getragen wurde, bevor die Wellen des Großen Auseinanderbrechens sie überfluteten. Ein seltsamer Code ist in der Sprache der Nachtelfen in den Ring eingraviert, und der Ring ist der Schlüssel zum antiken Schloss einer Statuette, die aus den Ruinen geborgen wurde.",al={"was ist der ring von zoram","lore zum ring von zoram","gegenstand ring von zoram"}},["770adfa7"]={q="Woher stammt der Ring von Zoram und wer hat ihn hergestellt?",a="Der Ring stammt aus der Nachtelfenstadt Zoram vor dem Auseinanderbrechen, entlang der Küste des antiken Kalimdor. Er gehörte den Herrschern der Stadt, bevor katastrophale Flutwellen Zoram vor zehntausend Jahren ertränkten, wodurch das Relikt im Meer verloren ging, bis die Naga es kürzlich aus den Ruinen bargen.",al={"herkunft des rings von zoram","wer hat den ring von zoram hergestellt","woher stammt der ring von zoram"}}},fp="13,163,23.386.0,23.375.0,35.192.0,32.200.0,29.173.0,31.228.0"}
P.entries["item:robo-mechanical-guts"] = {n="Robomechanische Gedärme",s="In Sturmwind sammelt Shoni Teile von den Maschinen, die Gnomeregan durchstreifen. Sie braucht sie, um Tunnelfahrzeuge zu reparieren, die bei der Rückeroberung der Stadt in Dun Morogh helfen sollen.",h="In Sturmwind sammelt Shoni Teile von den Maschinen, die Gnomeregan durchstreifen.",kw={"uhrwerk","dun morogh","gnomeregan","gyrodrillmatic excavationators","robomechanische gedärme","shoni","sturmwind"},ang={["profession:Engineering"]="Jedes Drahtknäuel und jedes Gyrozahnrad geht auf gnomische Entwürfe für automatisierte Maschinen zurück. Strahlung und Isolation haben die Maschinen verändert, und nun streifen sie umher.",["race:Gnome"]="Als Gnom kann es sich für Euch bittersüß anfühlen, die abtrünnigen Uhrwerkschützen Eurer verlorenen Heimat auszuschlachten. Ihre Mechanik liefert Teile, die bei der Rückeroberung von Gnomeregan helfen."},sec={{t="Bergungsgut für die Flotte",b="Nachdem Hochtüftler Gelbin Mekkadrill und die überlebenden Gnome aus Gnomeregan geflohen waren, blieben Tausende Maschinen zurück. Automatisierte Mechanismen, Uhrwerkschützen und Industrieroboter durchstreifen noch immer die Korridore der radioaktiven Stadt.\n\nIn Sturmwind baut die Tüftlerin Shoni Gyrodrillmatic Excavationators zusammen, um Gnomeregans Verteidigungsanlagen zu durchbrechen und die verlorene Stadt zurückzuerobern. Sie schickt Abenteurer in die verseuchten Hallen, um funktionstüchtige Teile aus den Robotern zu bergen, darunter Federn, Drähte und Gyrokomponenten."}},faq={{q="Wofür werden Robomechanische Gedärme verwendet?",a="Shoni in Sturmwind sammelt Robomechanische Gedärme, um Gyrodrillmatic Excavationators zu reparieren. Diese Tunnelfahrzeuge sollen bei der Rückeroberung von Gnomeregan in Dun Morogh helfen.",al={"wofür sind roboterinnereien","robomechanische gedärme verwendung","warum mechanische gedärme sammeln"}},{q="Wo findet Ihr diese Komponenten?",a="Ihr könnt diese Komponenten aus feindseligen Uhrwerksautomaten, Mechs und verseuchten Feinden bergen, die Gnomeregans Randgebiete und Tiefen durchstreifen.",al={"woher robomechanische gedärme bekommen","roboterinnereien beuteort","gnomeregan roboterteile"}},{q="Wer ist Shoni und warum braucht sie so viele Teile?",a="Shoni ist eine Gnomeningenieurin, die im Zwergendistrikt von Sturmwind stationiert ist. Sie braucht Teile, um fast vierhundert unterirdische Grabungsmaschinen für den Durchbruch in Gnomeregans besetzte Ruinen vorzubereiten.",al={"wer ist shoni","shoni sturmwind","flotte der gyrodrillmatic excavationators"}}},fx={f52d09f9={q="Warum will jemand Robo-Mechanical Guts?",a="Shoni die Schtille in Sturmwind benötigt sie dringend als Ersatzteile, um eine ganze Flotte von Gyrodrillmatic Excavationators zu reparieren. Da die Vorräte in der menschlichen Hauptstadt begrenzt sind, betrachtet sie die abtrünnigen Mechs in Gnomeregan als ergiebigen Schrottplatz, um ihre Ingenieursflotte einsatzbereit zu halten.",al={"warum robo-mechanical guts sammeln","wer will robo-mechanical guts","warum will shoni robo-mechanical guts"}},b1d0efc3={q="Was sind Robo-Mechanical Guts?",a="Es handelt sich um das verwickelte Innenleben, Zahnräder, Verkabelung und verwertbare mechanische Komponenten, die von den Uhrwerkautomaten entfernt wurden, die in Gnomeregan umherwandern. Obwohl sie für ein ungeschultes Auge kaum mehr als Schrott sind, bieten diese funktionellen Eingeweide entscheidende Rohmechanismen, die geniale Gnom-Ingenieure für komplexe Fahrzeugprojekte wiederverwenden können.",al={"was sind robo-mechanical guts","gegenstand robo-mechanical guts","was sind robo-eingeweide"}},cf2ae288={q="Woher stammen Robo-Mechanical Guts und wer hat sie hergestellt?",a="Diese Baugruppen stammen aus den Werkstätten von Gnomeregan und wurden von gnomischen Erfindern gefertigt, um ihre automatisierte Arbeiterschaft und die Stadtverteidigung anzutreiben. Als die verstrahlte Katastrophe eintrat und High Tinker Mekkatorque die Evakuierung befahl, wurden unzählige mechanische Konstrukte im Inneren zurückgelassen, wo sie weiterhin durch die ruinierten Gänge streifen, während ihr Innenleben noch intakt ist.",al={"wer hat robo-mechanical guts hergestellt","woher stammen robo-mechanical guts","herkunft von robo-mechanical guts"}}},fp="20,161,21.513.0,39.171.0,35.145.0,49.191.0"}
P.entries["item:rocket-car-parts"] = {n="Raketenwagenteile",s="Über die Schimmernde Ebene verstreut liegen Raketenwagenteile nach Zwischenfällen auf der Illusionenrennbahn. Gnomische und goblinische Rennfahrer treiben ihre experimentellen Flitzer bis an die Grenzen, und Händler sammeln Wrackteile, um sie an die Teams zurückzuverkaufen.",h="Über die Schimmernde Ebene verstreut liegen Raketenwagenteile nach Zwischenfällen auf der Illusionenrennbahn.",kw={"ingenieurskunst","gnom","goblin","kravel kohlebart","illusionenrennbahn","raketenwagenteile","bergung","die schimmernde ebene","tausend nadeln"},ang={["profession:Engineering"]="Verbrannte Zahnräder und zerfetzte Auspuffanlagen liegen über die Salzebene verstreut und zeugen davon, wie weit gnomische und goblinische Ingenieure gehen.",["race:Dwarf"]="Gnome und Goblins konzentrieren sich auf das Rennen, während Zwerge wie Kravel Kohlebart mit dem Bergen der zurückgelassenen Wrackteile Gewinn machen können."},sec={{t="Tempo, Wracks und gerissener Handel",b="Auf der Illusionenrennbahn in der Schimmernden Ebene liefern sich gnomische und goblinische Ingenieure einen erbitterten Wettstreit. Ihre Rennfahrer jagen immer höheren Geschwindigkeiten an Land nach. Pannen, Fehlzündungen und Unfälle verstreuen Metall über die Salzebene, wo Schrottsammler und Händler bald die Überreste einsammeln.\n\nDer Zwerg Kravel Kohlebart heuert Reisende an, um die gleißende Weite abzusuchen und die Trümmer einzusammeln. Beide Rennteams brauchen Ersatzteile für ihre nächsten Prototypen, sodass Wrackteile zu jenen Teams zurückkehren können, deren Wagen sie hinterlassen haben."}},faq={{q="Woher kommen all diese Raketenwagenteile?",a="Raketenwagenteile stammen von Unfällen, Explosionen und mechanischen Defekten auf der Illusionenrennbahn. Gnomische und goblinische Rennfahrer treiben experimentelle raketengetriebene Fahrzeuge über die Salzebene von Tausend Nadeln, bis die Wagen auseinanderbrechen.",al={"warum liegen teile auf der salzebene","herkunft des raketenwagenschrotts","woher kommen die teile"}},{q="Wer kauft diese geborgenen Schrottteile?",a="Händler wie der Zwerg Kravel Kohlebart kaufen Wrackteile, die Reisende einsammeln. Sie verkaufen Zahnräder, Verkleidungen und andere Teile zurück an Gnome und Goblins, die Material brauchen, um ihre Rennwagen zu reparieren und zu verbessern.",al={"wer will raketenwagenteile","kravel kohlebart raketenwagenteile","wer kauft die wrackteile"}},{q="Ist es gefährlich, die Teile zu bergen?",a="Von den Wrackteilen selbst geht keine Gefahr aus, doch das Metall kann grausige Unfallspuren tragen, darunter darin eingeklemmte, abgetrennte Gliedmaßen. Basilisken, versengte Skorpide und räuberische Salzgeier streifen nahe den Trümmern über die Salzebene.",al={"ist das einsammeln der teile sicher","gefahren beim sammeln der teile"}},{q="Stört es die Gnome und Goblins, dass die Teile aus verunglückten Wagen stammen?",a="Gnomische und goblinische Rennfahrer verwenden bereitwillig wiederverwertete Teile. Sie wollen funktionierende Maschinenteile, Zahnräder und Verkleidungen, um Wagen zu bauen, die schnell genug sind, einander auf der Rennstrecke abzuhängen.",al={"stören sich rennfahrer an wrackteilen","warum verwenden goblins schrott wieder"}}},fx={["9a01e74a"]={q="Was sind Raketenwagenteile?",a="Es handelt sich um die verstreuten Trümmer von Hochgeschwindigkeitsrennkatastrophen auf der schimmernden Ebene. Diese Schrottteile bestehen aus losen Zahnrädern, Zylindern, verbogenen Metallplatten und geborgenen Geräten und waren einst an den dröhnenden experimentellen Konstruktionen befestigt, die von Goblin- und Gnom-Rasern gebaut wurden, die auf der Illusionenrennbahn gegeneinander antraten.",al={"was sind raktenwagenteile","raktenwagenteile hintergrund","was sind diese teile"}}},fp="16,216,34.487.0,46.227.0,31.210.0,36.213.0,68.161.0"}
P.entries["item:rod-of-channeling"] = {n="Rute des Kanalisierens",s="Im Sumpfland tragen Zauberwirker des Dragonmaw-Klans die Rute des Kanalisierens. Strahad Farsan braucht drei davon für seine Akolythen, um einen Beschwörungskreis für einen Teufelsjäger in Ratschet zu stabilisieren.",h="Im Sumpfland tragen Zauberwirker des Dragonmaw-Klans die Rute des Kanalisierens.",kw={"lager der grollhauer","knochenbehüter","dragonmaw","teufelsjäger","rute des kanalisierens","schattenbehüter","strahad farsan","tome of the cabal"},ang={["class:Warlock"]="Als Hexenmeister sammelt Ihr während der Prüfungen des Tome of the Cabal drei Ruten des Kanalisierens. Sie helfen, das Ritual unter Kontrolle zu halten, während Ihr Euren ersten Teufelsjäger bindet."},sec={{t="Werkzeuge der Bindung",b="Hexenmeister brauchen mehr als Willenskraft, um einen Teufelsjäger zu binden. Strahad Farsan verlangt drei aufeinander abgestimmte Ruten, damit seine Akolythen gemeinsam Magie kanalisieren und den Beschwörungskreis stabilisieren können, während der Hexenmeister die Bestie bindet. Dunkelzauberer des Dragonmaw-Klans tragen die Ruten für ihr eigenes Wirken bei sich.\n\nIm Lager der Grollhauer und in den umliegenden Ruinen des Sumpflands tragen Knochenbehüter und Schattenbehüter des Dragonmaw-Klans die Ruten. Kämpfe hinterlassen Abnutzungen und Kerben, doch die Ruten bündeln weiterhin chaotische Netherenergie."}},faq={{q="Wozu dient die Rute des Kanalisierens?",a="Strahad Farsan braucht oberhalb von Ratschet die Ruten für seine Akolythen. Sie kanalisieren Magie, um den Kreis zu stabilisieren, in dem ein Hexenmeister einen feindseligen Teufelsjäger beschwört und bindet.",al={"was ist die rute des kanalisierens","zweck der rute des kanalisierens","warum brauche ich die rute des kanalisierens"}},{q="Wo sind Ruten des Kanalisierens zu finden?",a="Zauberwirker des Dragonmaw-Klans tragen die Ruten im Sumpfland. Knochenbehüter und Schattenbehüter des Dragonmaw-Klans tragen sie rund um das Lager der Grollhauer.",al={"wo gibt es ruten des kanalisierens","wer lässt die rute des kanalisierens fallen","fundort der rute des kanalisierens"}},{q="Warum braucht Strahad drei Ruten?",a="Strahads Akolythen helfen beim Beschwörungsritual für den Teufelsjäger. Jeder braucht einen Fokus, um den Magiefluss zu stabilisieren, während der Hexenmeister die Bestie unterwirft.",al={"warum drei ruten","warum drei ruten des kanalisierens"}},{q="Warum verwendet der Dragonmaw-Klan diese Ruten?",a="Der Dragonmaw-Klan verwendet die Ruten für seinen dunklen Schamanismus und seine Schattenkünste, Überbleibsel der alten Horde. Seine Knochenbehüter und Schattenbehüter kanalisieren Flüche, Nekromantie und Shadow Magic in ihren anhaltenden Gebietskriegen im Sumpfland.",al={"dragonmaw-ruten","warum hat der dragonmaw-klan sie"}}},fx={af4e8f1c={q="Was ist eine Rute des Kanalisierens?",a="Eine Rute des Kanalisierens ist ein arkaner Fokus, den Zauberwirker nutzen, um flüchtige magische Energien zu fokussieren und zu bändigen. Obwohl diese Ruten ursprünglich von den dunklen Zauberwirkern des Drachenmalclans im Sumpfland geführt wurden, sind sie mächtige Ritualinstrumente, die in den Händen erfahrener Hexenmeister in der Lage sind, hochstufige Beschwörungen zu stabilisieren.",al={"was ist eine rute des kanalisierens","rute des kanalisierens hintergrund","über rute des kanalisierens"}}},fp="17,163,22.464.0,39.158.0,38.133.0,33.140.0,39.227.0"}
P.entries["item:rolf-and-malakai-s-medallions"] = {n="Medaillons von Rolf und Malakai",s="Im östlichen Elwynn tragen die Medaillons von Rolf und Malakai die Insignien des Reiches, doch ihre Besitzer verschwanden auf Patrouille. Wache Thomas sucht die Abzeichen, um zu erfahren, was aus seinen Männern geworden ist.",h="Im östlichen Elwynn tragen die Medaillons von Rolf und Malakai die Insignien des Reiches, doch ihre Besitzer...",kw={"eastvale","elwynn","wache thomas","malakai","medaillons","murloc","rolf","wache von sturmwind"},ang={["faction:Alliance"]="Selbst im Herzen der Allianz droht den örtlichen Wachen tödliche Gefahr, während sie die Handelswege im Umland bewachen.",["race:Human"]="Für die Menschen von Elwynn stehen diese Abzeichen für den Verlust von Söhnen und Verteidigern. Ihr Tod zeigt die Verwundbarkeit des Königreichs, während seine Streitkräfte andernorts gebunden sind."},sec={{t="Eine düstere Bestätigung",b="Wache Thomas befehligt den Posten im östlichen Elwynn. Als Rolf und Malakai an den Flussufern verschwanden, fürchtete er das Schlimmste. Ihre Medaillons bestätigen, dass die Wachen durch vorrückende Murlocs starben. Die Garnison von Sturmwind hat Soldaten verloren, die Bedrohungen aus der Wildnis standhielten, während die Streitkräfte des Königreichs an ihre Grenzen stießen."},{t="Zeichen des Dienstes",b="Menschliche Wachen tragen bei der Stadtwache und auf Patrouillen im Umland Erkennungsmedaillons. Die Abzeichen bezeugen ihre Treue und ihre Befugnisse im Dienst der Krone. Die Rückgabe der Medaillons von Rolf und Malakai an Wache Thomas ermöglicht ihm, das Schicksal seiner vermissten Männer festzuhalten und ihr Opfer in seinem Lagebericht zu verzeichnen. Er kann auch vor aggressiven Murlocstämmen warnen, die sich nahe den Handelsstraßen ansiedeln."}},faq={{q="Was sind die Medaillons von Rolf und Malakai?",a="Die Medaillons von Rolf und Malakai sind Dienstabzeichen, die Wachen aus Sturmwind zur Erkennung tragen. Murlocs überfielen und töteten die Wachen, als diese im östlichen Wald von Elwynn stationiert waren.",al={"was sind die medaillons","rolfs medaillon","malakais medaillon"}},{q="Wem gehören diese Medaillons?",a="Die Medaillons gehörten den Wachen Rolf und Malakai. Sie dienten unter Wache Thomas und überwachten den Fluss und die Straßen zwischen Goldhain und dem Holzfällerlager des Osttals.",al={"wer waren rolf und malakai","wessen medaillons"}},{q="Wem soll ich diese Medaillons bringen?",a="Bringt die Medaillons zu Wache Thomas. Er hält an der östlichen Brücke auf der Straße zwischen Goldhain und dem Holzfällerlager des Osttals Wache.",al={"wer will die medaillons","wo diese abgeben","medaillons abgeben"}},{q="Warum sind diese Medaillons für Wache Thomas wichtig?",a="Wache Thomas schickte beide Wachen auf Patrouille und fürchtete, sie hätten ein grausames Ende gefunden. Ihre Medaillons bestätigen ihren Tod, sodass er ihr Opfer verzeichnen und Sturmwind vor der wachsenden Bedrohung durch die Murlocs warnen kann.",al={"warum will thomas sie","reaktion von wache thomas"}}},fp="29,178,19.339.0,17.358.0,39.180.1,34.161.0,39.135.0,51.197.1"}
P.entries["item:rot-blossom"] = {n="Faulblüte",s="Im Dämmerwald sprießen Faulblüten aus geschändeten Gräbern, genährt von verseuchter Erde und untoten Überresten. Ihre üblen alchemistischen Eigenschaften machen sie begehrt.",h="Im Dämmerwald sprießen Faulblüten aus geschändeten Gräbern, genährt von verseuchter Erde und untoten...",kw={"althea schwarzhaupt","dunkelhain","dämmerwald","faulblüte","skelettschändem","skelettschrecken","der friedhof \"stille gärten\"","zombie juice"},ang={["faction:Alliance"]="Das Sammeln dieser morbiden Blüten in verfluchter Erde hilft der Nachtwache auch, gefräßige Skelette von Dunkelhains Grenzen fernzuhalten.",["profession:Herbalism"]="Faulblüten sind üble Pflanzen, die sich von nekrotischer Fäulnis und Friedhofserde nähren, anders als Kräuter, die durch Licht und Regen gedeihen. Sie bieten einen düsteren Einblick in die verderbte Pflanzenwelt."},sec={{t="Flora der Grüfte",b="Im Dämmerwald wachsen Faulblüten in entweihter Friedhofserde, auch auf dem Friedhof \"Stille Gärten\". Einheimischen Gerüchten zufolge schlagen sie in den gespaltenen Schädeln von Skelettschrecken und Skelettschändem Wurzeln, die durch die Grabhügel streifen. Für die Menschen in Dunkelhain ist das Sammeln eine grausige Arbeit. Wer die Erde aufwühlt, muss sich den ruhelosen Toten stellen."},{t="Eine grausige Zutat",b="Faulblüten liefern eine Zutat für örtliche Gebräue. Ihre dunklen Essenzen werden für Zombie Juice benötigt, einen üblen Trank, der mit dem Überlebenskampf des Dämmerwalds verbunden ist. Wer zum Sammeln der Blüten ausgesandt wird, hilft oft der Nachtwache, indem er ruhelose Skelette niederstreckt, die über die heimgesuchten Grabstätten wandern."}},faq={{q="Wo lassen sich Faulblüten finden?",a="Faulblüten wachsen auf den verderbten Begräbnisstätten des Dämmerwalds, besonders auf dem Friedhof \"Stille Gärten\". Sie sprießen auch aus den Überresten untoter Skelettschändem.",al={"wo wachsen faulblüten","faulblüte fundort","faulblüten finden"}},{q="Wofür werden Faulblüten verwendet?",a="Örtliche Brauer und Alchemisten verwenden Faulblüten zur Herstellung von Zombie Juice, einer starken und üblen Mischung.",al={"faulblüte verwendung","warum faulblüten sammeln","was macht faulblüten nützlich"}},{q="Warum wachsen diese Blüten in Skeletten?",a="Die anhaltende dunkle Magie des Dämmerwalds befällt die Erde und die ruhelosen Toten. Faulblüten nähren sich von nekrotischer Verderbnis und Verwesung und können in den Schädeln und Brustkörben umherstreifender Skelette sprießen.",al={"faulblüten in schädeln","skelettschrecken blume","skelette faulblüte"}},{q="Wie hilft das Sammeln von Faulblüten Dunkelhain?",a="Faulblüten an Orten wie den Stillen Gärten zu sammeln bedeutet, die Skelettschrecken und Skelettschändem niederzustrecken, die das Gelände heimsuchen. Das verschafft Althea Schwarzhaupt und der bedrängten Nachtwache dringend benötigte Entlastung.",al={"althea schwarzhaupt faulblüte","night watch faulblüte","dunkelhain helfen"}}},fx={["93f3afdd"]={q="Was ist eine Faulblüte?",a="Eine Faulblüte ist eine morbide botanische Kuriosität, die man auf den verheerten Friedhöfen des Dämmerwalds findet. Anstatt in gesundem Boden zu keimen, gedeihen diese grimmigen Blumen inmitten von Verwesung und keimen bekanntermaßen im Inneren der hohlen Schädel von untoten Skelettschrecken und Skelettunholden. Da sie von fauligen Energien durchdrungen sind, werden sie von exzentrischen Einheimischen gesucht, die daraus starke Gebräue brauen.",al={"was sind faulblüten","faulblüte gegenstand","was ist eine faulblüte"}}},fp="11,152,19.329.0,21.281.0,32.165.0,31.94.0,40.188.0,47.215.0"}
P.entries["item:rot-hide-ichor"] = {n="Moderfellsekret",s="Im Grabmal sammelt Apotheker Renferrel Moderfellsekret für die Königliche Apothekervereinigung. Sie hofft, dass es zeigt, was die Gnolle verdorben hat und wie man ihnen entgegentreten kann.",h="Im Grabmal sammelt Apotheker Renferrel Moderfellsekret für die Königliche Apothekervereinigung.",kw={"apotheker renferrel","insel fenris","der lordameresee","moderfellgnolle","moderfellsekret","das grabmal","silberwald"},ang={["race:Undead"]="Als Verlassene versteht Ihr, warum die Untersuchung des Sekrets wichtig ist. Es könnte militärische Erkenntnisse liefern, um die Ostflanke von Silberwald zu sichern und das Wissen der Königlichen Apothekervereinigung über die Seuchenkunde zu vertiefen."},sec={{t="Eine Seuche im Blut",b="Auf der Insel Fenris sind die Moderfellgnolle durch eine unnatürliche Seuche entstellt. Ihre Körper verwesen, doch ein giftiges Sekret fließt durch ihre Adern und erhält ihr belebtes Fleisch. Die Königliche Apothekervereinigung hofft, dass die Flüssigkeit enthüllt, was das Rudel verdorben hat und wer es aus dem Inneren der zerstörten Feste befehligt."},{t="Forschung der Apotheker",b="Im Grabmal sammelt Apotheker Renferrel Phiolen des Sekrets zur Untersuchung. Die Verlassenen hoffen, die chemischen und magischen Kräfte voneinander zu trennen, die die Gnolle am Leben erhalten. Dann können sie die Schwächen des Rudels aufdecken, bevor sie Truppen für einen Großangriff über den Lordameresee entsenden."}},faq={{q="Woher stammt Moderfellsekret?",a="Moderfellsekret stammt von den Moderfellgnollen auf der Insel Fenris im Lordameresee, östlich des Festlands von Silberwald.",al={"wo gibt es moderfellsekret","wie findet man moderfellsekret","gnollsekret fundort"}},{q="Warum will Apotheker Renferrel dieses Sekret?",a="Apotheker Renferrel untersucht die Flüssigkeit, um den Ursprung der Verderbnis der Gnolle und körperliche oder alchemistische Schwächen aufzudecken, die die Verlassenen vor dem Inselangriff nutzen können.",al={"warum braucht renferrel sekret","renferrel questgrund","zweck von moderfellsekret"}},{q="Gehören die Moderfellgnolle zur Geißel?",a="Die Moderfellgnolle sind untot und durch eine Seuche entstellt. Die Verlassenen untersuchen, wer oder was sie erschaffen hat und sie auf der Insel Fenris befehligt.",al={"gehören moderfellgnolle zur geißel","wer kontrolliert die moderfellgnolle","was sind moderfellgnolle"}},{q="Haben alle Gnolle dieses Sekret?",a="Nein. Dieses Sekret gehört zum Moderfellrudel, dessen Fleisch und Blut durch üble nekromantische Seuchen verdorben sind.",al={"lassen alle gnolle sekret fallen","normales gnollblut"}}},fx={c332bd61={q="Was ist Moderfellsekret?",a="Moderfellsekret ist eine seltsame, unnatürliche Flüssigkeit, die durch die Körper der Moderfell-Gnolle auf der Insel Fenris fließt. Es ist kein gewöhnliches Blut; die Königliche Apothekergesellschaft glaubt, dass diese verseuchte Substanz direkt für die verdrehte, untote Natur und die erhöhte Widerstandsfähigkeit der Gnolle verantwortlich ist.",al={"was ist moderfellsekret","moderfellflüssigkeit","was ist das sekret"}}},fp="14,168,21.303.0,19.267.0,36.117.0,46.166.0,32.142.0,30.109.0"}
P.entries["item:rough-quartz"] = {n="Rohquarz",s="In Durotar erhält ein Schamane Rohquarz von einer Schwachen Erdmanifestation. Ein Ältester bindet den Stein in das erste Erdtotem des Schamanen ein.",h="In Durotar erhält ein Schamane Rohquarz von einer Schwachen Erdmanifestation.",kw={"call of earth","canaga erdenrufer","erdtotem","schwache erdmanifestation","rohquarz","das tal der prüfungen"},ang={["class:Shaman"]="Für Euch als Schamanen kennzeichnet Rohquarz Eure erste Zwiesprache mit dem Element Erde. Er verankert Eure Zauber und markiert Euren Weg als Mittler der Geister."},sec={{t="Herz des Erdtotems",b="In Durotar oder Mulgore gibt eine Schwache Erdmanifestation einem Schamanen Rohquarz, wenn er mit den Geistern Zwiesprache hält. Für ein ungeschultes Auge sieht der Stein wie ein gewöhnlicher Wüstenkiesel aus. Er steht für Ausdauer, Geduld und unerschütterliche Stärke.\n\nIm Tal der Prüfungen bindet Canaga Erdenrufer den Quarz in geschnitztes Holz ein, um ein Erdtotem herzustellen. Der Stein wird zum spirituellen Fokus, der einen jungen Schamanen mit Azeroths lebendigem Boden verbindet."}},faq={{q="Welchem Zweck dient Rohquarz?",a="Ein Schamanenältester bindet Rohquarz als spirituellen Kern in das erste Erdtotem eines Initianden ein. Er zeigt auch, dass der Neuling mit dem elementaren Erdgeist Zwiesprache gehalten hat.",al={"was bewirkt rohquarz","rohquarz verwendung","wofür wird rohquarz benötigt"}},{q="Wer gibt Euch den Rohquarz?",a="Eine Schwache Erdmanifestation gewährt Euch Rohquarz, nachdem Ihr während des Rituals Call of Earth in Durotar oder Mulgore mit dem Geist Zwiesprache gehalten habt.",al={"wo gibt es rohquarz","wer lässt rohquarz fallen"}},{q="Zu wem bringe ich diesen Stein in Durotar?",a="Bringt Rohquarz zu Canaga Erdenrufer, dem Schamanenlehrer im Tal der Prüfungen. Canaga fertigt daraus Euer Erdtotem.",al={"wo rohquarz abgeben","rohquarz abgeben","wer nimmt rohquarz an"}},{q="Wird dieser Quarz noch für etwas anderes verwendet?",a="Nein. Rohquarz ist ein heiliger Ritualgegenstand, aus dem ein Erdtotem hergestellt wird. Im gewöhnlichen Handel hat er keinen Nutzen.",al={"lässt sich rohquarz verkaufen","wird rohquarz zum herstellen verwendet"}}},fx={f25f16be={q="Was ist Rohquarz?",a="Rohquarz ist ein kleiner Elementarkiesel, der aufstrebenden Schamanen von einer Schwachen Erdmanifestation gegeben wird. Obwohl der Stein von bescheidener Größe und Aussehen ist, repräsentiert er das Bestehen des Rituals der Erde und die Verbindung mit dem Elementargeist eines Initianden und dient als greifbarer Beweis ihrer Bindung.",al={"was ist rohquarz","rohquarz gegenstand","rohquarz bedeutung"}},["871e2ee1"]={q="Warum will Canaga Erdenrufer den Rohquarz?",a="Canaga Erdenrufer benötigt den Rohquarz als Beweis dafür, dass Ihr dem Ruf gefolgt seid und mit dem Elementargeist kommuniziert habt. Er verwendet den Kiesel als Herz Eures ersten Erdtotems, was es Euch ermöglicht, weiter mit der Erde zu kommunizieren und Zauber zu wirken, die direkt mit ihrer Kraft verbunden sind.",al={"warum rohquarz nötig","rohquarz zweck","warum rohquarz zu canaga bringen"}}},fp="12,143,24.439.0,40.172.0,31.143.0,40.127.0,38.102.0"}
P.entries["item:rumbleshot-s-ammo"] = {n="Schlingerschuss' Munition",s="Nahe dem Graufelsbau liegt Schlingerschuss' Munition verlassen im Schnee. Ihr Kurier floh vor hungrigen Wendigos, bevor die Kiste den Büchsenmacher Hegnar Schlingerschuss in Dun Morogh erreichen konnte.",h="Nahe dem Graufelsbau liegt Schlingerschuss' Munition verlassen im Schnee.",kw={"munition","kiste","dun morogh","der graufelsbau","hegnar","loslor","schlingerschuss","wendigo"},ang={["class:Hunter"]="Haltet als Jäger in Dun Morogh Hegnars Pulver trocken und seine Schrotvorräte gefüllt. Zwergische Schusswaffen brauchen einen stetigen Nachschub an Munition.",["profession:Engineering"]="Als Ingenieur braucht Ihr Schrot und Pulver, um selbst gefertigte Schusswaffen und experimentelle Waffen zu testen."},sec={{t="Eine gestrandete Lieferung",b="Hegnar Schlingerschuss betreibt ein Waffengeschäft am Straßenrand auf dem Bergpfad von der Eisklamm nach Ambossar. Schützen aus Eisenschmiede, Gebirgsjäger und zwergische Mörserteams üben in den verschneiten Höhen, sodass seine Vorräte so schnell schwinden, wie Pulver verbrennt.\n\nLoslor schickte das Schrot aus Kharanos, doch die Lieferung erreichte die Regale nie. Ihr Kurier lagerte zu nahe am Graufelsbau. Als die Wendigos angriffen, floh der Kurier in Panik und ließ die schwere Kiste in ihrem Jagdgebiet zurück."}},faq={{q="Wer ist Hegnar Schlingerschuss?",a="Hegnar Schlingerschuss ist ein zwergischer Büchsenmacher mit einem Laden abseits der Straße nach Ambossar. Er versorgt örtliche Schützen, Jäger und Kanoniere des Militärs, die in den zerklüfteten Bergen von Dun Morogh üben.",al={"schlingerschuss","wer ist hegnar","waffenhändler"}},{q="Wie ging die Munitionskiste verloren?",a="Ein Kurier, der die Kiste transportierte, lagerte nahe dem Graufelsbau. Als die dortigen Wendigos angriffen, floh der verängstigte Kurier und ließ die schwere Kiste im Schnee zurück.",al={"warum ging die munition verloren","was geschah mit der munition","kurier munition"}},{q="Wo liegt der Graufelsbau?",a="Der Graufelsbau ist ein Höhlensystem in den Bergen südwestlich von Kharanos. Wendigos haben dort ihren Unterschlupf und gefährden allein reisende Wanderer an den umliegenden Hängen.",al={"graufelsbau lage","wo ist die wendigohöhle"}}},fx={["4221fe47"]={q="Was ist Schlingerschuss' Munition?",a="Es ist eine Kiste mit frischer Munition, die für Hegnar Schlingerschuss' Laden entlang der Straße nach Ambossar gepackt wurde. Da örtliche zwergische Schützen und Mörserteams ständig in der Nähe üben, ist Hegnar auf beständige Großlieferungen wie diese angewiesen, um seine Regale gefüllt und seine Kunden bewaffnet zu halten.",al={"was ist schlingerschuss' munition","schlingerschuss munitionskiste","was ist diese munition"}},["008970c2"]={q="Woher stammt Schlingerschuss' Munition?",a="Die Kiste wurde von Loslor Rudge aus Kharanos bereitgestellt und versandt. Unglücklicherweise wurde der Kurier, der sie in Richtung Südwesten nach Ambossar bringen sollte, in der Nähe von The Grizzled Den von wilden Wendigos überfallen und floh, wobei er die gesamte Lieferung im Schnee zurückließ.",al={"wer machte schlingerschuss' munition","woher stammt schlingerschuss' munition","wer sandte die munition"}},["6d6b5eaa"]={q="Warum benötigt Hegnar Schlingerschuss diese Munition?",a="Hegnar steht kurz davor, dass sein Lagerbestand vollständig aufgebraucht ist. Die nahegelegenen Bergsteiger, Schützen und Mörserteams verbrauchen beim Zielschießen in rasantem Tempo Schießpulver und Munition, was viele begierige Käufer warten lässt, sobald die frische Lieferung eintrifft.",al={"warum ist schlingerschuss' munition nötig","warum will man schlingerschuss munition","wer braucht schlingerschuss' munition"}}},fp="17,177,19.477.0,25.175.0,32.152.0,26.171.0"}
P.entries["item:rune-inscribed-parchment"] = {n="Mit Runen beschriftetes Pergament",s="Im Tal der Prüfungen übergibt Gornek angehenden Orcschamanen einen Ruf von Shikrik. Er fordert sie auf, ihr Volk zu führen und mit Elementargeistern Zwiesprache zu halten.",h="Im Tal der Prüfungen übergibt Gornek angehenden Orcschamanen einen Ruf von Shikrik.",kw={"durotar","gornek","pergament","mit runen beschriftetes pergament","schamane","shikrik","das tal der prüfungen"},ang={["class:Shaman"]="Als Schamane macht Ihr Euren ersten Schritt auf dem Pfad der Elemente. Unter Shikriks Anleitung erlernt Ihr die Ahnenverehrung und die Beherrschung der Elemente.",["race:Orc"]="Als Orc tragt Ihr die Weisheit der Ahnen in Durotar weiter. Die Wiederentdeckung der schamanischen Tradition ist für die New Horde von zentraler Bedeutung."},sec={{t="Ein Ruf zu den Geistern",b="Neue Orcschamanen werden im Tal der Prüfungen unter erfahrenen Aufsehern ausgebildet. Während der ersten Prüfungen eines Initianden übergibt Gornek ihm eine runenbedeckte Botschaft von Shikrik, der örtlichen Schamanenlehrerin. Sie fordert ihn auf, seine Bindung zu den Elementen zu vertiefen.\n\nUnter den Orcs vermitteln Schamanen zwischen den Lebenden und ihren Ahnen. Die Botschaft markiert eine Abkehr von roher Kraft hin zur disziplinierten Ehrfurcht vor den Wegen der Ahnen."}},faq={{q="Was ist das Mit Runen beschriftete Pergament?",a="Im Tal der Prüfungen übergibt Gornek unerfahrenen Orcschamanen eine handgeschriebene Botschaft. Sie weist sie an, sich zur geregelten Ausbildung bei Shikrik zu melden.",al={"runenpergament","was ist dieser gegenstand","schamanenpergament"}},{q="Wer hat das Pergament verfasst?",a="Shikrik, die Schamanenlehrerin im Tal der Prüfungen, hat das Pergament verfasst. Es unterweist junge Initianden in den Wegen der Elemente und der Ahnengeister.",al={"wer hat das pergament geschickt","verfasser des pergaments"}},{q="Warum gelten Schamanen unter den Orcs als Auserwählte?",a="Orcschamanen führen ihr Volk als spirituelle Anführer. Sie lauschen den Elementargeistern und dienen ihren Ahnen als Sprachrohr. Shikrik lehrt ihre Schüler, Verbündete zu heilen und den Zorn der Elemente gegen ihre Feinde zu richten.",al={"warum schamane sein","rolle der orcschamanen"}}},fx={["00232829"]={q="Warum möchte Shikrik, dass Ihr das Mit Runen beschriftete Pergament lest?",a="Shikrik hat diese Nachricht durch Gornek gesandt, um Euch direkt zu ihr zu rufen. Da sie erkannt hat, dass Ihr dazu auserwählt seid, das spirituelle Leben Eures Volkes zu leiten, beabsichtigt sie, mit Eurer formellen Ausbildung in der Kommunikation mit Ahnen, der Elementarbeherrschung und den Riten eines Orc-Schamanen zu beginnen.",al={"warum mit runen beschriftetes pergament lesen","warum schickt shikrik das pergament","zweck von mit runen beschriftetem pergament"}}},fp="24,154,24.414.0,37.140.0,24.153.0,49.220.0"}
P.entries["item:rune-inscribed-pendant"] = {n="Mit Runen beschrifteter Anhänger",s="Im Silberwald trifft ein Mit Runen beschrifteter Anhänger mit einer Lieferung für Mühlenbern im Grabmal ein. Die Kirin Tor nutzen solche Anhänger, um arkane Macht zu kanalisieren.",h="Im Silberwald trifft ein Mit Runen beschrifteter Anhänger mit einer Lieferung für Mühlenbern im Grabmal ein.",kw={"allister","mühlenbern","dalar morgenweber","dalaran","kirin tor","anhänger","mit runen beschrifteter anhänger","das grabmal"},ang={["class:Mage"]="Als Magier könnt Ihr in den Runen die Handwerkskunst der Kirin Tor erkennen. Sie stabilisieren unbeständige Ströme, während mächtige Zauber kanalisiert werden.",["race:Undead"]="Als einer der Verlassenen, die den Silberwald bewachen, wisst Ihr, dass abgefangene Fokusse Dalarans wie dieser Anhänger Hinweise auf menschlichen Widerstand liefern, der sich hinter Mühlenberns Mauern sammelt."},sec={{t="Relikt der Kirin Tor",b="Ein Mit Runen beschrifteter Anhänger wird zwischen kartografischen Vorräten für die Enklave Dalarans in Mühlenbern gefunden. Seine feinen arkanen Inschriften verraten seinen Zweck: die Zauber eines Magiers zu bündeln und zu verstärken. Weitere Anhänger zur Kanalisierung treffen in der Region ein, und die Verlassenen im Grabmal fragen sich, was die Kirin Tor vorbereiten."},{t="Ein Hinweis auf Mühlenberns Pläne",b="Im Grabmal sieht Schattenpriester Allister eine Gefahr in der befestigten Stellung der Magier Dalarans. Er schickt den Anhänger zur genaueren Untersuchung an Dalar Morgenweber. Dawnweaver erkennt ihn als Teil der Unternehmungen der Magier. Die Kirin Tor sammeln arkane Fokusse für mächtige defensive oder offensive Zauberwerke hinter Mühlenberns Grenzen."}},faq={{q="Wozu dient der Mit Runen beschriftete Anhänger?",a="Magier der Kirin Tor nutzen den Anhänger, um mächtige magische Ströme zu kanalisieren und zu lenken. Er bündelt komplexe Zauberkunst.",al={"was bewirkt der anhänger","zweck des anhängers","runenanhänger verwendung"}},{q="Woher stammt dieser Anhänger?",a="Der Anhänger stammt aus einer Lieferung für Mühlenbern im Silberwald, wo sich die verbliebenen Kirin Tor verschanzt haben.",al={"wo findet sich der anhänger","herkunft des anhängers","wo wurde er gefunden"}},{q="Wer untersucht den Anhänger im Grabmal?",a="Schattenpriester Allister untersucht den Anhänger kurz zusammen mit erbeuteten Karten. Er schickt ihn an Dalar Morgenweber im Grabmal, der darin das Werk der Kirin Tor erkennt.",al={"wer untersucht den anhänger","wer will den anhänger","dalar anhänger"}},{q="Warum sind die Verlassenen deswegen besorgt?",a="Große Lieferungen von Anhängern zur Kanalisierung deuten darauf hin, dass die Kirin Tor in Mühlenbern ein bedeutendes magisches Vorhaben vorbereiten. Die Verlassenen fürchten, dass es ihre Herrschaft über den Silberwald bedrohen könnte.",al={"warum interessiert es die verlassenen","mühlenbern bedrohung","warum ist der anhänger gefährlich"}}},fx={bf28d080={q="Was ist der Rune-Inscribed Pendant?",a="Es ist ein arkanes Artefakt, das von den mächtigen Magiern von Dalaran gefertigt und benutzt wird. Solche Anhänger werden häufig von der Kirin Tor verwendet, um gewaltige magische Energien zu fokussieren und zu kanalisieren, und sind eher Leiter potenter arkaner Macht als einfache Schmuckstücke.",al={"was ist rune-inscribed pendant","rune-inscribed pendant identität","was ist dieser anhänger aus dalaran"}}},fp="22,166,15.327.0,27.338.1,44.111.0,33.125.0,42.165.0,40.185.0"}
P.entries["item:rune-inscribed-tablet"] = {n="Mit Runen beschriftete Schrifttafel",s="Im Tal der Prüfungen gibt Gornek jungen Dunkelspeertrollschamanen eine steinerne Botschaft. Sie schickt vielversprechende Mystiker zu Shikrik, um eine formelle spirituelle Unterweisung zu erhalten.",h="Im Tal der Prüfungen gibt Gornek jungen Dunkelspeertrollschamanen eine steinerne Botschaft.",kw={"dunkelspeer","durotar","gornek","mit runen beschriftete schrifttafel","schamane","shikrik","lehrer","das tal der prüfungen"},ang={["class:Shaman"]="Für Euch als Schamanen markiert die Schrifttafel Euren ersten offiziellen Schritt zur Beherrschung von Erde, Feuer, Wasser und Luft. Eure Kraft strömt aus den Geistern der Ahnen.",["race:Troll"]="Als Dunkelspeertroll folgt Ihr dem Ruf eines Orclehrers. Er steht für eine wachsende Verbundenheit und einen gemeinsamen spirituellen Weg zwischen Eurem Volk und seinen neuen Verbündeten der Horde."},sec={{t="Ein Ruf zu den Geistern",b="Gornek gibt Initianden, die sich im Tal der Prüfungen bewähren, einen mit Runen behauenen Stein. Der Trollschamane Ishi-yo schickt ihn zu Shikrik, dem Schamanenlehrer. Für Dunkelspeertrolle beginnt mit der Schrifttafel ein gemeinsamer Weg mit den Orcs. Ihre alten spirituellen Traditionen verbinden sich mit dem schamanistischen Erbe, das Kriegshäuptling Thrall erneuert hat."}},faq={{q="Wofür wird die Mit Runen beschriftete Schrifttafel verwendet?",a="Gornek gibt die Schrifttafel jungen Trollschamanen im Tal der Prüfungen. Sie weist ihnen den Weg zu Shikrik, um eine formelle spirituelle Ausbildung zu erhalten.",al={"zweck der schrifttafel","was bewirkt die schrifttafel","verwendung der runentafel"}},{q="Wer schickt die Schrifttafel?",a="Der Trollschamane Ishi-yo schickt die Schrifttafel. Sie weist dem Initianden den Weg zu Shikrik, dem Schamanenlehrer der Orcs gleich außerhalb des Den im Tal der Prüfungen. Shikrik weiß, dass sie kommen.",al={"wer hat die schrifttafel geschrieben","absender der schrifttafel","wer hat sie behauen"}},{q="Wer erhält diese Schrifttafel?",a="Gornek gibt die Schrifttafel neu eingetroffenen Dunkelspeertrollschamanen als ihren ersten Klassenruf in Durotar.",al={"wer erhält die mit runen beschriftete schrifttafel","welche klasse erhält die schrifttafel"}}},fx={cd2cca59={q="Was ist die Mit Runen beschriftete Schrifttafel?",a="Die Mit Runen beschriftete Schrifttafel ist eine schriftliche Vorladung, die an aufstrebende Troll-Schamanen gerichtet ist, die im Tal der Prüfungen trainieren. Markiert mit schamanischen Runen dient sie als persönliche Nachricht, die durch Gornek weitergegeben wird, um vielversprechende Rekruten direkt bei ihrem örtlichen Ausbilder vorzustellen.",al={"was ist mit runen beschriftete schrifttafel","mit runen beschriftete schrifttafel hintergrund","was ist diese schrifttafel"}},["33b46b09"]={q="Warum möchte Shikrik, dass Ihr die Mit Runen beschriftete Schrifttafel erhaltet?",a="Die Schrifttafel stammt tatsächlich von Ishi-yo, dem Trollschamanen, der Euch zuerst unterrichtete; Gornek vermutet nur, dass sie von Shikrik stammt. Ishi-yo schickt Euch weiter zu Shikrik, die Euch bereits erwartet. Sie möchte Euch mit den Elementen und den Geistern Eurer Ahnen vertraut machen, damit Ihr eines Tages die Dörfer und Städte der Horde führen und beschützen könnt, so wie Thrall die Horde selbst führt.",al={"warum schickt shikrik die schrifttafel","warum wird diese schrifttafel gebraucht","shikrik mit runen beschriftete schrifttafel"}}},fp="21,159,24.315.0,43.130.0,21.178.0,25.105.0"}
P.entries["item:rune-of-nesting"] = {n="Rune des Nistens",s="Im Grabhügel von Ban'ethil hilft die Rune des Nistens, einen Ritus zur Erweckung der Druiden der Kralle vorzubereiten. Sie schlafen im Smaragdgrünen Traum, und vier heilige Relikte geleiten sie sicher zurück.",h="Im Grabhügel von Ban'ethil hilft die Rune des Nistens, einen Ritus zur Erweckung der Druiden der Kralle...",kw={"athridas bearmantle","grabhügel von ban'ethil","truhe des nistens","druiden der kralle","smaragdgrüner traum","relikte des erwachens","rune des nistens"},ang={["class:Druid"]="Als Druide wisst Ihr, dass die Rune des Nistens zu den heiligen Riten des Zirkels des Cenarius gehört. Sie zeugt von der Gefahr, der schlafende Brüder ausgesetzt sind, wenn ihre Heiligtümer überrannt werden.",["race:NightElf"]="Als Nachtelf seht Ihr den Verlust der Relikte des Erwachens und die Entweihung der Grabhügel als Zeichen wachsender Verderbnis unter Teldrassils Wildtieren und Furbolgs."},sec={{t="Ein heiliger Fokus des Erwachens",b="Tief in den verwinkelten Kammern des Grabhügels von Ban'ethil liegt die Rune des Nistens in der Truhe des Nistens. Nachtelfendruiden schlafen in unterirdischen Grabhügeln und verbinden sich durch den Smaragdgrünen Traum mit der Natur.\n\nFür eine sichere Rückkehr brauchen die Druiden der Kralle ein behutsames Erweckungsritual, das von heiligen Relikten geleitet wird. Die Rune des Nistens ist eines von vieren, neben dem Rabenkrallentalisman, dem Schwarzen Federkiel und dem Saphir des Himmels. Gemeinsam rufen die Relikte die schlafenden Druiden in die wache Welt zurück."},{t="Krise in Ban'ethil",b="Verderbte Furbolgs der Gnarlpine haben den Grabhügel von Ban'ethil überrannt, und seine schlafenden Verteidiger sind in Gefahr. Ohne die Relikte könnten die Druiden im Smaragdgrünen Traum gefangen bleiben, während Eindringlinge ihr Heiligtum entweihen. Die Bergung der Rune des Nistens und der zugehörigen Relikte ermöglicht Athridas Bearmantle in Dolanaar, den Ritus vorzubereiten, der sie sicher wecken kann."}},faq={{q="Wofür wird die Rune des Nistens verwendet?",a="Athridas Bearmantle braucht die Rune des Nistens, um das Ritual vorzubereiten, das die Druiden der Kralle sicher aus ihrem tiefen Schlaf im Smaragdgrünen Traum weckt. Sie ist eines der vier Relikte des Erwachens, die bei diesem Ritus verwendet werden.",al={"was bewirkt die rune des nistens","zweck der rune des nistens"}},{q="Wo ist die Rune des Nistens zu finden?",a="Die Rune des Nistens liegt in der Truhe des Nistens, in den unterirdischen Gängen des Grabhügels von Ban'ethil, westlich von Dolanaar auf Teldrassil.",al={"wo ist die rune des nistens","fundort der truhe des nistens"}},{q="Warum können die schlafenden Druiden nicht einfach von selbst aufwachen?",a="Die Druiden versetzen sich in eine empfindliche Trance, wenn sie im Smaragdgrünen Traum schlafen. Ohne heilige Relikte und ein Erweckungsritual können sie womöglich nicht zurückkehren, sodass ihr Geist umherirrt und ihr Körper in Gefahr bleibt.",al={"warum brauchen druiden ein erweckungsritual","warum können druiden nicht aufwachen"}},{q="Welche weiteren Relikte werden neben der Rune des Nistens benötigt?",a="Der Ritus erfordert vier Relikte des Erwachens: die Rune des Nistens, den Rabenkrallentalisman, den Schwarzen Federkiel und den Saphir des Himmels.",al={"weitere relikte des erwachens","gegenstände der relikte des erwachens"}}},fx={["375c0565"]={q="Was ist die Rune des Nistens?",a="Die Rune des Nistens ist eines der vier heiligen Relikte des Erwachens, die von den Druiden der Kralle in Teldrassil aufbewahrt werden. Sie wird in einer speziellen Truhe im Grabhügel von Ban'ethil aufbewahrt und enthält die spezialisierten Verzauberungen, die erforderlich sind, um das Erwachensritual für Druiden, die in tiefer Verbindung mit dem Smaragdgrünen Traum ruhen, ordnungsgemäß durchzuführen.",al={"rune des nistens","was ist die rune des nistens","rune des nistens hintergrund"}}},fp="15,179,28.497.0,19.354.0,37.212.0,35.133.0,58.204.0,59.139.0"}
P.entries["item:runes-of-summoning"] = {n="Runen der Beschwörung",s="Im Magieviertel von Unterstadt rufen Hexenmeister mit den Runen der Beschwörung einen Leerwandler aus dem Nether. Die Kreatur betritt einen Kreis, in dem ein angehender Hexenmeister sie seinem Willen unterwerfen kann.",h="Im Magieviertel von Unterstadt rufen Hexenmeister mit den Runen der Beschwörung einen Leerwandler aus dem...",kw={"carendin halgar","magieviertel","runen der beschwörung","the binding","unterstadt","leerwandler","hexenmeister"},ang={["class:Warlock"]="Als Hexenmeister beweist Ihr mit den Runen Eure Herrschaft über die Leere und verwandelt einen chaotischen Schatten in einen beständigen, treuen Diener.",["race:Undead"]="Als Untoter folgt Ihr praktizierenden Verlassenen in die Tiefen von Unterstadt, wo sie trotz uralter Tabus Leerenwesen unter den Ruinen von Lordaeron binden."},sec={{t="Unterwerfung im Magieviertel",b="Carendin Halgar gibt die Runen der Beschwörung an Hexenmeister weiter, die bereit sind, einen Leerwandler zu befehligen. Im Magieviertel von Unterstadt studieren praktizierende Verlassene, wie sich der Nether manipulieren lässt. Ein Hexenmeister wirkt die Runen im aktiven Beschwörungskreis unterhalb von Halgars Podest. Das Ritual reißt die Leere auf und ruft eine Kreatur hervor, die überwältigt und in die Knechtschaft gezwungen werden muss."}},faq={{q="Wozu dienen die Runen der Beschwörung?",a="Ein Hexenmeister wirkt die Runen im Magieviertel von Unterstadt, um einen ungebundenen Leerwandler aus dem Nether in die stoffliche Welt zu rufen. Anschließend kann der Hexenmeister ihn besiegen und seinem Willen unterwerfen.",al={"runen der beschwörung zweck","was bewirken runen der beschwörung","runen der beschwörung verwenden"}},{q="Wer stellt die Runen der Beschwörung bereit?",a="Carendin Halgar, der verlassene Hexenmeisterlehrer im Magieviertel von Unterstadt, stellt die Runen während der letzten Ausbildungsphase zur Bindung eines Leerwandlers bereit.",al={"wer gibt runen der beschwörung","runen der beschwörung lehrer","carendin halgar runen"}},{q="Wo müssen die Runen aktiviert werden?",a="Bringt die Runen zum violetten Beschwörungskreis direkt unter Carendin Halgars Plattform im Magieviertel.",al={"wo runen der beschwörung verwenden","runen der beschwörung ort","beschwörungskreis unterstadt"}},{q="Was geschieht nach der Beschwörung des Wesens?",a="Der Leerwandler greift an, sobald er beschworen wird. Der Hexenmeister muss ihn mit Magie und Waffen bezwingen. Nach seiner Niederlage wird das Wesen zum Dienst verpflichtet, und Carendin Halgar lehrt den dauerhaften Zauber zu seiner Beschwörung.",al={"was geschieht nach verwendung der runen","leerwandler bezwungen","nach beschwörung des leerwandlers"}}},fx={["1ce5479a"]={q="Was sind Runen der Beschwörung?",a="Die Runen der Beschwörung sind ein spezialisierter Ritualkatalysator, der aufstrebenden Hexenmeistern der Verlassenen in der Unterstadt gegeben wird. Wenn sie zum Kreis der Beschwörung im Magieviertel gebracht werden, fokussieren die Runen magische Energien, um einen Durchgang zu reißen und einen ungebundenen Leerwandler aus dem Nether hervorzulocken.",al={"was sind runen der beschwörung","runen der beschwörung","runen der beschwörung gegenstand"}},["0508549c"]={q="Warum möchte Carendin Halgar die Runen der Beschwörung zurückhaben?",a="Carendin Halgar stellt die Runen speziell als Prüfung der Meisterschaft zur Verfügung. Sobald Ihr sie aktiviert und den beschworenen Leerwandler im Kampf bezwungen habt, beweist die Rückgabe der Runen ihm gegenüber, dass Ihr die Kreatur beherrscht habt, was es ihm ermöglicht, Euch den permanenten Zauber beizubringen, um Leerwandler zu beschwören und zu befehligen.",al={"warum runen der beschwörung zurückgeben","warum will carendin die runen","runen der beschwörung zurückgeben"}}},fp="18,188,32.366.0,41.187.0,36.155.0,34.110.0,42.200.0"}
P.entries["item:sack-of-murloc-heads"] = {n="Sack mit Murlocköpfen",s="An Hillsbrads Stränden wird ein Sack mit Murlocköpfen als Beweis für die Bekämpfung örtlicher Küstengefahren zusammengestellt. Leutnant Farren Orinelle übergibt das Bündel vorbeiziehenden Abenteurern für Marshal Redpath in Süderstade.",h="An Hillsbrads Stränden wird ein Sack mit Murlocköpfen als Beweis für die Bekämpfung örtlicher Küstengefahren...",kw={"kopfgeld","farren orinelle","köpfe","hillsbrad","marshal redpath","murloc","süderstade"},ang={["faction:Alliance"]="Als Mitglied der Allianz seht Ihr die angeschlagene Logistik und die glanzlosen täglichen Lasten, die Süderstades Verteidiger tragen, während sie die nördliche Enklave der Allianz zusammenhalten."},sec={{t="Bürokratie und Küstenplagen",b="Süderstade wird von Gesetzlosen des Syndikats, Scharmützlern der Verlassenen und wilden Murlocs entlang der Küste angegriffen. Offiziere müssen der Stadtführung zeigen, dass die Küstengefahren bekämpft werden, um Gelder und Gunst zu erhalten. Leutnant Farren Orinelle sammelt abgetrennte Köpfe als Beweis, obwohl ihm die Fracht zuwider ist. Seine Zimperlichkeit veranlasst ihn, den Sack Reisenden für Marshal Redpath mitzugeben, statt die grausigen Beweise selbst zu tragen."}},faq={{q="Was ist der Sack mit Murlocköpfen?",a="Der Sack enthält abgetrennte Murlocköpfe, die an Hillsbrads westlichen Stränden gesammelt wurden. Er liefert Süderstades Garnisonskommandanten handfeste Beweise für die Bemühungen, die Küste zu befrieden.",al={"sack mit köpfen","murlocsack","was ist dieser gegenstand"}},{q="Warum liefert Leutnant Farren ihn nicht selbst ab?",a="Leutnant Farren Orinelle findet es widerlich, einen Sack voller verwesender Murlocköpfe zu tragen. Er überlässt die unangenehme Lieferung einem hilfsbereiten Abenteurer, der sie durch Süderstade trägt.",al={"warum farren andere den sack tragen lässt","farrens ausrede","fauler farren"}},{q="Wer erhält den Sack?",a="Marshal Redpath erhält den Sack. Er befehligt Süderstades Verteidigung, beurteilt die Sicherheit der Stadt und verlangt Beweise für die Verteidigungsbemühungen.",al={"wer bekommt die köpfe","wohin bringen","bei marshal redpath abgeben"}},{q="Warum verlangt Süderstade Murlocköpfe als Beweis?",a="Süderstade verlangt Murlocköpfe als Beweis, weil Murlocs ständig die Küste überfallen und den Hafen bedrohen. Offiziere müssen überprüfen, ob Patrouillen die Sicherheit an den Außengrenzen gewährleisten. Handfeste Trophäen helfen sicherzustellen, dass Soldaten keine Anerkennung für untätig verbrachte Wachen einfordern.",al={"warum murlocköpfe sammeln","tötungsnachweis"}}},fx={["3f14ed35"]={q="Woher stammt der Sack mit Murlocköpfen und wer hat ihn hergestellt?",a="Der Sack wurde aus den abgetrennten Köpfen der Murlocs zusammengestellt, die Ihr entlang der Südküste des Vorgebirges des Hügellands gejagt habt. Leutnant Farren Orinelle packte sie zusammen, um sie seinem kommandierenden Offizier zu überreichen, reichte das abstoßende Paket aber schnell an Euch zurück, damit Ihr es an seiner Stelle übergebt.",al={"wer machte den sack mit murlocköpfen","woher stammt der sack mit köpfen","wer gab den sack mit murlocköpfen"}}},fp="20,217,29.433.0,33.166.0,47.170.0,22.139.0,50.248.0"}
P.entries["item:sack-of-supplies"] = {n="Sack Vorräte",s="Überall in der Klingenschlucht liegen die für Rezlak bestimmten Vorratssäcke verstreut zwischen den Nistplätzen der Harpien. Dustwind-Harpien raubten die Waren beim Transport durch Durotar.",h="Überall in der Klingenschlucht liegen die für Rezlak bestimmten Vorratssäcke verstreut zwischen den...",kw={"durotar","dustwind-harpien","gazlowe","klingenschlucht","rezlak","sack vorräte"},ang={["faction:Horde"]="Die Vorräte von den örtlichen Raubtieren zurückzuholen, hält die Bauarbeiten im Grenzland um Orgrimmar ohne kostspielige Verzögerungen am Laufen."},sec={{t="Eine geplünderte Karawane",b="Rezlak braucht für seine Arbeit außerhalb von Orgrimmar einen stetigen Nachschub an Waren. Gazlowe beauftragte den Gobliningenieur aus Ratschet, für die Horde zu bauen. Eine Karawane mit einer zugesagten Lieferung kam nahe der Schluchtstraße südlich von Orgrimmar vorbei. Dustwind-Harpien überfielen sie und schleppten die Fracht zu ihren Nistplätzen in der Klingenschlucht, wobei sie Säcke neben ihren Nestern im Schmutz und Geröll verstreuten."}},faq={{q="Was steckt in diesen Vorratssäcken?",a="Die Säcke enthalten Baumaterialien und Handelswaren für Gazlowes Ingenieursarbeiten. Sie sollen orkische Bauvorhaben nahe Orgrimmar unterstützen. Ohne sie kann Rezlak seine Arbeit nicht vollenden.",al={"inhalt der vorratssäcke","was ist in den säcken","rezlaks vorräte"}},{q="Wer hat die Vorräte gestohlen?",a="Dustwind-Harpien haben die Vorräte gestohlen. Dieses wilde Vogelvolk bevölkert die hoch gelegenen Felsspalten und Schluchten der Klingenschlucht.",al={"wer nahm die vorräte","wer stahl die säcke"}},{q="Wer ist Rezlak?",a="Rezlak ist ein Gobliningenieur, den Gazlowe aus Ratschet entsandt hat, um der Horde beim Bau und der Instandhaltung der Leitungsinfrastruktur in Durotar zu helfen.",al={"wer ist rezlak","rezlaks geschichte"}}},fx={["812e6d27"]={q="Woher kommen diese Säcke Vorräte?",a="Diese Säcke waren Teil einer Lieferung, die im Namen von Gazlowe und seinen Goblin-Ingenieuren nach Durotar geschickt wurde. Der Karawanenzug, der sie transportierte, sollte die Orcs beim Bau und der Instandhaltung ihrer Siedlungen unterstützen, wurde jedoch unterwegs überfallen und geplündert, bevor er sein Ziel erreichen konnte.",al={"sack vorräte herkunft","woher kamen die vorräte","wer machte den vorratssack"}},["55ee41bd"]={q="Warum will Rezlak diese Vorratssäcke?",a="Rezlak kann die Bauarbeiten, die Gazlowe ihm zugewiesen hat, nicht ohne ordnungsgemäße Ausrüstung und Materialien durchführen. Harpyien aus der Klingenschlucht plünderten die Karawane, die seine Werkzeuge und Vorräte transportierte, was den Goblin-Vorarbeiter völlig ausbremste, bis jemand die gestohlene Fracht zurückholt.",al={"warum will rezlak vorräte","warum vorratssäcke nötig","winds in the desert vorräte warum"}}},fp="16,156,19.381.0,34.197.0,23.118.0,14.122.0"}
P.entries["item:salty-scorpid-venom"] = {n="Salziges Skorpidgift",s="In ganz Tausend Nadeln lockt Salziges Skorpidgift Gnome in ein gefährliches Rennen um Geschwindigkeit. Skorpide auf der Schimmernden Ebene tragen die Mineralsalze des Wüstenbodens in ihrem Gift, und gnomische Rennfahrer suchen es als Treibstoff.",h="In ganz Tausend Nadeln lockt Salziges Skorpidgift Gnome in ein gefährliches Rennen um Geschwindigkeit.",kw={"fizzel kupferbolz","illusionenrennbahn","salziges skorpidgift","scorpid reaver","scorpid terror","skorpidgift","die schimmernde ebene","tausend nadeln"},ang={["profession:Engineering"]="Als Ingenieur seht Ihr, wie Erfinder auf der Schimmernden Ebene nach Alternativen zu Erdöl und Kohle suchen. Sie testen organische Giftstoffe als flüchtige Brandbeschleuniger.",["race:Gnome"]="Als Gnom kennt Ihr die Risiken, tödliches Wüstengift mit Negakatalysatoren in Raketentreibstoff zu verwandeln, nur um Sekunden bei einer Runde einzusparen."},sec={{t="Ein flüchtiges Verbrennungsmittel",b="Skorpide auf der mineralreichen Schimmernden Ebene tragen Salz in ihrem Gift. Scorpid Reavers und Scorpid Terrors haben diese örtlichen Salze über Generationen aufgenommen. Fizzel Kupferbolz und andere gnomische Tüftler schätzen das ätzende Gift als möglichen Zusatz für Motorentreibstoff mit hoher Verbrennungsintensität, nicht für Gegengifte oder gewöhnliche Gifte."},{t="Treibstoff für den Rennbahnwettstreit",b="Auf der Illusionenrennbahn testen Gnome und Goblins immer gefährlichere Materialien in ihren Raketenwagen. Fizzel Kupferbolz glaubt, dass das Einkochen des salzhaltigen Gifts, seine Behandlung mit speziellen Katalysatoren und das Einmischen in Treibstofftanks seinem Wagen die gewaltige Hitze verleihen werden, die er braucht, um Goblinrennfahrer auf den Salzflächen abzuhängen."}},faq={{q="Welche Kreaturen produzieren Salziges Skorpidgift?",a="Scorpid Reavers und Scorpid Terrors auf den Salzflächen von Tausend Nadeln produzieren Salziges Skorpidgift.",al={"wer lässt salziges skorpidgift fallen","wo skorpidgift bekommen","quelle für skorpidgift"}},{q="Warum ist das Gift so salzig?",a="Die Skorpide leben auf dem mineralverkrusteten Boden der Schimmernden Ebene. Ihre Körper nehmen die konzentrierten Salze des ausgetrockneten Seebetts auf, wodurch ihr Gift einen hohen Salzgehalt erhält.",al={"warum ist es salzig","salt flat venom erklärung","hintergrund zu skorpiden und salz"}},{q="Wer will dieses Gift und warum?",a="Fizzel Kupferbolz, ein gnomischer Ingenieur an der Illusionenrennbahn, sucht das Gift für eine experimentelle Treibstoffmischung. Er glaubt, dass es heiß genug brennen wird, um seinen Raketenwagen zum Sieg zu treiben.",al={"wer braucht skorpidgift","warum will fizzel gift","fizzel kupferbolz questgegenstand"}}},fx={["9840b612"]={q="Was ist Salziges Skorpidgift?",a="Es handelt sich um eine wirkungsvolle, mineralhaltige Flüssigkeit, die von den Skorpionen geerntet wird, die durch Die schimmernde Ebene streifen. Das raue, ausgetrocknete Salzbecken hat dazu geführt, dass die örtlichen Skorpion-Schrecken und -Plünderer ein ungewöhnlich salzhaltiges Gift entwickelt haben. Obwohl es als natürliches Toxin tödlich ist, machen seine reaktiven chemischen Eigenschaften es für Bastler als flüchtiges Rohreagenz weitaus interessanter als als einfaches Gift.",al={"was ist salziges skorpidgift","salziges skorpidgift","skorpidgift ebene"}}},fp="19,215,27.321.0,27.317.0,43.99.0,26.173.0,29.181.0"}
P.entries["item:samophlange-item"] = {n="Samophlang",s="Im Brachland bleibt der Samophlange in einer automatisierten Steuerkonsole verborgen. Goblinmechaniker können nicht erklären, was das seltsame Bauteil bewirkt.",h="Im Brachland bleibt der Samophlange in einer automatisierten Steuerkonsole verborgen.",kw={"brachland","konsole","ratschet","samophlange","stotterspritter","tinkers' union","undermine"},ang={["profession:Engineering"]="Als Ingenieur erkennt Ihr im Samophlange vielleicht eine übermäßig komplizierte Konstruktion. Sein aufwendig gestaltetes Äußeres verbirgt einen Mechanismus, der so zerbrechlich ist, dass er beim Absetzen auf dem Boden kaputtgeht."},sec={{t="Eine rätselhafte Apparatur",b="Der Samophlange liegt in einer Steuerkonsole im Brachland, hinter einem Labyrinth aus Drähten und hohlen Röhren. Sorgfältiges Suchen ist nötig, um ihn aus seinem Gehäuse zu lösen. Er scheint für Uhrwerk- und Dampfmaschinen unentbehrlich zu sein, doch Goblintüftler können seinen Zweck nicht ergründen. Sie planen, ihn an die Tinkers' Union in Undermine zu schicken, doch unsanfte Handhabung könnte das zerbrechliche Teil beschädigen."},{t="Neugier und Katastrophe",b="Stotterspritter, ein Ingenieur in Ratschet, plant, den Samophlange zur Untersuchung an die führenden Köpfe der Tinkers' Union zu schicken. Doch die Neugier der Goblins durchkreuzt diesen Plan oft. Als Stotterspritter das empfindliche Gerät absetzt, um sein Innenleben zu untersuchen, zerbricht es zu Schrott."}},faq={{q="Was ist ein Samophlange?",a="Der Samophlange ist ein seltsames mechanisches Bauteil, das aus einer Steuerkonsole im Brachland geborgen wurde. Sein Zweck ist unbekannt, und die Konsole um ihn herum steckt voller Röhren und Drähte, die nichts Nützliches zu bewirken scheinen.",al={"was macht ein samophlange","samophlange zweck","was ist dieser gegenstand"}},{q="Wer will den Samophlange haben?",a="Stotterspritter, ein Ingenieur in Ratschet, möchte, dass ihm der Samophlange zur Untersuchung gebracht wird. Er plant, ihn an die Tinkers' Union zu schicken.",al={"wer braucht den samophlange","wem den samophlange geben"}},{q="Was macht Stotterspritter damit?",a="Stotterspritter plant, den Samophlange zur Untersuchung durch die Tinkers' Union nach Undermine zu schicken. Zuerst setzt er ihn ab, um ihn zu untersuchen, und der zerbrechliche Mechanismus geht kaputt.",al={"stotterspritter samophlange","was passiert mit dem samophlange"}},{q="Woher stammt der Samophlange?",a="Der Samophlange ist in einer Bedienkonsole im nördlichen Brachland untergebracht, hinter Schichten verwirrender Maschinerie, die keinem Zweck zu dienen scheinen.",al={"samophlange fundort","wo wird er gefunden"}}},fp="18,140,22.353.0,25.264.1,22.204.0,26.124.0,34.156.1,36.142.0"}
P.entries["item:samophlange-manual"] = {n="Samophlanghandbuch",s="In Orgrimmar sucht Rilli Greasygob die verstreuten Seiten des Samophlanghandbuchs. Das Handbuch erklärt, wie man das Samophlange der Venture Company repariert und bedient.",h="In Orgrimmar sucht Rilli Greasygob die verstreuten Seiten des Samophlanghandbuchs.",kw={"brachland","boss copperplug","felsadermine","ingenieurskunst","handbuch","rilli greasygob","samophlange","stotterspritter","venture company"},ang={["faction:Horde"]="Das Handbuch ermöglicht es Goblins in Orgrimmar, die der Horde nahestehen, direkt unter den Augen der Venture Company deren Bohrmaschinen zu untersuchen und umzufunktionieren.",["profession:Engineering"]="Das Handbuch offenbart firmeneigene Technologie der Venture Company. Es zeigt auch, wie Goblintüftler Geschäftsgeheimnisse und brauchbare Baupläne vor ihresgleichen schützen."},sec={{t="Geheimnisse der Apparatur",b="Boss Copperplug hielt das Wissen der Venture Company über das Samophlange unter Verschluss. Der ehrgeizige Aufseher enthielt den meisten Arbeitern die Seiten des Handbuchs vor. Lose Blätter gab er nur seinen treuesten Untergebenen. Als das Gerät nicht mehr in Firmenhand war, konnte es niemand reparieren, ohne die herausgerissenen Seiten von Copperplug und seiner Mannschaft in der Felsadermine zurückzuholen."},{t="Der Ehrgeiz eines Rivalen",b="Rilli Greasygob verließ die Venture Company und ließ sich in Orgrimmar nieder, um zu erfahren, wie das Samophlange gebaut war. Copperplug hatte ihn nie bevorzugt, also verlässt sich Rilli auf unternehmungslustige Reisende, um den Einband und die losen Blätter des Handbuchs zu beschaffen. Wieder zusammengesetzt gewährt das Handbuch Goblintüftlern, die mit der Horde zusammenarbeiten, einen seltenen Einblick in die Ingenieurskunst der Venture Company."}},faq={{q="Was ist das Samophlanghandbuch?",a="Das Samophlanghandbuch erklärt, wie man das komplexe, eigentümliche mechanische Gerät der Venture Company bedient und repariert.",al={"was ist das samophlanghandbuch","samophlange buch","samophlange anleitung"}},{q="Wem gehörte das Handbuch ursprünglich?",a="Boss Copperplug, ein Aufseher der Venture Company in der Felsadermine im nordöstlichen Brachland, verwahrte das Handbuch. Er hütete seine Geheimnisse und gab einzelne Seiten nur seinen vertrauenswürdigsten Arbeitern.",al={"wer hat das handbuch","boss copperplug handbuch","wer schrieb das handbuch"}},{q="Warum wurde das Handbuch in einzelne Seiten zerrissen?",a="Boss Copperplug zerlegte das Handbuch, damit Rivalen und Untergebene, denen er nicht vertraute, das Gerät nicht vollständig verstehen konnten. Er behielt den Einband und gab fünf bestimmte Seiten an seine Bergleute und Bediener weiter.",al={"warum handbuchseiten suchen","verstreute handbuchseiten","warum fehlen seiten"}},{q="Wer möchte das vollständige Handbuch lesen?",a="Rilli Greasygob, ein Ingenieur in Orgrimmar, möchte das wieder zusammengesetzte Handbuch, um das aus dem Brachland geborgene Zerbrochene Samophlang zu verstehen und zu reparieren.",al={"wer braucht das handbuch","rilli greasygob","wer will das samophlanghandbuch"}},{q="Wozu wird ein Samophlange verwendet?",a="Niemand außerhalb der Venture Company scheint zu wissen, wozu ein Samophlange verwendet wird. Die Firma experimentierte mit einem davon an einer kleinen Forschungsstätte südwestlich des Schlickermoors im Brachland, doch selbst die Ingenieure, die es untersuchten, wurden kaum daraus schlau.",al={"was macht ein samophlange","zweck des samophlange","samophlange zweck"}}},fp="18,165,26.354.0,18.351.0,31.117.0,32.197.0,34.191.0,39.147.0,31.252.0"}
P.entries["item:sample-ichor"] = {n="Sekretprobe",s="Im Silberwald trägt die Sekretprobe Spuren von Nekromantie und Hexenmeistermagie. Apotheker Renferrel gewann sie aus der Flüssigkeit, die die Moderfellgnolle am Leben erhält.",h="Im Silberwald trägt die Sekretprobe Spuren von Nekromantie und Hexenmeistermagie.",kw={"apotheker renferrel","bethor eismacht","magieviertel","moderfell","rot hide origins","sekretprobe","silberwald","unterstadt"},ang={["class:Mage"]="Als Magier kennt Ihr den Wert klassischer arkaner Studien im Kampf gegen dunkle Zauberei. Bethor Eismacht nutzt besondere Weissagungszauber, um die Rückstände in der Sekretprobe zu deuten.",["class:Warlock"]="Als Hexenmeister erkennt Ihr womöglich die Hexenmeisterkünste, die Apotheker Renferrel im Sekret mit Nekromantie verwoben fand. Das deutet darauf hin, dass teuflische Praktiken halfen, diese untoten Bestien zu binden."},sec={{t="Die Moderfellgnolle enträtseln",b="Apotheker Renferrel schickte die Sekretprobe zur genaueren Untersuchung nach Unterstadt. Er sammelte sie von den Moderfellgnollen und ihren verbliebenen Überresten und zerlegte die faulige Flüssigkeit dann in ihre Grundbestandteile. Seine Erkenntnisse zeigten, dass nekromantische Riten und Hexenmeistermagie das Sekret geformt hatten. Da seine Herstellung über einfache Alchemie hinausgeht, schickte Renferrel es zur Weissagung an Bethor Eismacht."}},faq={{q="Was ist die Sekretprobe?",a="Die Sekretprobe ist ein Extrakt, das Apotheker Renferrel aus den Körperflüssigkeiten der Moderfellgnolle gewann. Er zerlegte es in seine Grundbestandteile, um herauszufinden, wie Magie die wandelnden toten Bestien erschaffen hatte.",al={"sekretprobe","was ist dieses sekret","was ist die sekretprobe"}},{q="Wer muss diese Probe sehen?",a="Bethor Eismacht muss die Sekretprobe untersuchen. Er ist ein untoter Magier im Magieviertel von Unterstadt, bewandert in Weissagung und magischen Traditionen, die Spuren offenbaren können, die gewöhnliche Alchemie nicht erkennt.",al={"zu wem das sekret bringen","sekretprobe abgeben","bethor eismacht sekret"}},{q="Welche Art von Magie steckt im Sekret?",a="Die Sekretprobe enthält Hexenmeistermagie und Nekromantie, die in ihrer Flüssigkeit gebunden sind. Bethor Eismacht sagt, das Fläschchen trage mächtige, uralte Verzauberungen, die eingehendere Weissagung erfordern, um sie vollständig zu enthüllen.",al={"welche magie steckt im sekret","magieart des sekrets","moderfellmagie"}},{q="Warum haben die Apotheker die Untersuchung nicht selbst abgeschlossen?",a="Die Königliche Apothekervereinigung versteht sich hervorragend auf Alchemie, Giftstoffe und körperliche Seuchen. Komplexe arkane Geflechte verlangen nach einem Zauberer wie Bethor Eismacht, der magische Schulen erkennen und esoterische Zauber jenseits der üblichen Mittel eines Apothekers entschlüsseln kann.",al={"warum apotheker zu bethor geschickt","warum nicht auf moderfellsekret verzichten"}}},fx={f4e4cc11={q="Woher kommt diese Sekretprobe und wer hat sie hergestellt?",a="Apotheker Renferrel bereitete diese Phiole vor, indem er rohes Sekret zerlegte, das von den Rotbauchgnollen im Silberwald gesammelt wurde. Seine erste Analyse ergab, dass derjenige, der die ursprüngliche Substanz erschuf, sie sowohl mit Nekromantie als auch mit Hexenmeistermagie durchsetzt hatte, obwohl das wahre Mastermind hinter ihrer Erschaffung noch im Dunkeln liegt.",al={"sekretprobe herkunft","woher kommt sekretprobe","wer machte sekretprobe"}},["045e6062"]={q="Warum möchte Bethor Eismacht die Sekretprobe haben?",a="Apotheker Renferrel stieß bei dem Versuch, die Herkunft der Rotbauchgnolle zu bestimmen, an die Grenzen der alchemistischen Wissenschaft. Er schickte diese verfeinerte Probe an Bethor Eismacht im Magieviertel von Unterstadt, da Bethor über tiefgreifendes Wissen der arkanen und dunklen Künste verfügt, was es ihm ermöglicht, mithilfe von Wahrsagemagie die undurchsichtigen Zauber zu identifizieren, die in die Flüssigkeit eingewoben sind.",al={"warum will bethor sekretprobe","warum wird sekretprobe gesucht","zweck sekretprobe bethor"}}},fp="12,164,24.380.0,25.196.0,29.202.0,39.183.0,59.236.0"}
P.entries["item:sample-of-zanzil-s-altered-mixture"] = {n="Probe von Zanzils veränderter Mixtur",s="Die Probe von Zanzils veränderter Mixtur soll über das Meer nach Tarrens Mühle gelangen. Das Gebräu stammt vom Hexendoktor Zanzil und schwächt seinen Träger. Serge Hinott könnte ein Heilmittel finden und ergründen, wie das Gift wirkt.",h="Die Probe von Zanzils veränderter Mixtur soll über das Meer nach Tarrens Mühle gelangen.",kw={"veränderte mixtur","hillsbrad","gifte","schurke","serge hinott","das schlickermoor","tarrens mühle","zanzil"},ang={["class:Rogue"]="Als Schurke der Horde bringt Ihr diese gefährliche Probe zu Serge Hinott, dessen Lehren das Brauen, die Handhabung und das Auftragen tödlicher Gifte umfassen.",["faction:Horde"]="Als Reisender der Horde tragt Ihr das Gebräu mit Zeppelin und auf Straßen quer über einen Kontinent und folgt den Routen von Kalimdor zu den Gebieten der Verlassenen in Lordaeron."},sec={{t="Ein giftiges Andenken",b="Ein Agent trägt die Mixtur bei sich, nachdem er den Turm der Venture Company nahe dem Schlickermoor im Brachland betreten hat. Die Probe stammt aus einem Vorrat in Gallywix' Schatulle, und Zanzils Gebräu hat den Agenten vergiftet. Shenthul schickt den leidenden Agenten damit über das große Meer. In Tarrens Mühle im Vorgebirge des Hügellands kann der Apotheker Serge Hinott das Gift isolieren und seine Bestandteile bestimmen."},{t="Geheimnisse der Giftmischerei",b="Serge Hinott untersucht die veränderte Mixtur, um dem leidenden Boten zu helfen und zu ergründen, wie sich starke Gifte im Feld brauen und handhaben lassen. Schurken der Horde suchen dieses Wissen, um die dunkleren Künste ihres Handwerks zu meistern."}},faq={{q="Was ist diese Mixtur?",a="Die Mixtur ist ein alchemistisches Gebräu, das mit dem Hexendoktor Zanzil in Verbindung steht und aus dem Turm der Venture Company nahe dem Schlickermoor im Brachland geborgen wurde. Ihr starkes Gift verursacht bei jedem, der sie unmittelbar berührt, lang anhaltende, schwächende Beschwerden.",al={"was ist zanzils mixtur","probe von zanzils veränderter mixtur","zanzils giftprobe"}},{q="Warum muss ich sie zu Serge Hinott bringen?",a="Serge Hinott ist ein Apotheker in Tarrens Mühle im Vorgebirge des Hügellands. Mit seinem Wissen kann er den Wirkungen des Gebräus entgegenwirken und ein verlässliches Heilmittel herstellen, bevor das Gift bleibende Schäden verursacht.",al={"wer ist serge hinott","warum nach tarrens mühle bringen","heilmittel gegen zanzils mixtur"}},{q="Wer ist Zanzil?",a="Zanzil the Outcast ist ein Dschungeltroll und Hexendoktor, der für die Herstellung von wahnsinnbringenden Elixieren, Giften und Mutagenen bekannt ist. Seine Giftrezepte haben sich über seine heimischen Dschungel hinaus unter Söldnern und in Industriebetrieben wie der Venture Company verbreitet.",al={"wer ist zanzil","zanzil the outcast","zanzils geschichte"}},{q="Wie erreicht Ihr Tarrens Mühle, um sie abzuliefern?",a="Nehmt den Zeppelin von Durotar nach Unterstadt in Tirisfal. Folgt dann der Hauptstraße nach Süden durch den Silberwald und den Wegweisern nach Osten ins Vorgebirge des Hügellands bis nach Tarrens Mühle.",al={"wie nach tarrens mühle gelangen","reise ins vorgebirge des hügellands","weg nach tarrens mühle"}}},fp="34,213,13.394.0,22.207.1,21.236.0,41.185.0,14.243.0,43.189.0"}
P.entries["item:sample-snapjaw-shell"] = {n="Schnappkieferschalenprobe",s="Im ganzen Brachland bergen Schnappkieferpanzer einen Funken Leben aus den Süßwasseroasen. Taurendruiden schicken sie über das große Meer, um dem Silberwald zu helfen.",h="Im ganzen Brachland bergen Schnappkieferpanzer einen Funken Leben aus den Süßwasseroasen.",kw={"brachland","mura runetotem","oase","schnappkieferschalenprobe","das grabmal","silberwald","schnappkiefer","schildkrötenpanzer"},ang={["class:Druid"]="Druiden des Zirkels des Cenarius lernen durch das Studium der Oasenschnappkiefer, wie Leben fortbesteht und wie sich verseuchter Boden heilen ließe.",["race:Tauren"]="Als Tauren könnt Ihr die Reise dieses Panzers als Bekenntnis zur Earth Mother sehen. Euer Volk bringt Hilfe und natürliche Heilung über das Meer, selbst zu seinen untoten Verbündeten."},sec={{t="Ein Funken Oasenleben",b="Schnappkiefer gedeihen in den seltsamen, üppigen Oasen des Brachlands. Ihre widerstandsfähigen Panzer leuchten schwach und pulsieren noch lange voller Energie, nachdem das Tier verschwunden ist. Taurendruiden beobachten, wie rasch sich das Land verändert, und sehen in diesen Panzern einen widerstandsfähigen Funken von Kalimdors Wildnis. Ihre Lebenskraft zeigt, wie Leben selbst in rauen, trockenen Landstrichen gedeihen kann."},{t="Heilung ferner Lande",b="Naturforscher der Tauren schicken Boten mit Panzern über das Meer zu Mura Runetotem im Grabmal. Sie ist in den verseuchten Weiten des Silberwalds stationiert und sucht nach Wegen, den Verlassenen bei der Heilung der Nordlande zu helfen. Mura untersucht die Lebenskraft in den Schnappkieferpanzern und hofft, daraus zu erfahren, was einen kränkelnden Wald erneuern und sterbenden Boden wieder zum Grünen bringen kann."}},faq={{q="Was macht diesen Schnappkieferpanzer besonders?",a="Eine Schnappkieferschalenprobe bewahrt noch lange nach dem Sammeln ein schwaches Leuchten und einen Puls des Lebens. Sie stammt von Schnappkiefern rund um die seltsamen Süßwasseroasen des Brachlands, wo die natürlichen Energien ungewöhnlich stark sind.",al={"warum ist der panzer besonders","was ist ein schnappkieferpanzer","leuchtender panzer"}},{q="Wer braucht diese Probe?",a="Mura Runetotem, eine Taurendruidin, braucht den Panzer im Grabmal im Silberwald. Sie sucht nach Wegen, den Verlassenen bei der Heilung sterbender Lande zu helfen.",al={"wer will den panzer","wohin den panzer bringen","mura runetotem quest"}},{q="Warum einen Panzer aus dem Brachland bis in den Silberwald schicken?",a="Der Wald des Silberwalds ist verseucht und kränkelt, während das Leben in den Oasen des Brachlands aufgeblüht ist und sich behauptet hat. Druiden hoffen, dass die Lebenskraft in Kalimdors Tieren sie lehren kann, wie sich Lordaerons geschädigter Boden heilen lässt.",al={"warum in den silberwald schicken","verbindung zwischen panzer und silberwald"}},{q="Ist der Panzer gefährlich oder verderbt?",a="Nein. Der Panzer birgt reine Lebenskraft, keine dunkle Magie. Druiden sehen in der anhaltenden Energie inmitten des plötzlichen Wachstums im Brachland eine natürliche Widerstandskraft, die es zu fördern gilt.",al={"ist der panzer böse","ist der panzer verderbt"}}},fx={["6161673b"]={q="Was ist die Schnappkieferschalenprobe?",a="Es handelt sich um ein Exemplar vom Panzer einer Schnappkieferschildkröte, die in den trockenen Gebieten vom Brachland gefunden wurde. Diese Schale ist von einer seltsamen, pulsierenden Vitalität durchdrungen und wird sorgfältig aufbewahrt, damit ihre ungewöhnliche Lebensenergie weit weg von den Ebenen von Kalimdor untersucht werden kann.",al={"was ist schnappkieferschalenprobe","schnappkieferschale gegenstand","schnappkieferschalenprobe identität"}},c3ef5b23={q="Woher stammt die Schnappkieferschalenprobe?",a="Sie stammt von den wilden Schnappkiefern, die um die Oasen und Wasserwege vom Brachland leben. Die natürliche Schale wurde von Abenteurern der Horde in Kalimdor gesammelt und von den Tauren-Druiden als repräsentative Probe der blühenden Lebenskraft ausgewählt, die in dem sonnenverbrannten Ödland zu finden ist.",al={"schnappkieferschale herkunft","woher stammt schnappkieferschale","wer machte schnappkieferschalenprobe"}}},fp="20,149,21.326.0,21.350.0,38.194.0,22.140.0,51.200.0,34.157.0"}
P.entries["item:samuel-s-remains"] = {n="Samuels sterbliche Überreste",s="Nahe Todesend werden Samuels Knochen einem Diener der Geißel abgenommen und neben Marla beigesetzt.",h="Nahe Todesend werden Samuels Knochen einem Diener der Geißel abgenommen und neben Marla beigesetzt.",kw={"todesend","marla fipps","marlas grab","marla's last wish","novize elreth","samuel fipps","samuels sterbliche überreste"},ang={["race:Undead"]="Als Untoter lernt Ihr früh, dass die Ehrung der tragisch Verstorbenen die moralische Grenze zwischen freien Verlassenen und den willenlosen Dienern der Geißel markiert."},sec={{t="Ein tragisches Wiedersehen",b="Samuel Fipps und seine Frau Marla lebten friedlich in Tirisfal, bevor die Seuche des Untodes über Lordaeron hereinbrach. Samuel erlag ihr und wurde zu einem willenlosen Diener der Geißel. Marla entging dem Untod, doch Samuel erschlug sie. Im Sterben bat sie darum, neben ihm begraben zu werden, sobald seine verfluchte Gestalt zur Ruhe gebettet wäre.\n\nNovize Elreth in Todesend schickt frisch erwachte Verlassene in das Gebiet nordöstlich der Siedlung. Dort müssen sie Samuels umherstreifende Gestalt finden, seine Knochen bergen und sie in der vordersten Reihe des örtlichen Friedhofs beisetzen."}},faq={{q="Wer war Samuel Fipps?",a="Samuel Fipps war ein Mensch, der vor dem Dritten Krieg in Tirisfal lebte. Die Seuche der Geißel tötete ihn und erweckte ihn als untoten Diener des Lich King. Von blindem Hunger getrieben, erschlug er schließlich seine Frau Marla.",al={"samuel fipps","wer ist samuel","samuels vorgeschichte"}},{q="Wo werden Samuels sterbliche Überreste gefunden?",a="Samuels sterbliche Überreste werden seiner umherstreifenden Gestalt bei einem zerstörten Lager an der Straße nordöstlich von Todesend abgenommen. Wird seinem willenlosen Dasein ein Ende gesetzt, können seine Knochen geborgen werden.",al={"samuels sterbliche überreste finden","wo ist samuel fipps","samuels aufenthaltsort"}},{q="Warum bestatten die Verlassenen ihn neben seiner Frau?",a="Marlas letzter Wunsch war es, neben ihrem geliebten Mann zu ruhen, obwohl er sie getötet hatte. Novize Elreth erfüllt ihre Bitte, um zu zeigen, dass die frisch befreiten Verlassenen noch immer Mitgefühl, Achtung vor den Toten und Menschlichkeit besitzen. Diese Menschlichkeit unterscheidet sie von der Geißel.",al={"warum samuel begraben","marlas grab","marlas letzter wunsch"}}},fx={["29aac9a9"]={q="Woher stammen Samuels sterbliche Überreste?",a="Dies sind die sterblichen körperlichen Überreste von Samuel Fipps, einem ehemaligen Bewohner von Tirisfal, der der Plage der Untoten zum Opfer fiel und zu einer willenlosen Marionette der Geißel wurde. Nachdem er in der Wildnis nordöstlich von Todesend umhergeirrt war, wurde sein untoter Körper niedergestreckt, sodass seine Überreste endlich gesammelt und beigesetzt werden können.",al={"samuels überreste herkunft","woher kommen samuels überreste","wer machte samuels überreste"}}},fp="16,88,16.522.0,21.221.0,33.177.0,45.258.0"}
P.entries["item:sapphire-of-aku-mai"] = {n="Saphir von Aku'mai",s="Entlang der Tiefschwarzen Grotte bauen Naga die Saphire von Aku'mai ab. Wassergeister haften an den Kristallen, und Je'neu Sancrea sucht Hilfe, um sie sicherzustellen, bevor ihre arkane Kraft genutzt wird.",h="Entlang der Tiefschwarzen Grotte bauen Naga die Saphire von Aku'mai ab.",kw={"aku'mai","tiefschwarze grotte","kristalle","je'neu sancrea","naga","saphir","wassergeister","der zoramstrand"},ang={["class:Mage"]="Wasser durchdringt die Saphire auf natürliche Weise und macht sie zu geschätzten Leitern für mächtige arkane Komponenten.",["class:Shaman"]="Als Schamane des Irdenen Rings könnt Ihr die Wassergeister spüren, die in diesen Edelsteinen gebunden sind. Der Abbau durch die Naga bedroht die Elemente."},sec={{t="Edelsteine der Tiefe",b="An den wassergefüllten Eingängen zur Tiefschwarzen Grotte bergen die Wände am Zoramstrand von Eschental Saphire von Aku'mai. Wassergeister haften an den Kristallen, deren elementare Energie der Magie Kraft verleiht. Als Späher berichteten, dass Naga die Edelsteine unter Tage abbauten, bat der Schamane Je'neu Sancrea Reisende um Hilfe, um sie sicherzustellen. In den Händen der Naga könnten die Steine verheerende arkane Riten speisen."}},faq={{q="Was ist ein Saphir von Aku'mai?",a="Saphire von Aku'mai säumen die Wände der Tiefschwarzen Grotte. Wassergeister haften an den Kristallen und verleihen ihnen große arkane und elementare Kraft.",al={"was ist dieser kristall","geschichte des saphirs von aku'mai","was sind diese edelsteine"}},{q="Warum sammeln die Naga diese Saphire?",a="Je'neu Sancrea vermutet, dass die Naga die Wasserenergien und arkanen Energien der Kristalle für gefährliche Zauberei im versunkenen Tempel nutzen wollen. Ihre genauen Absichten bleiben ungewiss.",al={"warum wollen naga saphire","kristallabbau durch naga"}},{q="Wer sucht nach diesen Saphiren?",a="Je'neu Sancrea, ein Schamane des Irdenen Rings am Außenposten von Zoram'gar am Zoramstrand von Eschental, bittet Reisende, die Saphire zu sammeln und von den Händen der Naga fernzuhalten.",al={"wer will saphire von aku'mai","wer gibt essence of akumai ab"}},{q="Sind diese Kristalle unmittelbar mit dem Ungeheuer Aku'mai verbunden?",a="Die Kristalle sind nach Aku'mai benannt, der monströsen Hydra in der Tiefe, wachsen aber auf natürliche Weise in den Höhlenwänden. Ihr Name spiegelt ihre Nähe zu der dunklen Präsenz in den Ruinen wider.",al={"verbindung zu aku'mai","stammt es von aku'mai"}}},fx={["12f03799"]={q="Woher kommen die Saphire von Aku'mai und wer hat sie hergestellt?",a="Diese großen Saphircluster wachsen auf natürliche Weise entlang der Höhlenwände in den ersten Tunneln der Tiefschwarzen Grotte. Sie wurden nicht von sterblicher Hand gefertigt, sondern sind natürliche Mineralformationen, die von den umgebenden Energien der Höhle durchdrungen sind. Wassergeister haften auf natürliche Weise an den Kristallen und verleihen ihnen innewohnende elementare Kraft.",al={"herkunft saphir von aku'mai","wer machte saphir von aku'mai","woher kommen saphire von aku'mai"}}},fp="19,179,16.380.0,30.139.0,44.176.0,35.158.0,54.186.0"}
P.entries["item:sapphire-of-sky"] = {n="Saphir des Himmels",s="Im Grabhügel von Ban'ethil hilft der Saphir des Himmels, schlafende Druiden der Kralle aus dem Smaragdgrünen Traum zurückzurufen. Nachtelfen hüten ihn als eines der vier heiligen Relics of Wakening.",h="Im Grabhügel von Ban'ethil hilft der Saphir des Himmels, schlafende Druiden der Kralle aus dem Smaragdgrünen...",kw={"athridas bearmantle","grabhügel von ban'ethil","truhe des himmels","druide der kralle","smaragdgrüner traum","relics of wakening","saphir des himmels"},ang={["class:Druid"]="Als Druide versteht Ihr, warum heilige Anker wichtig sind, wenn Euer Geist den Smaragdgrünen Traum betritt. Ohne sie kann die Zwiesprache tödlich enden.",["race:NightElf"]="Als Nachtelf wisst Ihr, dass der Schutz der heiligen Relikte im Grabhügel von Ban'ethil hilft, Teldrassils zerbrechliche Ordnung angesichts wachsender Verderbnis zu bewahren."},sec={{t="Das Ritual des Erwachens",b="Druiden der Kralle halten im Grabhügel von Ban'ethil tief zwischen Teldrassils Wurzeln ihren Winterschlaf. Dort stehen sie in Zwiesprache mit der Wildnis. Das Erwachen aus dieser tiefen Trance ist gefährlich, deshalb sichern vier heilige Relikte den Übergang: der Schwarze Federkiel, der Rabenkrallentalisman, die Rune des Nistens und der Saphir des Himmels. Der Edelstein vervollständigt die Harmonie, die nötig ist, um die schlafenden Geister aus dem Smaragdgrünen Traum zurückzurufen. Ohne ihn könnten sie dort für immer gefangen bleiben."},{t="Die Bedrohung in Ban'ethil",b="Verderbte Gnarlpine-Furbolgs haben den Grabhügel von Ban'ethil überrannt und die heiligen Relikte an ihren Aufbewahrungsorten zurückgelassen. Der Saphir des Himmels liegt in der Truhe des Himmels, inmitten der gewundenen unterirdischen Gänge. Die Druiden schlafen noch immer, während die Furbolgs um sie herum wüten. Athridas Bearmantle in Dolanaar braucht den Saphir und die anderen Relikte, um die Schläfer zu wecken, bevor sie für immer verloren sind."}},faq={{q="Was ist der Saphir des Himmels?",a="Der Saphir des Himmels ist ein heiliger Edelstein und eines der vier Relics of Wakening, die im Grabhügel von Ban'ethil aufbewahrt werden. Zusammen mit drei Vogeltalismanen führt er Druiden der Kralle sicher aus dem Smaragdgrünen Traum.",al={"geschichte des saphirs des himmels","was ist dieser edelstein","saphir des himmels"}},{q="Wo wird der Saphir des Himmels aufbewahrt?",a="Der Saphir des Himmels wird in der Truhe des Himmels aufbewahrt, im unterirdischen Labyrinth des Grabhügels von Ban'ethil im Herzen Teldrassils.",al={"wo ist der saphir des himmels","fundort der truhe des himmels","fundort des saphirs"}},{q="Warum wird der Saphir gerade jetzt gebraucht?",a="Verderbte Gnarlpine-Furbolgs sind in den Grabhügel von Ban'ethil eingedrungen und haben die schlafenden Druiden in große Gefahr gebracht. Tief in Trance können sie nicht einfach von selbst erwachen. Athridas Bearmantle braucht den Saphir und die anderen Relikte für das heikle Ritual des Erwachens, bevor die Schläfer für immer verloren sind.",al={"warum den saphir holen","zweck der relics of wakening"}},{q="Wer nutzt dieses Artefakt?",a="Die Druiden der Kralle und Ritualhüter wie Athridas Bearmantle nutzen den Saphir, um ihre schlafenden Brüder aus tiefer Zwiesprache mit der Natur zu wecken.",al={"wer nutzt den saphir des himmels","edelstein für das druidenritual"}}},fp="15,171,19.457.0,23.394.0,28.199.0,34.132.0,37.295.0,23.152.0"}
P.entries["item:sara-balloo-s-plea"] = {n="Sara Balloos Hilfegesuch",s="In ihrer Trauer bittet Sara Balloo einen Streiter der Allianz, ihr handschriftliches Hilfegesuch zu König Magni Bronzebart zu bringen.",h="In ihrer Trauer bittet Sara Balloo einen Streiter der Allianz, ihr handschriftliches Hilfegesuch zu König...",kw={"a king's tribute","high seat","eisenschmiede","magni bronzebart","sara balloo","sara balloos hilfegesuch"},ang={["faction:Alliance"]="Als Streiter der Allianz bringt Ihr Saras Gesuch vor den König. Sie vertraut Euch wegen Eurer Dienste für die Allianz.",["race:Dwarf"]="Als Zwerg bringt Ihr Saras Nachricht zum High Seat, damit König Magni jeden Gebirgsjäger oder Bürger anhört, selbst in Trauer."},sec={{t="Das Gesuch einer Witwe",b="Ihre Trauer hält Sara davon ab, vor den High Seat zu treten, also vertraut sie ihre Worte einem Abenteurer an, der der Allianz treu ist. Sie bittet König Magni, der stillen Trauer und der Opfer einfacher Zwergenfamilien zu gedenken, die dem Königreich dienen."}},faq={{q="Was ist Sara Balloos Hilfegesuch?",a="Sara Balloos Hilfegesuch ist ein handschriftlicher Brief an König Magni Bronzebart. Sara bittet um sein Gehör, während sie im Stillen trauert.",al={"sara balloos hilfegesuch","witwe brief eisenschmiede","saras brief"}},{q="Warum braucht Sara Balloo jemanden, der es für sie überbringt?",a="Sara ist von Trauer überwältigt und glaubt, dass ein Auftritt vor dem König von Eisenschmiede in diesem Zustand ihrem Anliegen schaden würde. Deshalb vertraut sie einem Streiter der Allianz an, es zu überbringen.",al={"warum brief überbringen","warum kann sara nicht gehen","saras trauer"}},{q="Wer erhält diese Nachricht?",a="König Magni Bronzebart erhält Saras Brief am High Seat von Eisenschmiede.",al={"wer erhält das hilfegesuch","wem überbringen","magni brief"}},{q="Wozu führt die Übergabe des Briefes?",a="Die Übergabe des Briefes macht König Magni auf Sara Balloos Verlust aufmerksam und leitet eine königliche Antwort ein, die ihre gefallenen Angehörigen ehrt.",al={"hilfegesuch questreihe","verbindung zu a kings tribute","was passiert als nächstes"}}},fx={["2b83ea9f"]={q="Woher kommt Sara Balloos Hilfegesuch und wer hat es geschrieben?",a="Diese schriftliche Notiz wurde direkt von Sara Balloo verfasst, einer trauernden Zwergenfrau in Eisenschmiede. Von Verlust am Boden zerstört, bereitete sie die Nachricht selbst vor, um eine Petition an den Thron von Eisenschmiede zu richten, und vertraute sie einem Champion der Allianz an, anstatt selbst die emotionale Reise zum High Seat anzutreten.",al={"wer schrieb sara balloos hilfegesuch","woher stammt sara balloos hilfegesuch","wer machte sara balloos hilfegesuch"}},["4ac5e6cf"]={q="Warum möchte jemand Sara Balloos Hilfegesuch haben?",a="König Magni Bronzebart benötigt den Brief, um die Petition einer seiner trauernden Untertanen anzuhören. Sara Balloo bringt es in ihrem bekümmerten Zustand nicht übers Herz, vor dem Monarchen zu erscheinen, daher verlässt sie sich darauf, dass Ihr das Gesuch direkt in die Hände des Herrschers von Eisenschmiede überreicht.",al={"warum wird sara balloos hilfegesuch benötigt","wer will sara balloos hilfegesuch","warum sara balloos hilfegesuch überbringen"}}},fp="18,110,16.229.0,27.127.0,53.166.0,26.76.0,40.136.1"}
P.entries["item:sarilus-foulborne-s-head"] = {n="Sarilus Faulmuts Kopf",s="Über die Grenze vom Brachland her erreicht Sarilus Faulmuts Kopf das Eschental als Beweis für den Tod des Zauberers. Er entweihte die Gewässer des Eschentals, und die Schildwachen forderten seinen Kopf.",h="Über die Grenze vom Brachland her erreicht Sarilus Faulmuts Kopf das Eschental als Beweis für den Tod des...",kw={"brachland","glutnebelgipfel","kopf","mage summoner","sarilus faulmut","silberwindzuflucht","velene sternenschlag","wasserelementare"},ang={["faction:Alliance"]="Dieser Angriff erfordert, tief in feindliches Gebiet der Horde im Brachland einzudringen, um einen gefährlichen abtrünnigen Zauberwirker auszuschalten.",["race:NightElf"]="Faulmuts Kopf zu holen erfüllt die Rache der Schildwachen an einem arkanen Schänder, der die Geister des Landes entweihte."},sec={{t="Ein Schänder verstummt",b="Sarilus Faulmut war ein Zauberwirker der Verlassenen, der sich auf dem Glutnebelgipfel im nördlichen Brachland niedergelassen hatte. Er erzürnte die Nachtelfen, indem er Scharen von Wasserelementaren verdarb und an sich band.\n\nVon der Silberwindzuflucht aus erkannte Schildwache Velene Sternenschlag sein Werk und entsandte Streiter über die Grenze ins Gebiet der Horde, um seine Experimente zu beenden. Sternenschlag würde nur seinen abgetrennten Kopf als Beweis dafür akzeptieren, dass der spöttische Magier tot war und die aufgewühlten Gewässer des Eschentals etwas Ruhe finden könnten."}},faq={{q="Wer war Sarilus Faulmut?",a="Sarilus Faulmut war ein untoter Magier, der sich auf dem Glutnebelgipfel im nördlichen Brachland niedergelassen hatte. Er erzürnte die Nachtelfen, indem er Unmengen von Wasserelementaren verdarb und beschwor, weshalb Schildwache Velene Sternenschlag seinen Tod befahl.",al={"wer ist sarilus","sarilus faulmut hintergrundgeschichte","wer ist faulmut"}},{q="Warum will Schildwache Velene Sternenschlag seinen Kopf?",a="Velene Sternenschlag wollte Gewissheit, dass der überhebliche Zauberer tot war. Sarilus verspottete sie, während er die Wassergeister der Region entweihte, und nur seinen abgetrennten Kopf würde sie als Beweis für das Ende der Bedrohung akzeptieren.",al={"warum seinen kopf holen","velene sternenschlag kopf","beweis für den tod"}},{q="Wo befindet sich Sarilus Faulmut?",a="Sarilus Faulmut haust auf dem Glutnebelgipfel im nördlichen Brachland, unmittelbar südlich der Grenze zum Eschental.",al={"wo ist faulmut zu finden","sarilus aufenthaltsort","glutnebelgipfel magier"}},{q="Warum entweihte Faulmut Wasserelementare?",a="Sarilus Faulmut nutzte arkane Beschwörungen, um zahlreiche Wasserelementare seinem Willen zu unterwerfen und zu verderben. Seine rücksichtslosen Eingriffe störten das natürliche Gleichgewicht der Gewässer nahe dem Eschental und führten zu rascher Vergeltung durch die Schildwachen.",al={"warum elementare verderben","verderbnis der wasserelementare","faulmuts beweggründe"}}},fx={a996e76e={q="Woher stammt Sarilus Faulmuts Kopf?",a="Dieser abgetrennte Kopf stammt direkt von Sarilus Faulmut, einem Magier der Verlassenen, der sich auf dem Gipfel vom Glutnebelgipfel im nördlichen Brachland niedergelassen hatte. Faulmut operierte in der Nähe der Grenzen vom Eschental und verbrachte seine Tage damit, Wasserelementare zu schänden und die Nachtelfen zu provozieren, bis Schildwache Velene Sternenschlag einen Abenteurer in Feindesgebiet schickte, um seinem Spott ein Ende zu setzen.",al={"herkunft sarilus kopf","sarilus kopf herkunft","woher stammt foulmuts kopf"}}},fp="24,177,18.497.1,26.241.1,50.217.0,35.104.1,44.240.0"}
P.entries["item:sarkoth-s-mangled-claw"] = {n="Sarkoths zerstückelte Klaue",s="An den südlichen Klippen des Tals der Prüfungen trägt Sarkoths zerstückelte Klaue die Spuren eines verwundeten Jägers. Hana'zua zertrümmerte die Schere des Skorpids, bevor dessen giftiger Stich ihn niederstreckte.",h="An den südlichen Klippen des Tals der Prüfungen trägt Sarkoths zerstückelte Klaue die Spuren eines...",kw={"klaue","durotar","hana'zua","zerstückelte klaue","sarkoth","skorpid","das tal der prüfungen"},ang={["faction:Horde"]="Als Mitglied der Horde ist das Erringen der Trophäe im Tal der Prüfungen für Euch eine frühe Prüfung von Mut und Kampfkraft in Durotars rauer Wildnis.",["race:Troll"]="Als Troll gebt Ihr einem sterbenden Angehörigen der Dunkelspeer etwas Würde, indem Ihr Hana'zua die Klaue bringt. Er erfährt, dass sein letzter Schlag der Bestie vor dem Ende eine Schramme zufügte."},sec={{t="Eine Trophäe der Rache",b="Hana'zua, ein junger Dunkelspeer-Troll, begegnete Sarkoth bei der Jagd im Tal der Prüfungen. Der gewaltige Skorpid durchbohrte seine Brust mit seinem giftigen Stachel und ließ ihn blutend unter einem nahen Baum zurück.\n\nVor dem Stich zertrümmerte Hana'zua die Schere der Bestie. Die zerschlagene Klaue beweist, dass Sarkoth erschlagen wurde. Für den verwundeten Jäger zeigt ihre Schramme, dass sein verzweifelter Schlag traf, und wahrt seine Kriegerehre, während Gift durch seine Adern strömt."}},faq={{q="Warum ist die Klaue zerstückelt?",a="Sarkoths Schere wurde in einem verzweifelten Zweikampf mit Hana'zua, einem Trolljäger, zertrümmert. Sarkoth stach Hana'zua in die Brust, doch der Troll schlug zu, bevor sich die Klaue der Bestie um sein Bein schließen konnte.",al={"warum zerbrochene klaue","wer zertrümmerte sarkoths klaue","geschichte der zerstückelten klaue"}},{q="Wer will Sarkoths zerstückelte Klaue?",a="Hana'zua bittet um die Klaue. Schwer verwundet liegt er unter einem Baum im Tal der Prüfungen und fürchtet, dort zu sterben. Er will Sarkoth erschlagen sehen, um seine Ehre zu wahren; die vollbrachte Tat gibt ihm die Kraft, durchzuhalten, bis Gornek Hilfe schickt.",al={"wer braucht sarkoths klaue","bei wem abgeben","hanazua klaue"}},{q="Woher stammt diese Klaue?",a="Die Klaue stammt von Sarkoth, einem großen, angriffslustigen Skorpid, der das Hochplateau entlang der südlichen Klippen des Tals der Prüfungen in Durotar durchstreift.",al={"sarkoth fundort","wo ist sarkoth","wo zerstückelte klaue bekommen"}}},fx={["5a9dc5fc"]={q="Was ist Sarkoths zerstückelte Klaue?",a="Es handelt sich um die abgetrennte Schere von Sarkoth, einem ungewöhnlich großen und bösartigen Skorpion, der auf dem südlichen Plateau oberhalb von Das Tal der Prüfungen umherstreift. Die Klaue weist schwere, splitternde Schäden auf, die ihm der schwer verwundete Troll der Dunkelspeere Hana'zua während ihres verzweifelten Kampfes zugefügt hat; sie dient als unbestreitbarer Beweis dafür, dass die monströse Bestie endlich erschlagen wurde.",al={"was ist sarkoths zerstückelte klaue","sarkoth klaue identität","zerstückelte klaue"}}},fp="22,191,21.449.0,24.189.0,33.219.0,30.147.0"}
P.entries["item:sarltooth-s-talon"] = {n="Sarlatans Kralle",s="Über Whelgars Ausgrabungsstätte zeugt nur noch Sarlatans Kralle vom Angriff des Raptors. Ormer Eisenzopf will die Kralle als Beweis dafür, dass die Bestie tot ist.",h="Über Whelgars Ausgrabungsstätte zeugt nur noch Sarlatans Kralle vom Angriff des Raptors.",kw={"ausgrabung","ormer eisenzopf","raptor","sarltooth","kralle","sumpfland","whelgar"},ang={["class:Hunter"]="Als Jäger werden Eure Treffsicherheit und Eure Tierbeherrschung auf die Probe gestellt, wenn Ihr einen gerissenen Rudelführer wie Sarltooth aufspürt und eine Kralle als Trophäe nehmt.",["race:Dwarf"]="Als Zwerg bringt Ihr mit der Bergung dieser Kralle Rache für die zwergischen Archäologen, die auf Geheiß von König Magni Bronzebart im Dienst der Explorers' League starben."},sec={{t="Eine Trophäe der Rache",b="Ormer Eisenzopf sah vom Grat aus zu, wie Raptoren Whelgars Ausgrabungsstätte überrannten und die Zwergenexpedition niedermetzelten. Er konnte sie nicht aufhalten. Ein riesiger Raptor, Sarltooth, schien ihm der Anführer des Rudels zu sein. Aus Rache für seine gefallenen Angehörigen forderte Ormer den Tod der Bestie und eine ihrer Krallen als Beweis. Die Kralle markiert das Ende von Sarltooths Herrschaft über die alten Zwergenruinen."}},faq={{q="Woher stammt Sarlatans Kralle?",a="Sarlatans Kralle stammt von Sarltooth, einem großen Alpharaptor, der auf den westlichen Graten über Whelgars Ausgrabungsstätte im Sumpfland umherstreift.",al={"wer lässt sarlatans kralle fallen","sarltooth fundort","wie die kralle erhalten"}},{q="Wer will Sarlatans Kralle haben?",a="Ormer Eisenzopf will die Kralle haben. Der Zwerg hält vom Rundblick über Whelgars Ausgrabungsstätte aus Wache und verlangt einen Beweis dafür, dass die Bestie, die seine Mannschaft niedermetzelte, tot ist.",al={"wer nimmt die kralle","wo die kralle abgeben","ormer eisenzopf quest"}},{q="Warum braucht Ormer Eisenzopf einen Beweis für Sarltooths Tod?",a="Ormer glaubt, dass Sarltooth das Raptorenrudel anführte, das die zwergischen Ausgräber vertrieb und tötete. Er sieht in der Kralle Gerechtigkeit und ein wenig Frieden für seine gefallenen Kollegen.",al={"warum sarltooth töten","was hat sarltooth getan"}},{q="Was geschah mit den Zwergen an der Ausgrabungsstätte?",a="Die Zwerge suchten bei der Ausgrabung nach alten Artefakten für die Explorers' League. Wilde Raptoren überfielen die Arbeiter, schlachteten die meisten ab und trieben die Überlebenden auf den nahen Grat.",al={"whelgars ausgrabungsstätte hintergrundgeschichte","warum sind raptoren bei der ausgrabung"}}},fx={["28fc0e8a"]={q="Was ist Sarlatans Kralle?",a="Es handelt sich um eine abgetrennte Kralle von Sarlatan, dem wilden Raptor, der verdächtigt wird, das grausame Rudel anzuführen, das Whelgars Ausgrabungsstätte überrannt hat. Ormer Eisenzopf fordert die Kralle als unbestreitbaren Beweis dafür, dass das Biest erschlagen und die gefallenen zwergischen Ausgräber gerächt wurden.",al={"was ist sarlatans kralle","sarlatan kralle lore"}}},fp="17,153,21.384.0,39.137.0,28.174.0,57.173.0,52.167.0"}
P.entries["item:sathrah-s-sacrifice"] = {n="Sathrahs Opferung",s="Im Tempel des Mondes bietet Sathrahs Opferung dem Geist von Lady Sathrah eine Chance auf Frieden. Ihre silbrigen Spinndrüsen stammen von der mächtigen Spinne, die auf Teldrassil haust.",h="Im Tempel des Mondes bietet Sathrahs Opferung dem Geist von Lady Sathrah eine Chance auf Frieden.",kw={"darnassus","elune","lady sathrah","priesterin a'moora","sathrahs opferung","silbrige spinndrüsen","spinne","teldrassil","tempel des mondes"},ang={["class:Priest"]="Als Priester könnt Ihr den Ritus als einen Akt göttlicher Gnade betrachten. Die Sisterhood of Elune nutzt heiliges Wasser, um den Makel zu tilgen, statt das erschlagene Tier einfach zu entsorgen.",["race:NightElf"]="Als Nachtelf wisst Ihr, dass das Töten verderbter Wildtiere eine betrübliche Pflicht ist. Lady Sathrahs Geist zu Elune's Grace zurückzuführen, erweist dieser Pflicht die gebührende Ehre."},sec={{t="Läuterung im heiligen Wasser",b="Lady Sathrah war eine ehrwürdige Kreatur von Teldrassil. Dann breiteten sich schleichender Wahnsinn und Verderbnis in den Ästen des großen Baumes aus und ergriffen Besitz von ihr. Die Sisterhood of Elune bittet Euch, ihre silbrigen Spinndrüsen als geweihte Opfergabe zurückzubringen. Sie sind keine Trophäe.\n\nAm Brunnen im Tempel des Mondes werden ihre Überreste in heiligem Wasser gebadet. Der Ritus wäscht den Makel fort, der Sathrahs Verstand vergiftete, und befreit ihre gequälte Seele. Ihr Geist erscheint friedlich im Heiligtum, mit der Verheißung einer Wiedergeburt unter Elune's Grace."}},faq={{q="Was ist Sathrahs Opferung?",a="Bei Sathrahs Opferung werden silbrige Spinndrüsen von Lady Sathrah dargebracht, einer mächtigen Spinne, die auf Teldrassil der Verderbnis anheimfiel. Die Sisterhood of Elune nutzt sie in einem Ritus, um ihre Seele zu läutern.",al={"was sind die spinndrüsen","sathrahs opferung gegenstand","lady sathrah opfergabe"}},{q="Warum müssen die Spinndrüsen in den Brunnen gelegt werden?",a="Der Brunnen im Tempel des Mondes in Darnassus enthält heiliges Wasser, das Elune geweiht ist. Das Eintauchen von Sathrahs Überresten wäscht die Verderbnis fort, die sie in den Wahnsinn trieb, und befreit ihren Geist von seinen Qualen.",al={"warum tempelbrunnen","warum sathrah opfern","was bewirkt der brunnen"}},{q="Was geschieht, wenn die Opfergabe dargebracht wird?",a="Wenn Ihr die Opfergabe in das heilige Wasser legt, wird die Verderbnis getilgt und Lady Sathrahs geisterhafte Gestalt erscheint. Sie wandelt ruhig um das Becken und zeigt damit, dass ihre Seele Frieden gefunden hat.",al={"was geschieht am brunnen","sathrahs geist erscheint","brunnenereignis"}},{q="Wer beaufsichtigt dieses Ritual?",a="Priesterin A'moora beaufsichtigt den Ritus. Als Dienerin der Sisterhood of Elune im Tempel des Mondes weist sie Euch an, Sathrah zur Ruhe zu betten und ihre Überreste der Göttin darzubringen.",al={"wer vergibt sathrahs opferung","priesterin a'moora quest","wer läutert sathrah"}}},fx={c7289e92={q="Woher stammt Sathrahs Opferung?",a="Priesterin A'moora bereitete dieses Opfer direkt aus den silbrigen Spinndrüsen vor, die von Lady Sathrah stammen, einer großen Spinne, die in Teldrassil erlegt wurde, nachdem sie dem Wahnsinn und der Verderbnis anheimgefallen war.",al={"sathrahs opferung herkunft","woher stammt sathrahs opferung","wer machte sathrahs opferung"}},b18748b3={q="Warum möchte Priesterin A'moora Sathrahs Opferung haben?",a="Priesterin A'moora benötigt das Opfer, damit es in die heiligen Gewässer von The Temple of the Moon gelegt werden kann. Durch diese Opfergabe an Elune kann die Verderbnis, die Lady Sathrah im Leben verzerrt hat, endlich gereinigt werden, wodurch das große Biest zur Ruhe kommt und ihr Geist erneuert wiedergeboren werden kann.",al={"warum wird sathrahs opferung gesucht","warum sathrahs opferung opfern","wofür ist sathrahs opferung"}}},fp="19,171,31.542.0,28.176.0,50.196.0,44.187.1,25.187.0"}
P.entries["item:satyr-horns"] = {n="Satyrhörner",s="Im Eschental locken Satyrhörner rachsüchtige Dryaden und Händler auf dem Weg nach Ratschet an. Sie stammen von Satyrn, deren Verderbnis im uralten Wald Wurzeln geschlagen hat.",h="Im Eschental locken Satyrhörner rachsüchtige Dryaden und Händler auf dem Weg nach Ratschet an.",kw={"anilia","forest song","illiyana","nachtflucht","pixel","satyrhörner","satyrnaar","splitterholzposten","xavian"},ang={["faction:Horde"]="Vom Splitterholzposten aus beseitigen Krieger der Horde Satyrn, die ihren Holzeinschlag bedrohen, und verkaufen dann die Hörner an Goblinkäufer auf dem Weg nach Ratschet.",["race:NightElf"]="Für die Kaldorei ist das Erbeuten von Satyrhörnern eine bittere Pflicht. Es reinigt den Wald ihrer Ahnen von Verwandten, die ihr Erbe gegen den Dienst an Dämonen eingetauscht haben."},sec={{t="Trophäen für Rache und Handel",b="Die Satyrn des Eschentals tragen Hörner, die ihre dämonische Verderbnis kennzeichnen. Am Schrein von Aessina sammelt die Dryade Illiyana sie aus Rache für ihre verlorene Schwester Anilia. Pixel, eine reisende Goblindame, die am Splitterholzposten rastet, will damit handeln. In Ratschet ist die Nachfrage gestiegen, wo Jäger diese Überreste erschlagener Dämonen verkaufen."},{t="Die verdorbenen Enklaven ausmerzen",b="Satyrhörner müssen den Satyrn selbst abgeschnitten werden; gewöhnliche Lieferanten verkaufen sie nicht. Satyrn halten Festungen im ganzen Eschental, von den verdorbenen Hainen von Xavian bis zu den Senken von Satyrnaar und den Ruinen der Nachtflucht. Die Säuberung dieser Enklaven drängt die anhaltende dämonische Verderbnis zurück. Sie liefert auch trauernden Wächtern und eifrigen Händlern Beweise für die Dezimierung."}},faq={{q="Warum will Illiyana Satyrhörner?",a="Illiyana sucht Satyrhörner, um ihre Schwester Anilia zu rächen, die von den Satyrn des Eschentals ermordet wurde. Die Hörner zeigen, dass ihre Zahl schwindet, und bringen Anilias Geist Frieden.",al={"illiyana hörner","anilia satyrn","forest song quest"}},{q="Warum sammelt Pixel Satyrhörner?",a="Pixel, eine geschäftstüchtige Reisende, die am Splitterholzposten verweilt, sammelt Satyrhörner für die Reise nach Ratschet. Sie weiß, dass sie im Goblinhafen einen hohen Preis erzielen, und heuert deshalb Jäger an, die sich vor ihrer Abreise der Gefahr stellen.",al={"pixel splitterholzposten","warum will pixel hörner","ratschet satyrhörner"}},{q="Wo findet man am besten Satyrn mit diesen Hörnern?",a="Satyrn leben in mehreren verdorbenen Gebieten des Eschentals. Viele finden sich in Xavian und Satyrnaar im Nordosten sowie in der Nachtflucht im östlichen Teil des mittleren Waldgebiets.",al={"satyrn fundorte eschental","wo sind satyrn","satyrlager"}},{q="Was sind Satyrn, und warum haben sie Hörner?",a="Satyrn sind uralte Nachtelfen, die durch Pakte während des War of the Ancients in dämonische, tierhafte Wesen verwandelt wurden. Ihre Hufe, Schwänze und Hörner kennzeichnen die dämonische Verderbnis, die ihnen die Brennende Legion verliehen hat.",al={"was ist ein satyr","warum haben satyrn hörner"}}},fx={["2131c67f"]={q="Was sind Satyrhörner?",a="Satyrhörner sind die gekrümmten, teuflischen Hörner, die von den Köpfen der erschlagenen Satyrn abgetrennt wurden, die im Eschental lauern. Als dämonische Verderbnis der uralten Nachtelfen tragen Satyrn diese bedrohlichen Auswüchse als Zeichen ihrer verfluchten Heimsuchung. In den Händen von Abenteurern dienen sie hauptsächlich als grimmiger Beweis für den Untergang eines Satyrs oder als geschätzte, exotische Kuriositäten, mit denen in ganz Kalimdor gehandelt wird.",al={"was sind satyrhörner","satyrhörner gegenstand","satyrhorn identität"}},["8a39621c"]={q="Warum möchte jemand Satyrhörner haben?",a="Verschiedene Fraktionen suchen Satyrhörner aus sehr unterschiedlichen Gründen. Für die Dryade Illiyana in Forest Song dienen sie als unbestreitbare Trophäen der Vergeltung gegen die korrupten Dämonen, die ihre Schwester Anilia ermordeten. Unterdessen sammeln opportunistische Händler wie Pixel sie, um sie im geschäftigen Hafen von Ratschet zu verkaufen, wo eine große Nachfrage nach exotischen alchemistischen Reagenzien, Kuriositäten und Tierkörperteilen herrscht.",al={"wer will satyrhörner","warum satyrhörner sammeln","warum werden satyrhörner gesucht"}}},fp="11,163,34.327.0,30.359.0,35.170.0,36.223.0,58.155.0,44.212.0"}
P.entries["item:savannah-lion-tusk"] = {n="Savannenlöwenhauer",s="Im Brachland werden Savannenlöwenhauer von Jagdtrophäen zu Zutaten für Chen Stormstouts legendäres Bier.",h="Im Brachland werden Savannenlöwenhauer von Jagdtrophäen zu Zutaten für Chen Stormstouts legendäres Bier.",kw={"brachland","braumeister drohn","chen stormstout","dishu","humar","ratschet","savannenlöwenhauer"},ang={["class:Hunter"]="Als Jäger stellt das Aufspüren der wilden Rudel im Brachland Euer Können auf die Probe. Ihre gefährlichen Fangzähne können im Kampf tödlich sein und sind für einheimische Brauer wertvoll."},sec={{t="Eine ungewöhnliche Brauzutat",b="Die Großkatzen des Brachlands tragen scharfe, schwere Hauer. Prowler, Jägerinnen, von Patriarchen geführte Rudel und Bestien wie Humar the Pridelord tragen sie allesamt. Reisende nehmen die Zähne als Beweis einer erfolgreichen Jagd mit. In Ratschet verwendet Braumeister Drohn die Hauer zusammen mit plainstrider-Nieren und thunder lizard-Hörnern, um Chen Stormstouts berühmtes Gebräu nachzubrauen. Das starke Bier hat einen legendären Biss, dem nur wenige sterbliche Kehlen gewachsen sind."}},faq={{q="Warum braucht Braumeister Drohn Savannenlöwenhauer?",a="In Ratschet verwendet Braumeister Drohn Savannenlöwenhauer, um das nach Chen Stormstout benannte Gebräu nachzubrauen. Sein Mentor gab das Rezept an ihn weiter, und die Hauer sind eine von drei Zutaten aus dem Brachland für den unverwechselbaren Geschmack und Biss des Starkbiers.",al={"warum hauer für bier","drohn löwenhauer","braumeister drohn rezept"}},{q="Welche Bestien tragen Savannenlöwenhauer?",a="Savannenlöwenrudel im gesamten Brachland tragen diese Hauer. Dazu gehören Savannah Highmanes, Patriarchen, Matriarchs, Jägerinnen, Prowler und seltene Bestien wie Dishu und Humar the Pridelord.",al={"wo werden löwenhauer fallen gelassen","wer lässt löwenhauer fallen","savannenlöwenhauer herkunft"}},{q="Haben Löwen tatsächlich Hauer?",a="Die Großkatzen der Savanne haben übergroße Eckzähne, die in Kalimdors rauer Wildnis auffällig und dick heranwachsen. Einheimische Jäger und Grenzlandbewohner nennen sie Hauer.",al={"warum heißen löwenzähne hauer","löwenhauer und fangzähne im vergleich","löwenhauer anatomie"}}},fx={["98d362c4"]={q="Was ist ein Savannenlöwenhauer?",a="Ein Savannenlöwenhauer ist ein scharfer Eckzahn, der von den räuberischen Katzen geerntet wird, die durch die sonnengebrannten Ebenen vom Brachland streifen. Obwohl sie als Hauer bezeichnet werden, handelt es sich um die formidablen Fangzähne der Savannenlöwen, die die örtlichen Jagdgründe beherrschen. Neben ihrer Funktion als grimmige Trophäen des Überlebens in der Wildnis finden diese widerstandsfähigen Teile bei Einheimischen, die wissen, wie man ihre wesentlichen Qualitäten extrahiert, eigenartige Verwendung.",al={"was ist savannenlöwenhauer","savannenlöwenhauer lore","löwenhauer"}},ea601034={q="Woher stammt ein Savannenlöwenhauer?",a="Diese Hauer stammen direkt von den wilden Rudelkatzen, die die zentralen Savannen von Kalimdor durchjagen. Jede Löwenart, die das Brachland durchstreift – von Streunern und Jägerinnen bis hin zu mächtigen Patriarchen und Hochmähnen – besitzt diese scharfen Fangzähne und verlässt sich auf sie, um Steppenläufer zu Fall zu bringen und ihr Revier gegen konkurrierende Raubtiere zu verteidigen.",al={"woher kommen löwenhauer","wer lässt löwenhauer fallen","löwenhauer quelle"}}},fp="18,104,28.414.0,51.240.0,39.188.0,29.151.0"}
P.entries["item:scaber-stalk"] = {n="Schorfstängling",s="In Dunkelküste sucht Barithras Mondschatten Schorfstänglinge aus einer Höhle hinter den Cliffspring Falls.",h="In Dunkelküste sucht Barithras Mondschatten Schorfstänglinge aus einer Höhle hinter den Cliffspring Falls.",kw={"auberdine","barithras mondschatten","cave mushrooms","cliffspring falls","dunkelküste","todeskappe","schorfstängling"},ang={["profession:Herbalism"]="Diese unterirdischen Stängel sind kein häufig gehandeltes Kraut. Sie geben Einblick darin, wie ungewöhnliche klimatische Bedingungen in Höhlen und vordringende Schatten die dortigen Pilze beeinflussen.",["race:NightElf"]="Als Nachtelf beachtet Ihr die Warnung des Hains der Uralten und nähert Euch diesen Höhlenpilzen mit Vorsicht. Nahe den Cliffspring Falls schwärt eine verderbende Präsenz."},sec={{t="Ein seltenes Pilzexemplar",b="Hinter den Cliffspring Falls wachsen Schorfstänglinge in einer Höhle in den nordöstlichen Bergen von Dunkelküste. Die blassen Pilze gedeihen in ihren feuchten, abgeschiedenen Gängen, fern vom Waldbewuchs darüber. Nur wenige sammeln sie an einem so entlegenen Ort. Barithras Mondschatten in Auberdine schickt Kundschafter in die Dunkelheit, um die seltenen Stängel zu beschaffen."},{t="Ein Schatten in den Fällen",b="Der Hain der Uralten warnte die einheimischen Nachtelfen davor, die Höhle zu betreten, in der Schorfstänglinge wachsen. Seine Baumgeister spürten, wie ein dunkles, wachsendes Übel in den Cliffspring Falls Fuß fasste. Alchemisten schätzen die Stängel ebenso wie seltene Todeskappen für experimentelle Tränke. Wer sie sucht, könnte auf die Bosheit stoßen, die sich unter den Bergen sammelt."}},faq={{q="Wo wachsen Schorfstänglinge?",a="Schorfstänglinge wachsen in einer feuchten Höhle hinter den Cliffspring Falls, in den nordöstlichen Bergen von Dunkelküste.",al={"schorfstängling fundort","wo sind schorfstänglinge","schorfstängling höhle"}},{q="Wer sucht Schorfstänglinge?",a="Barithras Mondschatten in Auberdine sucht Schorfstänglinge und eine Todeskappe, um einen speziellen Trank zu brauen.",al={"wer verwendet schorfstänglinge","barithras mondschatten pilze","wer braucht schorfstänglinge"}},{q="Warum hat Barithras Mondschatten die Stängel nicht selbst gesammelt?",a="Der Hain der Uralten warnte Barithras davor, sich dorthin zu begeben, nachdem seine Geister ein gefährliches neues Übel in der Höhle hinter dem Wasserfall Zuflucht suchen spürten.",al={"warum holt er sie nicht selbst","barithras warnung","cliffspring höhle warnung"}},{q="Was wächst noch neben Schorfstänglingen?",a="In der Höhle wächst auch die tödliche Todeskappe, ein weiteres seltenes Exemplar, das Barithras für seine alchemistischen Forschungen benötigt.",al={"andere pilze in der höhle","todeskappe und schorfstängling","cliffspring pilze"}}},fx={f5b84e96={q="Was ist ein Schorfstängling?",a="Ein Schorfstängling ist eine seltene Pilzart, die in der schattigen Höhle hinter Cliffspring Falls in der Dunkelküste heimisch ist. Während unterirdische Pilze im nördlichen Kalimdor weit verbreitet sind, gedeiht diese spezielle Sorte in feuchten, dunklen Grotten, die finstere Energien beherbergen.",al={"was ist schorfstängling","schorfstängling info","schorfstängling pilz"}},["053fa90e"]={q="Warum möchte jemand Schorfstänglinge haben?",a="Barithras Mondschatten in Auberdine sucht Schorfstänglinge als lebenswichtige Zutat zum Brauen spezieller Tränke. Da diese wirkungsvollen Pilze nur in der abgelegenen Höhle nahe Cliffspring Falls wachsen, müssen sich Kräuterkundler und Alchemisten darauf verlassen, dass abenteuerlustige Reisende sie ernten.",al={"warum schorfstängling sammeln","schorfstängling verwendung","wofür sind schorfstänglinge"}}},fp="12,91,22.313.0,21.337.1,28.101.0,24.98.0,58.141.0,40.122.0"}
P.entries["item:scale-of-old-murk-eye"] = {n="Schuppe von Trübauge dem Alten",s="An Westfalls Küste sucht Kapitän Grausohn einen Beweis, dass Trübauge der Alte tot ist. Der Geist spukt im Leuchtturm von Westfall, wo die Angriffe des Murlocs das Leuchtfeuer erlöschen ließen.",h="An Westfalls Küste sucht Kapitän Grausohn einen Beweis, dass Trübauge der Alte tot ist.",kw={"kapitän grausohn","bedrohung der küste","murloc","trübauge der alte","schuppe von trübauge dem alten","westfall","der leuchtturm von westfall"},ang={["faction:Alliance"]="Als Seemann der Allianz auf dem großen Meer in Richtung Sturmwind könnt Ihr helfen, die Angriffe von Trübauge dem Alten zu beenden, damit Westfalls Leuchtfeuer brennt und Schiffe nicht an den Felsen zerschellen."},sec={{t="Trophäe einer Küstenplage",b="Trübauge der Alte machte Westfalls Küste zu einem Ort des Gemetzels. Kapitän Grausohn, der an den Leuchtturm von Westfall gebundene Geist, berichtet, dass der gerissene Murloc willensschwächere Murlocs um sich scharte, um die Küste zu überfallen. Trübauge vertrieb die Familie des Wärters, sodass das Leuchtfeuer dunkel blieb, als Grausohns Schiff an den Felsen zerschellte.\n\nAls die Familie zurückkehrte, um die Flamme wieder zu entzünden, griff Trübauge erneut an und schlachtete sie ab. Grausohn verlangt eine Schuppe der Kreatur als Beweis dafür, dass die Küste von ihrem wildesten Raubtier befreit ist."}},faq={{q="Wofür wird die Schuppe von Trübauge dem Alten verwendet?",a="Kapitän Grausohn braucht die Schuppe als Beweis dafür, dass Trübauge der Alte tot ist. Der Geist spukt im Leuchtturm von Westfall und sinnt auf Rache, weil Trübauge das Leuchtfeuer erlöschen ließ, als Grausohns Schiff zerschellte, und anschließend die Familie des Leuchtturmwärters abschlachtete.",al={"wer will die schuppe","trübauge schuppe abgeben","schuppe von trübauge dem alten verwendung"}},{q="Wer ist Trübauge der Alte?",a="Trübauge der Alte ist ein grausamer, gerissener Murlocanführer, der an Westfalls Sandstränden umherstreift. Er kann seine Artgenossen organisieren und zu tödlichen, koordinierten Überfällen auf Außenposten an der Küste zwingen.",al={"wer ist trübauge","trübauge hintergrundgeschichte","trübauge der alte"}},{q="Warum griff Trübauge der Alte den Leuchtturm an?",a="Trübauge der Alte überfiel den Leuchtturm zunächst, um den Wärter und seine Familie zu vertreiben, wodurch die Küste in Dunkelheit versank. Als sie zurückkehrten, um die Flamme wieder zu entzünden, scharte er seine Artgenossen zu einem weiteren Angriff um sich und ermordete die ganze Familie. Schiffe konnten die gefährlichen Untiefen an der Küste nicht mehr erkennen.",al={"warum leuchtturm angreifen","überfall auf den leuchtturm","trübauge leuchtturm"}}},fx={["6e72b95e"]={q="Was ist die Schuppe von Trübauge dem Alten?",a="Es ist eine zähe, charakteristische Schuppe, die direkt aus der Haut von Trübauge dem Alten stammt, dem berüchtigten Murlocanführer, der die Küste von Westfall terrorisiert. Sie bei Euch zu tragen dient als unwiderlegbarer Beweis dafür, dass der tödliche Küstenplünderer endlich erschlagen wurde.",al={"was ist schuppe von trübauge dem alten","schuppe von trübauge dem alten gegenstand","trübauge schuppe"}},["383f15e9"]={q="Woher stammt die Schuppe von Trübauge dem Alten?",a="Die Schuppe stammt aus der natürlichen Haut von Trübauge dem Alten, einem ungewöhnlich gerissenen und bösartigen Murloc, der an der Küste von Westfall umherstreift. Sie wurde nicht von sterblichen Händen geschmiedet oder gefertigt, sondern nach dem Sieg im Kampf aus seinem Kadaver entnommen.",al={"ursprung der schuppe von trübauge dem alten","wo bekommt man schuppe von trübauge dem alten","wer hat schuppe von trübauge dem alten hergestellt"}},e7059369={q="Warum will Kapitän Grausohn die Schuppe von Trübauge dem Alten?",a="Kapitän Grausohn, der Geist eines Seekapitäns, der am Leuchtturm von Westfall weilt, sucht Rache und Erlösung. Trübauge der Alte verscheuchte die Familie des Leuchtturmwärters, sodass das Leuchtfeuer in jener Nacht dunkel blieb, als Grausohns Schiff an den Felsen zerschellte; und als die Familie zurückkehrte, überfiel er sie erneut und schlachtete sie ab. Grausohn fordert die Schuppe als unbestreitbaren Beweis dafür, dass die Bestie tot und die Küste sicherer ist.",al={"warum will grausohn die schuppe","warum wird die schuppe von trübauge dem alten gesucht","wer will die schuppe von trübauge dem alten"}}},fp="21,165,27.481.0,43.240.0,20.178.0,43.277.0"}
P.entries["item:scarlet-armband"] = {n="Scharlachrote Armbinde",s="In Todesend kennzeichnen Scharlachrote Armbinden die Eiferer, die ins Gebiet der Verlassenen vordringen. Exekutor Arren sammelt sie als Beweis dafür, dass die frisch Auferstandenen zurückgeschlagen haben.",h="In Todesend kennzeichnen Scharlachrote Armbinden die Eiferer, die ins Gebiet der Verlassenen vordringen.",kw={"todesend","exekutor arren","scharlachrote armbinde","scarlet convert","scharlachroter kreuzzug","scharlachroter initiand","tirisfal"},ang={["race:Undead"]="Als frisch auferstandener Verlassener begegnet Ihr beim Sammeln Scharlachroter Armbinden dem Hass der lebenden Welt von Angesicht zu Angesicht. Euer Überleben hängt davon ab, Euch gegen den Kreuzzug zu verteidigen."},sec={{t="Ein Zeichen des Fanatismus",b="Scharlachrote Armbinden kennzeichnen die Anhänger des Scharlachroten Kreuzzugs, von Initianden bis zu frischen Konvertiten. Ihre roten Abzeichen warnen die frisch auferstandenen Verlassenen in Todesend, dass ganz in der Nähe Gefahr lauert. Die Kreuzfahrer unterscheiden nicht zwischen den willenlosen Dienern der Geißel und den Untertanen der Dunklen Fürstin, die einen freien Willen besitzen. Für sie muss jede wandelnde Leiche brennen.\n\nExekutor Arren sammelt die Armbinden, um den Tod feindlicher Späher südöstlich von Todesend zu bestätigen. Er braucht einen Beweis dafür, dass die neuen Verlassenen ihre junge Nation verteidigen können."}},faq={{q="Warum will Exekutor Arren Scharlachrote Armbinden?",a="Exekutor Arren will Scharlachrote Armbinden als Beweis dafür, dass die Truppen im Lager des Scharlachroten Kreuzzugs südöstlich von Todesend dezimiert werden. Der Kreuzzug bedroht frisch erwachte Verlassene, und die Abzeichen belegen, dass seine vorgeschobenen Späher und Rekruten ausgeschaltet wurden.",al={"warum armbinden sammeln","arren armbindenquest","zweck der scharlachroten armbinde"}},{q="Wer trägt diese Armbinden?",a="Scharlachrote Initianden, Scarlet Converts und der Bote Meven Korgal tragen diese Armbinden. Sie sind niederrangige Mitglieder des Scharlachroten Kreuzzugs, die nahe Todesend stationiert sind.",al={"wer lässt scharlachrote armbinden fallen","wo armbinden finden"}},{q="Warum hasst der Scharlachrote Kreuzzug die Verlassenen?",a="Der Scharlachrote Kreuzzug hasst die Verlassenen, weil seine Eiferer keinen Unterschied zwischen der willenlosen Geißel des Lich Kings und den Verlassenen mit ihrem freien Willen sehen. Sie betrachten alle Untoten als Abscheulichkeiten, die ausgerottet werden müssen.",al={"warum greifen scharlachrote untote an","kreuzzug gegen verlassene","scharlachrote eiferer"}},{q="Wo liegt das Lager, in dem diese Armbinden zu finden sind?",a="Das Lager liegt unmittelbar südöstlich von Todesend in Tirisfal, in den Hügeln jenseits der Siedlungsgrenze.",al={"standort des scharlachroten lagers","todesend scharlachrotes lager","wo sind scarlet converts"}}},fx={["365b2391"]={q="Was ist eine Scharlachrote Armbinde?",a="Eine Scharlachrote Armbinde ist ein Stück purpurroter Stoff, der von Initiaten und Konvertiten des Scharlachroten Kreuzzugs getragen wird. Sie dient als Erkennungszeichen für den fanatischen menschlichen Orden und kennzeichnet ihre Träger als verpflichtete Kreuzfahrer, die sich der Ausrottung aller Untoten aus Lordaeron widmen, unabhängig davon, ob diese Untoten der Geißel dienen oder wie die Verlassenen über einen freien Willen verfügen.",al={"was ist scharlachrote armbinde","bedeutung scharlachrote armbinde","lore scharlachrote armbinde"}}},fp="15,158,21.513.0,46.244.0,25.169.0,47.204.0,52.110.0"}
P.entries["item:scarlet-crusade-documents"] = {n="Dokumente des Scharlachroten Kreuzzugs",s="Im Lager des Kreuzzugs nahe Todesend reisen die Dokumente des Scharlachroten Kreuzzugs in den Händen eines Boten durch Tirisfal. Ihre Befehle nennen Feldkommandanten und lenken deren Streitkräfte, wodurch die Verlassenen Informationen über scharlachrote Stellungen in ganz Tirisfal erhalten.",h="Im Lager des Kreuzzugs nahe Todesend reisen die Dokumente des Scharlachroten Kreuzzugs in den Händen eines...",kw={"brill","todesend","exekutor arren","exekutor zygand","meven korgal","dokumente des scharlachroten kreuzzugs","the red messenger","vital intelligence"},ang={["race:Undead"]="Als erwachter Verlassener tragt Ihr diese Papiere von den Prüfungen auf dem Friedhof von Todesend in den größeren Krieg, der von Brill aus geleitet wird."},sec={{t="Abgefangene Befehle",b="Meven Korgal trug die Dokumente aus dem Lager des Kreuzzugs südöstlich von Todesend bei sich. Die Befehle des Hochlords richten sich an die Hauptleute des Tirisfal-Regionalkommandos des Kreuzzugs. Hauptmann Perrine muss den südwestlichen Turm befestigen und Informationen über die Untoten in Brill sammeln.\n\nHauptmann Vachon muss die Truppenbewegungen der Untoten nahe dem nördlichen Turm niederschlagen, während Hauptmann Melrose die Grenzen der Pestländer überwacht. Die Befehle nennen scharlachrote Feldoffiziere, ihre Posten und ihre Aufgaben in ganz Tirisfal."},{t="Lieferung nach Brill",b="Exekutor Arren erkennt, dass die örtlichen Streitkräfte von Todesend diese Informationen nicht vollständig nutzen können. Die erbeuteten Dokumente werden zum Passierschein eines neu erwachten Verlassenen aus Todesend. Tragt sie nach Nordosten, am Coldhearth-Anwesen vorbei nach Brill, und übergebt sie Exekutor Zygand vor dem Rathaus von Brill. Mit den Befehlen in der Hand können die Heerführer der Verlassenen schnelle Angriffe gegen scharlachrote Kommandanten planen, die sich in ganz Tirisfal verschanzt haben."}},faq={{q="Wer trug diese Dokumente bei sich?",a="Meven Korgal, ein Kurier des Scharlachroten Kreuzzugs, trug die Dokumente im Lager des Kreuzzugs südöstlich von Todesend bei sich.",al={"wer hat sie fallen gelassen","scharlachroter bote","meven korgal"}},{q="Welche Informationen enthalten die Dokumente?",a="Die Befehle des Hochlords richten sich an das Tirisfal-Regionalkommando des Kreuzzugs. Hauptmann Perrine muss den südwestlichen Turm befestigen und Informationen über die Untoten in Brill sammeln. Hauptmann Vachon muss die Truppenbewegungen der Untoten nahe dem nördlichen Turm niederschlagen, und Hauptmann Melrose muss die Grenzen der Pestländer überwachen.",al={"was steht in den papieren","inhalt der dokumente"}},{q="Wer muss diese Dokumente sehen?",a="Ihr beschafft die Dokumente für Exekutor Arren in Todesend. Er vertraut sie Euch zur Übergabe an Exekutor Zygand an, der vor dem Rathaus von Brill die regionalen Militäreinsätze leitet.",al={"wohin damit","wem die dokumente geben"}},{q="Warum sind diese Dokumente für die Verlassenen wichtig?",a="Die Befehle verraten, wo scharlachrote Offiziere in ganz Tirisfal stationiert sind. Die Verlassenen können sie nutzen, um feindliche Anführer auszuschalten und die Moral der Eiferer in der Region zu zerschlagen.",al={"warum wollen die verlassenen sie","bedeutung der scharlachroten dokumente"}}},fx={b6ac443b={q="Was sind die Dokumente des Scharlachroten Kreuzzugs?",a="Es handelt sich um ein Bündel vertraulicher Militärpapiere, Schlachtberichte und Befehle, die von einem Kurier des Scharlachroten Kreuzzugs mitgeführt werden. Während das Bündel größtenteils aus gewöhnlichen Spähberichten und Propaganda über Scharmützel mit den Verlassenen besteht, enthält es auch detaillierte Einsatzbefehle für Kreuzfahrer-Offiziere, die in ganz Tirisfal stationiert sind.",al={"was sind die dokumente","infos dokumente des scharlachroten kreuzzugs","scharlachrote dokumente gegenstand"}},["5f5d9cee"]={q="Woher stammten die Dokumente des Scharlachroten Kreuzzugs?",a="Sie sind Direktiven, die auf Befehl des Hochlords des Kreuzzugs an die Hauptleute seines Tirisfal Regional Command erlassen wurden. Sie wurden einem Kurier namens Meven Korgal anvertraut, den die Verlassenen im Lager des Kreuzzugs südöstlich von Todesend fanden.",al={"wer schrieb die dokumente des scharlachroten kreuzzugs","quelle der scharlachroten dokumente","woher stammten die dokumente"}}},fp="25,243,18.495.0,17.427.0,33.115.0,41.295.0,33.180.0,50.172.0"}
P.entries["item:scarlet-insignia-ring"] = {n="Scharlachroter Insignienring",s="In Tirisfal kennzeichnen Scharlachrote Insignienringe die Mitglieder des Scharlachroten Kreuzzugs. In Brill sammeln die Verlassenen sie als Beweis dafür, dass ein weiterer Fanatiker gefallen ist.",h="In Tirisfal kennzeichnen Scharlachrote Insignienringe die Mitglieder des Scharlachroten Kreuzzugs.",kw={"brill","todeswache burgess","exekutor zygand","proof of demise","scharlachroter kreuzzug","scharlachroter insignienring","tirisfal","varimathras"},ang={["faction:Horde"]="Als Mitglied der Horde helft Ihr durch das Sammeln dieser Ringe, einen Brückenkopf in den Östlichen Königreichen zu sichern. Jeder einzelne schwächt die fanatischen Kreuzfahrer rund um Unterstadt.",["race:Undead"]="Als Verlassene erklärt Ihr, indem Ihr diese Ringe toten Kreuzfahrern entreißt, dass Tirisfal den Toten gehört. Zugleich erfüllt Ihr damit die Befehle der Dark Lady und von Varimathras."},sec={{t="Zeichen des Fanatismus",b="Jeder Kämpfer des Scharlachroten Kreuzzugs in Tirisfal trägt einen Insignienring. Neophyten und eifrige Mönche tragen sie, ebenso die Hauptleute Melrache und Perrine. Das feurige Siegel des Kreuzzugs ziert jeden Ring. Es kennzeichnet Mitglieder eines von Paranoia zerfressenen Ordens. Für Außenstehende kennzeichnen die Ringe den fanatischsten menschlichen Überrest Lordaerons."},{t="Kopfgeld des Schreckenslords",b="Todeswache Burgess in Brill sammelt die Ringe auf Befehl von Varimathras. Dieser ist Fürstin Sylvanas' Schreckenslord-Leutnant. Die Verlassenen betrachten den Scharlachroten Kreuzzug als eine Pest, die sich über ihre neu beanspruchte Heimat ausbreitet. Rekruten bringen Ringe nach Brill zurück, als Beweis für den Tod eines Kreuzfahrers und ihre Treue zum Thron von Unterstadt."}},faq={{q="Wer trägt diese Insignienringe?",a="Fast jedes in Tirisfal stationierte Mitglied des Scharlachroten Kreuzzugs trägt einen Insignienring. Neophyten, Missionare, Fanatiker und Vorhutkämpfer tragen sie, ebenso die Feldoffiziere Captain Perrine, Captain Melrache und Captain Vachon.",al={"wer lässt ringe fallen","welche kreuzfahrer haben ringe","ringbesitzer"}},{q="Warum will Todeswache Burgess Scharlachrote Insignienringe?",a="Todeswache Burgess sammelt die Ringe als Beweis dafür, dass scharlachrote Kreuzfahrer getötet werden. Er folgt den Befehlen von Varimathras und der Dark Lady. In Brill beurteilt die Garnison der Verlassenen anhand der Ringe die Treue der Rekruten und ihren Erfolg dabei, Menschen aus Lordaeron zu vertreiben.",al={"warum ringe sammeln","grund für proof of demise","burgess ringe"}},{q="Wofür steht das Insignium auf dem Ring?",a="Der Ring trägt das Zeichen des Scharlachroten Kreuzzugs und steht für dessen heiligen Krieg zur Auslöschung allen Untodes in Lordaeron. Kreuzfahrer tragen ihn mit glühendem Stolz als Zeichen ihrer Rechtschaffenheit. Ihre Besessenheit treibt sie dazu, jeden außerhalb ihres Ordens abzuschlachten.",al={"scharlachrotes symbol","was ist das insignium","ringemblem"}},{q="Welche Rolle spielt Varimathras beim Sammeln dieser Ringe?",a="Varimathras ist Sylvanas Windläufers oberster Leutnant in Unterstadt. Er beaufsichtigt die militärischen Einsätze gegen feindlich gesinnte lebende Menschen in Tirisfal. Für Befehlshaber der Verlassenen wie Exekutor Zygand und Todeswache Burgess hat der Scharlachrote Kreuzzug Vorrang.",al={"varimathras befehle","warum will varimathras ringe","beteiligung des schreckenslords"}}},fx={d4097e42={q="Was ist ein Scharlachroter Insignienring?",a="Ein Scharlachroter Insignienring ist ein Erkennungsband, das von Mitgliedern des Scharlachroten Kreuzzugs in ganz Tirisfal getragen wird. Mit dem Emblem des militanten Ordens versehen, markiert er die Treue des Trägers zu ihrem fanatischen Kreuzzug zur Ausrottung des Untodes. Für die Verlassenen, die ihre neuen Grenzen verteidigen, dienen diese Ringe als unbestreitbarer Beweis dafür, dass ein feindlicher Soldat oder Offizier eliminiert wurde.",al={"was ist scharlachroter insignienring","lore scharlachroter insignienring","was sind diese ringe"}}},fp="21,155,18.319.0,23.321.0,31.226.0,56.262.0,45.244.0,58.256.0"}
P.entries["item:scavenged-goods"] = {n="Aufgestöberte Waren",s="Rund um Todesend sammeln Verlassene Aufgestöberte Waren aus Ausrüstungskisten. Frisch auferstandene Untote sind auf weggeworfene Vorräte angewiesen, um die nachfolgenden Rekruten zu bewaffnen und einzukleiden.",h="Rund um Todesend sammeln Verlassene Aufgestöberte Waren aus Ausrüstungskisten.",kw={"todeswache saltain","todesend","ausrüstungskisten","vorräte der verlassenen","aufgestöberte waren","beutesuche in todesend"},ang={["race:Undead"]="Als Verlassener braucht Ihr weggeworfene Ausrüstung, um zu überleben. Die Lebenden bieten Euch weder Hilfe noch Gnade."},sec={{t="Auf sich allein gestellt",b="Neue Verlassene erheben sich auf dem Friedhof von Todesend und tragen kaum mehr als verrottende Grabtücher. Nahe gelegene Siedlungen und Königreiche bieten ihnen keine Hilfe, also müssen sie bergen, was sie brauchen. Todeswache Saltain sammelt weggeworfene Waffen, Werkzeuge und Kleidungsstücke aus Kisten im ganzen Dorf. Er gibt diese Vorräte an die nächsten Rekruten weiter, die sich erheben."}},faq={{q="Wofür werden aufgestöberte Waren verwendet?",a="Todeswache Saltain sammelt Aufgestöberte Waren, um frisch aus dem Friedhof auferstandene Verlassene auszurüsten. Ohne Vorräte aus nahe gelegenen Kisten würden sie Tirisfal unbewaffnet und unbekleidet betreten.",al={"aufgestöberte waren zweck","warum aufgestöberte waren sammeln","was macht saltain mit aufgestöberten waren"}},{q="Wo sind diese Waren zu finden?",a="Die Waren liegen in Ausrüstungskisten vor Hütten und rund um verfallene Gebäude in ganz Todesend.",al={"wo aufgestöberte waren finden","aufgestöberte waren fundort","wo sind ausrüstungskisten"}},{q="Wer bittet um die aufgestöberten Waren?",a="Todeswache Saltain, ein Offizier in Todesend, bittet frisch erwachte Verlassene, die Vorräte zu sammeln. Er lehrt sie, für sich selbst zu sorgen, und trifft Vorbereitungen für die nachfolgenden Rekruten.",al={"wer will aufgestöberte waren","todeswache saltain quest"}}},fx={f565021a={q="Was sind aufgestöberte Waren?",a="Dies sind verschiedene brauchbare Ausrüstungsgegenstände, Kleidung und Ausrüstung, die aus alten Kisten geborgen wurden, die in Todesend verstreut waren. Anstatt makelloser Waffen handelt es sich um weggeworfene Überreste aus dem früheren Leben der Stadt, die den neu erweckten Verlassenen noch immer einen praktischen Nutzen bieten können.",al={"was sind aufgestöberte waren","was bedeutet aufgestöberte waren"}},["0b2267aa"]={q="Woher stammen die aufgestöberten Waren?",a="Sie stammen aus Ausrüstungskisten, die inmitten der Ruinen von Todesend zurückgelassen wurden. Diese Vorräte gehörten einst den lebenden Bewohnern von Lordaeron, bevor das Königreich der Seuche zum Opfer fiel, und blieben in den Ruinen vergessen, bis die Verlassenen begannen, die Stadt als ihren Bereitstellungsraum zurückzuerobern.",al={"ursprung aufgestöberte waren","wer hat aufgestöberte waren hergestellt","woher kamen die aufgestöberten waren"}},["36f8df02"]={q="Warum will Todeswache Saltain aufgestöberte Waren?",a="Die Verlassenen erwecken kontinuierlich neu auferstandene Tote vom Friedhof, und diese frischen Rekruten kommen mit kaum etwas in die Welt. Todeswache Saltain sammelt diese geborgenen Gegenstände, damit die auftauchenden Untoten grundlegende Kleidung und Ausrüstung haben, anstatt unbewaffnet und schutzlos in den Dienst zu stolpern.",al={"warum will saltain aufgestöberte waren","warum aufgestöberte waren sammeln","warum werden aufgestöberte waren benötigt"}}},fp="15,161,22.332.0,34.183.0,28.96.0,33.170.0"}
P.entries["item:scavenger-paw"] = {n="Aasfressertatze",s="In Todesend stammt die Aasfressertatze von jungen, zerlumpten Wölfen auf den Hügeln. Neu erwachte Verlassene sammeln die Tatzen, damit örtliche Betreuer daraus einfache Schutzausrüstung nähen können.",h="In Todesend stammt die Aasfressertatze von jungen, zerlumpten Wölfen auf den Hügeln.",kw={"todesend","novize elreth","ragged scavenger","aasfressertatze","the damned","young scavenger"},ang={["profession:Tailoring"]="Als Schneider könnt Ihr sehen, wie Novize Elreth aus Wolfstatzen und Fledermausflügeln einfache Ausrüstung für die jungen Siedlungen der Verlassenen näht.",["race:Undead"]="Als neu erwachter Verlassener mit verwesendem Fleisch und wenig Ausrüstung könnt Ihr Teile örtlicher Raubtiere sammeln, um genügend Rüstung für Tirisfals Gefahren herzustellen."},sec={{t="Zusammengeflickte Rüstung in Todesend",b="Frisch zurückgekehrte Verlassene in Todesend haben wenig übrig. Die Geißel und der Scharlachrote Kreuzzug bedrängen Tirisfal, also findet jeder Fetzen Haut und jeder Knochen praktische Verwendung. Novize Elreth unterstützt Schattenpriester Sarvis, indem sie neben Fledermausflügeln auch Tatzen von Aasfresserwölfen sammelt.\n\nSie fertigt brauchbare Kleidung und Rüstung für Verlassene, die gerade ihren Gräbern entstiegen sind. Ihre Rückkehr lässt sie noch immer verwirrt zurück."}},faq={{q="Wofür werden Aasfressertatzen verwendet?",a="Novize Elreth sammelt Aasfressertatzen in Todesend und näht aus Tierteilen einfache Kleidung und Rüstung für frisch auferstandene Verlassene.",al={"aasfressertatze zweck","verwendung für tatzen","warum tatzen sammeln"}},{q="Wo findet Ihr sie?",a="Ihr findet sie bei Young Scavengers und Ragged Scavengers, wilden Wölfen, die durch die Wälder und Felder um Todesend streifen.",al={"tatzen fundort","wo tatzen bekommen","welche wölfe lassen tatzen fallen"}},{q="Wer bittet um diese Tatzen?",a="Novize Elreth bittet um die Tatzen. Sie unterstützt Schattenpriester Sarvis, indem sie verwundete Rekruten behandelt, Ausrüstung schneidert und jene ausstattet, die ins Feld geschickt werden.",al={"wer will aasfressertatzen","tatzen questgeber","novize elreth tatzen"}}},fx={["41bb56d4"]={q="Was ist eine Aasfressertatze?",a="Eine Aasfressertatze ist die abgetrennte Pfote eines Aasfresserwolfs, der durch die verwunschenen Wälder von Tirisfal um Todesend streift. Obwohl es sich scheinbar um düstere Trophäen handelt, dienen diese haltbaren Tierkadaverteile als Rohmaterial für die neu erweckten Verlassenen, die jeden Rest der einheimischen Tierwelt nutzen müssen, um lebensnotwendige Dinge herzustellen und zu überleben.",al={"identität aasfressertatze","was sind aasfressertatzen","was ist aasfressertatze"}},["366465d3"]={q="Woher stammt eine Aasfressertatze?",a="Diese Pfoten werden von den jungen und struppigen Aasfresserwölfen geerntet, die am Rande von Todesend umherstreifen. Diese wilden Bestien schleichen durch die verdorrten Lichtungen direkt hinter den Mauern des Dorfes und suchen die verseuchte Landschaft nach Aas ab, was sie zu einer leichten Beute für frische Rekruten der Verlassenen macht, die ihre Stärke beweisen wollen.",al={"quelle aasfressertatze","wo bekommt man aasfressertatze","aasfresserwolf pfoten"}},f83538b8={q="Warum will jemand Aasfressertatzen?",a="Novize Elreth in Todesend sammelt sie, um Rüstungen und robuste Kleidung für neu erweckte Soldaten der Verlassenen zu schneidern. Die Ressourcen für die neugeborenen freien Untoten sind verzweifelt knapp, und Elreth setzt Felle, Flügel und Pfoten zusammen, um Ausrüstung zu flicken, die Euch vor den gedankenlosen Untoten und Scharlachroten Kreuzfahrern schützen kann, die den Zufluchtsort bedrohen.",al={"warum aasfressertatzen sammeln","wer braucht aasfressertatzen","verwendung aasfressertatzen lore"}}},fp="13,178,27.408.0,33.132.0,23.117.0,24.158.0"}
P.entries["item:scorched-spider-fang"] = {n="Versengter Spinnenfangzahn",s="Im ganzen Sumpfland tragen Höhlenpirscher und Blutegelpirscher Versengte Spinnenfangzähne. Furen Langbart in Sturmwind braucht fünfzig davon, um Kettenrüstungen für Krieger der Allianz zu verstärken.",h="Im ganzen Sumpfland tragen Höhlenpirscher und Blutegelpirscher Versengte Spinnenfangzähne.",kw={"höhlenpirscher","fire hardened mail","furen langbart","blutegelpirscher","versengter spinnenfangzahn","sturmwind","sumpfland"},ang={["class:Warrior"]="Als Krieger stellt Ihr Euch Furen Langbarts Prüfung: fünfzig Fangzähne zu sammeln. Die Arbeit prüft Eure Ausdauer und liefert die Rohmaterialien für Eure Kettenrüstung.",["profession:Blacksmithing"]="Als Schmied könnt Ihr erkennen, wie Furen versengtes Chitin und Fangzähne in Kettengliedern verarbeitet und dabei seltenen zwergischen Rüstungstraditionen folgt, die über gewöhnliches Verhütten hinausgehen."},sec={{t="Die Formel eines Zwergenschmieds",b="In Sturmwind verstärkt der Schmied Furen Langbart Kettenrüstungen mit ungewöhnlichen Mitteln. Er braucht fünfzig versengte Fangzähne von den Riesenspinnen des Sumpflands. Ihre dichte, giftige Substanz ist in der Hitze hart geworden. Furen arbeitet sie beim Härten in die Kettenglieder ein."},{t="Pirscher des Sumpflands",b="Höhlenpirscher und Blutegelpirscher tragen die Fangzähne, die Furen braucht. Sie leben in den versunkenen Tälern und Bauten des Sumpflands, inmitten von Nässe und Fäulnis. Ihre Kieferzangen sind gehärtet und versengt. Um fünfzig zu sammeln, muss man sich in tiefe Höhlen wagen und den Spinnen in ihren Schwärmen stellen."}},faq={{q="Wofür werden Versengte Spinnenfangzähne verwendet?",a="Furen Langbart in Sturmwind braucht fünfzig Versengte Spinnenfangzähne, um widerstandsfähige Brustrüstungen für Krieger der Allianz zu schmieden. Für die Arbeit werden auch Bestandteile aus dem Steinkrallengebirge und dem Kral der Klingenhauer benötigt.",al={"was tun mit versengten spinnenfangzähnen","versengter spinnenfangzahn verwendung","wer braucht versengte spinnenfangzähne"}},{q="Wo kann ich Versengte Spinnenfangzähne finden?",a="Höhlenpirscher und Blutegelpirscher im Sumpfland tragen Versengte Spinnenfangzähne. Sucht in ihren feuchten Bauten, an Hängen und in Ausgrabungshöhlen.",al={"versengter spinnenfangzahn fundort","welche spinnen lassen versengte spinnenfangzähne fallen","wo versengte spinnenfangzähne farmen"}},{q="Warum braucht ein Schmied so viele Spinnenfangzähne, um eine Rüstung herzustellen?",a="Furen Langbart nutzt ungewöhnliche zwergische Methoden, um Kettenrüstungen zu verstärken. Er behandelt ihre Glieder mit gehärteten Fangzähnen, Phlogiston und Bestienhörnern.",al={"warum fünfzig fangzähne","warum braucht furen spinnenfangzähne"}},{q="Kann jeder Abenteurer diese Fangzähne sammeln und abgeben?",a="Jeder, der durch das Sumpfland reist, kann die Spinnen töten und ihre Kieferzangen an sich nehmen. Furen vergibt den Rüstungsauftrag nur an angehende Krieger, die sich eine feuergehärtete Kettenrüstung verdienen wollen.",al={"versengter spinnenfangzahn nur für krieger","wer kann versengte spinnenfangzähne abgeben"}}},fx={a7a99cbb={q="Was ist ein Versengter Spinnenfangzahn?",a="Ein Versengter Spinnenfangzahn ist ein gehärteter, hitzebehandelter giftiger Zahn, der von räuberischen Arachniden wie Höhlenpirschern und Blutegelpirschern geerntet wird, die im Sumpfland lauern. Ihr geschwärztes, sprödes Aussehen täuscht über eine außergewöhnliche Dichte hinweg, was sie bei erfahrenen Rüstungsschmieden begehrt macht, die nach seltenen Komponenten für fortgeschrittene Schmiedetechniken suchen.",al={"was ist versengter spinnenfangzahn","versengte spinnenfangzähne","versengter fangzahn"}},c6d8f632={q="Woher stammen Versengte Spinnenfangzähne?",a="Diese Fangzähne werden nicht von sterblichen Händen gefertigt; sie werden direkt von den riesigen Arachniden des Sumpflands geerntet, insbesondere von Blutegelpirschern und Höhlenpirschern. Die ständige Einwirkung der unterirdischen Elemente und die natürliche Alchemie ihres Gifts verleihen diesen Fangzähnen ihre geschwärzte, feuergehärtete Widerstandsfähigkeit.",al={"woher kommen versengte spinnenfangzähne","ursprung versengter spinnenfangzahn","quelle versengter spinnenfangzahn"}}},fp="20,165,25.253.0,24.267.0,40.185.0,39.138.0,62.133.0,51.175.0"}
P.entries["item:scroll-of-messaging"] = {n="Rolle der Nachrichtenübermittlung",s="Im Steinkrallengebirge bereitet Gaxim Rostknirsch eine Nachricht vor, die Sprengstoff aus der Ferne zünden soll.",h="Im Steinkrallengebirge bereitet Gaxim Rostknirsch eine Nachricht vor, die Sprengstoff aus der Ferne zünden...",kw={"sprengstoff","gaxim rostknirsch","ng-5","fernzünder","rolle der nachrichtenübermittlung","steinkrallengebirge","venture co"},ang={["faction:Alliance"]="Die Rolle hilft Agenten der Allianz, Maschinen der Venture Company zu sabotieren und die Zerstörung des Waldes im Steinkrallengebirge durch das Unternehmen zu behindern.",["profession:Engineering"]="Die Rolle zeigt, wie gnomische Ingenieurskunst arkane Magie nutzen kann, um ein Signal zu empfangen und Sprengstoff aus der Ferne zu zünden."},sec={{t="Eine explosive Nachricht",b="Beim Holzfällerbetrieb der Venture Company wird Gaxim Rostknirsch eine Nachricht in eine Explosion verwandeln. Er plant, die Übertragungsbeschwörung der Rolle mit instabilen NG-5-Ladungen zu verbinden. Die Explosion wird die Wachen fortlocken. Dann können Agenten vorbeischlüpfen und technische Baupläne sowie vertrauliche Korrespondenz stehlen."}},faq={{q="Wofür wird die Rolle der Nachrichtenübermittlung verwendet?",a="Gaxim Rostknirsch nutzt die Übertragungsmagie der Rolle der Nachrichtenübermittlung, um NG-5 aus der Ferne zu zünden. Gemeinsam ermöglichen sie ihm, eine Explosion aus der Ferne auszulösen.",al={"rolle der nachrichtenübermittlung verwendung","was bewirkt die rolle der nachrichtenübermittlung","warum will gaxim die rolle"}},{q="Wer erhält diese Rolle?",a="Gaxim Rostknirsch, ein Gnomeningenieur im Steinkrallengebirge, erhält die Rolle.",al={"wer erhält die rolle der nachrichtenübermittlung","wohin die rolle der nachrichtenübermittlung bringen","empfänger der rolle"}},{q="Warum braucht Gaxim einen ferngezündeten Sprengsatz?",a="Gaxim braucht ein großes Ablenkungsmanöver beim Betrieb der Venture Company. Das Chaos wird eine Infiltration, den Diebstahl technischer Baupläne und die Bergung von Dokumenten decken, die den Kahlschlag des Unternehmens im Wald aufhalten sollen.",al={"gaxim grund für sprengstoff","warum venture co sprengen","steinkrallengebirge ablenkung"}},{q="Was ist NG-5?",a="NG-5 ist eine chemische Sprengladung, die Gaxim Rostknirsch verwendet. Verbunden mit dem magischen Signal der Rolle bildet sie einen Fernzünder.",al={"ng-5","was ist ng-5","ng5 sprengstoff"}}},fx={["2071477e"]={q="Was ist die Rolle der Nachrichtenübermittlung?",a="Die Rolle der Nachrichtenübermittlung ist ein verzaubertes Pergament, das einen arkanen Zauber trägt. Gaxim Rostknirsch suchte danach als unkonventionellen Katalysator, um ihn mit seiner flüchtigen Sprengstoffmischung, NG-5, zu kombinieren, was es ihm ermöglichte, eine ferngesteuerte Ladung gegen die Operationen der Venture Company im Steinkrallengebirge zu bauen.",al={"was ist rolle der nachrichtenübermittlung","lore rolle der nachrichtenübermittlung","über rolle der nachrichtenübermittlung"}}},fp="19,98,18.314.0,41.152.0,25.84.0,39.220.0,13.130.0"}
P.entries["item:sea-creature-bones"] = {n="Meereskreaturknochen",s="An der Dunkelküste werden Meereskreaturknochen mit den Leibern gewaltiger Meereskreaturen angespült. Gwennyth Bly'Leggonde sammelt Proben für den Tempel des Mondes in Darnassus, wo die Ursache der Strandungen untersucht wird.",h="An der Dunkelküste werden Meereskreaturknochen mit den Leibern gewaltiger Meereskreaturen angespült.",kw={"auberdine","beached sea creature","dunkelküste","greymist-murlocs","gwennyth bly'leggonde","nebelrand","meereskreaturknochen","tempel des mondes"},ang={["class:Druid"]="Als Druide seht Ihr im unerklärlichen Tod uralter Meeresraubtiere ein Zeichen für eine tiefgreifende Störung in den Gewässern vor Kalimdor. Eine solche Störung beunruhigt jeden Hüter, der sich dem ökologischen Gleichgewicht verschrieben hat.",["race:NightElf"]="Als Nachtelf wisst Ihr, dass diese plötzlichen Massenstrandungen Euer Volk zutiefst beunruhigen, denn es verehrt die Harmonie der Natur. Es sieht in den Strandungen ein düsteres Omen, das die Aufmerksamkeit des Tempels des Mondes verlangt."},sec={{t="Ein Vorzeichen am Ufer",b="Gewaltige Meereskreaturen werfen sich nun in die Untiefen der Dunkelküste und verenden dort. Darunter sind riesige Drescher, die weitaus größer sind als jene, die in diesen Gewässern heimisch sind. Für die Nachtelfen ist dieser plötzliche Anstieg ein unheilvolles Vorzeichen. Gwennyth Bly'Leggonde wurde vom Tempel des Mondes nach Auberdine entsandt, um Knochen der gestrandeten Kreaturen zu sammeln. Hippogryphen bringen die Proben zur genauen Untersuchung nach Darnassus."},{t="Aas und Aasfresser",b="Die gewaltigen Kadaver locken örtliche Aasfresser an. Greymist-Murlocs versammeln sich, um sich von den toten und sterbenden Kreaturen zu ernähren, und verteidigen ihre Futterplätze erbittert. Sie sind zu schwach, um Bestien dieser Größe zu jagen. Deshalb müssen sich Ermittler und Abenteurer am Nebelrand durch ihre Rudel kämpfen, um Knochenfragmente für die Untersuchung zu bergen."}},faq={{q="Warum werden diese Kreaturen angespült?",a="Die genaue Ursache bleibt unbekannt. Gelegentliche Strandungen sind eine natürliche Gefahr, doch der plötzliche, drastische Anstieg beunruhigt die Priesterinnen von Elune, die ihn für unnatürlich halten und eine förmliche Untersuchung eingeleitet haben.",al={"warum stranden drescher","dunkelküste tote wale","warum stranden kreaturen an der dunkelküste"}},{q="Wer will diese Knochen?",a="Gwennyth Bly'Leggonde sammelt die Knochen in Auberdine für den Tempel des Mondes in Darnassus. Die Gelehrten und Priesterinnen dort hoffen herauszufinden, was das Meer in Unruhe versetzt.",al={"wer nimmt die knochen","wer gibt meereskreaturknochen ab","gwennyth dunkelküste"}},{q="Haben die Murlocs diese riesigen Bestien getötet?",a="Nein. Die Greymist-Murlocs sind zu schwach, um Meeresbestien dieser Größe zu erlegen. Sie versammeln sich in großer Zahl, um sich von den Kreaturen zu ernähren, nachdem diese angespült wurden.",al={"haben murlocs den drescher getötet","greymist-murlocs haben meeresungeheuer getötet"}},{q="Wo werden die Knochen geborgen?",a="Die Knochen stammen von gewaltigen Kadavern, die entlang der Dunkelküste gestrandet sind, besonders an den Sandstränden südlich von Auberdine und am Nebelrand.",al={"wo meereskreaturknochen finden","beached sea creature fundorte"}}},fx={["90a4db20"]={q="Was sind diese Meereskreaturknochen?",a="Sie sind skelettartige Überreste, die vom massiven Kadaver eines angespülten Meeresungeheuers – insbesondere eines ungewöhnlich großen Dreschers – stammen, das an der nebligen Küste der Dunkelküste gestrandet ist. Diese massiven Überreste, die von lokalen Greifenmurlocs geplündert wurden, dienen Forschern als wichtiger physischer Beweis, um zu verstehen, warum die Ungeheuer des Ozeans an Land verenden.",al={"was sind meereskreaturknochen","lore meereskreaturknochen","riesige knochen dunkelküste"}},cb40613a={q="Woher stammen die Meereskreaturknochen?",a="Diese Knochen stammen von einem kolossalen Drescher, der weitaus größer ist als jeder andere, der in den Gewässern der Dunkelküste zu erwarten wäre, und der sich unerklärlicherweise an die Strände von Nebelrand südlich von Auberdine geworfen hat. Anstatt von lokalen Raubtieren gefertigt oder erschlagen worden zu sein, gehören die Knochen auf natürliche Weise zu Tiefseekreaturen, die sich auf mysteriöse Weise an Land trieben, um zu sterben.",al={"woher kommen meereskreaturknochen","ursprung meereskreaturknochen","ursprung beached sea creature"}}},fp="18,223,22.411.0,22.319.0,39.208.0,22.166.0,40.143.0,35.129.0"}
P.entries["item:sea-turtle-remains"] = {n="Meeresschildkrötenüberreste",s="An der Dunkelküste sammeln sich Meeresschildkrötenüberreste am Ufer und unter den Wellen. Forscher in Auberdine untersuchen die wachsende Zahl toter Meeresschildkröten.",h="An der Dunkelküste sammeln sich Meeresschildkrötenüberreste am Ufer und unter den Wellen.",kw={"auberdine","beached sea turtle","dunkelküste","gwennyth bly'leggonde","meeresschildkrötenüberreste","teldrassil","tempel des mondes","washed ashore"},ang={["class:Druid"]="Der unnatürliche Tod großer Meereskreaturen deutet auf eine tiefere Verderbnis hin, die das Gleichgewicht der Natur entlang der Küste Kalimdors stört.",["race:NightElf"]="Die massenhafte Strandung von Meereslebewesen vor Eurer angestammten Küste ist ein unheilvolles Zeichen. Die vermutete Ursache liegt in den Gewässern rings um Teldrassil."},sec={{t="Ein beunruhigender Strand",b="Riesige Meereskreaturen werden an der Dunkelküste angespült, während andere nahe versunkenen Wracks unter Wasser liegen. In Auberdine sammelt Gwennyth Bly'Leggonde Knochenfragmente und Gewebe von ihren Körpern. Der Tempel des Mondes in Darnassus bittet dringend um diese Proben. Seine Gelehrten und Priesterinnen befürchten, dass die Kreaturen vor einer unnatürlichen Störung in den Gewässern um Teldrassil fliehen."},{t="Aasfresser im seichten Wasser",b="Die Bergung der Überreste ist gefährlich. Murlocstämme entlang der Küste versammeln sich um die riesigen Kadaver, nagen ihre Knochen kahl und nisten neben ihnen. Gelehrte brauchen frische Knochenfragmente und Gewebe, bevor die Aasfresser Beweise zerstören, die den tödlichen Wanderzug der Kreaturen erklären könnten."}},faq={{q="Wofür werden diese Überreste verwendet?",a="In Auberdine sammelt Gwennyth Bly'Leggonde Überreste für die Gelehrten und Priesterinnen im Tempel des Mondes in Darnassus. Sie wollen herausfinden, warum so viele Meereskreaturen an der Dunkelküste sterben.",al={"warum schildkrötenüberreste sammeln","verwendung von schildkrötenknochen","meeresschildkrötenquest dunkelküste"}},{q="Warum stranden Meeresschildkröten an der Dunkelküste?",a="Die Forscher haben die Ursache noch nicht gefunden, befürchten aber, dass Meereslebewesen vor einer beunruhigenden Präsenz in den Gewässern um Teldrassil fliehen. Diese Strandungen deuten darauf hin, dass Meereslebewesen weithin in Bedrängnis sind.",al={"warum sterben schildkröten","schildkrötenstrandungen dunkelküste","gestrandete meereskreaturen"}},{q="Wo findet man diese Kadaver?",a="Kadaver riesiger Meeresschildkröten liegen entlang der Dunkelküste. Einige ruhen im seichten Wasser nahe versunkenen Schiffen westlich von Auberdine, während andere an Stränden verstreut liegen, umgeben von Murloclagern.",al={"fundorte von schildkrötenüberresten","wo meeresschildkrötenskelett finden"}},{q="Wer untersucht diese Überreste?",a="In Auberdine sammelt Gwennyth Bly'Leggonde die Überreste und schickt ausführliche Berichte an die Sisterhood of Elune im Tempel des Mondes in Darnassus.",al={"wer will die überreste","gwennyth blyleggonde"}}},fx={dfe0d6c5={q="Was sind diese Meeresschildkrötenüberreste?",a="Diese Überreste sind Skelettproben, die von riesigen Meeresschildkröten stammen, die an der Küste der Dunkelküste angespült wurden oder in ihren flachen Gewässern starben. Obwohl sie von lokalen Raubtieren und Murlocs geplündert wurden, sind noch verwertbare Knochen und Gewebe vorhanden, die physische Hinweise auf die letzten Momente der Kreaturen bieten.",al={"was sind meeresschildkrötenüberreste","lore meeresschildkrötenüberreste","was bedeutet meeresschildkrötenüberreste"}},be90da46={q="Woher stammen die Meeresschildkrötenüberreste?",a="Sie werden direkt von massiven Skelettkadavern gesammelt, die an den Ufern und Küstengewässern der Dunkelküste liegen, einschließlich Exemplaren in der Nähe von Auberdine. Es handelt sich um natürliche Überreste von Meereskreaturen und nicht um gefertigte Objekte, die zurückgelassen wurden, wenn sterbende Schildkröten an Land schwimmen und verenden.",al={"woher kommen meeresschildkrötenüberreste","ursprung meeresschildkrötenüberreste","quelle meeresschildkrötenüberreste"}}},fp="18,149,19.379.0,26.287.0,32.199.0,53.195.0,32.181.0,30.150.0"}
P.entries["item:sealed-description-of-thredd-s-visitor"] = {n="Versiegelte Beschreibung von Thredds Besucher",s="Aufseher Thelwasser versiegelt einen Bericht über den Mann, der Bazil Thredd im Verlies von Sturmwind besucht. Der vertrauliche Bericht könnte Ermittlern helfen, jemandem auf die Spur zu kommen, der in Sturmwinds politischen und kriminellen Kreisen verkehrt.",h="Aufseher Thelwasser versiegelt einen Bericht über den Mann, der Bazil Thredd im Verlies von Sturmwind besucht.",kw={"baros alexston","bazil thredd","maelik","mathias shaw","versiegelte beschreibung","verlies","aufseher thelwasser"},ang={["class:Rogue"]="Als Schurke könnt Ihr erkennen, wie falsche Namen, gefälschte Papiere und Gefängnisbesuche Mathias Shaws Aufmerksamkeit erregten, als er das Aussehen des Mannes mit Geheimdienstinformationen des SI:7 abglich.",["faction:Alliance"]="Als Mitglied der Allianz könnt Ihr die Schwachstelle in Sturmwinds Sicherheit erkennen: Verschwörer können mit gefälschten Ausweisen die Tore des Verlieses passieren."},sec={{t="Ein geheimnisvoller Gönner",b="Jahrelang erhielt der Gefangene Bazil Thredd im Verlies keinen Besuch. Dann kam ein wortkarger Mann ein- bis zweimal pro Woche mit gültigen Papieren auf den Namen Maelik. Aufseher Thelwasser wurde aufmerksam und hielt das Aussehen des Mannes fest. Er versiegelte die Beschreibung, damit neugierige Augen sie nicht lesen konnten, bevor die zuständigen Ermittler handelten."},{t="Von Steinmetzen zu Spionen",b="Stadtarchitekt Baros Alexston konnte die Beschreibung niemandem eindeutig zuordnen. Er vermutete eine Verbindung des Besuchers zur Defias-Rebellion und schickte den Versiegelten Umschlag an Meister Mathias Shaw, den Leiter von Sturmwinds Geheimdienst SI:7. Shaw erkannte in dem Mann einen tödlichen Söldner, der unter anderem den Namen Marzon verwendet. Nun erledigt der Söldner die schmutzige Arbeit für Lord Gregor Lescovar."}},faq={{q="Wer hat diese Beschreibung verfasst?",a="Aufseher Thelwasser, oberster Aufseher des Verlieses von Sturmwind, verfasste und versiegelte das Dokument. Er wurde misstrauisch, als ein unbekannter Mann begann, den inhaftierten Anführer der Defias, Bazil Thredd, regelmäßig zu besuchen.",al={"wer hat es geschrieben","verfasser der beschreibung","wer verfasste die notiz"}},{q="Wer ist der Besucher, den das Schriftstück beschreibt?",a="Der Besucher trug Papiere auf den Namen Maelik bei sich. Aufseher Thelwasser hielt sein Aussehen fest, damit Ermittler ihn identifizieren konnten.",al={"wer besuchte thredd","wer ist maelik","identität des besuchers"}},{q="Warum traf sich der Besucher mit Bazil Thredd?",a="Nachdem er jahrelang keinen Besuch erhalten hatte, bekam Bazil Thredd regelmäßig Besuch. Die versiegelte Beschreibung wird untersucht, um die Absichten des Besuchers zu ergründen.",al={"warum thredd besuchen","absicht von thredds besucher"}},{q="Wohin muss dieses versiegelte Dokument gebracht werden?",a="Bringt das Dokument zuerst zu Stadtarchitekt Baros Alexston in Sturmwind. Nachdem Alexston die Beschreibung des Unbekannten geprüft hat, weist er Euch an, sie zu Meister Mathias Shaw im Hauptquartier des SI:7 in der Altstadt zu bringen.",al={"wohin bringen","wer will die beschreibung"}}},fx={["7193ccc9"]={q="Warum ist die Beschreibung von Bazil Thredds Besucher so wichtig?",a="Seit Jahren saß Bazil Thredd verlassen im Verlies ohne einen einzigen Besucher. Als eine mysteriöse Gestalt, die Papiere unter dem Namen 'Maelik' mit sich führte, ihn plötzlich wöchentlich zu besuchen begann, schöpfte Aufseher Thelwasser Verdacht auf eine tiefergehende Verschwörung. Die Entlarvung dieses Besuchers ist entscheidend, um aufzudecken, wer in Sturmwind aktiv mit der inhaftierten Führung der Bruderschaft der Defias koordiniert, was Ermittler dazu veranlasst, Mathias Shaws Geheimdienstnetzwerk aufzusuchen, um die zwielichtige Kontaktperson zu identifizieren.",al={"warum wird die beschreibung benötigt","versiegelte beschreibung thredd warum gesucht","warum ist die besucherbeschreibung wichtig"}}},fp="38,215,19.325.0,25.380.1,27.196.0,42.127.2,46.153.2,49.206.1"}
P.entries["item:sealed-envelope"] = {n="Versiegelter Umschlag",s="Im Steinkrallengebirge hat Fizziks Geheimnisse der Venture Company im Versiegelten Umschlag für Stotterspritter in Ratschet versiegelt.",h="Im Steinkrallengebirge hat Fizziks Geheimnisse der Venture Company im Versiegelten Umschlag für...",kw={"baupläne","fizziks","ratschet","versiegelter umschlag","stotterspritter","steinkrallengebirge","super reaper 6000","venture company"},ang={["faction:Horde"]="Als Mitglied der Horde helft Ihr den neutralen Goblins von Ratschet, die aggressiven, ausbeuterischen Holzfällerbetriebe der Venture Company zu untergraben, indem Ihr diese Papiere vom Steinkrallengebirge nach Süden bringt.",["profession:Engineering"]="Für einen Ingenieur enthält der Umschlag technische Zeichnungen des Super Reaper 6000, einer zerstörerischen und lukrativen Maschine, die Goblins erdacht haben."},sec={{t="Industriespionage",b="Aus den Holzfällerbetrieben der Venture Company im Steinkrallengebirge verstoßen, schmuggelte der Gobliningenieur Fizziks ihre Geheimnisse hinaus. Im Umschlag befinden sich Firmenhandbücher, Betriebsanweisungen und technische Pläne. Darunter sind Baupläne für den Super Reaper 6000, eine Maschine für den industriellen Kahlschlag."},{t="Lieferung nach Ratschet",b="Fizziks schickt die Dokumente nach Süden zu Stotterspritter, einem Ingenieur im neutralen Goblinhafen Ratschet. Die Rivalen des Steamwheedle Cartel hegen wenig Zuneigung oder Vertrauen für Fizziks. Doch die Entwürfe sind von eindeutigem technischem Wert. Sie offenbaren das mechanische Geschick der Venture Company und geben unabhängigen Ingenieuren die Möglichkeit, ihre fortschrittlichen Holzfällermethoden zu nutzen."}},faq={{q="Was befindet sich im Versiegelten Umschlag?",a="Der Versiegelte Umschlag enthält Handbücher der Venture Company, technische Dokumente und Baupläne für den Super Reaper 6000, eine Maschine zur Rodung. Fizziks stahl sie, als er die Firma überstürzt verließ.",al={"inhalt des umschlags","was ist im versiegelten umschlag","gegenstände im versiegelten umschlag"}},{q="Wer hat dieses Paket zusammengestellt?",a="Der Gobliningenieur Fizziks stellte den Umschlag zusammen, nachdem die Venture Company ihn aus ihrem Holzfällerbetrieb im Steinkrallengebirge verstoßen hatte.",al={"wer hat den umschlag zusammengestellt","wer gab den versiegelten umschlag","fizziks umschlag"}},{q="Wer soll ihn erhalten?",a="Der Umschlag ist für Stotterspritter bestimmt, einen Goblintüftler in Ratschet, der Hafenstadt im Brachland.",al={"wer bekommt den umschlag","wohin geht der umschlag","lieferung an stotterspritter"}},{q="Warum will Stotterspritter diese Dokumente haben?",a="Stotterspritter mag die Venture Company nicht, und die Dokumente bieten wertvolle Verbesserungen und Baupläne. Sie ermöglichen es firmenfremden Tüftlern, die leistungsstarken mechanischen Konstruktionen der Firma zu verstehen und zu übernehmen.",al={"warum will stotterspritter ihn","venture company technik ratschet"}}},fp="15,109,19.315.0,19.342.0,35.192.0,25.138.0,30.99.0,43.185.0"}
P.entries["item:sealed-note-to-elling"] = {n="Versiegelte Notiz an Elling",s="In Sturmwind schickt Jorgen eine versiegelte Depesche an Elling Trias, den Inhaber von Trias' Cheese. Die Nachricht des Fischers zieht Trias in eine diskrete Untersuchung über einen verschwundenen Diplomaten hinein.",h="In Sturmwind schickt Jorgen eine versiegelte Depesche an Elling Trias, den Inhaber von Trias' Cheese.",kw={"elling trias","jorgen","versiegelte notiz an elling","sturmwind","the missing diplomat","der handelsdistrikt","trias käse"},ang={["class:Rogue"]="Als Schurke, der mit Sturmwinds Schattennetzwerken vertraut ist, erkennt Ihr in Elling Trias womöglich mehr als einen Käsehändler. Diese diskrete Korrespondenz passt zur Arbeit jener Netzwerke.",["faction:Alliance"]="Als Mitglied der Allianz überbringt Ihr Jorgens Nachricht im Dienst der Krone. So helft Ihr, eine Untersuchung voranzutreiben, die für Sturmwinds politische Stabilität entscheidend ist."},sec={{t="Eine diskrete Übergabe",b="Jorgen gibt für die versiegelte Notiz in Sturmwind eine strikte Anweisung: Übergebt sie Elling Trias persönlich und bewahrt Stillschweigen. Es steht zu viel auf dem Spiel, um unbedacht zu reden. Trias betreibt einen Käseladen im Handelsdistrikt. Dort bringt Jorgens Nachricht die Untersuchung über das Verschwinden des Diplomaten an seine Theke."}},faq={{q="Was steht in der versiegelten Notiz?",a="Die Notiz bleibt versiegelt, bis sie Elling Trias erreicht. Sie enthält Jorgens Bericht und verweist den Kurier für weitere Nachforschungen zum Verschwinden des Diplomaten an Trias.",al={"inhalt der notiz","was steht in der notiz","brieftext"}},{q="Warum erhält ein Käsehändler geheime Informationen?",a="Elling Trias betreibt einen unscheinbaren Käseladen im Handelsdistrikt als Tarnung für die Öffentlichkeit. Hinter dieser Fassade verfügt er über ein weitreichendes geheimes Netz aus Augen und Ohren in der ganzen Stadt. Das macht ihn bei heiklen Ermittlungen wertvoll.",al={"warum elling trias","warum käseladen","ist trias ein spion"}},{q="Wer ist Jorgen?",a="Jorgen ist ein Fischer, der unten am Wasser im Tal der Helden in Sturmwind zu finden ist. Er hat eine gemeinsame Vergangenheit mit Elling Trias und Bischof DeLavey, der ihn für diskrete Angelegenheiten fernab neugieriger Blicke heranzieht.",al={"wer schrieb die notiz","jorgens geschichte","wachmann jorgen"}},{q="Worum geht es im Fall des vermissten Diplomaten?",a="Ein Diplomat aus Sturmwind wurde nach Theramore geschickt, um Jaina Prachtmeer zu treffen, kam aber nie an. Die königlichen Behörden gehen im Stillen jeder verdächtigen Spur nach, um Panik auf den Straßen zu vermeiden.",al={"geschichte des vermissten diplomaten","wer ist der diplomat","warum wird der diplomat vermisst"}}},fx={["76232759"]={q="Was ist die Versiegelte Notiz an Elling?",a="Es ist eine vertrauliche Nachricht, die Euch von Jorgen ausgehändigt wurde und speziell für die Ohren – und Augen – von Elling Trias bestimmt ist. Mit einem Wachssiegel versehen, um Geheimhaltung zu gewährleisten, enthält sie dringende Informationen bezüglich der Ermittlungen zum The Missing Diplomat und wurde Euch zur sicheren Überbringung durch Sturmwind anvertraut.",al={"was ist die versiegelte notiz an elling","gegenstand versiegelte notiz an elling","was ist jorgens notiz"}},["2cd529f3"]={q="Woher stammt die Versiegelte Notiz an Elling?",a="Die Notiz wurde von Jorgen geschrieben und versiegelt. Nachdem er die Spur bezüglich des vermissten Diplomaten des Königreichs befragt und ausgewertet hat, verfasst Jorgen diese diskrete Depesche und legt sie direkt in Eure Hände, damit Ihr sie zu Elling Trias bringt.",al={"wer schrieb die versiegelte notiz an elling","woher kommt die versiegelte notiz","wer gab die versiegelte notiz an elling"}},["92e95eae"]={q="Warum wird die Versiegelte Notiz an Elling benötigt?",a="Das Verschwinden des Diplomaten ist eine Angelegenheit von äußerster Heikligkeit und Staatssicherheit. Jorgen kann auf der Straße nicht offen sprechen, daher dient die Notiz als stille Einführung und Informationsübergabe an Elling Trias, um Trias in die Ermittlungen einzubeziehen, ohne neugierige Blicke zu erregen.",al={"warum die versiegelte notiz überbringen","warum braucht elling trias die notiz","warum ist jorgens notiz wichtig"}}},fp="21,176,16.297.0,39.169.0,53.235.0,14.197.0,40.177.0"}
P.entries["item:sealed-note-to-watcher-backus"] = {n="Versiegelte Notiz an Behüter Backus",s="In Sturmwind schickt Elling Trias eine versiegelte Notiz an Behüter Backus im Dämmerwald. Er bittet den Wachmann der Nachtwache, über Aktivitäten der Defias nahe Dunkelhain zu berichten.",h="In Sturmwind schickt Elling Trias eine versiegelte Notiz an Behüter Backus im Dämmerwald.",kw={"dunkelhain","dämmerwald","elling trias","night watch","versiegelte notiz","the missing diplomat","behüter backus"},ang={["class:Rogue"]="Als Schurke könnt Ihr sehen, wie Trias sich für örtliche Informationen auf einen gewöhnlichen Wachmann verlässt. So kann er weit jenseits der Stadtmauern Informationen sammeln.",["faction:Alliance"]="Als Mitglied der Allianz könnt Ihr sehen, wie persönliche Bindungen und informelle Informationswege helfen, die zerrütteten Gebiete der Fraktion zusammenzuhalten, wenn offizielle Wege versagen."},sec={{t="Ein Wort an die Wache",b="Elling Trias erklärt sich bereit, seine Kontakte zu nutzen, um bei der Suche nach dem vermissten Diplomaten zu helfen. Er versiegelt eine Notiz für Behüter Backus, einen im Dämmerwald stationierten Wachmann der Nachtwache.\n\nTrias schickt einen Reisenden südwärts durch den Wald, um sie persönlich zu überbringen. Er hofft, dass Backus über alle Defias berichtet, die nahe Dunkelhain gesichtet werden."},{t="Trias' weitreichender Blick",b="Elling Trias verkauft Käse im Handelsdistrikt von Sturmwind und pflegt Kontakte über die Stadt hinaus. Seine Notiz erreicht Behüter Backus, einen Wachmann der wachsamen Nachtwache von Dunkelhain.\n\nDunkelhain wird von Untoten und wilden Bestien bedroht. Backus begrüßt Trias' Nachricht, ein Zeichen dafür, dass Trias sich über Sturmwind hinaus Respekt verdient hat."}},faq={{q="Wer hat diese Notiz geschrieben?",a="Elling Trias hat die Notiz geschrieben. Ihm gehört Trias' Cheese im Handelsdistrikt von Sturmwind, und insgeheim arbeitet er als Spion und Informationshändler.",al={"wer schrieb die versiegelte notiz an behüter backus","verfasser der notiz","wer gibt die notiz"}},{q="Warum wird sie an Behüter Backus geschickt?",a="Behüter Backus dient in der Nachtwache von Dunkelhain und ist ein vertrauenswürdiger Kontakt von Elling Trias. Trias bittet ihn, örtliche Sichtungen oder Gerüchte über Aktivitäten der Bruderschaft der Defias im Dämmerwald zu melden.",al={"wer ist behüter backus","warum an backus schicken","welche aufgabe hat backus"}},{q="Wo ist Behüter Backus zu finden?",a="Behüter Backus patrouilliert auf der Straße unmittelbar nördlich von Dunkelhain im Dämmerwald. Er bewacht die Waldzugänge zur Stadt.",al={"wo ist backus","behüter backus standort","behüter backus finden"}},{q="Was geschieht nach der Übergabe der Notiz?",a="Backus erkennt Trias' Namen und vertraut seiner Bitte. Er legt seine übliche Vorsicht gegenüber Reisenden ab und erklärt sich bereit, verdächtigen Aktivitäten im Wald nachzugehen.",al={"was sagt backus","nach übergabe der notiz"}}},fx={["8647b8fc"]={q="Was ist die Versiegelte Notiz an Behüter Backus?",a="Es ist eine vertrauliche Nachricht, verfasst von Elling Trias, dem Meisterkäsehändler von Sturmwind, die für Behüter Backus im Dämmerwald bestimmt ist. Trias schickt sie mit Euch, um Backus' Hilfe beim Sammeln von Informationen über die Aktivitäten der lokalen Bruderschaft der Defias als Teil der laufenden Ermittlungen zum vermissten Diplomaten zu gewinnen.",al={"was ist die versiegelte notiz an behüter backus","zweck der versiegelten notiz an behüter backus","trias' notiz an backus"}}},fp="29,149,20.285.0,25.309.1,20.137.0,39.189.0,34.110.0,41.163.0"}
P.entries["item:searing-collar"] = {n="Senghalsband",s="In der Knochenhöhle in Durotar verbrennen Senghalsbänder die Kultisten der Burning Blade, die sie tragen. Die erhitzten Halsreife helfen ihnen, sich auf dämonische Macht einzustimmen.",h="In der Knochenhöhle in Durotar verbrennen Senghalsbänder die Kultisten der Burning Blade, die sie tragen.",kw={"burning blade","dämon","durotar","teufelsmagie","margoz","senghalsband","die knochenhöhle"},ang={["class:Warlock"]="Als Hexenmeister kennt Ihr Senghalsbänder vielleicht als primitive Leiter, die Teufelsverderbnis in sterbliches Fleisch leiten.",["race:Orc"]="Als Orc ist der Fund von Kultisten, die diese Halsbänder vor Durotars Toren verwenden, eine düstere Erinnerung daran, dass der Schatten dämonischer Knechtschaft noch immer fortbesteht."},sec={{t="Werkzeuge der Verderbnis",b="Die Burning Blade versammelt sich in der Knochenhöhle, gleich östlich von Orgrimmar, zu finsteren Riten. Kultisten, Neophyten und Schläger tragen Senghalsbänder um den Hals. Das Metall brandmarkt und versengt ihre Haut, während sie seine Hitze ertragen.\n\nMargoz, ein Einsiedler, untersucht die grausamen Vorrichtungen. Er vermutet, dass ihre sengende Hitze und ihre Verzauberungen die Träger auf dämonische Energien einstimmen. Welche Rolle spielen die Halsbänder bei der Verderbnis, die sich unter den Augen der Horde in der Gesellschaft der Orcs ausbreitet?"}},faq={{q="Was ist ein Senghalsband?",a="Kultisten der Burning Blade tragen bei Ritualen Senghalsbänder um den Hals. Das erhitzte Metall verbrennt ihr Fleisch und hilft ihnen, sich auf dämonische Macht einzustimmen.",al={"was sind senghalsbänder","senghalsband hintergrundgeschichte","was bewirkt das halsband"}},{q="Wer trägt diese Halsbänder?",a="Mitglieder der Burning Blade, die sich in der Knochenhöhle verbergen, tragen die Halsbänder. Zu ihnen gehören Kultisten, Fanatiker, Schläger, Lehrlinge und Neophyten.",al={"wer verwendet sie","wer lässt senghalsbänder fallen","halsbänder der burning blade"}},{q="Warum verbrennen die Kultisten ihr eigenes Fleisch?",a="Die Burning Blade verwendet das sengende Metall bei ihren Ritualen. Indem die Kultisten die Verbrennungen und die dämonische Verzauberung ertragen, stimmen sie Körper und Geist auf dämonische Macht ein.",al={"warum ihr fleisch verbrennen","warum ein senghalsband tragen","zweck des halsbands"}},{q="Wer will die Senghalsbänder untersuchen?",a="Margoz, ein Ermittler, der in Durotar lagert, sammelt Senghalsbänder, um ihre Verzauberungen zu untersuchen und den Einfluss der Burning Blade aufzudecken.",al={"wer braucht senghalsbänder","wer untersucht die halsbänder","margoz halsbänder"}}},fp="14,140,25.448.0,25.149.0,24.139.0,41.162.0,41.141.0"}
P.entries["item:searing-coral"] = {n="Sengkoralle",s="An der Küste des Sumpflands wird Sengkoralle unter Wasser aus lebender Iron Coral gewonnen. Tüftler und Schmiede schätzen ihr hitzebeständiges Mineral zur Verstärkung von Rüstungen.",h="An der Küste des Sumpflands wird Sengkoralle unter Wasser aus lebender Iron Coral gewonnen.",kw={"furen langbart","iron coral","eisenschmiede","klockmort spannerspan","hafen von menethil","sengkoralle","kriegerrüstung","sumpfland"},ang={["class:Warrior"]="Als Krieger beweist Ihr mit dem Sammeln von Sengkoralle Eure Hingabe gegenüber Eisenschmiedes Rüstungsschmiedemeistern. Sie schmieden Euch eine maßgefertigte Brustplatte für schwere Kämpfe an vorderster Front.",["profession:Blacksmithing"]="Als Schmied könnt Ihr sehen, wie gnomischer Erfindergeist und klassische zwergische Metallverarbeitung gemeinsam Meeresmineralien in gehärtete Rüstungsplatten verwandeln."},sec={{t="Ein seltener Küstenrohstoff",b="Sengkoralle wächst im kalten Meer südlich vom Hafen von Menethil. Lebende Iron Coral gedeiht im Salzwasser und liefert mineralreiches Material, das extremer Hitze standhält. Sammler müssen die verhärteten Wucherungen losbrechen, während wilde Murlocs und andere Wasserbestien in der Nähe umherstreifen."},{t="Verwendung beim Schmieden",b="Zwergenschmiede verarbeiten traditionell keine Sengkoralle. In Eisenschmiede folgen neugierige gnomische Handwerker wie Klockmort Spannerspan den Methoden des erfahrenen Rüstungsschmieds Furen Langbart. Sie verhütten die Koralle und hämmern sie in Metalllegierungen ein, um leichte, haltbare Rüstungen für aufstrebende Krieger herzustellen."}},faq={{q="Wo wächst Sengkoralle?",a="Sengkoralle wächst in Beständen von Iron Coral unter den flachen Küstengewässern südlich vom Hafen von Menethil im Sumpfland.",al={"sengkoralle fundort","wo sengkoralle finden","iron coral fundort"}},{q="Wer sucht Sengkoralle in Eisenschmiede?",a="Klockmort Spannerspan, ein gnomischer Konstrukteur in Eisenschmiedes Tinkertown, sucht Sengkoralle. Er experimentiert mit Schmiedemethoden, die er vom legendären zwergischen Rüstungsschmied Furen Langbart gelernt hat.",al={"wer verwendet sengkoralle","klockmort spannerspan koralle","furen langbart koralle"}},{q="Wie lässt sich Koralle zu Rüstung schmieden?",a="Sengkoralle besitzt eine ungewöhnlich dichte, hitzebeständige Struktur. In einer Schmiede verhüttet und in Metalllegierungen eingehämmert, verstärkt sie die Verbundplatten und sorgt für außergewöhnlich widerstandsfähige Schutzausrüstung.",al={"koralle schmieden","kann man koralle verhütten","sengkoralle metallurgie"}},{q="Ist es gefährlich, Sengkoralle zu sammeln?",a="Die Koralle selbst lässt sich gefahrlos sammeln, sobald sie gefunden ist. Um sie zu erreichen, muss man in den offenen Gewässern vor der Küste des Sumpflands schwimmen, wo wilde Murlocs und aggressive Wasserbestien umherstreifen.",al={"ist sengkoralle heiß","iron coral sammeln"}}},fx={["3e3d13aa"]={q="Was ist Sengkoralle?",a="Sengkoralle ist ein seltener, mineralreicher Meeresbewuchs, der von Iron Coral-Formationen unter den Wellen entlang der Küste des Sumpflands, südlich des Hafen von Menethil, geerntet wird. Obwohl es sich um ein ozeanisches Exemplar handelt, erlauben es seine dichten und eigentümlichen Eigenschaften, von geschickten Schmieden geschmolzen, gehämmert und wie Metall verarbeitet zu werden.",al={"was ist sengkoralle","informationen zu sengkoralle","lore zu sengkoralle"}},["1c0d8f00"]={q="Woher stammt Sengkoralle?",a="Sengkoralle ist ein natürlicher aquatischer Bewuchs und kein hergestelltes Artefakt. Sie wächst ausschließlich an einem bekannten Ort auf der Welt: inmitten der Eisenkorallenbänke, die entlang der Küstengewässer südlich des Hafen von Menethil im Sumpfland untergetaucht sind.",al={"ursprung von sengkoralle","woher stammt sengkoralle","wer hat sengkoralle hergestellt"}}},fp="13,170,23.267.0,23.290.0,30.115.0,37.187.0,35.198.0,38.167.0"}
P.entries["item:secure-crate"] = {n="Gesicherte Kiste",s="Im Brachland ist eine Gesicherte Kiste für Ratschet bestimmt. Die Tränke und alchemistischen Waren darin sollen über das Meer in die Östlichen Königreiche gelangen.",h="Im Brachland ist eine Gesicherte Kiste für Ratschet bestimmt.",kw={"brachland","schwarzmeerbucht","tränke","ratschet","reagenzien","gesicherte kiste","verschiffung","wharfmaster dizzywig"},ang={["faction:Horde"]="Als Reisender der Horde wisst Ihr, dass Ratschets neutraler Hafen Kalimdor und die Östlichen Königreiche durch die Schifffahrt der Goblins verbindet.",["profession:Herbalism"]="Als Kräuterkundiger wisst Ihr, dass Alchemisten und Kräuterkundige jenseits des Meeres auf die Handelsrouten des Grenzlands angewiesen sind, um Rohzutaten auszutauschen."},sec={{t="Die Fracht eines Kuriers",b="Kuriere, Karawanen und Goblinschiffe transportieren Handelswaren zwischen Kalimdor und den Östlichen Königreichen. Wenn eine Karawane im Brachland ihre Abfahrt verpasst, bringen Reisende empfindliche Fracht wie diese Gesicherte Kiste hinunter zur Küste. Darin liegen Tränke, alchemistische Waren und Reagenzien für Geschäftspartner jenseits des großen Meeres. Ihr Siegel schützt die Kiste auf den Pfaden des Brachlands und während der Seereise."},{t="Durch den Hafen von Ratschet",b="Die Landreise der Kiste endet an den Docks von Ratschet, wo Werftmeister Dizzywig die Verschiffung beaufsichtigt. Ratschet ist ein neutraler Hafen für Waren, die über das Meer transportiert werden, darunter Fracht für die Schwarzmeerbucht. Dizzywig führt für das Steamwheedle Cartel Buch und erfasst Pakete und Fracht, bevor er sie auf das nächste auslaufende Schiff verlädt. Ratschet verbindet die Alte Welt mit dem Grenzland."}},faq={{q="Was befindet sich in der Gesicherten Kiste?",a="Die Gesicherte Kiste enthält Tränke, alchemistische Reagenzien und andere Vorräte für Geschäftspartner in den Östlichen Königreichen.",al={"kisteninhalt","was ist in der kiste","gegenstände der gesicherten kiste"}},{q="Wohin wird die Kiste geschickt?",a="Bringt die Gesicherte Kiste zu Werftmeister Dizzywig an den Docks von Ratschet. Er wird sie auf ein Handelsschiff mit Kurs auf die Schwarzmeerbucht in der Alten Welt buchen.",al={"zielort der kiste","wohin geht die gesicherte kiste"}},{q="Warum wurde die Kiste einem Abenteurer statt einer Karawane anvertraut?",a="Der Absender konnte Ratschet nicht rechtzeitig erreichen, und die planmäßige Handelskarawane war bereits aufgebrochen. Ein angeheuerter Kurier muss die Kiste rechtzeitig zur Flut zu den Docks bringen.",al={"warum habe ich die kiste","karawane verpasst"}},{q="Wer nimmt die Kiste in Ratschet entgegen?",a="Werftmeister Dizzywig nimmt die Kiste an den Docks von Ratschet entgegen. Er trägt sie in sein Frachtbuch ein, bevor er sie auf das nächste Schiff verlädt, das mit der Flut ausläuft.",al={"wer bekommt die kiste","dizzywig kiste"}}},fx={e5dd21c1={q="Was ist die Gesicherte Kiste?",a="Die Gesicherte Kiste ist eine dicht gepackte Lieferung, die eine Auswahl an Tränken, Reagenzien und anderen wertvollen Vorräten enthält. Sie ist sicher verpackt, damit ihr empfindlicher Inhalt eine lange Reise per Karawane und Schiff über das Meer in die Östliche Königreiche übersteht.",al={"was ist die gesicherte kiste","lore zur gesicherten kiste","über die gesicherte kiste"}},["4df2d75b"]={q="Woher stammt die Gesicherte Kiste und wer hat sie hergestellt?",a="Die Kiste stammt aus dem Brachland, gepackt und versiegelt von einem Apotheker oder Gelehrten, der dringend seine alchemistischen Vorräte exportieren musste. Da er nach dem Verpassen der regulären Handelskarawane keine Zeit hatte, persönlich zur Küste zu reisen, bereitete er die Kiste so vor, dass sie von Hand direkt zum Hafen in Ratschet gebracht werden konnte.",al={"wer hat die gesicherte kiste hergestellt","woher stammt die gesicherte kiste","ursprung der gesicherten kiste"}},b7ad6ca4={q="Warum wird die Gesicherte Kiste gesucht?",a="Geschäftspartner in den Östliche Königreiche jenseits des Meeres warten auf diese essenziellen Reagenzien und Tränke. Werftmeister Dizzywig in Ratschet muss die Kiste an seinen Docks geliefert bekommen, damit er sie in sein Handelsbuch eintragen und an Bord des nächsten auslaufenden Schiffes, das zur Schwarzmeerbucht segelt, verstauen kann.",al={"warum wird die gesicherte kiste gesucht","wer braucht die gesicherte kiste","warum will dizzywig die gesicherte kiste"}}},fp="12,139,17.376.0,27.382.0,32.111.0,30.151.0,62.163.0,31.158.0"}
P.entries["item:senir-s-report"] = {n="Senirs Bericht",s="In Dun Moroghs kalten Ausläufern schickt Senir Weißbart seine Erkenntnisse über die Frostmähnentrolle an Senator Barin Redstone in Eisenschmiede.",h="In Dun Moroghs kalten Ausläufern schickt Senir Weißbart seine Erkenntnisse über die Frostmähnentrolle an...",kw={"barin redstone","frostmähnentrolle","eisenschmiede","magni bronzebart","senat","senir weißbart","senirs bericht","the reports"},ang={["faction:Alliance"]="Als Mitglied der Allianz helft Ihr mit der Überbringung von Senirs Bericht, Dun Morogh zu verteidigen, während Ihr Euch durch die heikle Politik von Eisenschmiedes Herrschern bewegt.",["race:Dwarf"]="Als Zwerg geratet Ihr durch die Überbringung von Senirs Bericht in Eisenschmiedes Zwiespalt zwischen den Erlassen von König Magni Bronzebart und den Machtansprüchen des Senats."},sec={{t="Eine königliche Weisung",b="Senirs Bericht sammelt die Beobachtungen der Gebirgsjäger, die die Frostmähnentrolle in Dun Moroghs zerklüfteten Bergen auskundschafteten. Er enthält auch den Bericht seines Bruders Grelin über das Coldridgetal. Grelin handelte dort mit der Billigung von König Magni Bronzebart.\n\nSenir schickt die Erkenntnisse an Senator Barin Redstone im High Seat von Eisenschmiede. Er rät den Boten, zu verschweigen, wie viel Hilfe von außen er für die Zusammenstellung benötigte."},{t="Spannungen im High Seat",b="Senir Weißbarts Bericht erreicht den königlichen Hof und löst einen Aufruhr aus. Senator Barin Redstone erzürnt sowohl die Bedrohung durch die Trolle als auch die auf dem Bericht vermerkte Vollmacht. Magni umging die parlamentarische Kontrolle, während Weißbart auf ungeprüfte königliche Befehle hin handelte.\n\nDieses Vorgehen verstärkt den Unmut unter den Senatoren, die Kontrolle über die Verfahren fordern. Die Spannungen zwischen Magnis entschlossener Herrschaft und den Machtansprüchen des Senats verschärfen sich."}},faq={{q="Was ist Senirs Bericht?",a="Senir Weißbarts Bericht hält seine Untersuchungen zu den Frostmähnentrollen in Dun Morogh fest. Er schickt ihn an den Senat der Zwerge in Eisenschmiede.",al={"senirs bericht","was ist dieser bericht","der bericht"}},{q="Wer soll den Bericht erhalten?",a="Senir Weißbart richtet den Bericht an Senator Barin Redstone im High Seat von Eisenschmiede, nahe dem Thron von König Magni Bronzebart.",al={"wer bekommt den bericht","wem den bericht geben","berichtsempfänger"}},{q="Warum wird Senator Redstone beim Lesen so wütend?",a="Senator Redstone ist wütend, weil Grelin Weißbarts beigefügter Bericht besagt, dass Grelin mit König Magnis Vollmacht handelte, ohne den Senat zu konsultieren. Redstone nimmt es der Krone übel, in Verteidigungsfragen ohne Zustimmung des Senats eigenmächtig zu handeln.",al={"warum ist barin wütend","warum ist der senator wütend","redstones reaktion"}},{q="Warum bittet Senir Euch, Eure Hilfe nicht zu erwähnen?",a="Senir Weißbart bittet Euch, Eure Hilfe zu verschweigen, damit seine Vorgesetzten glauben, er habe die gefährliche Erkundung der verschneiten Hügel allein bewältigt. Er will seinen Ruf als gewissenhafter, fähiger Gebirgsjäger schützen.",al={"warum schweigen","senirs geheimnis","senirs verdienst"}}},fx={["078e838e"]={q="Woher stammt Senirs Bericht und wer hat ihn erstellt?",a="Senir Weißbart verfasste diese Depesche selbst in Dun Morogh, nachdem er die lokalen Bedrohungen durch die Frostmähnentrolle ausgekundschaftet und Hilfe beim Umgang mit der Höhle der Frostmähnen gesichert hatte. Zusammen mit seinen eigenen Erkenntnissen enthält sie Grelins Bericht über Das Coldridgetal, den Grelin mit Genehmigung von König Magni Bronzebart verfasste, und trägt beides aus den verschneiten Grenzgebieten in die großen Hallen der Hauptstadt.",al={"wer schrieb senirs bericht","woher stammt senirs bericht","autor von senirs bericht"}},e0c0da53={q="Warum will jemand Senirs Bericht?",a="Senator Barin Redstone und der Senat von Eisenschmiede benötigen offizielle Feldeinschätzungen, um regionale Entwicklungen und militärische Aktionen in Dun Morogh zu verfolgen. Da diese spezielle Depesche jedoch König Magnis einseitige Autorität über lokale Manöver geltend macht, hat sie scharfes politisches Gewicht und informiert den Senat über Aktionen der Krone, von denen sie glauben, dass sie ihre Aufsicht umgehen.",al={"warum senirs bericht überbringen","warum braucht redstone senirs bericht","zweck von senirs bericht"}}},fp="14,133,17.399.0,25.430.1,23.143.0,38.131.0,56.253.1,50.210.0"}
P.entries["item:serena-s-head"] = {n="Serenas Kopf",s="In den Trockenen Hügeln verlangt Darsok Schnelldolch Serena Bloodfeathers Kopf als Beweis für ihren Tod. Er will ihn auf einem Versorgungswagen der Horde zur Schau stellen, um vor weiteren Harpyienüberfällen zu warnen.",h="In den Trockenen Hügeln verlangt Darsok Schnelldolch Serena Bloodfeathers Kopf als Beweis für ihren Tod.",kw={"das wegekreuz","darsok schnelldolch","die trockenen hügel","harpyie","rexxar","serena bloodfeather","serenas kopf","witchwing"},ang={["class:Rogue"]="Darsok Schnelldolch schätzt saubere, erbarmungslose Arbeit. Er lobt Söldner, die sich hinter feindliche Nistplätze schleichen und ein Ziel ohne Zögern hinrichten.",["faction:Horde"]="Karawanen der Horde verbinden Durotar mit Mulgore und entlegenen Außenposten. Serenas Kopf auf einem Versorgungswagen zur Schau zu stellen, verkündet die Vorherrschaft der Horde über die wilden Ödlande."},sec={{t="Eine Warnung am Weg",b="Serena Bloodfeather führte die Witchwing-Harpyien der Trockenen Hügel bei Angriffen auf den Handel durch das nördliche Brachland an. Ihre Angriffe auf die Nachschublinien der Horde wurden erbitterter, nachdem der Bestienmeister Rexxar ihre Schwester erschlagen hatte.\n\nDarsok Schnelldolch, ein Orc-Schurke, befahl, Serena zu jagen, um die Moral der Schar zu brechen. Er will ihren abgetrennten Kopf an einer aufbrechenden Karawane befestigen, wo Harpyien von den Felsen aus die Warnung sehen werden."}},faq={{q="Warum will Darsok Schnelldolch Serenas Kopf?",a="Darsok will einen Beweis dafür, dass Serena Bloodfeather tot ist. Er will ihren Kopf an einer Versorgungskarawane der Horde befestigen und hofft, damit die überlebenden Witchwing-Harpyien von Reisenden fernzuhalten.",al={"warum serenas kopf nehmen","darsok serena kopf","was macht darsok mit dem kopf"}},{q="Warum griff Serena Bloodfeather Karawanen der Horde an?",a="Serena Bloodfeather griff Karawanen der Horde an, um ihre Schwester zu rächen, die der Halb-Oger-Champion Rexxar erschlagen hatte. Sie überfiel Nachschublinien der Horde und Reisende im gesamten Brachland.",al={"warum griff serena karawanen an","serena bloodfeather motiv","harpyienangriffe brachland"}},{q="Woher stammt diese Trophäe?",a="Die Trophäe stammt von Serena Bloodfeather, der Matriarchin, die zwischen den Felsen der Trockenen Hügel im äußersten Nordwesten des Brachlands nistet.",al={"wo serenas kopf finden","serena bloodfeather aufenthaltsort","wie serenas kopf bekommen"}}},fx={["29e11954"]={q="Was ist Serenas Kopf?",a="Serenas Kopf ist der abgetrennte Kopf von Serena Bloodfeather, der rachsüchtigen Matriarchin des Witchwing-Harpyienschwarms im nördlichen Brachland. Ihn zu nehmen, markiert ein Ende ihrer Überfälle auf die Versorgungsrouten des Wegekreuzes und dient als unwiderlegbarer Beweis dafür, dass die Harpyienplage an ihrer Spitze getroffen wurde.",al={"was ist serenas kopf","kopf von serena bloodfeather","gegenstand serenas kopf"}}},fp="13,176,21.411.1,47.194.0,53.175.1,33.126.0"}
P.entries["item:serpentbloom"] = {n="Schlangenflaum",s="Tief in den Höhlen des Wehklagens hat Schlangenflaum mit seinen wirkmächtigen natürlichen Eigenschaften das rege Interesse der Königlichen Apothekervereinigung geweckt.",h="Tief in den Höhlen des Wehklagens hat Schlangenflaum mit seinen wirkmächtigen natürlichen Eigenschaften das...",kw={"apothecary zamah","brachland","kraut","königliche apothekervereinigung","schlangenflaum","donnerfels","die höhlen des wehklagens"},ang={["profession:Herbalism"]="Als Kräuterkundiger könnt Ihr mit Eurem geschulten Blick seltene Höhlenblüten finden, wo andere nur feuchten Stein sehen.",["race:Undead"]="Als Untoter helft Ihr durch das Sammeln von Schlangenflaum Apothekerin Zamah und der Königlichen Apothekervereinigung bei ihrer Suche nach pflanzlichen Ressourcen in fremden Ländern, um die Verlassenen zu stärken."},sec={{t="Eine seltene unterirdische Pflanze",b="Im Brachland gedeiht Schlangenflaum in den schattigen, feuchten Tunneln der Höhlen des Wehklagens. Ungezügelte Energien des Smaragdgrünen Traums haben das Ökosystem der Höhlen verzerrt. Giftschlangen nisten oft zwischen den Stängeln des Krauts.\n\nFeindselige Bestien und verderbte Druiden überrennen die Höhlen. Nur wenige, die sich hineinwagen, kehren mit brauchbaren Exemplaren zurück."},{t="Das Interesse der Apotheker",b="An den Teichen der Visionen unter Donnerfels sammelt Apothekerin Zamah Schlangenflaum für die Königliche Apothekervereinigung in Unterstadt. Die Verlassenen suchen in ganz Kalimdor nach virulenten, sonderbaren und chemisch wirkmächtigen Pflanzen, um die Forschung für die Dunkle Fürstin voranzutreiben.\n\nZamah glaubt, dass eine Ernte von Schlangenflaum in beträchtlichen Mengen wertvolle Durchbrüche in der Alchemie der Verlassenen ermöglichen könnte."}},faq={{q="Wo wächst Schlangenflaum?",a="Schlangenflaum wächst nur tief in den Höhlen des Wehklagens, einem labyrinthartigen Höhlennetz südwestlich vom Wegekreuz im Brachland. Er klammert sich in den dunklen, feuchten Winkeln der Höhle an den Boden.",al={"wo schlangenflaum finden","schlangenflaum fundort","höhlen des wehklagens kraut"}},{q="Warum will die Königliche Apothekervereinigung Schlangenflaum?",a="Apothekerin Zamah, eine in Donnerfels stationierte Agentin der Königlichen Apothekervereinigung, sucht Schlangenflaum für die Forschung. Die Verlassenen untersuchen in ganz Kalimdor ungewöhnliche und gefährliche Pflanzen, um neue chemische Mixturen zu entwickeln und die übergeordneten Ziele der Vereinigung im Dienste von Sylvanas Windläufer voranzutreiben.",al={"wer will schlangenflaum","apothecary zamah kraut","warum schlangenflaum sammeln"}},{q="Warum ist die Ernte von Schlangenflaum gefährlich?",a="In den Höhlen des Wehklagens wimmelt es von Raptoren, Krokilisken und verderbten Druiden. Schlangenflaum bietet oft Giftschlangen Unterschlupf, die zubeißen können, wenn das Kraut berührt wird.",al={"schlangenflaum gefahr","schlangenflaum schlange"}},{q="Können Kräuterkundige Schlangenflaum leichter finden?",a="Ja. Kräuterkundige haben von Natur aus ein Gespür dafür, Pflanzen zu entdecken, und können Schlangenflaumvorkommen in den schattigen Winkeln der Höhle aufspüren.",al={"schlangenflaum finden kräuterkunde","schlangenflaum aufspüren"}}},fx={bee22cd2={q="Was ist Schlangenflaum?",a="Schlangenflaum ist ein äußerst seltenes Exemplar der Flora, das in den dunkelsten Winkeln der Höhlen des Wehklagens im Brachland heimisch ist. Verwurzelt in den feuchten, unterirdischen Tiefen, zeichnet sich dieses ungewöhnliche Kraut durch seine schlangenartigen Eigenschaften aus – es zu stören lockt oft aggressive Schlangen hervor, die sich um seine Wurzeln eingenistet haben.",al={"was ist schlangenflaum","kraut schlangenflaum","informationen zu schlangenflaum"}}},fp="12,133,25.327.0,19.368.0,29.186.0,56.295.0,41.163.0,45.131.0"}
P.entries["item:sethir-s-journal"] = {n="Sethirs Tagebuch",s="Auf Teldrassil wurde Sethirs Tagebuch durch heimliches Vorgehen geborgen. Seine Seiten zeigen, dass die Verderbnis vom Festland Kalimdors den Weltbaum erreicht hat.",h="Auf Teldrassil wurde Sethirs Tagebuch durch heimliches Vorgehen geborgen.",kw={"dunkelküste","destiny calls","die lichtung des orakels","satyr","sethir the ancient","sethirs tagebuch","syurna","teldrassil"},ang={["class:Rogue"]="Als Schurke könnt Ihr durch heimliches Vorgehen und Taschendiebstahl entscheidende Informationen finden, wo Krieger und Diplomaten gescheitert sind.",["race:NightElf"]="Als Nachtelf steht Ihr vor Beweisen, dass Teldrassil nicht gegen die uralte dämonische Verderbnis gefeit ist, die sich auf dem Festland Kalimdors ausbreitet."},sec={{t="Ein Hinweis auf die Verderbnis",b="Sethirs Tagebuch wurde Sethir the Ancient heimlich entwendet, einem einzelgängerischen Satyr nahe der Lichtung des Orakels. Teldrassil wurde in der Hoffnung errichtet, die Unsterblichkeit der Elfen wiederherzustellen, doch Krankheit hat in seinen Ästen Wurzeln geschlagen.\n\nIn Darnassus vermutete Syurna, dass Sethir Antworten hatte. Späher, die versuchten, mit ihm zu verhandeln oder ihn anzugreifen, fanden den Tod, also wurde das Tagebuch aus seinen Taschen gestohlen. Seine Aufzeichnungen zeigen, dass die Seuche, die jenseits des Meeres die Wälder und Gewässer der Dunkelküste vergiftet, Teldrassil erreicht hat."}},faq={{q="Was ist Sethirs Tagebuch?",a="Sethirs Tagebuch wird von Sethir the Ancient getragen, einem feindseligen Satyr auf den äußeren Ästen nahe der Lichtung des Orakels. Seine Notizen beschreiben die Verderbnis, die sich in der Region ausbreitet.",al={"was ist sethirs tagebuch","sethirs tagebuch hintergrund","wem gehört sethirs tagebuch"}},{q="Wie erhält man das Tagebuch?",a="Späher, die versuchten, mit Sethir zu verhandeln oder gegen ihn zu kämpfen, scheiterten und fanden den Tod. Das Tagebuch muss ihm heimlich aus den Taschen gestohlen werden.",al={"wie erhält man sethirs tagebuch","wo erhält man sethirs tagebuch","sethir bestehlen"}},{q="Was offenbart das Tagebuch?",a="Die Schurkenlehrerin Syurna sagt, das Tagebuch beweise, dass die seltsame Krankheit, die die Wälder und Gewässer der Dunkelküste verheert, Teldrassil erreicht hat.",al={"was steht in sethirs tagebuch","was enthält sethirs tagebuch"}},{q="Wer ist Sethir the Ancient?",a="Sethir the Ancient ist ein einzelgängerischer Satyr auf einem abgelegenen Ast nahe dem Rand der Lichtung des Orakels. Er geht gewaltsam gegen Eindringlinge vor und besitzt Informationen über die Verderbnis, die sich im Weltbaum ausbreitet.",al={"wer ist sethir","sethir the ancient"}}},fx={["3d18c972"]={q="Woher stammt Sethirs Tagebuch und wer hat es erstellt?",a="Das Tagebuch gehört Sethir the Ancient, einem feindseligen Satyr, der auf einem hohen Ast am Rande der Lichtung des Orakels in Teldrassil lauert. Da er seine persönlichen Schriften und Aufzeichnungen unter seinen Habseligkeiten trug, behielt er das Tagebuch, bis Schurken in Darnassus versuchten, es ihm heimlich abzunehmen, um aufzudecken, welche Verderbnis sich über den Weltenbaum ausbreitet.",al={"wer schrieb sethirs tagebuch","ursprung von sethirs tagebuch","sethirs tagebuch ursprung"}}},fp="16,144,19.475.1,25.171.0,28.130.0,29.130.0,26.207.0"}
P.entries["item:sevren-s-orders"] = {n="Sevrens Befehle",s="In Brill schickt Magistrat Sevren einen bewährten Agenten der Verlassenen nach Süden, nach Unterstadt. Die Befehle weisen den Agenten zu Bethor Eismacht im Magieviertel.",h="In Brill schickt Magistrat Sevren einen bewährten Agenten der Verlassenen nach Süden, nach Unterstadt.",kw={"bethor eismacht","brill","magieviertel","magistrat sevren","abtrünniger lich","sevrens befehle","unterstadt"},ang={["class:Mage"]="Als Magier führt Euch die Überbringung der Befehle zu Bethor Eismacht, einem der führenden Zauberwirker im Reich der Verlassenen.",["race:Undead"]="Als Untoter führt Euch Sevrens Siegel vom örtlichen Dienst in Tirisfal zur Arbeit für die arkane Elite von Unterstadt."},sec={{t="Vorladung in die Hauptstadt",b="Agenten der Verlassenen, die sich in Tirisfal gegen die Geißel bewähren, werden nach Süden gerufen, während ihr Volk seine Herrschaft über Lordaeron festigt. Magistrat Sevren verfasst diese Befehle als Vorstellung und Beglaubigung für Bethor Eismacht, einen der führenden arkanen Meister der Dunklen Fürstin im Magieviertel. Sevren weiß nur, dass es bei dem Auftrag um die Kontaktaufnahme mit einem abtrünnigen Lich geht. Die hohen Magier von Unterstadt verleihen der Vorladung ihre volle Autorität."}},faq={{q="Wer hat diese Befehle verfasst?",a="Magistrat Sevren, der die Angelegenheiten der Verlassenen in Brill beaufsichtigt, hat die Befehle verfasst.",al={"verfasser von sevrens befehlen","wer ist sevren","wer erteilt sevrens befehle"}},{q="Wer soll diese Befehle erhalten?",a="Die Befehle sind an Bethor Eismacht gerichtet, einen hochrangigen Magier der Verlassenen im Magieviertel von Unterstadt.",al={"wer erhält die befehle","wohin sevrens befehle bringen","wer ist bethor eismacht"}},{q="Welcher Auftrag wird in den Befehlen erwähnt?",a="Die Befehle verlangen, einen abtrünnigen Lich anzuwerben, um den Verlassenen zu helfen. Die gefährliche Aufgabe fällt einem Agenten zu, der sich bereits gegen die Geißel bewährt hat.",al={"was ist der lich-auftrag","was will bethor","auftrag zum abtrünnigen lich"}},{q="Warum wurde ich ausgewählt, sie zu überbringen?",a="Bethor verlangte nach einem Agenten, der sich gegen die Geißel bewährt hat. Magistrat Sevren hielt Eure Leistungen in Tirisfal für ausreichend, um Bethors gefährliches Ersuchen zu erfüllen.",al={"warum ich","warum hat sevren mich ausgewählt"}}},fx={["59d8f724"]={q="Was sind Sevrens Befehle?",a="Sevrens Befehle ist eine offizielle Depesche, geschrieben von Magistrat Sevren von Brill. Sie fungiert als formeller Ausweis, der Euch als Agenten von bewiesenem Wert identifiziert, der effektiv gegen die Geißel gekämpft hat und bereit ist, eine heikle Aufgabe zu übernehmen.",al={"was sind sevrens befehle","gegenstand sevrens befehle","was ist dieses dokument"}},["680dc8a1"]={q="Warum will Bethor Eismacht Sevrens Befehle?",a="Bethor Eismacht, ein prominenter Magier im Magieviertel der Unterstadt, forderte, dass Sevren einen Agenten zur Verfügung stellt, der in der Lage ist, eine gefährliche Aufgabe mit einem abtrünnigen Lich zu bewältigen. Das Vorlegen dieser Befehle beweist, dass Ihr Sevrens ausgewählter Agent seid und dass Eure Unterbrechung des mächtigen Zauberers gerechtfertigt ist.",al={"warum sevrens befehle überbringen","warum will bethor die befehle","wer braucht sevrens befehle"}}},fp="15,150,22.460.0,23.76.0,40.107.0,44.139.0,33.157.0"}
P.entries["item:shadowhide-pendant"] = {n="Schattenfellanhänger",s="Im Rotkammgebirge kennzeichnen Schattenfellanhänger Gnolle, die Morganth dienen. Seenhain nimmt zehn als Beweis dafür an, dass sein Gesetz durchgesetzt wurde.",h="Im Rotkammgebirge kennzeichnen Schattenfellanhänger Gnolle, die Morganth dienen.",kw={"büttel conacher","gnoll","seenhain","lieutenant fangore","morganth","anhänger","rotkammgebirge","schattenfell","solomon's law"},ang={["class:Warrior"]="Als Krieger steht Ihr aggressiven und körperlich imposanten Schattenfellgnollen gegenüber. Ihre Reihen stellen jene auf die Probe, die die Straßen nach Seenhain verteidigen.",["faction:Alliance"]="Als treuer Abenteurer der Allianz werdet Ihr womöglich dazu aufgerufen, das Gesetz des Königreichs zu wahren. Grenzsiedlungen wie Seenhain erhalten wenig Hilfe von der Garnison von Sturmwind, daher verlassen sich die örtlichen Magistrate auf Euch."},sec={{t="Zeichen des Trotzes",b="Schattenfellanhänger hängen an den Kriegern, Schlägern und Zauberkundigen des Schattenfellclans. Tief in den Hügeln des Rotkammgebirges führt Lieutenant Fangore den Clan, der nun unter Morganths Einfluss steht. Morganth ist ein abtrünniger Wirker des Arkanen. Für die Bewohner von Seenhain kennzeichnen die groben Amulette eine organisierte Bedrohung, die im Auftrag eines Feindes der Krone Siedlungen heimsucht."},{t="Seenhains Gerechtigkeit",b="Magistrat Solomon wahrt das Gesetz von Sturmwind, das für die aktive Unterstützung eines bekannten Verbrechers des Reiches die Todesstrafe vorsieht. Königliche Verstärkung ist zu spärlich, daher verlässt sich Büttel Conacher im Rathaus von Seenhain auf Abenteurer, um den Frieden zu wahren. Zehn Schattenfellanhänger beweisen, dass Gnolle, die Morganths Befehlen gehorchten, der Grenzlandjustiz zugeführt wurden."}},faq={{q="Was ist ein Schattenfellanhänger?",a="Schattenfellanhänger werden von Mitgliedern des Schattenfellclans der Gnolle im Rotkammgebirge getragen. Der örtliche Magistrat nimmt sie als Beweis dafür an, dass eindringende Gnolle zur Verteidigung der Ortschaft getötet wurden.",al={"was sind schattenfellanhänger","schattenfellanhänger hintergrund","rotkammgebirge anhänger"}},{q="Warum will Büttel Conacher diese Anhänger?",a="Büttel Conacher sammelt die Anhänger als Beweis dafür, dass Solomon's Law durchgesetzt wurde. Der Schattenfellclan arbeitet mit dem abtrünnigen Magier Morganth zusammen, um die örtliche Bevölkerung zu terrorisieren, daher betrachtet die Stadt jeden zugehörigen Gnoll als Feind, dem die Todesstrafe droht.",al={"warum anhänger sammeln","büttel conacher kopfgeld","conacher quest"}},{q="Wer trägt diese Anhänger?",a="Gewöhnliche Wegelagerer, Schläger und tollwütige Gnolle tragen die Anhänger. Auch Rohh the Silent und Lieutenant Fangore tragen sie in der Wildnis des Rotkammgebirges.",al={"wer lässt anhänger fallen","welche gnolle haben anhänger","schattenfellanhänger herkunft"}},{q="Welche Beziehung besteht zwischen dem Schattenfellclan und Morganth?",a="Morganth ist ein abtrünniger Wirker des Arkanen in den östlichen Ausläufern des Gebirges. Mit finsteren Mächten zwingt er die Schattenfellgnolle unter seinen Willen und entsendet sie dann als Fußsoldaten, um Seenhain zu terrorisieren und seine Pläne durchzusetzen.",al={"gnolle und morganth","warum arbeiten gnolle mit morganth zusammen","schattenfell morganth"}}},fp="18,127,18.341.0,19.340.0,29.212.0,46.256.0,27.145.0,66.218.0"}
P.entries["item:shaman-voodoo-charm"] = {n="Voodooglücksbringer des Schamanen",s="Im Grabhügel von Ban'ethil nutzen Schamanen der Gnarlpine den Voodooglücksbringer des Schamanen. Seine Magie kann den Geist eines schlafenden Druiden vom Körper trennen.",h="Im Grabhügel von Ban'ethil nutzen Schamanen der Gnarlpine den Voodooglücksbringer des Schamanen.",kw={"grabhügel von ban'ethil","smaragdgrüner traum","furbolg","gnarlpine","oben zornklaue","voodooglücksbringer des schamanen","schlafender druide","teldrassil"},ang={["class:Druid"]="Als Druide seht Ihr in dem Glücksbringer eine entsetzliche Entweihung des heiligen Schlummers. Seine dunkle Magie sperrt den Träumenden im Smaragdgrünen Traum ein und macht den Körper zu einer Marionette.",["race:NightElf"]="Als Nachtelf wisst Ihr, dass die Glücksbringer im Grabhügel von Ban'ethil zeigen, wie sehr die Gnarlpine eine der heiligsten gemeinschaftlichen Ruhestätten der Kaldorei entweiht haben."},sec={{t="Eine entartete Magie",b="Auf Teldrassil ist der Stamm der Gnarlpine dem Wahnsinn und der Verderbnis verfallen. Im Grabhügel von Ban'ethil wirken seine Schamanen Magie, die über gewöhnliche Wildniszauberei hinausgeht. Ihre Glücksbringer reißen das Bewusstsein eines schlafenden Druiden aus dem Reich der Sterblichen und sperren es im Smaragdgrünen Traum ein. Die Furbolgs beleben dann den leeren Körper. Nachtelfenbeschützer werden zu geistlosen Wächtern, die jeden töten, der die Grabhügel betritt."},{t="Den Fluch entschlüsseln",b="Oben Zornklaue fiel dem Ritual zum Opfer. Sein Geist bleibt im Smaragdgrünen Traum gefangen, während sein belebter Körper die Tiefen der Grabhügel terrorisiert. Durch den Schleier hindurch bat Oben Abenteurer, die Schamanen der Gnarlpine zu töten und einen ihrer Glücksbringer zurückzubringen. Er hoffte, dessen abscheuliche Verzauberung zu untersuchen, das verdrehte Handwerk der Furbolgs zu verstehen und einen Weg zu finden, sein geraubtes Fleisch zu befreien."}},faq={{q="Wozu dient der Voodooglücksbringer des Schamanen?",a="Schamanen der Gnarlpine trennen mit dem Glücksbringer den Geist eines schlafenden Druiden vom Körper und sperren ihn im Smaragdgrünen Traum ein. Seine Magie belebt das leere Fleisch, damit es Eindringlinge angreift.",al={"voodooglücksbringer zweck","was bewirkt der glücksbringer","schamanenglücksbringer verwendung"}},{q="Wer trägt diese Glücksbringer?",a="Schamanen der Gnarlpine tragen diese Glücksbringer in den Tiefen des Grabhügels von Ban'ethil auf Teldrassil.",al={"wer lässt den glücksbringer fallen","wo voodooglücksbringer des schamanen finden","gnarlpine schamane glücksbringer"}},{q="Warum braucht Oben Zornklaue einen davon?",a="Oben Zornklaue ist im Smaragdgrünen Traum gefangen, während sein belebter Körper Amok läuft. Er muss die abscheuliche Aura und Magie des Glücksbringers untersuchen, um einen Weg zu finden, die Verzauberung der Furbolgs zu brechen.",al={"warum will oben ihn","oben zornklaue glücksbringer","der schlafende druide gegenstand"}},{q="Warum verfügen Furbolgs über Voodoomagie?",a="Die Verderbnis hat die Schamanen der Gnarlpine auf Teldrassil dazu getrieben, dunkle Magie zu praktizieren. Ihre Glücksbringer verströmen eine abscheuliche, unnatürliche Aura, die der traditionellen Verehrung der Furbolgs für Naturgeister und Elemente widerspricht.",al={"warum nutzen furbolgs voodoo","furbolg voodoo hintergrundgeschichte"}}},fx={["6bf5e1a6"]={q="Was ist der Voodooglücksbringer des Schamanen?",a="Es ist ein verzauberter Furbolg-Talisman, der von korrumpierten Gnarlpine-Schamanen im Grabhügel von Ban'ethil geführt wird. Der Glücksbringer strahlt eine abscheuliche magische Aura aus und macht sich dunkle Rituale zunutze, die den Geist eines schlafenden Nachtelf-Druiden von seiner physischen Form trennen können, wodurch der Geist hilflos zurückbleibt, während die Furbolgs den schlummernden Körper animieren und kontrollieren.",al={"was ist der voodooglücksbringer des schamanen","lore zum voodooglücksbringer","was sind diese glücksbringer"}}},fp="19,134,17.393.0,20.378.1,41.170.0,25.89.0,32.180.0,34.204.0"}
P.entries["item:shard-of-water"] = {n="Wassersplitter",s="An der Küste des Brachlands empfängt Islen Wasserdeuter den Wassersplitter von einem Schamanen, der sich der Verderbnis gestellt hat.",h="An der Küste des Brachlands empfängt Islen Wasserdeuter den Wassersplitter von einem Schamanen, der sich der...",kw={"brachland","call of water","islen wasserdeuter","wassersplitter","silberwald","wassertotem"},ang={["class:Shaman"]="Als Schamane vollendet Ihr mit dem Erhalt des Splitters Eure Einstimmung auf die Wassergeister und die lange Reise, auf der Ihr Euch Euer Wassertotem verdient."},sec={{t="Zeichen elementarer Reinheit",b="Um das Wasser zu meistern, muss ein Schamane Gleichgewicht, Leben und Bewahrung verstehen. Im Verlauf von Call of Water reist Ihr zu verderbten Quellen und überquert das Meer zum verseuchten Silberwald. Dort reinigt Ihr die verunreinigten Gewässer und erhaltet den Wassersplitter. Dann bringt Ihr das kristallene Zeichen zu Islen Wasserdeuter an der felsigen Küste des Brachlands zurück. Es beweist Eure Würdigkeit und liefert den letzten Schlüssel zur Erschaffung eines Wassertotems."}},faq={{q="Wofür wird der Wassersplitter verwendet?",a="Ihr bringt den Splitter als Beweis Eurer Prüfung zu Islen Wasserdeuter an der Ostküste des Brachlands. Überreicht ihn, um Eure Zwiesprache mit dem Wasser abzuschließen und ein Wassertotem zu verdienen.",al={"wassersplitter zweck","was bewirkt der wassersplitter","warum habe ich einen wassersplitter"}},{q="Wer benötigt diesen Gegenstand?",a="Islen Wasserdeuter verlangt den Splitter als Bestätigung dafür, dass Ihr verunreinigtes Wasser gereinigt habt. Sie ist eine Schamanin in einer Hütte südlich von Ratschet an der Händlerküste.",al={"wer will den wassersplitter","wo den wassersplitter abgeben","islen wasserdeuter splitter"}},{q="Warum fand die Prüfung so weit entfernt im Silberwald statt?",a="Wasser bedeutet Heilung und Bewahrung, während Verderbnis das Leben zum Stillstand bringt. Die verunreinigten Gewässer des Silberwalds prüfen, ob Ihr inmitten tiefen Verfalls die Harmonie der Elemente wiederherstellen könnt.",al={"silberwald wasserquest","warum silberwald","schamane silberwald"}}},fx={aaf07767={q="Was ist der Wassersplitter?",a="Der Wassersplitter ist ein heiliges Elementarfragment, das Schamanen gewährt wird, die sich den Prüfungen des Wassers unterziehen. Er dient als greifbarer Beweis dafür, dass Ihr das Ritual zur Reinigung korrupter Gewässer durchgeführt habt und die wahre Natur des Wassers als Lebensspender und -beschützer versteht.",al={"was ist der wassersplitter","gegenstand wassersplitter","was ist dieser splitter"}},["47314211"]={q="Woher stammt der Wassersplitter und wer hat ihn erstellt?",a="Ihr erhaltet den Splitter am Ende Eurer spirituellen Reise im Silberwald, verliehen nach Abschluss Eures Rituals zur Reinigung der korrupten Gewässer der Region. Er verkörpert die Elementarkraft reinen Wassers, die durch diesen Ritus erweckt wurde.",al={"woher bekommt man den wassersplitter","wer gibt den wassersplitter","ursprung des wassersplitters"}}},fp="14,108,25.403.0,36.165.0,23.141.0,48.163.0"}
P.entries["item:shaw-s-report"] = {n="Shaws Bericht",s="In Westfall überbringt Shaws Bericht Gryan Starkmantel Erkenntnisse des SI:7. Von Meister Mathias Shaw verfasst, berichtet er von der Stonemasons Guild, Edwin van Cleef und ihrem Groll gegen die Krone nach Sturmwinds Wiederaufbau.",h="In Westfall überbringt Shaws Bericht Gryan Starkmantel Erkenntnisse des SI:7.",kw={"defias","edwin van cleef","gryan starkmantel","mathias shaw","shaws bericht","si:7","stonemasons guild","westfall"},ang={["class:Rogue"]="Shaws Bericht zeigt, wie weit Meister Mathias Shaws Einfluss reicht. Er leitet den SI:7, Sturmwinds Spionagenetzwerk.",["faction:Alliance"]="Der Bericht legt Sturmwinds innere Fäulnis offen. Eine unbeglichene Schuld gegenüber den Baumeistern des Königreichs trug dazu bei, einen Aufstand auszulösen, der die landwirtschaftlichen Gebiete des Reiches bedroht."},sec={{t="Erkenntnisse über die Steinmetze",b="Shaws Bericht erreicht die Späherkuppe aus dem geheimen Hauptquartier des SI:7 in Sturmwind. Er liefert der Volksmiliz erstmals klare Erkenntnisse darüber, wer die Banditen anführt, die Westfall verheeren. Edwin van Cleef führte einst die Stonemasons Guild, deren Steinmetze Sturmwind nach seiner Zerstörung im Ersten Krieg wiederaufbauten.\n\nDie Krone und der Adel verweigerten ihnen eine gerechte Bezahlung, und Groll schlug Wurzeln. Shaws Erkenntnisse verbinden die vertriebenen Handwerker mit dem Aufstand, der nun die äußeren Gebiete des Königreichs erfasst."}},faq={{q="Was ist Shaws Bericht?",a="Shaws Bericht ist ein versiegeltes Geheimdienstdossier, das Meister Mathias Shaw für Gryan Starkmantel verfasst hat. Shaw leitet Sturmwinds Geheimdienst SI:7, und der Bericht enthält die Erkenntnisse der Krone über die Stonemasons Guild und Edwin van Cleefs Vergangenheit.",al={"shaws bericht","was schreibt shaw","shaws bericht inhalt"}},{q="Was enthüllt der Bericht über Edwin van Cleef?",a="Der Bericht nennt Edwin van Cleef als ehemaligen Anführer der Stonemasons Guild. Er leitete Sturmwinds Wiederaufbau nach dem Ersten Krieg, dann rebellierten er und seine Handwerker, nachdem die Herrscher des Königreichs ihnen eine angemessene Bezahlung verweigert hatten.",al={"van cleef im bericht","was steht über van cleef"}},{q="Warum braucht Gryan Starkmantel diesen Bericht?",a="Gryan Starkmantel braucht den Bericht, weil er die Volksmiliz gegen koordinierte Banditenüberfälle in Westfall anführt. Da ihm keine regulären Truppen des Königreichs helfen, verlässt er sich auf Mathias Shaws Erkenntnisse, um zu erfahren, wer die Gesetzlosen lenkt und was sie antreibt.",al={"warum bericht an gryan senden","warum braucht starkmantel den bericht"}},{q="Wie reagiert Starkmantel auf den Bericht?",a="Der Bericht beunruhigt Gryan Starkmantel zutiefst. Er erinnert sich an Edwin van Cleef als fleißigen, fähigen Handwerker und kann ohne weitere Beweise kaum glauben, dass ein so angesehener Baumeister zum Schurken wurde.",al={"gryans reaktion","starkmantels reaktion"}}},fx={c86c6e50={q="Woher stammt Shaws Bericht und wer hat ihn verfasst?",a="Der Bericht wurde von Meister Mathias Shaw, dem Oberhaupt des Geheimdienstes von Sturmwind, SI:7, verfasst. Shaw arbeitete von seinem Hauptquartier in Die Altstadt aus und stellte die von SI:7 gesammelten Informationen über die Geschichte der Steinmetzgilde und Edwin van Cleef zusammen, um sie an Gryan Starkmantel auf der Späherkuppe zu schicken.",al={"wer hat shaws bericht geschrieben","wer hat shaws bericht erstellt","woher stammt shaws bericht"}}},fp="13,221,31.491.1,22.250.0,49.224.0,44.254.0,41.211.0"}
P.entries["item:shimmering-frond"] = {n="Schimmernder Wedel",s="Auf der Lichtung des Orakels verströmt eine Pflanze von jenseits des großen Meeres eine sich windende, schimmernde Aura. Ihre Wedel gehören zu einer Art, die in den Sümpfen des Elends heimisch ist.",h="Auf der Lichtung des Orakels verströmt eine Pflanze von jenseits des großen Meeres eine sich windende...",kw={"botanik","denalan","al'amethsee","die lichtung des orakels","schimmernder wedel","seltsame pflanze mit wedeln","sümpfe des elends","teldrassil"},ang={["class:Druid"]="Als Druide mögt Ihr eine Sumpfpflanze, die auf Teldrassils erst kürzlich emporgewachsenen Ästen gedeiht, als eine sonderbare Anomalie betrachten.",["profession:Herbalism"]="Als Kräuterkundiger könnt Ihr die Widerstandskraft würdigen, die eine Pflanze aus den Sümpfen des Elends brauchte, um den Ozean zu überqueren und in fremder Erde zu gedeihen."},sec={{t="Eine Probe aus der Ferne",b="Nahe der Lichtung des Orakels wächst eine strahlende Pflanze zwischen den Bäumen. Ihre Aura pulsiert, und ihre Wedel schimmern im Waldlicht. Denalan pflegt Pflanzkübel am Al'Amethsee. Er erkennt die Blätter als eine Art aus den Sümpfen des Elends in den Östlichen Königreichen. Wie Samen aus jenem fernen Sumpf das große Meer überquerten und auf Teldrassil Wurzeln schlugen, bleibt ein Rätsel. Denalan zieht Exemplare in seiner eigenen Erde heran, um sie zu erforschen."}},faq={{q="Woher stammt der Schimmernde Wedel?",a="Eine seltsame Pflanze auf der Lichtung des Orakels auf Teldrassil trägt den Schimmernden Wedel. Ihre Blätter schimmern im Waldlicht mit einem sich windenden, pulsierenden Leuchten.",al={"wo gibt es den schimmernden wedel","schimmernder wedel fundort","seltsame pflanze mit wedeln"}},{q="Wer interessiert sich für den Schimmernden Wedel?",a="Denalan, ein nachtelfischer Naturforscher am Al'Amethsee, möchte den Wedel untersuchen. Er erforscht seltsame Pflanzen, die überall auf Teldrassil Wurzeln schlagen.",al={"wer will den schimmernden wedel","wem den schimmernden wedel geben","denalan schimmernder wedel"}},{q="Was macht diese Pflanze auf Teldrassil so ungewöhnlich?",a="Die Pflanze stammt aus den Sümpfen des Elends in den Östlichen Königreichen, weit jenseits des großen Meeres. Ihr Vorkommen auf Teldrassil ist unerwartet, da sie weder in Kalimdor noch auf dem Weltbaum heimisch ist.",al={"warum ist der schimmernde wedel besonders","herkunft der pflanze","pflanze aus den sümpfen des elends"}},{q="Was geschieht, nachdem Ihr Denalan den Wedel gegeben habt?",a="Denalan pflanzt das Exemplar in seine Pflanzkübel am Al'Amethsee. Er untersucht sein rasches Wachstum und seine exotischen Eigenschaften.",al={"was macht denalan damit","hintergrund zu ausgetriebenen wedeln"}}},fx={["7be1ca60"]={q="Was ist Schimmernder Wedel?",a="Es ist ein Blatt einer ungewöhnlichen, wuchernden Pflanze, bekannt als die Strange Fronded Plant, die auf Die Lichtung des Orakels zu finden ist. Der Wedel schimmert ständig unter dem Blätterdach des Waldes und strahlt eine windende, pulsierende Aura aus, die für die Äste von Teldrassil ungewöhnlich ist.",al={"was ist schimmernder wedel","gegenstand schimmernder wedel","was ist dieser wedel"}}},fp="16,152,20.421.0,42.151.0,42.139.0,47.183.0,47.116.0"}
P.entries["item:shimmerweed"] = {n="Schimmerkraut",s="Auf dem Schimmergrat sammeln Frostmähnentrolle Schimmerkraut für ihre Rituale. Rejold Gerstenbräu aus Bräuhall will seinen scharfen Geschmack in seinem Stout erproben.",h="Auf dem Schimmergrat sammeln Frostmähnentrolle Schimmerkraut für ihre Rituale.",kw={"bräuhall","dun morogh","frostmähnen","perfektes stout","rejold gerstenbräu","schimmergrat","schimmerkraut"},ang={["profession:Herbalism"]="Als Kräuterkundiger könnt Ihr erkennen, wie regionale Pflanzen in örtlichen Brautraditionen und ritueller Alchemie Verwendung finden.",["race:Dwarf"]="Als Zwerg könnt Ihr erkennen, wie Erfindungsgeist eine seltsame Pflanze von einer nahen Felswand zum Gegenstand eines Brauexperiments macht."},sec={{t="Ein Trollgewächs",b="Schimmerkraut wächst auf eisigen Felsen hoch über dem Tiefland von Dun Morogh und wird von Frostmähnentrollen gepflegt. Sie ernten die Pflanze und bewahren sie überall in ihren Lagern in geflochtenen Körben auf. Dort dient sie ihren heiligen Ritualen. Außerhalb der Trollgesellschaft schenken nur wenige Gebirgsjäger dem Kraut große Beachtung, doch erfinderische Außenseiter haben Interesse daran gefunden."},{t="Eine geheime Zutat",b="In Bräuhall vermutet Braumeister Rejold Gerstenbräu, dass Schimmerkraut die fehlende Zutat bei seinem Versuch sein könnte, das ultimative Zwergenstout zu brauen. Er hat den scharfen, unverwechselbaren Geschmack des Krauts erkannt und will es in seinen Gärbottichen erproben. Also heuert Rejold Reisende an, die sich in die Lager der Frostmähnen schleichen, den feindseligen Trollen ausweichen und Scheffel davon zurückbringen sollen."}},faq={{q="Wo wächst Schimmerkraut?",a="Schimmerkraut wächst auf dem Schimmergrat, einer eisigen Anhöhe nordwestlich von Bräuhall in Dun Morogh. Frostmähnentrolle pflegen es und lagern ihre Ernte in Körben, die überall in ihren Lagern stehen.",al={"schimmerkraut fundort","wo schimmerkraut finden","schimmergrat pflanze"}},{q="Wofür verwenden die Frostmähnentrolle Schimmerkraut?",a="Frostmähnentrolle verwenden Schimmerkraut bei ihren geheimnisvollen Stammesriten und Zeremonien. Außenstehende kennen die genauen Einzelheiten nicht, doch das Kraut hat seinen Platz in ihren kulturellen und spirituellen Bräuchen auf dem Schimmergrat.",al={"schimmerkraut verwendung bei trollen","warum wollen trolle schimmerkraut"}},{q="Warum will Rejold Gerstenbräu Schimmerkraut?",a="Rejold Gerstenbräu will Schimmerkraut für seinen Versuch, in Bräuhall das perfekte Zwergenstout zu brauen. Er hat seinen einzigartigen Geschmack erkannt und hofft, dass frische Scheffel seiner experimentellen Maische das kräftige Geschmacksprofil verleihen, das sein Rezept braucht.",al={"rejold gerstenbräu quest","wer will schimmerkraut","warum mit schimmerkraut brauen"}},{q="Wächst Schimmerkraut auch außerhalb von Dun Morogh?",a="Schimmerkraut wurde auch in trockenen Landstrichen wie Durotar gesammelt, wo Weitseher wie Drek'Thar es für wirksame Kräutermischungen und heilende Sude schätzen. Die Pflanze wächst auch jenseits der gefrorenen Gipfel von Khaz Modan.",al={"schimmerkraut durotar","schimmerkraut außerhalb von dun morogh"}}},fx={["1978b4f9"]={q="Was ist Schimmerkraut?",a="Schimmerkraut ist eine unverwechselbare Pflanze, die hoch in den schneebedeckten Höhen von Dun Morogh von den Frostmähnentrollen kultiviert wird, insbesondere um Schimmergrat herum. Das Kraut, das für seinen ungewöhnlichen Geschmack und seine Eigenschaften bekannt ist, wird in Trollkörben gesammelt und spielt eine Rolle bei lokalen Stammesritualen, obwohl ehrgeizige Zwergenbrauer kürzlich Interesse daran gezeigt haben, seine starken Eigenschaften in experimentellen Bieren zu testen.",al={"was ist schimmerkraut","pflanze schimmerkraut","über schimmerkraut"}},d2fd1cd1={q="Woher stammt Schimmerkraut und wer hat es erschaffen?",a="Schimmerkraut wird von den Frostmähnentrollen in Dun Morogh auf natürliche Weise kultiviert, die die Pflanze auf Schimmergrat pflegen und in Körben ernten. Während die Frostmähnentrolle Ernten davon für ihre eigenen Rituale unterhalten, wachsen wilde Sorten des starken Krauts bekanntermaßen auch in fernen Ländern wie Durotar, wo Kräuterkundige und Schamanen der Wildnis es für das Brauen von Tränken schätzen.",al={"woher stammt schimmerkraut","wer hat schimmerkraut erschaffen","ursprung von schimmerkraut"}}},fp="11,155,15.319.0,19.352.0,28.175.0,49.209.0,44.230.0,50.210.0"}
P.entries["item:shindrell-s-note"] = {n="Shindrells Notiz",s="In Astranaar meldet Shindrell Feuerflink Verderbnis nahe der Stadt und an Eschentals Küste. Ihr Bericht reist ostwärts durch den Wald zu Kayneth Stillwind.",h="In Astranaar meldet Shindrell Feuerflink Verderbnis nahe der Stadt und an Eschentals Küste.",kw={"eschental","astranaar","forest song","kayneth stillwind","nightsongwälder","shindrell feuerflink","shindrells notiz"},ang={["class:Druid"]="Shindrells Beobachtungen helfen Kayneth Stillwind und seinen Mitdruiden, die Wurzeln der unnatürlichen Fäulnis aufzuspüren, die Eschental heimsucht.",["race:NightElf"]="Schildwachen, die Eschentals Siedlungen verteidigen, arbeiten mit Cenarion-Druiden zusammen, die die Krankheit des Waldes untersuchen."},sec={{t="Ein Schreiben durch die Wälder",b="Schildwachen und Druiden wachen gemeinsam über Eschentals Grenzen, während sich Unruhe im Wald ausbreitet. Von Astranaar aus berichtet Schildwache Shindrell Feuerflink von beunruhigenden Vorkommnissen entlang der Westküste und unter den Baumkronen im Herzen des Waldes.\n\nIhr Bericht ist an Kayneth Stillwind gerichtet, einen Druiden am Schrein von Forest Song in den Nightsongwäldern im Osten. Boten überbringen Shindrells Beobachtungen aus erster Hand, um seine Suche nach Verderbnis in den heiligen Hainen zu unterstützen."}},faq={{q="Was ist Shindrells Notiz?",a="Der Feldbericht von Schildwache Shindrell Feuerflink beschreibt beunruhigende Vorkommnisse und vermutete Verderbnis nahe Astranaar und entlang der Küste Eschentals.",al={"was ist diese notiz","shindrells notiz","was steht in der notiz"}},{q="Wer soll die Notiz erhalten?",a="Die Notiz ist an Kayneth Stillwind gerichtet, einen Nachtelfendruiden bei Forest Song in den Nightsongwäldern im östlichen Eschental.",al={"wem die notiz geben","wohin geht die notiz","für wen ist die notiz"}},{q="Warum wurde die Notiz verfasst?",a="Kayneth Stillwind fürchtete, dass Verderbnis in den westlichen Wäldern Wurzeln schlug, und bat um Berichte über ungewöhnliche Vorkommnisse. Shindrell trug ihre Beobachtungen zusammen, um ihm zu helfen, die Bedrohung einzuschätzen.",al={"warum die notiz schreiben","von welcher verderbnis spricht shindrell","zweck des berichts"}},{q="Wo lebt Shindrell Feuerflink?",a="Shindrell Feuerflink ist eine Nachtelfenschildwache, die in Astranaar stationiert ist, einer Siedlung im Herzen Eschentals.",al={"wo ist shindrell","shindrell feuerflink aufenthaltsort","wer hat das geschickt"}}},fx={ed6c40b2={q="Woher stammt Shindrells Notiz und wer hat sie verfasst?",a="Die Notiz wurde von Späher Shindrell Feuerflink in Astranaar verfasst. Als formeller Feldbericht geschrieben, beschreibt sie die beunruhigenden Ereignisse, die sie entlang der Küste von Eschental und in den umliegenden Wäldern beobachtet hat.",al={"wer hat shindrells notiz geschrieben","wer hat shindrells notiz erstellt","ursprung von shindrells notiz"}}},fp="16,162,26.450.0,25.139.0,33.121.0,25.183.0,38.102.0"}
P.entries["item:shipment-of-boots"] = {n="Stiefellieferung",s="An der Küste des Brachlands liegt die Stiefellieferung noch immer in einem Lager der Südmeerpiraten südlich von Ratschet. Drizzlik schickte die Kiste aus Beutebucht für Gazlowes Handelsnetzwerk, doch Piraten erbeuteten sie, bevor sie den Hafen erreichte.",h="An der Küste des Brachlands liegt die Stiefellieferung noch immer in einem Lager der Südmeerpiraten südlich...",kw={"beutebucht","drizzlik","gazlowe","ratschet","stiefellieferung","southsea freebooters","stolen booty"},ang={["class:Rogue"]="Als Schurke könnt Ihr durch die Lager der Südmeerpiraten an der Küste schleichen. Die Piraten patrouillieren dicht an dicht, daher ist ein lautloses Vorgehen am sichersten, wenn Ihr Gazlowes gestohlene Fracht zurückholt."},sec={{t="Eine geplünderte Fracht",b="Gazlowe vereinbarte mit Drizzlik, einem Bekleidungshändler in Beutebucht, Stiefel nach Ratschet zu schicken. Südmeerfreibeuter überfielen das Schiff, während sie an der Händlerküste patrouillierten. Sie brachten die Kisten in Strandlager südlich des Hafens und verteilten die gestohlenen Waren zwischen ihren Zelten und Hütten. Die Lieferung liegt noch immer dort, weit entfernt von den Docks von Ratschet."}},faq={{q="Wer hat diese Stiefellieferung verschickt?",a="Drizzlik, ein Goblinhändler in Beutebucht, verschickte die Stiefel aus dem südlichen Hafen.",al={"wer hat die stiefel hergestellt","woher kamen die stiefel","drizzlik stiefel"}},{q="Wer sollte die Stiefel erhalten?",a="Gazlowe bestellte die Stiefel für Ratschet. Er ist dort Chefingenieur und Aufseher, und die Lieferung sollte seinen örtlichen Arbeitskräften und dem Handel zugutekommen.",al={"wem gehören die stiefel","gazlowe stiefellieferung"}},{q="Wie gelangten die Stiefel zu den Piraten?",a="Südmeerfreibeuter überfielen das Frachtschiff an der Küste des Brachlands. Sie plünderten es und brachten die Kisten in ihre Lager südlich von Ratschet.",al={"warum haben südmeerpiraten stiefel","wer hat die stiefel gestohlen"}},{q="Wo lässt sich die Lieferung finden?",a="Die Lieferung liegt zwischen geplünderten Waren im Lager der Südmeerpiraten an der Küste südlich von Ratschet.",al={"stiefel fundort","wo ist die stiefellieferung","stiefellieferung finden"}}},fx={["06b396e7"]={q="Was ist Stiefellieferung?",a="Die Stiefellieferung ist eine Kiste mit Schuhwerk, die über Das große Meer von Beutebucht nach Ratschet geschickt wurde. Sie wurde vom Goblin-Händler Drizzlik versandt und war direkt für Gazlowe bestimmt, bevor die Südmeerfreibeuter das Frachtschiff mit seinen Handelswaren abfingen.",al={"was ist stiefellieferung","gegenstand stiefellieferung","was sind die stiefel"}}},fp="17,211,17.348.0,32.80.0,38.152.0,42.149.0,32.107.0"}
P.entries["item:shipment-of-iron"] = {n="Eisenlieferung",s="Auf den Feldern von Hillsbrad lagert Roheisen in der Menschenschmiede, wo es die Stadtbewohner gegen die Verlassenen bewaffnet.",h="Auf den Feldern von Hillsbrad lagert Roheisen in der Menschenschmiede, wo es die Stadtbewohner gegen die...",kw={"battle of hillsbrad","darthalia","die felder von hillsbrad","eisenlieferung","tarrens mühle","verringtan"},ang={["faction:Horde"]="Als Mitglied der Horde schwächt Ihr den bewaffneten Widerstand der Bauern, indem Ihr Hillsbrad den Nachschub entzieht, bevor sich der Feldzug gegen Süderstade richtet.",["profession:Blacksmithing"]="Für einen Schmied hält Roheisen die Waffenproduktion der Menschen im Tal am Leben. Ohne die Barren steht Verringtans Schmiede nutzlos da."},sec={{t="Nachschub für den Widerstand",b="Im gesamten Vorgebirge des Hügellands leisten menschliche Bauern Widerstand gegen Tarrens Mühle. Ein Großteil ihrer Stärke stammt aus der Schmiede am südwestlichen Rand der Felder von Hillsbrad. Schmied Verringtan und seine Lehrlinge verarbeiten schwere Eisenlieferungen rund um die Uhr zu Waffen und Rüstungen.\n\nDie Befehlshaber der Verlassenen haben angeordnet, die Esse zu löschen, die Schmiede zu töten und das gelagerte Metall für die Kriegsanstrengungen der Horde zu beschlagnahmen. Sie hoffen, die Entschlossenheit der Bauern zu brechen."}},faq={{q="Wo wird die Eisenlieferung aufbewahrt?",a="Das Eisen lagert in der Schmiedewerkstatt am südwestlichen Rand der Felder von Hillsbrad. Schmied Verringtan und seine Lehrlinge bewachen es streng.",al={"eisenlieferung fundort","wo ist das eisen","hillsbrad eisen fundort"}},{q="Warum wollen die Verlassenen dieses Eisen?",a="Das Eisen dient zur Bewaffnung der örtlichen Menschenmiliz, und die Verlassenen wollen diesen Nachschub abschneiden. Hochexekutorin Darthalia will die Vorräte auch für die Kriegsanstrengungen der Horde nutzen, wenn die Offensive darauf abzielt, Süderstade dem Erdboden gleichzumachen.",al={"warum eisen stehlen","tarrens mühle eisen","battle of hillsbrad eisen zweck"}},{q="Wer hat dieses Eisen ursprünglich verwendet?",a="Schmied Verringtan und seine vier Schmiedelehrlinge nutzten das Eisen, um die Stadtbewohner und Feldarbeiter zu bewaffnen. Sie machten einfache Bauern zu einer örtlichen Verteidigungstruppe gegen die Untoten.",al={"wem gehört das eisen","verringtan eisen","hillsbrad schmiede"}},{q="Wer befiehlt, die Eisenlieferung zu beschaffen?",a="Hochexekutorin Darthalia befehligt die Einsätze der Verlassenen von Tarrens Mühle aus. Während der Battle of Hillsbrad befiehlt sie, die Schmiede zu töten und das Eisen zu beschlagnahmen.",al={"wer gibt die quest","darthalia eisen quest"}}},fx={["8a003d21"]={q="Was ist Eisenlieferung?",a="Die Eisenlieferung ist ein Vorrat an Roheisen, der in der Schmiede der Menschen auf Die Felder von Hillsbrad gelagert wird. Er dient als Hauptmaterial, das Schmied Verringtan und seine Lehrlinge verwenden, um Waffen und Rüstungen für die örtlichen Stadtbewohner von Hillsbrad zu schmieden, die Widerstand gegen die Verlassene leisten.",al={"was ist eisenlieferung","eisenlieferung","eisenlieferung hillsbrad"}}},fp="16,106,22.445.0,35.153.0,37.217.0,35.182.0,46.154.0"}
P.entries["item:shipping-schedule"] = {n="Shipping Schedule",s="An Jerods Anlegestelle verschickt die Bruderschaft der Defias Schmuggelware über Elwynns Wasserwege. Ihr Hafenmeister hütet einen Plan der Lieferungen zwischen dem Rotkammgebirge und Westfall, und der SI:7 will ihn haben.",h="An Jerods Anlegestelle verschickt die Bruderschaft der Defias Schmuggelware über Elwynns Wasserwege.",kw={"defias","hafenmeister","wald von elwynn","jerods anlegestelle","mathias shaw","shipping schedule","si:7","schmuggel"},ang={["class:Rogue"]="Als Schurke könnt Ihr Eure Fähigkeiten im Schleichen und Taschendiebstahl prüfen, die der SI:7 von angehenden Agenten erwartet, indem Ihr den Plan aus den Taschen des Hafenmeisters stehlt."},sec={{t="Schmuggel an Jerods Anlegestelle",b="Südlich von Goldhain liegt Jerods Anlegestelle am Ufer des Nazferiti-Flusses auf der Seite von Elwynn. Die Bruderschaft der Defias nahm sie als Knotenpunkt für den Flussverkehr ein. Von dort transportieren sie Schmuggelware zwischen dem Rotkammgebirge und Westfall über Wasserwege, die der Aufmerksamkeit der Wache von Sturmwind entgehen. Ihr Hafenmeister hält den Shipping Schedule stets bei sich, in dem jede Lieferung verzeichnet ist."},{t="Im Visier des SI:7",b="Meister Mathias Shaw leitet den SI:7, den Geheimdienst von Sturmwind, und hat den Diebstahl des Plans angeordnet. Er kann die Versorgungslinien der Defias offenlegen, und seine Entwendung stellt neue Agenten auf die Probe. Der Diebstahl muss im Dockhaus erfolgen, aus den Taschen des Hafenmeisters. Wird der Agent gefasst, leugnet der SI:7 jede Verbindung. Keine Spur führt zurück zu seiner Kaserne in Sturmwind."}},faq={{q="Was ist der Shipping Schedule?",a="Der Shipping Schedule verzeichnet die Schmuggellieferungen, die der Hafenmeister der Bruderschaft der Defias an Jerods Anlegestelle abwickelt. Er erfasst Fracht, die zwischen dem Rotkammgebirge und Westfall über die Binnengewässer des Waldes von Elwynn transportiert wird.",al={"lieferzeitplan der defias","was ist dieses dokument","hafenmeister plan"}},{q="Wer will den Plan beschaffen lassen?",a="Meister Mathias Shaw, der Leiter des SI:7, will den Plan beschaffen lassen. Er nutzt ihn, um den Schmuggel der Defias zu verfolgen und vielversprechende Schurken im Einsatz zu prüfen.",al={"wer braucht den plan","mathias shaw plan","wer nimmt den shipping schedule"}},{q="Wo ist der Plan zu finden?",a="Der Hafenmeister der Bruderschaft der Defias trägt den Plan im Dockhaus an Jerods Anlegestelle bei sich. Die Anlegestelle liegt am Nazferiti-Fluss südlich von Goldhain im Wald von Elwynn, und das Dokument muss ihm dort entwendet werden.",al={"shipping schedule fundort","wo ist der hafenmeister","wie den plan bekommen"}},{q="Wozu dient Jerods Anlegestelle?",a="Die Bruderschaft der Defias nahm Jerods Anlegestelle als Umschlagplatz für den Schmuggel ein. Ihr Zugang zum Fluss verbindet ihre Unternehmungen im Rotkammgebirge mit ihren Stützpunkten in Westfall.",al={"jerods anlegestelle defias","warum haben die defias jerods anlegestelle","defias anlegestelle elwynn"}}},fx={["45ccd8c3"]={q="Woher stammt Shipping Schedule und wer hat ihn erstellt?",a="Der Zeitplan wird vom Hafenmeister der The Defias Brotherhood verwahrt, der auf Jerods Anlegestelle südlich von Goldhain stationiert ist. Er beschreibt die Flussoperationen des gesetzlosen Syndikats und verfolgt die Bewegung illegaler Waren und Schmuggelgut, das zwischen Rotkammgebirge und Westfall geschmuggelt wird.",al={"wer hat shipping schedule geschrieben","ursprung von shipping schedule","wer hat lieferzeitplan der defias erstellt"}}},fp="17,181,28.335.0,25.350.0,30.208.0,34.141.0,28.208.0,33.167.0"}
P.entries["item:sida-s-bag"] = {n="Sidas Tasche",s="Nahe Eisenbarts Grabmal liegt Sidas Tasche, von einem Schlamm verschluckt. Sida floh zum Hafen von Menethil, nachdem sie bei ihrem wöchentlichen Besuch ihre Tasche nach einem der Schleime geworfen hatte. Nun müssen die ätzenden Kreaturen nach ihren Habseligkeiten durchsucht werden.",h="Nahe Eisenbarts Grabmal liegt Sidas Tasche, von einem Schlamm verschluckt.",kw={"dun modr","eisenbarts grabmal","hafen von menethil","schlamm","sida","sidas tasche","sumpfland"},ang={["faction:Alliance"]="Die bedrängten Flüchtlinge und Einwohner im Hafen von Menethil verlassen sich auf durchreisende Abenteurer, die sich den räuberischen Schrecken stellen, die aus dem überfluteten Sumpfland herankriechen."},sec={{t="Eine panische Gegenwehr",b="Jede Woche besucht Sida Eisenbarts Grabmal nahe Dun Modr. Schreckliche, tropfende Schlämme überfielen sie dort, und in ihrer Panik schleuderte sie ihre Tasche nach einem von ihnen. Der Schlamm verschluckte die Tasche. Das verschaffte Sida Zeit, mit dem Leben davonzukommen und zum Hafen von Menethil zurückzukehren, während ihre Besitztümer in einem unbekannten Schleim gefangen blieben."},{t="Aus dem Schleim geborgen",b="Die Schlämme rund um Eisenbarts Grabmal reichen von blutroten bis hin zu monströsen Exemplaren und sehen einander sehr ähnlich. Streckt die Sumpfschleime nieder, bis Sidas Tasche unversehrt zum Vorschein kommt. Ätzender Schleim durchtränkte den strapazierfähigen Beutel, doch sein Inhalt blieb erhalten. Sida nimmt ihre Habseligkeiten wieder an sich, wirft dann die ruinierte, schleimbedeckte Hülle fort und bietet den ausgewaschenen Behälter demjenigen an, der ihretwegen dem Sumpf trotzte."}},faq={{q="Warum war Sidas Tasche in einem Schlamm?",a="Tropfende Schleime griffen Sida bei einem Besuch von Eisenbarts Grabmal an, und Panik erfasste sie. Sie schleuderte ihre Tasche nach einem von ihnen, um zu entkommen, und der Schlamm verschluckte sie im Ganzen.",al={"wie bekam der schlamm die tasche","warum ist die tasche im schleim","wie verlor sida ihre tasche"}},{q="Welche Schlämme tragen Sidas Tasche bei sich?",a="Sida kann die Schleime nicht auseinanderhalten, also könnte jeder räuberische Schlamm rund um Eisenbarts Grabmal im nordöstlichen Sumpfland die Tasche verschluckt haben. Crimson Oozes, Black Oozes und Monstrous Oozes streifen alle dort umher.",al={"wo ist sidas tasche zu finden","wer lässt sidas tasche fallen","welcher schleim hat die tasche"}},{q="Warum besucht Sida Eisenbarts Grabmal?",a="Jede Woche reist Sida vom Hafen von Menethil zur uralten Zwergengruft nahe Dun Modr. Die persönlichen Gründe für diese Besuche behält sie für sich.",al={"verbindung zwischen sida und ironbeard","warum eisenbarts grabmal"}},{q="Was war in Sidas Tasche?",a="Sida leert ihre wiedergefundenen Gegenstände auf den Boden und sammelt sie auf, ohne zu zeigen, worum es sich handelt. Sie sagt nur, dass sie viel zu wichtig waren, um sie in einem Schlamm auflösen zu lassen.",al={"was holt sida aus der tasche","tascheninhalt"}}},fx={["113113dd"]={q="Was ist Sidas Tasche?",a="Sidas Tasche ist ein persönlicher Beutel von Sida, einer Bewohnerin, die sich im Hafen von Menethil aufhält. Während sie ihren routinemäßigen Besuch bei Eisenbarts Grabmal im Sumpfland machte, wurde sie von Schleimen überfallen und warf ihre Tasche in einem verzweifelten Fluchtversuch nach einem der Wesen. Die Kreatur verschluckte sie ganz, wodurch die Tasche im geleeartigen Körper der Kreatur gefangen blieb.",al={"was ist sidas tasche","sida tasche","wer ist sida tasche"}},afbd2451={q="Warum möchte Sida ihre Tasche zurück?",a="Sida benötigt verzweifelt den Inhalt ihrer verlorenen Tasche, nicht den Beutel selbst. Sobald Ihr ihn aus den Überresten der Schlicke bei Eisenbarts Grabmal befreit und ihr im Hafen von Menethil zurückbringt, schüttet sie den schleimigen Inhalt sofort auf den Boden, sammelt ihn auf und händigt Euch den leeren, schleimverschmierten Beutel aus.",al={"warum möchte sida ihre tasche","warum sidas tasche","warum möchte jemand sidas tasche"}}},fp="10,224,18.300.0,24.369.0,34.160.0,29.204.0,37.154.0,27.179.0"}
P.entries["item:signed-recruitment-letter"] = {n="Unterschriebener Anwerbungsbrief",s="Von der Fernwacht schickt Kargal Schlachtnarbe einen unterschriebenen Brief mit dienstbereiten Rekruten nach Westen. Er weist sie an, sich bei Sergra Dunkeldorn am Wegekreuz zu melden.",h="Von der Fernwacht schickt Kargal Schlachtnarbe einen unterschriebenen Brief mit dienstbereiten Rekruten nach...",kw={"wehrpflicht","das wegekreuz","fernwacht","kargal schlachtnarbe","sergra darkthorn","unterschriebener anwerbungsbrief","brachland","thrall"},ang={["class:Shaman"]="Als Schamane meldet Ihr Euch bei Sergra Dunkeldorn, einer Orcschamanin, die Thrall damit betraut hat, bei der Sicherung des Brachlands zu helfen.",["faction:Horde"]="Als Mitglied der Horde tragt Ihr diesen Brief vom grundlegenden Dienst in Durotar zu den größeren Grenztruppen der Horde."},sec={{t="Versetzung eines Wehrpflichtigen",b="An der Fernwacht bereitet Kargal Schlachtnarbe Rekruten auf ihren Dienst im Brachland vor. Der Posten liegt östlich des Südstroms, den Neuankömmlinge aus Durotar überqueren. Sobald ein Wehrpflichtiger seine Bereitschaft bewiesen hat, stempelt und unterschreibt Kargal einen Vorstellungsbrief. Dessen Befehle schicken Rekruten auf der Straße nach Westen zum Wegekreuz, wo Sergra Dunkeldorn die Versorgung und die Verteidigung der trockenen Ebenen koordiniert."},{t="Spannungen an den Außenposten",b="Kargals Befehle lassen seine Verachtung für die Offizierin erkennen, die den Rekruten erwartet. Er nennt Sergra Dunkeldorn eine schroffe Schamanin, die Soldaten schwindelig redet. Kargal stellt Kriegshäuptling Thralls hohe Meinung von ihr offen infrage. Dennoch muss die Depesche Sergra erreichen, bevor weitere Aufträge am Wegekreuz erteilt werden."}},faq={{q="Welchen Zweck hat der Unterschriebene Anwerbungsbrief?",a="Der Unterschriebene Anwerbungsbrief versetzt Euch von Kargal Schlachtnarbe an der Fernwacht zum Dienst im Brachland. Er zeigt Sergra Dunkeldorn am Wegekreuz, dass Kargal Euch für bereit befunden hat.",al={"wozu dient dieser brief","anwerbungsbrief verwendung","unterschriebener brief brachland"}},{q="Wer hat den Brief unterschrieben?",a="Kargal Schlachtnarbe unterschreibt den Brief. Der Orcveteran beaufsichtigt die Fernwacht an der Grenze zwischen Durotar und dem Brachland. Er unterschreibt, nachdem ein Rekrut dort seine ersten Aufgaben erfüllt hat.",al={"wer hat den brief geschrieben","kargal brief","wer hat das unterschrieben"}},{q="Wem überbringe ich den Brief?",a="Ihr überbringt den Brief Sergra Dunkeldorn, einer einflussreichen Orcschamanin, die an der zentralen Kreuzung des Wegekreuzes stationiert ist.",al={"wohin den brief bringen","wer bekommt den brief","briefempfänger"}},{q="Warum spricht Kargal schlecht über Sergra Dunkeldorn?",a="Kargal nennt Sergra scharfzüngig und schwierig und meint, sie verschwende Zeit mit Reden, wenn Arbeit ansteht. Kriegshäuptling Thrall schätzt sie sehr, doch Kargal zweifelt an ihren Führungsqualitäten.",al={"kargal sergra fehde","warum hasst kargal sergra"}}},fx={ea3ee62a={q="Was ist Unterschriebener Anwerbungsbrief?",a="Es ist ein offizielles Einberufungsdokument der Horde, das Rekruten ausgehändigt wird, die aus Durotar im Brachland ankommen. Es wurde von Kargal Schlachtnarbe auf der Fernwacht entworfen und beglaubigt und dient als formelle Bescheinigung, dass Ihr überprüft, eingezogen und entsandt wurdet, um die Siedlung am Wegekreuz zu unterstützen.",al={"was ist unterschriebener anwerbungsbrief","anwerbungsbrief","was ist dieser brief"}},ea22ddb8={q="Warum möchte Sergra Dunkeldorn den Unterschriebener Anwerbungsbrief haben?",a="Sergra Dunkeldorn überwacht die Operationen am Wegekreuz und ist auf ankommende Arbeitskräfte angewiesen, um das Brachland für die Horde zu sichern. Der Brief bestätigt Eure Einberufung unter der Autorität von Kargal und beweist, dass Ihr bereit seid, Befehle entgegenzunehmen, Eure Stärke zu beweisen und die dringenden Arbeiten und Bedrohungen der Siedlung anzugehen.",al={"warum möchte sergra den brief","warum anwerbungsbrief überbringen","wer benötigt anwerbungsbrief"}}},fp="25,164,22.389.0,23.320.0,53.190.0,22.183.0,31.120.0,49.182.0"}
P.entries["item:silithid-egg-the-barrens"] = {n="Silithidenei (Brachland)",s="Überall auf dem Feld der Riesen liegen Silithideneier im Boden vergraben. Forscher der Horde sammeln die Eier, um mehr über den Schwarm zu erfahren, der sich im Südlichen Brachland ausbreitet.",h="Überall auf dem Feld der Riesen liegen Silithideneier im Boden vergraben.",kw={"das wegekreuz","gräberklaue","egg hunt","feld der riesen","korran","hügel","silithiden","silithidenei","brachland"},ang={["faction:Horde"]="Für die Horde bedrohen intelligente Insektenschwärme nahe dem Wegekreuz die Handelswege und Gebiete im Herzen Kalimdors."},sec={{t="Ein rätselhafter Schwarm",b="Auf dem Feld der Riesen erheben sich Silithidenhügel, während seltsame insektenartige Kreaturen die Erde aufwühlen. Ihre Eier liegen unter verhärtetem Boden, bewacht von Silithiden, die ihr Revier verteidigen. Die Horde weiß wenig über sie, doch Späher am Wegekreuz haben Anzeichen von Koordination und Intelligenz gesehen, die über die gewöhnlicher wilder Tiere hinausgehen. Noch nicht geschlüpfte Eier könnten Gelehrten in Orgrimmar helfen, mehr über den Lebenszyklus und das Wesen der Silithiden zu erfahren."},{t="Ausgrabung und Gefahr",b="Eine angepasste Gräberklaue wird benötigt, um Silithideneier aus den Hügeln zu lösen. Die Kreaturen verteidigen ihre unterirdischen Brutstätten erbittert und überfallen im Schwarm jeden, der ihre ungeschlüpfte Brut bedroht. Korran, ein Trollforscher, benötigt unversehrte Exemplare für seine Studien, bevor sich der Schwarm weiter über Kalimdor ausbreitet."}},faq={{q="Was sind Silithideneier?",a="Silithideneier sind noch nicht geschlüpfte Gelege, die in Erdhügeln im Südlichen Brachland vergraben liegen, besonders rund um das Feld der Riesen.",al={"silithidenei","was ist ein silithidenei","silithidenhügel"}},{q="Wer möchte diese Eier sammeln lassen?",a="Korran, ein Trollforscher am Wegekreuz, sammelt die Eier für seine Meister in Orgrimmar. Sie wollen die Biologie und das Verhalten der Silithiden erforschen.",al={"wer braucht eier","korran quest","egg hunt questgeber"}},{q="Warum werden die Silithiden erforscht?",a="Die Horde weiß wenig über die Silithiden. Korran hat Anzeichen von Intelligenz und Koordination gesehen, die über die gewöhnlicher Wildtiere hinausgehen. Ihr Auftauchen im Brachland beunruhigt die Anführer der Horde.",al={"warum silithiden erforschen","bedrohung durch silithiden","sind silithiden intelligent"}},{q="Wie werden die Eier gesammelt?",a="Eine angepasste Gräberklaue löst Eier aus Silithidenhügeln. Der aggressive Schwarm verteidigt seine Nester.",al={"wie eier bekommen","gräberklaue","silithideneier sammeln"}}},fx={["04f05afd"]={q="Woher stammen Silithideneier?",a="Diese Eier werden von den sonderbaren, insektenartigen Silithiden tief in ihren Erdhügeln im Südlichen Brachland gelegt, besonders überall im Feld der Riesen. Die Silithiden vergraben und bewachen ihre Gelege sorgfältig in diesen hoch aufragenden Erdhügeln und greifen jeden an, der es wagt, die Nester zu stören.",al={"herkunft silithidenei","woher kommen silithideneier","wer hat die silithideneier gelegt"}}},fp="26,168,18.405.0,21.294.0,23.125.0,31.142.0,35.191.0,26.96.0"}
P.entries["item:silixiz-s-tower-key"] = {n="Silixiz' Turmschlüssel",s="Am Turm der Venture Company nahe dem Schlickermoor steckt Silixiz' Turmschlüssel in der Tasche von Foreman Silixiz. Ein Agent der Shattered Hand muss ihn im Rahmen eines verdeckten Sabotageauftrags unbemerkt stehlen.",h="Am Turm der Venture Company nahe dem Schlickermoor steckt Silixiz' Turmschlüssel in der Tasche von Foreman...",kw={"barrens","foreman silixiz","shattered hand","shenthul","silixiz","das schlickermoor","turmschlüssel","venture co"},ang={["class:Rogue"]="Als Schurke der Horde nehmt Ihr Silixiz' Turmschlüssel als Aufnahmeprüfung für die Shattered Hand an Euch. Die Prüfung verlangt Heimlichkeit und Geschick im Taschendiebstahl.",["faction:Horde"]="Als Mitglied der Horde tragt Ihr eine Trophäe aus dem Kampf gegen die Ausbeutung und die chemischen Experimente der Venture Company in den nördlichen Barrens."},sec={{t="Eine Prüfung der Heimlichkeit",b="Nördlich des Schlickermoors bewacht die Venture Company ihren Turm streng. Grand Foreman Puzik Gallywix beaufsichtigt den abgelegenen Aussichtsposten, während Goblinsöldner auf dem Gelände patrouillieren. Foreman Silixiz trägt den Turmschlüssel draußen bei sich.\n\nEin Agent der Shattered Hand aus Orgrimmar muss den Schlüssel stehlen und behalten. Mit Gewalt geht es nicht. Der Agent muss unbemerkt eindringen und Silixiz den Schlüssel aus der Tasche stehlen, um seine Heimlichkeit zu beweisen, bevor er die giftigen oberen Turmebenen erklimmt."}},faq={{q="Wo finde ich Foreman Silixiz?",a="Foreman Silixiz befindet sich außerhalb des Turms der Venture Company, direkt nördlich des Schlickermoors im Nordosten der Barrens.",al={"silixiz standort","wo ist foreman silixiz","silixiz finden"}},{q="Kann ich den Schlüssel erhalten, indem ich Foreman Silixiz töte?",a="Nein. Der Schlüssel lässt sich nicht von Silixiz' Leiche nehmen. Ein Agent muss ihn aus seiner Tasche stehlen, solange er lebt.",al={"silixiz schlüssel beute","silixiz töten möglich","silixiz schlüssel plündern"}},{q="Wer benötigt diesen Schlüssel?",a="Kontaktleute der Shattered Hand verlangen, dass der Schlüssel zu Shenthul gebracht wird, dem Schurkenlehrer in Orgrimmar.",al={"wer will den schlüssel","silixiz schlüssel abgeben","silixiz' turmschlüssel quest"}},{q="Wofür wird der Schlüssel verwendet?",a="Der Schlüssel beweist, dass ein Agent den Turm der Venture Company nahe dem Schlickermoor betreten hat. Er geht zusammen mit Grand Foreman Puzik Gallywixs Kopf und dem Behälter mit Zanzils veränderter Mixtur an die Shattered Hand.",al={"was öffnet silixiz' schlüssel","silixiz schlüssel zweck","turmschlüssel benutzen"}}},fx={["163c94d7"]={q="Was ist Silixiz' Turmschlüssel?",a="Es ist ein Schlüssel, den Vorarbeiter Silixiz außerhalb des Turms der Venture Company nördlich von Das Schlickermoor bei sich trägt. Der Agent wurde angewiesen, ihn zu stehlen und aufzubewahren, falls der Kontakt der The Shattered Hand ihn später benötigt.",al={"was ist silixiz turmschlüssel","silixiz schlüssel","turmschlüssel der venture company"}}},fp="19,195,18.451.0,32.115.0,48.103.0,22.94.0,25.198.1"}
P.entries["item:silver-dawning-s-lockbox"] = {n="Schließkassette der Silbermorgen",s="Vor der Dunkelküste liegt die Schließkassette der Silbermorgen in einem Wrack nördlich von Auberdine. Küstenmurlocs versenkten das Schiff, und die Kassette enthält die persönlichen Habseligkeiten des Kapitäns und das Schiffslogbuch.",h="Vor der Dunkelküste liegt die Schließkassette der Silbermorgen in einem Wrack nördlich von Auberdine.",kw={"auberdine","dunkelküste","gorbold stahlhand","schließkassette","murloc","schiffswrack","silbermorgen"},ang={["race:Dwarf"]="Gorbold Stahlhand nimmt es auf sich, die gefallenen Kapitäne zu ehren und ihren überlebenden Kameraden ihre Habseligkeiten zurückzubringen.",["race:NightElf"]="Die Schließkassette enthält die letzten Aufzeichnungen und Habseligkeiten eines Kapitäns der Kaldorei, der bei der Verteidigung seines Schiffes vor den Küsten des nördlichen Kalimdor starb."},sec={{t="Versunkene Überreste",b="Die Silbermorgen segelte nach Auberdine, als Küstenmurlocs angriffen. Sie trieben das Schiff nördlich des Hafens unter die Wellen, und der Kapitän starb bei dem Angriff. Im gefluteten Rumpf liegt noch immer die Schließkassette des Kapitäns mit dem Schiffslogbuch und seinen persönlichen Habseligkeiten. Ihre Bergung könnte den überlebenden Besatzungsmitgliedern an Land etwas Frieden bringen."}},faq={{q="Wo befindet sich die Schließkassette der Silbermorgen?",a="Die Schließkassette liegt im versunkenen Wrack der Silbermorgen auf dem Meeresgrund nördlich von Auberdine vor der Dunkelküste.",al={"fundort der schließkassette","wo ist die kassette der silbermorgen","wrack der silbermorgen"}},{q="Was geschah mit der Silbermorgen?",a="Küstenmurlocs griffen die Silbermorgen an, als sie nach Auberdine segelte. Sie überwältigten die Besatzung, und das Schiff versank mit seinem Kapitän unter den Wellen.",al={"warum sank die silbermorgen","vorgeschichte der silbermorgen","wie erlitt das schiff schiffbruch"}},{q="Was befindet sich in der Schließkassette?",a="Die Schließkassette enthält die persönlichen Habseligkeiten und das Seelogbuch des Kapitäns der Silbermorgen.",al={"inhalt der silbermorgen","was ist in der kassette"}},{q="Wer sucht nach der Schließkassette?",a="Gorbold Stahlhand, ein in Auberdine stationierter Zwerg, bittet Schwimmer, die Schließkassette aus den Wracks zu bergen, damit die überlebenden Besatzungsmitglieder ihres gefallenen Kapitäns gedenken können.",al={"wer will die schließkassette","wer vergibt die quest","schließkassette abgeben"}}},fx={["9cc39920"]={q="Was ist Schließkassette der Silbermorgen?",a="Es ist die persönliche Truhe des verstorbenen Kapitäns der Silbermorgen. Als das Schiff von Murlocs vor der Nordküste von Dunkelküste überrannt und versenkt wurde, ging die Schließkassette mit dem Wrack unter. Sie enthält das Logbuch des Kapitäns und überlebende persönliche Gegenstände, die tief unter Wasser inmitten der umherstreifenden Kreaturen ruhen.",al={"was ist schließkassette der silbermorgen","lore schließkassette silbermorgen","kapitän schließkassette silbermorgen"}}},fp="24,179,15.344.0,46.130.0,36.149.0,27.76.0,27.167.0"}
P.entries["item:silvery-spinnerets"] = {n="Silbrige Spinndrüsen",s="Nahe dem Quellsee werden Silbrige Spinndrüsen für einen Ritus zu Ehren von Lady Sathrah gesucht. Ihre silbernen Netze sammelten einst heilenden Abendtau für die Sisterhood of Elune in Darnassus.",h="Nahe dem Quellsee werden Silbrige Spinndrüsen für einen Ritus zu Ehren von Lady Sathrah gesucht.",kw={"lady sathrah","priesterin a'moora","sathrahs opferung","silbrige spinndrüsen","tears of the moon","tempel des mondes","quellsee"},ang={["class:Priest"]="Für die Diener Elunes ist das Bergen der Spinndrüsen ein heiliger Bestattungsritus. Er bittet Mother Moon, eine Kreatur zu erlösen, statt ihren Tod als bloße Ausrottung zu behandeln.",["race:NightElf"]="Lady Sathrahs tragisches Ende erinnert die Kaldorei daran, dass selbst von Elune geliebte Kreaturen dem Leiden anheimfallen können, das Teldrassil erkranken lässt."},sec={{t="Heilige Netze und Verderbnis",b="Im Mondlicht nahe dem Quellsee spann Lady Sathrah schimmernde Netze. Ihre silberne Seide sammelte Abendnebel zu heilendem Tau, den die Sisterhood of Elune in Darnassus hoch schätzte.\n\nDann erreichte sie die Verderbnis in Teldrassil und trieb sie in gewalttätigen Wahnsinn. Sathrah bedrohte ihre Brut und den umliegenden Wald. Priesterin A'moora bittet Reisende, ihr Leiden zu beenden und ihre Spinndrüsen zu bergen, um einer einst verehrten Kreatur der großen Äste Gnade zu erweisen."},{t="Ein Opfer für die Wiedergeburt",b="Die Schwesternschaft bringt Elune die geborgenen Spinndrüsen am zentralen Brunnen im Tempel des Mondes dar. Im Ritus namens Sathrahs Opferung beten die Priesterinnen darum, dass die Mondgöttin den Geist der Kreatur aufnimmt. Sie bitten sie, den Wahnsinn zu läutern, der Sathrahs sterblichen Körper befiel, und ihr Frieden in der Wiedergeburt zu gewähren."}},faq={{q="Wo erhaltet Ihr die Silbrigen Spinndrüsen?",a="Bergt die Silbrigen Spinndrüsen von Lady Sathrah, einer großen Spinne nahe dem Quellsee an den nördlichen Grenzen Teldrassils.",al={"wo silbrige spinndrüsen finden","silbrige spinndrüsen beute","wer lässt silbrige spinndrüsen fallen"}},{q="Warum will Priesterin A'moora die Spinndrüsen?",a="Priesterin A'moora sucht die Spinndrüsen für eine heilige Opfergabe an Elune. Der Ritus ehrt Lady Sathrahs einstige Reinheit und bittet die Göttin, ihren Geist zu läutern und ihr Frieden und Wiedergeburt zu gewähren.",al={"warum amoora spinndrüsen will","tears of the moon zweck"}},{q="Warum waren Lady Sathrahs Netze besonders?",a="Lady Sathrah spann leuchtende silberne Seide, die im Mondlicht den Abendnebel auffing. Der Tau barg mächtige heilende Magie, und die Sisterhood of Elune schätzte ihn hoch und bewahrte ihn zur Heilung im Tempel des Mondes auf.",al={"lady sathrahs netze","was tat lady sathrah"}},{q="Warum wurde Lady Sathrah getötet, obwohl sie heilig war?",a="Die Verderbnis trieb Lady Sathrah in unheilbaren Wahnsinn, wie auch andere Wildtiere in Teldrassil. Ihre Angriffslust gefährdete den Wald und bedrohte ihre Brut, weshalb die Priesterinnen ihre Tötung als einen schmerzlichen Akt der Gnade betrachteten.",al={"warum lady sathrah töten","warum wurde sathrah wahnsinnig"}}},fx={["6e94bdc8"]={q="Was sind Silbrige Spinndrüsen?",a="Die Silbrige Spinndrüsen sind die seidenerzeugenden Organe, die der heiligen Spinne Lady Sathrah im nördlichen Teldrassil entnommen wurden. In gesünderen Zeiten benutzte sie sie, um schimmernde silberne Fäden durch das Mondlicht zu weben. Diese Netze fingen den Abendnebel ein und ergaben einen wunderbaren Tau mit starken heilenden Eigenschaften, der von den Priesterinnen von Elune geschätzt wurde.",al={"was sind silbrige spinndrüsen","info silbrige spinndrüsen","lady sathrah spinndrüsen"}},["48fdca9c"]={q="Woher stammen die Silbrige Spinndrüsen?",a="Sie werden von Lady Sathrah geerntet, einer riesigen Spinne, die in der Nähe von Quellsee entlang der nördlichen Grenzen von Teldrassil lebt. Einst als anmutige und reine Kreatur verehrt, die von Elune gesegnet war, verfiel Sathrah kürzlich dem Wahnsinn, was es erforderlich machte, dass die Nachtelfen ihrem Leiden ein Ende setzten und ihre heiligen Überreste zurückforderten.",al={"ursprung silbrige spinndrüsen","wer hat silbrige spinndrüsen erstellt","wo bekommt man silbrige spinndrüsen"}}},fp="18,177,29.453.0,23.332.1,40.123.0,47.192.0,37.213.0,46.220.0"}
P.entries["item:simple-memorandum"] = {n="Einfaches Memorandum",s="Im Coldridgetal werden angehende Gnomkrieger zur Ausbildung bei Thran Khorman in Ambossar geschickt. Sie bereiten sich auf den Krieg zur Rückeroberung von Gnomeregan vor.",h="Im Coldridgetal werden angehende Gnomkrieger zur Ausbildung bei Thran Khorman in Ambossar geschickt.",kw={"ambossar","das coldridgetal","dun morogh","gnomeregan","einfaches memorandum","thran khorman","kriegerausbildung"},ang={["class:Warrior"]="Als Krieger beginnt Ihr Eure geregelte Kampfausbildung bei Thran Khorman in Ambossar. Ihr lasst einfache Scharmützel hinter Euch.",["race:Gnome"]="Als verbannter Gnom teilt Ihr das Ziel, Eure Kampffertigkeiten an der Seite Eurer zwergischen Verbündeten zu schärfen. Ihr bereitet Euch auf die Befreiung von Gnomeregan vor."},sec={{t="Ein Ruf nach Ambossar",b="Junge Gnomkämpfer stellen sich im Coldridgetal wilden Tieren und Troggs, mit Empfehlungsschreiben in der Hand. Das Einfache Memorandum verweist seinen Überbringer an Thran Khorman, den Kriegerlehrer in Ambossar.\n\nGnome ziehen mit Verstand und Apparaturen in die Schlacht, doch die Rückeroberung von Gnomeregan verlangt Stärke und kämpferische Disziplin. Das Memorandum schickt seinen Überbringer über die erste Ausbildung hinaus, um bei Thran die Kriegskunst zu erlernen."}},faq={{q="Was ist das Einfache Memorandum?",a="Das Einfache Memorandum ist eine schriftliche Nachricht für angehende Gnomkrieger im Coldridgetal. Es weist sie an, sich beim zwergischen Kriegerlehrer in Ambossar zu melden.",al={"einfaches memorandum","was ist diese notiz","memorandum gegenstand"}},{q="Wer hat das Einfache Memorandum verfasst?",a="Das Einfache Memorandum trägt keine Unterschrift. Sten Starkarm vermutet, dass Thran Khorman es verfasst hat, doch seine Worte über die Rückeroberung von Gnomeregan kennzeichnen es als gnomische Anweisung. Es befiehlt Euch, Euch bei Thran zu melden, dem zwergischen Kriegerlehrer in Ambossar.",al={"wer hat das memorandum verfasst","wer hat die notiz geschickt","verfasser des einfachen memorandums"}},{q="Was geschieht nach dem Lesen des Einfachen Memorandums?",a="Nachdem Ihr das Einfache Memorandum gelesen habt, bringt Ihr es zu Thran Khorman in Ambossar. Er erkennt Eure Entschlossenheit, Eure verlorene Heimat zurückzuerobern, und bietet an, Euch die Grundlagen des Kampfes als Krieger beizubringen.",al={"was tun mit dem memorandum","wohin damit","einfaches memorandum abgeben"}},{q="Warum bildet ein Zwerg Gnomkrieger aus?",a="Ein Zwerg bildet Gnomkrieger aus, weil sich gnomische Flüchtlinge nach dem Fall von Gnomeregan in Eisenschmiede und Ambossar niedergelassen haben. Zwergische Veteranen wie Thran Khorman helfen ihren verbannten Verbündeten mit ihrer Kriegskunst bei der Ausbildung und der Rückeroberung ihrer verstrahlten Stadt.",al={"warum bildet thran gnome aus","zwerge bilden gnome aus"}}},fx={b027c55a={q="Warum wurde mir das Einfache Memorandum übergeben?",a="Das Memorandum ist eine gnomische Direktive, die Euch befiehlt, Euch bei Thran Khorman, dem Zwergenkriegerausbilder in Ambossar, zu melden. Als vertriebener Gnomkrieger ist es Eure oberste Direktive, Euch auf den Krieg zur Rückeroberung von Gnomeregan vorzubereiten, und Thran hat sein Wort gegeben, Euch und Euer Volk darauf vorzubereiten. Sten Starkarm hat Euch die Nachricht überreicht, während Ihr ihm im Coldridgetal geholfen habt.",al={"warum einfaches memorandum","zweck des einfachen memorandums","warum brauche ich das einfache memorandum"}}},fp="17,142,21.407.0,30.159.0,32.237.0,49.185.0,39.244.0"}
P.entries["item:simple-rune"] = {n="Einfache Rune",s="Im Coldridgetal schickt Thran Khorman vielversprechende junge Zwergenkrieger mit der Einfachen Rune zur Ausbildung nach Ambossar.",h="Im Coldridgetal schickt Thran Khorman vielversprechende junge Zwergenkrieger mit der Einfachen Rune zur...",kw={"ambossar","das coldridgetal","dun morogh","zwergenrune","einfache rune","thran khorman","kriegerausbildung"},ang={["class:Warrior"]="Für Euch als Zwergenkrieger markiert die Einfache Rune den ersten Schritt in die geregelte Ausbildung beim erfahrenen Lehrmeister Thran Khorman.",["race:Dwarf"]="Euch als Zwerg vermittelt Thran Khormans Rune die Grundlagen des Kampfes: den Griff einer Axt, das Gewicht einer Rüstung und den Schweiß einer echten Schlacht."},sec={{t="Ein Ruf zu den Waffen",b="Junge Kämpfer, die begonnen haben, Bedrohungen im Coldridgetal zu beseitigen, erhalten Thrans förmlichen Aufruf. Die kriegerischen Zeichen der Rune bergen keine Magie; sie weisen jeden Rekruten an, sich bei Thran in Ambossar zu melden. Dort lehrt er die Grundlagen des Kampfes und gibt praktische Ratschläge zum Überleben in der feindseligen Wildnis von Dun Morogh."}},faq={{q="Welchen Zweck hat die Einfache Rune?",a="Die Einfache Rune weist Rekruten an, sich in Ambossar von Thran Khorman unterweisen zu lassen. Junge Krieger im Coldridgetal erhalten sie als Tafel mit Anweisungen.",al={"einfache rune verwendung","was bewirkt die rune","einfache rune questgegenstand"}},{q="Wer verschickt die Einfache Rune?",a="Thran Khorman verschickt die Einfache Rune. Der zwergische Kriegerlehrer in Ambossar hält nach vielversprechenden Kämpfern Ausschau, die im Tal mithelfen.",al={"wer hat die rune geschrieben","wer hat die einfache rune gegeben","absender der rune"}},{q="Wohin bringe ich die Einfache Rune?",a="Bringt die Einfache Rune zu Thran Khorman in Ambossar, mitten im Coldridgetal.",al={"wohin gehen","rune abgeben","thran khorman standort"}}},fx={["0f0eb9fb"]={q="Was ist Einfache Rune?",a="Die Einfache Rune ist ein beschrifteter Zwergenstein, der vielversprechenden Kriegern im Coldridgetal übergeben wird. Anstatt mystische Verzauberungen zu tragen, fungiert sie als schriftliche Vorladung von Thran Khorman, die Kampfanfänger dazu auffordert, sich bei ihm in Ambossar zu melden, um ihre formelle kriegerische Ausbildung zu beginnen.",al={"was ist einfache rune","lore einfache rune","gegenstand einfache rune"}},["2d1fc984"]={q="Warum möchte Thran Khorman, dass Ihr die Einfache Rune besitzt?",a="Thran Khorman sendet die Rune, um Euch für die formelle Kriegerausbildung zu rekrutieren. Da er in Euren frühen Taten rund um Das Coldridgetal Potenzial sieht, möchte er Euch in der richtigen zwergischen Kampfdisziplin erden und Euch lehren, was es wirklich bedeutet, inmitten wachsender lokaler Bedrohungen für Eisenschmiede zu kämpfen.",al={"warum schickt thran rune","warum brauche ich einfache rune","warum möchte man einfache rune"}}},fp="11,120,17.305.0,39.169.0,26.137.0,32.83.0"}
P.entries["item:simple-sigil"] = {n="Einfaches Siegelzeichen",s="In Laubschattental ruft ein Einfaches Siegelzeichen angehende Nachtelfenkrieger zur Ausbildung bei Alyissia. Es markiert ihren ersten Schritt zur Verteidigung Teldrassils.",h="In Laubschattental ruft ein Einfaches Siegelzeichen angehende Nachtelfenkrieger zur Ausbildung bei Alyissia.",kw={"alyissia","ilthalaine","kaldorei krieger","laubschattental","einfaches siegelzeichen","teldrassil","kriegerausbildung"},ang={["class:Warrior"]="Für Euch als Krieger der Kaldorei markiert das Einfache Siegelzeichen den ersten Schritt in die Kampftraditionen, die dem Schutz Teldrassils dienen.",["race:NightElf"]="Als Nachtelf erkennt Ihr die Dringlichkeit der Lage der Kaldorei. Alyissia und andere Ausbilder werben fähige Kräfte an, um die wachsende Verderbnis in den Ästen des Weltbaums zu bekämpfen."},sec={{t="Ein Ruf zu den Waffen",b="In Laubschattental begleitet Konservator Ilthalaine junge Nachtelfen auf der Suche nach ihrer Berufung. Ein Bote bringt ein Einfaches Siegelzeichen von Alyissia, der Kriegerausbilderin. Ilthalaine überreicht es angehenden Kriegern, und seine Inschrift weist jeden Rekruten an, sich zur Unterweisung zu melden. Ihre Kampfausbildung beginnt, während unruhige Zeiten über den Weltbaum hereinbrechen."},{t="Die Last der Verteidigung",b="Mit dem Siegelzeichen teilt Alyissia den Rekruten mit, was die Kaldorei brauchen. Teldrassil ist jüngst gewachsen, Verderbnis breitet sich unter den Waldtieren aus, und die Wiederentdeckung ferner Länder wie Feralas hat die Beschützer der Nachtelfen überlastet. Das Siegelzeichen besitzt keine Macht. Es heißt jeden Rekruten im Kreis der Wächter willkommen, die ihr Volk vor aufkommenden Bedrohungen schützen sollen."}},faq={{q="Was ist das Einfache Siegelzeichen?",a="Das Einfache Siegelzeichen ist ein mit einer Inschrift versehenes Zeichen für angehende Nachtelfenkrieger in Laubschattental. Konservator Ilthalaine überreicht es ihnen, und seine Inschrift weist sie an, sich zur Ausbildung bei Alyissia zu melden.",al={"einfaches siegelzeichen gegenstand","was bewirkt einfaches siegelzeichen","was ist dieses siegelzeichen"}},{q="Wer schickt das Einfache Siegelzeichen?",a="Ein Bote bringt das Einfache Siegelzeichen von Alyissia, der Kriegerausbilderin in Laubschattental, zu Konservator Ilthalaine. Ilthalaine überreicht es angehenden Kriegern.",al={"wer hat das siegelzeichen hergestellt","wer hat einfaches siegelzeichen geschickt"}},{q="Was soll ich damit tun?",a="Lest die Inschrift und bringt das Einfache Siegelzeichen zu Alyissia nahe dem Fuß von Aldrassil in Laubschattental, um Eure Kriegerausbildung zu beginnen.",al={"wo einfaches siegelzeichen abgeben","wer nimmt einfaches siegelzeichen an"}},{q="Verleiht das Siegelzeichen besondere Fähigkeiten?",a="Nein. Das Einfache Siegelzeichen ist eine schriftliche Mitteilung, die angehende Krieger mit ihrer Mentorin bekannt macht.",al={"sie gelzeichen kräfte","einfaches siegelzeichen werte"}}},fp="12,138,17.341.0,21.366.0,25.193.0,27.150.0,25.131.0,43.91.0"}
P.entries["item:simple-tablet"] = {n="Einfache Schrifttafel",s="Im Tal der Prüfungen gibt Gornek neuen Trollkriegern eine Nachricht, die sie Frang überbringen sollen.",h="Im Tal der Prüfungen gibt Gornek neuen Trollkriegern eine Nachricht, die sie Frang überbringen sollen.",kw={"dunkelspeer","durotar","frang","gornek","einfache schrifttafel","the den","das tal der prüfungen","kriegerlehrer"},ang={["class:Warrior"]="Als Krieger stellt Euch die Nachricht Frang zur Kampfausbildung vor.",["race:Troll"]="Als Dunkelspeertroll in Durotar ruft Euch dieses Schreiben dazu auf, an der Seite der Orcs die vordersten Reihen der Horde zu verstärken."},sec={{t="Ein Ruf zum Kampf",b="Gornek gibt neuen Trollkriegern eine Nachricht von Tar'sere, die an Frang gerichtet ist, den Kriegerlehrer nahe dem Den. Sie führt den Rekruten in die Kampfausbildung in Durotar ein und fordert ihn auf, sich bei Frang zu melden. Die Nachricht ruft ihn dazu auf, für die Horde zu den Waffen zu greifen."}},faq={{q="Was ist die Einfache Schrifttafel?",a="Im Tal der Prüfungen gibt Gornek angehenden Trollkriegern eine Nachricht, die sie zur Kampfausbildung an Frang verweist.",al={"einfache schrifttafel","was ist diese schrifttafel","schrifttafel für trollkrieger"}},{q="Wer schickt die Schrifttafel?",a="Tar'sere unterzeichnet die Nachricht und verweist den Rekruten an Frang, den Kriegerlehrer außerhalb des Den im Tal der Prüfungen.",al={"wer hat die einfache schrifttafel geschickt","wer hat die schrifttafel geschrieben","absender der schrifttafel"}},{q="Wohin bringe ich die Schrifttafel?",a="Bringt die Einfache Schrifttafel zu Frang, der außerhalb des Den im Tal der Prüfungen rastet.",al={"wem die einfache schrifttafel geben","wohin die schrifttafel bringen","frangs standort"}},{q="Wer erhält diese Schrifttafel?",a="Die Einfache Schrifttafel erhalten Trollkrieger, die im Tal der Prüfungen ihre Übergangsriten beginnen.",al={"kann jeder die einfache schrifttafel erhalten","welche klasse erhält die einfache schrifttafel"}}},fx={["219776b3"]={q="Warum schickt Frang Euch die Einfache Schrifttafel?",a="Frang verfasst sie eigentlich gar nicht. Gornek vermutet, dass sie von Frang stammt, doch die Schrifttafel ist von dem Troll Tar'sere unterzeichnet, der Euch zu Frang vor The Den schickt. Frang braucht gerissene Trollkrieger, die den Orcs zeigen, wie man mit mehr als bloßer Muskelkraft kämpft, und kann Euch für die kommenden Schlachten der Horde ausbilden.",al={"warum einfache schrifttafel","warum wird man von frang gebraucht","zweck der einfachen schrifttafel"}}},fp="13,85,19.269.0,26.116.0,21.121.0,27.83.0,25.98.0"}
P.entries["item:singed-scale"] = {n="Angesengte Schuppe",s="In Durotar bringen Krieger Angesengte Schuppen von den verkohlten Panzerplatten elektrisierter Donnerechsen, um ihre Ausdauer zu beweisen und Verteidigung zu erlernen.",h="In Durotar bringen Krieger Angesengte Schuppen von den verkohlten Panzerplatten elektrisierter Donnerechsen...",kw={"fernwacht","blitzbalg","path of defense","angesengte schuppe","donnerechse","donnergrat","uzzek"},ang={["class:Warrior"]="Als angehender Krieger macht Ihr mit der Übergabe der Schuppen an Uzzek einen entscheidenden Schritt, um Schutz zu erlernen und der Horde als undurchdringlicher Schild zu dienen.",["faction:Horde"]="An der Fernwacht stellen Prüfungen sicher, dass Wachen und Vorhut an den Grenzen Durotars und des Brachlands unerschütterliche Ausdauer besitzen."},sec={{t="Ein Test of Endurance",b="Veteranen der Horde beurteilen einen Krieger nach den Schlägen, die er erträgt, während er Verbündete schützt. Der Donnergrat ist eine Schlucht im westlichen Durotar, wo Blitzbälge und Donnerechsen vor Sturmenergie knistern. Sie zu jagen bedeutet, unerbittliche Stromschläge und zermalmende Hiebe auszuhalten. Ihre geschwärzten Schuppen zeigen, dass ein Kämpfer schweren Angriffen standhalten und unter Druck standhaft bleiben kann."},{t="Der Weg des Schildes",b="An der Fernwacht an der Grenze zwischen Durotar und dem Brachland verlangt der erfahrene Krieger Uzzek fünf Schuppen von den Initianden, bevor er sie unterrichtet. Er glaubt, dass sie körperliche Zähigkeit brauchen, bevor sie Haltungen und taktische Verteidigung erlernen können. Die Schuppen zu bringen beweist ihre nötige Stärke, um dicke Haut, schwere Rüstung und bedachte Beinarbeit zu einer festen Verteidigung gegen die Feinde der Horde zu vereinen."}},faq={{q="Wofür werden Angesengte Schuppen verwendet?",a="Angesengte Schuppen beweisen kriegerische Ausdauer. Uzzek, ein Kriegerlehrer, verlangt fünf davon, bevor er einem Initianden fortgeschrittene Verteidigungstechniken beibringt.",al={"angesengte schuppe verwendung","wer will angesengte schuppen","angesengte schuppe quest"}},{q="Wo findet man Angesengte Schuppen?",a="Ihr findet Angesengte Schuppen bei Donnerechsen und Blitzbälgen im Donnergrat, einer Schlucht im westlichen Durotar auf der anderen Flussseite vom Brachland aus gesehen.",al={"angesengte schuppe fundort","woher angesengte schuppen bekommen","wie angesengte schuppe bekommen"}},{q="Warum sind die Schuppen angesengt?",a="Donnerechsen leiten Blitze und elektrische Stürme durch ihre Körper. Das anhaltende Knistern elementarer Energie versengt und schwärzt ihre äußere Haut und verleiht den Schuppen ihre verkohlte Beschaffenheit.",al={"warum angesengt","warum sind die schuppen verbrannt"}},{q="Wer ist Uzzek und warum sind ihm diese Schuppen wichtig?",a="Uzzek ist ein erfahrener Krieger an der Fernwacht im östlichen Brachland. Er bildet aufstrebende Krieger der Horde im Verteidigungskampf aus und verlangt, dass sie zuerst ihre Widerstandskraft gegen tödliche Bestien beweisen.",al={"wer ist uzzek","uzzek"}}},fx={c263d0cb={q="Was ist eine Angesengte Schuppe?",a="Eine Angesengte Schuppe ist eine zähe Reptilienschuppe, die von den wilden Donner- und Blitz-Echsen stammt, die auf dem Donnergrat hausen. Da sie ständig vor natürlicher elektrischer Energie knistern, weisen diese Kreaturen Platten auf, die durch ihre eigenen gewaltsamen Blitzentladungen geschwärzt und vernarbt sind und eine verkohlte, aber bemerkenswert widerstandsfähige Rüstung hinterlassen.",al={"was ist eine angesengte schuppe","hintergrund zu angesengter schuppe","infos zu angesengten schuppen"}}},fp="12,138,19.371.0,21.395.0,32.137.0,32.142.0,26.201.0,53.197.0"}
P.entries["item:skeleton-finger"] = {n="Skelettfinger",s="Im Dämmerwald hinterlassen rastlose Tote Skelettfinger für Madame Eva aus Dunkelhain. Sie sammelt sie zusammen mit Ghulfängen und Spinnengift, um schützende Talismane herzustellen.",h="Im Dämmerwald hinterlassen rastlose Tote Skelettfinger für Madame Eva aus Dunkelhain.",kw={"dunkelhain","dämmerwald","ghulfangzahn","madame eva","skeletträuber","skelettfinger","totem des gegenschlages"},ang={["class:Mage"]="Als Magier, der volkstümliche Wahrsagekunst erforscht, mögt Ihr in Madame Evas Vergeltungszauber aus Skelettfingern und natürlichen Giften eine ungewöhnliche Mischung aus Volkshexerei und Sympathiemagie erkennen.",["class:Paladin"]="Als Paladin mögt Ihr davor zurückschrecken, Skelettüberreste zu entweihen und ihre abgetrennten Teile bei Euch zu tragen. In der unheilvollen Finsternis des Dämmerwalds ist es eine düstere Notwendigkeit, mit den Knochen der Unheiligen die Lebenden zu schützen."},sec={{t="Knochen der Rastlosen",b="Im ganzen Dämmerwald erheben sich Skeletträuber und Krieger, ebenso wie nekrotische Magier und Unholde. Die meisten Reisenden lassen ihre fauligen Überreste unberührt, doch Wahrsager und Mystiker schätzen ihre kalte Essenz. Madame Eva, die Seherin von Dunkelhain, sammelt ihre knöchernen Finger für das Totem des Gegenschlages. Sie bindet deren verbliebene nekrotische Energien in einen Schutzzauber, der Angreifer zurückschlägt."}},faq={{q="Welche Kreaturen hinterlassen einen Skelettfinger?",a="Skelettfinger stammen von Skeletträubern, Healers, Warders, Kriegern, Horrors, Unholden und Skeletal Mages im ganzen Dämmerwald.",al={"wo werden skelettfinger hinterlassen","was hinterlässt skelettfinger","skelettfinger herkunft"}},{q="Wer sucht im Dämmerwald nach Skelettfingern?",a="Madame Eva, die Seherin von Dunkelhain, braucht Skelettfinger, um einen Schutzzauber zu erschaffen.",al={"wer braucht skelettfinger","skelettfinger questgeber","wofür sind skelettfinger"}},{q="Was ist das Totem des Gegenschlages?",a="Madame Eva stellt das Totem des Gegenschlages aus Skelettfingern, Ghulfängen und Spinnengift her. Sie bindet deren dunkle Energien in eine Aura, die jedem schadet, der ihren Träger angreift.",al={"totem des gegenschlages zweck","was stellt madame eva her"}},{q="Warum braucht Madame Eva Überreste von Untoten für einen Schutzzauber?",a="Madame Eva nutzt in ihren Ritualen die anhaltende Verderbnis und Angriffslust der örtlichen Kreaturen. Sie bindet die gewalttätigen Essenzen der Skelette, Ghule und giftigen Bestien des Dämmerwalds in einen Schutzzauber, der Angreifer bestraft.",al={"warum knochenmagie","warum skelettfinger für das totem"}}},fx={["7c732e26"]={q="Was ist ein Skelettfinger?",a="Ein Skelettfinger ist ein abgetrenntes, ausgetrocknetes Knochenfragment, das von einem der belebten Skeletthorroren stammt, die durch die verdorbenen Wälder und Krypten des Dämmerwaldes wandern. Durch die nekrotische Verderbnis, die die Region befallen hat, bewahrt, behalten diese Finger Spuren der dunklen Magie, die die Untoten rastlos macht und in Bewegung hält.",al={"was ist ein skelettfinger","was sind skelettfinger","skelettfinger identifizieren"}},a7de6990={q="Woher stammt ein Skelettfinger?",a="Diese Finger stammen von den Skelettüberresten, die auf den verwunschenen Friedhöfen und in den Ruinen des Dämmerwaldes wiedererweckt wurden. Sie werden nicht hergestellt oder gefertigt, sondern direkt von den belebten Leichen – wie Skelettkriegern, Unholden, Wächtern und Plünderern – geerntet, die durch die Finsternis kriechen, belebt von der mysteriösen und schleichenden Verderbnis, die den Wald befällt.",al={"herkunft von skelettfinger","woher kommen skelettfinger","wer fertigte den skelettfinger"}}},fp="15,157,21.373.0,38.125.0,39.84.0,32.179.0,63.206.0"}
P.entries["item:skin-of-sweet-rum"] = {n="Schlauch mit süßem Rum",s="Im Gasthaus \"Zur Höhle des Löwen\" in Goldhain ist ein Schlauch mit süßem Rum für Seenhain bestimmt, wo der Krieg die Vorräte der Taverne dezimiert hat.",h="Im Gasthaus \"Zur Höhle des Löwen\" in Goldhain ist ein Schlauch mit süßem Rum für Seenhain bestimmt, wo der...",kw={"barkeeper daniels","dry times","goldhain","seenhain","gasthaus \"zur höhle des löwen\"","schlauch mit süßem rum","süßer rum"},ang={["faction:Alliance"]="Als Reisender der Allianz könnt Ihr sehen, wie die Invasion der Schwarzfelsorcs die kleinen Siedlungen belastet, die Sturmwinds östliche Grenzen verteidigen."},sec={{t="Ein seltener Trost für Seenhain",b="Der Taverne in Seenhain gehen die Getränke aus, da die Invasion der Schwarzfelsorcs die Straßen ins Rotkammgebirge versperrt. Barkeeper Daniels braucht Getränke für die Stadtwachen und Flüchtlinge. Deshalb schickt er Reisende los, um regionale Spezialitäten zu beschaffen, darunter einen Wasserschlauch mit süßem Rum aus dem Gasthaus \"Zur Höhle des Löwen\" in Goldhain."}},faq={{q="Wo kann ich einen Schlauch mit süßem Rum finden?",a="Ihr könnt einen Schlauch mit süßem Rum beim Gastwirt oder Schankwirt im Gasthaus \"Zur Höhle des Löwen\" in Goldhain im Wald von Elwynn kaufen.",al={"süßer rum fundort","wo süßen rum kaufen","wer verkauft süßen rum"}},{q="Wer möchte diesen Rum?",a="Barkeeper Daniels führt die Taverne in Seenhain. Er möchte einen Schlauch mit süßem Rum und andere regionale Getränke, um während Dry Times seine Regale wieder aufzufüllen.",al={"wer braucht süßen rum","süßen rum abgeben","süßer rum quest"}},{q="Warum geht Seenhain der Alkohol aus?",a="Die Invasion der Schwarzfelsorcs hat die Handelswege ins Rotkammgebirge abgeschnitten. Händlerwagen können nicht sicher reisen, und Seenhains Alkoholvorräte sind beinahe aufgebraucht.",al={"warum ist der alkohol ausgegangen","warum sitzt seenhain auf dem trockenen","dry times grund"}},{q="Welche anderen Spirituosen werden neben dem Rum benötigt?",a="Barkeeper Daniels braucht außerdem ein Fass Thunderbrew Lager aus Westfall, ein Fässlein mit Merlot aus Sturmwind und eine Flasche mit Fusel aus Dunkelhain.",al={"dry times getränke","daniels getränkeliste","welcher weitere alkohol wird benötigt"}}},fx={efbd5e13={q="Was ist ein Schlauch mit süßem Rum?",a="Ein Schlauch mit süßem Rum ist ein Lederschlauch, der mit zuckerhaltigem Likör gefüllt ist und in Goldhain im Wald von Elwynn verkauft wird. Er ist eine von mehreren regionalen Spezialitäten, die in den Menschenkönigreichen im südlichen Azeroth geschätzt werden.",al={"was ist süßer rum","infos zum schlauch mit süßem rum","süßer rum"}}},fp="17,123,28.311.0,37.117.0,19.140.0,39.152.0,48.148.0"}
P.entries["item:skittering-blood"] = {n="Huschendes Blut",s="Im Silberwald liefert Huschendes Blut der Royal Apothecary Society Material für ihre New Plague. Alchemisten der Verlassenen gewinnen es aus Spinnentieren im Huschdunkel, während sie nach einer Waffe gegen die Geißel und die Menschheit suchen.",h="Im Silberwald liefert Huschendes Blut der Royal Apothecary Society Material für ihre New Plague.",kw={"faranell","new plague","renferrel","royal apothecary society","silberwald","huschendes blut","das huschdunkel","skitterweb"},ang={["faction:Horde"]="Als Mitglied der Horde helft Ihr den Apothekern der Verlassenen, Lordaeron in ihrem Krieg gegen die Geißel mit selbst entwickelten Waffen zu sichern.",["race:Undead"]="Als Untoter helft Ihr Königin Sylvanas und der Royal Apothecary Society dabei, eine biologische Waffe gegen Arthas und die lebende Menschheit zu entwickeln."},sec={{t="Ein giftiges Destillat",b="Skitterweb lurkers, strikers und ihre Brutmutter Krethis the Shadowspinner liefern giftiges Blut. Apotheker Renferrel entdeckte, dass es, mit Giftstoffen aus den Herzen ergrauter Bären verfeinert, die Grundlage eines außergewöhnlich tödlichen Elixiers bildet. Seine kontaminierenden Wirkstoffe eignen sich auch für die chemischen Experimente des Apothekariums."},{t="Nährstoff für die New Plague",b="In Unterstadt leitet Apothekermeister Faranell die Suche der Royal Apothecary Society nach einer New Plague. Die Verlassenen stehen Horden der Geißel und feindseligen Überresten der Menschheit gegenüber, also setzen sie auf biologische Kriegsführung, um ihre Chancen auszugleichen. Faranell untersucht die Giftigkeit des Blutes, während er an einer Seuche arbeitet, die Unleben und lebendiges Fleisch gleichermaßen vernichten kann."}},faq={{q="Wofür wird Huschendes Blut verwendet?",a="Die Royal Apothecary Society verwendet Huschendes Blut bei ihrer Arbeit an der New Plague der Verlassenen. Mit Giftstoffen aus Bärenherzen vermengt, ergibt es eine instabile Mischung, die Apothekermeister Faranell für den Einsatz gegen die Geißel und lebende Menschen untersucht.",al={"huschendes blut verwendung","warum spinnenblut sammeln","was macht faranell mit huschendem blut"}},{q="Wo findet man Huschendes Blut?",a="Skitterweb lurkers, strikers und Krethis the Shadowspinner liefern Huschendes Blut im Huschdunkel und seiner Umgebung. Das düstere, von Spinnweben überwucherte Waldstück liegt im Nordwesten des Silberwalds.",al={"woher huschendes blut bekommen","huschendes blut fundort","wer lässt huschendes blut fallen"}},{q="Wer verlangt diese Proben?",a="Apotheker Renferrel beim Grabmal im Silberwald bittet um das Blut. Die Proben gehen an Apothekermeister Faranell im Apothekarium von Unterstadt.",al={"wer will huschendes blut","questgeber für huschendes blut"}},{q="Warum brauchen die Verlassenen Gift von heimischen Wildtieren?",a="Die Royal Apothecary Society gewinnt natürliche Giftstoffe aus Lordaerons verderbter Tierwelt. Das Gift der riesigen Spinnentiere des Silberwalds liefert rohe biologische Krankheitserreger, die konzentriert und zu synthetischen Seuchen als Waffen verarbeitet werden können.",al={"warum spinnengift","apotheker forschung an wildtieren"}}},fx={["8eea8a63"]={q="Was ist Huschendes Blut?",a="Huschendes Blut ist das virulente Ichors, das von den riesigen Spinnen geerntet wird, die im Huschdunkel des Silberwalds hausen. Es besitzt natürliche giftige und kontaminierende Eigenschaften, die es zu einem unschätzbaren biologischen Reagenz für alchemistische Experimente machen.",al={"was ist huschendes blut","gegenstand huschendes blut","über huschendes blut"}},f7d32240={q="Woher stammt Huschendes Blut und wer hat es hergestellt?",a="Es wird nicht hergestellt, sondern auf natürliche Weise von den räuberischen Spinnentieren gewonnen, die den nordwestlichen Silberwald bewohnen, darunter Skitterweb-Lauerer, Skitterweb-Angreifer und die Brutmutter Krethis die Schattenspinnerin. Das Blut wird von Jägern, die Gathering Materials für die Verlassenen sammeln, direkt aus ihren Kadavern extrahiert.",al={"woher kommt huschendes blut","wer erzeugte huschendes blut","ursprung von huschendem blut"}}},fp="16,224,18.307.0,22.345.0,34.245.0,32.185.0,27.156.0,49.221.0"}
P.entries["item:sleepers-key"] = {n="Schlüssel des Schläfers",s="Am Steinkrallengipfel hilft der Schlüssel des Schläfers, eine heilige druidische Schatzkammer zu schützen. Nachtelfendruiden schufen ihn als einen von drei verzauberten Schlüsseln für den Hort im Krallenbau.",h="Am Steinkrallengipfel hilft der Schlüssel des Schläfers, eine heilige druidische Schatzkammer zu schützen.",kw={"torhüterschlüssel","sleepers' cache","schlüssel des schläfers","der steinkrallengipfel","krallenbau","hort im krallenbau","the den"},ang={["class:Druid"]="Als Druide könnt Ihr erkennen, wie die Schlüssel und Verstecke des Krallenbaus mehrere Schutzschichten bilden. Verborgene Verstecke und Schlüsselschlösser halten mächtige Relikte unter Verschluss.",["faction:Horde"]="Als Mitglied der Horde beschafft Ihr den Schlüssel des Schläfers im Rahmen eines koordinierten Überfalls ins Herz des Steinkrallengipfels. Der Überfall beseitigt die Schutzbanne der Nachtelfen, um die in ihrem Hort versiegelten Relikte zu erbeuten."},sec={{t="Ein druidischer Schutz",b="Der Krallenbau ist eine Zuflucht und ein Sanktum für die Druiden Kalimdors auf dem Steinkrallengipfel. Nachtelfische Hüter legten Schlösser und verborgene Verstecke an, um heilige Relikte und mächtige Schätze vor unerwünschter Aufmerksamkeit zu schützen. Der Schlüssel des Schläfers ist einer von drei Schlüsseln, die einen Schutzbann bilden.\n\nDer Schlüssel des Schläfers ruht in einem abgelegenen Versteck tief im Bau. Der Torhüterschlüssel, der nahe der Schwelle verborgen ist, öffnet dieses Versteck. Der Klauenschlüssel und der Grabhügelschlüssel vervollständigen den Satz. Setzt alle drei Schlüssel in die Steinschlösser des Horts im Krallenbau ein, und der Schutzbann schwindet. Uralte Gegenstände liegen darin."}},faq={{q="Wofür wird der Schlüssel des Schläfers verwendet?",a="Der Schlüssel des Schläfers öffnet gemeinsam mit dem Grabhügelschlüssel und dem Klauenschlüssel den Hort im Krallenbau. Die mit einem Schutzbann versehene steinerne Schatzkammer liegt tief im Grabhügelbau auf dem Steinkrallengipfel.",al={"was bewirkt der schlüssel des schläfers","zweck des schlüssels des schläfers","schlüssel zum hort im krallenbau"}},{q="Wie wurde der Schlüssel des Schläfers weggeschlossen?",a="Die Druiden legten den Schlüssel des Schläfers in die Sleepers' Cache in den nordwestlichen Tunneln des Krallenbaus. Der Torhüterschlüssel öffnet sie. Die Druiden versteckten diesen Schlüssel in einer unscheinbaren Laterne nahe dem Eingang des Baus.",al={"wo ist der schlüssel des schläfers","sleepers' cache öffnen","torhüterschlüssel voraussetzung"}},{q="Warum verbargen die Druiden ihre Relikte hinter mehreren Schlüsseln?",a="Die Nachtelfendruiden errichteten ausgeklügelte Schutzvorkehrungen, damit ihre mächtigen Gegenstände und heiligen Erbstücke bei einem Angriff auf den Bau nicht in feindliche Hände fielen. Indem sie die Schlüssel in getrennten Verstecken verbargen, erschwerten sie Eindringlingen die Plünderung des Horts.",al={"warum so viele schlüssel","verteidigung des krallenbaus","rätsel um den druidischen hort"}},{q="Warum heißt er Schlüssel des Schläfers?",a="Die Druiden erklären den Namen nie. Der Schlüssel des Schläfers teilt seinen Namen mit der Sleepers' Cache, der verborgenen Truhe im Krallenbau, in der der Schlüssel aufbewahrt wird.",al={"wer sind die schläfer","namensbedeutung schlüssel des schläfers"}}},fx={["0a862a33"]={q="Was ist der Schlüssel des Schläfers?",a="Der Schlüssel des Schläfers ist einer von drei speziellen Schlüsseln, die von den Nachtelfendruiden des Steinkrallengipfels gefertigt wurden. Er ist in einem verschlossenen Versteck tief im Krallenbau verborgen und bildet einen wesentlichen Bestandteil des Schutzsystems, das den zentralen Hort heiliger Relikte der Druiden bewacht.",al={"was ist der schlüssel des schläfers","hintergrund zum schlüssel des schläfers","über den schlüssel des schläfers"}},["8275ad63"]={q="Woher stammt der Schlüssel des Schläfers und wer hat ihn hergestellt?",a="Der Schlüssel wurde von den Druiden gefertigt, die den Krallenbau auf dem Steinkrallengipfel errichteten. Um ihre mächtigen Artefakte vor Eindringlingen zu schützen, entwickelten sie ein kompliziertes Sicherheitssystem und sicherten den Schlüssel in einer speziellen Truhe, dem Versteck des Schläfers.",al={"wer fertigte den schlüssel des schläfers","ursprung des schlüssels des schläfers","woher stammt der schlüssel des schläfers"}},["3884172c"]={q="Warum will jemand den Schlüssel des Schläfers?",a="Die Horde sucht den Schlüssel, um die vielschichtigen Verteidigungsanlagen der Druiden zu umgehen und den Hort im Krallenbau zu öffnen. Zusammen mit dem Klauenschlüssel und dem Grabhügelschlüssel öffnet er das steinerne Gewölbe, in dem die mächtigen Relikte aufbewahrt werden, die die Druiden auf dem Steinkrallengipfel versteckt haben.",al={"warum den schlüssel des schläfers finden","warum den schlüssel des schläfers brauchen","wer will den schlüssel des schläfers"}}},fp="13,149,19.546.0,35.148.0,38.200.0,56.237.0,35.141.0"}
P.entries["item:smoky-iron-ingot"] = {n="Rauchiger Eisenblock",s="In Windshear schmelzen Kobolde Rauchige Eisenblöcke aus Erz aus dem Steinkrallengebirge. Orkische Rüstungsschmiede schätzen die Barren für robuste Kettenrüstung für Krieger der Horde.",h="In Windshear schmelzen Kobolde Rauchige Eisenblöcke aus Erz aus dem Steinkrallengebirge.",kw={"brutal armor","kobold","rauchiger eisenblock","steinkrallengebirge","thun'grim firegaze","krieger","windshear"},ang={["class:Warrior"]="Für Krieger der Horde stellt das Sammeln dieser Blöcke die Ausdauer im Steinkrallengebirge auf die Probe. Die Barren werden benötigt, um den Brutal Hauberk zu schmieden.",["profession:Blacksmithing"]="Diese Blöcke zeigen, wie Koboldgräber Metall mit primitiven Methoden schmelzen, während ausgebildete Schmiede verfeinerte Techniken anwenden."},sec={{t="Grobe Metallurgie der Kobolde",b="Kobolde schmelzen Rauchige Eisenblöcke in den Tunneln der Scherwindklippe im Steinkrallengebirge. Sie fördern Erz aus den felsigen Hängen und erhitzen es über primitiven, rauchenden Feuern. Rückstände und Holzkohle haften an den Barren, doch das Metall bleibt dicht und fest."},{t="Das Schmieden der Brutal Armor",b="Thun'grim Brandblick ist ein nahezu blinder orkischer Rüstungsschmied in einem kargen Lager mit Blick auf das Brachland. Er verlangt nach diesen Blöcken, um Rüstungen für bewährte Krieger der Horde herzustellen. Zusammen mit veredelten Eisenbarren, Pulverisiertem Azurit und flüchtigem Phlogiston bildet das rauchige Metall einen widerstandsfähigen Kern für Brutal Hauberks."}},faq={{q="Woher stammen Rauchige Eisenblöcke?",a="Kobolde in den Grabungsstätten und Tunneln von Windshear im östlichen Steinkrallengebirge tragen Rauchige Eisenblöcke bei sich. Zu ihnen gehören Gräber, Steinmetze, Gezücht, Geomanten und ihre Oberanführer.",al={"wo rauchigen eisenblock finden","rauchiger eisenblock fundort","wer lässt rauchige eisenblöcke fallen"}},{q="Wofür werden Rauchige Eisenblöcke verwendet?",a="Krieger, die Thun'grim Firegazes Ruf folgen, sammeln Rauchige Eisenblöcke. Der Rüstungsschmiedemeister lebt auf den Gipfeln nahe dem Wegekreuz im Brachland und benötigt fünfzehn Blöcke, um den Brutal Hauberk zu schmieden.",al={"rauchiger eisenblock verwendung","wofür ist rauchiger eisenblock","brutal armor questgegenstand"}},{q="Warum werden die Blöcke als „rauchig“ bezeichnet?",a="Kobolde nutzen primitive, schwach brennende Feuer, um in ihren düsteren Tunneln Metall zu schmelzen. Ruß, Holzkohlestaub und Asche haften an den Blöcken und nehmen ihnen den sauberen Glanz.",al={"warum ist er rauchig","rauchiges eisen hintergrundgeschichte"}},{q="Kann jeder Schmied diese Blöcke verarbeiten?",a="Nein. Die unregelmäßigen, rußverkrusteten Barren eignen sich nicht für das gewöhnliche Schmiedehandwerk. Nur Schmiede wie Thun'grim Brandblick wissen, wie sie daraus maßgefertigte Kampfausrüstung herstellen können.",al={"können spieler rauchiges eisen schmieden","ist rauchiges eisen eine handelsware"}}},fx={["9ee5c553"]={q="Woher stammt der Rauchige Eisenblock und wer hat ihn hergestellt?",a="Diese Barren werden von den Kobolden der Scherwindklippe in den Steinkrallengebirgen abgebaut und geschmolzen. Tief in ihren unterirdischen Tunneln fördern Gräber und Ungeziefer das Roherz und gießen es zu brauchbaren Eisenblöcken, um ihre unterirdischen Operationen zu verstärken und ihre Kriegstrupps zu bewaffnen.",al={"quelle des rauchigen eisenblocks","woher kommen rauchige eisenblöcke","wer fertigt rauchige eisenblöcke"}},["18404e72"]={q="Was ist ein Rauchiger Eisenblock?",a="Rauchige Eisenblöcke sind grob verhüttete Barren aus dunklem, rußgestreiftem Eisen, die bei den Windshear-Kobolden zu finden sind, deren Tunnel tief ins Steinkrallengebirge reichen. Im Vergleich zu veredelten Metallerzeugnissen sind sie grob, besitzen aber dennoch die Widerstandskraft, die geschickte Schmiede für schwere, langlebige Rüstungen benötigen.",al={"was ist ein rauchiger eisenblock","rauchiger eisenblock informationen","wissenswertes über rauchige eisenblöcke"}},["8ab45f92"]={q="Warum werden Rauchige Eisenblöcke gebraucht?",a="Der fast blinde Orcschmiedemeister Thun'grim Brandblick, der oben auf den Anhöhen des Brachlands lebt, benötigt fünfzehn dieser Blöcke, um Brutal Armor für würdige Krieger der Horde anzufertigen. Zusammen mit anderen seltenen alchemistischen und mineralischen Stoffen dient das grobe Metall als Grundmaterial für eine Rüstung, die brutaler Kriegsführung standhalten soll.",al={"warum rauchige eisenblöcke beschaffen","wer will rauchige eisenblöcke","rauchiger eisenblock verwendung hintergrund"}}},fp="16,164,23.242.0,24.281.0,37.182.0,36.194.0,40.159.0,43.166.0"}
P.entries["item:smoldering-embers"] = {n="Glimmende Überreste",s="Im Verbrannten Tal bleiben Glimmende Überreste zurück, wenn Feuerelementare ausgelöscht werden. Nachtelfen-Schildwachen sammeln sie als Beweis dafür, dass die Feuer eingedämmt werden.",h="Im Verbrannten Tal bleiben Glimmende Überreste zurück, wenn Feuerelementare ausgelöscht werden.",kw={"brennender zerstörer","brennender verheerer","das verbrannte tal","enraged spirits","kaela schattenspeer","abtrünniger flammengeist","glimmende überreste","steinkrallengebirge","venture co"},ang={["class:Druid"]="Als Druide seht Ihr in den Überresten einen tragischen Beweis dafür, dass industrielle Gier die Natur aus dem Gleichgewicht gebracht hat. Elementare Wut hindert den ascheerstickten Boden daran, sich zu regenerieren.",["race:NightElf"]="Für Nachtelfen ist der Brand des Verbrannten Tals eine Wunde in Kalimdor. Seine Überreste zu sammeln ist eine ernste Pflicht, um die Schändung durch Fremde zu tilgen und unter Elunes Blick Frieden wiederherzustellen."},sec={{t="Überreste des Verbrannten Tals",b="Holzeinschlag und Industrie der Venture Company setzten das Verbrannte Tal in Brand. Ihre Arbeit weckte zerstörerische Kräfte tief in der Erde. Brennende Verheerer, Brennende Zerstörer und Abtrünnige Flammengeister fegten über das versengte Becken hinweg. Wenn ein Feuerelementar ausgelöscht wird, bleibt ein aschebedeckter Kern zurück. Dieser glimmende Rest zählt zu den Glimmenden Überresten, die beweisen, dass die im Tal wütenden Feuer unter Kontrolle gebracht werden."}},faq={{q="Woher stammen die Glimmenden Überreste?",a="Glimmende Überreste stammen von Feuerelementaren im Verbrannten Tal im südlichen Steinkrallengebirge. Brennende Verheerer, Brennende Zerstörer und Abtrünnige Flammengeister hinterlassen sie.",al={"wo glimmende überreste finden","wer hinterlässt glimmende überreste","herkunft glimmender überreste"}},{q="Warum will Kaela Schattenspeer diese Überreste?",a="Kaela Schattenspeer will die Überreste als Beweis dafür, dass die Feuerelementare im Verbrannten Tal dezimiert werden. Sie glaubt, dass das gezeichnete Land unter Elune's Grace nicht heilen kann, solange gewalttätige Geister ungehindert umherstreifen.",al={"warum glimmende überreste sammeln","kaela schattenspeer überreste","enraged spirits ziel"}},{q="Was ließ die Feuerelementare im Verbrannten Tal erscheinen?",a="Die Venture Company brachte Feuerelementare ins Verbrannte Tal, indem sie den uralten Wald mit rücksichtslos eingesetzten Maschinen und wahllosen Brandrodungen abholzte. Ihre rücksichtslose Arbeit destabilisierte das Land und entfesselte feindselige Elementare aus Flammen und Stein. Diese Kräfte vertrieben die Goblins.",al={"was geschah mit dem verbrannten tal","warum feuerelementare im steinkrallengebirge","venture co feuergeister"}}},fx={["4d13fc7e"]={q="Was sind Glimmende Überreste?",a="Glimmende Überreste sind die brennenden physischen Überreste, die von den zerstörerischen Feuerelementaren zurückgelassen werden, die das verbrannte Tal befallen. Diese glühenden Überreste bleiben zurück, nachdem Kreaturen wie Brennende Verheerer, Schurkenflammengeister und Brennende Zerstörer erschlagen wurden, und dienen als greifbarer Beweis dafür, dass ihr feuriger Amoklauf durch den verwüsteten Wald beendet wurde.",al={"was sind glimmende überreste","hintergrund zu glimmenden überresten","was ist eine glimmende überreste"}}},fp="17,159,28.404.0,37.182.0,45.208.0,62.277.0"}
P.entries["item:snellig-s-snuffbox"] = {n="Snelligs Schnupftabakdose",s="Bei der verlorenen Flotte bleibt Snelligs Schnupftabakdose bei ihrem untoten Besitzer zwischen den Wracks. Erster Maat Fitzsimmons im Hafen von Menethil will sie als Beweis dafür, dass sein verfluchter Schiffskamerad Ruhe gefunden hat.",h="Bei der verlorenen Flotte bleibt Snelligs Schnupftabakdose bei ihrem untoten Besitzer zwischen den Wracks.",kw={"verfluchte besatzung","fitzsimmons","kul tiras","die verlorene flotte","snellig","schnupftabakdose","third fleet","sumpfland"},ang={["faction:Alliance"]="Als Abenteurer der Allianz ist es Eure düstere Pflicht gegenüber einem alten Verbündeten zur See, die Habseligkeiten gefallener Seeleute der Kul Tiraner zu bergen und ihren verfluchten Geistern Ruhe zu schenken."},sec={{t="Ein Andenken der Third Fleet",b="First Mate Snellig umklammert noch immer seine Schnupftabakdose in einem Wrack vor dem nördlichen Sumpfland. Die Third Fleet von Kul Tiras lief dort auf Grund, und ihre Seeleute und Offiziere ertranken durch eine geheimnisvolle Macht, die mit einem verborgenen Schatz an Bord der Schiffe verbunden war. An diese Macht gebunden, erhob sich die ertrunkene Besatzung erneut als gequälte Geister und skelettartige Untote.\n\nSnellig sucht den verrottenden Frachtraum des Wracks heim, das der Küste am nächsten liegt. Seine Schnupftabakdose ist ein gewöhnliches Andenken an sein sterbliches Leben auf See. Erster Maat Fitzsimmons, der einzige lebende Überlebende der Katastrophe, will sie als Beweis dafür zurückhaben, dass zumindest ein verlorener Schiffskamerad von seinen Qualen erlöst wurde."}},faq={{q="Was ist Snelligs Schnupftabakdose?",a="First Mate Snellig besaß einst den kleinen, persönlichen Behälter namens Snelligs Schnupftabakdose. Sein untoter Überrest trägt sie an Bord eines Schiffswracks vor der nördlichen Küste des Sumpflands bei sich.",al={"was ist dieser gegenstand","snelligs schnupftabakdose","schnupftabakdose"}},{q="Wo finde ich Snelligs Schnupftabakdose?",a="Ihr könnt die Schnupftabakdose von First Mate Snellig erbeuten, der den Frachtraum des küstennächsten Schiffswracks bei der verlorenen Flotte im nordwestlichen Sumpfland heimsucht.",al={"wo lässt snellig die schnupftabakdose fallen","snellig finden","first mate snellig fundort"}},{q="Wer will diese Schnupftabakdose?",a="Erster Maat Fitzsimmons will, dass Ihr ihm die Schnupftabakdose zum Hafen von Menethil bringt. Der einzige lebende Überlebende der Third Fleet bittet darum als Beweis dafür, dass Snellig Ruhe gefunden hat.",al={"wer nimmt die schnupftabakdose","bei wem abgeben","fitzsimmons quest"}},{q="Warum ist First Mate Snellig verflucht?",a="Fitzsimmons sagt, ein dunkler, schrecklicher Schatz, der an Bord eines der Schiffe der Third Fleet verborgen war, habe die Besatzungen beim Schiffbruch ins Verderben gestürzt. Ihre Seelen bleiben im verrottenden Holz gefangen, und ihnen wird die Ruhe verwehrt.",al={"warum ist snellig untot","fluch der verlorenen flotte","fluch der third fleet"}}},fp="18,184,29.620.0,27.168.0,35.152.0,24.167.0,33.194.0"}
P.entries["item:snufflenose-command-stick"] = {n="Schnüffelnasenleitstecken",s="In Ratschet schickt Mebok Mizzyrix trainierte Murmeltiere in den Kral der Klingenhauer, um Blaulaubknollen zu finden.",h="In Ratschet schickt Mebok Mizzyrix trainierte Murmeltiere in den Kral der Klingenhauer, um Blaulaubknollen zu...",kw={"blaulaubknolle","leitstecken","murmeltier","mebok mizzyrix","ratschet","kral der klingenhauer","schnüffelnase","brachland"},ang={["profession:Cooking"]="Blaulaubknollen werden auf der ganzen Welt als kulinarische Delikatesse geschätzt. Um sie zu finden, braucht Ihr ein trainiertes Tier und einen Leitstecken statt gewöhnlicher Küchenutensilien."},sec={{t="Ein Stecken für Nager",b="Mebok Mizzyrix hat Schnüffelnasenmurmeltiere darauf trainiert, tief im Kral der Klingenhauer nach Blaulaubknollen zu suchen. Die Wurzeln liegen unter dornigen Tunneln verborgen, wo sie ohne Hilfe kaum zu finden sind. Mebok ist ein Händler in Ratschet und vermeidet es, selbst die Höhlen der Quilboar zu betreten. Deshalb gibt er Abenteurern den Schnüffelnasenleitstecken, um die Murmeltiere zu lenken. Aus bis zu fünfzig Schritt Entfernung weist der Stecken sie an, die Wurzeln zu erschnüffeln und freizulegen."}},faq={{q="Wozu dient der Schnüffelnasenleitstecken?",a="Der Schnüffelnasenleitstecken führt ein trainiertes Schnüffelnasenmurmeltier zu verborgenen Blaulaubknollen im Kral der Klingenhauer. Richtet ihn auf ein Murmeltier, und es folgt der Witterung, um die Wurzeln auszugraben.",al={"leitstecken benutzen","was bewirkt der leitstecken","zweck des leitsteckens"}},{q="Wo erhaltet Ihr den Schnüffelnasenleitstecken?",a="Ihr erhaltet den Schnüffelnasenleitstecken in Ratschet, direkt vor Mebok Mizzyrix' Werkstatt. Dazu gehören eine Kiste mit einem trainierten Murmeltier und eine Gebrauchsanweisung.",al={"wo gibt es den leitstecken","fundort des leitsteckens","wer gibt den leitstecken"}},{q="Warum will Mebok Mizzyrix Blaulaubknollen haben?",a="Mebok Mizzyrix sucht Blaulaubknollen, weil diese seltenen Delikatessen bei wohlhabenden kulinarischen Kontakten auf der ganzen Welt beträchtlichen Gewinn einbringen. Sie wachsen tief unter dem Brachland im Gebiet der Quilboar, also heuert er Abenteurer an, um sie zu sammeln.",al={"warum knollen","zweck der blaulaubknolle","warum will mebok knollen"}},{q="Dürft Ihr den Stecken behalten, nachdem Ihr die Knollen gefunden habt?",a="Nein. Nachdem Ihr die gewünschten Knollen gesammelt habt, bringt Ihr den Schnüffelnasenleitstecken und die Transportkiste samt Eurer Ernte zu Mebok in Ratschet zurück.",al={"leitstecken behalten","leitstecken zurückgeben"}}},fx={["8cc828c2"]={q="Was ist ein Schnüffelnasenleitstecken?",a="Der Schnüffelnasenleitstecken ist das patentierte Handhabungswerkzeug von Snuff Inc., das mit den trainierten Gophern des Goblin-Unternehmers Mebok Mizzyrix in Ratschet geliefert wird. Er wurde speziell entwickelt, um trainierte Schnüffelnasengopher zu leiten und ihnen das Signal zu geben, vergrabene, schwer zu findende Delikatessen aufzuspüren, die ein gewöhnlicher Späher völlig übersehen würde.",al={"was ist ein leitstecken","schnüffelnasenleitstecken","was ist der schnüffelnasenleitstecken"}},["9fdd5faa"]={q="Woher stammt der Schnüffelnasenleitstecken und wer hat ihn hergestellt?",a="Der Leitstecken ist ein patentiertes Produkt von Snuff Inc., dessen Eigentümer Marwig Rustbolt den Gebrauch in der Schnüffelnasenbesitzeranleitung erklärt. Mebok Mizzyrix in Ratschet trainierte seine Schnüffelnasengopher, um seltene Delikatessen zu ernten, und hält die Leitstecken, Kisten und Handbücher zusammen, damit angeheuerte Helfer die Kreaturen ordnungsgemäß kontrollieren können.",al={"wer fertigte den leitstecken","ursprung des leitsteckens","woher stammt der leitstecken"}},fb1cfa60={q="Warum will jemand den Schnüffelnasenleitstecken?",a="Seltene Blaulaubknollen sind unter dem Brombeergestrüpp im Kral der Klingenhauer ohne Hilfe unmöglich zu entdecken. Der Leitstecken ist entscheidend, weil er einen trainierten Schnüffelnasengopher dazu zwingt, fünfzig Schritte weit zu schnüffeln und die Knollen auszugraben, die dann für eine stattliche Belohnung an Mebok Mizzyrix zurückgegeben werden können.",al={"warum brauchst du den stecken","warum ist der leitstecken gesucht","warum schnüffelnasenleitstecken besorgen"}}},fp="25,93,17.432.0,47.178.0,50.166.0,45.247.0,54.141.0"}
P.entries["item:snufflenose-owner-s-manual"] = {n="Schnüffelnasenbesitzeranleitung",s="Neben Mebok Mizzyrix in Ratschet zeigt die Schnüffelnasenbesitzeranleitung, wie man einen abgerichteten Gopher im Kral der Klingenhauer nach Blaulaubknollen suchen lässt. Marwig Rustbolt von Snuff Inc. schrieb sie zu diesem Zweck.",h="Neben Mebok Mizzyrix in Ratschet zeigt die Schnüffelnasenbesitzeranleitung, wie man einen abgerichteten...",kw={"blaulaubknolle","gopher","anleitung","mebok mizzyrix","ratschet","kral der klingenhauer","snufflenose"},ang={["profession:Cooking"]="Die Anleitung erklärt, wie man Blaulaubknollen birgt, eine unterirdische Wurzel, die Feinschmecker und Händler in ganz Azeroth als seltene Delikatesse schätzen."},sec={{t="Die Betriebsanleitung eines Goblins",b="Marwig Rustbolt von Snuff Inc. schrieb den Leitfaden für den Umgang mit den abgerichteten Snufflenose Gophers des Unternehmens. Ihre feinen Nasen können unterirdisch vergrabene Blaulaubknollen aus fünfzig Schritt Entfernung aufspüren. Die Anleitung zeigt, wie man einen Gopher aus einer belüfteten Kiste freilässt und sein Wühlen mit einem Befehlsstab lenkt. Goldsucher führen ihn auf der Suche nach Knollen durch die Dornen und Borstennackentunnel des Krals der Klingenhauer."}},faq={{q="Welchen Zweck hat die Schnüffelnasenbesitzeranleitung?",a="Die Anleitung zeigt, wie man Mebok Mizzyrix' abgerichteten Snufflenose Gopher aus seiner Kiste freilässt und mit einem Befehlsstab lenkt. Der Gopher sucht im Kral der Klingenhauer nach Blaulaubknollen.",al={"was erklärt die anleitung","warum die anleitung lesen","zweck der anleitung"}},{q="Wo finde ich die Anleitung?",a="Ihr findet die Anleitung in Ratschet neben Mebok Mizzyrix, den Kisten und den Befehlsstäben, die zum Sammeln von Knollen verwendet werden.",al={"fundort der anleitung","wo ist das buch","wie die anleitung bekommen"}},{q="Warum braucht man Snufflenose Gophers, um Blaulaubknollen zu finden?",a="Blaulaubknollen liegen tief im Kral der Klingenhauer vergraben, wo Humanoide sie kaum erkennen können. Ein abgerichteter Gopher kann eine solche Knolle aus fünfzig Schritt Entfernung riechen.",al={"warum gophers einsetzen","knollen ohne gophers finden"}},{q="Wer hat die Anleitung geschrieben?",a="Marwig Rustbolt, Besitzer von Snuff Inc., hat die Anleitung unterzeichnet. Er schrieb sie, um neuen Besitzern beizubringen, wie sie ihre Gophers füttern, ausführen und mit dem patentierten Befehlsstab befehligen.",al={"verfasser der anleitung","wer hat sie verfasst"}}},fx={["1c231f00"]={q="Was ist die Schnüffelnasenbesitzeranleitung?",a="Es ist ein Anleitungshandbuch, das zusammen mit einem trainierten Schnüffelnasengopher und einem Leitstecken bereitgestellt wird. Das Handbuch führt Abenteurer in die Handhabung der Kreatur in den unterirdischen Tunneln des Kral der Klingenhauer ein und erklärt, wie man den Gopher dazu bringt, schwer zu findende unterirdische Blaulaubknollen aufzuspüren.",al={"was ist die schnüffelnasenbesitzeranleitung","identität der schnüffelnasenanleitung","was ist das handbuch"}}},fp="26,193,26.388.0,54.184.0,28.114.0,59.142.0,21.165.0"}
P.entries["item:sodium-nitrate"] = {n="Natriumnitrat",s="In Bael Modan nutzen Zwerge Natriumnitrat für Sprengladungen gegen das Gestein des südlichen Brachlands. Gann Steinkeil sucht die Chemikalie für Sprengladungen gegen die Festung.",h="In Bael Modan nutzen Zwerge Natriumnitrat für Sprengladungen gegen das Gestein des südlichen Brachlands.",kw={"bael modan","bael'dun","blackforge","gann steinkeil","nitroglyzerin","revenge of gann","natriumnitrat","holzbrei"},ang={["profession:Engineering"]="Ingenieure erkennen in Natriumnitrat, Nitroglycerin und Holzbrei das Rezept für stabilisiertes Dynamit, die Grundlage von Ganns behelfsmäßigen Sprengladungen.",["race:Tauren"]="Als Tauren greift Gann Steinkeil auf zwergische Chemikalien zurück, um die Zerstörung seines angestammten Landes zu vergelten."},sec={{t="Industrielle Sprengungen",b="In Bael Modan nutzen zwergische Ausgräber Natriumnitrat, um das Gestein des südlichen Brachlands aufzubrechen. Die Bael'dun-Expedition drang mit Erdbewegungsmaschinen und Sprengreagenzien in das angestammte Land des Stonespire-Stammes ein. Schützen, Soldaten und Offiziere tragen die Chemikalie innerhalb der Ausgrabungsstätte und in der nahe gelegenen Festung bei sich."},{t="Wende und Vergeltung",b="Gann Steinkeil beobachtete die Eindringlinge, nachdem sie die Heimat seines Stammes verwüstet hatten, und erbeutete ihre Konstruktionspläne. Gewöhnliche Angriffe konnten die verteidigte Festung nicht bezwingen, also wendet der verbannte Tauren die Sprengvorräte der Zwerge gegen sie. Er mischt erbeutetes Natriumnitrat mit Nitroglyzerin und Holzbrei zu Sprengladungen, die Bael Modans Grundmauern erschüttern sollen."}},faq={{q="Wofür wird Natriumnitrat im Brachland verwendet?",a="Zwerge aus Eisenschmiede verwenden Natriumnitrat in Sprengstoffen, um felsigen Boden an ihrer Ausgrabungsstätte aufzusprengen. Gann Steinkeil mischt es mit Nitroglyzerin und Holzbrei zu Sprengladungen gegen Bael Modan.",al={"natriumnitrat verwendung","was bewirkt natriumnitrat"}},{q="Woher stammt Natriumnitrat?",a="Zwergische Truppen, die in Bael Modan im südlichen Brachland stationiert sind, tragen Natriumnitrat bei sich. Schützen, Soldaten, Offiziere und Befehlshaber wie Lord Cyrik Blackforge halten es bereit.",al={"wer lässt natriumnitrat fallen","wo gibt es natriumnitrat"}},{q="Warum braucht Gann Steinkeil diese Chemikalie?",a="Gann Steinkeil verlor das Dorf seiner Vorfahren durch die Ausgrabungen der Zwerge. Ohne schweres Belagerungsgerät studierte er ihre Konstruktionspläne und machte sich daran, aus zwergischen Vorräten Sprengladungen herzustellen, die ihre befestigten Stellungen durchbrechen könnten.",al={"warum will gann natriumnitrat","gann steinkeil sprengstoff"}},{q="Ist Natriumnitrat allein schon gefährlich?",a="Für sich genommen ist Natriumnitrat ein Oxidationsmittel und chemisches Salz, kein sofort explodierender Sprengstoff. Vermischt mit einem Brennstoff und stoßempfindlichen Chemikalien wie Nitroglyzerin wird es gefährlich und instabil.",al={"ist natriumnitrat ein sprengstoff"}}},fx={caaef0db={q="Was ist Natriumnitrat?",a="Natriumnitrat ist ein flüchtiges chemisches Mittel, das von den Zwergenexpeditionstruppen gelagert wird, die in Bael Modan stationiert sind. Während es bei der Lagerung relativ stabil ist, verlassen sich die Zwerge darauf als Kernkomponente für die Zusammenstellung hochgradiger Sprengladungen, die verwendet werden, um massiven Stein an ihren Ausgrabungsstätten zu sprengen. In den Händen eines cleveren Saboteurs kann es jedoch genauso leicht umfunktioniert werden, um die Festung selbst zu zerstören.",al={"was ist natriumnitrat","hintergrund zu natriumnitrat","natriumnitrat im brachland"}}},fp="14,175,21.313.0,25.375.1,47.185.0,36.176.0,44.233.0,39.199.0"}
P.entries["item:solomon-s-plea-to-darkshire"] = {n="Solomons Hilfegesuch an Dunkelhain",s="Seenhain wendet sich an Dunkelhain, während die Bedrohungen näher rücken. Magistrat Solomon bittet Lord Ello Schwarzhaupt, die Nachtwache nach Norden zu schicken, um das Rotkammgebirge zu verteidigen.",h="Seenhain wendet sich an Dunkelhain, während die Bedrohungen näher rücken.",kw={"dunkelhain","dämmerwald","seenhain","lord ello schwarzhaupt","magistrat solomon","botschaft nach dunkelhain","night watch","rotkammgebirge","solomons hilfegesuch"},ang={["faction:Alliance"]="Für die Allianz zeigt Solomons Hilfegesuch, wie die südlichen Siedlungen einander um Hilfe bitten, während Sturmwind kaum Unterstützung leistet.",["race:Human"]="Als menschlicher Reisender tragt Ihr eine Depesche bei Euch, die von der Gefahr für das Rotkammgebirge und den Dämmerwald kündet."},sec={{t="Ein verzweifelter Hilferuf",b="Schwarzfelsorcs, Gnolle und Murlocs greifen Seenhain an, während kaum Verstärkung aus Sturmwind eintrifft. Magistrat Solomon schickt ein förmliches Hilfegesuch an Bürgermeister Ello Schwarzhaupt in Dunkelhain und bittet ihn, die Miliz der Nachtwache nach Norden ins Rotkammgebirge zu entsenden. Da die zentrale militärische Unterstützung im gesamten Süden Azeroths versagt, müssen menschliche Siedlungen einander um Hilfe bitten, um zu überleben."},{t="Dunkelhains düstere Lage",b="Dunkelhain ringt darum, seine Grenzen gegen Untote, gefräßige Bestien und die Finsternis zu halten, die den Dämmerwald umklammert. Die Nachtwache ist bis an ihre Grenzen gefordert, sodass die Stadt keine Verteidiger für das Rotkammgebirge entbehren kann, als Solomons Hilfegesuch eintrifft."}},faq={{q="Was ist Solomons Hilfegesuch an Dunkelhain?",a="Im dringenden Brief an Lord Ello Schwarzhaupt bittet Magistrat Solomon die Nachtwache, das Rotkammgebirge gegen Schwarzfelsorcs und Gnolle zu verteidigen.",al={"solomons brief an dunkelhain","was ist solomons hilfegesuch","brief aus seenhain an den dämmerwald"}},{q="Warum bittet Seenhain Dunkelhain statt Sturmwind um militärische Hilfe?",a="Angesichts politischer Untätigkeit und innerer Unruhen hat Sturmwind nur wenige Garnisonstruppen in seine abgelegenen Gebiete entsandt. Mit zunehmenden Angriffen allein gelassen, sucht Magistrat Solomon Hilfe bei benachbarten menschlichen Städten.",al={"warum dunkelhain bitten","warum nicht sturmwind","warum braucht solomon die night watch"}},{q="Wer ist Lord Ello Schwarzhaupt?",a="Lord Ello Schwarzhaupt ist Dunkelhains Bürgermeister und oberster ziviler Amtsträger im Dämmerwald. Er leitet die Stadt und koordiniert die Nachtwache, ihre zivile Verteidigungstruppe gegen die Gefahren in den Wäldern.",al={"wer ist schwarzhaupt","bürgermeister von dunkelhain","lord ello"}},{q="Kann Dunkelhain die Nachtwache tatsächlich entbehren, um Seenhain zu helfen?",a="Nein. Der Dämmerwald ist Untoten, wilden Worgen und dunkler Magie ausgesetzt, und die Nachtwache kann Dunkelhains Grenzen kaum halten. Sie kann keine Kämpfer entbehren, die ins Rotkammgebirge ziehen könnten.",al={"hilft dunkelhain","kommt die night watch","hat schwarzhaupt wachen geschickt"}}},fx={a3b7e1d6={q="Woher stammt Solomons Hilfegesuch an Dunkelhain und wer hat es geschrieben?",a="Der Brief wurde direkt von Magistrat Solomon, dem Stadtoberhaupt von Seenhain im Rotkammgebirge, verfasst. Da Schwarzfelsorcs seine Stadt stark bedrängen und Sturmwind keine königlichen Verstärkungen schicken kann, schrieb Solomon den dringenden Appell selbst aus dem Rathaus von Seenhain in der Hoffnung, Hilfe von benachbarten Siedlungen zu erhalten.",al={"wer schrieb solomons hilfegesuch","ursprung von solomons hilfegesuch an dunkelhain","wer verfasste solomons gesuch"}},["5061acb5"]={q="Warum möchte Lord Ello Schwarzhaupt Solomons Hilfegesuch an Dunkelhain?",a="Lord Ello Schwarzhaupt benötigt den Brief, da er offiziell die verzweifelte Verteidigung von Seenhain und Magistrat Solomons direkte Bitte um militärische Unterstützung detailliert beschreibt. Als Bürgermeister von Dunkelhain und Kommandant der Nachtwache verlässt sich Schwarzhaupt auf offizielle Depeschen wie diese, um die Bedrohungen zu verstehen, denen ihre Verbündeten der Allianz gegenüberstehen, und um zu bewerten, ob seine Stadt Wachen entbehren kann.",al={"warum solomons gesuch überbringen","warum braucht schwarzhaupt den brief","zweck von solomons hilfegesuch an dunkelhain"}}},fp="27,149,24.361.0,23.222.1,36.139.0,73.206.0,27.193.0,63.165.1"}
P.entries["item:solomon-s-plea-to-westfall"] = {n="Solomons Hilfegesuch an Westfall",s="In Seenhain bittet Magistrat Solomon Westfall um Hilfe, während Schwarzfelsorcs und Gnolle das Rotkammgebirge bedrohen. Sturmwinds königliche Armee hat nicht geantwortet, also bittet er Gryan Starkmantel, die Volksmiliz zu entsenden.",h="In Seenhain bittet Magistrat Solomon Westfall um Hilfe, während Schwarzfelsorcs und Gnolle das Rotkammgebirge...",kw={"gryan starkmantel","seenhain","magistrat solomon","volksmiliz","rotkammgebirge","solomons hilfegesuch","sturmwinds armee","westfall"},ang={["faction:Alliance"]="Für die Allianz zeigt Solomons Hilfegesuch, wie entlegene Orte sich an örtliche Freiwillige wenden, wenn königliche Truppen ausbleiben.",["race:Human"]="Als Mensch könnt Ihr erkennen, wie sehr die ländlichen Siedlungen inzwischen unter Druck stehen. Der vermisste König und politische Vernachlässigung machen die Grenzgebiete verwundbar."},sec={{t="Ein verzweifelter Hilferuf",b="Schwarzfelsorcs und feindselige Gnolle bedrohen das Rotkammgebirge, während Magistrat Solomon in Seenhain isoliert ist. Sturmwinds königliche Armee ist nicht in ausreichender Stärke eingetroffen, um die Grenzen der Region zu verteidigen. Da keine Zeit bleibt, auf die Hauptstadt zu warten, sucht Solomon schriftlich Hilfe außerhalb der regulären Armee. Er hat von einer freiwilligen Verteidigungstruppe gehört, die sich im westlich gelegenen Elwynn formiert, und wendet sich deshalb an die Volksmiliz."},{t="Hilfe jenseits der Grenze",b="Solomon richtet seine Botschaft an Gryan Starkmantel, einen kampferfahrenen Krieger, der die Verteidigung von Westfalls Grenzland organisiert. Er hofft, dass Starkmantel Kämpfer für Seenhain entbehren kann, bis Sturmwind reguläre Reserven entsendet. Ein Abenteurer überbringt das Dokument. Sturmwinds entlegene Gebiete stimmen sich kaum miteinander ab, sodass örtliche Magistrate gegenseitige Hilfe selbst organisieren müssen."}},faq={{q="Was ist Solomons Hilfegesuch an Westfall?",a="Magistrat Solomon aus Seenhain schreibt an Gryan Starkmantel und bittet die Volksmiliz in Westfall, Verstärkung zur Verteidigung des Rotkammgebirges zu entsenden.",al={"was ist solomons hilfegesuch","solomons hilfegesuch an westfall brief","seenhain westfall brief"}},{q="Warum bittet Magistrat Solomon Westfall statt Sturmwind um Hilfe?",a="Sturmwinds königliche Truppen sind nicht in ausreichender Stärke eingetroffen, während die Gefahr in Seenhain wächst. Da keine Zeit bleibt, auf die Krone zu warten, sucht Solomon Hilfe bei einer nahe gelegenen Kampftruppe.",al={"warum westfall um hilfe bitten","warum nicht sturmwind um hilfe bitten","warum hilfegesuch an westfall senden"}},{q="Wer ist Gryan Starkmantel?",a="Gryan Starkmantel führt die Volksmiliz an, einen freiwilligen Verteidigungsbund örtlicher Bauern und Siedler, die Westfall vor der Bruderschaft der Defias schützen.",al={"wer ist starkmantel","gryan starkmantels rolle"}},{q="Welche Bedrohungen drängen Solomon dazu, diesen Brief zu senden?",a="Schwarzfelsorcs dringen ein, und Gnolle verüben im gesamten Rotkammgebirge Überfälle. Ihre Angriffe setzen Seenhains Stadtwache unter Druck.",al={"warum ist seenhain in gefahr","was bedroht das rotkammgebirge"}}},fx={["7804da1c"]={q="Woher stammt Solomons Hilfegesuch an Westfall und wer hat es verfasst?",a="Der Brief wurde direkt von Magistrat Solomon in Seenhain verfasst, der bedrängten Stadt im Rotkammgebirge. Verzweifelt, nachdem die Armee von Sturmwind keine versprochenen Verstärkungen zur Verteidigung seines Volkes schickte, schrieb Solomon diese dringende Nachricht selbst, um Verbündete in der Nähe um Hilfe anzuflehen.",al={"wer schrieb solomons hilfegesuch an westfall","woher stammt solomons hilfegesuch","schöpfer von solomons hilfegesuch"}},["6d6e291d"]={q="Warum möchte Gryan Starkmantel Solomons Hilfegesuch an Westfall haben?",a="Gryan Starkmantel führt die The People's Militia in Westfall an, und diese Depesche informiert ihn über die schlimme Notlage von Seenhain. Solomon hofft, dass die Miliz Kämpfer erübrigen kann, um die schwindenden Verteidigungen des Rotkammgebirges zu stärken, während die Stadt auf Nachricht und Truppen vom Hof von König Anduin in Sturmwind wartet.",al={"warum solomons hilfegesuch überbringen","warum will starkmantel das hilfegesuch","wofür ist der brief"}}},fp="26,207,24.381.0,26.355.0,35.148.0,72.165.0,25.151.0,53.124.0"}
P.entries["item:soran-ruk-fragment"] = {n="Fragment von Soran'ruk",s="In der Tiefschwarzen Grotte schöpfen Kultisten Kraft aus Splittern von Soran'ruks zerbrochener Gefängniskugel. Die Stücke bergen noch immer Teufelsenergie des Dämons, der einst darin gebunden war.",h="In der Tiefschwarzen Grotte schöpfen Kultisten Kraft aus Splittern von Soran'ruks zerbrochener Gefängniskugel.",kw={"tiefschwarze grotte","doan karhan","teufelsenergie","kugel von soran'ruk","soran'ruk","soranruk","twilight acolyte"},ang={["class:Warlock"]="Als Hexenmeister könnt Ihr dämonische Gefängnisgefäße wie die Kugel von Soran'ruk nutzen, um rohe Teufelsenergie zu kanalisieren, ohne einen Dämon direkt zu unterwerfen."},sec={{t="Ein zerbrochenes Gefängnis",b="Soran'ruks Gefängniskugel wurde zerschlagen, nachdem ihr Dämon bei der Brennenden Legion in Ungnade gefallen war. Dämonen, die ihren Meistern missfallen, können ihre Geister in Kugeln versiegelt und dann Teufelszauberern als Machtquellen übergeben bekommen. In den versunkenen Ruinen der Tiefschwarzen Grotte besitzen Kultisten des Schattenhammers kleinere Splitter einer Hälfte der Kugel. Sie nutzen die verbliebene dämonische Essenz für ihre eigenen Zauber."},{t="Wiederherstellung im Brachland",b="Jedes Fragment birgt eine Spur der Lebenskraft des gefangenen Dämons. Doan Karhan, ein zurückgezogen lebender Gelehrter im südlichen Brachland, hat ein Leben lang dämonische Gefäße studiert. Er besitzt eine ähnliche Kugel, die Kugel von Zargain. Ein ehrgeiziger Hexenmeister kann ihm drei kleine Fragmente und das größere Stück aus dem Silberwald bringen. Doan kann das Relikt wieder zu einem Instrument der Macht zusammenschmieden."}},faq={{q="Was ist Soran'ruk?",a="Soran'ruk war ein Dämon der Brennenden Legion, der bei ihren Anführern in Ungnade fiel. Zur Strafe wurde sein Geist herausgezogen und in einer kristallinen Kugel gefangen. Sterbliche Hexenmeister und Magier nutzten die Kugel als Energiequelle.",al={"wer ist soranruk","soran'ruk geschichte","ist soranruk ein dämon"}},{q="Wo findet man diese Fragmente?",a="Twilight Acolytes tragen die kleineren Splitter durch die höhlenartigen Hallen der Tiefschwarzen Grotte am Zoramstrand.",al={"woher bekommt man ein fragment von soranruk","wer lässt fragmente von soran'ruk fallen","soranruk fragment fundort"}},{q="Warum besitzt der Schattenhammer diese Splitter?",a="Kultisten des Schattenhammers sammeln die Splitter wegen der magischen Essenz des gefangenen Dämons. Sie nutzen verderbte Artefakte, um ihre dunklen Rituale zu speisen und verbotene Magie zu kanalisieren.",al={"warum haben kultisten es","schattenhammer soranruk"}},{q="Wer kann die Kugel von Soran'ruk wiederherstellen?",a="Doan Karhan kann die Kugel von Soran'ruk wiederherstellen. Der einsame Eremit lebt im südlichen Brachland nahe der Grenze zu Tausend Nadeln. Er erforscht die dämonischen Kugeln der Brennenden Legion und schmiedet sie neu.",al={"wer repariert die kugel","wo fragment von soranruk abgeben","doan karhan kugel"}}},fx={["49c59cce"]={q="Woher stammen die Soran'ruk-Fragmente und wer hat sie erschaffen?",a="Es sind die zerbrochenen Überreste des The Orb of Soran'ruk, einem dämonischen Gefäß, das von der Brennende Legion geschmiedet wurde. Wenn Dämonen in Ungnade fallen, sperrt die Legion ihre Geister in solche Sphären und vertraut sie ihren Magiern und Hexenmeistern an. Der The Orb of Soran'ruk wurde später in Stücke zerbrochen, wobei diese kleineren Scherben in die Hände der Akolythen des Twilight's Hammer innerhalb der Tiefschwarze Grotte gelangten.",al={"ursprung der soran'ruk-fragmente","wer erschuf soran'ruk-fragmente","woher kommen soran'ruk-fragmente"}},["5e1e8c12"]={q="Warum möchte jemand Soran'ruk-Fragmente haben?",a="Selbst in Scherben zerbrochen summen die Fragmente noch immer vor der Essenz und der Macht des gefangenen Dämons. Der Hexenmeistereinsiedler Doan Karhan im Brachland hat sein Leben dem Studium und der Rekonstruktion von Legion-Sphären gewidmet. Wenn Ihr ihm diese kleineren Scherben zusammen mit dem großen Fragment aus Burg Shadowfang bringt, kann er den The Orb of Soran'ruk zu einem mächtigen Werkzeug für Euer Handwerk umschmieden.",al={"warum soran'ruk-fragmente sammeln","wer will soran'ruk-fragmente","warum werden soran'ruk-fragmente benötigt"}}},fp="18,150,18.407.0,29.373.1,18.217.0,32.115.0,49.168.0,37.191.0"}
P.entries["item:southsea-treasure"] = {n="Schatz der Südmeerfreibeuter",s="Der Schatz der Südmeerfreibeuter liegt auf einem Piratenschiff südlich von Ratschet, wo Wrenix der Jämmerliche den Hort begehrt. Der unterste Frachtraum der Tide Razor liegt unter dem Übungsgelände der Südmeerfreibeuter.",h="Der Schatz der Südmeerfreibeuter liegt auf einem Piratenschiff südlich von Ratschet, wo Wrenix der...",kw={"r.c.v.k.","schlossknacken","polly","ratschet","shattered hand","schatz der südmeerfreibeuter","tide razor","wrenix der jämmerliche"},ang={["class:Rogue"]="Als angehender Schurke könnt Ihr beim Bergen des Schatzes der Südmeerfreibeuter das Schlossknacken üben und die Shattered Hand kennenlernen, ein zwielichtiges Syndikat.",["faction:Horde"]="Als Mitglied der Horde könnt Ihr den örtlichen Behörden helfen, indem Ihr das Beutelager der Südmeerfreibeuter ins Visier nehmt. Die Piraten stören den Handel im Brachland und im Hafen von Ratschet."},sec={{t="Ein tödlicher Raubzug",b="Die Tide Razor liegt an der Händlerküste südlich von Ratschet vor Anker. Die Südmeerfreibeuter nutzen sie als vorgeschobenen Stützpunkt und Übungsgelände. Ihre Beute, bekannt als Schatz der Südmeerfreibeuter, wartet im untersten Frachtraum.\n\nWrenix der Jämmerliche, ein Goblinhalunke in Ratschet, macht den Diebstahl zur Prüfung für angehende Taschendiebe. Ihm zufolge kamen die letzten fünf Agenten, die nach der Truhe geschickt wurden, in Stücken zurück. Wachsame Piraten bewachen das Schiff, und eine wilde Kreatur bewacht den Frachtraum."},{t="Pollys Andenken",b="Polly bewacht den Schatz der Südmeerfreibeuter im Frachtraum. Diebe, die den Piratenausbildern entgehen und das Schloss der Truhe knacken, finden den feindseligen Papagei statt loser Schätze.\n\nWrenix' R.C.V.K.-Gerät kann helfen, Polly zu bezwingen. Erst dann lässt sich der Schatz aus dem Frachtraum holen und unversehrt nach Ratschet zurückbringen."}},faq={{q="Wo befindet sich der Schatz der Südmeerfreibeuter?",a="Der Schatz der Südmeerfreibeuter befindet sich an Bord der Tide Razor, die an der Küste südlich von Ratschet im Brachland vor Anker liegt. Er liegt im untersten Frachtraum unter den Übungsräumen der Piraten.",al={"wo ist der schatz","tide razor standort","wie den schatz der südmeerfreibeuter finden"}},{q="Wer will den Schatz der Südmeerfreibeuter?",a="Wrenix der Jämmerliche, ein Goblin in Ratschet, will den Schatz der Südmeerfreibeuter. Er heuert verdeckt arbeitende Agenten an, die das Schiff betreten und ihn für ihn bergen sollen.",al={"wer gibt die quest","wer ist wrenix","wer will ihn"}},{q="Warum ist die Truhe nach dem Schlossknacken leer?",a="Polly bewacht den Schatz der Südmeerfreibeuter im Frachtraum. Wer das Schloss der Truhe knackt, ruft den bösartigen Papagei in den Kampf; wer Polly besiegt, erhält den Schatz.",al={"woher kam polly","warum ist polly erschienen","warum ist der schatz nicht in der kiste"}},{q="Was ist ein R.C.V.K. und warum wird es benötigt?",a="Wrenix der Jämmerliche stellt das R.C.V.K. bereit, ein experimentelles Goblingerät, das ungewöhnlich wilde Bedrohungen aus der Luft schwächen soll. Er sieht es für Polly vor, den tödlichen Wächterpapagei im Frachtraum des Schiffs.",al={"was ist r.c.v.k.","wie polly besiegen","feindseliger papagei"}},{q="Wofür nutzen die Südmeerfreibeuter das Schiff?",a="Die Tide Razor ist ein Stützpunkt und Diebesversteck der Südmeerfreibeuter. Auf ihrer zweiten Ebene bieten Übungsschließkassetten der Besatzung einen Ort, an dem sie ihre Beutelschneider ausbilden können.",al={"was ist die tide razor","piratenversteck brachland","southsea schiffsfrachtraum"}}},fx={c9f033cd={q="Was ist der Schatz der Südmeerfreibeuter?",a="Der Schatz der Südmeerfreibeuter ist die geplünderte Beute, die von den Südmeerfreibeutern an Bord ihres Schiffes, der Tide Razor, gehortet wird, das vor der Küste vom Brachland ankert. Tief im Laderaum des Schiffes aufbewahrt und von einem berüchtigt wilden Piratenpapagei namens Polly bewacht, repräsentiert er die unrechtmäßig erworbenen Gewinne, die die Freibeuter bei ihren Überfällen entlang der Händlerküste angehäuft haben.",al={"was ist der schatz der südmeerfreibeuter","gegenstand schatz der südmeerfreibeuter","welche art von schatz ist der schatz der südmeerfreibeuter"}}},fp="17,189,14.462.0,16.299.1,39.172.0,32.139.0,35.155.1,41.195.0,50.159.0"}
P.entries["item:spectral-comb"] = {n="Spektraler Kamm",s="Südlich von Dunkelhain sammelt der Spektrale Kamm auf einem verfallenen Bauernhof Geisterhaar von der blinden Mary.",h="Südlich von Dunkelhain sammelt der Spektrale Kamm auf einem verfallenen Bauernhof Geisterhaar von der blinden...",kw={"die blinde mary","kamm","dunkelhain","dämmerwald","geist","geisterhaarfaden","spektraler kamm"},ang={["faction:Alliance"]="Als Reisender der Allianz könnt Ihr den Kamm in die Gegend südlich von Dunkelhain tragen und das tragische Schicksal der einstigen Siedler des Dämmerwalds kennenlernen.",["profession:Tailoring"]="Als Schneider könnt Ihr mit dem Spektralen Kamm ätherische Fasern von willigen Geistern sammeln, statt sie mit gewöhnlichen Mitteln zu scheren."},sec={{t="Ein Werkzeug für rastlose Tote",b="Gewöhnliche Kämme können das Haar eines Geistes nicht erreichen, weshalb nur wenige sterbliche Handwerker es sammeln können. Der Spektrale Kamm gleitet durch diese unsichtbaren Strähnen. Auf einem verfallenen Bauernhof südlich von Dunkelhain wird er der blinden Mary angeboten, einem weinenden Geist, der allein klagt. Das Kämmen spendet ihr Trost, und sie nimmt den Kamm bereitwillig zur Hand. Die Fasern, die sie zurücklässt, lassen sich zu Geisterhaarfaden verweben."}},faq={{q="Wofür wird der Spektrale Kamm verwendet?",a="Ihr gebt den Spektralen Kamm der blinden Mary, einem weinenden Geist südlich von Dunkelhain. Während sie ihr Haar kämmt, sammelt der Kamm ätherische Strähnen, die sich zu übernatürlichem Faden verspinnen lassen.",al={"spektraler kamm verwendung","wozu braucht man den spektralen kamm","was macht der kamm"}},{q="Wer ist die blinde Mary?",a="Die blinde Mary ist ein gequälter Geist, der in einem verlassenen Haus in den Hügeln südlich von Dunkelhain spukt. Von einer Tragödie in den Wahnsinn getrieben, riss sie sich die eigenen Augen aus und fürchtet, dass andere sie im Tod abscheulich finden.",al={"geschichte der blinden mary","wer ist der geist mit dem kamm","die blinde mary"}},{q="Warum kann kein gewöhnlicher Kamm verwendet werden?",a="Ein gewöhnlicher Kamm kann das körperlose Haar eines Geistes nicht berühren. Der Spektrale Kamm gleitet durch die Strähnen einer Geistererscheinung.",al={"warum spektraler kamm","gewöhnlicher kamm geist"}}},fx={e893aa2f={q="Was ist der Spektraler Kamm?",a="Der Spektraler Kamm ist ein ätherisches Pflegegerät, das speziell verzaubert wurde, um mit dem Körperlosen zu interagieren. Während gewöhnliche Utensilien ohne Wirkung direkt durch ein Phantom hindurchgehen würden, kann dieser Kamm die spektralen Strähnen des Haares eines Geistes tatsächlich berühren, entwirren und sammeln.",al={"was ist der spektraler kamm","spektraler kamm","identität des spektralen kamms"}}},fp="13,95,24.375.0,35.177.0,18.186.0,37.119.0"}
P.entries["item:spells-of-shadow"] = {n="Schattenzauber",s="Unter Orgrimmar liegt Schattenzauber unter den bewachten Schätzen der Searing Blade. Die Führung der Verlassenen in Unterstadt will es bergen lassen.",h="Unter Orgrimmar liegt Schattenzauber unter den bewachten Schätzen der Searing Blade.",kw={"zauberformeln aus dem nether","der flammenschlund","searing blade","schattenzauber","sylvanas","the power to destroy","unterstadt","varimathras"},ang={["class:Warlock"]="Als Hexenmeister seht Ihr, wie Kultisten der Searing Blade durch dämonische Gaben der Legion Schatten- und Netherkünste wirken.",["race:Undead"]="Als Untoter helft Ihr Fürstin Sylvanas, unter Orgrimmar gefährliches dämonisches Wissen an sich zu bringen. Seine Macht soll Unterstadt gegen die Geißel stärken."},sec={{t="Folianten der Searing Blade",b="Im Flammenschlund bewachen Kultisten der Searing Blade Schattenzauber unter ihren Schätzen. Der Splitterkult ist mit dem Shadow Council verbunden, und seine Mitglieder wirken dunkle Riten, die ihnen Dämonenmeister der Brennenden Legion gewährt haben. Das Buch enthält Schatten- und Teufelszauberei. Kultisten und Hexenmeister halten es bei sich, während sie unter der Horde in Durotar ihre Pläne schmieden."},{t="Der Ehrgeiz der Dark Lady",b="Kunde von den dämonischen Gaben der Searing Blade erreichte die königlichen Gemächer von Unterstadt. Fürstin Sylvanas Windläufer und ihr Schreckenslord-Leutnant Varimathras befanden, dass die Relikte an Kultisten mit geringerer Weitsicht verschwendet seien. Deshalb schickt Varimathras Abenteurer der Horde in den Flammenschlund, um Schattenzauber und seinen Begleitband Zauberformeln aus dem Nether zu erbeuten. Ihre Macht soll der Sache der Verlassenen gegen die Geißel und den Lichkönig dienen."}},faq={{q="Was ist Schattenzauber?",a="Kultisten der Searing Blade verwahren Schattenzauber im Flammenschlund. Das Zauberbuch enthält Shadow Magic, die von der Brennenden Legion gewährt wurde.",al={"schattenzauber buch","was ist schattenzauber","schattenzauber buch rfc"}},{q="Wer will dieses Buch?",a="Varimathras sucht Schattenzauber für Fürstin Sylvanas Windläufer. Ihr Schreckenslord-Berater residiert im Königsviertel von Unterstadt.",al={"wer braucht schattenzauber","wer gibt schattenzauber ab","schattenzauber questgeber"}},{q="Wo ist das Buch zu finden?",a="Kultisten und Hexenmeister der Searing Blade tragen Schattenzauber im Flammenschlund bei sich, den feurigen Höhlen unter Orgrimmar.",al={"schattenzauber fundort","wo gibt es schattenzauber","wie bekommt man schattenzauber"}},{q="Warum wollen die Verlassenen dieses Grimoire?",a="Fürstin Sylvanas glaubt, dass die dunklen Gaben der Legion in die Hände der Verlassenen gehören statt in die geringerer Kultisten. Sie will mit der Magie die Verlassenen gegen die Geißel und den Lichkönig stärken.",al={"warum will sylvanas das buch","warum will varimathras schattenzauber"}}},fp="16,148,26.335.0,24.437.0,29.130.0,20.133.0,28.114.0,39.193.0"}
P.entries["item:spotted-sunfish"] = {n="Gefleckter Sonnenfisch",s="Im Immerruhsee locken Gefleckte Sonnenfische Angler und hungrige Murlocs an. Ihr Fang bringt Handel nach Seenhain, während Murlocs die seichten Gewässer gefährlich machen.",h="Im Immerruhsee locken Gefleckte Sonnenfische Angler und hungrige Murlocs an.",kw={"dockmaster baren","der immerruhsee","seenhain","murloc","rotkammgebirge","selling fish","gefleckter sonnenfisch"},ang={["profession:Cooking"]="Als Koch könnt Ihr Gefleckte Sonnenfische verwenden, Süßwasserfische, die im Rotkammgebirge heimisch sind."},sec={{t="Ein begehrter Fang",b="Gefleckte Sonnenfische bringen Handel an die Piers von Seenhain. Dockmaster Baren kauft die regelmäßigen Fänge aus dem See und versorgt eine bedrängte Stadt mit Nahrung und Handel. Aggressive Murlocstämme durchstreifen die seichten Gewässer und stören den Fischfang. In ihren Lagern können Reisende ihnen die gesammelten Sonnenfische mit Gewalt abnehmen."}},faq={{q="Wo kommen Gefleckte Sonnenfische vor?",a="Gefleckte Sonnenfische leben im Immerruhsee im Rotkammgebirge. Angler fangen sie dort, und Murlocs sammeln sie in Lagern am Ufer.",al={"wo gefleckte sonnenfische bekommen","gefleckte sonnenfische fundort","immerruhsee fische"}},{q="Wer kauft oder braucht Gefleckte Sonnenfische?",a="Dockmaster Baren kauft Gefleckte Sonnenfische an den Docks von Seenhain. Er handelt mit den Fischen und bezahlt für frischen Nachschub.",al={"wer will gefleckte sonnenfische","dockmaster baren fische","selling fish quest"}},{q="Warum tragen die Murlocs diese Fische bei sich?",a="Murlocs am Immerruhsee sammeln Sonnenfische, um ihre wachsenden Stämme zu ernähren. Sie bewahren ihre Fänge in Lagern entlang der seichten Gewässer auf.",al={"murloc gefleckte sonnenfische","warum murlocs fische fallen lassen"}},{q="Könnt Ihr sie auch ohne Angeln bekommen?",a="Ja. Reisende ohne Angelrute können die feindseligen Murlocs am Ufer des Immerruhsees besiegen und die Fische an sich nehmen, die sie gesammelt haben.",al={"sonnenfische ohne angelrute bekommen","ohne angelrute sonnenfische"}}},fx={["723094c5"]={q="Was ist ein Gefleckter Sonnenfisch?",a="Der Gefleckter Sonnenfisch ist ein geschätzter Süßwasserfisch, der im Immerruhsee im Rotkammgebirge heimisch ist. In der ganzen Region für seinen Geschmack und seinen Handelswert bekannt, gedeiht er in den tiefen Gewässern des Sees und dient als Grundnahrungsmittel für die Fischer von Seenhain sowie als primäre Nahrungsquelle für die dortigen Murlocs.",al={"was ist der gefleckter sonnenfisch","infos zum gefleckten sonnenfisch","hintergrund des gefleckten sonnenfischs"}},["1a933976"]={q="Woher stammt der Gefleckter Sonnenfisch?",a="Gefleckter Sonnenfisch stammt auf natürliche Weise aus den kühlen Gewässern des Immerruhsees im Rotkammgebirge. Anstatt gezüchtet oder kultiviert zu werden, handelt es sich um wilde Fische, die direkt aus dem See geerntet werden, entweder durch Angeln entlang der Docks und Ufer gefangen oder aus den Klauen der lokalen Murloc Poachers zurückgeholt.",al={"herkunft des gefleckten sonnenfischs","woher kommt der gefleckter sonnenfisch","quelle des gefleckten sonnenfischs"}}},fp="15,149,14.293.0,32.145.0,34.109.0,36.126.0,36.137.0"}
